#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS        1
#define ADS1115_ADDR   0x48
#define ADS1115_REG_CONV  0x00
#define ADS1115_REG_CONFIG 0x01

/* Config: single-shot, AIN0 single-ended, PGA ±4.096 V, 128 SPS, start */
#define ADS1115_CFG_BASE 0x8000  /* OS bit: begin conversion */
#define ADS1115_CFG_MUX  0x4000  /* MUX[14:12] = 100 -> AIN0 */
#define ADS1115_CFG_PGA  0x0200  /* PGA[11:9]  = 001 -> ±4.096 V */
#define ADS1115_CFG_DR   0x0080  /* DR[7:5]   = 100 -> 128 SPS */
#define ADS1115_CFG_CQUE 0x0003  /* Disable comparator */

#define SAMPLE_PERIOD_US 500000  /* 500 ms */
#define MAX_READ_RETRIES 3

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int16_t read_ads1115(int handle, int16_t *out)
{
    char cfg[3];
    char conv[2];
    int  rc;

    /* Write config: 16-bit big-endian, MSB first */
    cfg[0] = ADS1115_REG_CONFIG;
    cfg[1] = (ADS1115_CFG_BASE >> 8) & 0xFF;
    cfg[2] = ADS1115_CFG_BASE & 0xFF;

    rc = i2cWriteDevice(handle, cfg, 3);
    if (rc < 0) {
        fprintf(stderr, "i2cWriteDevice (config) failed: %d\n", rc);
        return -1;
    }

    /* Wait for conversion to complete (~8 ms at 128 SPS) */
    gpioDelay(10000);

    /* Read conversion register: 16-bit big-endian */
    rc = i2cReadI2CBlockData(handle, ADS1115_REG_CONV, conv, 2);
    if (rc < 0) {
        fprintf(stderr, "i2cReadI2CBlockData (conv) failed: %d\n", rc);
        return -1;
    }
    if (rc != 2) {
        fprintf(stderr, "i2cReadI2CBlockData: got %d bytes, expected 2\n", rc);
        return -1;
    }

    *out = (int16_t)(((uint16_t)(uint8_t)conv[0] << 8) | (uint8_t)conv[1]);
    return 0;
}

static int read_current(int handle, float *current_out)
{
    int16_t raw;
    int  rc;

    for (int attempt = 0; attempt < MAX_READ_RETRIES; attempt++) {
        if (read_ads1115(handle, &raw) == 0) {
            /* ±4.096 V PGA → 1 bit = 125 µV → 1 LSB ≈ 0.125 mA */
            *current_out = (float)raw * 0.000125f;
            return 0;
        }
        gpioDelay(10000);
    }

    fprintf(stderr, "Failed to read ADS1115 after %d attempts\n", MAX_READ_RETRIES);
    return -1;
}

int main(void)
{
    int rc;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Verify ADS1115 is present by reading the default config register */
    char cfg[2];
    rc = i2cReadI2CBlockData(g_i2c_handle, ADS1115_REG_CONFIG, cfg, 2);
    if (rc < 0) {
        fprintf(stderr, "ADS1115 not responding on bus %d addr 0x%02X\n",
                I2C_BUS, ADS1115_ADDR);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (rc != 2) {
        fprintf(stderr, "ADS1115 returned %d bytes, expected 2\n", rc);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MLX91219 Current Sensor via ADS1115 on I2C bus %d\n", I2C_BUS);
    printf("Sensor ADDR=0x%02X, AIN0, ±4.096 V PGA, 128 SPS, 500 ms interval\n",
           ADS1115_ADDR);
    printf("Press Ctrl+C to exit.\n\n");

    while (g_running) {
        float current;
        if (read_current(g_i2c_handle, &current) == 0) {
            printf("Current: %.2f A\n", current);
        } else {
            fprintf(stderr, "Sensor read failed; continuing...\n");
        }
        fflush(stdout);
        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

