#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000
#define SPI_FLAGS   0
#define FLAME_PIN   4
#define MCP3008_CHANNEL 0
#define LOG_FILE    "flame_data.csv"
#define SAMPLE_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float calculate_temperature(int adc_value) {
    return (float)adc_value * 0.1f;
}

static void log_data(FILE *fp, int flame_detected, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%d,%.2f\n", timestamp, flame_detected, temperature);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(FLAME_PIN, PI_INPUT);
    gpioSetMode(4, PI_OUTPUT); /* CE0 on GPIO8 */

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("fopen");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    while (running) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        int flame_detected = (adc_value == 0) ? 1 : 0;
        float temperature = calculate_temperature(adc_value);

        if (adc_value < 0) {
            fprintf(stderr, "Sensor read error, skipping entry\n");
        } else {
            log_data(fp, flame_detected, temperature);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    fclose(fp);
    spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

