static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_flame_sensor(void) {
    static int last_state = 0;
    static uint32_t last_change_tick = 0;

    int val = gpioRead(FLAME_SENSOR_PIN);
    if (val < 0) {
        fprintf(stderr, "Error reading flame sensor GPIO %d\n", FLAME_SENSOR_PIN);
        return -1;
    }

    uint32_t now = gpioTick();
    if (now - last_change_tick < DEBOUNCE_MS * 1000) {
        return last_state;
    }
    last_state = val;
    last_change_tick = now;
    return last_state;
}

static float read_temperature(void) {
    if (i2cWriteByteData(i2c_handle, ADS1115_REG_CONFIG, ADS1115_CONFIG_BASE) < 0) {
        fprintf(stderr, "Error writing ADS1115 config\n");
        return -1.0f;
    }
    gpioDelay(10000); /* 10 ms for conversion */

    int16_t raw = i2cReadWordData(i2c_handle, ADS1115_REG_CONVERSION);
    if (raw < 0) {
        fprintf(stderr, "Error reading ADS1115 conversion register\n");
        return -1.0f;
    }
    /* ADS1115 returns 16-bit two's complement; PGA 4.096V -> LSB = 125 uV */
    float voltage = (raw * 4.096f) / 32768.0f;
