#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_BITS         8
#define SPI_MODE         0
#define ADC_CHANNEL      0
#define FAN_GPIO         18
#define CURRENT_THRESHOLD 10.0
#define LOG_FILE         "current_log.txt"
#define SAMPLE_INTERVAL  1
#define ADC_MAX          1023
#define ADC_FAULT        0x8000

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int spi_init(const char *device)
{
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", device, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

static int read_adc(int fd, uint8_t channel)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid ADC channel %u\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf        = (unsigned long)tx,
        .rx_buf        = (unsigned long)rx,
        .len           = 3,
        .speed_hz      = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs   = 0,
        .cs_change     = 0,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE: %s\n", strerror(errno));
        return -1;
    }

    int value = ((rx[1] & 0x03) << 8) | rx[2];
    if (value == ADC_FAULT) {
        fprintf(stderr, "ADC fault (all bits set or all clear)\n");
        return -1;
    }
    return value;
}

static void log_current(int current, const char *filename)
{
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s): %s\n", filename, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        fclose(fp);
        return;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s, Current: %d\n", ts, current);
    fclose(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM): %s\n", strerror(errno));
        return 1;
    }

    int spi_fd = spi_init(SPI_DEVICE);
    if (spi_fd < 0) {
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    struct gpiod_line *fan_line = gpiod_chip_get_line(chip, FAN_GPIO);
    if (!fan_line) {
        fprintf(stderr, "gpiod_chip_get_line(%d): %s\n", FAN_GPIO, strerror(errno));
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    if (gpiod_line_request_output(fan_line, "current_monitor", 0) < 0) {
        fprintf(stderr, "gpiod_line_request_output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    int ret = 0;

    while (g_running) {
        int current = read_adc(spi_fd, ADC_CHANNEL);
        if (current < 0) {
            fprintf(stderr, "ADC read failed; continuing\n");
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        if (current == ADC_FAULT) {
            fprintf(stderr, "ADC fault; continuing\n");
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        log_current(current, LOG_FILE);

        int fan_state = (current > CURRENT_THRESHOLD) ? 1 : 0;
        if (gpiod_line_set_value(fan_line, fan_state) < 0) {
            fprintf(stderr, "gpiod_line_set_value: %s\n", strerror(errno));
            ret = 1;
            break;
        }

        printf("Current: %d, Fan: %s\n", current, fan_state ? "ON" : "OFF");
        sleep(SAMPLE_INTERVAL);
    }

    gpiod_line_set_value(fan_line, 0);
    gpiod_line_release(fan_line);
    gpiod_chip_close(chip);
    close(spi_fd);

    return ret;
}

