#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <math.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x48
#define LOG_FILE       "co_log.txt"
#define SAMPLE_INTERVAL 5
#define ADC_MAX        32767.0f
#define ADC_VREF       3.3f
#define CO_RES_MIN     100.0f
#define CO_RES_MAX     1000.0f
#define CO_PPM_MIN     0.0f
#define CO_PPM_MAX     100.0f

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int init_i2c(void) {
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_sensor(float *co_ppm) {
    char buf[2];
    int bytes = i2cReadDevice(g_i2c_handle, buf, 2);
    if (bytes != 2) {
        fprintf(stderr, "I2C read failed (got %d bytes): %s\n",
                bytes, bytes < 0 ? strerror(errno) : "short read");
        return -1;
    }
    int raw = (buf[0] << 8) | buf[1];
    if (raw < 0 || raw > ADC_MAX) {
        fprintf(stderr, "ADC raw out of range: %d\n", raw);
        return -1;
    }
    float v = (float)raw * ADC_VREF / ADC_MAX;
    float r = 3.3f / v - 1.0f;
    if (r < CO_RES_MIN || r > CO_RES_MAX) {
        fprintf(stderr, "CO resistance out of range: %.2f\n", r);
        return -1;
    }
    *co_ppm = CO_PPM_MIN + (r - CO_RES_MIN) *
              (CO_PPM_MAX - CO_PPM_MIN) / (CO_RES_MAX - CO_RES_MIN);
    return 0;
}

static void log_data(float co_ppm) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[64];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s, %.2f ppm\n", ts, co_ppm);
    } else {
        fprintf(fp, "(time error), %.2f ppm\n", co_ppm);
    }
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    printf("CO sensor logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        float co_ppm;
        if (read_sensor(&co_ppm) == 0) {
            log_data(co_ppm);
            printf("CO: %.2f ppm\n", co_ppm);
        } else {
            fprintf(stderr, "Sensor read failed; continuing.\n");
        }
        sleep(SAMPLE_INTERVAL);
    }

    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    printf("CO sensor logging stopped.\n");
    return 0;
}

