static int read_sensor_data(int handle, uint16_t *ox, uint16_t *red) {
    char buffer[4];
    int bytes_read = i2cReadDevice(handle, buffer, 4);
    if (bytes_read != 4) {
        fprintf(stderr, "Error: I2C read failed (expected 4 bytes, got %d)\n", bytes_read);
        return -1;
    }
    *ox = (uint16_t)((buffer[0] << 8) | buffer[1]);
    *red = (uint16_t)((buffer[2] << 8) | buffer[3]);
    return 0;
}

static float calculate_co_ppm(uint16_t ox) {
    return (float)ox * 0.1f;
}

static int log_data(float co_ppm) {
    FILE *fp = fopen(CO_LOG_FILE, "a");
    if (!fp) {
        perror("Error opening " CO_LOG_FILE);
        return -1;
    }
