/*
 * Raspberry Pi 4 Model B – dual IMP23ABSU microphone sound-pressure logger.
 *
 * Wiring:
 *   IMP23ABSU OUT1  -> GPIO2  (BCM2, I2C SDA1)
 *   IMP23ABSU OUT2  -> GPIO3  (BCM3, I2C SCL1)
 *   IMP23ABSU VDD   -> 3.3 V
 *   IMP23ABSU GND   -> GND
 *
 * The IMP23ABSU is an ANALOG MEMS microphone; the Raspberry Pi GPIO pins
 * are sampled as analog voltages via the on-chip comparator (pulled high
 * by the internal pull-up).  This is a bit-banged I2C emulation that reads
 * the analog level on each GPIO and converts it to a signed 16-bit value.
 *
 * Build:  gcc -O2 -Wall -Wextra -o audio_logger audio_logger.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS          "/dev/i2c-1"
#define LOG_FILE         "audio_log.txt"
#define SAMPLE_PERIOD_US 100000   /* 100 ms */
#define ERROR_VALUE      (-999.0f)

/* ---- Per-sample state ---- */
typedef struct {
    int      fd;
    int      gpio;          /* BCM pin number */
    float    last_raw;      /* previous sample for delta */
    bool     have_last;     /* initialised yet? */
} sample_ctx_t;

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read the analog comparator on a GPIO pin and return a signed 16-bit
 * value.  The comparator is driven high by the internal pull-up when
 * the pin exceeds VDD/2; the kernel reports the pin as HIGH when the
 * analog voltage is above that threshold.  We treat HIGH as +1 and
 * LOW as -1.  This is a simple edge-crossing counter with a 100 ms
 * window; a more robust implementation would use a proper analog
 * threshold detector.  For this application the approximation is
 * acceptable. */
static int16_t read_analog_level(int fd, int gpio)
{
    if (fd < 0)
        return 0;

    /* Set the pin as input with the internal pull-up so the comparator
     * has a defined HIGH threshold. */
    uint8_t  buf[1] = { 0x0 };
    if (write(fd, buf, 1) != 1) {
        fprintf(stderr, "write(pull-up) failed: %s\n", strerror(errno));
        return 0;
    }

    /* Poll the pin state; after ~100 ms the comparator will have
     * settled. */
    uint8_t  val = 0;
    for (int i = 0; i < 100; i++) {
        if (read(fd, &val, 1) != 1) {
            fprintf(stderr, "read(poll) failed: %s\n", strerror(errno));
            return 0;
        }
        if (val & 0x01)
            return (int16_t)1;
        usleep(1000);
    }
    return (int16_t)0;
}

/* ------------------------------------------------------------------ */
static void sample_ctx_init(sample_ctx_t *sc, int fd, int gpio)
{
    sc->fd = fd;
    sc->gpio = gpio;
    sc->last_raw = 0.0f;
    sc->have_last = false;
}

/* ------------------------------------------------------------------ */
static void sample_ctx_destroy(sample_ctx_t *sc)
{
    if (sc->fd >= 0) {
        close(sc->fd);
        sc->fd = -1;
    }
}

/* ------------------------------------------------------------------ */
static void log_data(float avg_level)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[64];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s,%.2f\n", ts, avg_level);
    } else {
        fprintf(fp, "(time-error),%.2f\n", avg_level);
    }

    if (fclose(fp) != 0)
        fprintf(stderr, "fclose(%s) failed: %s\n", LOG_FILE, strerror(errno));
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Configure GPIO2/BCM2 as input with pull-up ---- */
    if (ioctl(i2c_fd, I2C_SLAVE, 2) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 2) failed: %s\n", strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    /* ---- Configure GPIO3/BCM3 as input with pull-up ---- */
    if (ioctl(i2c_fd, I2C_SLAVE, 3) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 3) failed: %s\n", strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    /* ---- Sample contexts ---- */
    sample_ctx_t ctx1 = { .fd = i2c_fd, .gpio = 2, .last_raw = 0.0f, .have_last = false };
    sample_ctx_t ctx2 = { .fd = i2c_fd, .gpio = 3, .last_raw = 0.0f, .have_last = false };

    /* ---- Main loop ---- */
    while (g_running) {
        /* Read both microphones */
        int16_t v1 = read_analog_level(ctx1.fd, ctx1.gpio);
        int16_t v2 = read_analog_level(ctx2.fd, ctx2.gpio);

        /* Compute average; if either read failed, log the error value */
        float avg = (v1 > 0) ? (v1 + v2) / 2.0f : ERROR_VALUE;
        if (v1 == ERROR_VALUE)
            avg = ERROR_VALUE;

        /* Log the sample */
        log_data(avg);

        /* Sleep 100 ms */
        usleep(SAMPLE_PERIOD_US);
    }

    /* ---- Clean shutdown ---- */
    close(i2c_fd);
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

