/*
 * Raspberry Pi 4 Model B – Dual ADMP401 MEMS Microphone RMS Monitor
 *
 * Samples two ADMP401 microphones via an MCP3008 ADC on SPI0 (CE0=GPIO8,
 * CE1=GPIO9, MISO=GPIO9, MOSI=GPIO10, SCLK=GPIO11) while driving an LED
 * on GPIO27.  Acquires 100 samples per channel (100 ms window) and logs
 * RMS levels to audio_events.csv.  The LED is illuminated for 500 ms
 * whenever either channel exceeds a high-level threshold.
 *
 * Build:  gcc -O2 -Wall -o audio_monitor audio_monitor.c -lpigpio -lrt
 * Run:    sudo ./audio_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL    0          /* MCP3008 on SPI0 CE0 (GPIO8)            */
#define SPI_SPEED      1000000    /* 1 MHz SPI clock                         */
#define SPI_FLAGS      0          /* Mode 0, active-low CE, 8-bit words      */

#define LED_GPIO       27         /* LED on GPIO27 (BCM)                      */

#define SAMPLES_PER_WINDOW 100    /* 100 ms window = 100 samples/ch        */
#define SAMPLE_PERIOD_US  1000    /* 1 ms between samples                   */
#define LED_ON_DURATION_US 500000  /* 500 ms LED illumination                */

#define HIGH_LEVEL_THRESHOLD  0.5f /* RMS threshold for LED trigger          */

#define ADC_MAX          1023     /* MCP3008 10-bit full-scale code         */

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* --------------------------- Signal Handler ------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- MCP3008 Read --------------------------------- */
/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (single-ended + channel, upper nibble)
 *   tx[2] = 0x00                       (clock out low nibble)
 * Result: 10-bit value assembled from rx[1] (lower 2 bits) and rx[2] (8 bits).
 */
static int mcp3008_read(int handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    if (spiXfer(handle, tx, rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed on channel %d\n", channel);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
}

/* --------------------------- RMS Calculation -------------------------------- */
static float calculate_rms(int *samples, int num_samples)
{
    double sum_sq = 0.0;
    for (int i = 0; i < num_samples; i++) {
        double v = (double)samples[i];
        sum_sq += v * v;
    }
    return (float)sqrt(sum_sq / (double)num_samples);
}

/* --------------------------- Timestamp ------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm timeinfo;

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &timeinfo);
}

/* --------------------------- CSV Logging ----------------------------------- */
static int log_data(const char *timestamp, float rms1, float rms2)
{
    FILE *fp = fopen("audio_events.csv", "a");
    if (!fp) {
        perror("fopen(audio_events.csv)");
        return -1;
    }

    if (fprintf(fp, "%s,%.4f,%.4f\n", timestamp, rms1, rms2) < 0) {
        perror("fprintf");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }
    return 0;
}

/* --------------------------- LED Control ---------------------------------- */
static void led_on(void)
{
    if (gpioWrite(LED_GPIO, 1) < 0) {
        fprintf(stderr, "gpioWrite(LED on) failed\n");
    }
}

static void led_off(void)
{
    if (gpioWrite(LED_GPIO, 0) < 0) {
