    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Audio monitoring started. Press Ctrl+C to exit.\n");

    int samples[2][SAMPLES_PER_WINDOW];
    int sample_idx = 0;

    while (g_running) {
        for (int ch = 0; ch < 2; ch++) {
            int val = mcp3008_read(g_spi_handle, ch);
            if (val < 0) {
                fprintf(stderr, "Error reading channel %d\n", ch);
                continue;
            }
            samples[ch][sample_idx] = val;
            sample_idx++;

            if (sample_idx >= SAMPLES_PER_WINDOW) {
                sample_idx = 0;
                float rms = calculate_rms(samples[ch], SAMPLES_PER_WINDOW);
                char ts[32];
                get_timestamp(ts, sizeof(ts));

                if (log_data(ts, rms, rms) != 0) {
                    fprintf(stderr, "Logging failed for channel %d\n", ch);
                } else {
                    printf("[%s] ch%d RMS=%.4f\n", ts, ch, rms);
                }

                if (rms > HIGH_LEVEL_THRESHOLD) {
                    led_on();
                    gpioDelay(LED_ON_DURATION_US);
                    led_off();
                }
            }
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* Cleanup */
    led_off();
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
    }
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
