/*
 * MLX91204 Hall-effect current sensor monitor via ADS1115 ADC.
 *
 * Hardware (Raspberry Pi 4 Model B):
 *   - ADS1115 ADC on I2C bus 1 (SDA = GPIO2, SCL = GPIO3)
 *   - MLX91204 analog output -> ADS1115 AIN0
 *   - Warning LED on GPIO17 (BCM)
 *
 * Build:  gcc -O2 -Wall -o current_monitor current_monitor.c -lm
 * Run:    sudo ./current_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <errno.h>
#include <string.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS          "/dev/i2c-1"
#define ADS1115_ADDR     0x48

/* ADS1115 register addresses */
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG     0x01

/* Config register bits */
#define ADS1115_CFG_OS_BEGIN   (1 << 15)
#define ADS1115_CFG_MUX_AIN0   (0x4000)   /* AIN0 vs GND */
#define ADS1115_CFG_PGA_4_096V (0x0200)   /* +/-4.096 V range */
#define ADS1115_CFG_MODE_SS   (0x0100)   /* Single-shot mode */
#define ADS1115_CFG_DR_128    (0x0080)   /* 128 SPS */
#define ADS1115_CFG_CQUE_NONE (0x0003)   /* Disable comparator */

#define WARNING_LED_PIN     17
#define BUFFER_SIZE         100
#define THRESHOLD_A         50.0
#define SAMPLE_RATE_HZ      10
#define SAMPLE_PERIOD_US    (1000000 / SAMPLE_RATE_HZ)
#define ADC_MAX_COUNT       32767.0   /* 16-bit signed, single-ended positive */
#define ADC_VREF            4.096
#define ADC_MAX_RAW         (ADC_VREF / 32767.0)

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static int g_led_pin = WARNING_LED_PIN;

/* Circular buffer */
static double g_current_buffer[BUFFER_SIZE];
static int    g_buf_head = 0;
static int    g_buf_count = 0;

/* ----------------------------- Prototypes -------------------------------- */
static int  ads1115_write_reg(int fd, uint8_t reg, uint16_t val);
static int  ads1115_read_reg(int fd, uint8_t reg, uint16_t *val);
static int  ads1115_init(int fd);
static int  ads1115_read_channel(int fd, int16_t *raw);
static double raw_to_current(int16_t raw);
static void buffer_add(double current);
static double buffer_average(void);
static void led_set(int on);
static void cleanup(void);
static void sigint_handler(int sig);

/* ----------------------------- I2C helpers -------------------------------- */
static int ads1115_write_reg(int fd, uint8_t reg, uint16_t val)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(val >> 8);
    buf[2] = (uint8_t)(val & 0xFF);

    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int ads1115_read_reg(int fd, uint8_t reg, uint16_t *val)
{
    uint8_t buf[2];

    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *val = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int ads1115_init(int fd)
{
    uint16_t config = ADS1115_CFG_OS_BEGIN | ADS1115_CFG_MUX_AIN0 |
                      ADS1115_CFG_PGA_4_096V | ADS1115_CFG_MODE_SS |
                      ADS1115_CFG_DR_128    | ADS1115_CFG_CQUE_NONE;

    if (ads1115_write_reg(fd, ADS1115_REG_CONFIG, config) != 0)
        return -1;

    /* Wait for the first conversion to complete (~8 ms at 128 SPS) */
    usleep(10000);
    return 0;
}

static int ads1115_read_channel(int fd, int16_t *raw)
{
    uint16_t config = ADS1115_CFG_OS_BEGIN | ADS1115_CFG_MUX_AIN0 |
                      ADS1115_CFG_PGA_4_096V | ADS1115_CFG_MODE_SS |
                      ADS1115_CFG_DR_128    | ADS1115_CFG_CQUE_NONE;

    if (ads1115_write_reg(fd, ADS1115_REG_CONFIG, config) != 0)
        return -1;

    /* Wait for conversion to complete */
    usleep(10000);

    uint16_t val;
    if (ads1115_read_reg(fd, ADS1115_REG_CONVERSION, &val) != 0)
        return -1;

    *raw = (int16_t)val;
    return 0;
}

static double raw_to_current(int16_t raw)
{
    return (double)raw * ADC_VREF / ADC_MAX_COUNT;
}

/* ----------------------------- Circular buffer ----------------------------- */
static void buffer_add(double current)
{
    g_current_buffer[g_buf_head] = current;
    g_buf_head = (g_buf_head + 1) % BUFFER_SIZE;
    if (g_buf_count < BUFFER_SIZE)
        g_buf_count++;
}

static double buffer_average(void)
{
    if (g_buf_count == 0)
        return 0.0;
    double sum = 0.0;
    for (int i = 0; i < g_buf_count; i++)
        sum += g_current_buffer[i];
    return sum / (double)g_buf_count;
}

static void led_set(int on)
{
    if (g_led_pin < 0 || g_led_pin > 31)
        return;
    if (on)
        gpioWrite(g_led_pin, 1);
    else
        gpioWrite(g_led_pin, 0);
}

/* ----------------------------- Cleanup ------------------------------------- */
static void cleanup(void)
{
    led_set(0);
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                ADS1115_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize ADS1115 */
    if (ads1115_init(g_i2c_fd) != 0) {
        fprintf(stderr, "ADS1115 initialization failed (sensor absent or bus error).\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure LED pin */
    if (gpioSetMode(WARNING_LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Cannot set GPIO%d as output: %s\n",
                WARNING_LED_PIN, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    led_set(0);

    printf("Monitoring MLX91204 current via ADS1115 on %s (A0, 10 Hz, threshold %.1f A)...\n",
           I2C_BUS, THRESHOLD_A);
    printf("Press Ctrl+C to exit.\n");

    int consecutive_errors = 0;

    while (g_running) {
        int16_t raw;
        if (ads1115_read_channel(g_i2c_fd, &raw) != 0) {
            consecutive_errors++;
            if (consecutive_errors >= 10) {
                fprintf(stderr, "Too many consecutive I2C errors; aborting.\n");
                break;
            }
            usleep(SAMPLE_PERIOD_US);
            continue;
        }
        consecutive_errors = 0;

        double current = raw_to_current(raw);
        buffer_add(current);

        double avg = buffer_average();
        printf("Raw: %6d  Current: %7.2f A  Avg: %7.2f A\n", raw, current, avg);

        if (avg > THRESHOLD_A) {
            led_set(1);
            printf("WARNING: Average current %.2f A exceeds threshold %.1f A!\n",
                   avg, THRESHOLD_A);
            led_set(0);
        }

        usleep(SAMPLE_PERIOD_US);
    }

    cleanup();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

