static void led_set(int on)
{
    if (g_led_pin < 0 || g_led_pin > 31)
        return;
    if (on)
        gpioWrite(g_led_pin, 1);
    else
        gpioWrite(g_led_pin, 0);
}

/* ----------------------------- Cleanup ------------------------------------- */
static void cleanup(void)
{
    led_set(0);
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                ADS1115_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize ADS1115 */
    if (ads1115_init(g_i2c_fd) != 0) {
        fprintf(stderr, "ADS1115 initialization failed (sensor absent or bus error).\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure LED pin */
    if (gpioSetMode(WARNING_LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Cannot set GPIO%d as output: %s\n",
                WARNING_LED_PIN, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    led_set(0);

    printf("Monitoring MLX91204 current via ADS1115 on %s (A0, 10 Hz, threshold %.1f A)...\n",
           I2C_BUS, THRESHOLD_A);
    printf("Press Ctrl+C to exit.\n");

    int consecutive_errors = 0;

    while (g_running) {
        int16_t raw;
        if (ads1115_read_channel(g_i2c_fd, &raw) != 0) {
            consecutive_errors++;
            if (consecutive_errors >= 10) {
                fprintf(stderr, "Too many consecutive I2C errors; aborting.\n");
                break;
            }
            usleep(SAMPLE_PERIOD_US);
            continue;
        }
        consecutive_errors = 0;

        double current = raw_to_current(raw);
        buffer_add(current);

        double avg = buffer_average();
        printf("Raw: %6d  Current: %7.2f A  Avg: %7.2f A\n", raw, current, avg);

        if (avg > THRESHOLD_A) {
            led_set(1);
            printf("WARNING: Average current %.2f A exceeds threshold %.1f A!\n",
                   avg, THRESHOLD_A);
            led_set(0);
        }

        usleep(SAMPLE_PERIOD_US);
    }

    cleanup();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

