/*
 * TCS34725 color sensor logger for Raspberry Pi 4 Model B
 * Bus: I2C-1  (GPIO2=SDA, GPIO3=SCL)
 * Sensor: Adafruit TCS34725 breakout
 *
 * Build: gcc -O2 -Wall -Wextra -o color_logger color_logger.c -ltcs34725
 *
 * The Adafruit TCS34725 driver is a small shim that exposes the
 * sensor's registers via a single I2C handle.  It does not require
 * wiringPi; the driver's own build system produces a static library
 * that is linked here.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#include <pigpio.h>

/* ---- TCS34725 constants (from datasheet / Adafruit driver) ---- */
#define TCS34725_I2C_BUS        1
#define TCS34725_I2C_ADDR       0x29
#define TCS34725_COMMAND_BIT    0x80

#define TCS34725_ENABLE         0x00
#define TCS34725_ENABLE_PON     0x01
#define TCS34725_ENABLE_AEN     0x02

#define TCS34725_ID             0x12
#define TCS34725_ID_VALUE       0x44

#define TCS34725_CDATAL         0x14
#define TCS34725_CDATAH         0x15
#define TCS34725_RDATAL         0x16
#define TCS34725_RDATAH         0x17
#define TCS34725_GDATAL         0x18
#define TCS34725_GDATAH         0x19
#define TCS34725_BDATAL         0x1A
#define TCS34725_BDATAH         0x1B

#define LOG_FILE               "color_log.csv"
#define SAMPLE_INTERVAL_US     1000000   /* 1 second */
#define MAX_CONSECUTIVE_ERRORS 3

/* ---- Globals for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian register pair from the TCS34725.        */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int tcs_read_reg16(int handle, uint8_t reg, uint16_t *out)
{
    char cmd = (char)(reg | TCS34725_COMMAND_BIT);
    char buf[2];

    if (i2cWriteDevice(handle, &cmd, 1) != 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice (reg 0x%02X): %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "[ERROR] i2cReadDevice (reg 0x%02X): %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = (uint16_t)((uint8_t)buf[0] | ((uint8_t)buf[1] << 8));
    return 0;
}

/* ------------------------------------------------------------------ */
/* Write an 8-bit register on the TCS34725.                            */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int tcs_write_reg8(int handle, uint8_t reg, uint8_t value)
{
    char cmd = (char)(reg | TCS34725_COMMAND_BIT);
    char buf[2] = { (char)value, 0x00 };

    if (i2cWriteDevice(handle, &cmd, 1) != 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice (reg 0x%02X): %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (i2cWriteDevice(handle, buf, 2) != 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice (reg 0x%02X): %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise the TCS34725: power on, enable RGBC, wait 3 ms.           */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int tcs_init(int handle)
{
    if (tcs_write_reg8(handle, TCS34725_ENABLE, TCS34725_ENABLE_PON) != 0)
        return -1;
    gpioDelay(3000);  /* 3 ms power-on settling */

    if (tcs_write_reg8(handle, TCS34725_ENABLE,
                       TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read clear, red, green, blue channels.                              */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int tcs_read_crgb(int handle, uint16_t *clear, uint16_t *red,
                         uint16_t *green, uint16_t *blue)
{
    if (tcs_read_reg16(handle, TCS34725_CDATAL, clear) != 0) return -1;
    if (tcs_read_reg16(handle, TCS34725_RDATAL, red)   != 0) return -1;
    if (tcs_read_reg16(handle, TCS34725_GDATAL, green) != 0) return -1;
    if (tcs_read_reg16(handle, TCS34725_BDATAL, blue)  != 0) return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, uint16_t clear, uint16_t red,
                    uint16_t green, uint16_t blue)
{
    time_t     rawtime;
    struct tm  tm_info;
    char       timestamp[24];

    time(&rawtime);
    localtime_r(&rawtime, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    if (fprintf(fp, "%s,%u,%u,%u,%u\n", timestamp, clear, red, green, blue) < 0) {
        fprintf(stderr, "[ERROR] fprintf to log: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "[WARN] fflush log: %s\n", strerror(errno));
    }
    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    uint16_t clear, red, green, blue;

    /* ---- Initialise pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] gpioInitialise failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    g_i2c_handle = i2cOpen(TCS34725_I2C_BUS, TCS34725_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                TCS34725_I2C_BUS, TCS34725_I2C_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Verify sensor identity ---- */
    int id = i2cReadByteData(g_i2c_handle, TCS34725_ID);
    if (id < 0) {
        fprintf(stderr, "[FATAL] Failed to read ID register: %s\n",
                strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (id != TCS34725_ID_VALUE) {
        fprintf(stderr, "[FATAL] Unexpected ID 0x%02X (expected 0x%02X)\n",
                id, TCS34725_ID_VALUE);
        cleanup();
        return EXIT_FAILURE;
    }
    printf("[INFO] TCS34725 detected (ID=0x%02X)\n", id);

    /* ---- Initialise sensor ---- */
    if (tcs_init(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] TCS34725 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open log file (append; create if missing) ---- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open %s: %s\n",
                LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "clear,red,green,blue\n");
        fflush(g_log_file);
    }

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("[INFO] Logging to %s every 1 s. Press Ctrl-C to stop.\n",
           LOG_FILE);

    /* ---- Main loop ---- */
    while (g_running) {
        if (tcs_read_crgb(g_i2c_handle, &clear, &red, &green, &blue) == 0) {
            if (log_data(g_log_file, clear, red, green, blue) != 0) {
                fprintf(stderr, "[ERROR] Logging failed; aborting.\n");
                break;
            }
        } else {
            fprintf(stderr, "[WARN] Sensor read failed; continuing.\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* ---- Graceful exit ---- */
    printf("\n[INFO] Shutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

