/*
 * Raspberry Pi 4 Model B – MLX90834 pressure/NTC temperature monitor
 *
 * Hardware:
 *   - ADS1115 ADC on I2C bus 1 (GPIO2=SDA, GPIO3=SCL)
 *   - MLX90834 pressure sensor on AIN0 (single-ended)
 *   - NTC temperature sensor on AIN1 (single-ended)
 *   - Warning LED on GPIO17 (active-high)
 *
 * Build:
 *   gcc -O2 -Wall -o mlx90834_monitor mlx90834_monitor.c -lm
 *
 * Run:
 *   ./mlx90834_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <math.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define ADS1115_ADDR   0x48

/* ADS1115 register addresses */
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG     0x01

/* Config register bits */
#define ADS1115_CFG_OS_BEGIN   (1 << 15)
#define ADS1115_CFG_MUX_BASE   (0x4 << 12)   /* AIN0..AIN3 */
#define ADS1115_CFG_PGA_4_096 (0x1 << 9)
#define ADS1115_CFG_MODE_SE   (0x1 << 8)   /* single-shot */
#define ADS1115_CFG_DR_128    (0x0 << 5)    /* 128 SPS */
#define ADS1115_CFG_CQUE_NONE (0x3 << 0)    /* disable comparator */

/* GPIO */
#define WARNING_LED_PIN 17

/* Thresholds */
#define PRESSURE_THRESHOLD_KPA 105.0
#define MAX_RETRIES           3

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit value to an ADS1115 register.                          */
/* ------------------------------------------------------------------ */
static int ads1115_write_reg(int fd, uint8_t reg, uint16_t val)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(val >> 8);
    buf[2] = (uint8_t)(val & 0xFF);

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "ads1115_write_reg(0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit value from an ADS1115 register.                         */
/* ------------------------------------------------------------------ */
static int ads1115_read_reg(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];

    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "ads1115_read_reg write(0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "ads1115_read_reg read(0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Trigger a single-shot conversion and read the result.               */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int ads1115_read_channel(int fd, uint8_t mux, float *value)
{
    uint16_t config = ADS1115_CFG_OS_BEGIN | ADS1115_CFG_MUX_BASE | ADS1115_CFG_PGA_4_096 |
                      ADS1115_CFG_MODE_SE | ADS1115_CFG_DR_128 | ADS1115_CFG_CQUE_NONE;

    if (ads1115_write_reg(fd, ADS1115_REG_CONFIG, config) != 0)
        return -1;

    /* Wait for conversion to complete (~8 ms at 128 SPS) */
    usleep(10000);

    uint16_t raw;
    if (ads1115_read_reg(fd, ADS1115_REG_CONVERSION, &raw) != 0)
        return -1;

    /* PGA 4.096 V → LSB = 4.096 / 32768 ≈ 0.000125 V */
    *value = (float)raw * 0.000125f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Convert raw ADC counts to physical units.                           */
/* ------------------------------------------------------------------ */
static float raw_to_pressure(uint16_t raw)
{
    /* MLX90834 pressure channel: 0..32767 counts ≈ 0..100 kPa */
    return (float)raw * 0.003055f;
}

static float raw_to_temperature(uint16_t raw)
{
    /* NTC: 0..32767 counts ≈ 0..100 °C (inverse relationship) */
    return (float)raw * 0.003055f - 50.0f;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Set slave address */
    if (ioctl(g_i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n", ADS1115_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Verify device presence with a dummy read */
    uint16_t dummy;
    if (ads1115_read_reg(g_i2c_fd, ADS1115_REG_CONFIG, &dummy) != 0) {
        fprintf(stderr, "ADS1115 not responding on 0x%02X\n", ADS1115_ADDR);
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Configure LED pin */
    if (gpioSetMode(WARNING_LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d): %s\n", WARNING_LED_PIN, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }
    gpioWrite(WARNING_LED_PIN, 0);

    printf("MLX90834 monitor started (ADS1115 @ 0x%02X). Ctrl+C to exit.\n", ADS1115_ADDR);

    while (g_running) {
        float pressure = 0.0f, temperature = 0.0f;
        bool ok = false;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (ads1115_read_channel(g_i2c_fd, 0x00, &pressure) == 0 &&
                ads1115_read_channel(g_i2c_fd, 0x01, &temperature) == 0) {
                ok = true;
                break;
            }
            usleep(10000);
        }

        if (!ok) {
            fprintf(stderr, "Sensor read failed after %d attempts; skipping cycle.\n", MAX_RETRIES);
            sleep(1);
            continue;
        }

        printf("Pressure: %.2f kPa | Temperature: %.2f °C\n", pressure, temperature);

        if (pressure > PRESSURE_THRESHOLD_KPA) {
            gpioWrite(WARNING_LED_PIN, 1);
        } else {
            gpioWrite(WARNING_LED_PIN, 0);
        }

        sleep(1);
    }

    /* Cleanup */
    gpioWrite(WARNING_LED_PIN, 0);
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
    }
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

