#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_MODE        0
#define SPI_BITS        8
#define SPI_CS          8
#define ADC_CHANNEL     0
#define OVERCURRENT_THRESHOLD 10.0
#define SHUTDOWN_GPIO   27
#define SAMPLE_INTERVAL_US 100000
#define ADC_MAX_VALUE   1023

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int init_spi(void) {
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI max speed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

static int read_adc(int fd, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer error: %s\n", strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static float convert_to_current(int adc_value) {
    return (float)adc_value * 0.001f;
}

static void log_current(float current) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(g_log_file, "%s, Current: %.2f A\n", timestamp, current) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
    } else {
        fflush(g_log_file);
    }
}

static void shutdown_motor(void) {
    if (gpioWrite(SHUTDOWN_GPIO, 1) < 0) {
        fprintf(stderr, "Error setting shutdown GPIO HIGH\n");
    }
}

static void cleanup(void) {
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioWrite(SHUTDOWN_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error registering SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(SHUTDOWN_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting shutdown GPIO mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioWrite(SHUTDOWN_GPIO, 0) < 0) {
        fprintf(stderr, "Error initializing shutdown GPIO\n");
        gpioTerminate();
        return 1;
    }

    g_spi_fd = init_spi();
    if (g_spi_fd < 0) {
        gpioTerminate();
        return 1;
    }

    g_log_file = fopen("current_log.txt", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(g_spi_fd);
        gpioTerminate();
        return 1;
    }

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int adc_value = read_adc(g_spi_fd, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        float current = convert_to_current(adc_value);

        log_current(current);

        if (current > OVERCURRENT_THRESHOLD) {
            fprintf(stderr, "OVERCURRENT DETECTED! Current: %.2f A\n", current);
            log_current(current);
            shutdown_motor();
            break;
        }

        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

