/*
 * Raspberry Pi 4 Model B – MLX90830 pressure sensor via ADS1115 ADC
 *
 * Wiring:
 *   ADS1115 SDA  -> Pi GPIO2 (BCM 2, I2C bus 1)
 *   ADS1115 SCL  -> Pi GPIO3 (BCM 3, I2C bus 1)
 *   ADS1115 VDD  -> 3.3 V
 *   ADS1115 GND  -> GND
 *   ADS1115 AIN0 -> MLX90830 analog output
 *
 * Build:  gcc -O2 -Wall -o pressure_log pressure_log.c -lm
 * Run:    ./pressure_log
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <math.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define ADC_DEVICE     "ADS1115"
#define LOG_FILE       "pressure_log.txt"
#define SAMPLE_PERIOD  1          /* seconds between samples */
#define ADC_MAX_COUNT  32767.0    /* 16-bit signed positive max */
#define ADC_VREF       4.096      /* volts (PGA gain 1) */
#define ADC_RESOLUTION  1.0       /* LSB per volt */
#define PRESSURE_MIN   0.0
#define PRESSURE_MAX   100.0
#define ADC_CHANNEL    0          /* AIN0 */

/* ADS1115 register addresses */
#define ADS1115_REG_CONVERSION  0x00
#define ADS1115_REG_CONFIG      0x01

/* Config register bits */
#define ADS1115_CFG_OS_BEGIN    (1 << 15)
#define ADS1115_CFG_MUX_AIN0    (0x4000)  /* AIN0 vs GND */
#define ADS1115_CFG_PGA_4_096  (0x0200)  /* PGA = 4.096 V */
#define ADS1115_CFG_MODE_SINGLE (0x0100)  /* single-shot */
#define ADS1115_CFG_DR_128SPS  (0x0080)  /* 128 SPS */
#define ADS1115_CFG_CQUE_NONE  (0x0003)  /* disable comparator */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit value to an ADS1115 register.                        */
/* ------------------------------------------------------------------ */
static int ads1115_write_reg(int fd, uint8_t reg, uint16_t value)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)((value >> 8) & 0xFF);
    buf[2] = (uint8_t)(value & 0xFF);

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "ads1115_write_reg(0x%02X): write failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit value from an ADS1115 register.                       */
/* ------------------------------------------------------------------ */
static int ads1115_read_reg(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];

    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "ads1115_read_reg: write pointer failed: %s\n",
                strerror(errno));
        return -1;
    }
    if (read(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "ads1115_read_reg: read failed: %s\n",
                strerror(errno));
        return -1;
    }
    *out = (uint16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Trigger a single-shot conversion and read the raw ADC value.       */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int ads1115_read_raw(int fd, int16_t *raw_out)
{
    uint16_t config = ADS1115_CFG_OS_BEGIN
                    | ADS1115_CFG_MUX_AIN0
                    | ADS1115_CFG_PGA_4_096
                    | ADS1115_CFG_MODE_SINGLE
                    | ADS1115_CFG_DR_128SPS
                    | ADS1115_CFG_CQUE_NONE;

    if (ads1115_write_reg(fd, ADS1115_REG_CONFIG, config) != 0)
        return -1;

    /* Wait for conversion to complete (~8 ms at 128 SPS). */
    struct timespec ts = { 0, 10000000L };  /* 10 ms */
    nanosleep(&ts, NULL);

    uint16_t conv;
    if (ads1115_read_reg(fd, ADS1115_REG_CONVERSION, &conv) != 0)
        return -1;

    *raw_out = (int16_t)conv;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Convert raw ADC count to pressure (Pa).                            */
/* ------------------------------------------------------------------ */
static double raw_to_pressure(int16_t raw)
{
    if (raw < 0)
        raw = 0;
    double voltage = (raw / ADC_MAX_COUNT) * ADC_VREF;
    double pressure = (voltage / 3.0) * 100.0;   /* 0–100 kPa */
    return pressure;
}

/* ------------------------------------------------------------------ */
/* Log a pressure reading with an ISO-8601 timestamp.                  */
/* ------------------------------------------------------------------ */
static void log_pressure(double pressure)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "log_pressure: cannot open %s: %s\n",
                LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "log_pressure: localtime_r failed: %s\n",
                strerror(errno));
        fclose(fp);
        return;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);

    fprintf(fp, "%s, %.2f kPa\n", ts, pressure);
    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper – safe to call multiple times.                       */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Set slave address (ADS1115 defaults to 0x48 when not in address-able mode) */
    if (ioctl(g_i2c_fd, I2C_SLAVE, 0x48) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x48): %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Verify device presence by reading the config register */
    uint16_t cfg;
    if (ads1115_read_reg(g_i2c_fd, ADS1115_REG_CONFIG, &cfg) != 0) {
        fprintf(stderr, "ADS1115 not detected on bus %s at 0x48\n", I2C_BUS);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ADS1115 initialized on %s (0x48). Logging to %s every %d s.\n",
           I2C_BUS, LOG_FILE, SAMPLE_PERIOD);
    printf("Press Ctrl-C to stop.\n");

    int consecutive_errors = 0;

    while (g_running) {
        int16_t raw;
        if (ads1115_read_raw(g_i2c_fd, &raw) != 0) {
            consecutive_errors++;
            fprintf(stderr, "ADC read error (%d consecutive)\n",
                    consecutive_errors);
            if (consecutive_errors >= 10) {
                fprintf(stderr, "Too many consecutive ADC errors; aborting.\n");
                break;
            }
            sleep(SAMPLE_PERIOD);
            continue;
        }
        consecutive_errors = 0;

        double pressure = raw_to_pressure(raw);

        if (pressure < PRESSURE_MIN || pressure > PRESSURE_MAX) {
            fprintf(stderr, "Pressure out of range: %.2f kPa (raw=%d)\n",
                    pressure, raw);
        } else {
            log_pressure(pressure);
            printf("Pressure: %.2f kPa (raw=%d)\n", pressure, raw);
        }

        sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down cleanly.\n");
    cleanup();
    return EXIT_SUCCESS;
}

