    fprintf(fp, "%s, %.2f kPa\n", ts, pressure);
    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper – safe to call multiple times.                       */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Set slave address (ADS1115 defaults to 0x48 when not in address-able mode) */
    if (ioctl(g_i2c_fd, I2C_SLAVE, 0x48) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x48): %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Verify device presence by reading the config register */
    uint16_t cfg;
    if (ads1115_read_reg(g_i2c_fd, ADS1115_REG_CONFIG, &cfg) != 0) {
        fprintf(stderr, "ADS1115 not detected on bus %s at 0x48\n", I2C_BUS);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ADS1115 initialized on %s (0x48). Logging to %s every %d s.\n",
           I2C_BUS, LOG_FILE, SAMPLE_PERIOD);
    printf("Press Ctrl-C to stop.\n");

    int consecutive_errors = 0;

    while (g_running) {
        int16_t raw;
        if (ads1115_read_raw(g_i2c_fd, &raw) != 0) {
            consecutive_errors++;
            fprintf(stderr, "ADC read error (%d consecutive)\n",
                    consecutive_errors);
            if (consecutive_errors >= 10) {
                fprintf(stderr, "Too many consecutive ADC errors; aborting.\n");
                break;
            }
            sleep(SAMPLE_PERIOD);
            continue;
        }
        consecutive_errors = 0;

        double pressure = raw_to_pressure(raw);

        if (pressure < PRESSURE_MIN || pressure > PRESSURE_MAX) {
            fprintf(stderr, "Pressure out of range: %.2f kPa (raw=%d)\n",
                    pressure, raw);
        } else {
            log_pressure(pressure);
            printf("Pressure: %.2f kPa (raw=%d)\n", pressure, raw);
        }

        sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down cleanly.\n");
    cleanup();
    return EXIT_SUCCESS;
}

