#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define MCP3208_CHANNEL 0
#define HUMIDITY_THRESHOLD 80.0
#define LOG_FILE "humidity_log.txt"
#define EMAIL_RECIPIENT "recipient@example.com"
#define EMAIL_SENDER "sender@example.com"
#define EMAIL_SERVER "smtp.example.com"

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    unsigned char mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Error setting SPI mode");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    unsigned char bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Error setting bits per word");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    unsigned int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Error setting SPI speed");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

static int read_mcp3208(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3208 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((channel & 0x07) << 4) | 0x80, 0x00 };
    unsigned char rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("Error during SPI transfer");
        return -1;
    }

    return ((rx[1] & 0x0F) << 8) | rx[2];
}

static float adc_to_humidity(int adc_value) {
    float humidity = 100.0 - ((float)adc_value / 4095.0) * 100.0;
    if (humidity < 0.0) humidity = 0.0;
    if (humidity > 100.0) humidity = 100.0;
    return humidity;
}

static float adc_to_temperature(int adc_value) {
    float temperature = 25.0 + ((float)adc_value / 4095.0) * 75.0;
    return temperature;
}

static void log_data(float humidity, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, humidity, temperature);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

static void send_email_alert(float humidity) {
    char command[512];
    snprintf(command, sizeof(command),
             "echo \"Subject: Humidity Alert\n\nHumidity level exceeded threshold.\n\nCurrent humidity: %.2f%%\" | ssmtp %s",
             humidity, EMAIL_RECIPIENT);

    int result = system(command);
    if (result == -1) {
        perror("Error executing ssmtp command");
    } else if (result != 0) {
        fprintf(stderr, "ssmtp command returned non-zero exit code: %d\n", result);
    }
}

static void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Error registering SIGINT handler");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Error registering SIGTERM handler");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (spi_init() < 0) {
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    printf("Humidity monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = read_mcp3208(MCP3208_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            break;
        }

        float humidity = adc_to_humidity(adc_value);
        float temperature = adc_to_temperature(adc_value);

        log_data(humidity, temperature);

        if (humidity > HUMIDITY_THRESHOLD) {
            send_email_alert(humidity);
        }

        gpioDelay(5000000);
    }

    cleanup();
    return 0;
}

