#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_BITS         8
#define SPI_MODE         0

#define GPIO_CHIP        "gpiochip4"
#define CE0_LINE         8
#define SCLK_LINE        11
#define MOSI_LINE        10
#define MISO_LINE        9

#define ADC_CHANNEL      0
#define ADC_MAX          4095
#define ADC_VREF         3.3
#define TMP36_OFFSET     500.0
#define TMP36_SCALE      100.0

#define LOG_FILE         "temperature_log.csv"
#define SAMPLE_PERIOD_US 1000000
#define MAX_CONSEC_ERRORS 10

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int spi_init(void) {
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

static int gpio_init(void) {
    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open(%s): %s\n", GPIO_CHIP, strerror(errno));
        return -1;
    }

    struct gpiod_line *ce = gpiod_chip_get_line(chip, CE0_LINE);
    struct gpiod_line *sck = gpiod_chip_get_line(chip, SCLK_LINE);
    struct gpiod_line *mosi = gpiod_chip_get_line(chip, MOSI_LINE);
    struct gpiod_line *miso = gpiod_chip_get_line(chip, MISO_LINE);

    if (!ce || !sck || !mosi || !miso) {
        fprintf(stderr, "gpiod_chip_get_line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(ce, "mcp3208-ce", 1) < 0) {
        fprintf(stderr, "gpiod_line_request_output(ce): %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(sck, "mcp3208-sck", 0) < 0) {
        fprintf(stderr, "gpiod_line_request_output(sck): %s\n", strerror(errno));
        gpiod_line_release(ce);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(mosi, "mcp3208-mosi", 0) < 0) {
        fprintf(stderr, "gpiod_line_request_output(mosi): %s\n", strerror(errno));
        gpiod_line_release(ce);
        gpiod_line_release(sck);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_input(miso, "mcp3208-miso") < 0) {
        fprintf(stderr, "gpiod_line_request_input(miso): %s\n", strerror(errno));
        gpiod_line_release(ce);
        gpiod_line_release(sck);
        gpiod_line_release(mosi);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

static int spi_transfer(uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = len;
    tr.speed_hz = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs = 0;
    tr.cs_change = 0;

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_adc(uint16_t *value) {
    uint8_t tx[3] = { 0x01, (uint8_t)(0x80 | (ADC_CHANNEL << 4)), 0x00 };
    uint8_t rx[3] = { 0 };

    if (gpiod_line_set_value(ce, 0) < 0) {
        fprintf(stderr, "gpiod_line_set_value(ce,0): %s\n", strerror(errno));
        return -1;
    }

    if (spi_transfer(tx, rx, 3) < 0) {
        gpiod_line_set_value(ce, 1);
        return -1;
    }

    if (gpiod_line_set_value(ce, 1) < 0) {
        fprintf(stderr, "gpiod_line_set_value(ce,1): %s\n", strerror(errno));
        return -1;
    }

    *value = ((uint16_t)rx[1] << 8) | rx[2];
    return 0;
}

static float adc_to_celsius(uint16_t adc) {
    float voltage = (float)adc * ADC_VREF / ADC_MAX;
    return (voltage - TMP36_OFFSET) * TMP36_SCALE;
}

static int log_open(void) {
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    fseek(g_log_fp, 0, SEEK_END);
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "timestamp,temperature_celsius\n");
        fflush(g_log_fp);
    }
    return 0;
}

static void log_sample(float temp) {
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(g_log_fp, "%s,%.2f\n", ts, temp);
    fflush(g_log_fp);
}

static void cleanup(void) {
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    if (gpiod_line_is_requested(ce)) {
        gpiod_line_set_value(ce, 1);
        gpiod_line_release(ce);
    }
    if (gpiod_line_is_requested(sck)) gpiod_line_release(sck);
    if (gpiod_line_is_requested(mosi)) gpiod_line_release(mosi);
    if (gpiod_line_is_requested(miso)) gpiod_line_release(miso);
    gpiod_chip_close(GPIO_CHIP);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return 1;
    }

    g_spi_fd = spi_init();
    if (g_spi_fd < 0) {
        cleanup();
        return 1;
    }

    if (gpio_init() < 0) {
        cleanup();
        return 1;
    }

    if (log_open() < 0) {
        cleanup();
        return 1;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    uint16_t consecutive_errors = 0;

    while (g_running) {
        uint16_t adc = 0;
        if (read_adc(&adc) < 0) {
            consecutive_errors++;
            fprintf(stderr, "ADC read error (%u)\n", consecutive_errors);
            if (consecutive_errors >= MAX_CONSEC_ERRORS) {
                fprintf(stderr, "Too many consecutive errors, aborting.\n");
                break;
            }
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        consecutive_errors = 0;

        float temp = adc_to_celsius(adc);

        if (temp < -40.0f || temp > 125.0f) {
            fprintf(stderr, "Warning: temperature out of range: %.2f C\n", temp);
        }

        log_sample(temp);
        usleep(SAMPLE_PERIOD_US);
    }

    cleanup();
    printf("Exiting.\n");
    return 0;
}

