/*
 * ADXL335 impact logger via MCP3008 ADC on Raspberry Pi 4 Model B
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V (Pin 1)
 *   MCP3008 VREF -> 3.3 V (Pin 1)
 *   MCP3008 AGND -> GND
 *   MCP3008 DGND -> GND
 *   MCP3008 CLK  -> GPIO11 (SPI0 SCLK)
 *   MCP3008 DOUT -> GPIO9  (SPI0 MISO)
 *   MCP3008 DIN  -> GPIO10 (SPI0 MOSI)
 *   MCP3008 CS   -> GPIO8  (SPI0 CE0)
 *   MCP3008 CH0  -> ADXL335 X out
 *   MCP3008 CH1  -> ADXL335 Y out
 *   MCP3008 CH2  -> ADXL335 Z out
 *
 * Build: gcc -O2 -Wall -o impact_logger impact_logger.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U
#define SPI_MODE        SPI_MODE_0
#define SPI_BITS        8

#define ADC_CHANNEL_X   0
#define ADC_CHANNEL_Y   1
#define ADC_CHANNEL_Z   2

#define LOG_FILE        "impact_log.txt"
#define SAMPLE_PERIOD_US 10000U   /* 100 Hz */
#define IMPACT_THRESHOLD 100.0f   /* raw ADC threshold */

static volatile sig_atomic_t g_running = 1;
static int  g_spi_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read a single-ended channel from the MCP3008.                       */
/* Returns 0..1023 on success, -1 on error.                            */
/* ------------------------------------------------------------------ */
static int mcp3008_read(int fd, uint8_t channel)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid channel %u\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read: 3-byte transfer.
     * Byte 0: 0x01  (start bit)
     * Byte 1: (0x08 | channel) << 4  (single-ended + channel select)
     * Byte 2: 0x00  (don't care, clocks out low bits)
     *
     * Response: bits 9..0 are in rx[1] (low 2 bits) and rx[2] (8 bits).
     */
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = sizeof(tx);
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    int value = ((rx[1] & 0x03) << 8) | rx[2];
    if (value < 0 || value > 1023) {
        fprintf(stderr, "ADC value out of range: %d\n", value);
        return -1;
    }
    return value;
}

/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, int x, int y, int z)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%d,%d,%d\n", ts, x, y, z);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
static void log_impact(FILE *fp)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,IMPACT DETECTED\n", ts);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open SPI device ---- */
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", SPI_DEVICE, strerror(errno));
        return EXIT_FAILURE;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ADXL335 impact logger started.  Threshold = %.1f\n", IMPACT_THRESHOLD);
    printf("Logging to %s at 100 Hz.  Press Ctrl-C to stop.\n", LOG_FILE);

    /* ---- Main sampling loop ---- */
    while (g_running) {
        int x = mcp3008_read(g_spi_fd, ADC_CHANNEL_X);
        int y = mcp3008_read(g_spi_fd, ADC_CHANNEL_Y);
        int z = mcp3008_read(g_spi_fd, ADC_CHANNEL_Z);

        if (x < 0 || y < 0 || z < 0) {
            fprintf(stderr, "ADC read error — skipping sample\n");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        log_data(g_log_fp, x, y, z);

        if (x > IMPACT_THRESHOLD || y > IMPACT_THRESHOLD || z > IMPACT_THRESHOLD) {
            log_impact(g_log_fp);
        }

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

