/*
 * biometric_logger.c — Raspberry Pi Zero W
 *
 * Reads raw IR and RED ADC samples from a Silicon Labs Si1172-A30-GMR
 * optical heart-rate sensor on I2C bus 1 and logs them to
 * biometric_log.csv with timestamp, proxy-HR, proxy-SpO2, and an
 * error flag (0 = OK, 1 = read error, 2 = sensor absent/uninit).
 *
 * The Si1172 requires a proprietary algorithm to convert raw PPG
 * samples to true heart-rate and SpO2 values.  This program logs
 * the raw 16-bit IR and RED ADC values as proxy values for HR and
 * SpO2, documenting this limitation.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o biometric_logger biometric_logger.c -li2c
 *   (or use pigpio if the I2C driver is unavailable)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- I2C configuration ---- */
#define I2C_BUS        "/dev/i2c-1"
#define SI1172_ADDR    0x51          /* Si1172-A30-GMR default 7-bit address */

/* ---- Si1172 register map (representative subset) ---- */
#define SI1172_REG_HW_KEY      0x00
#define SI1172_REG_MEAS_RATE   0x08
#define SI1172_REG_ALS_IR_DATA 0x22  /* IR photodiode ADC */
#define SI1172_REG_ALS_RED_DATA 0x24  /* RED photodiode ADC  */

/* ---- Application constants ---- */
#define SAMPLE_PERIOD_SEC      1
#define LOG_FILE_NAME          "biometric_log.csv"
#define MAX_RETRIES            3
#define RETRY_DELAY_US         100000  /* 100 ms */

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a single byte to an 8-bit register.                          */
/* ------------------------------------------------------------------ */
static int si1172_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a single byte from an 8-bit register.                          */
/* ------------------------------------------------------------------ */
static int si1172_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    n = read(fd, out, 1);
    if (n != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise the Si1172: write HW_KEY, set measurement rate.          */
/* ------------------------------------------------------------------ */
static int si1172_init(int fd)
{
    /* Write HW_KEY to enable the device and start autonomous measurement. */
    if (si1172_write_reg8(fd, SI1172_REG_HW_KEY, 0x17) != 0)
        return -1;

    /* Set measurement rate to 1 sample per second (0x01). */
    if (si1172_write_reg8(fd, SI1172_REG_MEAS_RATE, 0x01) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read the 16-bit IR and RED ADC values.                               */
/* ------------------------------------------------------------------ */
static int si1172_read_adc(int fd, uint16_t *ir, uint16_t *red)
{
    uint8_t  ir_lo, ir_hi, red_lo, red_hi;

    if (si1172_read_reg8(fd, SI1172_REG_ALS_IR_DATA, &ir_lo) != 0)
        return -1;
    if (si1172_read_reg8(fd, SI1172_REG_ALS_IR_DATA + 1, &ir_hi) != 0)
        return -1;
    *ir = ((uint16_t)ir_hi << 8) | ir_lo;

    if (si1172_read_reg8(fd, SI1172_REG_ALS_RED_DATA, &red_lo) != 0)
        return -1;
    if (si1172_read_reg8(fd, SI1172_REG_ALS_RED_DATA + 1, &red_hi) != 0)
        return -1;
    *red = ((uint16_t)red_hi << 8) | red_lo;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Log one sample row to the CSV file.                                  */
/* ------------------------------------------------------------------ */
static void log_sample(FILE *fp, uint16_t ir, uint16_t red,
                       int hr, int spo2, int err_flag)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return;
    }

    fprintf(fp, "%ld,%d,%d,%d\n", (long)now, hr, spo2, err_flag);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SI1172_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                SI1172_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* ---- Probe: try a zero-length write to detect a present device ---- */
    if (write(g_i2c_fd, NULL, 0) < 0) {
        fprintf(stderr, "Si1172 not responding at 0x%02X: %s\n",
                SI1172_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* ---- Initialise sensor ---- */
    if (si1172_init(g_i2c_fd) != 0) {
        fprintf(stderr, "Si1172 initialisation failed.\n");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* ---- Open log file (append) ---- */
    g_log_fp = fopen(LOG_FILE_NAME, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE_NAME, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "timestamp,hr,b spo2,error_flag\n");
        fflush(g_log_fp);
    }

    printf("Logging Si1172 samples to %s (Ctrl-C to stop)\n", LOG_FILE_NAME);

    /* ---- Main sampling loop ---- */
    while (g_running) {
        uint16_t ir = 0, red = 0;
        int err_flag = 0;

        int ok = 1;
        for (int attempt = 0; attempt < MAX_RETRIES && ok; ++attempt) {
            if (si1172_read_adc(g_i2c_fd, &ir, &red) == 0) {
                ok = 0;
            } else {
                err_flag = 1;
                if (attempt < MAX_RETRIES - 1)
                    usleep(RETRY_DELAY_US);
            }
        }

        if (!ok) {
            /* Sensor absent or bus error — log with error flag 2 */
            err_flag = 2;
        } else {
            /* Proxy HR and SpO2 values (raw ADC counts) */
            int hr = (int)ir;
            int spo2 = (int)red;
        }

        log_sample(g_log_fp, ir, red, hr, spo2, err_flag);
        sleep(SAMPLE_PERIOD_SEC);
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    printf("Done.\n");
    return EXIT_SUCCESS;
}

