/*
 * Raspberry Pi 4 Model B – Honeywell SpiroQuant A+ ES1-005 mass-flow sensor
 * via MCP3008 ADC on SPI0 (CE0 / GPIO8), mode 0, 1 MHz, channel 0.
 *
 * Build:  gcc -O2 -Wall -Wextra -o flow_logger flow_logger.c -lm
 * Run:    ./flow_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL      0          /* SPI0 CE0 (GPIO8)                          */
#define SPI_BAUD         1000000    /* 1 MHz                                    */
#define SPI_FLAGS        0          /* mode 0, active-low CE, 8-bit words        */
#define ADC_CHANNEL      0          /* MCP3008 single-ended channel 0           */
#define ADC_MAX          1023       /* 10-bit ADC full-scale code                */
#define FLOW_MIN         0.0        /* L/min – sensor-absent / fault marker     */
#define FLOW_MAX         5.0        /* L/min – sensor / application limit       */
#define LOG_FILE         "flow_log.csv"
#define SAMPLE_PERIOD_US 1000000    /* 1 second between samples                 */
#define ADC_TIMEOUT_US   1000000    /* 1 s timeout per SPI transfer              */

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static FILE *g_log_file  = NULL;

/* --------------------------- Signal handling ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- MCP3008 read ------------------------------- */
/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
 *   tx[2] = 0x00                       (clock out remaining bits)
 * Result: 10-bit value assembled from rx[1] (low 2 bits) and rx[2] (8 bits).
 */
static int mcp3008_read(int spi_handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int bytes = spiXfer(spi_handle, tx, rx, 3);
    if (bytes != 3) {
        fprintf(stderr, "spiXfer failed: returned %d (pigpio error %d)\n",
                bytes, bytes);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

/* --------------------------- Flow conversion ----------------------------- */
static float adc_to_flow_rate(int adc_value)
{
    if (adc_value < 0)   adc_value = 0;
    if (adc_value > ADC_MAX) adc_value = ADC_MAX;

    /* Linear interpolation: 0 ADC = FLOW_MIN, ADC_MAX = FLOW_MAX */
    return FLOW_MIN + ((float)adc_value / (float)ADC_MAX) * (FLOW_MAX - FLOW_MIN);
}

/* --------------------------- Timestamp ----------------------------------- */
static void get_timestamp(char *buf, size_t len)
{
    struct timespec ts;
    struct tm tm_info;

    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        snprintf(buf, len, "1970-01-01 00:00:00.000000");
        return;
    }

    localtime_r(&ts.tv_sec, &tm_info);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm_info);
    size_t pos = strlen(buf);
    snprintf(buf + pos, len - pos, ".%06ld", ts.tv_nsec / 1000);
}

/* --------------------------- Logging ------------------------------------- */
static int log_flow_rate(FILE *fp, float flow_rate)
{
    char ts[40];
    get_timestamp(ts, sizeof(ts));

    if (fprintf(fp, "%s,%.4f\n", ts, flow_rate) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* --------------------------- Cleanup ------------------------------------- */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

/* --------------------------------- Main ---------------------------------- */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- SPI open --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (pigpio error %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Log file --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Cannot open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,flow_rate_lpm\n");
        fflush(g_log_file);
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Flow logger started. Logging to '%s'. Press Ctrl+C to stop.\n",
           LOG_FILE);

    /* --- Main loop --- */
    while (g_running) {
        int adc_value = mcp3008_read(g_spi_handle, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read failed; retrying in 1 s\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        /* Sensor-absent / fault marker */
        if (adc_value == 0 || adc_value == ADC_MAX) {
            fprintf(stderr, "Warning: ADC at rail (%d) – sensor absent or wiring fault\n",
                    adc_value);
        }

        float flow_rate = adc_to_flow_rate(adc_value);

        if (flow_rate < FLOW_MIN || flow_rate > FLOW_MAX) {
            fprintf(stderr, "Warning: flow rate %.4f L/min out of range [%.1f, %.1f]\n",
                    flow_rate, FLOW_MIN, FLOW_MAX);
        }

        if (log_flow_rate(g_log_file, flow_rate) != 0) {
            fprintf(stderr, "Logging failed; continuing\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

