/*
 * Raspberry Pi Zero W – TDK ICP-10125 I2C pressure/temperature sensor
 *
 * Wiring:
 *   ICP-10125 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   ICP-10125 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   ICP-10125 VDD  -> 3.3 V
 *   ICP-10125 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -o icp10125 icp10125.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define CSV_FILE       "environmental_data.csv"
#define SAMPLE_PERIOD  5          /* seconds between samples */
#define MEAS_DELAY_US  20000      /* 20 ms measurement wait */

/* ICP-10125 commands (high-precision mode) */
#define CMD_MEASURE_HP  0x3608
#define CMD_READ_ID     0x0000

/* Expected device ID (lower 8 bits of the 16-bit response) */
#define ICP10125_ID     0x25

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */

static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int i2c_write_cmd(int fd, uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "write(cmd 0x%04X): %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_n(int fd, uint8_t *dst, size_t n)
{
    ssize_t total = 0;
    while ((size_t)total < n) {
        ssize_t r = read(fd, dst + total, n - total);
        if (r < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "read: %s\n", strerror(errno));
            return -1;
        }
        if (r == 0) {
            fprintf(stderr, "read: unexpected EOF (sensor absent?)\n");
            return -1;
        }
        total += r;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor read                                                         */
/* ------------------------------------------------------------------ */

static int read_sensor(int fd, uint16_t *raw_p, uint16_t *raw_t)
{
    /* Issue high-precision measurement command */
    if (i2c_write_cmd(fd, CMD_MEASURE_HP) < 0)
        return -1;

    /* Wait for conversion to complete */
    usleep(MEAS_DELAY_US);

    /* Read 6 bytes: pressure(2)+crc, temperature(2)+crc */
    uint8_t data[6];
    if (i2c_read_n(fd, data, sizeof(data)) < 0)
        return -1;

    *raw_p = ((uint16_t)data[0] << 8) | data[1];
    *raw_t = ((uint16_t)data[3] << 8) | data[4];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Calibration / conversion                                            */
/* ------------------------------------------------------------------ */

/*
 * ICP-10125 calibration (high-precision mode, 16-bit ADC).
 *   T = raw_t / 100.0  °C
 *   P = raw_p / 100.0  Pa
 */
static float cal_t(uint16_t raw_t)
{
    return (float)raw_t / 100.0f;
}

static float cal_p(uint16_t raw_p)
{
    float t = cal_t((uint16_t)raw_t);
    return (float)raw_p / 100.0f + (t / 100.0f) * 0.0f;
}

/* ------------------------------------------------------------------ */
/* CSV logging                                                         */
/* ------------------------------------------------------------------ */

static int log_csv(FILE *fp, float temp, float pressure)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r: %s\n", strerror(errno));
        return -1;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.2f,%.2f\n", ts, temp, pressure) < 0) {
        fprintf(stderr, "fprintf: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* Signal handling for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    int fd = i2c_open(I2C_BUS, 0x25);
    if (fd < 0)
        return EXIT_FAILURE;

    /* Verify sensor identity */
    uint16_t id = 0;
    if (read_sensor(fd, &id, NULL) < 0) {
        fprintf(stderr, "Sensor not responding at 0x25 – check wiring.\n");
        close(fd);
        return EXIT_FAILURE;
    }
    if (id != ICP10125_ID) {
        fprintf(stderr, "Unexpected device ID 0x%02X (expected 0x%02X).\n",
                id, ICP10125_ID);
        close(fd);
        return EXIT_FAILURE;
    }

    /* Open CSV log file */
    FILE *fp = fopen(CSV_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s): %s\n", CSV_FILE, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(fp) == 0) {
        fprintf(fp, "timestamp,temperature_c,pressure_pa\n");
        fflush(fp);
    }

    printf("ICP-10125 logging started.  Press Ctrl+C to stop.\n");

    while (g_running) {
        uint16_t raw_p = 0, raw_t = 0;

        if (read_sensor(fd, &raw_p, &raw_t) < 0) {
            fprintf(stderr, "Sensor read failed; retrying in %d s.\n",
                    SAMPLE_PERIOD);
            /* Still log the error event */
            if (log_csv(fp, 0.0f, 0.0f) < 0)
                fprintf(stderr, "CSV log failed.\n");
        } else {
            float temp = cal_t(raw_t);
            float pressure = cal_p(raw_p);

            printf("Temperature: %.2f °C  Pressure: %.2f Pa\n",
                   temp, pressure);

            if (log_csv(fp, temp, pressure) < 0)
                fprintf(stderr, "CSV log failed.\n");
        }

        /* Sleep but wake early on signal */
        for (int i = 0; i < SAMPLE_PERIOD && g_running; i++)
            sleep(1);
    }

    /* Cleanup */
    if (fclose(fp) != 0)
        fprintf(stderr, "fclose: %s\n", strerror(errno));
    if (close(fd) < 0)
        fprintf(stderr, "close(fd): %s\n", strerror(errno));

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

