/*
 * Raspberry Pi 3 Model B+ - Dual MP23ABS1 Microphone Noise Cancellation
 * Uses MCP3008 ADC on SPI0 CE0 (GPIO8) to sample two microphones.
 * Applies a basic noise-cancellation algorithm and prints results to stdout.
 *
 * Compile: gcc -o mic_nc mic_nc.c -lm
 * Run:     ./mic_nc <gain1> <gain2>
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED_HZ 1000000
#define NUM_CHANNELS 2
#define SAMPLE_RATE_HZ 44100
#define SAMPLES_PER_BUFFER 1024

#define MCP3008_CHANNEL_MIC1 0
#define MCP3008_CHANNEL_MIC2 1

#define ADC_MAX_VALUE 1023

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    uint8_t mode = SPI_MODE_0;
    uint8_t bits = 8;
    uint32_t speed = SPI_SPEED_HZ;

    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Error setting SPI bits per word");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Error setting SPI max speed");
        close(fd);
        return -1;
    }

    return fd;
}

static int read_mcp3008(int fd, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: 3 bytes.
     * Byte 0: 0x01 (start bit)
     * Byte 1: (0x08 | channel) << 4 (single-ended + channel select)
     * Byte 2: 0x00 (don't care)
     * Result: bits 9..0 are in the lower 2 bits of byte 1 and all of byte 2. */
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("Error during SPI transfer");
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static void apply_noise_cancellation(int *mic1_samples, int *mic2_samples, int num_samples, int gain1, int gain2) {
    for (int i = 0; i < num_samples; i++) {
        double mic1_sample = (double)mic1_samples[i] / (double)gain1;
        double mic2_sample = (double)mic2_samples[i] / (double)gain2;

        double diff = mic1_sample - mic2_sample;
        double noise_canceled = diff * -0.5;

        mic1_samples[i] = (int)(noise_canceled + 0.5);
        mic2_samples[i] = (int)(mic1_sample + noise_canceled);
    }
}

static void print_samples(int *mic1_samples, int *mic2_samples, int num_samples) {
    for (int i = 0; i < num_samples; i++) {
        printf("%d,%d\n", mic1_samples[i], mic2_samples[i]);
    }
    printf("\n");
}

int main(int argc, char *argv[]) {
    int spi_fd = -1;
    int mic1_samples[NUM_CHANNELS * SAMPLES_PER_BUFFER];
    int mic2_samples[NUM_CHANNELS * SAMPLES_PER_BUFFER];
    int num_samples = SAMPLES_PER_BUFFER;

    int gain1 = 1;
    int gain2 = 1;

    if (argc != 3) {
        fprintf(stderr, "Usage: %s <gain1> <gain2>\n", argv[0]);
        return EXIT_FAILURE;
    }

    gain1 = atoi(argv[1]);
    gain2 = atoi(argv[2]);

    if (gain1 <= 0 || gain2 <= 0) {
        fprintf(stderr, "Error: Gain values must be positive integers.\n");
        return EXIT_FAILURE;
    }

    spi_fd = spi_init(SPI_DEVICE);
    if (spi_fd < 0) {
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Error setting up SIGINT handler");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    printf("Sampling audio at %d Hz with gains: Mic1=%d, Mic2=%d\n", SAMPLE_RATE_HZ, gain1, gain2);

    while (running) {
        for (int i = 0; i < num_samples; i++) {
            int mic1_value = read_mcp3008(spi_fd, MCP3008_CHANNEL_MIC1);
            int mic2_value = read_mcp3008(spi_fd, MCP3008_CHANNEL_MIC2);

            if (mic1_value < 0 || mic2_value < 0) {
                fprintf(stderr, "Error reading ADC values. Skipping sample.\n");
                mic1_samples[i] = 0;
                mic2_samples[i] = 0;
                continue;
            }

            mic1_samples[i] = mic1_value;
            mic2_samples[i] = mic2_value;
        }

        apply_noise_cancellation(mic1_samples, mic2_samples, num_samples, gain1, gain2);

        print_samples(mic1_samples, mic2_samples, num_samples);

        usleep(1000000 / SAMPLE_RATE_HZ);
    }

    printf("\nExiting gracefully...\n");

    if (spi_fd >= 0) {
        close(spi_fd);
    }

    return EXIT_SUCCESS;
}

