#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS 8

#define FLAME_SENSOR_CHANNEL 0
#define BUZZER_GPIO 18
#define AMBIENT_TEMP_FILE "ambient_temp.txt"
#define LOG_FILE "flame_log.txt"
#define MAX_RETRIES 3
#define SAMPLE_INTERVAL_MS 500

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_ambient_temperature(void) {
    FILE *fp = fopen(AMBIENT_TEMP_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Warning: cannot open %s: %s\n", AMBIENT_TEMP_FILE, strerror(errno));
        return 25.0f;
    }
    float temp;
    if (fscanf(fp, "%f", &temp) != 1) {
        fprintf(stderr, "Warning: invalid ambient temperature file, using default 25.0 C\n");
        temp = 25.0f;
    }
    fclose(fp);
    return temp;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .pad = 0
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error: SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static float calculate_voltage(int adc_value) {
    return (float)adc_value * 3.3f / 1024.0f;
}

static float calculate_temperature(float voltage) {
    return read_ambient_temperature() - (voltage / 3.3f) * 100.0f;
}

static void log_data(int raw_adc, float voltage, float temp, int flame_detected) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_fp) {
        fprintf(log_fp, "%s,%d,%.3f,%.3f,%s\n", timestamp, raw_adc, voltage, temp, flame_detected ? "YES" : "NO");
        fflush(log_fp);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error: cannot open %s: %s\n", SPI_DEVICE, strerror(errno));
        gpioTerminate();
        return 1;
    }

    unsigned char mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error: SPI_IOC_WR_MODE failed: %s\n", strerror(errno));
        goto cleanup;
    }

    unsigned char bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error: SPI_IOC_WR_BITS_PER_WORD failed: %s\n", strerror(errno));
        goto cleanup;
    }

    unsigned int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error: SPI_IOC_WR_MAX_SPEED_HZ failed: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpioSetMode(BUZZER_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: cannot set GPIO %d as output\n", BUZZER_GPIO);
        goto cleanup;
    }
    gpioWrite(BUZZER_GPIO, 0);

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Error: cannot open %s: %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int raw_adc = -1;
        for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
            raw_adc = read_mcp3008(FLAME_SENSOR_CHANNEL);
            if (raw_adc >= 0) break;
            usleep(10000);
        }

        if (raw_adc < 0) {
            fprintf(stderr, "Error: failed to read ADC after %d attempts, skipping sample\n", MAX_RETRIES);
            gpioWrite(BUZZER_GPIO, 0);
            continue;
        }

        float voltage = calculate_voltage(raw_adc);
        float temp = calculate_temperature(voltage);
        int flame_detected = (voltage > 2.0f) ? 1 : 0;

        gpioWrite(BUZZER_GPIO, flame_detected ? 1 : 0);

        log_data(raw_adc, voltage, temp, flame_detected);

        printf("Raw ADC: %d, Voltage: %.3f V, Temperature: %.2f C, Flame: %s\n",
               raw_adc, voltage, temp, flame_detected ? "YES" : "NO");

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

cleanup:
    printf("\nShutting down...\n");
    if (log_fp) fclose(log_fp);
    if (spi_fd >= 0) close(spi_fd);
    gpioWrite(BUZZER_GPIO, 0);
    gpioTerminate();
    return 0;
}

