/*
 * Raspberry Pi Zero W – Honeywell AWM7300V airflow sensor via MCP3008 ADC
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V (pin 1)
 *   MCP3008 VREF -> 3.3 V (pin 1)
 *   MCP3008 AGND -> GND  (pin 6)
 *   MCP3008 DGND -> GND  (pin 6)
 *   MCP3008 CLK  -> GPIO11 (SCLK, pin 23)
 *   MCP3008 DOUT -> GPIO9  (MISO, pin 21)
 *   MCP3008 DIN  -> GPIO10 (MOSI, pin 19)
 *   MCP3008 CS   -> GPIO8  (CE0,  pin 24)
 *   MCP3008 CH0  -> AWM7300V analog output
 *
 * Build: gcc -O2 -Wall -o airflow airflow.c -lpigpio -lrt
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0          /* CE0 on GPIO8 */
#define SPI_SPEED      1000000    /* 1 MHz – well within MCP3008 spec */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */
#define ADC_CHANNEL    0          /* MCP3008 single-ended channel 0 */
#define SAMPLE_PERIOD  100000     /* 100 ms in microseconds */
#define LOG_FILE       "airflow_log.csv"

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* MCP3008 single-ended read                                           */
/* Returns 0–1023 on success, -1 on SPI error, -2 on invalid channel */
/* ------------------------------------------------------------------ */
static int mcp3008_read(int handle, int channel)
{
    if (channel < 0 || channel > 7) {
