/* Convert raw ADC count to LPM (linear approximation)                 */
/* ------------------------------------------------------------------ */
static float adc_to_lpm(int adc_value)
{
    /*
     * AWM7300V output is 0–3.3 V; MCP3008 is 0–3.3 V.
     * Assuming a linear mapping: 0 V -> 0 LPM, 3.3 V -> 100 LPM.
     * Scale factor = (100 LPM / 3.3 V) / 1024 counts ≈ 0.0304 LPM/count.
