#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <sys/types.h>
#include <sys/wait.h>

#define DEFAULT_SPI_CHANNEL 0
#define DEFAULT_ADC_CHANNEL 0
#define DEFAULT_MIN_VALUE 500
#define DEFAULT_MAX_VALUE 1000
#define DEFAULT_THRESHOLD 30
#define DEFAULT_LOGGING_INTERVAL 60
#define DEFAULT_RECIPIENT_EMAIL "recipient@example.com"
#define DEFAULT_MSMTP_CONFIG "msmtp.conf"

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;
static int g_adc_channel = DEFAULT_ADC_CHANNEL;
static int g_spi_channel = DEFAULT_SPI_CHANNEL;
static int g_min_value = DEFAULT_MIN_VALUE;
static int g_max_value = DEFAULT_MAX_VALUE;
static int g_threshold = DEFAULT_THRESHOLD;
static int g_logging_interval = DEFAULT_LOGGING_INTERVAL;
static char *g_recipient_email = DEFAULT_RECIPIENT_EMAIL;
static char *g_msmtp_config = DEFAULT_MSMTP_CONFIG;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int spi_init(void) {
    char spi_device[32];
    snprintf(spi_device, sizeof(spi_device), "/dev/spidev%d.%d", g_spi_channel, 0);
    int fd = open(spi_device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", spi_device, strerror(errno));
        return -1;
    }
    unsigned int speed = 500000;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    unsigned char mode = SPI_MODE_0;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    unsigned char bits = 8;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int read_adc(int fd, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }
    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = {0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = 500000,
        .delay_usecs = 0,
        .bits_per_word = 8,
    };
    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error during SPI transfer: %s\n", strerror(errno));
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float calculate_moisture(int adc_value) {
    if (g_max_value <= g_min_value) {
        fprintf(stderr, "Invalid calibration values: min=%d max=%d\n", g_min_value, g_max_value);
        return -1.0f;
    }
    float moisture = (float)(adc_value - g_min_value) / (float)(g_max_value - g_min_value) * 100.0f;
    if (moisture < 0.0f) moisture = 0.0f;
    if (moisture > 100.0f) moisture = 100.0f;
    return moisture;
}

static void log_data(float moisture) {
    FILE *fp = fopen("plant_data.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening plant_data.txt: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, %.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, moisture);
    fclose(fp);
}

static void send_email_alert(float moisture) {
    char command[512];
    snprintf(command, sizeof(command),
             "echo \"Subject: Plant Moisture Alert\n\nPlant moisture level is below threshold.\nMoisture: %.2f%%\" | msmtp -t %s -f %s",
             moisture, g_recipient_email, g_msmtp_config);
    int status = system(command);
    if (status == -1) {
        fprintf(stderr, "Error executing msmtp: %s\n", strerror(errno));
    } else if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        fprintf(stderr, "msmtp exited with status %d\n", WEXITSTATUS(status));
    }
}

static void cleanup(void) {
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "c:p:m:v:t:i:e:c:h")) != -1) {
        switch (opt) {
            case 'c': g_adc_channel = atoi(optarg); break;
            case 'p': g_spi_channel = atoi(optarg); break;
            case 'm': g_min_value = atoi(optarg); break;
            case 'v': g_max_value = atoi(optarg); break;
            case 't': g_threshold = atoi(optarg); break;
            case 'i': g_logging_interval = atoi(optarg); break;
            case 'e': g_recipient_email = optarg; break;
            case 'c': g_msmtp_config = optarg; break;
            case 'h':
            default:
                fprintf(stderr, "Usage: %s [-c adc_channel] [-p spi_channel] [-m min_value] [-v max_value] [-t threshold] [-i interval] [-e recipient_email] [-c msmtp_config]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }
    if (g_max_value <= g_min_value) {
        fprintf(stderr, "Invalid calibration values: min=%d max=%d\n", g_min_value, g_max_value);
        return EXIT_FAILURE;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting up signal handlers: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    g_spi_fd = spi_init();
    if (g_spi_fd < 0) {
        return EXIT_FAILURE;
    }
    printf("Plant monitoring started. Logging every %d seconds. Press Ctrl+C to exit.\n", g_logging_interval);
    while (g_running) {
        int adc_value = read_adc(g_spi_fd, g_adc_channel);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value, retrying in %d seconds...\n", g_logging_interval);
            sleep(g_logging_interval);
            continue;
        }
        float moisture = calculate_moisture(adc_value);
        if (moisture < 0.0f) {
            fprintf(stderr, "Error calculating moisture, retrying in %d seconds...\n", g_logging_interval);
            sleep(g_logging_interval);
            continue;
        }
        if (moisture < g_threshold) {
            send_email_alert(moisture);
        }
        log_data(moisture);
        sleep(g_logging_interval);
    }
    cleanup();
    printf("Plant monitoring stopped.\n");
    return EXIT_SUCCESS;
}

