    if (fp == NULL) {
        fprintf(stderr, "Error opening plant_data.txt: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, %.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, moisture);
    fclose(fp);
}

static void send_email_alert(float moisture) {
    char command[512];
    snprintf(command, sizeof(command),
             "echo \"Subject: Plant Moisture Alert\n\nPlant moisture level is below threshold.\nMoisture: %.2f%%\" | msmtp -t %s -f %s",
             moisture, g_recipient_email, g_msmtp_config);
    int status = system(command);
    if (status == -1) {
        fprintf(stderr, "Error executing msmtp: %s\n", strerror(errno));
    } else if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        fprintf(stderr, "msmtp exited with status %d\n", WEXITSTATUS(status));
    }
}

static void cleanup(void) {
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "c:p:m:v:t:i:e:c:h")) != -1) {
        switch (opt) {
            case 'c': g_adc_channel = atoi(optarg); break;
            case 'p': g_spi_channel = atoi(optarg); break;
            case 'm': g_min_value = atoi(optarg); break;
            case 'v': g_max_value = atoi(optarg); break;
            case 't': g_threshold = atoi(optarg); break;
            case 'i': g_logging_interval = atoi(optarg); break;
            case 'e': g_recipient_email = optarg; break;
            case 'c': g_msmtp_config = optarg; break;
            case 'h':
            default:
                fprintf(stderr, "Usage: %s [-c adc_channel] [-p spi_channel] [-m min_value] [-v max_value] [-t threshold] [-i interval] [-e recipient_email] [-c msmtp_config]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }
    if (g_max_value <= g_min_value) {
        fprintf(stderr, "Invalid calibration values: min=%d max=%d\n", g_min_value, g_max_value);
        return EXIT_FAILURE;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting up signal handlers: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    g_spi_fd = spi_init();
    if (g_spi_fd < 0) {
        return EXIT_FAILURE;
    }
    printf("Plant monitoring started. Logging every %d seconds. Press Ctrl+C to exit.\n", g_logging_interval);
    while (g_running) {
        int adc_value = read_adc(g_spi_fd, g_adc_channel);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value, retrying in %d seconds...\n", g_logging_interval);
            sleep(g_logging_interval);
            continue;
        }
        float moisture = calculate_moisture(adc_value);
        if (moisture < 0.0f) {
            fprintf(stderr, "Error calculating moisture, retrying in %d seconds...\n", g_logging_interval);
            sleep(g_logging_interval);
            continue;
        }
        if (moisture < g_threshold) {
            send_email_alert(moisture);
        }
        log_data(moisture);
        sleep(g_logging_interval);
    }
    cleanup();
    printf("Plant monitoring stopped.\n");
    return EXIT_SUCCESS;
}

