    if (argc > 1) {
        sample_interval = atoi(argv[1]);
        if (sample_interval <= 0) {
            fprintf(stderr, "Invalid sample interval. Using default %d seconds.\n",
                    SAMPLE_INTERVAL);
            sample_interval = SAMPLE_INTERVAL;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
