        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error registering SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (spi_init() < 0) {
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n",
                LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Soil Moisture Monitoring Started. Press Ctrl+C to exit.\n");
    printf("Sampling every %d seconds. Press Ctrl+C to change interval.\n",
           sample_interval);

    while (g_running) {
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Warning: Failed to read ADC value. Retrying in %d seconds.\n",
                    sample_interval);
        } else {
            float moisture = calculate_moisture(adc_value);
            if (moisture < 0.0f) {
                fprintf(stderr, "Warning: Invalid moisture calculation. Retrying in %d seconds.\n",
