#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000  /* 1 MHz */
#define SPI_FLAGS 0         /* Mode 0, active-low CE */

#define ADC_CHANNEL 0
#define ADC_MAX 1023
#define VREF 3.3
#define V_MIN 0.0
#define V_MAX 3.3
#define LOG_INTERVAL_SEC 1

static volatile sig_atomic_t g_running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: 3-byte transfer
     *   tx[0] = 0x01  (start bit)
     *   tx[1] = (0x08 | channel) << 4  (single-ended + channel)
     *   tx[2] = 0x00  (don't care)
     * Result: 10-bit value in rx[1] (low 2 bits) and rx[2] (8 bits)
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

static float adc_to_voltage(int adc_value) {
    return ((float)adc_value / (float)ADC_MAX) * VREF;
}

static void log_pressure(float pressure) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    printf("[%s] Pressure: %.3f V\n", timestamp, pressure);
    fflush(stdout);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Pressure monitoring started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (g_running) {
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error; retrying in %d seconds...\n", LOG_INTERVAL_SEC);
            sleep(LOG_INTERVAL_SEC);
            continue;
        }

        float voltage = adc_to_voltage(adc_value);

        /* Sensor-absent / out-of-range detection */
        if (voltage == V_MIN || voltage == V_MAX) {
            fprintf(stderr, "Warning: sensor voltage at rail (%.3f V) - possible sensor absent or wiring fault\n", voltage);
        }

        log_pressure(voltage);

        sleep(LOG_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

