    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI max speed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    *fd_out = fd;
    return 0;
}

static int read_mcp3008(int fd, uint8_t channel, uint16_t *value)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid ADC channel %u\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: start bit, SGL/DIFF=1 + D2 D1 D0, then don't-care */
    uint8_t tx[3] = {
        0x01,
        (uint8_t)(0x80 | (channel << 4)),
        0x00
    };
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf        = (unsigned long)tx,
        .rx_buf        = (unsigned long)rx,
        .len           = 3,
        .speed_hz      = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs   = 0,
        .cs_change     = 0,
        .tx_nbits      = 0,
        .rx_nbits      = 0,
        .pad           = 0
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    /* 10-bit result: low 2 bits of rx[1] << 8 | rx[2] */
    *value = (uint16_t)(((rx[1] & 0x03) << 8) | rx[2]);
    return 0;
}

static float calculate_moisture_percentage(uint16_t adc_value)
{
    if (adc_value > 1023) adc_value = 1023;
    float percentage = (float)adc_value / 1023.0f * 100.0f;
    if (percentage < 0.0f) percentage = 0.0f;
    if (percentage > 100.0f) percentage = 100.0f;
    return percentage;
}

