#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define SPI_BUS          0
#define SPI_CHANNEL      0
#define SPI_SPEED_HZ     1000000
#define SPI_MODE         0
#define SPI_BITS         8

#define MCP3008_CHANNEL  0
#define PUMP_GPIO        17
#define MOISTURE_LOW     300
#define MOISTURE_HIGH    600
#define BUFFER_SIZE      20
#define SAMPLE_INTERVAL  5
#define SPI_TIMEOUT_MS   1000

#define LOG_FILE         "moisture_log.txt"

typedef struct {
    time_t timestamp;
    int    moisture_level;
    bool   pump_on;
} LogEntry;

static LogEntry log_buffer[BUFFER_SIZE];
static int    buffer_index = 0;
static int    buffer_count = 0;

static volatile sig_atomic_t running = 1;
static int    spi_fd = -1;
static bool   pigpio_initialized = false;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_message(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    } else {
        fprintf(fp, "[timestamp error] %s\n", message);
    }
    fclose(fp);
}

static int spi_transfer(int fd, uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf        = (unsigned long)tx,
        .rx_buf        = (unsigned long)rx,
        .len           = len,
        .speed_hz      = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs   = 0,
        .cs_change     = 0,
        .tx_nbits      = 0,
        .rx_nbits      = 0,
        .pad           = 0
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        log_message("SPI transfer failed");
        return -1;
    }
    return 0;
}

static int read_mcp3008(int fd, int channel) {
    if (channel < 0 || channel > 7) {
        log_message("Invalid MCP3008 channel");
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    if (spi_transfer(fd, tx, rx, sizeof(tx)) < 0) {
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static void control_pump(int moisture_level) {
    static bool pump_on = false;

    if (moisture_level < MOISTURE_LOW && !pump_on) {
        if (gpioWrite(PUMP_GPIO, 1) == 0) {
            pump_on = true;
            log_message("Pump ON");
        } else {
            log_message("Failed to turn pump ON");
        }
    } else if (moisture_level > MOISTURE_HIGH && pump_on) {
        if (gpioWrite(PUMP_GPIO, 0) == 0) {
            pump_on = false;
            log_message("Pump OFF");
        } else {
            log_message("Failed to turn pump OFF");
        }
    }
}

static void update_log_buffer(int moisture_level) {
