#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x57
#define SAMPLE_INTERVAL_SEC 1
#define LOG_FILE "health_log.txt"
#define SPO2_THRESHOLD 95
#define HEART_RATE_THRESHOLD 100
#define MAX_RETRIES 3

/* MAX30102 register addresses */
#define REG_PART_ID 0x00
#define REG_REV_ID 0x01
#define REG_SEQ_ID 0x02
#define REG_INT_CFG 0x03
#define REG_INT_STATUS 0x04
#define REG_FIFO_WR_PTR 0x05
#define REG_OVF_COUNTER 0x06
#define REG_FIFO_RD_PTR 0x07
#define REG_FIFO_DATA 0x08
#define REG_MODE_CONFIG 0x09
#define REG_SPO2_CONFIG 0x0A
#define REG_LED1_PA 0x0C
#define REG_LED2_PA 0x0D
#define REG_LED3_PA 0x0E
#define REG_LED4_PA 0x0F
#define REG_LED5_PA 0x10
#define REG_LED6_PA 0x11
#define REG_LED7_PA 0x12
#define REG_LED8_PA 0x13
#define REG_LED9_PA 0x14
#define REG_LED10_PA 0x15
#define REG_LED11_PA 0x16
#define REG_LED12_PA 0x17
#define REG_LED13_PA 0x18
#define REG_LED14_PA 0x19
#define REG_LED15_PA 0x1A
#define REG_LED16_PA 0x1B
#define REG_LED17_PA 0x1C
#define REG_LED18_PA 0x1D
#define REG_LED19_PA 0x1E
#define REG_LED20_PA 0x1F
#define REG_FIFO_CONFIG 0x20
#define REG_FIFO_MODE 0x21
#define REG_FIFO_CIRC 0x22
#define REG_FIFO_EN 0x23
#define REG_FIFO_STATUS 0x24
#define REG_SPO2_DATA 0x7B
#define REG_HR_DATA 0x7D

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_error(const char *msg) {
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp) {
        fprintf(fp, "%s: %s\n", ts, msg);
        fclose(fp);
    }
    fprintf(stderr, "%s: %s\n", ts, msg);
}

static int i2c_write_reg(uint8_t reg, uint8_t val) {
    char buf[2] = {(char)reg, (char)val};
    int rc = i2cWriteDevice(i2c_handle, buf, 2);
    if (rc < 0) {
        log_error("I2C write failed");
        return -1;
    }
    return 0;
}

static int i2c_read_reg(uint8_t reg, uint8_t *val) {
    char reg_buf[1] = {(char)reg};
    int rc = i2cWriteDevice(i2c_handle, reg_buf, 1);
    if (rc < 0) {
        log_error("I2C write (reg select) failed");
        return -1;
    }
    char data_buf[1];
    rc = i2cReadDevice(i2c_handle, data_buf, 1);
    if (rc < 0) {
        log_error("I2C read failed");
        return -1;
    }
    *val = (uint8_t)data_buf[0];
    return 0;
}

static int init_max30102(void) {
    uint8_t part_id = 0;
    if (i2c_read_reg(REG_PART_ID, &part_id) != 0) {
        log_error("Cannot read Part ID - sensor absent or bus error");
        return -1;
    }
    if (part_id != 0x15) {
        fprintf(stderr, "Unexpected Part ID: 0x%02X (expected 0x15)\n", part_id);
        log_error("Unexpected Part ID");
        return -1;
    }
    printf("MAX30102 detected (Part ID 0x%02X)\n", part_id);

    if (i2c_write_reg(REG_MODE_CONFIG, 0x40) != 0) return -1;
    if (i2c_write_reg(REG_FIFO_MODE, 0x00) != 0) return -1;
    if (i2c_write_reg(REG_FIFO_CIRC, 0x07) != 0) return -1;
    if (i2c_write_reg(REG_FIFO_EN, 0x00) != 0) return -1;
    if (i2c_write_reg(REG_FIFO_CONFIG, 0x0F) != 0) return -1;
    if (i2c_write_reg(REG_OVF_COUNTER, 0x00) != 0) return -1;
    if (i2c_write_reg(REG_INT_CFG, 0x00) != 0) return -1;
    if (i2c_write_reg(REG_INT_STATUS, 0x00) != 0) return -1;
    if (i2c_write_reg(REG_MODE_CONFIG, 0x01) != 0) return -1;
    if (i2c_write_reg(REG_FIFO_MODE, 0x01) != 0) return -1;
    if (i2c_write_reg(REG_SPO2_CONFIG, 0x27) != 0) return -1;
    if (i2c_write_reg(REG_LED1_PA, 0x24) != 0) return -1;
    if (i2c_write_reg(REG_LED2_PA, 0x24) != 0) return -1;
    if (i2c_write_reg(REG_LED3_PA, 0x24) != 0) return -1;
    if (i2c_write_reg(REG_LED4_PA, 0x24) != 0) return -1;
    if (i2c_write_reg(REG_LED5_PA, 0x24) != 0) return -1;
    if (i2c_write_reg(REG_LED6_PA, 0x24) != 0) return -1;
    if (i2c_write_reg(REG_LED7_PA, 0x24) != 0) return -1;
    if (i2c_write_reg(REG_LED8_PA, 0x24) != 0) return -1;
    if (i2c_write_reg(REG_LED9_PA, 0x24) != 0) return -1;
    if (i2c_write_reg(REG_LED10_PA, 0x24) != 0) return -1;
    if (i2c_write_reg(REG_LED11_PA, 0x24) != 0) return -1;
    if (i2c_write_reg(REG_LED12_PA, 0x24) != 0) return -1;
    if (i2c_write_reg(REG_LED13_PA, 0x24) != 0) return -1;
    if (i2c_write_reg(REG_LED14_PA, 0x24) != 0) return -1;
    if (i2c_write_reg(REG_LED15_PA, 0x24) != 0) return -1;
    if (i2c_write_reg(REG_LED16_PA, 0x24) != 0) return -1;
    if (i2c_write_reg(REG_LED17_PA, 0x24) != 0) return -1;
    if (i2c_write_reg(REG_LED18_PA, 0x24) != 0) return -1;
    if (i2c_write_reg(REG_LED19_PA, 0x24) != 0) return -1;
    if (i2c_write_reg(REG_LED20_PA, 0x24) != 0) return -1;
    if (i2c_write_reg(REG_LED21_PA, 0x24) != 0) return -1;
    if (i2c_write_reg(REG_LED22_PA, 0x24) != 0) return -1;
    if (i2c_write_reg(REG_LED23_PA, 0x24) != 0) return -1;
    if (i2c_write_reg(REG_LED24_PA, 0x24) != 0) return -1;
    if (i2c_write_reg(REG_LED25_PA, 0x24) != 0) return -1;
    if (i2c_write_reg(REG_LED26_PA, 0x24) != 0) return -1;
    if (i2c_write_reg(REG_LED27_PA, 0x24) != 0) return -1;
    if (i2c_write_reg(REG_LED28_PA, 0x24) != 0) return -1;
    if (i2c_write_reg(REG_LED29_PA, 0x24) != 0) return -1;
    if (i2c_write_reg(REG_LED30_PA, 0x24) != 0) return -1;
    if (i2c_write_reg(REG_LED31_PA, 0x24) != 0) return -1;
    if (i2c_write_reg(REG_MODE_CONFIG, 0x02) != 0) return -1;
    if (i2c_write_reg(REG_FIFO_EN, 0x01) != 0) return -1;
    return 0;
}

static int read_spo2_hr(uint16_t *spo2, uint16_t *hr) {
    uint8_t status = 0;
    if (i2c_read_reg(REG_INT_STATUS, &status) != 0) return -1;
    if ((status & 0x03) != 0x03) {
        log_error("Data not ready");
        return -1;
    }
    uint8_t data[6];
    if (i2cReadDevice(i2c_handle, (char *)data, 6) != 6) {
        log_error("I2C read failed");
        return -1;
    }
    *spo2 = (data[1] << 8) | data[0];
    *hr = (data[3] << 8) | data[2];
    return 0;
}

static void log_event(uint16_t spo2, uint16_t hr) {
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp) {
        fprintf(fp, "%s: SpO2=%u, HR=%u\n", ts, spo2, hr);
        fclose(fp);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %d\n", I2C_BUS, I2C_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_max30102() != 0) {
        fprintf(stderr, "MAX30102 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Monitoring SpO2 and HR. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t spo2 = 0, hr = 0;
        int retries = 0;
        int ok = 0;

        while (retries < MAX_RETRIES && running) {
            if (read_spo2_hr(&spo2, &hr) == 0) {
                ok = 1;
                break;
            }
            retries++;
            if (retries < MAX_RETRIES) {
                gpioDelay(100000);
            }
        }

        if (ok) {
            printf("SpO2: %u%%, HR: %u BPM\n", spo2, hr);
            if (spo2 < SPO2_THRESHOLD) {
                log_event(spo2, hr);
            }
            if (hr > HEART_RATE_THRESHOLD) {
                log_event(spo2, hr);
            }
        } else {
            log_error("Failed to read sensor data after retries");
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

