/*
 * door_monitor.c — Raspberry Pi 5 (Bookworm, 64-bit kernel 6.6+)
 *
 * Monitors a GP2Y0A21YK0F Sharp IR distance sensor via an ADS1115 ADC
 * on /dev/i2c-1, energizes a 5 V relay on GPIO17 for 3 s when the
 * calibrated distance threshold is breached, and logs door-open events
 * to /var/log/door_events.log.
 *
 * Wiring:
 *   ADS1115 SDA -> GPIO2 (BCM), SCL -> GPIO3 (BCM), ADDR -> GND (0x48)
 *   ADS1115 A0  -> GP2Y0A21YK0F analog output
 *   Relay IN   -> GPIO17 (BCM), 5 V -> relay VCC, GND -> Pi GND
 *   Reed sensor (active-low) -> GPIO27 (BCM), 3.3 V -> reed VCC, GND -> Pi GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o door_monitor door_monitor.c
 * Run:    sudo ./door_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define ADS1115_ADDR   0x48

#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG     0x01

/* Config: single-shot, AIN0 single-ended, PGA 4.096 V, 128 SPS, no comp */
#define ADS1115_CFG_BASE 0x8000  /* OS bit: start conversion */
#define ADS1115_CFG_MUX  0x4000  /* AIN0 single-ended */
#define ADS1115_CFG_PGA  0x0200  /* PGA 4.096 V */
#define ADS1115_CFG_DR   0x0080  /* 128 SPS */
#define ADS1115_CFG_CQUE 0x0003  /* Disable comparator */

#define RELAY_GPIO 17
#define REED_GPIO  27
#define REED_ACTIVE_LOW 0

#define LOG_FILE "/var/log/door_events.log"
#define SAMPLE_INTERVAL_US 200000   /* 200 ms */
#define RELAY_PULSE_US      3000000  /* 3 s */
#define CALIBRATION_SAMPLES 10
#define CALIBRATION_DELAY_US 50000  /* 50 ms */

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a 16-bit value to an ADS1115 register. */
static int ads1115_write_reg(int fd, uint8_t reg, uint16_t val)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)((val >> 8) & 0xFF);
    buf[2] = (uint8_t)(val & 0xFF);
    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "ads1115_write_reg(0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a 16-bit value from an ADS1115 register. */
static int ads1115_read_reg(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "ads1115_read_reg write(0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "ads1115_read_reg read(0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    *out = (uint16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

/* Read a 16-bit big-endian sample from the ADS1115. */
static int ads1115_read_sample(int fd, int16_t *sample)
{
    uint16_t raw;
    if (ads1115_read_reg(fd, ADS1115_REG_CONVERSION, &raw) < 0)
        return -1;
    *sample = (int16_t)raw;
    return 0;
}

/* Read the calibrated distance threshold. */
static int read_threshold(int fd, int *threshold)
{
    int samples[CALIBRATION_SAMPLES];
    for (int i = 0; i < CALIBRATION_SAMPLES; i++) {
        if (ads1115_read_sample(fd, &samples[i]) < 0) {
            fprintf(stderr, "Failed to read sample %d\n", i);
            return -1;
        }
        usleep(CALIBRATION_DELAY_US);
    }
    /* Average the samples (signed 16-bit). */
    int sum = 0;
    for (int i = 0; i < CALIBRATION_SAMPLES; i++)
        sum += samples[i];
    *threshold = sum / CALIBRATION_SAMPLES;
    return 0;
}

/* Energize the relay for RELAY_PULSE_US microseconds, then de-energize. */
static void relay_pulse(int relay_fd)
{
    if (write(relay_fd, "1", 1) != 1) {
        fprintf(stderr, "relay_pulse: write HIGH: %s\n", strerror(errno));
        return;
    }
    usleep(RELAY_PULSE_US);
    if (write(relay_fd, "0", 1) != 1) {
        fprintf(stderr, "relay_pulse: write LOW: %s\n", strerror(errno));
    }
}

/* Log an event with millisecond timestamp. */
static void log_event(const char *event)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "log_event: cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char tmbuf[32];
    strftime(tmbuf, sizeof(tmbuf), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(fp, "%s.%03ld: %s\n", tmbuf, ts.tv_nsec / 1000000, event);
    fclose(fp);
}

int main(void)
{
    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Set slave address */
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n", ADS1115_ADDR, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    /* Verify ADS1115 is present by reading the config register */
    uint16_t cfg;
    if (ads1115_read_reg(i2c_fd, ADS1115_REG_CONFIG, &cfg) < 0) {
        fprintf(stderr, "ADS1115 not responding at 0x%02X\n", ADS1115_ADDR);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    /* Configure relay GPIO */
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d): %s\n", RELAY_GPIO, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    if (gpioSetMode(REED_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d): %s\n", REED_GPIO, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(REED_GPIO, REED_ACTIVE_LOW ? PI_PUD_DOWN : PI_PUD_UP) < 0) {
        fprintf(stderr, "gpioSetPullUpDown(%d): %s\n", REED_GPIO, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    if (gpioWrite(RELAY_GPIO, 0) < 0) {
        fprintf(stderr, "gpioWrite(%d, 0): %s\n", RELAY_GPIO, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    /* Open log file */
    FILE *log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        gpioWrite(RELAY_GPIO, 0);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    printf("Door monitor started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int16_t sample;
        if (ads1115_read_sample(i2c_fd, &sample) < 0) {
            fprintf(stderr, "ADC read failed; continuing.\n");
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        int threshold;
        if (read_threshold(i2c_fd, &threshold) < 0) {
            fprintf(stderr, "Threshold read failed; continuing.\n");
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        if (sample < threshold) {
            printf("Distance below threshold (%d) — triggering relay.\n", threshold);
            log_event("distance_below_threshold");
            relay_pulse(RELAY_GPIO);
            int reed = gpioRead(REED_GPIO);
            if (reed < 0) {
                fprintf(stderr, "gpioRead(%d): %s\n", REED_GPIO, strerror(errno));
            } else {
                log_event(reed ? "door_not_opened" : "door_opened");
            }
        }

        usleep(SAMPLE_INTERVAL_US);
    }

    /* Cleanup */
    gpioWrite(RELAY_GPIO, 0);
    fclose(log_fp);
    close(i2c_fd);
    printf("Door monitor stopped.\n");
    return EXIT_SUCCESS;
}

