#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <linux/gpio.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_MODE        SPI_MODE_0
#define SPI_BITS        8

#define CS0_PIN         8
#define CS1_PIN         7
#define CS2_PIN         25
#define CS0_OFFSET      0
#define CS1_OFFSET      1
#define CS2_OFFSET      2

#define NUM_SENSORS      3
#define READ_INTERVAL_S  5

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int setup_signals(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int spi_open(void)
{
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "ioctl(SPI_IOC_WR_MODE): %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "ioctl(SPI_IOC_WR_BITS_PER_WORD): %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "ioctl(SPI_IOC_WR_MAX_SPEED_HZ): %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

static int gpio_export(int pin)
{
    int fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "open(/sys/class/gpio/export): %s\n", strerror(errno));
        return -1;
    }
    char buf[32];
    int len = snprintf(buf, sizeof(buf), "%d", pin);
    if (write(fd, buf, len) != len) {
        fprintf(stderr, "write(/sys/class/gpio/export): %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_unexport(int pin)
{
    int fd = open("/sys/class/gpio/unexport", O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "open(/sys/class/gpio/unexport): %s\n", strerror(errno));
        return -1;
    }
    char buf[32];
    int len = snprintf(buf, sizeof(buf), "%d", pin);
    if (write(fd, buf, len) != len) {
        fprintf(stderr, "write(/sys/class/gpio/unexport): %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_set_direction(int pin, const char *dir)
{
    int fd = open("/sys/class/gpio/gpio" STRINGSIZE(pin) "/direction", O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", "/sys/class/gpio/gpio" STRINGSIZE(pin) "/direction", strerror(errno));
        return -1;
    }
    int len = snprintf(buf, sizeof(buf), "%s", dir);
    if (write(fd, buf, len) != len) {
        fprintf(stderr, "write(%s): %s\n", "/sys/class/gpio/gpio" STRINGSIZE(pin) "/direction", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_set_value(int pin, int val)
{
    int fd = open("/sys/class/gpio/gpio" STRINGSIZE(pin) "/value", O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", "/sys/class/gpio/gpio" STRINGSIZE(pin) "/value", strerror(errno));
        return -1;
    }
    int len = snprintf(buf, sizeof(buf), "%d", val);
    if (write(fd, buf, len) != len) {
        fprintf(stderr, "write(%s): %s\n", "/sys/class/gpio/gpio" STRINGSIZE(pin) "/value", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int spi_transfer(int fd, uint8_t *tx, uint8_t *rx, size_t len)
{
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = len;
    tr.speed_hz = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs = 0;
    tr.cs_change = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "ioctl(SPI_IOC_MESSAGE): %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_adc(int fd, int cs_pin, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    if (gpio_set_value(cs_pin, 0) < 0) {
        return -1;
    }

    if (spi_transfer(fd, tx, rx, 3) < 0) {
        gpio_set_value(cs_pin, 1);
        return -1;
    }

    if (gpio_set_value(cs_pin, 1) < 0) {
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static int log_data(FILE *fp, int s1, int s2, int s3)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return -1;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, s1, s2, s3) < 0) {
        fprintf(stderr, "fprintf: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    int spi_fd = -1;
    FILE *fp = NULL;
    int ret = EXIT_FAILURE;

    if (setup_signals() < 0) {
        goto cleanup;
    }

    spi_fd = spi_open();
    if (spi_fd < 0) {
        goto cleanup;
    }

    int cs_pins[NUM_SENSORS] = { CS0_PIN, CS1_PIN, CS2_PIN };
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (gpio_export(cs_pins[i]) < 0) {
            goto cleanup;
        }
        if (gpio_set_direction(cs_pins[i], "out") < 0) {
            goto cleanup;
        }
        if (gpio_set_value(cs_pins[i], 1) < 0) {
            goto cleanup;
        }
    }

    fp = fopen("soil_moisture_log.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "fopen(soil_moisture_log.csv): %s\n", strerror(errno));
        goto cleanup;
    }

    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        if (fprintf(fp, "timestamp,sensor1,sensor2,sensor3\n") < 0) {
            fprintf(stderr, "fprintf(header): %s\n", strerror(errno));
            goto cleanup;
        }
        if (fflush(fp) != 0) {
            fprintf(stderr, "fflush(header): %s\n", strerror(errno));
            goto cleanup;
        }
    }

    printf("Soil Moisture Logging Started. Press Ctrl+C to stop.\n");

    while (g_running) {
        int s1 = -1, s2 = -1, s3 = -1;
        int read_ok = 1;

        for (int i = 0; i < NUM_SENSORS; i++) {
            s1 = read_adc(spi_fd, cs_pins[i], 0);
            s2 = read_adc(spi_fd, cs_pins[i], 1);
            s3 = read_adc(spi_fd, cs_pins[i], 2);
            if (s1 < 0 || s2 < 0 || s3 < 0) {
                read_ok = 0;
                break;
            }
        }

        if (log_data(fp, s1, s2, s3) < 0) {
            fprintf(stderr, "Failed to log data.\n");
        }

        if (g_running) {
            sleep(READ_INTERVAL_S);
        }
    }

    printf("\nShutting down gracefully...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (fp != NULL) {
        if (fclose(fp) != 0) {
            fprintf(stderr, "fclose: %s\n", strerror(errno));
        }
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    for (int i = 0; i < NUM_SENSORS; i++) {
        gpio_set_value(cs_pins[i], 1);
        gpio_unexport(cs_pins[i]);
    }
    return ret;
}

