#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_MODE        0
#define SPI_BITS        8

#define PUMP_GPIO       18
#define DEFAULT_PUMP_DUR 10
#define DEFAULT_SLEEP_S  60
#define DEFAULT_MOISTURE_THRESH 30.0f
#define MAX_SPI_RETRIES 3

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;
static int g_pump_gpio = PUMP_GPIO;
static float g_moisture_threshold = DEFAULT_MOISTURE_THRESH;
static int g_pump_duration = DEFAULT_PUMP_DUR;
static int g_sleep_interval = DEFAULT_SLEEP_S;

static void log_message(const char *msg) {
    FILE *fp = fopen("irrigation.log", "a");
    if (!fp) {
        perror("fopen irrigation.log");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    } else {
        fprintf(fp, "[timestamp error] %s\n", msg);
    }
    fclose(fp);
}

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    for (int attempt = 0; attempt < MAX_SPI_RETRIES; attempt++) {
        struct spi_ioc_transfer tr = {
            .tx_buf = (unsigned long)tx,
            .rx_buf = (unsigned long)rx,
            .len = 3,
            .speed_hz = SPI_SPEED_HZ,
            .bits_per_word = SPI_BITS,
            .delay_usecs = 0,
            .cs_change = 0,
            .tx_nbits = 0,
            .rx_nbits = 0,
            .pad = 0
        };

        if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) >= 0) {
            int adc = ((rx[1] & 0x03) << 8) | rx[2];
            return adc;
        }
        log_message("SPI transfer failed, retrying...");
        usleep(10000);
    }

    log_message("SPI transfer failed after all retries.");
    return -1;
}

static void control_pump(int on) {
    if (gpioWrite(g_pump_gpio, on ? 1 : 0) < 0) {
        log_message("Failed to write pump GPIO");
    } else {
        char msg[128];
        snprintf(msg, sizeof(msg), "Pump %s", on ? "activated" : "deactivated");
        log_message(msg);
    }
}

static void cleanup(void) {
    if (g_pump_gpio >= 0) {
        gpioWrite(g_pump_gpio, 0);
        gpioSetMode(g_pump_gpio, PI_INPUT);
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "t:d:s:")) != -1) {
        switch (opt) {
            case 't':
                g_moisture_threshold = (float)atof(optarg);
                if (g_moisture_threshold < 0.0f || g_moisture_threshold > 100.0f) {
                    fprintf(stderr, "Threshold must be between 0 and 100\n");
                    return EXIT_FAILURE;
                }
