}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write_byte: write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int fd, uint8_t reg, uint8_t *out)
{
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "i2c_read_byte: write reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    n = read(fd, out, 1);
    if (n != 1) {
        fprintf(stderr, "i2c_read_byte: read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    int fd = -1;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, PCF8591_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                PCF8591_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Put the PCF8591 into single-shot mode so that each read returns the
       current conversion result rather than the previous conversion's
       latched data. */
    if (i2c_write_byte(fd, PCF8591_CONFIG, 0x00) < 0) {
        goto cleanup;
    }

    while (g_running) {
        /* Dummy read to discard the latched result of the previous
           conversion so the next read gives the freshly converted AIN0. */
        uint8_t dummy;
        if (i2c_read_byte(fd, PCF8591_AIN0, &dummy) < 0) {
            goto cleanup;
        }

        uint8_t sample;
        if (i2c_read_byte(fd, PCF8591_AIN0, &sample) < 0) {
            goto cleanup;
        }

        printf("AIN0: %u\n", (unsigned)sample);
        fflush(stdout);

        usleep(SAMPLE_DELAY_US);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return rc;
}

