#define SPI_SPEED      1000000
#define SPI_FLAGS      0
#define ADC_CHANNEL    0
#define PUMP_GPIO      18
#define MOISTURE_THRESHOLD 300
#define WATERING_DURATION 10
#define LOG_FILE       "watering_events.txt"
#define SAMPLE_INTERVAL 60
#define ADC_MAX_VALUE  1023
#define ADC_MIN_VALUE  0
#define INVALID_ADC_VALUE -1

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static int pump_state = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d (must be 0-7)\n", channel);
        return INVALID_ADC_VALUE;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return INVALID_ADC_VALUE;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int control_pump(int state) {
    if (gpioWrite(PUMP_GPIO, state) != 0) {
        fprintf(stderr, "Error: Failed to write GPIO %d\n", PUMP_GPIO);
        return -1;
    }
    pump_state = state;
    return 0;
}

static void log_event(int moisture_level) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d - Moisture Level: %d\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, moisture_level);
    } else {
        fprintf(fp, "Timestamp error - Moisture Level: %d\n", moisture_level);
    }

    fclose(fp);
}

static void cleanup(void) {
    if (pump_state) {
        control_pump(0);
        pump_state = 0;
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error: sigaction failed");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", PUMP_GPIO);
        gpioTerminate();
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    printf("Soil Moisture Monitoring and Watering System started.\n");
    printf("ADC channel: %d, Pump GPIO: %d, Threshold: %d\n",
           ADC_CHANNEL, PUMP_GPIO, MOISTURE_THRESHOLD);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        int moisture_level = read_adc(ADC_CHANNEL);

        if (moisture_level == INVALID_ADC_VALUE) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        if (moisture_level < MOISTURE_THRESHOLD) {
            printf("Moisture level: %d - below threshold %d, watering...\n",
                   moisture_level, MOISTURE_THRESHOLD);

            if (control_pump(1) == 0) {
                log_event(moisture_level);

                for (int i = 0; i < WATERING_DURATION && running; i++) {
                    sleep(1);
                }

                if (control_pump(0) == 0) {
                    printf("Pump deactivated.\n");
                } else {
                    fprintf(stderr, "Error: Failed to deactivate pump\n");
                }
            } else {
                fprintf(stderr, "Error: Failed to activate pump\n");
            }
        } else {
            printf("Moisture level: %d - above threshold %d\n", moisture_level, MOISTURE_THRESHOLD);
        }

        for (int i = 0; i < SAMPLE_INTERVAL && running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

