#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_FLAGS   0        /* mode 0, active-low CE */
#define ADC_CHANNEL 0
#define PWM_PIN     18
#define PWM_FREQ    1000     /* 1 kHz */
#define PWM_RANGE   1023
#define SAMPLE_US   100000   /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a single-ended channel from the MCP3008.
 * Returns 0 on success and stores the 10-bit result in *out;
 * returns -1 on SPI transfer failure.
 */
static int mcp3008_read(int spi_handle, int channel, uint16_t *out)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 SPI protocol (3 bytes):
     *   Byte 0: 0x01  (start bit)
     *   Byte 1: (0x08 | channel) << 4  (single-ended + channel, upper nibble)
     *   Byte 2: 0x00  (don't care, clocks out low 2 bits)
     *
     * Response:
     *   rx[0] = don't care
     *   rx[1] = [null bit][b9 b8] in the lower two bits
     *   rx[2] = b7..b0
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (spiXfer returned %d)\n", ret);
        return -1;
    }

    *out = ((uint16_t)(rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return 0;
}

int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install signal handlers\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Configure PWM on GPIO18 --- */
    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN, PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO%d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO%d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure PWM is off before entering the main loop */
    gpioPWM(PWM_PIN, 0);

    /* --- Open SPI0 CE0 at 1 MHz, mode 0 --- */
    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel %d (pigpio error %d)\n",
                SPI_CHANNEL, spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Main loop --- */
    while (g_running) {
        uint16_t adc_value = 0;

        if (mcp3008_read(spi_handle, ADC_CHANNEL, &adc_value) != 0) {
            fprintf(stderr, "ADC read failed; continuing\n");
            gpioDelay(SAMPLE_US);
            continue;
        }

        int pwm_value = (int)adc_value;  /* map 0..1023 to 0..1023 */

        if (gpioPWM(PWM_PIN, pwm_value) != 0) {
            fprintf(stderr, "Failed to set PWM on GPIO%d\n", PWM_PIN);
            break;
        }

        printf("ADC: %u, PWM: %d\n", adc_value, pwm_value);
        fflush(stdout);

        gpioDelay(SAMPLE_US);
    }

    /* --- Clean shutdown --- */
    gpioPWM(PWM_PIN, 0);
    spiClose(spi_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

