#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <getopt.h>
#include <math.h>
#include <pigpio.h>

#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define LED_PIN 17
#define SAMPLE_INTERVAL_US 100000
#define BLINK_DURATION_US 1000000
#define PGA_GAIN 4.096
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int threshold = 100.0;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int16_t read_ads1115_single_ended(int handle, uint8_t channel) {
    if (channel > 3) return -1;

    uint8_t config[3];
    config[0] = 0x01; // Start conversion
    config[1] = 0x80 | (channel << 4); // Single-ended, AIN0..AIN3
    config[2] = 0x83; // 128 SPS, traditional comparator

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2cWriteDevice(handle, (char *)config, 3) != 0) {
            fprintf(stderr, "Error: I2C write failed (attempt %d)\n", attempt + 1);
            usleep(10000);
            continue;
        }

        usleep(10000);

        uint8_t reg = 0x00;
        if (i2cWriteDevice(handle, (char *)&reg, 1) != 0) {
            fprintf(stderr, "Error: I2C write failed (attempt %d)\n", attempt + 1);
            continue;
        }

        uint8_t data[2];
        if (i2cReadDevice(handle, (char *)data, 2) != 2) {
            fprintf(stderr, "Error: I2C read failed (attempt %d)\n", attempt + 1);
            continue;
        }

        return (int16_t)((data[0] << 8) | data[1]);
    }

    return -1;
}

static double calculate_gauss(int16_t adc_value) {
    double voltage = (adc_value / 32767.0) * PGA_GAIN;
    double gauss = (voltage / 0.1) - 0.0;
    return gauss;
}

static void blink_led(int pin, double threshold) {
    printf("Threshold exceeded! Blinking LED.\n");
    for (int i = 0; i < 20 && running; i++) {
        gpioWrite(pin, 1);
        usleep(50000);
        gpioWrite(pin, 0);
        usleep(50000);
    }
}

int main(int argc, char *argv[]) {
    int opt;

    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold_gauss]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at 0x%02X\n", ADS1115_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Monitoring magnetic field on AIN0 (ADS1115, I2C 0x%02X). Threshold: %.2f Gauss\n", ADS1115_ADDR, threshold);

    while (running) {
        int16_t adc_value = read_ads1115_single_ended(i2c_handle, 0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            break;
        }

        double gauss = calculate_gauss(adc_value);
        printf("Magnetic Field: %.2f Gauss\n", gauss);

        if (gauss > threshold) {
            blink_led(LED_PIN, threshold);
        }

        usleep(SAMPLE_INTERVAL_US);
    }

    gpioWrite(LED_PIN, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

