#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <syslog.h>
#include <errno.h>
#include <stdbool.h>
#include <stdint.h>
#include <pthread.h>
#include <math.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <mosquitto.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS 8

#define PUMP_GPIO 17
#define MOISTURE_THRESHOLD_LOW 30.0f
#define MOISTURE_THRESHOLD_HIGH 35.0f
#define SAMPLE_INTERVAL_SEC 60
#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC_MOISTURE "soil_moisture"
#define MQTT_TOPIC_PUMP "pump_control"

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static struct mosquitto *mosq = NULL;
static pthread_mutex_t mosq_mutex = PTHREAD_MUTEX_INITIALIZER;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        syslog(LOG_ERR, "Failed to open SPI device %s: %s", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        syslog(LOG_ERR, "Failed to set SPI mode: %s", strerror(errno));
        close(spi_fd); spi_fd = -1; return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        syslog(LOG_ERR, "Failed to set SPI bits per word: %s", strerror(errno));
        close(spi_fd); spi_fd = -1; return -1;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        syslog(LOG_ERR, "Failed to set SPI speed: %s", strerror(errno));
        close(spi_fd); spi_fd = -1; return -1;
    }

    syslog(LOG_INFO, "SPI initialized: %s, mode %d, %d bits, %d Hz", SPI_DEVICE, mode, bits, speed);
    return 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        syslog(LOG_ERR, "Invalid MCP3008 channel: %d", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        syslog(LOG_ERR, "SPI transfer failed: %s", strerror(errno));
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float adc_to_moisture(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        syslog(LOG_ERR, "ADC value out of range: %d", adc_value);
        return -1.0f;
    }
    return (float)adc_value / 1023.0f * 100.0f;
}

static int control_pump(float moisture) {
    int target = (moisture < MOISTURE_THRESHOLD_LOW) ? 1 : 0;
    if (target != mosquitto_lib.last_delivery.qos) {
        mosquitto_lib.last_delivery.qos = target;
    }

    if (mosquitto_lib.last_delivery.payloadlen > 0) {
        char payload[32];
        snprintf(payload, sizeof(payload), "%d", target);
        mosquitto_lib.last_delivery.payload = payload;
    }

    if (mosquitto_publish(mosq, NULL, MQTT_TOPIC_PUMP, mosquitto_lib.last_delivery.payloadlen,
                          (int)mosquitto_lib.last_delivery.payloadlen,
                          mosquitto_lib.last_delivery.qos, target, NULL) != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to publish pump control: %s", mosquitto_strerror(mosquitto_lib.last_delivery.result));
        return -1;
    }
    syslog(LOG_INFO, "Pump %s", target ? "ON" : "OFF");
    return 0;
}

static void mqtt_message_callback(struct mosquitto *m, void *userdata, const struct mosquitto_message *message) {
    (void)m; (void)userdata;
    if (message->payloadlen > 0) {
        char payload[32];
        int len = message->payloadlen < (int)sizeof(payload) - 1 ? message->payloadlen : (int)sizeof(payload) - 1;
        memcpy(payload, message->payload, len);
        payload[len] = '\0';
        syslog(LOG_INFO, "Received MQTT message: %s", payload);
        if (strcmp(payload, "pump_on") == 0) {
            if (control_pump(0.0f) != 0) {
                syslog(LOG_ERR, "Failed to turn pump ON");
            }
        } else if (strcmp(payload, "pump_off") == 0) {
            if (control_pump(1.0f) != 0) {
                syslog(LOG_ERR, "Failed to turn pump OFF");
            }
        }
    }
}

static void mqtt_connect_callback(struct mosquitto *m, void *userdata, int result) {
    (void)m; (void)userdata;
    if (result == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "Connected to MQTT broker %s:%d", MQTT_BROKER, MQTT_PORT);
        if (mosquitto_subscribe(m, NULL, MQTT_TOPIC_MOISTURE, 0) != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "Failed to subscribe to moisture topic: %s", mosquitto_strerror(mosquitto_lib.last_result.result));
        }
        if (mosquitto_subscribe(m, NULL, MQTT_TOPIC_PUMP, 0) != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "Failed to subscribe to pump control topic: %s", mosquitto_strerror(mosquitto_lib.last_result.result));
        }
        mosquitto_connect_callback_set(m, NULL, mqtt_message_callback);
    } else {
        syslog(LOG_ERR, "MQTT connect failed: %s", mosquitto_strerror(result));
    }
}

static void mqtt_disconnect_callback(struct mosquitto *m, void *userdata, int rc) {
    (void)m; (void)userdata;
    syslog(LOG_INFO, "MQTT disconnected: %s", mosquitto_strerror(rc));
}

static void *mqtt_thread(void *arg) {
    (void)arg;
    mosquitto_lib.last_delivery.qos = 0;
    mosquitto_lib.last_delivery.payloadlen = 0;
    mosquitto_lib.last_delivery.payload = NULL;

    if (mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60) != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT connect failed: %s", mosquitto_strerror(mosquitto_lib.last_result.result));
        return NULL;
    }

    if (mosquitto_on_connect(m, mqtt_connect_callback) != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to set MQTT on_connect callback");
        return NULL;
    }

    if (mosquitto_on_disconnect(m, mqtt_disconnect_callback) != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to set MQTT on_disconnect callback");
        return NULL;
    }

    if (mosquitto_loop_start(m) != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to start MQTT loop");
        return NULL;
    }

    while (running) {
        sleep(1);
    }

    mosquitto_loop_stop(m, false);
    mosquitto_disconnect(m);
    mosquitto_destroy(m);
    mosq = NULL;
    return NULL;
}

static void cleanup(void) {
    if (mosq) {
        mosquitto_loop_stop(mosq, false);
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosq = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    pthread_mutex_destroy(&mosq_mutex);
    mosquitto_lib.last_delivery.qos = 0;
    mosquitto_lib.last_delivery.payloadlen = 0;
    mosquitto_lib.last_delivery.payload = NULL;
    syslog(LOG_INFO, "Cleanup complete");
}

int main(void) {
    openlog("soil_moisture", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting soil moisture monitoring");

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to set signal handlers: %s", strerror(errno));
        closelog();
        return 1;
    }

    if (spi_init() != 0) {
        closelog();
        return 1;
    }

    if (mosquitto_lib_init(&mosq_lib) != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to initialize mosquitto library");
        close(spi_fd); spi_fd = -1;
        closelog();
        return 1;
    }

    mosquitto_lib.last_delivery.qos = 0;
    mosquitto_lib.last_delivery.payloadlen = 0;
    mosquitto_lib.last_delivery.payload = NULL;

    mosq = mosquitto_new(NULL, true, &mosq_lib);
    if (!mosq) {
        syslog(LOG_ERR, "Failed to create mosquitto instance: %s", mosquitto_strerror(mosquitto_lib.last_result.result));
        mosquitto_lib_cleanup(&mosq_lib);
        close(spi_fd); spi_fd = -1;
        closelog();
        return 1;
    }

    if (pthread_create(&mqtt_thread_id, NULL, mqtt_thread, NULL) != 0) {
        syslog(LOG_ERR, "Failed to create MQTT thread: %s", strerror(errno));
        mosquitto_destroy(mosq);
        mosq = NULL;
        mosquitto_lib_cleanup(&mosq_lib);
        close(spi_fd); spi_fd = -1;
        closelog();
        return 1;
    }

    while (running) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            syslog(LOG_ERR, "Failed to read ADC value");
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        float moisture = adc_to_moisture(adc_value);
