#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define SPI_CHANNEL    0
#define SPI_BAUD       1000000
#define SPI_FLAGS      0
#define VREF           3.3
#define NUM_CHANNELS   3
#define CSV_FILENAME   "sensor_data.csv"
#define SAMPLE_PERIOD  5

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int initialize_pigpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

static int initialize_spi(void)
{
    int handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (handle < 0) {
        fprintf(stderr, "SPI open failed (channel %d, baud %d): pigpio error %d\n",
                SPI_CHANNEL, SPI_BAUD, handle);
        return -1;
    }
    return handle;
}

static int read_mcp3008_channel(int spi_handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: 3-byte transfer.
     * Byte 0: 0x01  (start bit)
     * Byte 1: (0x08 | channel) << 4  (single-ended + channel select)
     * Byte 2: 0x00  (don't care, clocks out low 2 bits)
     * Result: bits 9..0 are in rx[1] (low 2 bits) and rx[2] (8 bits).
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed on channel %d: returned %d\n",
                channel, ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

static double convert_to_voltage(int adc_value)
{
    return ((double)adc_value / 1023.0) * VREF;
}

