/*
 * Vibration-monitor node for Raspberry Pi 3 Model B+
 *
 * Hardware:
 *   - MAX9814 electret microphone amplifier -> MCP3008 channel 0
 *   - MCP3008 SPI0 CE0  -> /dev/spidev0.0
 *   - Vibration motor 1 -> GPIO17 (BCM) via NPN transistor
 *   - Vibration motor 2 -> GPIO27 (BCM) via NPN transistor
 *   - Motors driven at 3 V, PWM frequency 100 Hz
 *
 * Build:  gcc -O2 -Wall -o vib_monitor vib_monitor.c -lm
 * Run:    ./vib_monitor   (requires r/w access to /dev/spidev0.0 and /tmp/vibration_log.txt)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE        "/dev/spidev0.0"
#define SPI_SPEED_HZ      1000000U   /* 1 MHz */
#define SPI_BITS_PER_WORD 8U
#define SPI_MODE          0

#define VIBRATION_MOTOR_1_PIN 17
#define VIBRATION_MOTOR_2_PIN 27

#define NOISE_THRESHOLD     500
#define PWM_FREQUENCY       100
#define PWM_RANGE           100
#define SAMPLE_INTERVAL_US  10000U   /* 10 ms */
#define LOG_FILE            "vibration_log.txt"
#define MAX_RETRIES         3

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* SPI helpers                                                          */
/* ------------------------------------------------------------------ */
static int spi_init(void)
{
    uint8_t mode = SPI_MODE;
    uint8_t bits = SPI_BITS_PER_WORD;
    uint32_t speed = SPI_SPEED_HZ;

    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1;
        return -1;
    }

    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1;
        return -1;
    }

    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI max speed: %s\n", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1;
        return -1;
    }

    return 0;
}

/*
 * MCP3008 single-ended read.
 * Returns 0..1023 on success, -1 on error.
 */
static int mcp3008_read(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 SPI frame (mode 0, MSB-first):
     *   byte 0: 0x01                       (start bit)
     *   byte 1: (0x08 | channel) << 4      (single-ended + channel)
     *   byte 2: 0x00                       (don't care, clocks out low bits)
     *
     * Response:
     *   byte 0: undefined
     *   byte 1: bits 9..2 of ADC result in lower nibble
     *   byte 2: bits 1..0 of ADC result in upper nibble
     */
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = sizeof(tx);
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS_PER_WORD;
    tr.delay_usecs   = 0;

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Motor control (hardware PWM via software loop)                      */
/* ------------------------------------------------------------------ */
static void motor_set_pin(int pin, int duty_percent)
{
    if (duty_percent < 0)   duty_percent = 0;
    if (duty_percent > 100) duty_percent = 100;

    int on_time_us = (PWM_RANGE * duty_percent) / 100;
    int off_time_us = (PWM_RANGE * 100) / 100 - on_time_us;

    if (on_time_us > 0) {
        if (gpioWrite(pin, 1) < 0) {
            fprintf(stderr, "gpioWrite(pin=%d, 1) failed: %s\n", pin, strerror(errno));
        }
        usleep(on_time_us);
    }
    if (off_time_us > 0) {
        if (gpioWrite(pin, 0) < 0) {
            fprintf(stderr, "gpioWrite(pin=%d, 0) failed: %s\n", pin, strerror(errno));
        }
        usleep(off_time_us);
    }
}

static void motor_on(int pin)
{
    motor_set_pin(pin, 100);
}

static void motor_off(int pin)
{
    motor_set_pin(pin, 0);
}

/* ------------------------------------------------------------------ */
/* Noise threshold logic                                              */
/* ------------------------------------------------------------------ */
static int noise_level_above_threshold(int noise_level)
{
    return noise_level > NOISE_THRESHOLD;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_event(const char *event)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, event);
    } else {
        fprintf(fp, "[timestamp error] %s\n", event);
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    motor_off(VIBRATION_MOTOR_1_PIN);
    motor_off(VIBRATION_MOTOR_2_PIN);

    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Initialize SPI */
    if (spi_init() < 0) {
        return EXIT_FAILURE;
    }

    /* Configure motor pins as outputs */
    if (gpioSetMode(VIBRATION_MOTOR_1_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT) failed: %s\n",
                VIBRATION_MOTOR_1_PIN, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(VIBRATION_MOTOR_2_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT) failed: %s\n",
                VIBRATION_MOTOR_2_PIN, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Ensure motors are off at start */
    motor_off(VIBRATION_MOTOR_1_PIN);
    motor_off(VIBRATION_MOTOR_2_PIN);

    printf("Vibration monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int noise_level = mcp3008_read(0);

        if (noise_level < 0) {
            fprintf(stderr, "ADC read failed; skipping sample.\n");
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        int above = noise_level_above_threshold(noise_level);

        if (above) {
            motor_on(VIBRATION_MOTOR_1_PIN);
            motor_on(VIBRATION_MOTOR_2_PIN);
            log_event("Vibration detected");
        } else {
            motor_off(VIBRATION_MOTOR_1_PIN);
            motor_off(VIBRATION_MOTOR_2_PIN);
        }

        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

