        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    motor_off(VIBRATION_MOTOR_1_PIN);
    motor_off(VIBRATION_MOTOR_2_PIN);

    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Initialize SPI */
    if (spi_init() < 0) {
        return EXIT_FAILURE;
    }

    /* Configure motor pins as outputs */
    if (gpioSetMode(VIBRATION_MOTOR_1_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT) failed: %s\n",
                VIBRATION_MOTOR_1_PIN, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(VIBRATION_MOTOR_2_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT) failed: %s\n",
                VIBRATION_MOTOR_2_PIN, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Ensure motors are off at start */
    motor_off(VIBRATION_MOTOR_1_PIN);
    motor_off(VIBRATION_MOTOR_2_PIN);

    printf("Vibration monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int noise_level = mcp3008_read(0);

        if (noise_level < 0) {
            fprintf(stderr, "ADC read failed; skipping sample.\n");
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        int above = noise_level_above_threshold(noise_level);

        if (above) {
            motor_on(VIBRATION_MOTOR_1_PIN);
            motor_on(VIBRATION_MOTOR_2_PIN);
            log_event("Vibration detected");
        } else {
            motor_off(VIBRATION_MOTOR_1_PIN);
            motor_off(VIBRATION_MOTOR_2_PIN);
        }

        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

