#define SPI_BUS        "/dev/spidev0.0"
#define CSV_FILE       "tamper_log.csv"
#define SAMPLE_INTERVAL 5
#define BH1750_CONV_MS 180

#define BH1750_ADDR     0x77
#define BH1750_CMD      0x10
#define BH1750_CONV     0x10
#define BH1750_RESET    0x01

#define MCP3008_CHANNEL 0
#define MCP3008_CS_PIN  8

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int spi_fd = -1;
static FILE *log_fp = NULL;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_cmd(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) return -1;
    return 0;
}

static int i2c_read_n(int fd, uint8_t *buf, size_t n) {
    size_t total = 0;
    while (total < n) {
        ssize_t r = read(fd, buf + total, n - total);
        if (r < 0) return -1;
        if (r == 0) return -1;
        total += (size_t)r;
    }
    return 0;
}

static int bh1750_read_lux(int fd, float *lux_out) {
    if (i2c_write_cmd(fd, BH1750_RESET) < 0) return -1;
    usleep(10000);
    if (i2c_write_cmd(fd, BH1750_CONV) < 0) return -1;
    usleep(BH1750_CONV_MS * 1000);

    uint8_t buf[2];
    if (i2c_read_n(fd, buf, 2) < 0) return -1;

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static int read_mcp3008(int fd, int channel, int *out) {
    if (channel < 0 || channel > 7) return -1;

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = 1000000,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) return -1;

    *out = ((rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

static void log_data(FILE *fp, int sound_db, float light_lux, int err_code) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) return;
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%d,%.2f,%d\n", ts, sound_db, light_lux, err_code);
    fflush(fp);
}

int main(void) {
    struct sigaction sa = { .sa_handler = sig_handler };
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
