    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("ioctl I2C_SLAVE"); close(i2c_fd); return 1;
    }

    if (i2c_write_cmd(i2c_fd, BH1750_RESET) < 0) {
        fprintf(stderr, "BH1750 reset failed\n"); close(i2c_fd); return 1;
    }

    spi_fd = open(SPI_BUS, O_RDWR);
    if (spi_fd < 0) { perror("open spi"); close(i2c_fd); return 1; }

    uint8_t mode = SPI_MODE_0, bits = 8, speed = 1000000;
    uint8_t cs = MCP3008_CS_PIN;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_CS_PIN, &cs) < 0) {
        perror("ioctl spi"); close(i2c_fd); close(spi_fd); return 1;
    }

    log_fp = fopen(CSV_FILE, "a");
    if (!log_fp) { perror("fopen csv"); close(i2c_fd); close(spi_fd); return 1; }

    while (running) {
        int sound_db = -1, err_code = 0;
        float light_lux = -1.0f;

        if (read_mcp3008(spi_fd, MCP3008_CHANNEL, &sound_db) < 0) {
            fprintf(stderr, "ADC read failed\n");
            err_code = 1;
        } else {
            printf("Sound: %d dB\n", sound_db);
        }

        if (bh1750_read_lux(i2c_fd, &light_lux) < 0) {
            fprintf(stderr, "BH1750 read failed\n");
            err_code = 2;
        } else {
            printf("Light: %.2f lux\n", light_lux);
        }

        log_data(log_fp, sound_db, light_lux, err_code);
        sleep(SAMPLE_INTERVAL);
    }

    if (log_fp) fclose(log_fp);
    if (spi_fd >= 0) close(spi_fd);
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

