     * Result: rx[1] low 2 bits + rx[2] form the 10-bit value.
     */
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = 3;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("ioctl(SPI_IOC_MESSAGE)");
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static void log_data(int moisture_level)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    printf("[%s] Moisture Level: %d%%\n", timestamp, moisture_level);
    fflush(stdout);
}

static void control_pump(int moisture_level)
{
    int desired = (moisture_level < MOISTURE_THRESHOLD) ? 1 : 0;
    if (gpioWrite(PUMP_GPIO, desired) < 0) {
        fprintf(stderr, "gpioWrite(%d, %d) failed\n", PUMP_GPIO, desired);
    }
}

static void cleanup(void)
{
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    gpioWrite(PUMP_GPIO, 0);
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise() failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT) failed\n", PUMP_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(PUMP_GPIO, 0);

    if (init_spi() < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Soil Moisture Monitoring System started.\n");
    printf("SPI: %s @ %u Hz | Pump: BCM GPIO %d | Threshold: %d%%\n",
           SPI_DEVICE, SPI_SPEED_HZ, PUMP_GPIO, MOISTURE_THRESHOLD);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        int moisture_level = -1;
        int retries = 0;

        while (retries < MAX_RETRIES && g_running) {
            moisture_level = read_mcp3008(0);
            if (moisture_level >= 0) {
                break;
            }
            retries++;
            if (retries < MAX_RETRIES) {
                fprintf(stderr, "Read attempt %d/%d failed; retrying...\n",
                        retries, MAX_RETRIES);
                sleep(1);
            }
        }

        if (moisture_level < 0) {
            fprintf(stderr, "Failed to read moisture level after %d retries.\n",
                    MAX_RETRIES);
            log_data(-1);
            control_pump(-1);
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        log_data(moisture_level);
        control_pump(moisture_level);

        for (int i = 0; i < SAMPLE_INTERVAL && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

