#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define MCP3008_CHANNEL 0
#define FAN_GPIO 18
#define CO2_THRESHOLD 700.0
#define LOG_FILE "air_quality.log"
#define SAMPLE_INTERVAL 5
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int fd, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .pad = 0
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float adc_to_voltage(int adc_value) {
    return (float)adc_value * 3.3 / 1024.0;
}

static float voltage_to_co2(float voltage) {
    if (voltage <= 0.0) return 0.0;
    return 400.0 * pow(voltage, -1.5);
}

static void log_data(float co2, int fan_state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%d\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, co2, fan_state);
    } else {
        fprintf(fp, "INVALID_TIME,%.2f,%d\n", co2, fan_state);
    }
    fclose(fp);
}

static void control_fan(float co2, int *fan_state) {
    if (co2 > CO2_THRESHOLD && *fan_state == 0) {
        if (gpioWrite(FAN_GPIO, 1) == 0) {
            *fan_state = 1;
            printf("Fan ON (CO2: %.2f ppm)\n", co2);
        } else {
            fprintf(stderr, "Failed to turn fan ON\n");
        }
    } else if (co2 <= CO2_THRESHOLD && *fan_state == 1) {
        if (gpioWrite(FAN_GPIO, 0) == 0) {
            *fan_state = 0;
            printf("Fan OFF (CO2: %.2f ppm)\n", co2);
        } else {
            fprintf(stderr, "Failed to turn fan OFF\n");
        }
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", FAN_GPIO);
        gpioTerminate();
        return 1;
    }
    gpioWrite(FAN_GPIO, 0);

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        gpioTerminate();
        return 1;
    }

    unsigned int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        goto cleanup;
    }

    unsigned char mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        goto cleanup;
    }

    unsigned char bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        goto cleanup;
    }

    int fan_state = 0;
    int consecutive_errors = 0;

    while (running) {
        int adc_value = read_mcp3008(spi_fd, MCP3008_CHANNEL);
        if (adc_value < 0) {
            consecutive_errors++;
            fprintf(stderr, "ADC read error (attempt %d/%d)\n", consecutive_errors, MAX_RETRIES);
            if (consecutive_errors >= MAX_RETRIES) {
                fprintf(stderr, "Max consecutive errors reached, exiting\n");
                break;
            }
            sleep(1);
            continue;
        }
        consecutive_errors = 0;

        if (adc_value < 0 || adc_value > 1023) {
            fprintf(stderr, "ADC value out of range: %d\n", adc_value);
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        float voltage = adc_to_voltage(adc_value);
        float co2 = voltage_to_co2(voltage);

        control_fan(co2, &fan_state);
        log_data(co2, fan_state);

        printf("CO2: %.2f ppm, Fan: %s\n", co2, fan_state ? "ON" : "OFF");

        for (int i = 0; i < SAMPLE_INTERVAL && running; i++) {
            sleep(1);
        }
    }

cleanup:
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    gpioWrite(FAN_GPIO, 0);
    gpioTerminate();
    return 0;
}

