#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_BITS         8
#define SPI_MODE         0

#define ADC_CHANNEL      0
#define ADC_MAX          1023
#define DISTANCE_THRESHOLD_CM 20.0f
#define DEBOUNCE_MS      1000
#define POLL_MS          100
#define LOG_FILE         "door_events.log"

#define RELAY_GPIO       17
#define RELAY_CONSUMER   "door_monitor"

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int spi_init(void)
{
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("open(" SPI_DEVICE ")");
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl(SPI_IOC_WR_MODE)");
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("ioctl(SPI_IOC_WR_BITS_PER_WORD)");
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl(SPI_IOC_WR_MAX_SPEED_HZ)");
        close(fd);
        return -1;
    }

    g_spi_fd = fd;
    return 0;
}

static int read_adc(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = {
        0x01,
        (uint8_t)((0x08 | channel) << 4),
        0x00
    };
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf        = (unsigned long)tx,
        .rx_buf        = (unsigned long)rx,
        .len           = 3,
        .speed_hz      = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs   = 0,
        .cs_change     = 0,
    };

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("ioctl(SPI_IOC_MESSAGE)");
        return -1;
    }

    int value = ((rx[1] & 0x03) << 8) | rx[2];
    return value;
}

static float adc_to_distance_cm(int adc_value)
{
    if (adc_value < 0) return -1.0f;
    return (float)adc_value * 0.1f;
}

static int log_event(const char *event)
{
    if (g_log_fp == NULL) {
        g_log_fp = fopen(LOG_FILE, "a");
        if (g_log_fp == NULL) {
            perror("fopen(" LOG_FILE ")");
            return -1;
        }
    }

    time_t now = time(NULL);
    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        perror("localtime_r");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(g_log_fp, "%s - %s\n", ts, event) < 0) {
        perror("fprintf(log)");
        return -1;
    }

    if (fflush(g_log_fp) != 0) {
        perror("fflush(log)");
        return -1;
    }

    return 0;
}

static int relay_init(void)
{
    if (gpiod_chip_open_by_name("gpiochip0") < 0) {
        perror("gpiod_chip_open_by_name");
        return -1;
    }

    struct gpiod_line *line = gpiod_chip_get_line(gpiod_chip_open_by_name("gpiochip0"), RELAY_GPIO);
    if (line == NULL) {
        perror("gpiod_chip_get_line");
        return -1;
    }

    if (gpiod_line_request_output(line, RELAY_CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output");
        return -1;
    }

    return 0;
}

static void relay_set(int state)
{
    if (gpiod_line_set_value(line, state) < 0) {
        perror("gpiod_line_set_value");
    }
}

static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    if (relay_init() >= 0) {
        gpiod_line_set_value(line, 0);
        gpiod_line_release(line);
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        return EXIT_FAILURE;
    }

    if (relay_init() < 0) {
        fprintf(stderr, "Relay initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Door monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int adc = read_adc(ADC_CHANNEL);
        if (adc < 0) {
            fprintf(stderr, "ADC read error; skipping cycle\n");
            usleep(POLL_MS * 1000);
            continue;
        }

        float distance = adc_to_distance_cm(adc);
        if (distance < 0.0f) {
            fprintf(stderr, "Invalid distance conversion\n");
            usleep(POLL_MS * 1000);
            continue;
        }

        if (distance < DISTANCE_THRESHOLD_CM) {
            printf("Distance: %.2f cm - Door OPENED\n", distance);
            if (log_event("Door opened") < 0) {
                fprintf(stderr, "Logging failed\n");
            }

            relay_set(1);

            for (int elapsed = 0; elapsed < DEBOUNCE_MS * 1000 && g_running; elapsed += 1000) {
                usleep(1000);
            }

            relay_set(0);
        }

        usleep(POLL_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

