    }

    if (spi_init() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(VALVE_GPIO, PI_OUTPUT) < 0) {
        perror("gpioSetMode");
        close(spi_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(VALVE_GPIO, PWM_FREQUENCY) < 0) {
        perror("gpioSetPWMfrequency");
        close(spi_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(VALVE_GPIO, PWM_RANGE) < 0) {
        perror("gpioSetPWMrange");
        close(spi_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

