    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction SIGINT");
        fclose(log_file);
        close(spi_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction SIGTERM");
        fclose(log_file);
        close(spi_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Irrigation system started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc1 = read_mcp3008(0);
        int adc2 = read_mcp3008(1);
        int adc3 = read_mcp3008(2);

        if (adc1 < 0 || adc2 < 0 || adc3 < 0) {
            fprintf(stderr, "Error reading ADC values. Skipping cycle.\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        int avg = (adc1 + adc2 + adc3) / SAMPLES;

        if (set_valve_position(avg) != 0) {
            fprintf(stderr, "Error setting valve position.\n");
        }

        if (log_data(adc1, adc2, adc3, avg, 0) != 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");

    set_valve_position(0);
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

