/*
 * Raspberry Pi Zero W – YL-69 soil moisture sensor via MCP3008 ADC
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V (Pin 1)
 *   MCP3008 VREF -> 3.3 V (Pin 1)
 *   MCP3008 AGND -> GND  (Pin 6)
 *   MCP3008 CLK  -> GPIO11 (SPI0 SCLK, Pin 23)
 *   MCP3008 DOUT -> GPIO9  (SPI0 MISO, Pin 21)
 *   MCP3008 DIN  -> GPIO10 (SPI0 MOSI, Pin 19)
 *   MCP3008 CS   -> GPIO8  (SPI0 CE0,  Pin 24)
 *   MCP3008 DGND -> GND  (Pin 6)
 *   MCP3008 CH0  -> YL-69 analog output
 *
 * Build:  gcc -O2 -Wall -o soil_monitor soil_monitor.c -lpigpio -lrt
 * Run:    sudo ./soil_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL    0          /* SPI0 CE0 (GPIO8)                          */
#define SPI_SPEED      1000000    /* 1 MHz                                    */
#define SPI_FLAGS      0          /* SPI mode 0, active-low CE, 8-bit words   */
#define ADC_CHANNEL    0          /* MCP3008 single-ended channel 0           */
#define LOG_FILE       "soil_data.txt"
#define SAMPLE_PERIOD  5          /* seconds between samples                  */
#define MAX_RETRIES    5          /* consecutive SPI failures before skipping  */
#define ADC_MAX        1023       /* 10-bit ADC full-scale code               */
#define ADC_MIN        0
#define ADC_VREF       3.3        /* MCP3008 VREF (VDD = 3.3 V)               */

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* --------------------------- Signal handling ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- MCP3008 read ------------------------------- */
/*
 * MCP3008 SPI protocol (3-byte transfer, SPI mode 0, MSB-first):
 *   Byte 0: 0x01                       – start bit
 *   Byte 1: (0x08 | channel) << 4     – SGL/DIFF=1 (single-ended) + channel
 *   Byte 2: 0x00                       – dummy (clocks out low 2 bits)
 *
 * Response (3 bytes):
 *   rx[0] = don't care
 *   rx[1] = [null bit][b9 b8] in the low nibble
 *   rx[2] = b7..b0
 *
 * 10-bit result = ((rx[1] & 0x03) << 8) | rx[2]
 */
static int read_mcp3008(int spi_handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int bytes = spiXfer(spi_handle, tx, rx, 3);
    if (bytes != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", bytes);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    if (adc_value < ADC_MIN || adc_value > ADC_MAX) {
        fprintf(stderr, "ADC value out of range: %d\n", adc_value);
        return -1;
    }
    return adc_value;
}

/* --------------------------- Moisture conversion ------------------------- */
static float adc_to_moisture_percent(int adc_value)
{
    if (adc_value < 0) return -1.0f;
    return ((float)adc_value / (float)ADC_MAX) * 100.0f;
}

/* --------------------------- Logging ------------------------------------ */
static void log_data(float moisture_percent, int adc_value)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s, Moisture: %.2f%%, ADC: %d\n", ts, moisture_percent, adc_value);
    } else {
        fprintf(fp, "(time-error), Moisture: %.2f%%, ADC: %d\n", moisture_percent, adc_value);
    }

    fclose(fp);
}

/* --------------------------- Retry logic --------------------------------- */
static int read_with_retry(int spi_handle, int channel, int max_retries)
{
    for (int attempt = 1; attempt <= max_retries; attempt++) {
        int adc = read_mcp3008(spi_handle, channel);
        if (adc >= 0) {
            return adc;
        }
        fprintf(stderr, "SPI read attempt %d/%d failed\n", attempt, max_retries);
        if (attempt < max_retries) {
            gpioDelay(1000000 / (1 << attempt)); /* 1 s, 2 s, 4 s, 8 s */
        }
    }
    return -1;
}

/* --------------------------- Cleanup ------------------------------------- */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

/* --------------------------------- Main ---------------------------------- */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- SPI open --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Soil moisture monitoring started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_PERIOD);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        int adc_value = read_with_retry(g_spi_handle, ADC_CHANNEL, MAX_RETRIES);

        if (adc_value < 0) {
            fprintf(stderr, "SPI communication failed after %d retries; skipping sample.\n",
                    MAX_RETRIES);
            log_data(-1.0f, -1);
        } else {
            float moisture = adc_to_moisture_percent(adc_value);
            log_data(moisture, adc_value);
            printf("Moisture: %.2f%%  ADC: %d\n", moisture, adc_value);
        }

        /* Sleep in 1 s increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD && g_running; i++) {
            gpioDelay(1000000);
        }
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

