#include <linux/pwm.h>

#define CONFIG_FILE      "theremin_config.txt"
#define SPI_DEVICE       "/dev/spidev0.0"
#define PWM_CHIP         0
#define PWM_CHANNEL      0
#define PWM_PERIOD_NS    1000000ULL   /* 1 kHz */
#define PWM_DUTY_MAX     1000000ULL   /* 100 % */

#define TRIG_PIN         23
#define ECHO_PIN         24
#define LDR_ADC_CHANNEL  0

#define SAMPLE_PERIOD_US 10000
#define MAX_ECHO_PULSES  255
#define ECHO_TIMEOUT_US  30000
#define MAX_DISTANCE_MM  400.0
#define MIN_DISTANCE_MM  2.0

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;
static int g_ldr_cal = 0;
static int g_trig_cal = 0;
static double g_min_dist = MAX_DISTANCE_MM;
static double g_max_dist = MIN_DISTANCE_MM;
static double g_last_dist = MAX_DISTANCE_MM;
static double g_last_vol = 0.0;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int spi_init(void)
{
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE_0;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = 8;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = 1000000;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

static int spi_read_adc(int fd, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf        = (unsigned long)tx,
        .rx_buf        = (unsigned long)rx,
        .len           = 3,
        .speed_hz      = 1000000,
        .bits_per_word = 8,
        .delay_usecs   = 0,
        .cs_change     = 0,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE: %s\n", strerror(errno));
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static double read_ultrasonic(int trig_pin, int echo_pin)
{
    if (g_spi_fd < 0) {
        fprintf(stderr, "SPI not initialised\n");
        return -1.0;
    }

    if (g_last_dist < 0.0) {
        g_last_dist = (double)ECHO_TIMEOUT_US / 2.0;
    }

    if (g_last_dist > MAX_DISTANCE_MM) g_last_dist = MAX_DISTANCE_MM;

    if (g_last_dist > 0.0) {
        double d = g_last_dist - (double)ECHO_TIMEOUT_US / 2.0;
        if (d < 0.0) d = 0.0;
        if (d > MAX_DISTANCE_MM) d = MAX_DISTANCE_MM;
        return d;
    }

    if (g_running) {
        fprintf(stderr, "Ultrasonic sensor timeout\n");
    }
    return -1.0;
}

static double read_ldr(int spi_fd)
{
    int val = spi_read_adc(spi_fd, LDR_ADC_CHANNEL);
    if (val < 0) return -1.0;
    return (double)val / 1023.0;
}

static void set_pwm_duty(int duty)
{
    if (duty < 0) duty = 0;
    if (duty > PWM_DUTY_MAX) duty = PWM_DUTY_MAX;

    long long on_ns = (long long)PWM_PERIOD_NS * (long long)duty / PWM_DUTY_MAX;
    long long off_ns = PWM_PERIOD_NS - on_ns;

    struct pwm_export *export = pwm_export_open(PWM_CHIP, PWM_CHANNEL, 0);
    if (!export) {
        fprintf(stderr, "pwm_export_open: %s\n", strerror(errno));
        return;
    }

    struct pwm_config *cfg = pwm_config_new();
    if (!cfg) {
        pwm_export_close(export);
        fprintf(stderr, "pwm_config_new: %s\n", strerror(errno));
        return;
    }

    pwm_config_set_period(cfg, PWM_PERIOD_NS);
    pwm_config_set_duty_cycle(cfg, on_ns);
    pwm_config_set_duty_cycle(cfg, off_ns);

    if (pwm_export_set_config(export, cfg) < 0) {
        fprintf(stderr, "pwm_export_set_config: %s\n", strerror(errno));
        pwm_config_free(cfg);
        pwm_export_close(export);
    }
    pwm_config_free(cfg);

    if (pwm_export_start(export, 0) < 0) {
        fprintf(stderr, "pwm_export_start: %s\n", strerror(errno));
    }

    if (export) pwm_export_close(export);
}

static void stop_pwm(void)
{
    struct pwm_export *export = pwm_export_open(PWM_CHIP, PWM_CHANNEL, 0);
    if (export) {
        pwm_export_set_duty_cycle(export, 0);
        pwm_export_start(export, 0);
        pwm_export_close(export);
    }
}

static void save_config(const char *fn, int trig_cal, int ldr_cal)
{
    FILE *fp = fopen(fn, "w");
    if (!fp) {
        fprintf(stderr, "fopen(%s): %s\n", fn, strerror(errno));
        return;
    }
    fprintf(fp, "trig_cal=%d ldr_cal=%d\n", trig_cal, ldr_cal);
    fclose(fp);
}

static int load_config(const char *fn)
{
    FILE *fp = fopen(fn, "r");
    if (!fp) return -1;
    if (fscanf(fp, "trig_cal=%d ldr_cal=%d", &g_trig_cal, &g_ldr_cal) != 2) {
        fprintf(stderr, "Invalid config file\n");
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return 0;
}

static void map_ultrasonic_to_freq(double dist)
{
    if (dist < 0.0) return;
    double freq = 1000.0 + (dist / 100.0) * 10000.0;
    if (freq < 20.0) freq = 20.0;
    if (freq > 20000.0) freq = 20000.0;
    printf("Ultrasonic: %.2f mm  ->  %d Hz\n", dist, (int)(freq + 0.5));
}

static void map_ldr_to_vol(double vol)
{
    if (vol < 0.0) vol = 0.0;
    if (vol > 1.0) vol = 1.0;
    printf("LDR: %.2f -> Volume: %.2f%%\n", g_ldr_cal, vol * 100.0);
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

int main(void)
{
    struct sigaction sa = { .sa_handler = sig_handler };
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return 1;
    }

    if (load_config(CONFIG_FILE) < 0) {
        g_trig_cal = 0; g_ldr_cal = 0;
        printf("No config file found – using defaults.\n");
    }

    g_spi_fd = spi_init();
    if (g_spi_fd < 0) {
        fprintf(stderr, "SPI init failed. Exiting.\n");
        return 1;
    }

    if (ioctl(TRIG_PIN, PWM_export, PWM_CHIP) < 0) {
        fprintf(stderr, "TRIG_PIN PWM_export: %s\n", strerror(errno));
        goto cleanup;
    }
    if (ioctl(ECHO_PIN, PWM_export, PWM_CHIP) < 0) {
        fprintf(stderr, "ECHO_PIN PWM_export: %s\n", strerror(errno));
        goto cleanup;
    }
    if (ioctl(PWM_CHANNEL, PWM_export, PWM_CHIP) < 0) {
        fprintf(stderr, "PWM_CHANNEL PWM_export: %s\n", strerror(errno));
        goto cleanup;
    }

    if (g_trig_cal == 0) {
        g_trig_cal = 500;
        printf("Calibrating trigger pulse width...\n");
        int attempts = 0;
        while (g_running) {
            int val = g_spi_fd;
            if (val < 0) { fprintf(stderr, "SPI read failed during calibration\n"); goto cleanup; }
            int pw = spi_read_adc(val, LDR_ADC_CHANNEL);
            if (pw < 0) { fprintf(stderr, "SPI read failed during calibration\n"); goto cleanup; }
            double vol = (double)pw / 1023.0;
            if (vol < 0.0) vol = 0.0;
            if (vol > 1.0) vol = 1.0;
            if (vol > g_ldr_cal) g_ldr_cal = vol;
            if (g_ldr_cal < 0.0) g_ldr_cal = 0.0;
            printf("LDR cal: %.2f%%\n", vol * 100.0);
            usleep(100000);
            attempts++;
            if (attempts > 100) break;
        }
        printf("LDR calibration complete.\n");
    }

    if (g_trig_cal == 0) {
        g_trig_cal = 500;
        printf("Calibrating trigger pulse width...\n");
        int attempts = 0;
        while (g_running) {
            int val = g_spi_fd;
            if (val < 0) { fprintf(stderr, "SPI read failed during calibration\n"); goto cleanup; }
            int pw = spi_read_adc(val, LDR_ADC_CHANNEL);
            if (pw < 0) { fprintf(stderr, "SPI read failed during calibration\n"); goto cleanup; }
            double vol = (double)pw / 1023.0;
            if (vol < 0.0) vol = 0.0;
            if (vol > 1.0) vol = 1.0;
            if (vol > g_trig_cal) g_trig_cal = vol;
            if (g_trig_cal < 0.0) g_trig_cal = 0.0;
            printf("Trigger cal: %.2f%%\n", vol * 100.0);
            usleep(100000);
            attempts++;
            if (attempts > 100) break;
        }
        printf("Trigger calibration complete.\n");
    }

    printf("Theremin started. Ctrl+C to exit.\n");

    while (g_running) {
        double dist = read_ultrasonic(TRIG_PIN, ECHO_PIN);
        double vol = read_ldr(g_spi_fd);

        if (dist < 0.0) {
            fprintf(stderr, "Ultrasonic read error – retaining last values.\n");
        } else {
            if (dist < g_last_dist) g_last_dist = dist;
            if (dist > g_max_dist) g_max_dist = dist;
            if (dist < g_min_dist) g_min_dist = dist;
            printf("Ultrasonic: %.2f mm\n", dist);
            map_ultrasonic_to_freq(dist);
        }

        if (vol < 0.0) {
            fprintf(stderr, "LDR read error – retaining last volume.\n");
        } else {
            if (vol < g_last_vol) g_last_vol = vol;
            if (vol > 1.0) vol = 1.0;
            if (vol < 0.0) vol = 0.0;
            map_ldr_to_vol(vol);
        }

        set_pwm_duty((int)vol);
        usleep(SAMPLE_PERIOD_US);
    }

cleanup:
    stop_pwm();
    if (g_spi_fd >= 0) close(g_spi_fd);
    return 0;
}

