#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000
#define SPI_MODE    0
#define SPI_CS      8
#define FAN_GPIO    18
#define AQI_THRESHOLD 100
#define LOG_FILE    "air_quality.log"
#define SAMPLE_INTERVAL 5
#define MAX_RETRIES 3
#define RETRY_DELAY 1

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float calculate_aqi(int adc_value) {
    if (adc_value <= 0) return 0.0f;
    float ratio = (float)adc_value / 1023.0f;
    float co2 = 400.0f * (1.0f - powf(ratio, 0.6f));
    float aqi = (co2 < 50.0f) ? 50.0f : (co2 < 100.0f) ? 100.0f * (1.0f - powf((co2 - 50.0f) / 50.0f, 1.5f)) : 300.0f * (1.0f - powf((co2 - 100.0f) / 50.0f, 1.5f));
    return aqi;
}

static void control_fan(int on) {
    gpioWrite(FAN_GPIO, on ? 1 : 0);
}

static void log_data(float aqi) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, AQI: %.2f\n", timestamp, aqi);
    fflush(log_file);
}

static void cleanup(void) {
    control_fan(0);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set fan GPIO mode\n");
        cleanup();
        return 1;
    }
    control_fan(0);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Air quality monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc_value = -1;
        for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
            adc_value = read_mcp3008(0);
            if (adc_value >= 0) break;
            fprintf(stderr, "SPI read attempt %d/%d failed\n", attempt + 1, MAX_RETRIES);
            if (attempt < MAX_RETRIES - 1) {
                sleep(RETRY_DELAY);
            }
        }

        if (adc_value < 0) {
            fprintf(stderr, "SPI read failed after %d attempts. Re-initializing SPI.\n", MAX_RETRIES);
            spiClose(spi_handle);
            spi_handle = -1;
            sleep(RETRY_DELAY);
            spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
            if (spi_handle < 0) {
                fprintf(stderr, "SPI re-initialization failed: %d\n", spi_handle);
                break;
            }
            continue;
        }

        float aqi = calculate_aqi(adc_value);
        log_data(aqi);
        control_fan(aqi > AQI_THRESHOLD ? 1 : 0);

        for (int i = 0; i < SAMPLE_INTERVAL && !terminate; i++) {
            sleep(1);
        }
    }

    cleanup();
    printf("Air quality monitoring stopped.\n");
    return 0;
}

