#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000
#define SPI_FLAGS   0

#define MOTOR1_ENABLE 18
#define MOTOR2_ENABLE 24
#define MOTOR1_DIR    23
#define MOTOR2_DIR    25

#define PWM_RANGE 255
#define PWM_FREQ 1000

#define SPEED_MIN 0
#define SPEED_MAX 255
#define ACCEL_STEP 5
#define DECEL_STEP 5
#define HOLD_SEC  2
#define PAUSE_SEC 5
#define LOOP_SEC  1

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(SPI_CHANNEL, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int map_reading_to_speed(int reading) {
    if (reading < 0) return SPEED_MIN;
    if (reading > 1023) return SPEED_MAX;
    return (int)((reading / 1023.0) * (SPEED_MAX - SPEED_MIN) + SPEED_MIN);
}

static void set_motor_speed(int enable, int dir, int speed) {
    if (speed < 0) speed = 0;
    if (speed > SPEED_MAX) speed = SPEED_MAX;

    if (speed > 0) {
        gpioPWM(enable, speed);
    } else {
        gpioPWM(enable, 0);
    }

    if (dir > 0) {
        gpioWrite(MOTOR_DIR, 1);
    } else {
        gpioWrite(MOTOR_DIR, 0);
    }
}

static void accelerate(int enable, int dir, int speed) {
    for (int i = 0; i <= SPEED_MAX && g_running; i += ACCEL_STEP) {
        set_motor_speed(enable, dir, i);
        time_sleep(0.01);
    }
}

static void decelerate(int enable, int dir, int speed) {
    for (int i = SPEED_MAX; i >= 0 && g_running; i -= ACCEL_STEP) {
        set_motor_speed(enable, dir, i);
        time_sleep(0.01);
    }
}

static void hold(int enable, int dir, int speed) {
    set_motor_speed(enable, dir, speed);
    time_sleep(HOLD_SEC);
}

static void reverse(int enable, int dir, int speed) {
    set_motor_speed(enable, dir, speed);
    time_sleep(0.1);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MOTOR1_ENABLE, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR2_ENABLE, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR1_DIR, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR2_DIR, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
