#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define LED_GPIO 17
#define SAMPLE_INTERVAL_US 100000
#define DEBOUNCE_MS 10
#define CALIBRATION_TIME_S 5

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int calibrate_noise_level(int *baseline) {
    double sum = 0.0;
    int count = 0;
    time_t start = time(NULL);

    while (running && (time(NULL) - start) < CALIBRATION_TIME_S) {
        int val = read_mcp3008(0);
        if (val < 0) {
            fprintf(stderr, "Error reading ADC during calibration\n");
            return -1;
        }
        sum += val;
        count++;
        usleep(100000);
    }

    if (count == 0) {
        fprintf(stderr, "No samples collected during calibration\n");
        return -1;
    }

    *baseline = (int)(sum / count);
    printf("Calibration complete. Baseline: %d\n", *baseline);
    return 0;
}

static void control_led(int level) {
    static int led_state = 0;
    static struct timeval last_change = {0, 0};
    struct timeval now;

    gettimeofday(&now, NULL);
    long elapsed_ms = (now.tv_sec - last_change.tv_sec) * 1000L +
                      (now.tv_usec - last_change.tv_usec) / 1000L;

    if (level != led_state) {
        if (elapsed_ms > DEBOUNCE_MS) {
            led_state = level;
            gpioWrite(LED_GPIO, level);
            last_change = now;
        }
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_GPIO);
        gpioTerminate();
        return 1;
    }
    gpioWrite(LED_GPIO, 0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    int baseline = 0;
    if (calibrate_noise_level(&baseline) != 0) {
        fprintf(stderr, "Calibration failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    printf("Monitoring sound levels... (Ctrl+C to exit)\n");

    while (running) {
        int val = read_mcp3008(0);
        if (val < 0) {
            fprintf(stderr, "ADC read error\n");
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        int level = val;
        control_led(level);
        printf("Sound Level: %d\n", level);
        usleep(SAMPLE_INTERVAL_US);
    }

    gpioWrite(LED_GPIO, 0);
    spiClose(spi_handle);
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return 0;
}

