#include <time.h>
#include <signal.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <linux/gpio.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define GPIO_CHIP       "/dev/gpiochip0"
#define GPIO_CS         8          /* GPIO 8  = physical pin 24 (BCM 8)  = CE0  */
#define GPIO_MOSI       10         /* GPIO 10 = physical pin 19 (BCM 10) = MOSI */
#define GPIO_MISO       9          /* GPIO 9  = physical pin 21 (BCM 9)  = MISO */
#define GPIO_SCLK       11         /* GPIO 11 = physical pin 23 (BCM 11) = SCLK */
#define ADC_CHANNEL     0
#define ADC_MAX         1023       /* MCP3008 is 10-bit */
#define SAMPLE_RATE_HZ  1000
#define SAMPLE_PERIOD_NS (1000000000L / SAMPLE_RATE_HZ)
#define LOG_FILE        "audio_log.txt"

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int spi_init(void)
{
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE_0;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = 8;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = 1000000U;  /* 1 MHz */
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

static int gpio_init(void)
{
    int fd = open(GPIO_CHIP, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", GPIO_CHIP, strerror(errno));
        return -1;
    }

    struct gpio_config cfg = {
        .consumer      = "audio_adc",
        .request_type  = GPIO_REQUEST_DIRECTION_INPUT,
        .flags         = 0,
    };

    if (ioctl(fd, GPIO_SET_CONFIG, &cfg) < 0) {
        fprintf(stderr, "GPIO_SET_CONFIG (CS): %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    cfg.request_type = GPIO_REQUEST_DIRECTION_OUTPUT;
    if (ioctl(fd, GPIO_SET_CONFIG, &cfg) < 0) {
        fprintf(stderr, "GPIO_SET_CONFIG (CS out): %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    /* Ensure CS is high (inactive) at startup */
    if (ioctl(fd, GPIO_WRITE, &(uint32_t){GPIO_CS, 1}) < 0) {
        fprintf(stderr, "GPIO_WRITE (CS high): %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

static int gpio_set_cs(int fd, int val)
{
    if (val < 0 || val > 1) {
        fprintf(stderr, "gpio_set_cs: invalid value %d\n", val);
        return -1;
    }
    uint32_t val32 = (uint32_t)val;
    if (ioctl(fd, GPIO_WRITE, &val32) < 0) {
        fprintf(stderr, "GPIO_WRITE (CS): %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_adc(int spi_fd, int cs_fd, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "read_adc: invalid channel %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: start bit, config byte, then dummy byte */
    uint8_t tx[3] = {
        0x01,
        (uint8_t)((0x08 | channel) << 4),
        0x00
    };
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf        = (unsigned long)tx,
        .rx_buf        = (unsigned long)rx,
        .len           = 3,
        .speed_hz      = 1000000,
        .bits_per_word = 8,
        .delay_usecs   = 0,
        .cs_change     = 0,
    };

    if (ioctl(cs_fd, GPIO_WRITE, &(uint32_t){GPIO_CS, 0}) < 0) {
        fprintf(stderr, "ADC CS low: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE: %s\n", strerror(errno));
        gpio_set_cs(cs_fd, 1);
        return -1;
    }

    if (ioctl(cs_fd, GPIO_WRITE, &(uint32_t){GPIO_CS, 1}) < 0) {
        fprintf(stderr, "ADC CS high: %s\n", strerror(errno));
        return -1;
    }

    /* 10-bit result: low 2 bits of rx[1] + rx[2] */
    int adc = ((rx[1] & 0x03) << 8) | rx[2];
    return adc;
}

static long long get_timestamp_ns(void)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC_RAW, &ts) < 0) {
        fprintf(stderr, "clock_gettime: %s\n", strerror(errno));
        return 0;
    }
    return (long long)ts.tv_sec * 1000000000LL + ts.tv_nsec;
}

static int log_sample(FILE *fp, long long ts, int adc)
{
    if (fprintf(fp, "%lld|%d\n", ts, adc) < 0) {
        fprintf(stderr, "fprintf: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
