    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int spi_fd = spi_init();
    if (spi_fd < 0) {
        return EXIT_FAILURE;
    }

    int cs_fd = gpio_init();
    if (cs_fd < 0) {
        close(spi_fd);
        return EXIT_FAILURE;
    }

    FILE *fp = fopen(LOG_FILE, "w");
    if (!fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        close(cs_fd);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    printf("Audio logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        int adc = read_adc(spi_fd, cs_fd, ADC_CHANNEL);
        if (adc < 0) {
            fprintf(stderr, "ADC read error\n");
            break;
        }

        long long ts = get_timestamp_ns();
        if (log_sample(fp, ts, adc) < 0) {
            break;
        }

        struct timespec req = {
            .tv_sec  = 0,
            .tv_nsec = SAMPLE_PERIOD_NS,
        };
        struct timespec rem;
        while (nanosleep(&req, &rem) < 0 && errno == EINTR && g_running) {
            req = rem;
        }
    }

    printf("\nShutting down...\n");
    fclose(fp);
    close(cs_fd);
    close(spi_fd);
    return EXIT_SUCCESS;
}

