#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define SENSOR3_PIN 27
#define LOG_FILE "magnetic_log.txt"
#define SAMPLE_INTERVAL_US 100000  /* 100 ms */
#define ADC_MAX 3.3f
#define ADC_MIN 0.0f
#define FIELD_MIN_MT -100.0f
#define FIELD_MAX_MT 100.0f

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static int read_sensor(int gpio_pin)
{
    int level = gpioRead(gpio_pin);
    if (level < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n",
                gpio_pin, strerror(errno));
        return -1;
    }
    return level;
}

static float calculate_magnetic_field(int sensor_pin)
{
    int level = read_sensor(sensor_pin);
    if (level < 0)
        return -1.0f;

    float voltage = (float)level * ADC_MAX / (ADC_MAX - ADC_MIN);
    float field = (voltage - ADC_MIN) / (ADC_MAX - ADC_MIN) * (FIELD_MAX_MT - FIELD_MIN_MT) +
                  FIELD_MIN_MT;
    return field;
}

static int log_data(float f1, float f2, float f3)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[64];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s,%.3f,%.3f,%.3f\n", ts, f1, f2, f3);
    } else {
        fprintf(fp, "timestamp_error,%.3f,%.3f,%.3f\n", f1, f2, f3);
    }

    if (fflush(fp) != 0)
        fprintf(stderr, "Warning: fflush failed: %s\n", strerror(errno));

    fclose(fp);
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed: %s\n", strerror(errno));
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR1_PIN, PI_INPUT) != 0 ||
        gpioSetMode(SENSOR2_PIN, PI_INPUT) != 0 ||
        gpioSetMode(SENSOR3_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Enable internal pull-downs so sensors read LOW when no magnet is present */
    if (gpioSetPullUpDown(SENSOR1_PIN, PI_PUD_DOWN) != 0 ||
        gpioSetPullUpDown(SENSOR2_PIN, PI_PUD_DOWN) != 0 ||
        gpioSetPullUpDown(SENSOR3_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Warning: pull-down setup failed\n");
    }

    while (program_running) {
        float f1 = calculate_magnetic_field(SENSOR1_PIN);
        float f2 = calculate_magnetic_field(SENSOR2_PIN);
        float f3 = calculate_magnetic_field(SENSOR3_PIN);

        if (f1 < 0.0f || f2 < 0.0f || f3 < 0.0f) {
            fprintf(stderr, "Warning: sensor read failure, skipping log\n");
        } else {
            if (f1 < FIELD_MIN_MT || f1 > FIELD_MAX_MT ||
                f2 < FIELD_MIN_MT || f2 > FIELD_MAX_MT ||
                f3 < FIELD_MIN_MT || f3 > FIELD_MAX_MT) {
                fprintf(stderr,
                        "Warning: magnetic field out of range "
                        "(s1=%.3f, s2=%.3f, s3=%.3f) — skipping log\n",
                        f1, f2, f3);
            } else {
                if (log_data(f1, f2, f3) != 0)
                    fprintf(stderr, "Warning: failed to log data\n");
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

