#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PUMP_GPIO          17
#define SPI_CHANNEL        0
#define SPI_SPEED          500000
#define SPI_FLAGS          0
#define MOISTURE_CHANNEL   0
#define MOISTURE_THRESHOLD 30
#define SAMPLE_INTERVAL_S  60
#define LOG_FILE           "watering.log"

static volatile sig_atomic_t g_running = 1;
static int g_pump_state = 0;

static void log_event(const char *msg) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    } else {
        fprintf(fp, "[timestamp error] %s\n", msg);
    }
    fclose(fp);
}

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(SPI_CHANNEL, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "spiXfer failed (ret=%d)\n", ret);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static void control_pump(int on) {
    if (gpioWrite(PUMP_GPIO, on ? 1 : 0) < 0) {
        fprintf(stderr, "gpioWrite(%d, %d) failed\n", PUMP_GPIO, on);
        log_event("ERROR: failed to write pump GPIO");
        return;
    }
    g_pump_state = on ? 1 : 0;
    char msg[64];
    snprintf(msg, sizeof(msg), "Pump %s", on ? "ON" : "OFF");
    log_event(msg);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT) failed\n", PUMP_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(PUMP_GPIO, 0);

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_event("Program started");

    while (g_running) {
        int moisture = read_mcp3008(MOISTURE_CHANNEL);
        if (moisture < 0) {
            log_event("ERROR: ADC read failed");
        } else {
            char msg[64];
            snprintf(msg, sizeof(msg), "Moisture level: %d%%", moisture);
            log_event(msg);

            if (moisture < MOISTURE_THRESHOLD && g_pump_state == 0) {
                control_pump(1);
            } else if (moisture >= MOISTURE_THRESHOLD && g_pump_state == 1) {
                control_pump(0);
            }
        }

        for (int i = 0; i < SAMPLE_INTERVAL_S && g_running; i++) {
            sleep(1);
        }
    }

    log_event("Program terminated");
    gpioWrite(PUMP_GPIO, 0);
    spiClose(spi_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

