#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <stdbool.h>
#include <pigpio.h>

#define MQTT_HOST "mqtt.eclipseprojects.io"
#define MQTT_PORT 1883
#define MQTT_TOPIC "home/led_control"
#define MQTT_CLIENT_ID "rpi_led_control"
#define MQTT_QOS 0
#define LED_GPIO 17
#define MAX_RECONNECT_DELAY 60
#define MAX_RECONNECT_DELAY_SEC 60
#define MAX_RECONNECT_DELAY_MS 0

static volatile sig_atomic_t running = 1;
static int mqtt_client_handle = -1;
static int pigpio_initialized = 0;
static int led_state = 0;

static void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(stderr, "[%s] ERROR: %s (errno: %d - %s)\n",
            timestamp, message, errno, strerror(errno));
}

static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

static void on_connect(void *context, char *client_id, int result) {
    (void)context;
    (void)client_id;
    if (result == 0) {
        printf("Connected to MQTT broker.\n");
        if (mqtt_client_subscribe(mqtt_client_handle, MQTT_TOPIC, MQTT_QOS) != 0) {
            log_error("Failed to subscribe to MQTT topic.");
        } else {
            printf("Subscribed to topic: %s\n", MQTT_TOPIC);
        }
    } else {
        log_error("MQTT connection failed.");
    }
}

static void on_disconnect(void *context, int cause) {
    (void)context;
    (void)cause;
    printf("MQTT connection lost.\n");
}

static void on_message(void *context, char *topic, int topic_len, char *payload, int payload_len) {
    (void)context;
    (void)topic;
    (void)topic_len;

    if (payload_len <= 0) {
        log_error("Empty MQTT payload received.");
        return;
    }

    bool led_state_value = false;
    if (json_parse(payload, payload_len, &led_state_value) != 0) {
        log_error("Failed to parse JSON payload.");
        return;
    }

    if (led_state_value != led_state) {
        if (gpioWrite(LED_GPIO, led_state_value) == 0) {
            led_state = led_state_value;
            printf("LED state changed to: %s\n", led_state_value ? "ON" : "OFF");
        } else {
            log_error("Failed to write to GPIO.");
        }
    }
}

static void on_subscribe(void *context, int mid, int qos_count, const int *granted_qos) {
    (void)context;
    (void)mid;
    (void)qos_count;
    (void)granted_qos;
    printf("Subscribed to topic: %s\n", MQTT_TOPIC);
}

static void cleanup(void) {
    if (mqtt_client_handle >= 0) {
        mqtt_client_disconnect(mqtt_client_handle);
        mqtt_client_handle = -1;
    }
    if (pigpio_initialized) {
        gpioWrite(LED_GPIO, 0);
        gpioTerminate();
        pigpio_initialized = 0;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        log_error("Failed to install signal handlers.");
        return 1;
    }

    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed.");
        return 1;
    }
    pigpio_initialized = 1;

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        log_error("Failed to set GPIO mode.");
        cleanup();
        return 1;
    }
    if (gpioWrite(LED_GPIO, 0) != 0) {
        log_error("Failed to initialize LED state.");
        cleanup();
        return 1;
    }

    mqtt_client_handle = mqtt_connect(MQTT_HOST, MQTT_PORT, MQTT_CLIENT_ID, MQTT_QOS);
    if (mqtt_client_handle < 0) {
        log_error("Failed to connect to MQTT broker.");
        cleanup();
        return 1;
    }

    if (mqtt_set_callback(mqtt_client_handle, on_connect, NULL, on_disconnect, NULL, on_subscribe, on_message) != 0) {
        log_error("Failed to set MQTT callbacks.");
        cleanup();
        return 1;
    }

