#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>

#define GPIO_CHIP_NAME   "/dev/gpiochip0"
#define GPIO_LINE_OFFSET 17
#define LOG_FILE         "/var/log/vibration_shutdown.log"
#define CONSUMER         "vibration-monitor"

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signum)
{
    (void)signum;
    program_running = 0;
}

static int log_event(const char *message)
{
    int fd = open(LOG_FILE, O_WRONLY | O_APPEND | O_CREAT, 0644);
    if (fd < 0) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("Error getting time");
        close(fd);
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        perror("Error converting time");
        close(fd);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        close(fd);
        return -1;
    }

    char log_message[256];
    int n = snprintf(log_message, sizeof(log_message), "%s: %s\n", timestamp, message);
    if (n < 0 || n >= (int)sizeof(log_message)) {
        fprintf(stderr, "Error formatting log message\n");
        close(fd);
        return -1;
    }

    ssize_t written = write(fd, log_message, (size_t)n);
    if (written < 0) {
        perror("Error writing to log file");
        close(fd);
        return -1;
    }

    if (close(fd) < 0) {
        perror("Error closing log file");
        return -1;
    }

    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Error registering SIGINT handler");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Error registering SIGTERM handler");
        return EXIT_FAILURE;
    }

    int gpio_fd = open(GPIO_CHIP_NAME, O_RDWR);
    if (gpio_fd < 0) {
        perror("Error opening GPIO chip");
        return EXIT_FAILURE;
    }

    if (ioctl(gpio_fd, GPIO_GET_LINE consumer, &GPIO_LINE_OFFSET) < 0) {
        perror("Error getting GPIO line");
        close(gpio_fd);
        return EXIT_FAILURE;
    }

    if (ioctl(gpio_fd, GPIO_request_falling_edge_events, CONSUMER) < 0) {
        perror("Error requesting falling edge events on GPIO line");
        close(gpio_fd);
        return EXIT_FAILURE;
    }

    printf("Vibration sensor monitoring started on GPIO%d. Press Ctrl+C to exit.\n", GPIO_LINE_OFFSET);

    while (program_running) {
        struct timespec ts = { .tv_sec = 1, .tv_nsec = 0 };
        int ret = ioctl(gpio_fd, GPIO_EVENT_WAIT, &ts);

        if (ret < 0) {
            if (errno == EINTR) {
                continue;
            }
            perror("Error waiting for GPIO event");
            break;
        }

        if (ret == 0) {
            continue;
        }

        struct gpio_event event;
        if (ioctl(gpio_fd, GPIO_EVENT_READ, &event) < 0) {
            perror("Error reading GPIO event");
            continue;
        }

        if (event.event_type != GPIOTE_VIBRATION) {
            continue;
        }

        printf("Vibration detected! Shutting down...\n");
        if (log_event("Vibration detected! Shutting down.") < 0) {
            fprintf(stderr, "Warning: failed to log event\n");
        }

        if (system("sudo shutdown -h now") == -1) {
            perror("Error executing shutdown command");
        }
        break;
    }

    if (ioctl(gpio_fd, GPIO_LINE_RELEASE, GPIO_LINE_OFFSET) < 0) {
        perror("Error releasing GPIO line");
    }
    close(gpio_fd);

    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

