#define SPI_BUS "/dev/spidev0.0"
#define LOG_FILE "environmental_log.txt"
#define SAMPLE_INTERVAL_SEC 1

/* BH1750 registers */
#define BH1750_ADDR 0x38
#define BH1750_CONTROL 0x10
#define BH1750_DATA 0x00

/* MCP3008 SPI command */
#define MCP3008_START 0x01
#define MCP3008_SINGLE 0x80
#define MCP3008_CHANNEL_0 0x00

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int spi_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_bh1750(int fd, float *lux) {
    uint8_t data[2];
    uint8_t status;

    /* Power on and set to continuous high-resolution mode */
    if (i2c_write_reg8(fd, BH1750_CONTROL, 0x10) < 0) return -1;
    usleep(180000); /* 180 ms power-on delay */

    /* Wait for measurement to complete (max 180 ms) */
    for (int i = 0; i < 20; i++) {
        if (i2c_read_reg8(fd, BH1750_DATA, &status) < 0) return -1;
        if (status & 0x80) break; /* data ready */
        usleep(10000);
    }
    if (!(status & 0x80)) {
        fprintf(stderr, "BH1750 measurement timeout\n");
        return -1;
    }

    /* Read 2-byte big-endian result */
    if (i2c_read_reg8(fd, BH1750_DATA, data) < 0) return -1;

    *lux = (float)((data[0] << 8) | data[1]) / 1.2f;
    return 0;
}

static int read_mcp3008(int fd, int channel, int *adc_value) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = {MCP3008_START, (uint8_t)(MCP3008_SINGLE | (channel << 4)), 0x00};
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = 1000000,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    *adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

static int log_data(float lux, int adc_value) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, Light: %.2f, Sound: %d\n", timestamp, lux, adc_value);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handlers: %s\n", strerror(errno));
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", BH1750_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    spi_fd = open(SPI_BUS, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI bus %s: %s\n", SPI_BUS, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    printf("Environmental monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        float lux = 0.0f;
        int adc_value = 0;

        if (read_bh1750(i2c_fd, &lux) < 0) {
            fprintf(stderr, "BH1750 read failed; skipping sample.\n");
        } else if (read_mcp3008(spi_fd, 0, &adc_value) < 0) {
            fprintf(stderr, "MCP3008 read failed; skipping sample.\n");
        } else {
            if (log_data(lux, adc_value) < 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            } else {
                printf("Light: %.2f lux, Sound: %d\n", lux, adc_value);
            }
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down gracefully...\n");
    if (i2c_fd >= 0) close(i2c_fd);
    if (spi_fd >= 0) close(spi_fd);
    return 0;
}

