#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <linux/i2c-dev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define I2C_DEVICE "/dev/i2c-1"
#define SPI_SPEED_HZ 500000
#define MCP4725_I2C_ADDR 0x60
#define LOG_FILE "temperature_log.txt"
#define SAMPLE_INTERVAL_US 500000

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open SPI device");
        return -1;
    }

    uint8_t mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl SPI_IOC_WR_MODE");
        close(spi_fd); spi_fd = -1;
        return -1;
    }

    uint8_t bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("ioctl SPI_IOC_WR_BITS_PER_WORD");
        close(spi_fd); spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl SPI_IOC_WR_MAX_SPEED_HZ");
        close(spi_fd); spi_fd = -1;
        return -1;
    }

    return 0;
}

static int i2c_init(void) {
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("open I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MCP4725_I2C_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(i2c_fd); i2c_fd = -1;
        return -1;
    }

    return 0;
}

static int spi_transfer(uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("ioctl SPI_IOC_MESSAGE");
        return -1;
    }
    return 0;
}

static int mcp4725_write(uint16_t value) {
    uint8_t buf[3] = {
        (uint8_t)(value >> 8),
        (uint8_t)(value & 0xFF),
        0x00
    };
    if (write(i2c_fd, buf, 3) != 3) {
        perror("write MCP4725");
        return -1;
    }
    return 0;
}

static int read_adc(uint8_t channel) {
    if (channel > 7) {
        fprintf(stderr, "Invalid ADC channel %u\n", channel);
        return -1;
    }

    uint8_t tx[3] = {
        0x01,
        (uint8_t)((0x08 | channel) << 4),
        0x00
    };
    uint8_t rx[3] = {0};

    if (spi_transfer(tx, rx, 3) < 0) {
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static float adc_to_celsius(int adc_value) {
    float voltage = (adc_value / 1023.0f) * 3.3f;
    return (voltage - 0.5f) * 100.0f;
}

static int log_data(FILE *fp, int adc_value, float temp_c, float dac_voltage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        perror("localtime");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s, ADC: %d, Temp: %.2f C, DAC: %.2f V\n", timestamp, adc_value, temp_c, dac_voltage) < 0) {
        perror("fprintf");
        return -1;
    }

    fflush(fp);
    return 0;
}

static void cleanup(void) {
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_fp != NULL) {
        fclose(log_fp);
        log_fp = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (spi_init() < 0) {
        return 1;
    }

    if (i2c_init() < 0) {
        cleanup();
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        perror("fopen log file");
        cleanup();
        return 1;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = read_adc(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC, retrying in 1 second...\n");
            usleep(1000000);
            continue;
        }

        float temp_c = adc_to_celsius(adc_value);
        float dac_voltage = (float)adc_value * 3.3f / 1023.0f;

        if (mcp4725_write((uint16_t)(dac_voltage * 255.0f)) < 0) {
            fprintf(stderr, "Error writing to DAC, retrying in 1 second...\n");
            usleep(1000000);
            continue;
        }

        if (log_data(log_fp, adc_value, temp_c, dac_voltage) < 0) {
            fprintf(stderr, "Error logging data, retrying in 1 second...\n");
            usleep(1000000);
            continue;
        }

        printf("ADC: %d, Temp: %.2f C, DAC: %.2f V\n", adc_value, temp_c, dac_voltage);

        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

