#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MIC_ADC_PIN 26
#define LED_PIN 16
#define DEBOUNCE_MS 50
#define LED_ON_MS 500
#define SAMPLE_PERIOD_US 1000
#define THRESHOLD 200
#define MAX_ADC_VALUE 1023

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(MIC_ADC_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set MIC_ADC_PIN %d as input.\n", MIC_ADC_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set LED_PIN %d as output.\n", LED_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize LED_PIN %d low.\n", LED_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int read_adc(void) {
    int value = gpioRead(MIC_ADC_PIN);
    if (value < 0) {
        fprintf(stderr, "Error: gpioRead failed on MIC_ADC_PIN %d.\n", MIC_ADC_PIN);
        return -1;
    }
    return value;
}

static void control_led(int on) {
    if (gpioWrite(LED_PIN, on ? 1 : 0) != 0) {
        fprintf(stderr, "Warning: gpioWrite failed on LED_PIN %d.\n", LED_PIN);
    }
}

static void log_event(void) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    printf("[%s] Clap detected!\n", timestamp);
    fflush(stdout);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Clap detection started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    int last_clap_ms = -DEBOUNCE_MS;

    while (running) {
        int adc_value = read_adc();
        if (adc_value < 0) {
            gpioDelay(10000);
            continue;
        }

        if (adc_value > THRESHOLD) {
            int now_ms = gpioTick() / 1000;
            if (now_ms - last_clap_ms >= DEBOUNCE_MS) {
                log_event();
                control_led(1);
                gpioDelay(LED_ON_MS * 1000);
                control_led(0);
                last_clap_ms = now_ms;
            }
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    control_led(0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

