#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000
#define ADC_CHANNEL 0
#define LED_PIN     21
#define THRESHOLD   10.0f
#define LOG_FILE    "magnetic_log.txt"
#define SAMPLE_US   100000

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float adc_to_magnetic_field(int adc_value) {
    return (float)adc_value * 0.1f;
}

static int log_data(float magnetic_field) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, %.2f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, magnetic_field);
    } else {
        fprintf(fp, "timestamp_error, %.2f\n", magnetic_field);
    }

    fclose(fp);
    return 0;
}

static void control_led(float magnetic_field) {
    int level = (magnetic_field > THRESHOLD) ? 1 : 0;
    if (gpioWrite(LED_PIN, level) < 0) {
        fprintf(stderr, "gpioWrite failed on pin %d\n", LED_PIN);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed on pin %d\n", LED_PIN);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }
    gpioWrite(LED_PIN, 0);

    printf("Monitoring magnetic field on MCP3008 channel %d... (Ctrl+C to exit)\n", ADC_CHANNEL);

    while (running) {
        int adc = read_mcp3008(ADC_CHANNEL);
        if (adc < 0) {
            fprintf(stderr, "ADC read error\n");
        } else {
            float field = adc_to_magnetic_field(adc);
            if (log_data(field) != 0) {
                fprintf(stderr, "Logging failed\n");
            }
            control_led(field);
        }
        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(LED_PIN, 0);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    return 0;
}

