#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define GPIO_POWER_PIN  17
#define ADC_CHANNEL     0
#define LOG_FILE        "current_log.txt"
#define SAMPLE_INTERVAL 1
#define ADC_MAX_VALUE   1023
#define ADC_VREF        5.0f

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int setup_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int init_spi(void)
{
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("open(SPI_DEVICE)");
        return -1;
    }

    unsigned char mode = SPI_MODE_0;
    unsigned char bits = 8;
    unsigned int speed = 1000000; /* 1 MHz */

    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("ioctl(SPI_IOC_WR_MODE)");
        close(fd);
        return -1;
    }
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("ioctl(SPI_IOC_WR_BITS_PER_WORD)");
        close(fd);
        return -1;
    }
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("ioctl(SPI_IOC_WR_MAX_SPEED_HZ)");
        close(fd);
        return -1;
    }

    return fd;
}

static int init_gpio(void)
{
    int fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd < 0) {
        perror("open(/sys/class/gpio/export)");
        return -1;
    }
    if (write(fd, "17", 1) == -1) {
        perror("write(/sys/class/gpio/export 17)");
        close(fd);
        return -1;
    }
    close(fd);

    usleep(100000); /* allow sysfs to create the directory */

    fd = open("/sys/class/gpio/gpio17/value", O_WRONLY);
    if (fd < 0) {
        perror("open(/sys/class/gpio/gpio17/value)");
        return -1;
    }
    if (write(fd, "1", 1) == -1) {
        perror("write(/sys/class/gpio/gpio17/value 1)");
        close(fd);
        return -1;
    }
    close(fd);

    return 0;
}

static int read_adc(int spi_fd, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = 3;
    tr.speed_hz = 1000000;
    tr.bits_per_word = 8;
    tr.delay_usecs = 0;
    tr.cs_change = 0;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("ioctl(SPI_IOC_MESSAGE)");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float adc_to_amperes(int adc_value)
{
    return (float)adc_value * (ADC_VREF / ADC_MAX_VALUE);
}

static int log_data(FILE *fp, float current)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        perror("localtime_r");
        return -1;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%.3f\n", timestamp, current) < 0) {
        perror("fprintf");
        return -1;
    }
    if (fflush(fp) == EOF) {
        perror("fflush");
        return -1;
    }
    return 0;
}

int main(void)
{
    int spi_fd = -1;
    FILE *fp = NULL;
    int ret = EXIT_FAILURE;

    if (setup_signal_handlers() != 0) {
        goto cleanup;
    }

    spi_fd = init_spi();
    if (spi_fd < 0) {
        goto cleanup;
    }

    if (init_gpio() != 0) {
        goto cleanup;
    }

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        goto cleanup;
    }

    printf("Starting current monitoring. Press Ctrl+C to stop.\n");

    while (g_running) {
        int adc_value = read_adc(spi_fd, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            break;
        }

        float current = adc_to_amperes(adc_value);

        if (log_data(fp, current) != 0) {
            fprintf(stderr, "Error logging data\n");
            break;
        }

        sleep(SAMPLE_INTERVAL);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fp != NULL) {
        fclose(fp);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (g_running == 0) {
        printf("\nExiting gracefully.\n");
    }
    return ret;
}

