 *   MCP3008 VREF -> Pi 5V
 *   MCP3008 AGND -> Pi GND
 *   MCP3008 DGND -> Pi GND
 *   MCP3008 CLK  -> Pi GPIO11 (SCLK)
 *   MCP3008 DOUT -> Pi GPIO9  (MISO)
 *   MCP3008 DIN  -> Pi GPIO10 (MOSI)
 *   MCP3008 CS   -> Pi GPIO8  (CE0)
 *   MCP3008 CH0  -> MLX91211 VOUT
 *   MLX91211 VDD -> Pi 5V
 *   MLX91211 GND -> Pi GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o current_monitor current_monitor.c -lpigpio -lrt
 * Run:    sudo ./current_monitor
 */

#define SPI_CHANNEL    0          /* CE0 (GPIO8) */
#define SPI_SPEED      1000000    /* 1 MHz – well within MCP3008 3.3 V limit */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */
#define ADC_CHANNEL    0          /* MCP3008 single-ended channel 0 */
#define LOG_FILE       "current_log.txt"
#define SAMPLE_US      100000     /* 100 ms between samples */
#define VREF           5.0f       /* MCP3008 reference voltage */
#define ADC_MAX        1023       /* 10-bit ADC */
#define ADC_VREF       ((float)ADC_MAX / (float)ADC_MAX + 1.0f) * VREF

static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler – set flag so main loop exits cleanly               */
/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read one sample from the MCP3008 on the given channel              */
/* Returns 0–1023 on success, -1 on SPI transfer error,               */
/* -2 on voltage outside the sensor's 0–5 V operating range.         */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care bits)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: rx[1] low 2 bits + rx[2] 8 bits = 10-bit value
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0, 0, 0 };

    int ret = spiXfer(SPI_CHANNEL, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "spiXfer failed (returned %d): %s\n",
                ret, strerror(errno));
        return -1;
    }

    int adc = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc;
}

/* ------------------------------------------------------------------ */
/* Convert ADC reading to current (A)                                */
/* ------------------------------------------------------------------ */
static float adc_to_current(int adc_value)
{
    float voltage = ((float)adc_value / (float)ADC_MAX) * VREF;
    if (voltage < 0.0f || voltage > 5.0f) {
        fprintf(stderr, "Warning: voltage %.3f V outside sensor range [0, 5 V]\n",
                voltage);
        return 0.0f;
    }
    return voltage / 3.3f;   /* MLX91211: 3.3 V full-scale */
}

/* ------------------------------------------------------------------ */
/* Append a timestamped current reading to the log file                */
/* ------------------------------------------------------------------ */
static int log_current(float current)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                 &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(g_log, "%s %.2f A\n", timestamp, current) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(g_log) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- open SPI ---- */
    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (channel %d, %d Hz): %s\n",
                SPI_CHANNEL, SPI_SPEED, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- open log file ---- */
    g_log = fopen(LOG_FILE, "a");
    if (g_log == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        fclose(g_log);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MLX91211 current monitor started. Logging to '%s'.\n", LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    /* ---- main sampling loop ---- */
    while (g_running) {
        int adc = read_mcp3008(ADC_CHANNEL);
        if (adc < 0) {
            /* SPI / transfer error – skip this sample, keep running */
            gpioDelay(SAMPLE_US);
            continue;
        }

        if (adc == 0 || adc == ADC_MAX) {
            /* Sensor disconnected or out of range – skip */
            gpioDelay(SAMPLE_US);
            continue;
        }

        float current = adc_to_current(adc);

        if (log_current(current) != 0) {
            /* Logging failed – exit cleanly */
            break;
        }

        gpioDelay(SAMPLE_US);
    }

    /* ---- cleanup ---- */
    printf("\nShutting down...\n");
    if (g_log != NULL) {
        fclose(g_log);
        g_log = NULL;
    }
    if (spiClose(spi_handle) != 0) {
        fprintf(stderr, "spiClose failed: %s\n", strerror(errno));
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

