#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17
#define DEBOUNCE_SAMPLES 5
#define DEBOUNCE_DELAY_US 2000
#define POLL_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor_debounced(int pin) {
    int low_count = 0;
    for (int i = 0; i < DEBOUNCE_SAMPLES; i++) {
        int v = gpioRead(pin);
        if (v < 0) {
            fprintf(stderr, "gpioRead failed on pin %d: %s\n", pin, pigpio_error(v));
            return -1;
        }
        if (v == 0) low_count++;
        gpioDelay(DEBOUNCE_DELAY_US);
    }
    return (low_count >= (DEBOUNCE_SAMPLES / 2) + 1) ? 0 : 1;
}

static void log_sensor_state(int s1, int s2) {
    printf("Sensor 1: %s, Sensor 2: %s\n", s1 ? "0" : "1", s2 ? "0" : "1");
    if (s1 == 0 && s2 == 0) {
        printf("ALERT: Both sensors detect object\n");
    }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SENSOR_1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SENSOR_2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO%d\n", SENSOR_1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO%d\n", SENSOR_2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Monitoring Omron B5W-DB01 sensors on GPIO%d and GPIO%d. Press Ctrl+C to exit.\n",
           SENSOR_1_PIN, SENSOR_2_PIN);

    while (running) {
        int s1 = read_sensor_debounced(SENSOR_1_PIN);
        int s2 = read_sensor_debounced(SENSOR_2_PIN);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "Sensor read error, exiting\n");
            break;
        }

        log_sensor_state(s1, s2);
        gpioDelay(POLL_INTERVAL_US);
    }

    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

