#include <time.h>
#include <signal.h>
#include <string.h>
#include <driver.h>
#include <stdint.h>

#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define MCP3008_CHANNEL 0
#define READ_DELAY 60
#define MIN_ADC 300
#define MAX_ADC 800
#define LOG_FILE "soil_moisture_log.csv"

static int spi_handle = -1;
static volatile sig_atomic_t program_running = 1;

int read_mcp3008(int channel);
double calculate_moisture_level(int adc_value);
int log_data(double moisture_level);
void signal_handler(int signal);

int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    uint8_t tx_buf[3] = {0x01, (uint8_t)((0x08 | channel) << 4), 0x00};
    uint8_t rx_buf[3] = {0};

    if (spiXfer(spi_handle, (char *)tx_buf, (char *)rx_buf, 3) != 3) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

double calculate_moisture_level(int adc_value) {
    if (adc_value < MIN_ADC || adc_value > MAX_ADC) {
        fprintf(stderr, "Error: ADC value out of range: %d\n", adc_value);
        return -1.0;
    }
    return (double)(adc_value - MIN_ADC) / (double)(MAX_ADC - MIN_ADC) * 100.0;
}

int log_data(double moisture_level) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f\n", timestamp, moisture_level);
    fclose(fp);
    return 0;
}

void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        program_running = 0;
    }
}

int spi_setup(spi_config_t *config) {
    config->spiClock = SPI_BAUD;
    config->spiChannel = SPI_CHANNEL;
    config->spiMode = 0;
    config->csActive = 0;
    config->txBitOrder = 0;
    config->rxBitOrder = 0;
    config->txDataAlignment = 0;
    config->rxDataAlignment = 0;
    config->txDataSize = 8;
    config->rxDataSize = 8;
    config->txDelay = 0;
    config->rxDelay = 0;
    config->txDataHold = 0;
    config->rxDataHold = 0;
    config->txDataActive = 0;
    config->rxDataActive = 0;
    config->txDataFlags = 0;
    config->rxDataFlags = 0;
    config->txDataPriority = 0;
    config->rxDataPriority = 0;
    config->txOverrun = 0;
    config->rxOverrun = 0;
    config->txByteEnable = 0;
    config->rxByteEnable = 0;
    config->txByteSelect = 0;
    config->rxByteSelect = 0;
    config->txByteDisable = 0;
    config->rxByteDisable = 0;
    config->txByteSelectActive = 0;
    config->rxByteSelectActive = 0;
    config->txByteDisableActive = 0;
    config->rxByteDisableActive = 0;
    return 0;
}

int main() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }

    if (driverInitialise() < 0) {
        fprintf(stderr, "Error: Could not initialize driver\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: Could not open SPI device\n");
        driverTerminate();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Soil Moisture Monitoring Program\n");
    printf("Press Ctrl+C to exit\n");

    while (program_running) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            sleep(READ_DELAY);
            continue;
        }

        double moisture_level = calculate_moisture_level(adc_value);
        if (moisture_level < 0) {
            fprintf(stderr, "Error: Failed to calculate moisture level\n");
            sleep(READ_DELAY);
            continue;
        }

        if (log_data(moisture_level) != 0) {
            fprintf(stderr, "Error: Failed to log data\n");
        }

        printf("Moisture Level: %.2f%%\n", moisture_level);
        sleep(READ_DELAY);
    }

    spiClose(spi_handle);
    driverTerminate();
    printf("Program terminated.\n");
    return 0;
}

