#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <syslog.h>
#include <errno.h>
#include <fcntl.h>
#include <poll.h>
#include <gpiod.h>

#define PIR_PIN          17
#define POLL_TIMEOUT_MS  50
#define DEBOUNCE_MS      200
#define CAPTURE_DIR      "/home/pi/security_cam"
#define POLL_TIMEOUT_NS  (POLL_TIMEOUT_MS * 1000000L)

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_event(int priority, const char *msg)
{
    syslog(priority, "%s", msg);
}

static int ensure_directory(const char *path)
{
    struct stat st;
    if (stat(path, &st) == 0) {
        if (S_ISDIR(st.st_mode))
            return 0;
        log_event(LOG_WARNING, "Target directory exists but is not a directory");
        return -1;
    }
