#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>

#define DEFAULT_DEVICE "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define NUM_BUFFERS 4
#define FRAME_COUNT 100
#define TIMEOUT_SEC 2

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int camera_init(int fd) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;

    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "VIDIOC_QUERYCAP failed: %s\n", strerror(errno));
        return -1;
    }
    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        return -1;
    }
    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming I/O\n");
        return -1;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_GREY;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "VIDIOC_S_FMT failed: %s\n", strerror(errno));
        return -1;
    }

    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(stderr, "VIDIOC_REQBUFS failed: %s\n", strerror(errno));
        return -1;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (xioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        fprintf(stderr, "VIDIOC_QUERYBUF failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int camera_open(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", device, strerror(errno));
        return -1;
    }
    return fd;
}

static int camera_start(int fd) {
    if (xioctl(fd, VIDIOC_STREAMON, &struct v4l2_capability { .cap = V4L2_CAP_VIDEO_CAPTURE }) < 0) {
        fprintf(stderr, "VIDIOC_STREAMON failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int camera_close(int fd) {
    if (xioctl(fd, VIDIOC_STREAMOFF, &struct v4l2_capability { .cap = V4L2_CAP_VIDEO_CAPTURE }) < 0) {
        fprintf(stderr, "VIDIOC_STREAMOFF failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int camera_release_buffers(int fd, unsigned long *bufs) {
    unsigned long n = 0;
    for (unsigned long i = 0; i < NUM_BUFFERS; i++) {
        if (bufs[i] >= 0) {
            if (xioctl(fd, VIDIOC_QBUF, &bufs[i]) < 0) {
                fprintf(stderr, "VIDIOC_QBUF failed: %s\n", strerror(errno));
                return -1;
            }
            n++;
        }
    }
    return n;
}

static int camera_mmap(int fd, unsigned long *bufs) {
    unsigned long n = 0;
    for (unsigned long i = 0; i < NUM_BUFFERS; i++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (xioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            fprintf(stderr, "VIDIOC_QUERYBUF failed: %s\n", strerror(errno));
            return -1;
        }

        if (bufs[i] < 0) {
            bufus[i] = buf.length;
            bufus[i] = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
            if (bufus[i] == MAP_FAILED) {
                fprintf(stderr, "mmap failed: %s\n", strerror(errno));
                return -1;
            }
            bufus[i] = buf.m.offset;
            bufus[i] = buf.length;
            n++;
        }
    }
    return n;
}

static int camera_read_frame(int fd, unsigned long *bufs, unsigned long *n) {
    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = TIMEOUT_SEC;
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);
    if (r == -1) {
        if (errno == EINTR) return 0;
        fprintf(stderr, "select() failed: %s\n", strerror(errno));
        return -1;
    }
    if (r == 0) {
        fprintf(stderr, "select() timeout\n");
        return -1;
    }

    unsigned long nbufs = *n;
    for (unsigned long i = 0; i < NUM_BUFFERS; i++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;

        if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
            if (errno == EAGAIN) continue;
            fprintf(stderr, "VIDIOC_DQBUF failed: %s\n", strerror(errno));
            return -1;
        }

        if (buf.index == i) {
            unsigned long len = buf.bytesused;
            unsigned char *data = (unsigned char *)buf.m.offset;
            FILE *fp = fopen("image_0001.pgm", "wb");
            if (!fp) {
                fprintf(stderr, "Cannot open image_0001.pgm: %s\n", strerror(errno));
                xioctl(fd, VIDIOC_QBUF, &buf);
                return -1;
            }
            fprintf(fp, "P5\n%d %d\n255\n", IMAGE_WIDTH, IMAGE_HEIGHT);
            fwrite(data, 1, len, fp);
            fclose(fp);
            *n = nbufs + 1;
        }
        xioctl(fd, VIDIOC_QBUF, &buf);
    }
    return 0;
}

int main(int argc, char *argv[]) {
    const char *device = DEFAULT_DEVICE;
    if (argc > 1) device = argv[1];

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return 1;
    }

    int fd = camera_open(device);
    if (fd < 0) return 1;

    if (camera_init(fd) < 0) {
        close(fd);
        return 1;
    }

    if (camera_start(fd) < 0) {
        close(fd);
        return 1;
    }

    unsigned long *bufs = calloc(NUM_BUFFERS, sizeof(unsigned long));
    if (!bufs) {
        fprintf(stderr, "Out of memory\n");
        camera_close(fd);
        return 1;
    }

    for (int i = 0; i < NUM_BUFFERS; i++) bufus[i] = -1;

    if (camera_mmap(fd, bufus) < 0) {
        for (int i = 0; i < NUM_BUFFERS; i++) {
            if (bufus[i] >= 0) xioctl(fd, VIDIOC_QBUF, &bufs[i]);
        }
        camera_close(fd);
        free(bufus);
        return 1;
    }

    unsigned long nbufs = *n;
    printf("Capturing %d frames...\n", FRAME_COUNT);

    while (running && nbufs < FRAME_COUNT) {
        if (camera_read_frame(fd, bufus, &nbufs) < 0) break;
    }

    for (int i = 0; i < NUM_BUFFERS; i++) {
        if (bufus[i] >= 0) xioctl(fd, VIDIOC_QBUF, &bufs[i]);
    }

    camera_close(fd);
    free(bufus);
    printf("Captured %d frames.\n", nbufs);

    return 0;
}

