    if (xioctl(fd, VIDIOC_STREAMOFF, &struct v4l2_capability { .cap = V4L2_CAP_VIDEO_CAPTURE }) < 0) {
        fprintf(stderr, "VIDIOC_STREAMOFF failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int camera_release_buffers(int fd, unsigned long *bufs) {
    unsigned long n = 0;
    for (unsigned long i = 0; i < NUM_BUFFERS; i++) {
        if (bufs[i] >= 0) {
            if (xioctl(fd, VIDIOC_QBUF, &bufs[i]) < 0) {
                fprintf(stderr, "VIDIOC_QBUF failed: %s\n", strerror(errno));
                return -1;
            }
            n++;
        }
    }
    return n;
}

static int camera_mmap(int fd, unsigned long *bufs) {
    unsigned long n = 0;
    for (unsigned long i = 0; i < NUM_BUFFERS; i++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (xioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            fprintf(stderr, "VIDIOC_QUERYBUF failed: %s\n", strerror(errno));
            return -1;
        }

        if (bufs[i] < 0) {
            bufus[i] = buf.length;
            bufus[i] = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
            if (bufus[i] == MAP_FAILED) {
                fprintf(stderr, "mmap failed: %s\n", strerror(errno));
                return -1;
            }
            bufus[i] = buf.m.offset;
            bufus[i] = buf.length;
            n++;
        }
    }
    return n;
}

static int camera_read_frame(int fd, unsigned long *bufs, unsigned long *n) {
    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = TIMEOUT_SEC;
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);
    if (r == -1) {
        if (errno == EINTR) return 0;
        fprintf(stderr, "select() failed: %s\n", strerror(errno));
        return -1;
    }
    if (r == 0) {
        fprintf(stderr, "select() timeout\n");
        return -1;
    }

    unsigned long nbufs = *n;
    for (unsigned long i = 0; i < NUM_BUFFERS; i++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;

        if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
            if (errno == EAGAIN) continue;
            fprintf(stderr, "VIDIOC_DQBUF failed: %s\n", strerror(errno));
            return -1;
        }

        if (buf.index == i) {
            unsigned long len = buf.bytesused;
            unsigned char *data = (unsigned char *)buf.m.offset;
            FILE *fp = fopen("image_0001.pgm", "wb");
            if (!fp) {
                fprintf(stderr, "Cannot open image_0001.pgm: %s\n", strerror(errno));
                xioctl(fd, VIDIOC_QBUF, &buf);
                return -1;
            }
            fprintf(fp, "P5\n%d %d\n255\n", IMAGE_WIDTH, IMAGE_HEIGHT);
            fwrite(data, 1, len, fp);
            fclose(fp);
            *n = nbufs + 1;
        }
        xioctl(fd, VIDIOC_QBUF, &buf);
    }
    return 0;
}

int main(int argc, char *argv[]) {
    const char *device = DEFAULT_DEVICE;
    if (argc > 1) device = argv[1];

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return 1;
    }

    int fd = camera_open(device);
    if (fd < 0) return 1;

    if (camera_init(fd) < 0) {
        close(fd);
        return 1;
    }

    if (camera_start(fd) < 0) {
        close(fd);
        return 1;
    }

    unsigned long *bufs = calloc(NUM_BUFFERS, sizeof(unsigned long));
    if (!bufs) {
        fprintf(stderr, "Out of memory\n");
        camera_close(fd);
        return 1;
    }

    for (int i = 0; i < NUM_BUFFERS; i++) bufus[i] = -1;

    if (camera_mmap(fd, bufus) < 0) {
        for (int i = 0; i < NUM_BUFFERS; i++) {
            if (bufus[i] >= 0) xioctl(fd, VIDIOC_QBUF, &bufs[i]);
        }
        camera_close(fd);
        free(bufus);
        return 1;
    }

    unsigned long nbufs = *n;
    printf("Capturing %d frames...\n", FRAME_COUNT);

    while (running && nbufs < FRAME_COUNT) {
        if (camera_read_frame(fd, bufus, &nbufs) < 0) break;
    }

    for (int i = 0; i < NUM_BUFFERS; i++) {
        if (bufus[i] >= 0) xioctl(fd, VIDIOC_QBUF, &bufs[i]);
    }

    camera_close(fd);
    free(bufus);
    printf("Captured %d frames.\n", nbufs);

    return 0;
}

