        fprintf(stderr, "Failed to open %s: %s\n", VIDEO_DEVICE, strerror(errno));
        return EXIT_FAILURE;
    }

    struct v4l2_capability cap;
    memset(&cap, 0, sizeof(cap));
    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "VIDIOC_QUERYCAP failed: %s\n", strerror(errno));
        goto cleanup;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", VIDEO_DEVICE);
        goto cleanup;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming I/O\n", VIDEO_DEVICE);
        goto cleanup;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "VIDIOC_S_FMT failed: %s\n", strerror(errno));
        goto cleanup;
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(stderr, "VIDIOC_REQBUFS failed: %s\n", strerror(errno));
        goto cleanup;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (xioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        fprintf(stderr, "VIDIOC_QUERYBUF failed: %s\n", strerror(errno));
        goto cleanup;
    }

    frame_buffer = (unsigned char *)malloc(buf.length);
    if (!frame_buffer) {
        fprintf(stderr, "Failed to allocate frame buffer: %s\n", strerror(errno));
        goto cleanup;
    }

    if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        fprintf(stderr, "VIDIOC_QBUF failed: %s\n", strerror(errno));
        goto cleanup;
    }

    if (xioctl(fd, VIDIOC_STREAMON, &buf) < 0) {
        fprintf(stderr, "VIDIOC_STREAMON failed: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Capturing MJPEG video from %s...\n", VIDEO_DEVICE);

    while (g_running) {
        FD_ZERO(&readfds);
        FD_SET(fd, &readfds);

        tv.tv_sec = CAPTURE_TIMEOUT_SEC;
        tv.tv_usec = CAPTURE_TIMEOUT_USEC;

        int sel = select(fd + 1, &readfds, NULL, NULL, &tv);
        if (sel < 0) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "select() failed: %s\n", strerror(errno));
            break;
        }

        if (sel == 0) {
            fprintf(stderr, "Timeout: no frame available in %d.%06ld seconds\n",
                    CAPTURE_TIMEOUT_SEC, CAPTURE_TIMEOUT_USEC);
            continue;
        }

        if (capture_frame(fd, frame_buffer, &buf.length) < 0) {
            fprintf(stderr, "Frame capture failed, continuing...\n");
            continue;
        }

        struct timespec ts;
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            fprintf(stderr, "clock_gettime() failed: %s\n", strerror(errno));
            continue;
        }

        char timestamp[32];
        struct tm tm_info;
        if (localtime_r(&ts.tv_sec, &tm_info) == NULL) {
            fprintf(stderr, "localtime_r() failed\n");
            continue;
        }
        if (strftime(timestamp, sizeof(timestamp), "%d.%06ld", &tm_info) == 0) {
            fprintf(stderr, "strftime() failed\n");
            continue;
        }

        if (log_timestamp(LOG_FILE, timestamp) < 0) {
            fprintf(stderr, "Failed to log timestamp\n");
        }

        printf("Captured frame: %s\n", timestamp);
    }

    printf("\nShutting down gracefully...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (frame_buffer) {
        free(frame_buffer);
    }
    if (fd >= 0) {
        xioctl(fd, VIDIOC_STREAMOFF, &buf);
        close(fd);
    }
    return ret;
}

