    int fd = open(name, O_RDWR);
    if (fd < 0) {
        perror("open device");
        return -1;
    }
    return fd;
}

static int init_device(int fd) {
    struct v4l2_capability cap;
    memset(&cap, 0, sizeof(cap));
    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("VIDIOC_QUERYCAP");
        return -1;
    }
    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        return -1;
    }
    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming I/O\n");
        return -1;
    }
    return 0;
}

static int set_pixel_format(int fd, enum v4l2_pixel_format fmt) {
    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = fmt;
    if (xioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("VIDIOC_S_FMT");
        return -1;
    }
    if (fmt.fmt.pix.pixelformat != fmt) {
        fprintf(stderr, "Warning: device selected MJPEG format\n");
    }
    return 0;
}

static int mmap_buffers(int fd, void **buffers, size_t *n_buffers) {
    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("VIDIOC_REQBUFS");
        return -1;
    }
    if (req.count < 1) {
        fprintf(stderr, "Insufficient buffer memory\n");
        return -1;
    }

    *n_buffers = req.count;
    buffers = calloc(*n_buffers, sizeof(void *));
    if (!buffers) {
        perror("calloc");
        return -1;
    }

    for (int i = 0; i < *n_buffers; i++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (xioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("VIDIOC_QUERYBUF");
            return -1;
        }

        void *buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
        if (buffer == MAP_FAILED) {
            perror("mmap");
            return -1;
        }
        buffers[i] = buffer;
    }
    return 0;
}

static int start_streaming(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("VIDIOC_STREAMON");
        return -1;
    }
    return 0;
}

static int stop_streaming(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("VIDIOC_STREAMOFF");
        return -1;
    }
    return 0;
}

static int dequeue_buffer(int fd, void **buffer, size_t *buf_size) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("VIDIOC_DQBUF");
        return -1;
    }

    *buffer = buf.m.offset;
    *buf_size = buf.length;
    return 0;
}

static int write_to_file(const char *filename, const void *data, size_t size) {
    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        perror("fopen");
        return -1;
    }
    size_t written = fwrite(data, 1, size, fp);
    if (written != size) {
        perror("fwrite");
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction SIGINT");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction SIGTERM");
        return 1;
    }

    int fd = open_device(DEVICE_NAME);
    if (fd < 0) {
        return 1;
    }

    if (init_device(fd) < 0) {
        close(fd);
        return 1;
    }

    if (set_pixel_format(fd, V4L2_PIX_FMT_MJPEG) < 0) {
        close(fd);
        return 1;
    }

    void *buffers[NUM_BUFFERS];
    size_t n_buffers = 0;

    if (mmap_buffers(fd, buffers, &n_buffers) < 0) {
        close(fd);
        return 1;
    }

    if (start_streaming(fd) < 0) {
        stop_streaming(fd);
        munmap(buffers, n_buffers * sizeof(void *));
        free(buffers);
        close(fd);
        return 1;
    }

    void *frame = NULL;
    size_t frame_size = 0;
    if (dequeue_buffer(fd, &frame, &frame_size) < 0) {
        stop_streaming(fd);
        munmap(buffers, n_buffers * sizeof(void *));
        free(buffers);
        close(fd);
        return 1;
    }

    if (frame_size == 0) {
        fprintf(stderr, "Frame buffer is empty\n");
        stop_streaming(fd);
        munmap(buffers, n_buffers * sizeof(void *));
        free(buffers);
        close(fd);
        return 1;
    }

    if (write_to_file(OUTPUT_FILE, frame, frame_size) < 0) {
        stop_streaming(fd);
        munmap(buffers, n_buffers * sizeof(void *));
        free(buffers);
        close(fd);
        return 1;
    }

    stop_streaming(fd);
    for (size_t i = 0; i < n_buffers; i++) {
        if (buffers[i]) {
            munmap(buffers[i], buffers[i] ? buffers[i] / (size_t)IMAGE_WIDTH : 0);
        }
    }
    free(buffers);
    close(fd);

    printf("Saved image to %s\n", OUTPUT_FILE);
    return 0;
}

