#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define TILT_UP_BUTTON 6
#define TILT_DOWN_BUTTON 7
#define PAN_LEFT_BUTTON 8
#define PAN_RIGHT_BUTTON 9

#define MIN_PULSE_WIDTH 1000   /* microseconds */
#define MAX_PULSE_WIDTH 2000   /* microseconds */
#define MIN_DUTY 50
#define MAX_DUTY 100
#define SERVO_MIN_PULSE 1000   /* microseconds */
#define SERVO_MAX_PULSE 2000   /* microseconds */
#define SERVO_MIN_ANGLE 25
#define SERVO_MAX_ANGLE 125
#define PAN_TILT_INCREMENT 5
#define POLL_DELAY_US 50000     /* 50 ms */
#define PWM_PERIOD_US 20000     /* 20 ms -> 50 Hz */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int set_servo_angle(int pin, int angle)
{
    if (angle < SERVO_MIN_ANGLE) angle = SERVO_MIN_ANGLE;
    if (angle > SERVO_MAX_ANGLE) angle = SERVO_MAX_ANGLE;

    int pulse_width = SERVO_MIN_PULSE +
        (int)((long)(angle - SERVO_MIN_ANGLE) *
              (SERVO_MAX_PULSE - SERVO_MIN_PULSE) /
              (SERVO_MAX_ANGLE - SERVO_MIN_ANGLE));

    if (gpioServo(pin, pulse_width) < 0) {
        fprintf(stderr, "gpioServo failed on pin %d (pulse %d us)\n",
                pin, pulse_width);
        return -1;
    }
    return 0;
}

static int adjust_pan(int angle, int *position)
{
    int new_angle = angle + PAN_TILT_INCREMENT;
    if (new_angle < SERVO_MIN_ANGLE) new_angle = SERVO_MIN_ANGLE;
    if (new_angle > SERVO_MAX_ANGLE) new_angle = SERVO_MAX_ANGLE;

    *position = new_angle;
    return 0;
}

static int adjust_tilt(int angle, int *position)
{
    int new_angle = angle - PAN_TILT_INCREMENT;
    if (new_angle < SERVO_MIN_ANGLE) new_angle = SERVO_MIN_ANGLE;
    if (new_angle > SERVO_MAX_ANGLE) new_angle = SERVO_MAX_ANGLE;

    *position = new_angle;
    return 0;
}

static int set_button(int pin, int state)
{
    if (gpioSetMode(pin, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed on pin %d\n", pin);
        return -1;
    }
    if (gpioSetPullUpDown(pin, PI_PUD_UP) < 0) {
        fprintf(stderr, "gpioSetPullUpDown failed on pin %d\n", pin);
        return -1;
    }
    if (gpioWrite(pin, state) < 0) {
        fprintf(stderr, "gpioWrite failed on pin %d\n", pin);
        return -1;
    }
    return 0;
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (set_servo_angle(PAN_SERVO_PIN, 75) != 0 ||
        set_servo_angle(TILT_SERVO_PIN, 75) != 0) {
        fprintf(stderr, "Failed to initialise servos\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int pan_angle = 75;
    int tilt_angle = 75;

    if (set_button(TILT_UP_BUTTON, 0) != 0 ||
        set_button(TILT_DOWN_BUTTON, 0) != 0 ||
        set_button(PAN_LEFT_BUTTON, 0) != 0 ||
        set_button(PAN_RIGHT_BUTTON, 0) != 0) {
        fprintf(stderr, "Failed to initialise button pins\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (g_running) {
        int tilt_up = gpioRead(TILT_UP_BUTTON);
        int tilt_down = gpioRead(TILT_DOWN_BUTTON);
        int pan_left = gpioRead(PAN_LEFT_BUTTON);
        int pan_right = gpioRead(PAN_RIGHT_BUTTON);

        if (tilt_up < 0 || tilt_down < 0 ||
            pan_left < 0 || pan_right < 0) {
            fprintf(stderr, "gpioRead error\n");
            break;
        }

        if (tilt_up == 0) {
            if (adjust_tilt(tilt_angle, &tilt_angle) != 0) {
                fprintf(stderr, "Tilt adjustment failed\n");
            }
        } else if (tilt_down == 0) {
            if (adjust_tilt(tilt_angle, &tilt_angle) != 0) {
                fprintf(stderr, "Tilt adjustment failed\n");
            }
        }

        if (pan_left == 0) {
            if (adjust_pan(pan_angle, &pan_angle) != 0) {
                fprintf(stderr, "Pan adjustment failed\n");
            }
        } else if (pan_right == 0) {
            if (adjust_pan(pan_angle, &pan_angle) != 0) {
                fprintf(stderr, "Pan adjustment failed\n");
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* Clean shutdown: stop PWM and release servo pins */
    gpioServo(PAN_SERVO_PIN, 0);
    gpioServo(TILT_SERVO_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

