#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>
#include <errno.h>
#include <time.h>
#include <signal.h>

#define VIDEO_DEVICE "/dev/video0"
#define JPEG_QUALITY 75
#define NUM_BUFFERS 4
#define TIMEOUT_SEC 2

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int xioctl(int fd, int request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int init_camera(int *fd) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    unsigned int i;

    *fd = open(VIDEO_DEVICE, O_RDWR);
    if (*fd < 0) {
        perror("open");
        return -1;
    }

    if (xioctl(*fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("VIDIOC_QUERYCAP");
        goto fail;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", VIDEO_DEVICE);
        goto fail;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming i/o\n", VIDEO_DEVICE);
        goto fail;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(*fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("VIDIOC_S_FMT");
        goto fail;
    }

    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(*fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("VIDIOC_REQBUFS");
        goto fail;
    }

    if (req.count < 1) {
        fprintf(stderr, "Insufficient buffer memory\n");
        goto fail;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (xioctl(*fd, VIDIOC_QUERYBUF, &buf) < 0) {
        perror("VIDIOC_QUERYBUF");
        goto fail;
    }

    if (buf.length < 1024) {
        fprintf(stderr, "Insufficient buffer size\n");
        goto fail;
    }

    if (xioctl(*fd, VIDIOC_QBUF, &buf) < 0) {
        perror("VIDIOC_QBUF");
        goto fail;
    }

    return 0;

fail:
    close(*fd);
    *fd = -1;
    return -1;
}

static int start_streaming(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("VIDIOC_STREAMON");
        return -1;
    }
    return 0;
}

static int stop_streaming(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("VIDIOC_STREAMOFF");
        return -1;
    }
    return 0;
}

static int capture_frame(int fd, void **buffer) {
    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = TIMEOUT_SEC;
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);
    if (r == -1) {
        if (errno == EINTR) return 0;
        perror("select");
        return -1;
    }
    if (r == 0) {
        fprintf(stderr, "select timeout\n");
        return -1;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_DQBUF, &type) < 0) {
        perror("VIDIOC_DQBUF");
        return -1;
    }

    *buffer = (void *)type.m.offset;
    return 1;
}

static int convert_yuyv_to_rgb24(const unsigned char *yuyv, unsigned char *rgb, int width, int height) {
    const unsigned char *yuyv_ptr = (const unsigned char *)yuyv;
    unsigned char *rgb_ptr = (unsigned char *)rgb;

    for (int i = 0; i < height * width; i += 2) {
        int y0 = yuyv_ptr[i];
        int u = yuyv_ptr[i + 1];
        int y1 = yuyv_ptr[i + width];
        int v = yuyv_ptr[i + width + 1];

        int y = (y0 + y1) / 2;
        int u_r = (u - 128) * 2980 / 1000;
        int u_g = (u - 128) * 409 / 1000;
        int u_b = (u - 128) * 558 / 1000;
        int y_r = y * 2980 / 1000;
        int y_g = y * 409 / 1000;
        int y_b = y * 558 / 1000;

        int c = y_r - 16;
        int cr = y_r - c;
        int cg = y_g - c;
        int cb = y_b - c;

        int r = (cr < 0) ? 0 : (cr < 16) ? cr * 12 + 16 : cr * 12 + 16;
        int g = (cg < 0) ? 0 : (cg < 16) ? cg * 12 + 16 : cg * 12 + 16;
        int b = (cb < 0) ? 0 : (cb < 16) ? cb * 12 + 16 : cb * 12 + 16;

        rgb_ptr[i] = (unsigned char)r;
        rgb_ptr[i + 1] = (unsigned char)g;
        rgb_ptr[i + 2] = (unsigned char)b;
    }
    return 0;
}

static int encode_jpeg(const unsigned char *rgb, int width, int height, const char *filename) {
    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        perror("fopen");
        return -1;
    }

    struct jpeg_compress_struct cinfo;
    struct jpeg_error_mgr jerr;
    unsigned char *buffer = NULL;
    int row_stride = width * 3;

    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_compress(&cinfo);
    jpeg_mem_dest(&cinfo, &buffer, 1 << 20);

    cinfo.image_width = width;
    cinfo.image_height = height;
    cinfo.input_components = 3;
    cinfo.in_color_space = JCS_RGB;

    jpeg_set_defaults(&cinfo);
    jpeg_set_quality(&cinfo, JPEG_QUALITY, TRUE);
    jpeg_start_compress(&cinfo, TRUE);

    JSAMPROW row = (JSAMPROW)rgb;
    while (cinfo.next_scanline < cinfo.image_height) {
        jpeg_write_scanlines(&cinfo, &row, 1);
    }

    jpeg_finish_compress(&cinfo);
    jpeg_destroy_compress(&cinfo);
    jpeg_destroy_error(&jerr);

    if (ferror(fp)) {
        perror("fwrite");
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }

    return 0;
}

int main(void) {
    int fd = -1;
    unsigned char *yuyv = NULL;
    unsigned char *rgb = NULL;
    char filename[64];

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    if (init_camera(&fd) != 0) {
        fprintf(stderr, "Camera initialization failed\n");
        return 1;
    }

    if (start_streaming(fd) != 0) {
        fprintf(stderr, "Failed to start streaming\n");
        goto cleanup;
    }

    while (running) {
        if (capture_frame(fd, &yuyv) == 0) {
            if (convert_yuyv_to_rgb24(yuyv, rgb, 640, 480) != 0) {
                fprintf(stderr, "Failed to convert YUYV to RGB\n");
                break;
            }

            if (encode_jpeg(rgb, 640, 480, filename) != 0) {
                fprintf(stderr, "Failed to encode JPEG\n");
                break;
            }

            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[20];
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y%m%d_%H%M%S", timeinfo);

            snprintf(filename, sizeof(filename), "capture_%s.jpg", timestamp);
            printf("Captured image: %s\n", filename);
        } else {
            fprintf(stderr, "Failed to capture frame\n");
        }
    }

cleanup:
    if (yuyv) munmap((void *)yuyv, 1024);
    if (rgb) munmap((void *)rgb, 1024 * 640 * 480);
    if (fd >= 0) stop_streaming(fd);
    if (fd >= 0) close(fd);
    return 0;
}

