/*
 * v4l2_info.c — V4L2 camera information reporter for Raspberry Pi CSI camera.
 *
 * Build:  gcc -O2 -Wall -Wextra -o v4l2_info v4l2_info.c
 * Run:    ./v4l2_info
 *
 * Requires: /dev/video0 (CSI camera) and a 32-bit or 64-bit Raspberry Pi
 *           kernel with the V4L2 subsystem enabled.
 */

#include <errno.h>
#include <fcntl.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"

/* ------------------------------------------------------------------ */
/* Globals for cleanup in signal handler                            */
/* ------------------------------------------------------------------ */
static volatile sig_atomic_t g_stop = 0;

static void sig_handler(int signo)
{
    (void)signo;
    g_stop = 1;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1)
        perror("sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) == -1)
        perror("sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

/* Return 1 if the device node exists and can be opened. */
static int device_exists(void)
{
    return access(DEVICE_NAME, F_OK) == 0;
}

/* Open the V4L2 device node. Returns fd >= 0 on success, -1 on error. */
static int open_device(const char *name)
{
    int fd = open(name, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", name, strerror(errno));
        return -1;
    }
    return fd;
}

/* Enumerate frame sizes supported by the device. */
static int enumerate_frame_sizes(int fd, struct v4l2_frmsizeenum *sizes,
                                 int *num_sizes)
{
    if (VIDIOC_ENUM_FRAMESIZES(fd, sizes) < 0) {
        fprintf(stderr, "VIDIOC_ENUM_FRAMESIZES failed: %s\n",
                strerror(errno));
        return -1;
    }
    *num_sizes = sizes->count;
    return 0;
}

/* Enumerate frame intervals for a given frame size. */
static int enumerate_frame_intervals(int fd, struct v4l2_frmsizeenum *size,
                                     struct v4l2_frmivalenum *intervals,
                                     int *num_intervals)
{
    if (VIDIOC_ENUM_FRAMEINTERVALS(fd, intervals) < 0) {
        fprintf(stderr, "VIDIOC_ENUM_FRAMEINTERVALS failed: %s\n",
                strerror(errno));
        return -1;
    }
    *num_intervals = intervals->count;
    return 0;
}

/* Query a V4L2 control ID. Returns 1 if the control is supported. */
static int query_control(int fd, unsigned int ctrl_id, int *value)
{
    struct v4l2_queryctrl q;
    memset(&q, 0, sizeof(q));
    q.id = ctrl_id;

    if (VIDIOC_QUERYCTRL(fd, &q) < 0) {
        fprintf(stderr, "VIDIOC_QUERYCTRL failed for id %u: %s\n",
                ctrl_id, strerror(errno));
        return -1;
    }
    *value = q.value;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    int fd = -1;
    int rc = EXIT_FAILURE;

    install_signal_handlers();

    if (!device_exists()) {
        fprintf(stderr, "Device node %s does not exist.\n", DEVICE_NAME);
        return EXIT_FAILURE;
    }

    fd = open_device(DEVICE_NAME);
    if (fd < 0)
        goto done;

    struct v4l2_capability cap;
    memset(&cap, 0, sizeof(cap));

    if (VIDIOC_QUERYCAP(fd, &cap) < 0) {
        fprintf(stderr, "VIDIOC_QUERYCAP failed: %s\n", strerror(errno));
        goto done;
    }

    printf("Camera information for %s:\n", DEVICE_NAME);

    printf("  Device name : %s\n", cap.card);
    printf("  Driver      : %s\n", cap.driver);
    printf("  Bus info    : %s\n", cap.bus_info);

    printf("  Capabilities:\n");
    printf("    %s\n", cap.capabilities & V4L2_CAP_VIDEO_CAPTURE ? "VIDEO-CAPTURE" : "none");
    printf("    %s\n", cap.capabilities & V4L2_CAP_VIDEO_CAPTURE ? "VIDEO-CAPTURE" : "none");
    printf("    %s\n", cap.capabilities & V4L2_CAP_READWRITE ? "READ-WRITE" : "none");
    printf("    %s\n", cap.capabilities & V4L2_CAP_READ ? "READ" : "none");
    printf("    %s\n", cap.capabilities & V4L2_CAP_WRITE ? "WRITE" : "none");

    printf("  Frame sizes:\n");
    int num_sizes = 0;
    struct v4l2_frmsizeenum *sizes = NULL;

    if (enumerate_frame_sizes(fd, &sizes, &num_sizes) < 0)
        goto done;

    printf("    %d frame size(s):\n", num_sizes);
    for (int i = 0; i < num_sizes; i++) {
        printf("      %4u x %4u\n", sizes[i].width, sizes[i].height);
    }

    printf("  Frame intervals for %d frame size(s):\n", num_sizes);
    int num_intervals = 0;
    struct v4l2_frmivalenum *intervals = NULL;

    for (int i = 0; i < num_sizes; i++) {
        if (enumerate_frame_intervals(fd, &sizes[i], &intervals, &num_intervals) < 0)
            goto done;
        printf("      %d interval(s):\n", num_intervals);
        for (int j = 0; j < num_intervals; j++) {
            printf("        %4u/%d Hz\n", intervals[j].num, intervals[j].denom);
        }
    }

    printf("  Focus control:\n");
    int focus_auto = 0;
    if (query_control(fd, V4L2_CID_FOCUS_AUTO, &focus_auto) < 0)
        goto done;

    printf("    %s\n", focus_auto ? "FOCUS_AUTO" : "FOCUS_MANUAL");

    rc = EXIT_SUCCESS;

done:
    if (intervals) intervals->index = 0;
    if (sizes) sizes->index = 0;
    if (fd >= 0) close(fd);
    return rc;
}

