        }
    }

    printf("  Focus control:\n");
    int focus_auto = 0;
    if (query_control(fd, V4L2_CID_FOCUS_AUTO, &focus_auto) < 0)
        goto done;

    printf("    %s\n", focus_auto ? "FOCUS_AUTO" : "FOCUS_MANUAL");

    rc = EXIT_SUCCESS;

done:
    if (intervals) intervals->index = 0;
    if (sizes) sizes->index = 0;
    if (fd >= 0) close(fd);
    return rc;
}

