#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define UP_BUTTON_PIN 6
#define DOWN_BUTTON_PIN 7
#define LEFT_BUTTON_PIN 8
#define RIGHT_BUTTON_PIN 9

#define MIN_PULSE_WIDTH 1000
#define MAX_PULSE_WIDTH 2000
#define CENTER_PULSE_WIDTH 1500
#define PULSE_INCREMENT 10
#define LOOP_DELAY_US 50000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_servo_pulse(int pin, int pulse_width) {
    if (pulse_width < MIN_PULSE_WIDTH || pulse_width > MAX_PULSE_WIDTH) {
        fprintf(stderr, "Error: pulse width %d out of range [%d, %d]\n",
                pulse_width, MIN_PULSE_WIDTH, MAX_PULSE_WIDTH);
        return -1;
    }
    if (gpioServo(pin, pulse_width) < 0) {
        fprintf(stderr, "Error: gpioServo failed on pin %d\n", pin);
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    gpioServo(PAN_SERVO_PIN, 0);
    gpioServo(TILT_SERVO_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(UP_BUTTON_PIN, PI_INPUT) != 0 ||
        gpioSetMode(DOWN_BUTTON_PIN, PI_INPUT) != 0 ||
        gpioSetMode(LEFT_BUTTON_PIN, PI_INPUT) != 0 ||
        gpioSetMode(RIGHT_BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(UP_BUTTON_PIN, PI_PUD_UP) != 0 ||
        gpioSetPullUpDown(DOWN_BUTTON_PIN, PI_PUD_UP) != 0 ||
        gpioSetPullUpDown(LEFT_BUTTON_PIN, PI_PUD_UP) != 0 ||
        gpioSetPullUpDown(RIGHT_BUTTON_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PAN_SERVO_PIN, 50) != 0 ||
        gpioSetPWMfrequency(TILT_SERVO_PIN, 50) != 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PAN_SERVO_PIN, 2000) != 0 ||
        gpioSetPWMrange(TILT_SERVO_PIN, 2000) != 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Pan-Tilt Servo Control Program\n");
    printf("Press UP to move up, DOWN to move down, LEFT to move left, RIGHT to move right.\n");
    printf("Press Ctrl+C to exit.\n");
    printf("Center position: %d us\n", CENTER_PULSE_WIDTH);
    fflush(stdout);

    int pan_pulse = CENTER_PULSE_WIDTH;
    int tilt_pulse = CENTER_PULSE_WIDTH;

    while (running) {
        int up_val = gpioRead(UP_BUTTON_PIN);
        int down_val = gpioRead(DOWN_BUTTON_PIN);
        int left_val = gpioRead(LEFT_BUTTON_PIN);
        int right_val = gpioRead(RIGHT_BUTTON_PIN);

        if (up_val < 0 || down_val < 0 || left_val < 0 || right_val < 0) {
            fprintf(stderr, "Error: gpioRead failed\n");
            break;
        }

        if (up_val == 0) pan_pulse += PULSE_INCREMENT;
        if (down_val == 0) pan_pulse -= PULSE_INCREMENT;
        if (left_val == 0) tilt_pulse += PULSE_INCREMENT;
        if (right_val == 0) tilt_pulse -= PULSE_INCREMENT;

        if (pan_pulse < MIN_PULSE_WIDTH) pan_pulse = MIN_PULSE_WIDTH;
        if (pan_pulse > MAX_PULSE_WIDTH) pan_pulse = MAX_PULSE_WIDTH;
        if (tilt_pulse < MIN_PULSE_WIDTH) tilt_pulse = MIN_PULSE_WIDTH;
        if (tilt_pulse > MAX_PULSE_WIDTH) tilt_pulse = MAX_PULSE_WIDTH;

        if (set_servo_pulse(PAN_SERVO_PIN, pan_pulse) != 0) {
            fprintf(stderr, "Error: failed to set pan servo\n");
            break;
        }
        if (set_servo_pulse(TILT_SERVO_PIN, tilt_pulse) != 0) {
            fprintf(stderr, "Error: failed to set tilt servo\n");
            break;
        }

        gpioDelay(LOOP_DELAY_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

