#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <gpiod.h>

#define PIR_PIN          17
#define DEBOUNCE_MS      2000
#define POLL_INTERVAL_MS 100
#define IMAGE_QUALITY    85
#define UPLOAD_ENDPOINT  "http://"
#define UPLOAD_PATH      "/upload"
#define MOTION_DIR       "motion_captures"
#define MAX_FILENAME     256
#define MAX_PATH         512
#define MAX_PAYLOAD      4096

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int ensure_directory(const char *path)
{
    struct stat st;
    if (stat(path, &st) == 0) {
        if (S_ISDIR(st.st_mode))
            return 0;
        fprintf(stderr, "Error: '%s' exists but is not a directory\n", path);
        return -1;
    }
    if (errno != ENOENT) {
        fprintf(stderr, "stat('%s') failed: %s\n", path, strerror(errno));
        return -1;
    }
    if (mkdir(path, 0755) == -1) {
        if (errno == EEXIST) {
            fprintf(stderr, "Warning: '%s' already exists; not creating.\n", path);
        } else {
            fprintf(stderr, "mkdir('%s') failed: %s\n", path, strerror(errno));
            return -1;
        }
    }
    return 0;
}

static int capture_image(const char *filename)
{
    char command[MAX_PATH];
    int ret = snprintf(command, sizeof(command),
                       "raspistill -n -o '%s' -q %d 2>/dev/null",
                       filename, IMAGE_QUALITY);
    if (ret < 0 || (size_t)ret >= sizeof(command)) {
        fprintf(stderr, "Error: image filename too long\n");
        return -1;
    }

    int status = system(command);
    if (status == -1) {
        fprintf(stderr, "system() failed: %s\n", strerror(errno));
        return -1;
    }
    if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
        fprintf(stderr, "raspistill failed (status=0x%04x)\n", status);
        return -1;
    }
    return 0;
}

static int upload_image(const char *filename, const char *timestamp,
                        int motion, int pin)
{
    char payload[MAX_PAYLOAD];
    int ret = snprintf(payload, sizeof(payload),
                       "{\"filename\":\"%s\",\"timestamp\":\"%s\",\"motion\":%d,\"pin\":%d}",
                       filename, timestamp, motion, pin);
    if (ret < 0 || (size_t)ret >= sizeof(payload)) {
        fprintf(stderr, "Error: payload too long\n");
        return -1;
    }

    char request[MAX_PATH];
    int req_len = snprintf(request, sizeof(request),
                           "POST %s HTTP/1.1\r\n"
                           "Host: %s:%d\r\n"
                           "Content-Type: application/json\r\n"
                           "Content-Length: %d\r\n"
                           "Connection: close\r\n"
                           "\r\n"
                           "%s",
                           UPLOAD_PATH, UPLOAD_ENDPOINT, 80, req_len, payload);
    if (req_len < 0 || (size_t)req_len >= sizeof(request)) {
        fprintf(stderr, "Error: request buffer too small\n");
        return -1;
    }

    int fd = socket(AF_INET, SOCK_STREAM, 0);
    if (fd == -1) {
        perror("socket()");
        return -1;
    }

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons(80);
    if (inet_pton(AF_INET, UPLOAD_ENDPOINT, &addr.sin_addr) <= 0) {
        fprintf(stderr, "inet_pton() failed for %s\n", UPLOAD_ENDPOINT);
        close(fd);
        return -1;
    }

    if (connect(fd, (struct sockaddr *)&addr, sizeof(addr)) == -1) {
        perror("connect()");
        close(fd);
        return -1;
    }

    ssize_t sent = 0;
    while (sent < req_len) {
        ssize_t n = write(fd, request + sent, req_len - sent);
        if (n == -1) {
            if (errno == EINTR) continue;
            perror("write()");
            close(fd);
            return -1;
        }
        sent += n;
    }

    char resp[MAX_PATH];
    ssize_t r = read(fd, resp, sizeof(resp) - 1);
    if (r > 0) {
        resp[r] = '\0';
        if (strstr(resp, "HTTP/1.") == NULL) {
            fprintf(stderr, "Server did not respond with HTTP\n");
            close(fd);
            return -1;
        }
    } else if (r == -1 && errno != EINTR) {
        perror("read()");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

int main(int argc, char *argv[])
{
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <IP> <port>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *ip = argv[1];
    int port = atoi(argv[2]);
    if (port <= 0 || port > 65535) {
        fprintf(stderr, "Invalid port: %s\n", argv[2]);
        return EXIT_FAILURE;
    }

    if (install_signal_handlers() == -1) {
        return EXIT_FAILURE;
    }

    if (ensure_directory(MOTION_DIR) == -1) {
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name(\"gpiochip0\")");
        return EXIT_FAILURE;
    }

    struct gpiod_line *pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        perror("gpiod_chip_get_line(17)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input_flags(pir_line, "pir_monitor",
                                       GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_DOWN) < 0) {
        perror("gpiod_line_request_input_flags");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    struct gpiod_line_event event;
    struct timespec ts = { 0, POLL_INTERVAL_MS * 1000000L };
    int last_motion = 0;

    while (g_running) {
        int rv = gpiod_line_event_wait(pir_line, &ts);
        if (rv < 0) {
            if (errno == EINTR) continue;
            perror("gpiod_line_event_wait");
            break;
        }
        if (rv == 0) continue;

        if (gpiod_line_event_read(pir_line, &event) < 0) {
            if (errno == EINTR) continue;
            perror("gpiod_line_event_read");
            break;
        }

        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            int motion = gpiod_line_get_value(pir_line);
            if (motion < 0) {
                perror("gpiod_line_get_value");
                continue;
            }
            if (motion == 1 && last_motion == 0) {
                last_motion = 1;
                struct timespec ts_now;
                clock_gettime(CLOCK_REALTIME, &ts_now);
                char timestamp[MAX_PATH];
                struct tm tm_info;
                localtime_r(&ts_now.tv_sec, &tm_info);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);
                snprintf(timestamp + strlen(timestamp),
                         sizeof(timestamp) - strlen(timestamp),
                         ".%06ldZ", ts_now.tv_nsec / 1000);
                char filename[MAX_PATH];
                snprintf(filename, sizeof(filename), "%s/motion_%s.jpg", MOTION_DIR, timestamp);

                if (capture_image(filename) == 0) {
                    char payload[MAX_PAYLOAD];
                    snprintf(payload, sizeof(payload),
                             "{\"filename\":\"%s\",\"timestamp\":\"%s\",\"motion\":%d,\"pin\":%d}",
                             filename, timestamp, 1, PIR_PIN);
                    if (upload_image(filename, timestamp, 1, PIR_PIN) == 0) {
                        printf("Motion detected and uploaded: %s\n", filename);
                    } else {
                        fprintf(stderr, "Error: failed to upload image\n");
                    }
                } else {
                    fprintf(stderr, "Error: failed to capture image\n");
                }
            }
        }
        last_motion = 0;
    }

    gpiod_line_release(pir_line);
    gpiod_chip_close(chip);
    printf("Program terminated cleanly.\n");
    return EXIT_SUCCESS;
}

