    addr.sin_family = AF_INET;
    addr.sin_port = htons(80);
    if (inet_pton(AF_INET, UPLOAD_ENDPOINT, &addr.sin_addr) <= 0) {
        fprintf(stderr, "inet_pton() failed for %s\n", UPLOAD_ENDPOINT);
        close(fd);
        return -1;
    }

    if (connect(fd, (struct sockaddr *)&addr, sizeof(addr)) == -1) {
        perror("connect()");
        close(fd);
        return -1;
    }

    ssize_t sent = 0;
    while (sent < req_len) {
        ssize_t n = write(fd, request + sent, req_len - sent);
        if (n == -1) {
            if (errno == EINTR) continue;
            perror("write()");
            close(fd);
            return -1;
        }
        sent += n;
    }

    char resp[MAX_PATH];
    ssize_t r = read(fd, resp, sizeof(resp) - 1);
    if (r > 0) {
        resp[r] = '\0';
        if (strstr(resp, "HTTP/1.") == NULL) {
            fprintf(stderr, "Server did not respond with HTTP\n");
            close(fd);
            return -1;
        }
    } else if (r == -1 && errno != EINTR) {
        perror("read()");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

int main(int argc, char *argv[])
{
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <IP> <port>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *ip = argv[1];
    int port = atoi(argv[2]);
    if (port <= 0 || port > 65535) {
        fprintf(stderr, "Invalid port: %s\n", argv[2]);
        return EXIT_FAILURE;
    }

    if (install_signal_handlers() == -1) {
        return EXIT_FAILURE;
    }

    if (ensure_directory(MOTION_DIR) == -1) {
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name(\"gpiochip0\")");
        return EXIT_FAILURE;
    }

    struct gpiod_line *pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        perror("gpiod_chip_get_line(17)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input_flags(pir_line, "pir_monitor",
                                       GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_DOWN) < 0) {
        perror("gpiod_line_request_input_flags");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    struct gpiod_line_event event;
    struct timespec ts = { 0, POLL_INTERVAL_MS * 1000000L };
    int last_motion = 0;

    while (g_running) {
        int rv = gpiod_line_event_wait(pir_line, &ts);
        if (rv < 0) {
            if (errno == EINTR) continue;
            perror("gpiod_line_event_wait");
            break;
        }
        if (rv == 0) continue;

        if (gpiod_line_event_read(pir_line, &event) < 0) {
            if (errno == EINTR) continue;
            perror("gpiod_line_event_read");
            break;
        }

        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            int motion = gpiod_line_get_value(pir_line);
            if (motion < 0) {
                perror("gpiod_line_get_value");
                continue;
            }
            if (motion == 1 && last_motion == 0) {
                last_motion = 1;
                struct timespec ts_now;
                clock_gettime(CLOCK_REALTIME, &ts_now);
                char timestamp[MAX_PATH];
                struct tm tm_info;
                localtime_r(&ts_now.tv_sec, &tm_info);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);
                snprintf(timestamp + strlen(timestamp),
                         sizeof(timestamp) - strlen(timestamp),
                         ".%06ldZ", ts_now.tv_nsec / 1000);
                char filename[MAX_PATH];
                snprintf(filename, sizeof(filename), "%s/motion_%s.jpg", MOTION_DIR, timestamp);

                if (capture_image(filename) == 0) {
                    char payload[MAX_PAYLOAD];
                    snprintf(payload, sizeof(payload),
                             "{\"filename\":\"%s\",\"timestamp\":\"%s\",\"motion\":%d,\"pin\":%d}",
                             filename, timestamp, 1, PIR_PIN);
                    if (upload_image(filename, timestamp, 1, PIR_PIN) == 0) {
                        printf("Motion detected and uploaded: %s\n", filename);
                    } else {
                        fprintf(stderr, "Error: failed to upload image\n");
                    }
                } else {
                    fprintf(stderr, "Error: failed to capture image\n");
                }
            }
        }
        last_motion = 0;
    }

    gpiod_line_release(pir_line);
    gpiod_chip_close(chip);
    printf("Program terminated cleanly.\n");
    return EXIT_SUCCESS;
}

