#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>

#define VIDEO_DEVICE "/dev/video0"
#define WIDTH 200
#define HEIGHT 150
#define NUM_FRAMES 1
#define TIMEOUT_SEC 2

static volatile sig_atomic_t g_stop = 0;

static void sig_handler(int signo) {
    (void)signo;
    g_stop = 1;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int init_camera(int *fd) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    unsigned int pix_fmt = V4L2_PIX_FMT_YUYV;
    int fd_used = 0;

    if (xioctl(*fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("VIDIOC_QUERYCAP");
        return -1;
    }
    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        return -1;
    }
    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming I/O\n");
        return -1;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = pix_fmt;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(*fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("VIDIOC_S_FMT");
        return -1;
    }
    if (fmt.fmt.pix.pixelformat != pix_fmt) {
        fprintf(stderr, "Device did not accept YUYV format\n");
        return -1;
    }

    memset(&req, 0, sizeof(req));
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(*fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("VIDIOC_REQBUFS");
        return -1;
    }
    if (req.count < 1) {
        fprintf(stderr, "Insufficient buffer memory\n");
        return -1;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (xioctl(*fd, VIDIOC_QUERYBUF, &buf) < 0) {
        perror("VIDIOC_QUERYBUF");
        return -1;
    }

    if (buf.length < WIDTH * HEIGHT * 2) {
        fprintf(stderr, "Insufficient buffer size\n");
        return -1;
    }

    if (xioctl(*fd, VIDIOC_STREAMON, &buf) < 0) {
        perror("VIDIOC_STREAMON");
        return -1;
    }
    fd_used = 1;
    return 0;
}

static int capture_frame(int fd, unsigned char *buffer, int *width, int *height) {
    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);
    tv.tv_sec = TIMEOUT_SEC;
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);
    if (r == -1) {
        if (errno == EINTR) return -1;
        perror("select");
        return -1;
    }
    if (r == 0) {
        fprintf(stderr, "Timeout waiting for frame\n");
        return -1;
    }

    if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("VIDIOC_DQBUF");
        return -1;
    }

    if (buf.bytesused < WIDTH * HEIGHT * 2) {
        fprintf(stderr, "Short frame (%d bytes)\n", buf.bytesused);
        return -1;
    }

    memcpy(buffer, buf.base, buf.bytesused);
    *width = WIDTH;
    *height = HEIGHT;
    return 0;
}

static int write_yuv(const unsigned char *yuv, int w, int h, const char *fn) {
    FILE *fp = fopen(fn, "wb");
    if (!fp) {
        perror("fopen");
        return -1;
    }
    size_t off = 0;
    for (int i = 0; i < NUM_FRAMES; i++) {
        if (g_stop) goto cleanup;
        off += w * h * 2;
    }
    if (off != w * h * 2) {
        fprintf(stderr, "Short frame count: %zu != %d\n", off, w * h * 2);
        goto cleanup;
    }
    size_t written = fwrite(yuv + i * w * h, 1, w * h, fp);
    if (written != (size_t)(w * h)) {
        fprintf(stderr, "fwrite failed: %s\n", strerror(errno));
        goto cleanup;
    }
    if (fflush(fp) != 0) {
        perror("fflush");
        goto cleanup;
    }
    return 0;

cleanup:
    if (fflush(fp) != 0) perror("fflush");
    if (fclose(fp) != 0) perror("fclose");
    return -1;
}

int main(void) {
    int fd = -1;
    unsigned char *buffer = NULL;
    int w = WIDTH, h = HEIGHT;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction SIGINT");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction SIGTERM");
        return EXIT_FAILURE;
    }

    fd = open(VIDEO_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("open");
        return EXIT_FAILURE;
    }

    if (init_camera(&fd) < 0) {
        goto cleanup;
    }

    buffer = (unsigned char *)mmap(NULL, buf.bytesused, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        perror("mmap");
        goto cleanup;
    }

    if (write_yuv(buffer, w, h, "cropped.yuv") < 0) {
        goto cleanup;
    }
    rc = EXIT_SUCCESS;

cleanup:
    if (fd_used) {
        xioctl(fd, VIDIOC_STREAMOFF, &buf);
        munmap(buffer, buf.bytesused);
    }
    if (fd >= 0) close(fd);
    return rc;
}

