#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <time.h>
#include <stdbool.h>
#include <pigpio.h>

#define PAN_SERVO_PIN 17
#define TILT_SERVO_PIN 18
#define PWM_FREQUENCY 50
#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500
#define SERVO_NEUTRAL_ANGLE 90
#define SERVO_NEUTRAL_PULSE_WIDTH (SERVO_MIN_PULSE_WIDTH + (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH) / 2)
#define STEP_ANGLE 5
#define DELAY_MS 100
#define MAX_ANGLE 180
#define MIN_ANGLE 0

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_servo_angle(int pin, int angle) {
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Error: Angle %d out of range [%d, %d]\n", angle, MIN_ANGLE, MAX_ANGLE);
        return -1;
    }
    int pulse_width = SERVO_MIN_PULSE_WIDTH +
        (int)((float)angle / MAX_ANGLE * (float)(SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH));
    if (gpioServo(pin, pulse_width) < 0) {
        fprintf(stderr, "Error: gpioServo failed on pin %d (pulse %d)\n", pin, pulse_width);
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    gpioServo(PAN_SERVO_PIN, SERVO_NEUTRAL_PULSE_WIDTH);
    gpioServo(TILT_SERVO_PIN, SERVO_NEUTRAL_PULSE_WIDTH);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
