/*
 * Raspberry Pi 4 Model B – CPU temp + CPU usage on SSD1306 128×64 OLED
 *
 * Build:  gcc -O2 -Wall -Wextra -o oled_cpu oled_cpu.c -lpigpio -lrt
 * Run:    sudo ./oled_cpu
 *
 * Hardware:
 *   SSD1306 on I2C bus 1 (GPIO2=SDA, GPIO3=SCL), 3.3 V logic.
 *   /sys/class/thermal/thermal_zone0/temp  → CPU temperature °C
 *   /proc/stat                               → CPU usage percentage
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

/* ---- Configuration ---------------------------------------------------- */
#define I2C_BUS        1
#define OLED_WIDTH     128
#define OLED_HEIGHT    64
#define OLED_PAGES     (OLED_HEIGHT / 8)   /* 8 rows per page */

#define TEMP_FILE      "/sys/class/thermal/thermal_zone0/temp"
#define STAT_FILE      "/proc/stat"

#define OLED_BUFFER_SIZE (OLED_WIDTH * OLED_PAGES)

/* ---- Globals ---------------------------------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ---- Signal handler ---------------------------------------------------- */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Helpers ----------------------------------------------------------- */
static int read_cpu_temp(void)
{
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", TEMP_FILE, strerror(errno));
        return -1;
    }

    char buf[16];
    if (fgets(buf, sizeof(buf), fp) == NULL) {
        fprintf(stderr, "Error reading %s: %s\n", TEMP_FILE, strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);

    char *endptr = NULL;
    long millideg = strtol(buf, &endptr, 10);
    if (endptr == buf || *endptr != '\n' && *endptr != '\0') {
        fprintf(stderr, "Error parsing temperature: '%s'\n", buf);
        return -1;
    }

    return (int)(millideg / 1000);   /* °C */
}

static int read_cpu_usage(void)
{
    FILE *fp = fopen(STAT_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", STAT_FILE, strerror(errno));
        return -1;
    }

    char line[256];
    if (!fgets(line, sizeof(line), fp)) {
        fprintf(stderr, "Error reading %s: %s\n", STAT_FILE, strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);

    /* Strip trailing whitespace */
    size_t len = strlen(line);
    while (len > 0 && (line[len - 1] == ' ' || line[len - 1] == '\t')) {
        line[--len] = '\0';
    }

    /* Parse CPU usage percentage (user + nice + system) */
    char *start = line;
    while (*start == ' ' || *start == '\t') start++;

    char *endptr = NULL;
    long total = strtol(start, &endptr, 10);
    if (endptr == start || *endptr != '\0' || total <= 0) {
        fprintf(stderr, "Error parsing CPU usage: '%s'\n", line);
        return -1;
    }

    /* Sleep time is the remaining bytes */
    char *sleep_start = endptr + 1;
    while (*sleep_start == ' ' || *sleep_start == '\t') sleep_start++;

    char *sleep_end = NULL;
    long sleep_us = strtol(sleep_start, &sleep_end, 10);
    if (sleep_end == sleep_start || sleep_us <= 0) {
        fprintf(stderr, "Error parsing sleep time: '%s'\n", line);
        return -1;
    }

    /* 100 - (sleep_us / total_us) * 100 = percentage of time not spent sleeping */
    long total_us = (long)sleep_us + total;
    if (total_us == 0) return 0;
    long sleep_pct = (long)sleep_us / total_us * 100;
    long idle_pct = 100 - sleep_pct;
    return (int)idle_pct;   /* percentage */
}

/* ---- SSD1306 primitives ------------------------------------------------ */
static int oled_init(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, 0x3C90, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x3C90: %s\n",
                I2C_BUS, strerror(errno));
        g_i2c_handle = -1;
        return -1;
    }

    /* Set display resolution to 128×64 */
    if (i2cWriteByte(g_i2c_handle, 0x20) < 0) {
        fprintf(stderr, "Error setting OLED page size\n");
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }

    /* Set display to normal (not inverted) */
    if (i2cWriteByte(g_i2c_handle, 0x81) < 0) {
        fprintf(stderr, "Error setting OLED display mode\n");
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }

    /* Set contrast (0x7F = max contrast) */
    if (i2cWriteByte(g_i2c_handle, 0x81) < 0) {
        fprintf(stderr, "Error setting OLED contrast\n");
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }

    return 0;
}

static int oled_clear(void)
{
