#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>

#define ANEMOMETER_GPIO 17
#define SPI_DEVICE "/dev/spidev0.0"
#define I2C_DEVICE "/dev/i2c-1"
#define LCD_WIDTH 16
#define LCD_CHR 1
#define LCD_CMD 0
#define SPI_SPEED_HZ 1000000
#define SPI_MODE 0
#define SPI_BITS 8
#define SAMPLE_WINDOW_MS 500
#define ADC_CHANNEL 0
#define ADC_MAX 1023
#define ADC_STUCK_THRESHOLD 5

static volatile sig_atomic_t running = 1;
static volatile uint32_t pulse_count = 0;
static volatile uint32_t sample_start_ms = 0;
static int spi_fd = -1;
static int i2c_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void interrupt_handler(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; (void)level; (void)tick; (void)user;
    pulse_count++;
}

static int init_spi(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd); spi_fd = -1; return -1;
    }
    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(spi_fd); spi_fd = -1; return -1;
    }
    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(spi_fd); spi_fd = -1; return -1;
    }
    return 0;
}

static int init_i2c(void) {
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device %s: %s\n", I2C_DEVICE, strerror(errno));
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, 0x27) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x27: %s\n", strerror(errno));
        close(i2c_fd); i2c_fd = -1; return -1;
    }
    return 0;
}

static int lcd_send_nibble(uint8_t nibble) {
    uint8_t data = (nibble & 0xF0) | LCD_CHR;
    if (write(i2c_fd, &data, 1) != 1) {
        fprintf(stderr, "I2C write error for nibble 0x%02X: %s\n", nibble, strerror(errno));
        return -1;
    }
    return 0;
}

static int lcd_send_command(uint8_t cmd) {
    uint8_t data = (cmd & 0xF0) | LCD_CMD;
    if (write(i2c_fd, &data, 1) != 1) {
        fprintf(stderr, "I2C write error for command 0x%02X: %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int lcd_send_data(uint8_t data) {
    uint8_t data_high = (data & 0xF0) | LCD_CHR;
    uint8_t data_low = ((data << 4) & 0xF0) | LCD_CHR;
    if (write(i2c_fd, &data_high, 1) != 1) {
        fprintf(stderr, "I2C write error for data high 0x%02X: %s\n", data_high, strerror(errno));
        return -1;
    }
    if (write(i2c_fd, &data_low, 1) != 1) {
        fprintf(stderr, "I2C write error for data low 0x%02X: %s\n", data_low, strerror(errno));
        return -1;
    }
    return 0;
}

static int lcd_clear(void) {
    lcd_send_nibble(0x80);
    lcd_send_nibble(0x00);
    lcd_send_nibble(0x00);
    lcd_send_nibble(0x00);
    return 0;
}

static int lcd_init(void) {
    lcd_send_nibble(0x30);
    lcd_send_nibble(0x30);
    lcd_send_nibble(0x30);
    lcd_send_nibble(0x20);
    lcd_send_command(0x28);
    lcd_send_command(0x0C);
    lcd_send_command(0x06);
    lcd_send_command(0x01);
    lcd_send_command(0x02);
    lcd_send_command(0x0C);
    lcd_send_command(0x0C);
    lcd_send_nibble(0x03);
    lcd_send_nibble(0x03);
    lcd_send_nibble(0x03);
    lcd_send_nibble(0x03);
    return 0;
}

static int read_wind_direction(void) {
    uint8_t tx[3] = {0x01, (uint8_t)(0x80 | (ADC_CHANNEL << 4)), 0x00};
    uint8_t rx[3] = {0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer error for wind direction: %s\n", strerror(errno));
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int calculate_wind_speed(uint32_t pulses, uint32_t window_ms) {
    if (window_ms == 0) return 0;
    double wind_speed = (double)pulses / (double)window_ms * 100.0;
    if (wind_speed < 0.0) wind_speed = 0.0;
    if (wind_speed > 100.0) wind_speed = 100.0;
    return (int)wind_speed;
}

static void display_data(int wind_speed, int wind_direction) {
    lcd_clear();
    lcd_send_nibble(0x80);
    lcd_send_nibble(0x00);
    lcd_send_nibble(0x00);
    lcd_send_nibble(0x00);
    lcd_send_command(0x28);
    lcd_send_command(0x0C);
    lcd_send_command(0x06);
    lcd_send_command(0x01);
    lcd_send_command(0x02);
    lcd_send_command(0x0C);
    lcd_send_command(0x0C);
    lcd_send_nibble(0x03);
    lcd_send_nibble(0x03);
    lcd_send_nibble(0x03);
    lcd_send_nibble(0x03);
    lcd_send_data(wind_speed);
    lcd_send_data(wind_direction);
}

static void cleanup(void) {
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (init_spi() < 0) return 1;
    if (init_i2c() < 0) {
        cleanup();
        return 1;
    }

    if (lcd_init() < 0) {
        fprintf(stderr, "LCD initialization failed\n");
        cleanup();
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED_HZ) < 0) {
        fprintf(stderr, "SPI configuration failed\n");
        cleanup();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, 0x27) < 0) {
        fprintf(stderr, "I2C slave address 0x27 not detected\n");
        cleanup();
        return 1;
    }

    if (lcd_clear() < 0) {
        fprintf(stderr, "LCD initialization failed\n");
        cleanup();
        return 1;
    }

    struct timespec start, now;
    clock_gettime(CLOCK_MONOTONIC, &start);
    sample_start_ms = start.tv_sec * 1000 + start.tv_nsec / 1000000;

    while (running) {
        if (pulse_count == 0) {
            pulse_count = 1;
            sample_start_ms = start.tv_sec * 1000 + start.tv_nsec / 1000000;
        }

        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);
        uint32_t elapsed_ms = (ts.tv_sec - start.tv_sec) * 1000 + (ts.tv_nsec - start.tv_nsec) / 1000000;
        if (elapsed_ms >= SAMPLE_WINDOW_MS) {
            int wind_speed = calculate_wind_speed(pulse_count, SAMPLE_WINDOW_MS);
            int wind_direction = read_wind_direction();
            if (wind_direction < 0) {
                fprintf(stderr, "Error reading wind direction\n");
            } else {
                display_data(wind_speed, wind_direction);
            }
            pulse_count = 0;
            sample_start_ms = start.tv_sec * 1000 + start.tv_nsec / 1000000;
        }
    }

    lcd_clear();
    lcd_send_nibble(0x00);
    lcd_send_nibble(0x00);
    lcd_send_nibble(0x00);
    lcd_send_nibble(0x00);
    lcd_send_command(0x28);
    lcd_send_command(0x0C);
    lcd_send_command(0x06);
    lcd_send_command(0x01);
    lcd_send_command(0x02);
    lcd_send_command(0x0C);
    lcd_send_command(0x0C);
    lcd_send_nibble(0x03);
    lcd_send_nibble(0x03);
    lcd_send_nibble(0x03);
    lcd_send_nibble(0x03);
