#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define ROWS 8
#define COLS 8
#define DELAY_US 800

static const int row_pins[ROWS] = {17, 18, 27, 22, 23, 24, 25, 4};
static const int col_pins[COLS] = {5, 6, 12, 13, 19, 16, 26, 20};

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static void set_row(int row, int state) {
    if (gpioWrite(row_pins[row], state) != 0) {
        fprintf(stderr, "Error: gpioWrite failed on row pin %d\n", row_pins[row]);
        exit(EXIT_FAILURE);
    }
}

static void set_col(int col, int state) {
    if (gpioWrite(col_pins[col], state) != 0) {
        fprintf(stderr, "Error: gpioWrite failed on column pin %d\n", col_pins[col]);
        exit(EXIT_FAILURE);
    }
}

static void clear_matrix(void) {
    for (int r = 0; r < ROWS; r++) {
        set_row(r, 0);
    }
    for (int c = 0; c < COLS; c++) {
        set_col(c, 0);
    }
}

static void draw_char(int col, int row, int char_index) {
    if (char_index < 0 || char_index >= (int)sizeof(led_font[0])) {
        fprintf(stderr, "Error: Invalid character index %d\n", char_index);
        return;
    }
    for (int i = 0; i < 8; i++) {
        int bit = (led_font[char_index][i] >> 7) & 1;
        set_row(row + i, bit);
        set_col(col + i, 1);
    }
}

static void draw_matrix(void) {
    clear_matrix();
    for (int r = 0; r < ROWS; r++) {
        for (int c = 0; c < COLS; c++) {
            int char_index = (r * COLS + c) % (int)sizeof(led_font[0]);
            draw_char(c, r, char_index);
        }
    }
}

static void shift_left(void) {
    for (int i = 0; i < COLS; i++) {
        int c = i;
        while (c > 0 && running) {
            draw_char(c, 0, 0);
            c--;
        }
    }
}

static void shift_right(void) {
    for (int i = COLS - 1; i >= 0 && running; i--) {
        draw_char(i, 0, 0);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < ROWS; i++) {
        if (gpioSetMode(row_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode failed for row pin %d\n", row_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < COLS; i++) {
        if (gpioSetMode(col_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode failed for column pin %d\n", col_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction failed for SIGINT\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        draw_matrix();
        shift_left();
        shift_right();
        gpioDelay(DELAY_US);
    }

    clear_matrix();
    gpioTerminate();
    return EXIT_SUCCESS;
}

