#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_ROWS 8
#define NUM_COLS 8
#define DELAY_MS 150

static const unsigned int row_pins[NUM_ROWS] = {2, 3, 4, 17, 27, 22, 10, 9};
static const unsigned int col_pins[NUM_COLS] = {14, 15, 18, 23, 24, 25, 8, 7};

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *row_lines[NUM_ROWS];
static struct gpiod_line *col_lines[NUM_COLS];

static void cleanup(void) {
    for (int i = 0; i < NUM_ROWS; i++) {
        if (row_lines[i]) {
            gpiod_line_release(row_lines[i]);
            row_lines[i] = NULL;
        }
    }
    for (int i = 0; i < NUM_COLS; i++) {
        if (col_lines[i]) {
            gpiod_line_release(col_lines[i]);
            col_lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

static void sig_handler(int sig) {
    (void)sig;
    cleanup();
    exit(0);
}

static int set_all(struct gpiod_line **lines, int val) {
    for (int i = 0; i < NUM_ROWS; i++) {
        if (gpiod_line_set_value(lines[i], val) < 0) {
            fprintf(stderr, "Failed to set row %d\n", i);
            return -1;
        }
    }
    for (int i = 0; i < NUM_COLS; i++) {
        if (gpiod_line_set_value(lines[i], val) < 0) {
            fprintf(stderr, "Failed to set col %d\n", i);
            return -1;
        }
    }
    return 0;
}

static int light_row(int row) {
    if (gpiod_line_set_value(row_lines[row], 1) < 0) {
        fprintf(stderr, "Failed to set row %d HIGH\n", row);
        return -1;
    }
    return 0;
}

static int clear_matrix(void) {
    if (set_all(col_lines, 1) < 0) return -1;
    if (set_all(row_lines, 0) < 0) return -1;
    return 0;
}

static int run_animation(void) {
    for (int col = 0; col < NUM_COLS; col++) {
        if (clear_matrix() < 0) return -1;
        for (int r = 0; r < NUM_ROWS; r++) {
            if (light_row(r) < 0) return -1;
        }
        usleep(DELAY_MS * 1000);
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    for (int i = 0; i < NUM_ROWS; i++) {
        row_lines[i] = gpiod_chip_get_line(chip, row_pins[i]);
        if (!row_lines[i]) {
            fprintf(stderr, "Failed to get row line %d\n", row_pins[i]);
            cleanup();
            return 1;
        }
        if (gpiod_line_request_output(row_lines[i], "led_matrix", 0) < 0) {
            fprintf(stderr, "Failed to request row line %d as output\n", row_pins[i]);
            cleanup();
            return 1;
        }
    }

    for (int i = 0; i < NUM_COLS; i++) {
        col_lines[i] = gpiod_chip_get_line(chip, col_pins[i]);
        if (!col_lines[i]) {
            fprintf(stderr, "Failed to get col line %d\n", col_pins[i]);
            cleanup();
            return 1;
        }
        if (gpiod_line_request_output(col_lines[i], "led_matrix", 1) < 0) {
            fprintf(stderr, "Failed to request col line %d as output\n", col_pins[i]);
            cleanup();
            return 1;
        }
    }

    while (1) {
        if (run_animation() < 0) {
            fprintf(stderr, "Animation failed, exiting\n");
            cleanup();
            return 1;
        }
    }

    cleanup();
    return 0;
}

