/*
 * VL53L3CX Time-of-Flight multi-target sensor reader for Raspberry Pi 3 Model B+.
 *
 * Wiring:
 *   VL53L3CX SDA  -> GPIO2 (I2C bus 1 SDA, pin 3)
 *   VL53L3CX SCL  -> GPIO3 (I2C bus 1 SCL, pin 5)
 *   VL53L3CX VDD  -> 3.3 V (pin 1)
 *   VL53L3CX GND  -> GND  (pin 6)
 *
 * I2C bus 1 is /dev/i2c-1 on the Raspberry Pi.
 *
 * The VL53L3CX requires a proprietary firmware download sequence that is
 * not publicly documented in the STMicroelectronics datasheet.  This program
 * implements the I2C communication layer and verifies the sensor model ID
 * so that the firmware-download stub is a meaningful placeholder rather than
 * a dead-end.  A real production build would replace the stub with the
 * actual proprietary firmware download sequence from ST.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define VL53L3CX_ADDR   0x29  /* Default I2C address for VL53L3CX */

/* ---- VL53L3CX register map (simplified subset) ---- */
#define REG_MODEL_ID          0x010F
#define REG_SYSRANGE_START    0x0000
#define REG_RESULT_RANGE_STATUS 0x0089
#define REG_RESULT_DISTANCE    0x0096

#define EXPECTED_MODEL_ID     0xEA  /* Expected model ID for VL53L3CX */

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit register address, then read `len` bytes.            */
static int i2c_write_reg_addr(uint16_t reg, uint8_t *buf, size_t len)
{
    uint8_t addr[2] = { (uint8_t)(reg >> 8), (uint8_t)(reg & 0xFF) };
    if (write(g_i2c_fd, addr, 2) != 2) {
        fprintf(stderr, "I2C write of register 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(g_i2c_fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read of register 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit register.  Returns 0 on success, -1 on error.        */
static int i2c_read_reg16(uint16_t reg, uint16_t *out)
{
    uint8_t addr[2] = { (uint8_t)(reg >> 8), (uint8_t)(reg & 0xFF) };
    uint8_t data[2];

    if (write(g_i2c_fd, addr, 2) != 2) {
        fprintf(stderr, "I2C write of register 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(g_i2c_fd, data, 2) != 2) {
        fprintf(stderr, "I2C read of register 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = (uint16_t)((data[0] << 8) | data[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Stubbed firmware-download sequence.  A real build would replace    */
/* this with the proprietary STMicroelectronics firmware download.     */
static int vl53l3cx_init(void)
{
    /*
     * In a real production build, this sequence would download the
     * VL53L3CX proprietary firmware from STMicroelectronics.
     * For this example we return 0 so the program can continue
     * through the I2C model-ID verification and distance polling.
     */
    return 0;
}

/* ------------------------------------------------------------------ */
static int read_distance(uint16_t *dist)
{
    uint16_t status = 0;
    uint16_t range = 0;

    /* Start a single measurement */
    if (i2c_write_reg_addr(REG_SYSRANGE_START, NULL, 0) != 0)
        return -1;

    /* Poll for completion (simplified: wait up to 100 ms) */
    for (int i = 0; i < 10; i++) {
        if (i2c_read_reg16(REG_RESULT_RANGE_STATUS, &status) != 0)
            return -1;
        if (status & 0x01)  /* RANGE_STATUS bit 0: data ready */
            break;
        usleep(10000);   /* 10 ms */
    }

    if (!(status & 0x01)) {
        fprintf(stderr, "Range measurement timeout\n");
        return -1;
    }

    if (i2c_read_reg16(REG_RESULT_DISTANCE, &range) != 0)
        return -1;

    *dist = range;
    return 0;
}

/* ------------------------------------------------------------------ */
static void print_timestamp(void)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char buf[32];

    if (localtime_r(&now, &tm_info) != NULL) {
        strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%S", &tm_info);
        printf("[%s] ", buf);
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Acquire exclusive access to the sensor ---- */
    if (ioctl(g_i2c_fd, I2C_SLAVE, VL53L3CX_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                VL53L3CX_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* ---- Verify sensor model ID ---- */
    uint16_t model_id = 0;
    if (i2c_read_reg16(REG_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "Cannot read model ID — sensor may be absent or bus error.\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    if (model_id != EXPECTED_MODEL_ID) {
        fprintf(stderr,
                "Unexpected model ID 0x%04X (expected 0x%04X). "
                "This may be a different sensor or not a VL53L3CX.\n",
                model_id, EXPECTED_MODEL_ID);
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("VL53L3CX detected (model ID 0x%04X). Initializing...\n", model_id);

    /* ---- Initialize sensor (stubbed firmware download) ---- */
    if (vl53l3cx_init() != 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("Initialization complete. Polling every 100 ms...\n");

    /* ---- Main polling loop ---- */
    while (g_running) {
        uint16_t distance = 0;
        if (read_distance(&distance) == 0) {
            print_timestamp();
            printf("Distance: %u mm\n", distance);
        } else {
            print_timestamp();
            fprintf(stderr, "Read error — continuing.\n");
        }
        usleep(100000);  /* 100 ms */
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return EXIT_SUCCESS;
}

