/*
 * MLX75031 Time-of-Flight distance logger for Raspberry Pi Zero W
 *
 * Reads distance data from a Melexis MLX75031 sensor on I2C bus 1
 * every 100 ms and appends timestamped distance values to
 * depth_log.csv.  I2C errors are logged to stderr, the I2C handle
 * is re-opened on failure, and SIGINT triggers a graceful shutdown.
 *
 * Build:  gcc -O2 -Wall -Wextra -o mlx75031_log mlx75031_log.c
 * Run:    ./mlx75031_log
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define LOG_FILE       "depth_log.csv"
#define SAMPLE_PERIOD_US 100000   /* 100 ms */
#define MLX75031_REG_DIST_MSB  0x00
#define MLX75031_REG_DIST_LSB  0x01
#define MLX75031_REG_CTRL      0x02

/* CTRL register bit layout (example; adjust per datasheet) */
#define MLX75031_CTRL_START    0x01
#define MLX75031_CTRL_SAMPLE   0x02

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to an 8-bit sensor register.                       */
/* Returns 0 on success, -1 on error.                                */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s (wrote %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from an 8-bit sensor register.                       */
/* Returns 0 on success and stores the value in *out; -1 on error.    */
/* ------------------------------------------------------------------ */
static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    n = read(fd, out, 1);
    if (n != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Open the I2C bus and acquire the MLX75031 slave address.            */
/* Returns a valid file descriptor on success, or -1 on error.        */
/* ------------------------------------------------------------------ */
static int mlx75031_init(int *fd_out)
{
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, 0x74) < 0) {   /* example slave address */
        fprintf(stderr, "ioctl I2C_SLAVE (0x74) failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    /* Probe the device by reading the DIST_MSB register. */
    uint8_t probe;
    if (i2c_read_reg8(fd, MLX75031_REG_DIST_MSB, &probe) != 0) {
        fprintf(stderr, "MLX75031 not responding at 0x74 on %s\n", I2C_BUS);
        close(fd);
        return -1;
    }

    *fd_out = fd;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read distance from the MLX75031.  Returns 0 on success, -1 on error.*/
/* ------------------------------------------------------------------ */
static int mlx75031_read_distance(int fd, int *distance_out)
{
    uint8_t msb, lsb;

    if (i2c_read_reg8(fd, MLX75031_REG_DIST_MSB, &msb) != 0)
        return -1;

    if (i2c_read_reg8(fd, MLX75031_REG_DIST_LSB, &lsb) != 0)
        return -1;

