#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_PIN 4
#define LED_PIN 17
#define LOG_FILE "proximity.log"
#define POLL_DELAY_US 100000
#define LED_BLINK_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d).\n", gpioInitialise());
        return -1;
    }

    if (gpioSetMode(SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input.\n", SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", LED_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise LED state on GPIO %d.\n", LED_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void log_detection(void) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t rawtime = time(NULL);
    if (rawtime == (time_t)-1) {
        perror("Error getting time");
        fclose(fp);
        return;
    }

    struct tm timeinfo;
    if (gmtime_r(&rawtime, &timeinfo) == NULL) {
        perror("Error converting time");
        fclose(fp);
        return;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &timeinfo) == 0) {
        fprintf(stderr, "Error formatting timestamp.\n");
        fclose(fp);
        return;
    }

    if (fprintf(fp, "%s Object detected\n", timestamp) < 0) {
        perror("Error writing to log file");
    }

    if (fclose(fp) != 0) {
        perror("Error closing log file");
    }
}

static void blink_led(void) {
    if (gpioWrite(LED_PIN, 1) != 0) {
        fprintf(stderr, "Warning: failed to turn LED on.\n");
        return;
    }
    gpioDelay(LED_BLINK_US);
    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Warning: failed to turn LED off.\n");
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error registering SIGINT handler");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error registering SIGTERM handler");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    int prev_state = gpioRead(SENSOR_PIN);
    if (prev_state < 0) {
        fprintf(stderr, "Error: failed to read initial sensor state on GPIO %d.\n", SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Proximity sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int current_state = gpioRead(SENSOR_PIN);
        if (current_state < 0) {
            fprintf(stderr, "Error: failed to read sensor on GPIO %d.\n", SENSOR_PIN);
            break;
        }

        if (current_state == 0 && prev_state == 1) {
            printf("Object detected!\n");
            log_detection();
            blink_led();
        }

        prev_state = current_state;
        gpioDelay(POLL_DELAY_US);
    }

    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

