    if (i2cReadDevice(i2c_handle, data_buf, 1) != 1) {
        fprintf(stderr, "Error reading from register 0x%02X\n", reg);
        return -1;
    }
    *value = (uint8_t)data_buf[0];
    return 0;
}

static int read_reg16(uint8_t reg, uint16_t *value) {
    uint8_t buf[2];
    if (i2cReadI2CBlockData(i2c_handle, reg, (char *)buf, 2) != 2) {
        fprintf(stderr, "Error reading 16-bit from register 0x%02X\n", reg);
        return -1;
    }
    *value = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int init_si1145(void) {
    uint8_t part_id = 0;
    if (read_reg(SI1145_REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Failed to read PART_ID\n");
        return -1;
    }
    if (part_id != 0x45) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x45)\n", part_id);
        return -1;
    }

    /* Hardware key for proper operation */
    if (write_reg(SI1145_REG_HW_KEY, 0x17) != 0) return -1;

    /* Set measurement rates to 1 sample per channel */
    if (write_reg(SI1145_REG_MEAS_RATE0, 0x01) != 0) return -1;
    if (write_reg(SI1145_REG_MEAS_RATE1, 0x01) != 0) return -1;
    if (write_reg(SI1145_REG_ALS_RATE, 0x01) != 0) return -1;
    if (write_reg(SI1145_REG_ALS_IR_RATE, 0x01) != 0) return -1;
    if (write_reg(SI1145_REG_PS_RATE, 0x01) != 0) return -1;
    if (write_reg(SI1145_REG_ALS_VIS_ADCMUX, 0x03) != 0) return -1;
    if (write_reg(SI1145_REG_ALS_VIS_ADC_GAIN, 0x00) != 0) return -1;
    if (write_reg(SI1145_REG_ALS_IR_ADCMUX, 0x03) != 0) return -1;
    if (write_reg(SI1145_REG_ALS_IR_ADC_GAIN, 0x00) != 0) return -1;
    if (write_reg(SI1145_REG_ALS_VIS_DATA0, 0x01) != 0) return -1;
    if (write_reg(SI1145_REG_ALS_VIS_DATA1, 0x00) != 0) return -1;
    if (write_reg(SI1145_REG_ALS_IR_DATA0, 0x01) != 0) return -1;
    if (write_reg(SI1145_REG_ALS_IR_DATA1, 0x00) != 0) return -1;
    if (write_reg(SI1145_REG_PS_DATA0, 0x01) != 0) return -1;
    if (write_reg(SI1145_REG_PS_DATA1, 0x00) != 0) return -1;

    /* Start autonomous measurements */
    if (write_reg(SI1145_REG_COMMAND, SI1145_CMD_PSALS_PS_FORCE) != 0) return -1;

    return 0;
}

static int read_sensor_data(uint16_t *proximity, uint16_t *ambient_light) {
    /* Trigger a forced measurement */
    if (write_reg(SI1145_REG_COMMAND, SI1145_CMD_PSALS_PS_FORCE) != 0) return -1;
    gpioDelay(10000); /* 10 ms delay for measurement */

    /* Read proximity */
    if (read_reg16(SI1145_REG_PS_DATA0, proximity) != 0) return -1;

    /* Read ambient light */
    if (read_reg16(SI1145_REG_ALS_VIS_DATA0, ambient_light) != 0) return -1;

