/*
 * HC-SR04 ultrasonic distance measurement on Raspberry Pi Zero W.
 *
 * Wiring:
 *   HC-SR04 TRIGGER -> GPIO 17 (BCM)
 *   HC-SR04 ECHO    -> GPIO 27 (BCM) via 1k/2k voltage divider (5V->3.3V)
 *   HC-SR04 VCC     -> 5V (external supply recommended)
 *   HC-SR04 GND     -> GND
 *
 * Build:  gcc -O2 -Wall -o hcsr04 hcsr04.c
 */

#define _POSIX_C_SOURCE 200809L

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define TRIGGER_PIN        17
#define ECHO_PIN           27

#define TRIGGER_PULSE_US   10          /* HC-SR04 trigger pulse width          */
#define ECHO_TIMEOUT_US    30000       /* 30 ms max wait for echo               */
#define LOOP_DELAY_US      100000      /* 100 ms between measurements          */
#define LOG_INTERVAL_S     60         /* Log every 60 seconds                */
#define MIN_DISTANCE_CM    2.0f
#define MAX_DISTANCE_CM    400.0f
#define MIN_DISTANCE_MM    (MIN_DISTANCE_CM * 1000.0f)
#define MAX_DISTANCE_MM    (MAX_DISTANCE_CM * 1000.0f)
#define PROXIMITY_THRESHOLD_MM 150.0f

#define LOG_FILE_NAME      "distance_log.txt"

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

/* --------------------------- Signal handling ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- Timestamp helper ----------------------------- */
static void get_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        snprintf(buf, len, "TIMESTAMP_ERROR");
        return;
    }
    struct tm tmv;
    if (localtime_r(&now, &tmv) == NULL) {
        snprintf(buf, len, "TIMESTAMP_ERROR");
        return;
    }
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tmv);
}

/* --------------------------- Echo measurement ----------------------------- */
/*
 * Returns:
 *   > 0  : distance in cm (valid reading)
 *   -1.0 : echo never rose (sensor absent or not responding)
 *   -2.0 : echo stuck high (timeout)
 */
static float measure_distance(void)
{
    uint32_t start_tick = 0, end_tick = 0;
    uint32_t timeout_tick = gpioTick();

    /* --- Issue 10 us trigger pulse --- */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "gpioWrite(TRIGGER, 1) failed\n");
        return -1.0f;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "gpioWrite(TRIGGER, 0) failed\n");
        return -1.0f;
    }

    /* --- Wait for echo rising edge --- */
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_tick) >= ECHO_TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo rising edge\n");
            return -2.0f;
        }
        gpioDelay(10);
    }
    start_tick = gpioTick();

    /* --- Wait for echo falling edge --- */
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - start_tick) >= ECHO_TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo falling edge\n");
            return -2.0f;
        }
        gpioDelay(10);
    }
    end_tick = gpioTick();

    uint32_t pulse_us = end_tick - start_tick;
    float distance = (float)pulse_us * 0.0343f / 2.0f;

    if (distance < MIN_DISTANCE_MM || distance > MAX_DISTANCE_MM) {
        fprintf(stderr, "Distance out of range: %.2f cm\n", distance);
        return -1.0f;
    }

    return distance;
}

/* --------------------------- Logging ------------------------------------- */
static void log_distance(float distance)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));

    if (distance < 0.0f) {
        fprintf(g_log_fp, "%s, ERROR: %s\n", ts,
                distance < 0.0f ? "Sensor read failure" : "Timeout");
    } else {
        fprintf(g_log_fp, "%s, Distance: %.2f cm\n", ts, distance);
    }
    fflush(g_log_fp);
}

/* --------------------------- Main ---------------------------------------- */
int main(void)
{
    /* --- Initialise pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pins --- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(TRIGGER) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode(ECHO) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(1000);

    /* --- Open log file --- */
    g_log_fp = fopen(LOG_FILE_NAME, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE_NAME, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        fclose(g_log_fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        fclose(g_log_fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement started.\n");
    printf("TRIGGER=GPIO%d, ECHO=GPIO%d, Log=%s\n",
           TRIGGER_PIN, ECHO_PIN, LOG_FILE_NAME);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        float distance = measure_distance();

        if (distance < 0.0f) {
            fprintf(stderr, "Skipping log entry due to read error.\n");
        } else {
            log_distance(distance);
            if (distance < PROXIMITY_THRESHOLD_MM) {
                printf("Time to water the plant! Distance: %.2f cm\n",
                       distance);
            }
        }

        /* Sleep in small increments so signals are caught promptly */
        for (int i = 0; i < 10 && g_running; i++) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");
    gpioWrite(TRIGGER_PIN, 0);
    gpioWrite(ECHO_PIN, 0);
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

