static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_init(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    i2c_handle = i2cOpen(1, APDS9960_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at 0x%02X: %s\n",
                APDS9960_ADDR, strerror(errno));
        return -1;
    }
    return 0;
}

static int sensor_init(void) {
    int id = i2cReadByteData(i2c_handle, APDS9960_ID);
    if (id < 0) {
        fprintf(stderr, "Error reading ID register: %s\n", strerror(errno));
        return -1;
    }
    if (id != 0x3D) {
        fprintf(stderr, "Unexpected ID: 0x%02X (expected 0x3D)\n", id);
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, APDS9960_ENABLE, 0x00) < 0) {
        fprintf(stderr, "Error clearing ENABLE register: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(1000);

    if (i2cWriteByteData(i2c_handle, APDS9960_ATIME, 0x00) < 0) {
        fprintf(stderr, "Error writing ATIME: %s\n", strerror(errno));
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, APDS9960_WTIME, 0x00) < 0) {
        fprintf(stderr, "Error writing WTIME: %s\n", strerror(errno));
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, APDS9960_CONTROL, 0x00) < 0) {
        fprintf(stderr, "Error writing CONTROL: %s\n", strerror(errno));
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, APDS9960_ENABLE, 0x01) < 0) {
        fprintf(stderr, "Error enabling sensor: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(1000);
    return 0;
}

static int read_proximity(uint16_t *prox) {
    char buf[6];
    if (i2cReadI2CBlockData(i2c_handle, APDS9960_PROX_DATA0, buf, 6) != 6) {
        fprintf(stderr, "Error reading proximity data: %s\n", strerror(errno));
        return -1;
    }
    *prox = (uint16_t)((buf[1] << 8) | buf[0]);
    return 0;
}

static int read_color(uint16_t *r, uint16_t *g, uint16_t *b) {
    char buf[6];
    if (i2cReadI2CBlockData(i2c_handle, APDS9960_RDATAL, buf, 6) != 6) {
        fprintf(stderr, "Error reading color data: %s\n", strerror(errno));
        return -1;
    }
    *r = (uint16_t)((buf[1] << 8) | buf[0]);
    *g = (uint16_t)((buf[3] << 8) | buf[2]);
    *b = (uint16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

static void log_data(uint16_t r, uint16_t g, uint16_t b, uint16_t prox) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, r, g, b, prox);
    fflush(log_file);
}

static void cleanup(void) {
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (i2c_init() != 0) {
        gpioTerminate();
        return 1;
    }

    if (sensor_init() != 0) {
        cleanup();
        return 1;
    }

    log_file = fopen("color_proximity_log.csv", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Red,Green,Blue,Proximity\n");
        fflush(log_file);
    }

    uint16_t r, g, b, prox;
    int consecutive_errors = 0;

    while (running) {
        if (read_proximity(&prox) == 0) {
            if (read_color(&r, &g, &b) == 0) {
                if (prox > APDS9960_PROX_THRESHOLD) {
                    log_data(r, g, b, prox);
                    consecutive_errors = 0;
                }
            } else {
                consecutive_errors++;
            }
        } else {
            consecutive_errors++;
            fprintf(stderr, "Proximity read error (%d consecutive)\n", consecutive_errors);
            if (consecutive_errors >= MAX_RETRIES) {
                fprintf(stderr, "Max retries reached, re-initializing I2C...\n");
                i2cClose(i2c_handle);
                i2c_handle = -1;
                if (i2c_init() != 0) {
                    fprintf(stderr, "I2C re-init failed, exiting.\n");
                    break;
                }
                if (sensor_init() != 0) {
                    fprintf(stderr, "Sensor re-init failed, exiting.\n");
                    break;
                }
                consecutive_errors = 0;
            }
        }
        gpioDelay(POLL_DELAY_US);
    }

    cleanup();
    return 0;
}

