/*
 * VL53L0X Time-of-Flight sensor reader for Raspberry Pi 3 Model B+
 * Uses raw I2C bit-banging (no driver library dependency).
 *
 * Wiring:
 *   VL53L0X SDA -> GPIO2 (I2C1 SDA)
 *   VL53L0X SCL -> GPIO3 (I2C1 SCL)
 *   VL53L0X TRIG -> GPIO17 (BCM 17, falling-edge trigger)
 *   VL53L0X VDD -> 3.3 V
 *   VL53L0X GND -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o vl53l0x_reader vl53l0x_reader.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- Configuration ---- */
#define I2C_BUS        "/dev/i2c-1"
#define GPIO_TRIGGER   17          /* BCM 17 – falling-edge trigger */
#define LOG_FILE       "distance_log.txt"
#define POLL_TIMEOUT_MS 100        /* RESULT_INTERRUPT_STATUS poll timeout */

/* VL53L0X register addresses (16-bit, big-endian on the bus) */
#define VL53L0X_REG_IDENTIFICATION_MODEL_ID  0x00C0
#define VL53L0X_REG_SYSTEM_MODE_START        0x0000
#define VL53L0X_REG_RESULT_INTERRUPT_STATUS  0x0044
#define VL53L0X_REG_RESULT_RANGE_STATUS      0x0089
#define VL53L0X_REG_RESULT_DISTANCE          0x0096

#define VL53L0X_MODEL_ID_EXPECTED  0xEA
#define VL53L0X_SOFT_RESET        0x0000
#define VL53L0X_SYSTEM_START       0x0001

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ---- Signal handler ---- */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C bit-bang helpers ---- */
static int i2c_write_reg16(int fd, uint16_t reg, uint8_t value)
{
    uint8_t buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;

    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "I2C write to reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint16_t reg, uint8_t *buf, size_t len)
{
    uint8_t addr[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;

    if (write(fd, addr, 2) != 2) {
        fprintf(stderr, "I2C write (addr) for reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read from reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- VL53L0X helpers ---- */
static int vl53l0x_init(int fd)
{
    uint8_t id_buf[2];
    if (i2c_read_reg16(fd, VL53L0X_REG_IDENTIFICATION_MODEL_ID, id_buf, 2) != 0)
        return -1;

    uint16_t model_id = ((uint16_t)id_buf[0] << 8) | id_buf[1];
    if (model_id != VL53L0X_MODEL_ID_EXPECTED) {
        fprintf(stderr, "VL53L0X not found (model ID = 0x%04X, expected 0x%02X)\n",
                model_id, VL53L0X_MODEL_ID_EXPECTED);
        return -1;
    }

    /* Soft reset */
    if (i2c_write_reg16(fd, VL53L0X_REG_SYSTEM_MODE_START, VL53L0X_SOFT_RESET) != 0)
        return -1;
    usleep(10000);  /* 10 ms settle */

    /* Clear any stale interrupt */
    if (i2c_write_reg16(fd, VL53L0X_REG_SYSTEM_MODE_START, 0x0000) != 0)
        return -1;

    return 0;
}

static int vl53l0x_trigger_and_wait(int fd)
{
    /* Clear any stale interrupt before triggering */
    if (i2c_write_reg16(fd, VL53L0X_REG_SYSTEM_MODE_START, 0x0000) != 0)
        return -1;

    /* Start a single measurement */
    if (i2c_write_reg16(fd, VL53L0X_REG_SYSTEM_MODE_START, VL53L0X_SYSTEM_START) != 0)
        return -1;

    /* Poll RESULT_INTERRUPT_STATUS with timeout */
    uint8_t status;
    int waited = 0;
    do {
        if (i2c_read_reg16(fd, VL53L0X_REG_RESULT_INTERRUPT_STATUS, &status, 1) != 0)
            return -1;
        usleep(1000);  /* 1 ms */
        waited++;
    } while ((status & 0x01) == 0 && waited < POLL_TIMEOUT_MS * 1000);

    if (waited >= POLL_TIMEOUT_MS * 1000) {
        fprintf(stderr, "VL53L0X measurement timeout\n");
        return -1;
    }

    /* Read and clear the interrupt */
    uint8_t status_reg;
    if (i2c_read_reg16(fd, VL53L0X_REG_RESULT_INTERRUPT_STATUS, &status_reg, 1) != 0)
        return -1;

    /* Clear interrupt by writing 0x01 to RESULT_INTERRUPT_CLEAR */
    if (i2c_write_reg16(fd, VL53L0X_REG_RESULT_INTERRUPT_CLEAR, 0x01) != 0)
        return -1;

    return 0;
}

static int vl53l0x_read_distance_mm(int fd, int *distance_mm)
{
    uint8_t dist_buf[2];
    if (i2c_read_reg16(fd, VL53L0X_REG_RESULT_DISTANCE, dist_buf, 2) != 0)
        return -1;

    uint16_t raw = ((uint16_t)dist_buf[0] << 8) | dist_buf[1];
    *distance_mm = raw;  /* mm resolution */
    return 0;
}

/* ---- Logging ---- */
static void log_distance(FILE *fp, int distance_mm)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, distance_mm);
    fflush(fp);
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_log_fp) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ---- Main ---- */
int main(void)
{
    /* Install signal handler */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Verify sensor presence */
    if (vl53l0x_init(g_i2c_fd) != 0) {
        fprintf(stderr, "VL53L0X initialization failed – sensor absent or bus error.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure GPIO 17 as input with pull-up */
    if (gpioSetMode(GPIO_TRIGGER, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d) failed: %s\n", GPIO_TRIGGER, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(GPIO_TRIGGER, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown(%d) failed: %s\n", GPIO_TRIGGER, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("VL53L0X ready. Logging to %s. Press Ctrl+C to stop.\n", LOG_FILE);

    /* Main loop */
    while (g_running) {
        if (vl53l0x_trigger_and_wait(g_i2c_fd) != 0) {
            /* Error already reported; continue waiting */
            usleep(100000);  /* 100 ms */
            continue;
        }

        int distance_mm;
        if (vl53l0x_read_distance_mm(g_i2c_fd, &distance_mm) != 0) {
            fprintf(stderr, "Failed to read distance\n");
            usleep(100000);
            continue;
        }

        log_distance(g_log_fp, distance_mm);
        usleep(100000);  /* 100 ms between measurements */
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

