 *   CH101 VCC  -> Pi 3.3 V (Pin 1)
 *   CH101 GND  -> Pi GND   (Pin 9)
 *   CH101 SDA  -> Pi GPIO2 / I2C bus 1 SDA (Pin 3)
 *   CH101 SCL  -> Pi GPIO3 / I2C bus 1 SCL (Pin 5)
 *
 * Build: gcc -O2 -Wall -o ch101_logger ch101_logger.c -li2c
 * Run:   sudo ./ch101_logger   (I2C bus requires root or i2c group access)
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define CH101_I2C_ADDR  0x48
#define LOG_FILE        "distance_log.txt"
#define SAMPLE_PERIOD_US 200000   /* 200 ms */
#define TRIGGER_DELAY_US 50000    /* 50 ms  */

/* CH101 register addresses (16-bit, big-endian on the wire) */
#define CH101_REG_TRIGGER  0x00
#define CH101_REG_DISTANCE 0x04

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg16(int fd, uint8_t addr, uint16_t val)
{
    uint8_t buf[3];
    buf[0] = addr;
    buf[1] = (uint8_t)((val >> 8) & 0xFF);
    buf[2] = (uint8_t)(val & 0xFF);

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                addr, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t addr, uint16_t *val)
{
    uint8_t addr_buf = addr;
    uint8_t data[2];

    if (write(fd, &addr_buf, 1) != 1) {
        fprintf(stderr, "I2C write (addr select 0x%02X) failed: %s\n",
                addr, strerror(errno));
        return -1;
    }

    if (read(fd, data, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                addr, strerror(errno));
        return -1;
    }

    *val = (uint16_t)((data[0] << 8) | data[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm tm_info;

    time(&rawtime);
    localtime_r(&rawtime, &tm_info);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm_info);
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_distance(FILE *fp, const char *ts, int distance_mm)
{
    if (fprintf(fp, "%s, %d\n", ts, distance_mm) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush log failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, CH101_I2C_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                CH101_I2C_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("CH101 distance logger started. Press Ctrl-C to stop.\n");

    /* ---- Main sampling loop ---- */
    while (g_running) {
        /* Trigger measurement */
        if (i2c_write_reg16(g_i2c_fd, CH101_REG_TRIGGER, 0x0001) != 0) {
            /* Skip this sample but keep running */
            usleep(TRIGGER_DELAY_US);
            continue;
        }

        /* Wait for measurement to complete */
        usleep(TRIGGER_DELAY_US);

        /* Read distance */
        uint16_t raw;
        if (i2c_read_reg16(g_i2c_fd, CH101_REG_DISTANCE, &raw) != 0) {
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        int distance_mm = (int)raw;

        char ts[32];
        get_timestamp(ts, sizeof(ts));

        if (log_distance(g_log_fp, ts, distance_mm) != 0) {
            /* Logging failed; continue sampling */
        }

        printf("%s, Distance: %d mm\n", ts, distance_mm);

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

