code:
/*
 * Raspberry Pi Zero W – TDK InvenSense ICU-20201 ToF distance monitor
 *
 * Hardware:
 *   - ICU-20201 on I2C bus 1 (SDA=GPIO2, SCL=GPIO3), address 0x49
 *   - LED + ~330 Ω resistor on GPIO 17 (BCM)
 *
 * Behaviour:
 *   - Samples the sensor every 100 ms.
 *   - Drives the LED high when distance < 20 cm, low otherwise.
 *   - Appends a timestamped distance reading to distance_log.txt.
 *   - Handles SIGINT/SIGTERM for clean shutdown.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o icu20201_monitor icu20201_monitor.c -lpigpio -lrt
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS            1
#define I2C_ADDR           0x49          /* ICU-20201 default I2C address */
#define LED_GPIO           17            /* BCM 17 */
#define DISTANCE_THRESHOLD 20.0f        /* cm */
#define SAMPLE_PERIOD_US   100000       /* 100 ms */
#define LOG_FILE           "distance_log.txt"

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* --------------------------- Signal handling ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- I2C helpers --------------------------------- */
/*
 * ICU-20201 distance register (16-bit, big-endian on the wire).
 * The sensor returns a raw 16-bit value; the exact mapping to cm depends
 * on the specific firmware calibration and the environment.
 */
static int read_distance_raw(int handle, uint16_t *raw_out)
{
    char buf[2];
    int  bytes_read;

    bytes_read = i2cReadDevice(handle, buf, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "[I2C] read_distance_raw: expected 2 bytes, got %d (errno %d: %s)\n",
                bytes_read, errno, strerror(errno));
        return -1;
    }

    *raw_out = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/* --------------------------- Logging ------------------------------------ */
static int log_distance(float distance)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "[LOG] fopen(%s): %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "[LOG] localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "[LOG] strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s, %.2f cm\n", ts, distance) < 0) {
        fprintf(stderr, "[LOG] fprintf failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "[LOG] fclose: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* --------------------------- LED control -------------------------------- */
static void control_led(float distance)
{
    int level = (distance < DISTANCE_THRESHOLD) ? 1 : 0;
    if (gpioWrite(LED_GPIO, level) < 0) {
        fprintf(stderr, "[LED] gpioWrite(%d, %d) failed\n", LED_GPIO, level);
    }
}

/* --------------------------- Cleanup ------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

/* --------------------------------- Main ---------------------------------- */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- I2C open --- */
