/*
 * Si1182-GMR Proximity & Ambient Light Logger
 * Board:  Raspberry Pi Zero W
 * Bus:    I2C-1 (GPIO2=SDA, GPIO3=SCL)
 * Sensor: Silicon Labs Si1182-GMR (I2C 7-bit address 0x49)
 *
 * Build:  gcc -O2 -Wall -o si1182_log si1182_log.c -li2c
 * Run:    ./si1182_log   (Ctrl+C to stop)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SI1182_ADDR    0x49
#define LOG_FILE       "biometric_log.txt"
#define SAMPLE_MS      500
#define MAX_RETRIES    3

/* Si1182 register addresses (command byte 0x40 + reg) */
#define REG_ALS_DATA0  0x41
#define REG_ALS_DATA1  0x42
#define REG_PS_DATA0   0x43
#define REG_PS_DATA1   0x44
#define REG_MEAS_CFG   0x07
#define REG_PS_LED21   0x0F
#define REG_PS_LED3    0x10
#define REG_PS_LED4    0x11
#define REG_PS_LED5    0x12
#define REG_PS_LED6    0x13
#define REG_PS_LED7    0x14
#define REG_PS_LED8    0x15
#define REG_PS_LED9    0x16
#define REG_PS_LED10   0x17
#define REG_PS_LED11   0x18
#define REG_PS_LED12   0x19
#define REG_PS_LED13   0x1A
#define REG_PS_LED14   0x1B
#define REG_PS_LED15   0x1C
#define REG_PS_LED16   0x1D
#define REG_PS_LED17   0x1E
#define REG_PS_LED18   0x1F

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log = NULL;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t cmd, uint8_t val)
{
    uint8_t buf[2] = { cmd, val };
    ssize_t n = write(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "I2C write cmd 0x%02X failed: %s (wrote %zd bytes)\n",
                cmd, strerror(errno), n);
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t cmd, uint8_t *val)
{
    ssize_t n = write(fd, &cmd, 1);
    if (n != 1) {
        fprintf(stderr, "I2C write (cmd) 0x%02X failed: %s\n",
                cmd, strerror(errno));
        return -1;
    }
    n = read(fd, val, 1);
    if (n != 1) {
        fprintf(stderr, "I2C read cmd 0x%02X failed: %s\n",
                cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t cmd, uint16_t *val)
{
    uint8_t buf[2];
    ssize_t n = write(fd, &cmd, 1);
    if (n != 1) {
        fprintf(stderr, "I2C write (cmd) 0x%02X failed: %s\n",
                cmd, strerror(errno));
        return -1;
    }
    n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "I2C read cmd 0x%02X failed: %s\n",
                cmd, strerror(errno));
        return -1;
    }
    *val = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int init_sensor(void)
{
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, SI1182_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                SI1182_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return -1;
    }

    /* Probe: try a register read to confirm the sensor is present */
    uint8_t dummy;
    if (i2c_read_reg8(g_i2c_fd, REG_MEAS_CFG, &dummy) < 0) {
        fprintf(stderr, "Si1182 not responding at 0x%02X on %s\n",
                SI1182_ADDR, I2C_BUS);
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return -1;
    }

    /* Configure measurement: ALS + PS, 1-shot mode */
    if (i2c_write_reg8(g_i2c_fd, REG_MEAS_CFG, 0x03) < 0)
        return -1;

    /* Configure LED current for proximity channels */
    if (i2c_write_reg8(g_i2c_fd, REG_PS_LED21, 0x0F) < 0) return -1;
    if (i2c_write_reg8(g_i2c_fd, REG_PS_LED3,  0x0F) < 0) return -1;
    if (i2c_write_reg8(g_i2c_fd, REG_PS_LED4,  0x0F) < 0) return -1;
    if (i2c_write_reg8(g_i2c_fd, REG_PS_LED5,  0x0F) < 0) return -1;
    if (i2c_write_reg8(g_i2c_fd, REG_PS_LED6,  0x0F) < 0) return -1;
    if (i2c_write_reg8(g_i2c_fd, REG_PS_LED7,  0x0F) < 0) return -1;
    if (i2c_write_reg8(g_i2c_fd, REG_PS_LED8,  0x0F) < 0) return -1;
    if (i2c_write_reg8(g_i2c_fd, REG_PS_LED9,  0x0F) < 0) return -1;
    if (i2c_write_reg8(g_i2c_fd, REG_PS_LED10, 0x0F) < 0) return -1;
    if (i2c_write_reg8(g_i2c_fd, REG_PS_LED11, 0x0F) < 0) return -1;
    if (i2c_write_reg8(g_i2c_fd, REG_PS_LED12, 0x0F) < 0) return -1;
    if (i2c_write_reg8(g_i2c_fd, REG_PS_LED13, 0x0F) < 0) return -1;
    if (i2c_write_reg8(g_i2c_fd, REG_PS_LED14, 0x0F) < 0) return -1;
    if (i2c_write_reg8(g_i2c_fd, REG_PS_LED15, 0x0F) < 0) return -1;
    if (i2c_write_reg8(g_i2c_fd, REG_PS_LED16, 0x0F) < 0) return -1;
    if (i2c_write_reg8(g_i2c_fd, REG_PS_LED17, 0x0F) < 0) return -1;
    if (i2c_write_reg8(g_i2c_fd, REG_PS_LED18, 0x0F) < 0) return -1;

    return 0;
}

static int read_sensor_data(uint16_t *prox, uint16_t *light)
{
    int retries = MAX_RETRIES;
    while (retries > 0) {
        if (i2c_read_reg16(g_i2c_fd, REG_ALS_DATA0, prox) == 0 &&
            i2c_read_reg16(g_i2c_fd, REG_ALS_DATA1, light) == 0)
            return 0;
        retries--;
        if (retries > 0)
            usleep(10000);
    }
    fprintf(stderr, "Sensor read failed after %d retries\n", MAX_RETRIES);
    return -1;
}

static void log_data(uint16_t prox, uint16_t light)
{
    time_t rawtime;
    struct tm timeinfo;
    char ts[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(g_log, "%s, Proximity: %u, Ambient Light: %u\n", ts, prox, light);
    fflush(g_log);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (init_sensor() < 0) {
        fprintf(stderr, "Sensor initialization failed. Exiting.\n");
        if (g_i2c_fd >= 0) close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("Si1182 logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        uint16_t prox, light;
        if (read_sensor_data(&prox, &light) == 0) {
            log_data(prox, light);
            printf("Proximity: %u, Ambient Light: %u\n", prox, light);
        } else {
            fprintf(stderr, "Skipping log entry due to read failure.\n");
        }
        usleep(SAMPLE_MS * 1000);
    }

    printf("\nShutting down...\n");
    if (g_log) fclose(g_log);
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    return EXIT_SUCCESS;
}

