/*
 * ICU-20201 Time-of-Flight distance monitor for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   ICU-20201 SDA  -> GPIO 2 (I2C bus 1 SDA)
 *   ICU-20201 SCL  -> GPIO 3 (I2C bus 1 SCL)
 *   ICU-20201 VDD  -> 3.3 V
 *   ICU-20201 GND  -> GND
 *   LED anode     -> GPIO 17 (BCM) via 330 Ω resistor -> GND
 *
 * Build:  gcc -O2 -Wall -o tof_monitor tof_monitor.c -lpigpio -lrt
 * Run:    sudo ./tof_monitor [distance_threshold_mm]
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

/* ---- Configuration ---- */
#define I2C_BUS            1
#define I2C_ADDR           0x39          /* ICU-20201 default I2C address */
#define LED_GPIO           17            /* BCM 17 */
#define LOG_FILE           "tof_log.txt"
#define POLL_DELAY_US      50000         /* 50 ms */
#define WHO_AM_I_REG       0x00
#define WHO_AM_I_VAL       0x01          /* expected device ID */
#define DIST_REG           0x40          /* distance register (16-bit, mm) */
#define DIST_REG_MASK      0xFFFF        /* 16-bit, big-endian on bus */

/* ---- Globals for signal-safe cleanup ---- */
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;
static volatile sig_atomic_t g_running = 1;

/* ---- Prototypes ---- */
static int  init_i2c(void);
static int  read_distance_mm(void);
static void log_distance(int distance_mm);
static void signal_handler(int sig);
static void cleanup(void);

/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    int threshold = 100;                 /* default in mm */
    int opt;

    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atoi(optarg);
                if (threshold <= 0) {
                    fprintf(stderr, "Threshold must be a positive integer.\n");
                    return EXIT_FAILURE;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold_mm]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output.\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);   /* LED off initially */

    /* Initialize I2C */
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        cleanup();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Monitoring distance (threshold = %d mm). Press Ctrl+C to exit.\n",
           threshold);

    /* Main polling loop */
    while (g_running) {
        int distance = read_distance_mm();

        if (distance >= 0) {
            log_distance(distance);

            if (distance < threshold) {
                gpioWrite(LED_GPIO, 1);   /* LED on */
            } else {
                gpioWrite(LED_GPIO, 0);   /* LED off */
            }
        } else {
            /* Sensor read error: ensure LED is off and log the fault */
            gpioWrite(LED_GPIO, 0);
            fprintf(stderr, "Sensor read error — LED off.\n");
        }

        gpioDelay(POLL_DELAY_US);       /* 50 ms */
    }

    /* Graceful shutdown */
    gpioWrite(LED_GPIO, 0);
    cleanup();
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

/* ------------------------------------------------------------------ */
/* Initialize I2C: open bus, verify WHO_AM_I, then configure mode.     */
/* Returns 0 on success, -1 on failure.                                 */
/* ------------------------------------------------------------------ */
static int init_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (bus %d, addr 0x%02X): %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        return -1;
    }

    /* Verify device identity */
    int who = i2cReadByteData(g_i2c_handle, WHO_AM_I_REG);
    if (who < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register: %d\n", who);
        return -1;
    }
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr,
                "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, WHO_AM_I_VAL);
        return -1;
    }

    /* Put sensor in measurement mode (example register; adjust per datasheet) */
    if (i2cWriteByteData(g_i2c_handle, 0x20, 0x01) < 0) {
        fprintf(stderr, "Failed to set measurement mode: %d\n", who);
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read 16-bit distance (mm) from the ICU-20201.                        */
/* Returns distance on success, -1 on error.                            */
/* ------------------------------------------------------------------ */
static int read_distance_mm(void)
{
    int lo = i2cReadByteData(g_i2c_handle, DIST_REG);
    if (lo < 0) {
        fprintf(stderr, "I2C read low byte failed: %d\n", lo);
        return -1;
    }

    int hi = i2cReadByteData(g_i2c_handle, DIST_REG + 1);
    if (hi < 0) {
        fprintf(stderr, "I2C read high byte failed: %d\n", hi);
        return -1;
    }

    return (hi << 8) | lo;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped distance reading to the log file.              */
/* ------------------------------------------------------------------ */
static void log_distance(int distance_mm)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return;
    }

    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    if (t == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(g_log_file, "%s, Distance: %d mm\n", ts, distance_mm) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return;
    }

    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
    }
}

/* ------------------------------------------------------------------ */
/* Signal handler — set flag only; defer cleanup to main.              */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Release all resources.                                               */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

