code:
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define B5L_I2C_ADDR   0x60
#define B5L_CMD_LEN    4
#define B5L_RESP_LEN   15
#define B5L_CMD_HEADER 0x40
#define B5L_CMD_MEAS   0x01
#define B5L_CMD_LEN_VAL 0x40
#define B5L_RESP_LEN_VAL 0x0F
#define INTRUSION_THRESH 1000
#define SAMPLES_PER_CYCLE 10
#define CYCLE_DELAY_MS   100
#define MEAS_DELAY_MS    10

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_cmd(int fd, uint8_t addr, const uint8_t *cmd, size_t len) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("ioctl(I2C_SLAVE)");
        return -1;
    }
    ssize_t n = write(fd, cmd, len);
    if (n < 0) {
        perror("write");
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "Short write: %zd of %zu bytes\n", n, len);
        return -1;
    }
    return 0;
}

static int i2c_read_data(int fd, uint8_t addr, uint8_t *buf, size_t len) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("ioctl(I2C_SLAVE)");
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        perror("read");
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "Short read: %zd of %zu bytes\n", n, len);
        return -1;
    }
    return 0;
}

static int read_b5l_data(int fd, int *distance_out) {
    uint8_t cmd[B5L_CMD_LEN] = { B5L_CMD_HEADER, B5L_CMD_MEAS, 0x00, 0x00 };
    uint8_t resp[B5L_RESP_LEN];

    if (i2c_write_cmd(fd, B5L_I2C_ADDR, cmd, sizeof(cmd)) < 0) {
        return -1;
    }

    usleep(MEAS_DELAY_MS * 1000);

    if (i2c_read_data(fd, B5L_I2C_ADDR, resp, sizeof(resp)) < 0) {
        return -1;
    }

    if (resp[0] != B5L_CMD_HEADER) {
        fprintf(stderr, "Unexpected header: 0x%02X (expected 0x%02X)\n",
                resp[0], B5L_CMD_HEADER);
        return -1;
    }

    uint16_t raw = ((uint16_t)resp[11] << 8) | resp[12];
    *distance_out = (int)raw;
    return 0;
}

static int log_intrusion(FILE *fp, int distance) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        return -1;
    }
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    if (fprintf(fp, "%s, Distance: %d mm\n", ts, distance) < 0) {
        perror("fprintf");
        return -1;
    }
    fflush(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open(" I2C_BUS ")");
        return EXIT_FAILURE;
    }

    g_log_fp = fopen("intrusion_log.txt", "a");
    if (!g_log_fp) {
        perror("fopen(intrusion_log.txt)");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("Intrusion detection started. Press Ctrl-C to exit.\n");

    while (g_running) {
        int sum = 0;
        int valid = 0;

        for (int i = 0; i < SAMPLES_PER_CYCLE && g_running; i++) {
            int d;
            if (read_b5l_data(g_i2c_fd, &d) == 0) {
                sum += d;
                valid++;
            } else {
                fprintf(stderr, "Read failed at sample %d\n", i);
            }
            usleep(CYCLE_DELAY_MS * 1000);
        }

        if (!g_running) {
            break;
        }

        if (valid > 0) {
            int avg = sum / valid;
            printf("Average distance: %d mm\n", avg);

            if (avg < INTRUSION_THRESH) {
