/*
 * VL53L0X Time-of-Flight distance sensor reader for Raspberry Pi 3 Model B+
 * Bus: I2C-1 (GPIO2=SDA, GPIO3=SCL), address 0x29 (ADDR pin low)
 * Build: gcc -O2 -Wall -o vl53l0x_reader vl53l0x_reader.c -li2c
