#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define VL53L0X_ADDR   0x29

/* VL53L0X register addresses */
#define REG_MODEL_ID            0x00C0
#define REG_SYSTEM_INTERRUPT    0x0044
#define REG_RESULT_INTERRUPT_STATUS 0x0046
#define REG_RESULT_RANGE_STATUS 0x0089
#define REG_RESULT_DISTANCE     0x0096

#define EXPECTED_MODEL_ID       0xEA
#define POLL_TIMEOUT_MS         100
#define LOOP_DELAY_MS           500

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a 16-bit register address, then a single byte of data. */
static int i2c_write_reg8(int fd, uint16_t reg, uint8_t value)
{
    uint8_t buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;

    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "i2c_write_reg8(0x%04X, 0x%02X) failed: %s\n",
                reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a 16-bit register address, then a 2-byte data payload. */
static int i2c_read_reg16(int fd, uint16_t reg, uint16_t *out)
{
    uint8_t addr[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;

    if (write(fd, addr, 2) != 2) {
        fprintf(stderr, "i2c_read_reg16 write(0x%04X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    uint8_t data[2];
    if (read(fd, data, 2) != 2) {
        fprintf(stderr, "i2c_read_reg16 read(0x%04X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *out = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

static int vl53l0x_init(int fd)
{
    uint16_t model_id = 0;

    if (i2c_read_reg16(fd, REG_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "Failed to read model ID from sensor.\n");
        return -1;
    }

    if (model_id != EXPECTED_MODEL_ID) {
        fprintf(stderr,
                "Unexpected model ID: 0x%04X (expected 0x%02X). "
                "Sensor not present or wrong device.\n",
                model_id, EXPECTED_MODEL_ID);
        return -1;
    }

    printf("VL53L0X detected (model ID 0x%04X).\n", model_id);
    return 0;
}

static int vl53l0x_read_distance(int fd, int *distance_mm)
{
    uint16_t status = 0;
    uint16_t dist   = 0;

    /* Poll RESULT_INTERRUPT_STATUS with a timeout. */
    for (int i = 0; i < POLL_TIMEOUT_MS; i++) {
        if (i2c_read_reg16(fd, REG_RESULT_INTERRUPT_STATUS, &status) != 0)
            return -1;

        if (status & 0x01)
            break;

        usleep(1000);
    }

    if (!(status & 0x01)) {
        fprintf(stderr, "Timeout waiting for measurement.\n");
        return -1;
    }

    /* Read distance. */
    if (i2c_read_reg16(fd, REG_RESULT_DISTANCE, &dist) != 0)
        return -1;

    *distance_mm = dist;
    return 0;
}

static void print_distance(int distance_mm)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s Distance: %d mm\n", timestamp, distance_mm);
    fflush(stdout);
}

int main(void)
{
    int fd = -1;
    int rc = EXIT_FAILURE;

    /* Install signal handlers for graceful shutdown. */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the I2C bus. */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the sensor's I2C address. */
    if (ioctl(fd, I2C_SLAVE, VL53L0X_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                VL53L0X_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Initialize the sensor. */
    if (vl53l0x_init(fd) != 0) {
        fprintf(stderr, "VL53L0X initialization failed.\n");
        goto cleanup;
    }

    printf("Starting distance readings (Ctrl+C to stop)...\n");
    fflush(stdout);

    /* Main polling loop. */
    while (g_running) {
        int distance_mm = 0;

        if (vl53l0x_read_distance(fd, &distance_mm) == 0) {
            print_distance(distance_mm);
        } else {
            fprintf(stderr, "Failed to read distance.\n");
        }

        /* Sleep for the remainder of the 500 ms cycle. */
        usleep(LOOP_DELAY_MS * 1000);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    if (rc == EXIT_SUCCESS)
        printf("\nExiting gracefully.\n");

    return rc;
}

