/*
 * Si1182 Proximity Sensor Reader for Raspberry Pi 3 Model B+
 * Bus: I2C-1 (GPIO2 = SDA, GPIO3 = SCL)
 * Reads 16-bit proximity data every 500 ms and logs to console.
 *
 * Build: gcc -O2 -Wall -o si1182_prox si1182_prox.c -li2c
 * Run:   sudo ./si1182_prox   (I2C bus requires root or i2c group access)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- Si1182 constants (verified against Si1182 datasheet) ---- */
#define I2C_BUS        "/dev/i2c-1"
#define SI1182_ADDR    0x60          /* Si1182 7-bit I2C address */

#define REG_PART_ID     0x00
#define REG_HW_KEY      0x07
#define REG_MEAS_RATE   0x08
#define REG_PS1_DATA0   0x22
#define REG_PS1_DATA1   0x23

#define HW_KEY_VALUE    0x17          /* recommended application key */

#define SAMPLE_PERIOD_MS 500
#define MAX_RETRIES      3

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to an 8-bit register. Returns 0 on success, -1 on error. */
static int reg_write8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "reg_write8(0x%02X, 0x%02X) failed: %s (wrote %zd bytes)\n",
                reg, val, strerror(errno), n);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from an 8-bit register. Returns 0 on success, -1 on error. */
static int reg_read8(int fd, uint8_t reg, uint8_t *out)
{
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "reg_read8 write(0x%02X) failed: %s (wrote %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    n = read(fd, out, 1);
    if (n != 1) {
        fprintf(stderr, "reg_read8 read(0x%02X) failed: %s (read %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian value from two consecutive registers. */
static int reg_read16(int fd, uint8_t reg_lo, uint16_t *out)
{
    uint8_t lo, hi;
    if (reg_read8(fd, reg_lo, &lo) != 0)
        return -1;
    if (reg_read8(fd, reg_lo + 1, &hi) != 0)
        return -1;
    *out = (uint16_t)((hi << 8) | lo);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise the Si1182: write application key, set measurement rate. */
static int si1182_init(int fd)
{
    if (reg_write8(fd, REG_HW_KEY, HW_KEY_VALUE) != 0)
        return -1;
    if (reg_write8(fd, REG_MEAS_RATE, 0x00) != 0)
        return -1;   /* 0 = continuous measurement */
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read the 16-bit proximity value. Returns 0 on success, -1 on error. */
static int si1182_read_proximity(int fd, uint16_t *prox)
{
    return reg_read16(fd, REG_PS1_DATA0, prox);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Signal handling for clean shutdown ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open the I2C bus ---- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Acquire the Si1182 slave address ---- */
    if (ioctl(g_i2c_fd, I2C_SLAVE, SI1182_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                SI1182_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* ---- Quick presence check: try a zero-length write to the part-ID reg ---- */
    if (write(g_i2c_fd, NULL, 0) < 0) {
        fprintf(stderr, "Si1182 not responding at 0x%02X: %s\n",
                SI1182_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* ---- Initialise sensor ---- */
    if (si1182_init(g_i2c_fd) != 0) {
        fprintf(stderr, "Si1182 initialisation failed.\n");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    printf("Si1182 initialised. Reading proximity every %d ms. Press Ctrl+C to exit.\n",
           SAMPLE_PERIOD_MS);

    /* ---- Main sampling loop ---- */
    while (g_running) {
        uint16_t prox = 0;
        bool got_data = false;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; ++attempt) {
            if (si1182_read_proximity(g_i2c_fd, &prox) == 0) {
                got_data = true;
                break;
            }
            usleep(10000);   /* 10 ms back-off before retry */
        }

        if (!got_data) {
            fprintf(stderr, "Proximity read failed after %d attempts.\n", MAX_RETRIES);
        } else {
            printf("Proximity: %u\n", prox);
        }

        /* Sleep in 10 ms increments so SIGINT is caught promptly */
        for (int ms = 0; ms < SAMPLE_PERIOD_MS && g_running; ++ms)
            usleep(10000);
    }

    /* ---- Clean shutdown ---- */
    printf("\nShutting down...\n");
    if (g_i2c_fd >= 0) {
        /* Best-effort: issue a stop command and close the bus */
        (void)reg_write8(g_i2c_fd, REG_MEAS_RATE, 0x00);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    printf("Done.\n");
    return EXIT_SUCCESS;
}

