/*
 * OPT3101 Time-of-Flight sensor reader for Raspberry Pi Zero W
 *
 * Wiring:
 *   OPT3101 SDA  -> GPIO2 (I2C bus 1 SDA, pin 3)
 *   OPT3101 SCL  -> GPIO3 (I2C bus 1 SCL, pin 5)
 *   OPT3101 VDD  -> 3.3 V (pin 1)
 *   OPT3101 GND  -> GND  (pin 6)
 *
 * I2C address: 0x49 (7-bit)
 *
 * Build:  gcc -O2 -Wall -Wextra -o opt3101_reader opt3101_reader.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define OPT3101_ADDR   0x49

/* OPT3101 register addresses (16-bit, big-endian on the bus) */
#define REG_RESULT     0x00
#define REG_ALS_CONF   0x01
#define REG_ALS_DATA   0x02
#define REG_MEAS_CONF  0x03
#define REG_INT_CFG    0x04
#define REG_INT_STATUS 0x05
#define REG_INT_CLEAR  0x06

#define SAMPLE_PERIOD_MS 500

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1)
        perror("sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) == -1)
        perror("sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg16(int fd, uint16_t reg, uint16_t value)
{
    uint8_t buf[4];
    buf[0] = (uint8_t)(reg >> 8);
    buf[1] = (uint8_t)(reg & 0xFF);
    buf[2] = (uint8_t)(value >> 8);
    buf[3] = (uint8_t)(value & 0xFF);

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint16_t reg, uint16_t *out)
{
    uint8_t reg_buf[2];
    uint8_t data_buf[2];

    reg_buf[0] = (uint8_t)(reg >> 8);
    reg_buf[1] = (uint8_t)(reg & 0xFF);

    if (write(fd, reg_buf, sizeof(reg_buf)) != (ssize_t)sizeof(reg_buf)) {
        fprintf(stderr, "I2C write (reg select 0x%04X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (read(fd, data_buf, sizeof(data_buf)) != (ssize_t)sizeof(data_buf)) {
        fprintf(stderr, "I2C read from reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *out = ((uint16_t)data_buf[0] << 8) | data_buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* OPT3101 sensor operations                                           */
/* ------------------------------------------------------------------ */
static int opt3101_init(int fd)
{
    /* Clear any pending interrupt */
    if (i2c_write_reg16(fd, REG_INT_CLEAR, 0x0001) < 0)
        return -1;

    /* Configure ALS: enable channel 0, 1, 2 (LEDs), 1 sample/cycle */
    if (i2c_write_reg16(fd, REG_ALS_CONF, 0x0003) < 0)
        return -1;

    /* Configure measurement: 1 sample, 1 ms conversion time */
    if (i2c_write_reg16(fd, REG_MEAS_CONF, 0x0001) < 0)
        return -1;

    /* Configure interrupt: enable new-sample-ready */
    if (i2c_write_reg16(fd, REG_INT_CFG, 0x0001) < 0)
        return -1;

    return 0;
}

static int opt3101_read_distance(int fd, uint16_t *distance_mm)
{
    uint16_t als;

    if (i2c_read_reg16(fd, REG_ALS_DATA, &als) < 0)
        return -1;

    /* Distance = ALS value / 2 (per datasheet) */
    *distance_mm = als / 2;
    return 0;
}

static int opt3101_read_ambient_light(int fd, uint16_t *ambient_light)
{
    return i2c_read_reg16(fd, REG_ALS_DATA, ambient_light);
}

static int opt3101_get_error_flags(int fd, uint16_t *error_flags)
{
    return i2c_read_reg16(fd, REG_INT_STATUS, error_flags);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int ret = EXIT_FAILURE;

    install_signal_handlers();

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the OPT3101 device */
    if (ioctl(g_i2c_fd, I2C_SLAVE, OPT3101_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                OPT3101_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Probe: try a dummy read to confirm the sensor is present */
    uint16_t probe;
    if (i2c_read_reg16(g_i2c_fd, REG_ALS_DATA, &probe) < 0) {
        fprintf(stderr, "OPT3101 not responding at 0x%02X: %s\n",
                OPT3101_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Initialize sensor */
    if (opt3101_init(g_i2c_fd) < 0) {
        fprintf(stderr, "OPT3101 initialization failed.\n");
        goto cleanup;
    }

    printf("OPT3101 initialized. Logging every %d ms. Press Ctrl-C to stop.\n",
           SAMPLE_PERIOD_MS);

    while (g_running) {
        uint16_t distance_mm = 0;
        uint16_t ambient_light = 0;
        uint16_t error_flags   = 0;

        if (opt3101_read_distance(g_i2c_fd, &distance_mm) < 0) {
            fprintf(stderr, "Distance read failed; continuing.\n");
        } else if (opt3101_read_ambient_light(g_i2c_fd, &ambient_light) < 0) {
            fprintf(stderr, "Ambient light read failed; continuing.\n");
        } else if (opt3101_get_error_flags(g_i2c_fd, &error_flags) < 0) {
            fprintf(stderr, "Error flags read failed; continuing.\n");
        } else {
            printf("Distance: %5u mm | Ambient: %5u | Errors: 0x%04X\n",
                   distance_mm, ambient_light, error_flags);
        }

        /* Sleep in small increments so SIGINT is caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD_MS && g_running; i += 10) {
            usleep(10 * 1000);
        }
    }

    printf("\nShutting down cleanly.\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return ret;
}

