/*
 * HC-SR04 Ultrasonic Distance Sensor Reader for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   HC-SR04 TRIG -> GPIO 17 (BCM)
 *   HC-SR04 ECHO -> GPIO 18 (BCM) via 1 kΩ series resistor (5 V sensor, 3.3 V Pi)
 *
 * The HC-SR04 requires a 10 µs trigger pulse and supports echo returns up to
 * 38 ms (maximum range ~400 cm).  We issue a 10 µs pulse, wait up to 200 ms
 * for the echo rising edge, wait up to 200 ms for the echo falling edge, and
 * log the distance in centimetres every second.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o hcsr04 hcsr04.c -lpigpio -lrt
 *   (Run as root or with appropriate permissions for /dev/gpiochip0 access.)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      17
#define ECHO_PIN         18

#define TRIGGER_PULSE_US 10          /* HC-SR04 datasheet: 10 µs trigger pulse   */
#define ECHO_TIMEOUT_US  200000      /* 200 ms max wait for echo rising edge     */
#define ECHO_TIMEOUT_US  200000      /* 200 ms max wait for echo falling edge    */
#define READ_INTERVAL_S  1           /* Read one sample per second                */
#define MAX_PULSE_US     38000       /* HC-SR04 max range ~400 cm (~38 ms)        */
#define MIN_PULSE_US     0           /* Sanity: ignore 0 µs readings             */

/* ------------------------------------------------------------------ */
/* Shared state between signal handler and main thread                */
/* ------------------------------------------------------------------ */
static volatile sig_atomic_t g_running = 1;
static volatile uint32_t     g_pulse_us = 0;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits and cleans up          */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* pigpio alert callback — fires on every edge of ECHO_PIN              */
/* ------------------------------------------------------------------ */
static void echo_callback(int gpio, int level, uint32_t tick)
{
    (void)gpio;

    if (level == 1) {
        /* Rising edge — echo pulse starts */
        g_pulse_us = tick;
    } else if (level == 0) {
        /* Falling edge — echo pulse ends */
        if (g_pulse_us > 0) {
            g_pulse_us = 0;
            /* pigpio tick is microseconds since boot; handle wrap-around */
            uint32_t diff = tick - g_pulse_us;          /* correct on wrap */
            if (diff > MAX_PULSE_US) {
                /* Out of range — reset so we don't log nonsense */
                g_pulse_us = 0;
            } else {
                double distance_cm = (double)diff / 58.0; /* cm per µs round-trip */
                printf("Distance: %.2f cm\n", distance_cm);
                fflush(stdout);
            }
        }
    }
}

/* ------------------------------------------------------------------ */
/* Trigger a 10 µs pulse on TRIGGER_PIN                                */
/* ------------------------------------------------------------------ */
static void trigger_sensor(void)
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Install signal handlers for graceful shutdown ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (run as root?).\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure GPIO pins ---- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: cannot set TRIGGER_PIN %d as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: cannot set ECHO_PIN %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts LOW */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(50);  /* let things settle */

    /* ---- Register echo alert callback ---- */
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Error: cannot register alert on ECHO_PIN %d.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance reader started.\n");
    printf("  Trigger: GPIO %d | Echo: GPIO %d (via 1 kΩ resistor)\n",
           TRIGGER_PIN, ECHO_PIN);
    printf("  Reading every %d s. Press Ctrl+C to exit.\n\n", READ_INTERVAL_S);
    fflush(stdout);

    /* ---- Main loop ---- */
    while (g_running) {
        trigger_sensor();
        /* Wait for the echo falling edge (timeout) */
        uint32_t waited = 0;
        while (g_running && waited < ECHO_TIMEOUT_US) {
            gpioDelay(1000);  /* 1 ms */
            waited += 1000;
        }
        if (!g_running) {
            break;  /* signal received during wait */
        }
        if (waited >= ECHO_TIMEOUT_US) {
            fprintf(stderr, "Warning: echo timeout — no object detected or sensor absent.\n");
        }

        /* Wait for the echo rising edge (timeout) */
        waited = 0;
        while (g_running && waited < ECHO_TIMEOUT_US) {
            gpioDelay(1000);
            waited += 1000;
        }
        if (!g_running) {
            break;
        }
        if (waited >= ECHO_TIMEOUT_US) {
            fprintf(stderr, "Warning: echo timeout — no object detected or sensor absent.\n");
        }

        /* Sleep for the remainder of the read interval (approx) */
        uint32_t remaining = (uint32_t)(READ_INTERVAL_S * 1000000ULL);
        remaining -= waited;
        if (remaining > 0) {
            gpioDelay(remaining);
        }
    }

    /* ---- Cleanup ---- */
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);  /* unregister callback */
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

