#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>
#include <pigpio.h>

#define UART_DEVICE "/dev/serial0"
#define GPIO_LED 17
#define RANGE_THRESHOLD 1.0f
#define LOG_FILE "intrusion_log.csv"
#define MAGIC_WORD 0x01020304
#define FRAME_SIZE 136
#define NUM_BINS 64
#define LED_DURATION_MS 2000

static volatile sig_atomic_t running = 1;
static int uart_fd = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_uart(const char *device) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd < 0) {
        fprintf(stderr, "Error opening UART %s: %s\n", device, strerror(errno));
        return -1;
    }

    struct termios tty;
    memset(&tty, 0, sizeof(tty));
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "tcgetattr failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    cfsetispeed(&tty, B9600);
    cfsetospeed(&tty, B9600);

    tty.c_cflag = CS8 | CLOCAL | CREAD;
    tty.c_iflag = IGNPAR;
    tty.c_oflag = 0;
    tty.c_lflag = 0;

    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 5;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "tcsetattr failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static int read_exact(int fd, uint8_t *buf, size_t len) {
    size_t total = 0;
    while (total < len) {
        ssize_t n = read(fd, buf + total, len - total);
        if (n < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "UART read error: %s\n", strerror(errno));
            return -1;
        }
        if (n == 0) {
            fprintf(stderr, "UART EOF (sensor absent?)\n");
            return -1;
        }
        total += (size_t)n;
    }
    return 0;
}

static int decode_frame(const uint8_t *buf, float *distances) {
    if (buf[0] != MAGIC_WORD) {
        fprintf(stderr, "Invalid magic word: 0x%02X\n", buf[0]);
        return -1;
    }

    const uint8_t *data = buf + 8;
    for (int i = 0; i < NUM_BINS; i++) {
        uint16_t raw = (uint16_t)data[2 * i] | ((uint16_t)data[2 * i + 1] << 8);
        distances[i] = (float)raw * 0.04375f;
    }
    return 0;
}

static int log_intrusion(float distance) {
    time_t now = time(NULL);
    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return -1;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info);

    if (fprintf(log_fp, "%s,%.2f\n", ts, distance) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(log_fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void activate_led(int duration_ms) {
    if (gpioWrite(GPIO_LED, 1) != 0) {
        fprintf(stderr, "gpioWrite HIGH failed\n");
        return;
    }
    gpioDelay(duration_ms * 1000);
    if (gpioWrite(GPIO_LED, 0) != 0) {
        fprintf(stderr, "gpioWrite LOW failed\n");
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(GPIO_LED, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed\n");
        gpioTerminate();
        return 1;
    }
    gpioWrite(GPIO_LED, 0);

    uart_fd = init_uart(UART_DEVICE);
    if (uart_fd < 0) {
        gpioTerminate();
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        close(uart_fd);
        gpioTerminate();
        return 1;
    }

    float distances[NUM_BINS];
    uint8_t frame_buf[FRAME_SIZE];

    while (running) {
        if (read_exact(uart_fd, frame_buf, FRAME_SIZE) != 0) {
            fprintf(stderr, "Error reading frame, retrying...\n");
            gpioDelay(100000);
            continue;
        }

        if (decode_frame(frame_buf, distances) == 0) {
            for (int i = 0; i < NUM_BINS; i++) {
                if (distances[i] > RANGE_THRESHOLD) {
                    printf("Intrusion detected! Distance: %.2f m\n", distances[i]);
                    if (log_intrusion(distances[i]) != 0) {
                        fprintf(stderr, "Failed to log intrusion\n");
                    }
                    activate_led(LED_DURATION_MS);
                }
            }
        }
    }

    printf("\nShutting down...\n");
    if (log_fp) fclose(log_fp);
    if (uart_fd >= 0) close(uart_fd);
    gpioWrite(GPIO_LED, 0);
    gpioTerminate();
    return 0;
}

