static int  read_distance(float *distance_out);
static int  log_distance(float distance);
static void cleanup(void);

/* ----------------------------- Signal handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- I2C init ----------------------------------- */
static int init_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, I2C_ADDR, pigpio_error(g_i2c_handle));
        return -1;
    }
    return 0;
}

/* ----------------------------- Read distance ------------------------------ */
/*
 * The ICU-20201 returns a 16-bit big-endian distance value.
 * A zero-length conversion yields 0xFFFF (2 bytes of 0xFF).
 */
static int read_distance(float *distance_out)
{
    char buf[2];
    int  rc;

    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        rc = i2cReadDevice(g_i2c_handle, buf, 2);
        if (rc == 2) {
            uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
            *distance_out = (float)raw / 100.0f;   /* cm */
            return 0;
        }
        if (rc < 0) {
            fprintf(stderr, "[WARN] i2cReadDevice failed (attempt %d/%d): %s\n",
                    attempt + 1, MAX_RETRIES, pigpio_error(rc));
        } else {
            fprintf(stderr, "[WARN] i2cReadDevice short read (attempt %d/%d): got %d bytes\n",
                    attempt + 1, MAX_RETRIES, rc);
        }
        if (attempt < MAX_RETRIES - 1) {
            usleep(10000);   /* 10 ms back-off */
        }
    }

    fprintf(stderr, "[ERROR] Distance read failed after %d attempts\n", MAX_RETRIES);
    return -1;
}

/* ----------------------------- Log distance ------------------------------ */
static int log_distance(float distance)
{
    time_t     t;
    struct tm  tm_buf;
    char       ts[32];

    t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "[ERROR] time() failed: %s\n", strerror(errno));
        return -1;
    }
    if (localtime_r(&t, &tm_buf) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r() failed\n");
        return -1;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_buf) == 0) {
        fprintf(stderr, "[ERROR] strftime() failed\n");
        return -1;
    }

    if (fprintf(g_log_file, "%s, %.2f\n", ts, distance) < 0) {
        fprintf(stderr, "[ERROR] fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "[ERROR] fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ----------------------------- Cleanup ------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    float distance;
    int   rc;

    /* --- pigpio init --------------------------------------------------- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] gpioInitialise() failed\n");
        return EXIT_FAILURE;
    }

    /* --- I2C init ------------------------------------------------------ */
    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- GPIO alert setup --------------------------------------------- */
    if (gpioSetMode(ALERT_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "[ERROR] gpioSetMode(%d, PI_OUTPUT) failed\n", ALERT_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(ALERT_GPIO, 0);   /* ensure known state */

    /* --- Log file ------------------------------------------------------ */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[ERROR] fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers --------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGINT) failed: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGTERM) failed: %s\n", strerror(errno));
    }

    printf("Monitoring distance on I2C bus %d, addr 0x%02X.  Alert on GPIO%d.\n",
           I2C_BUS, I2C_ADDR, ALERT_GPIO);
    printf("Threshold: %.1f cm.  Press Ctrl-C to exit.\n", DISTANCE_THRESHOLD);

    /* --- Main loop ----------------------------------------------------- */
    while (g_running) {
        rc = read_distance(&distance);
        if (rc == 0) {
            printf("Distance: %.2f cm\n", distance);
            if (log_distance(distance) != 0) {
                fprintf(stderr, "[WARN] Logging failed; continuing.\n");
            }
            if (distance < DISTANCE_THRESHOLD) {
                gpioWrite(ALERT_GPIO, 1);
                printf("  << ALERT: %.2f cm below %.1f cm threshold >>\n",
                       distance, DISTANCE_THRESHOLD);
            } else {
                gpioWrite(ALERT_GPIO, 0);
            }
        } else {
            /* Sensor absent or bus error: ensure alert is off and log the fault */
            gpioWrite(ALERT_GPIO, 0);
            if (rc < 0) {
                fprintf(stderr, "[ERROR] Sensor read failed; continuing.\n");
            } else {
                fprintf(stderr, "[WARN] Sensor absent or bus error; continuing.\n");
            }
        }
        usleep(POLL_DELAY_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

