/*
 * Parking-assistance system using the STMicroelectronics VL53L1X
 * Time-of-Flight sensor on a Raspberry Pi 3 Model B+.
 *
 * Wiring:
 *   VL53L1X SDA  -> GPIO2 (I2C bus 1 SDA, pin 3)
 *   VL53L1X SCL  -> GPIO3 (I2C bus 1 SCL, pin 5)
 *   VL53L1X VDD  -> 3.3 V (pin 1)
 *   VL53L1X GND  -> GND  (pin 6)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o parking_assist parking_assist.c -lm
 *
 * Run:
 *   ./parking_assist
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <math.h>
#include <pigpio.h>

/* ---- Configuration ---- */
#define I2C_BUS              1
#define VL53L1X_ADDR         0x29
#define LOG_FILE             "distance_log.csv"
#define POLL_INTERVAL_US     100000          /* 100 ms */
#define MEAS_TIMEOUT_MS      100             /* max wait for a single measurement */

/* ---- VL53L1X register map (16-bit addresses, big-endian on the wire) ---- */
#define VL53L1X_REG_SOFT_RESET              0x0003
#define VL53L1X_REG_SYSTEM_MODE_START       0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS     0x0089
#define VL53L1X_REG_RESULT_DISTANCE         0x0096

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit register address, then read `len` bytes back.        */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int vl53l1x_read_block(int handle, uint16_t reg, uint8_t *buf, uint8_t len)
{
    char addr[2];
    char data[1 + len];

    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, addr, 1) != 0)
        return -1;

    if (i2cReadDevice(handle, data, len + 1) != (int)(len + 1))
        return -1;

    memcpy(buf, data + 1, len);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit register address, then write `val`.                  */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int vl53l1x_write_reg(int handle, uint16_t reg, uint8_t val)
{
    char addr[2];
    char data[2];

    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;

    data[0] = (reg >> 8) & 0xFF;
    data[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, addr, 1) != 0)
        return -1;

    if (i2cWriteDevice(handle, data, 2) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise the VL53L1X sensor.                                      */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int vl53l1x_init(int handle)
{
    /* Soft reset */
    if (vl53l1x_write_reg(handle, VL53L1X_REG_SOFT_RESET, 0x00) != 0) {
        fprintf(stderr, "VL53L1X soft reset failed: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(10000);  /* 10 ms settle */

    /* Start continuous ranging (mode bit 0 = 1) */
    if (vl53l1x_write_reg(handle, VL53L1X_REG_SYSTEM_MODE_START, 0x01) != 0) {
        fprintf(stderr, "VL53L1X start ranging failed: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(10000);  /* 10 ms for first measurement */
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read distance in millimetres. Returns -1 on error.                 */
/* ------------------------------------------------------------------ */
static int vl53l1x_read_distance(int handle)
{
    uint8_t status = 0;
    uint8_t dist   = 0;

    /* Poll RANGE_STATUS until data-ready (bit 0) */
    for (int i = 0; i < MEAS_TIMEOUT_MS; i++) {
        if (vl53l1x_read_block(handle, VL53L1X_REG_RESULT_RANGE_STATUS, &status, 1) != 0)
            return -1;
        if (status & 0x01)
            break;
        gpioDelay(1000);  /* 1 ms */
    }

    if (!(status & 0x01)) {
        fprintf(stderr, "VL53L1X measurement timeout\n");
        return -1;
    }

    /* Read distance (16-bit, big-endian) */
    if (vl53l1x_read_block(handle, VL53L1X_REG_RESULT_DISTANCE, &dist, 1) != 0)
        return -1;

    return (int)dist;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped distance reading to the log file.             */
/* ------------------------------------------------------------------ */
static int log_distance(FILE *fp, int distance)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(fp, "%s,%d\n", timestamp, distance) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Determine parking guidance message.                               */
/* ------------------------------------------------------------------ */
static const char *determine_guidance(int distance)
{
    if (distance < 300) return "STOP";
    if (distance < 600) return "APPROACH";
    if (distance < 1200) return "SLOW";
    return "CLEAR";
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (bus %d, addr 0x%02X): %s\n",
                I2C_BUS, VL53L1X_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Initialise sensor ---- */
    if (vl53l1x_init(g_i2c_handle) != 0) {
        fprintf(stderr, "VL53L1X initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open log file (append mode) ---- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header only if file is empty */
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,distance_mm\n");
        fflush(g_log_file);
    }

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Parking assistance system started. Press Ctrl+C to exit.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        int distance = vl53l1x_read_distance(g_i2c_handle);

        if (distance < 0) {
            fprintf(stderr, "Read error; continuing...\n");
        } else {
            const char *guidance = determine_guidance(distance);
            printf("Distance: %d mm  %s\n", distance, guidance);
            if (log_distance(g_log_file, distance) != 0)
                fprintf(stderr, "Logging failed\n");
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

