code:
/*
 * CH201 Ultrasonic Time-of-Flight Sensor Reader for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   CH201 SDA  -> GPIO 2 (I2C bus 1 SDA)
 *   CH201 SCL  -> GPIO 3 (I2C bus 1 SCL)
 *   CH201 VDD  -> 3.3 V
 *   CH201 GND  -> GND
 *   LED anode -> GPIO 18 (BCM) via 330 ohm resistor -> 3.3 V
 *   LED cathode -> GND
 *
 * Behavior:
 *   Reads distance every 100 ms, logs (timestamp, distance, blink_freq),
 *   blinks the LED faster as distance decreases (one half-cycle per loop).
 *   Handles I2C errors, SIGINT/SIGTERM, and sensor-absent conditions.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS          "/dev/i2c-1"
#define CH201_I2C_ADDR   0x60
#define LED_GPIO         18
#define BLINK_HALF_MS    100
#define SAMPLE_MS        100
#define MAX_RETRIES      3
#define RETRY_DELAY_MS   10
#define POLL_DELAY_MS    10

/* CH201 register addresses (16-bit, big-endian on the bus) */
#define CH201_REG_DIST_MSB  0x00
#define CH201_REG_DIST_LSB  0x01
#define CH201_REG_CTRL      0x02

/* CTRL register bit masks */
#define CH201_CTRL_MEASURE  0x01
#define CH201_CTRL_RESET    0x80

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1)
        perror("sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) == -1)
        perror("sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg16(int fd, uint16_t reg, uint8_t value)
{
    uint8_t buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (write(fd, buf, sizeof(buf)) == (ssize_t)sizeof(buf))
            return 0;
        fprintf(stderr, "I2C write reg 0x%04X failed (attempt %d/%d): %s\n",
                reg, attempt + 1, MAX_RETRIES, strerror(errno));
        if (attempt < MAX_RETRIES - 1)
            usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

static int i2c_read_reg16(int fd, uint16_t reg, uint8_t *buf, size_t len)
{
    uint8_t addr[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (write(fd, addr, sizeof(addr)) != (ssize_t)sizeof(addr)) {
            fprintf(stderr, "I2C write address 0x%04X failed (attempt %d/%d): %s\n",
                    reg, attempt + 1, MAX_RETRIES, strerror(errno));
            if (attempt < MAX_RETRIES - 1)
                usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        ssize_t n = read(fd, buf, len);
        if (n == (ssize_t)len)
            return 0;
        fprintf(stderr, "I2C read reg 0x%04X failed (attempt %d/%d): got %zd of %zu (%s)\n",
                reg, attempt + 1, MAX_RETRIES, n, len, strerror(errno));
        if (attempt < MAX_RETRIES - 1)
            usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* CH201 sensor abstraction                                             */
/* ------------------------------------------------------------------ */
static int ch201_reset(int fd)
{
    if (i2c_write_reg16(fd, CH201_REG_CTRL, CH201_CTRL_RESET) != 0) {
        fprintf(stderr, "Failed to reset CH201 (CTRL reset bit).\n");
        return -1;
    }
    usleep(10000); /* 10 ms settle after reset */
    return 0;
}

static int ch201_start_measurement(int fd)
{
    return i2c_write_reg16(fd, CH201_REG_CTRL, CH201_CTRL_MEASURE);
}

static int ch201_read_distance(int fd, uint16_t *distance)
{
    uint8_t buf[2];
    if (i2c_read_reg16(fd, CH201_REG_DIST_MSB, buf, sizeof(buf)) != 0)
        return -1;

    *distance = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* LED control                                                         */
/* ------------------------------------------------------------------ */
static void led_set(int gpio, int on)
{
    if (gpioWrite(gpio, on) != 0)
        fprintf(stderr, "Warning: gpioWrite(%d, %d) failed: %s\n",
                gpio, on, strerror(errno));
}

static void led_blink_half_cycle(int gpio, int on_ms)
{
    led_set(gpio, on);
    usleep(on_ms * 1000);
    led_set(gpio, 0);
    usleep((SAMPLE_MS - on_ms) * 1000);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    install_signal_handlers();

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, CH201_I2C_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                CH201_I2C_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Reset sensor */
    if (ch201_reset(g_i2c_fd) != 0) {
        fprintf(stderr, "CH201 not responding at 0x%02X — sensor absent or wiring fault.\n",
                CH201_I2C_ADDR);
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT) failed: %s\n",
                LED_GPIO, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }
    led_set(LED_GPIO, 0);

    printf("CH201 reader started.  I2C 0x%02X  LED GPIO %d  blink ~%d Hz\n",
           CH201_I2C_ADDR, LED_GPIO, 1000000 / SAMPLE_MS);
    fflush(stdout);

    while (g_running) {
        uint16_t distance = 0;
        bool ok = false;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (ch201_start_measurement(g_i2c_fd) == 0) {
                if (ch201_read_distance(g_i2c_fd, &distance) == 0) {
                    ok = true;
                    break;
                }
            }
            usleep(RETRY_DELAY_MS * 1000);
        }

        if (!ok) {
            fprintf(stderr, "Sensor read failed after %d retries; skipping sample.\n",
                    MAX_RETRIES);
            led_blink_half_cycle(LED_GPIO, SAMPLE_MS);
            usleep(POLL_DELAY_MS * 1000);
            continue;
        }

        time_t now = time(NULL);
        double freq = 1000000.0 / (double)distance;
        printf("%ld, Distance: %u mm, LED: %.2f Hz\n",
               (long)now, distance, freq);
        fflush(stdout);

        led_blink_half_cycle(LED_GPIO, SAMPLE_MS);
        usleep(POLL_DELAY_MS * 1000);
    }

    /* Cleanup */
    led_set(LED_GPIO, 0);
    if (g_i2c_fd >= 0)
        close(g_i2c_fd);
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

