code:
/*
 * MLX75030 Time-of-Flight distance logger for Raspberry Pi 3 Model B+
 * I2C bus 1, 100 ms sampling interval, CSV output.
 *
 * Wiring:
 *   MLX75030 SDA  -> GPIO2 (pin 3)
 *   MLX75030 SCL  -> GPIO3 (pin 5)
 *   MLX75030 VDD  -> 3.3 V
 *   MLX75030 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -o mlx75030_logger mlx75030_logger.c -lpigpio -lrt
 * Run:    sudo ./mlx75030_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x60          /* MLX75030 default I2C address */
#define SAMPLE_US      100000        /* 100 ms sampling interval */
#define MEAS_DELAY_US  10000         /* 10 ms measurement settling time */
#define MAX_RETRIES    3
#define LOG_FILE       "distance_log.csv"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int handle, uint8_t cmd)
{
    int rc = i2cWriteByte(handle, cmd);
    if (rc < 0) {
        fprintf(stderr, "[I2C] write cmd 0x%02X failed (rc=%d)\n", cmd, rc);
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int handle, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadDevice(handle, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "[I2C] read failed (rc=%d, expected %u)\n", rc, len);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* MLX75030 measurement                                                */
/* ------------------------------------------------------------------ */
/*
 * Trigger a single measurement and read the 2-byte distance value.
 * Returns 0 on success and stores distance in *out_cm; -1 on error.
 */
static int read_distance_cm(int handle, int *out_cm)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2c_write_cmd(handle, 0x01) < 0) {
            gpioDelay(MEAS_DELAY_US);
            continue;
        }

        gpioDelay(MEAS_DELAY_US);

        uint8_t buf[2];
        if (i2c_read_bytes(handle, buf, sizeof(buf)) < 0) {
            gpioDelay(MEAS_DELAY_US);
            continue;
        }

        uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
        *out_cm = (int)raw;
        return 0;
    }

    fprintf(stderr, "[MLX75030] measurement failed after %d attempts\n", MAX_RETRIES);
    return -1;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_data(const char *filename, int distance_cm)
{
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        perror("[LOG] fopen");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("[LOG] localtime_r");
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "[LOG] strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s,%d\n", ts, distance_cm) < 0) {
        perror("[LOG] fprintf");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("[LOG] fclose");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- open I2C --- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[SIG] sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MLX75030 distance logger started.  Bus %d, addr 0x%02X, "
           "logging to %s.  Press Ctrl-C to stop.\n",
           I2C_BUS, I2C_ADDR, LOG_FILE);

    /* --- main loop --- */
    while (g_running) {
        int distance_cm = 0;

        if (read_distance_cm(g_i2c_handle, &distance_cm) == 0) {
            printf("Distance: %d cm\n", distance_cm);
            if (log_data(LOG_FILE, distance_cm) < 0) {
                fprintf(stderr, "[LOG] write failed; continuing\n");
            }
        } else {
            fprintf(stderr, "[MLX75030] read failed; will retry next cycle\n");
        }

        /* sleep SAMPLE_US, but wake early on signal */
        for (int i = 0; i < 10 && g_running; i++) {
            gpioDelay(100000); /* 100 ms slices */
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

