        uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
        *out_cm = (int)raw;
        return 0;
    }

    fprintf(stderr, "[MLX75030] measurement failed after %d attempts\n", MAX_RETRIES);
    return -1;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_data(const char *filename, int distance_cm)
{
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        perror("[LOG] fopen");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("[LOG] localtime_r");
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "[LOG] strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s,%d\n", ts, distance_cm) < 0) {
        perror("[LOG] fprintf");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("[LOG] fclose");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- open I2C --- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[SIG] sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MLX75030 distance logger started.  Bus %d, addr 0x%02X, "
           "logging to %s.  Press Ctrl-C to stop.\n",
           I2C_BUS, I2C_ADDR, LOG_FILE);

    /* --- main loop --- */
    while (g_running) {
        int distance_cm = 0;

        if (read_distance_cm(g_i2c_handle, &distance_cm) == 0) {
            printf("Distance: %d cm\n", distance_cm);
            if (log_data(LOG_FILE, distance_cm) < 0) {
                fprintf(stderr, "[LOG] write failed; continuing\n");
            }
        } else {
            fprintf(stderr, "[MLX75030] read failed; will retry next cycle\n");
        }

        /* sleep SAMPLE_US, but wake early on signal */
        for (int i = 0; i < 10 && g_running; i++) {
            gpioDelay(100000); /* 100 ms slices */
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

