        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d\n", SENSOR_1_GPIO);
        goto cleanup;
    }
    if (gpioSetMode(SENSOR_2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d\n", SENSOR_2_GPIO);
        goto cleanup;
    }

    if (gpioSetPullUpDown(SENSOR_1_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for GPIO %d\n", SENSOR_1_GPIO);
        goto cleanup;
    }
    if (gpioSetPullUpDown(SENSOR_2_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for GPIO %d\n", SENSOR_2_GPIO);
        goto cleanup;
    }

    printf("Proximity detection started. Press Ctrl+C to exit.\n");

    while (program_running) {
        current_state_1 = read_sensor(SENSOR_1_GPIO);
        current_state_2 = read_sensor(SENSOR_2_GPIO);

        if (current_state_1 < 0 || current_state_2 < 0) {
            fprintf(stderr, "Error: sensor read failed, exiting\n");
            break;
        }

        if (current_state_1 != prev_state_1) {
            if (log_event(1, current_state_1 == 0 ? "DETECTED" : "CLEARED") != 0) {
                fprintf(stderr, "Error: failed to log event for sensor 1\n");
            }
            prev_state_1 = current_state_1;
        }

        if (current_state_2 != prev_state_2) {
            if (log_event(2, current_state_2 == 0 ? "DETECTED" : "CLEARED") != 0) {
                fprintf(stderr, "Error: failed to log event for sensor 2\n");
            }
            prev_state_2 = current_state_2;
        }

        gpioDelay(POLL_MS * 1000);
    }

cleanup:
    if (log_file != NULL) {
        if (fclose(log_file) != 0) {
            perror("Error closing log file");
        }
        log_file = NULL;
    }
    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return EXIT_SUCCESS;
}

