#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define CH101_I2C_ADDR  0x60
#define MEAS_STATUS_REG 0x00
#define MEAS_READY_MASK 0x01
#define SAMPLE_INTERVAL_US 500000
#define MEAS_TIMEOUT_US   50000

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo) {
    (void)signo;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t val;
    if (read(fd, &val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = val;
    return 0;
}

static int ch101_read_distance_mm(int fd, int *distance_mm) {
    uint8_t status;
    int elapsed = 0;

    while (elapsed < MEAS_TIMEOUT_US) {
        if (i2c_read_reg8(fd, MEAS_STATUS_REG, &status) < 0)
            return -1;
        if (status & MEAS_READY_MASK)
            break;
        usleep(1000);
        elapsed += 1000;
    }

    if (elapsed >= MEAS_TIMEOUT_US) {
        fprintf(stderr, "CH101 measurement timeout\n");
        return -1;
    }

    uint8_t raw;
    if (i2c_read_reg8(fd, MEAS_STATUS_REG, &raw) < 0)
        return -1;

    *distance_mm = (int)raw;
    return 0;
}

static int log_data(FILE *fp, int distance_mm) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }
    if (fprintf(fp, "%s,%d\n", ts, distance_mm) < 0) {
        fprintf(stderr, "fprintf to CSV failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return 1;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, CH101_I2C_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n", CH101_I2C_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    FILE *fp = fopen("distance_log.csv", "a");
    if (!fp) {
        fprintf(stderr, "fopen(distance_log.csv) failed: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    while (g_running) {
        int distance_mm;
        if (ch101_read_distance_mm(fd, &distance_mm) < 0) {
            fprintf(stderr, "Skipping sample due to I2C error\n");
        } else {
            if (log_data(fp, distance_mm) < 0) {
                fprintf(stderr, "Skipping log entry due to file error\n");
            }
        }
        usleep(SAMPLE_INTERVAL_US);
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose failed: %s\n", strerror(errno));
    }
    if (close(fd) < 0) {
        fprintf(stderr, "close(fd) failed: %s\n", strerror(errno));
    }
    return 0;
}

