#define VL53L5CX_REG_RESULT_RANGE_STATUS_64BIT_ADDR 0x0018
#define VL53L5CX_REG_RESULT_RANGE_VAL_64BIT_ADDR 0x001A

#define VL53L5CX_MODEL_ID 0xEA
#define NUM_ZONES 64

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint16_t reg, uint8_t value) {
    uint8_t buf[3] = { (reg >> 8) & 0xFF, reg & 0xFF, value };
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "I2C write error at reg 0x%04X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint16_t reg, uint8_t *value) {
    uint8_t reg_buf[2] = { (reg >> 8) & 0xFF, reg & 0xFF };
    if (write(fd, reg_buf, 2) != 2) {
        fprintf(stderr, "I2C write (reg select) error at reg 0x%04X: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read error at reg 0x%04X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint16_t reg, uint16_t *value) {
    uint8_t reg_buf[2] = { (reg >> 8) & 0xFF, reg & 0xFF };
    uint8_t data[2];
    if (write(fd, reg_buf, 2) != 2) {
        fprintf(stderr, "I2C write (reg select) error at reg 0x%04X: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, data, 2) != 2) {
        fprintf(stderr, "I2C read error at reg 0x%04X: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (data[0] << 8) | data[1];
    return 0;
}

static int vl53l5cx_init(int fd) {
    uint8_t model_id;
    if (i2c_read_reg8(fd, VL53L5CX_REG_IDENTIFICATION_MODEL_ID, &model_id) < 0) {
        return -1;
    }
