        return -1;
    }

    if (i2c_write_reg8(fd, VL53L5CX_REG_SYSTEM_MODE_START, 0x00) < 0) return -1;
    usleep(10000);

    if (i2c_write_reg8(fd, VL53L5CX_REG_SYSTEM_INTERRUPT_CONFIG, 0x04) < 0) return -1;
    if (i2c_write_reg8(fd, VL53L5CX_REG_SYSTEM_RANGE_CONFIG, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, VL53L5CX_REG_RESULT_RANGE_STATUS, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, VL53L5CX_REG_RESULT_RANGE_VAL, 0x00) < 0) return -1;

    return 0;
}

static int read_range_data(int fd, uint16_t *distances) {
    uint8_t status;
    uint16_t range_val;
    uint8_t status_64bit, range_64bit;

    if (i2c_read_reg8(fd, VL53L5CX_REG_RESULT_RANGE_STATUS, &status) < 0) return -1;
    if (i2c_read_reg16(fd, VL53L5CX_REG_RESULT_RANGE_VAL, &range_val) < 0) return -1;

    if ((status & 0x07) == 0x07) {
        if (i2c_read_reg8(fd, VL53L5CX_REG_RESULT_RANGE_STATUS_64BIT, &status_64bit) < 0) return -1;
        if (i2c_read_reg16(fd, VL53L5CX_REG_RESULT_RANGE_VAL_64BIT, &range_64bit) < 0) return -1;

        if (status_64bit & 0x01) {
            distances[0] = range_64bit;
        }
    } else {
        distances[0] = range_val;
    }

    for (int i = 1; i < NUM_ZONES; i++) {
        if (i2c_read_reg8(fd, VL53L5CX_REG_RESULT_RANGE_STATUS, &status) < 0) return -1;
        if (status & (1 << i)) {
            if (i2c_read_reg16(fd, VL53L5CX_REG_RESULT_RANGE_VAL, &range_val) < 0) return -1;
            distances[i] = range_val;
        } else {
            distances[i] = 0;
        }
    }

    return 0;
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, 0x29C0) < 0) {
        fprintf(stderr, "Failed to acquire I2C bus access: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (vl53l5cx_init(i2c_fd) < 0) {
        fprintf(stderr, "VL53L5CX initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    printf("VL53L5CX initialized. Reading %d zones every 500ms...\n", NUM_ZONES);

    uint16_t distances[NUM_ZONES];
    while (running) {
        if (read_range_data(i2c_fd, distances) == 0) {
            printf("Zone Distances: ");
            for (int i = 0; i < NUM_ZONES; i++) {
                printf("%u ", distances[i]);
            }
            printf("\n");
        } else {
            fprintf(stderr, "Failed to read range data.\n");
        }
        usleep(500000);
    }

    printf("\nExiting gracefully...\n");
    if (i2c_fd >= 0) {
        i2c_write_reg8(i2c_fd, VL53L5CX_REG_SYSTEM_MODE_START, 0x00);
        close(i2c_fd);
    }
    return 0;
}

