/*
 * MLX75030 Time-of-Flight distance reader for Raspberry Pi Zero W
 *
 * Wiring:
 *   MLX75030 SDA  -> GPIO2 (I2C bus 1 SDA, pin 3)
 *   MLX75030 SCL  -> GPIO3 (I2C bus 1 SCL, pin 5)
 *   MLX75030 VDD  -> 3.3 V (pin 1)
 *   MLX75030 GND  -> GND  (pin 6)
 *
 * I2C bus 1, address 0x74 (7-bit).
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o mlx75030_reader mlx75030_reader.c -li2c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>

#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>

#define I2C_BUS        "/dev/i2c-1"
#define MLX75030_ADDR  0x74          /* 7-bit I2C address */

/* MLX75030 register addresses (16-bit, big-endian on the bus) */
#define MLX75030_REG_DISTANCE_H  0x00
#define MLX75030_REG_DISTANCE_L  0x01

#define SAMPLE_PERIOD_MS  100
#define MAX_RETRIES      3
#define RETRY_DELAY_MS   10

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit register address, then read `len` bytes back.       */
/* Returns 0 on success, -1 on error.                                */
/* ------------------------------------------------------------------ */
static int i2c_write_reg_addr(uint16_t reg, uint8_t *buf, size_t len)
{
    if (len == 0) {
        if (write(g_i2c_fd, &reg, sizeof(reg)) != (ssize_t)sizeof(reg)) {
            fprintf(stderr, "I2C write of register 0x%04X failed: %s\n",
                    reg, strerror(errno));
            return -1;
        }
        return 0;
    }

    if (write(g_i2c_fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read of %zu bytes from 0x%04X failed: %s\n",
                len, reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit big-endian value from a previously written register  */
/* address. Returns 0 on success and stores the value in *out; -1     */
/* on error.                                                  */
/* ------------------------------------------------------------------ */
static int i2c_read_reg16(uint16_t reg, uint16_t *out)
{
    uint8_t buf[2];

    if (i2c_write_reg_addr(reg, buf, sizeof(buf)) != 0)
        return -1;

    if (read(g_i2c_fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C read of 16-bit register 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read distance in millimetres. Returns 0 on success, -1 on error.   */
/* ------------------------------------------------------------------ */
static int read_distance_mm(uint16_t *distance_mm)
{
    for (int attempt = 1; attempt <= MAX_RETRIES; ++attempt) {
        if (i2c_read_reg16(MLX75030_REG_DISTANCE_H, distance_mm) == 0)
            return 0;

        fprintf(stderr, "Retrying distance read (attempt %d/%d)...\n",
                attempt, MAX_RETRIES);
        usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

/* ------------------------------------------------------------------ */
static void print_timestamp_ms(void)
{
    struct timespec ts;
    struct tm tm_info;

    if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
        localtime_r(&ts.tv_sec, &tm_info);
        printf("%04d-%02d-%02d %02d:%02d:%02d.%03ld\n",
               tm_info.tm_year + 1900, tm_info.tm_mon + 1, tm_info.tm_mday,
               tm_info.tm_hour, tm_info.tm_min, tm_info.tm_sec,
               ts.tv_nsec / 1000000);
    } else {
        printf("[timestamp error] ");
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Signal handling for graceful shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus --- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Acquire exclusive access to the MLX75030 slave --- */
    if (ioctl(g_i2c_fd, I2C_SLAVE, MLX75030_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                MLX75030_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("MLX75030 distance reader started on %s (addr 0x%02X).\n",
           I2C_BUS, MLX75030_ADDR);
    printf("Sampling every %d ms. Press Ctrl-C to exit.\n\n",
           SAMPLE_PERIOD_MS);

    /* --- Main sampling loop --- */
    while (g_running) {
        uint16_t dist;

        if (read_distance_mm(&dist) == 0) {
            print_timestamp_ms();
            printf("Distance: %u mm\n", dist);
        } else {
            print_timestamp_ms();
            fprintf(stderr, "Failed to read distance after %d retries.\n",
                    MAX_RETRIES);
        }

        /* Sleep SAMPLE_PERIOD_MS, but wake early if a signal arrives */
        for (int ms = 0; ms < SAMPLE_PERIOD_MS && g_running; ++ms)
            usleep(1000);
    }

    /* --- Graceful cleanup --- */
    printf("\nShutting down...\n");
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    printf("Resources released. Goodbye.\n");
    return EXIT_SUCCESS;
}

