/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Signal handling for graceful shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus --- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Acquire exclusive access to the MLX75030 slave --- */
    if (ioctl(g_i2c_fd, I2C_SLAVE, MLX75030_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                MLX75030_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("MLX75030 distance reader started on %s (addr 0x%02X).\n",
           I2C_BUS, MLX75030_ADDR);
    printf("Sampling every %d ms. Press Ctrl-C to exit.\n\n",
           SAMPLE_PERIOD_MS);

    /* --- Main sampling loop --- */
    while (g_running) {
        uint16_t dist;

        if (read_distance_mm(&dist) == 0) {
            print_timestamp_ms();
            printf("Distance: %u mm\n", dist);
        } else {
            print_timestamp_ms();
            fprintf(stderr, "Failed to read distance after %d retries.\n",
                    MAX_RETRIES);
        }

        /* Sleep SAMPLE_PERIOD_MS, but wake early if a signal arrives */
        for (int ms = 0; ms < SAMPLE_PERIOD_MS && g_running; ++ms)
            usleep(1000);
    }

    /* --- Graceful cleanup --- */
    printf("\nShutting down...\n");
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    printf("Resources released. Goodbye.\n");
    return EXIT_SUCCESS;
}

