/*
 * VL53L4CX distance reader for Raspberry Pi Zero W
 *
 * Wiring:
 *   VL53L4CX SDA  -> GPIO2 (I2C bus 1 SDA)
 *   VL53L4CX SCL  -> GPIO3 (I2C bus 1 SCL)
 *   VL53L4CX VDD  -> 3.3 V
 *   VL53L4CX GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o vl53l4cx_reader vl53l4cx_reader.c -lm
 *
 * Run:
 *   ./vl53l4cx_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ---- VL53L4CX constants (driver register map) ---- */
#define I2C_BUS              1
#define I2C_ADDR             0x29
#define REG_SYSTEM_START     0x00
#define REG_SYSTEM_INTERRUPT 0x01
#define REG_RESULT_RANGE_STATUS 0x14
#define REG_RESULT_DISTANCE   0x1E
#define REG_RESULT_RANGE_STATUS_INT 0x1F

#define POLL_INTERVAL_US     500000   /* 500 ms */
#define MAX_RANGE_MM         4000     /* 4 m round-trip */

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to a 16-bit register address; returns 0 on success. */
static int reg_write_byte(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;

    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "I2C write to reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from a 16-bit register address; returns -1 on error. */
static int reg_read_byte(int handle, uint16_t reg, uint8_t *out)
{
    char addr[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, addr, 2) != 2) {
        fprintf(stderr, "I2C write (addr) for reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    char data;
    if (i2cReadDevice(handle, &data, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *out = (uint8_t)data;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit big-endian register; returns -1 on error. */
static int reg_read_word(int handle, uint16_t reg, uint16_t *out)
{
    uint8_t lo, hi;
    if (reg_read_byte(handle, reg, &lo) != 0)
        return -1;
    if (reg_read_byte(handle, reg + 1, &hi) != 0)
        return -1;
    *out = ((uint16_t)hi << 8) | lo;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise the VL53L4CX: start continuous ranging. */
static int init_sensor(int handle)
{
    /* Clear any stale interrupt and start ranging */
    if (reg_write_byte(handle, REG_SYSTEM_INTERRUPT, 0x00) != 0)
        return -1;
    if (reg_write_byte(handle, REG_SYSTEM_START, 0x01) != 0)
        return -1;

    /* Allow the first measurement to complete */
    gpioDelay(100000); /* 100 ms */
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read distance in millimetres; returns -1 on error. */
static int read_distance(int handle)
{
    uint16_t status;
    uint16_t dist;

    /* Poll interrupt status bit (bit 0) */
    if (reg_read_word(handle, REG_RESULT_RANGE_STATUS_INT, &status) != 0)
        return -1;

    if (!(status & 0x01))
        return 0; /* no new data yet */

    /* Read distance */
    if (reg_read_word(handle, REG_RESULT_DISTANCE, &dist) != 0)
        return -1;

    /* Clear interrupt so the next measurement can signal */
    if (reg_write_byte(handle, REG_SYSTEM_INTERRUPT, 0x00) != 0)
        return -1;

    return (int)dist;
}

/* ------------------------------------------------------------------ */
static void log_data(int distance_mm)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[40];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    printf("Timestamp: %s.%06ld, Distance: %d mm\n",
           timestamp, ts.tv_nsec / 1000, distance_mm);
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open I2C ---- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (bus %d, addr 0x%02X): %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Sensor init ---- */
    if (init_sensor(g_i2c_handle) != 0) {
        fprintf(stderr, "Sensor initialisation failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("VL53L4CX distance reader started. Press Ctrl+C to exit.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        int distance = read_distance(g_i2c_handle);

        if (distance < 0) {
            fprintf(stderr, "I2C read error; continuing.\n");
        } else if (distance > MAX_RANGE_MM) {
            fprintf(stderr, "Distance out of range (%d mm); skipping.\n", distance);
        } else {
            log_data(distance);
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down cleanly.\n");
    cleanup();
    return EXIT_SUCCESS;
}

