#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define BUZZER_GPIO 22
#define DISTANCE_THRESHOLD 100
#define POLL_INTERVAL_MS 500

#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_SYSTEM_MODE_START 0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_DISTANCE 0x0096

#define VL53L1X_MODEL_ID 0xEA

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int gpio_initialized = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(int fd, uint16_t reg, uint8_t value) {
    uint8_t buf[3] = { (reg >> 8) & 0xFF, reg & 0xFF, value };
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "I2C write error at reg 0x%04X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint16_t reg, uint8_t *buf, size_t len) {
    uint8_t reg_buf[2] = { (reg >> 8) & 0xFF, reg & 0xFF };
    if (write(fd, reg_buf, 2) != 2) {
        fprintf(stderr, "I2C write (reg select) error at 0x%04X: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read error at 0x%04X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int vl53l1x_init(int fd) {
    uint8_t model_id = 0;
    if (i2c_read_reg16(fd, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id, 1) < 0) {
        return -1;
    }
    if (model_id != VL53L1X_MODEL_ID) {
        fprintf(stderr, "Unexpected model ID: 0x%02X (expected 0x%02X)\n", model_id, VL53L1X_MODEL_ID);
        return -1;
    }

    if (i2c_write_reg16(fd, VL53L1X_REG_SYSTEM_MODE_START, 0x00) < 0) return -1;
    usleep(10000);

    if (i2c_write_reg16(fd, VL53L1X_REG_SYSTEM_MODE_START, 0x40) < 0) return -1;
    usleep(10000);

    return 0;
}

static int vl53l1x_read_distance(int fd, uint16_t *distance) {
    uint8_t status = 0;
    uint8_t dist_buf[2] = {0};

    if (i2c_read_reg16(fd, VL53L1X_REG_RESULT_RANGE_STATUS, &status, 1) < 0) return -1;
    if ((status & 0x01) == 0) {
        return 1; // No new data yet
    }

    if (i2c_read_reg16(fd, VL53L1X_REG_RESULT_DISTANCE, dist_buf, 2) < 0) return -1;

    *distance = (dist_buf[0] << 8) | dist_buf[1];
    return 0;
}

static void buzzer_on(void) {
    if (gpio_initialized) {
        gpioWrite(BUZZER_GPIO, 1);
    }
}

static void buzzer_off(void) {
    if (gpio_initialized) {
        gpioWrite(BUZZER_GPIO, 0);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, 0x29) < 0) {
        fprintf(stderr, "Failed to acquire I2C bus access: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (vl53l1x_init(i2c_fd) < 0) {
        fprintf(stderr, "VL53L1X initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    gpio_initialized = 1;
    if (gpioSetMode(BUZZER_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output: %s\n", BUZZER_GPIO, strerror(errno));
        close(i2c_fd);
        return 1;
    }
    buzzer_off();

    printf("VL53L1X ranging started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t distance = 0;
        int ret = vl53l1x_read_distance(i2c_fd, &distance);

        if (ret == 0) {
            printf("Distance: %u mm\n", distance);
            if (distance < DISTANCE_THRESHOLD) {
                buzzer_on();
            } else {
                buzzer_off();
            }
        } else if (ret < 0) {
            fprintf(stderr, "Error reading distance, retrying...\n");
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");
    buzzer_off();
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (gpio_initialized) {
        gpioTerminate();
    }
    return 0;
}

