    usleep(10000);

    return 0;
}

static int vl53l1x_read_distance(int fd, uint16_t *distance) {
    uint8_t status = 0;
    uint8_t dist_buf[2] = {0};

    if (i2c_read_reg16(fd, VL53L1X_REG_RESULT_RANGE_STATUS, &status, 1) < 0) return -1;
    if ((status & 0x01) == 0) {
        return 1; // No new data yet
    }

    if (i2c_read_reg16(fd, VL53L1X_REG_RESULT_DISTANCE, dist_buf, 2) < 0) return -1;

    *distance = (dist_buf[0] << 8) | dist_buf[1];
    return 0;
}

static void buzzer_on(void) {
    if (gpio_initialized) {
        gpioWrite(BUZZER_GPIO, 1);
    }
}

static void buzzer_off(void) {
    if (gpio_initialized) {
        gpioWrite(BUZZER_GPIO, 0);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, 0x29) < 0) {
        fprintf(stderr, "Failed to acquire I2C bus access: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (vl53l1x_init(i2c_fd) < 0) {
        fprintf(stderr, "VL53L1X initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    gpio_initialized = 1;
    if (gpioSetMode(BUZZER_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output: %s\n", BUZZER_GPIO, strerror(errno));
        close(i2c_fd);
        return 1;
    }
    buzzer_off();

    printf("VL53L1X ranging started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t distance = 0;
        int ret = vl53l1x_read_distance(i2c_fd, &distance);

        if (ret == 0) {
            printf("Distance: %u mm\n", distance);
            if (distance < DISTANCE_THRESHOLD) {
                buzzer_on();
            } else {
                buzzer_off();
            }
        } else if (ret < 0) {
            fprintf(stderr, "Error reading distance, retrying...\n");
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");
    buzzer_off();
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (gpio_initialized) {
        gpioTerminate();
    }
    return 0;
}

