#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define SERVO_PIN   17

#define MIN_DISTANCE_CM 2.0f
#define MAX_DISTANCE_CM 400.0f
#define MIN_ANGLE_DEG   (-90.0f)
#define MAX_ANGLE_DEG   (+90.0f)
#define SERVO_PULSE_US   1500
#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US  50000   /* 50 ms */
#define LOOP_DELAY_US    200000  /* 200 ms */
#define LOG_FILE        "sensor_data.log"

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN %d as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set SERVO_PIN %d as output.\n", SERVO_PIN);
        gpioTerminate();
        return -1;
    }

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise TRIGGER_PIN low.\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void trigger_sensor(void)
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

/*
 * Returns distance in cm, or -1.0f on timeout / error.
 * Uses a busy-wait loop with a 50 ms timeout to avoid blocking the main thread.
 */
static float read_distance(void)
{
    uint32_t start_tick = 0, end_tick = 0;
    uint32_t elapsed;

    trigger_sensor();

    /* Wait for echo rising edge */
    do {
        elapsed = gpioTick();
        if (elapsed >= ECHO_TIMEOUT_US) {
            return -1.0f;
        }
        if (gpioRead(ECHO_PIN) == 1) {
            start_tick = elapsed;
            break;
        }
    } while (1);

    /* Wait for echo falling edge */
    do {
        elapsed = gpioTick();
        if (elapsed >= ECHO_TIMEOUT_US) {
            return -1.0f;
        }
        if (gpioRead(ECHO_PIN) == 0) {
            end_tick = elapsed;
            return (float)(end_tick - start_tick) / 58.0f;
    } while (1);
}

static float map_distance_to_angle(float distance)
{
    if (distance < MIN_DISTANCE_CM) distance = MIN_DISTANCE_CM;
    if (distance > MAX_DISTANCE_CM) distance = MAX_DISTANCE_CM;

    return (distance - MIN_DISTANCE_CM) /
           (MAX_DISTANCE_CM - MIN_DISTANCE_CM) *
           (MAX_ANGLE_DEG - MIN_ANGLE_DEG) + MIN_ANGLE_DEG;
}

static int set_servo_angle(float angle)
{
    if (angle < MIN_ANGLE_DEG) angle = MIN_ANGLE_DEG;
    if (angle > MAX_ANGLE_DEG) angle = MAX_ANGLE_DEG;

    int pulse = (int)(SERVO_PULSE_US * (angle / 180.0f));
    if (gpioServo(SERVO_PIN, pulse) < 0) {
        fprintf(stderr, "Error: gpioServo failed for angle %.2f deg.\n", angle);
        return -1;
    }
    return 0;
}

static void log_data(float distance, float angle)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: cannot open log file '%s'.\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Distance: %.2f cm, Angle: %.2f deg\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                distance, angle);
    } else {
        fprintf(fp, "Distance: %.2f cm, Angle: %.2f deg\n", distance, angle);
    }

    fclose(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        return EXIT_FAILURE;
    }

    printf("Parking assist system started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float distance = read_distance();

        if (distance < 0.0f) {
            fprintf(stderr, "Warning: sensor read timeout, skipping cycle.\n");
        } else {
            float angle = map_distance_to_angle(distance);
            if (set_servo_angle(angle) < 0) {
                fprintf(stderr, "Warning: servo set failed, continuing.\n");
            }
            log_data(distance, angle);
            printf("Distance: %.2f cm, Angle: %.2f deg\n", distance, angle);
        }

        gpioDelay(LOOP_DELAY_US);
    }

    /* Clean shutdown */
    gpioServo(SERVO_PIN, 0);   /* Stop servo pulses */
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

