#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <mqueue.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS        "/dev/i2c-1"
#define VL53L1X_ADDR   0x29
#define GPIO_BUZZER    23
#define DISTANCE_THRESHOLD 100
#define POLL_INTERVAL_US 50000
#define MEASUREMENT_TIMEOUT_MS 50

#define VL53L1X_REG_SOFT_RESET              0x0000
#define VL53L1X_REG_SYSTEM_MODE_START       0x0001
#define VL53L1X_REG_RESULT_RANGE_STATUS     0x0089
#define VL53L1X_REG_RESULT_DISTANCE         0x0096

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static mqd_t g_mq = (mqd_t)-1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint16_t reg, uint8_t value) {
    uint8_t buf[3] = { (reg >> 8) & 0xFF, reg & 0xFF, value };
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "I2C write to reg 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint16_t reg, uint8_t *value) {
    uint8_t reg_buf[2] = { (reg >> 8) & 0xFF, reg & 0xFF };
    if (write(fd, reg_buf, 2) != 2) {
        fprintf(stderr, "I2C write (reg select) for 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int vl53l1x_init(int fd) {
    if (i2c_write_reg8(fd, VL53L1X_REG_SOFT_RESET, 0x00) < 0) return -1;
    gpioDelay(1000);
    if (i2c_write_reg8(fd, VL53L1X_REG_SOFT_RESET, 0x01) < 0) return -1;
    gpioDelay(10000);

    if (i2c_write_reg8(fd, VL53L1X_REG_SYSTEM_MODE_START, 0x00) < 0) return -1;
    gpioDelay(10000);

    return 0;
}

static int vl53l1x_read_distance(int fd, int *distance) {
    uint8_t status = 0;
    int timeout = MEASUREMENT_TIMEOUT_MS;

    while (timeout-- > 0) {
        if (i2c_read_reg8(fd, VL53L1X_REG_RESULT_RANGE_STATUS, &status) < 0) return -1;
        if (status & 0x01) break;
        gpioDelay(1000);
    }

    if (timeout <= 0) {
        fprintf(stderr, "VL53L1X measurement timeout\n");
        return -1;
    }

    uint8_t dist_buf[2];
    if (i2c_read_reg8(fd, VL53L1X_REG_RESULT_DISTANCE, &dist_buf[0]) < 0) return -1;
    if (i2c_read_reg8(fd, VL53L1X_REG_RESULT_DISTANCE + 1, &dist_buf[1]) < 0) return -1;

    *distance = (dist_buf[0] << 8) | dist_buf[1];
    return 0;
}

static void log_message(const char *message) {
    if (g_mq == (mqd_t)-1) return;
    if (mq_send(g_mq, message, strlen(message), MSG_DONTWAIT) == -1) {
        fprintf(stderr, "Failed to send message to queue: %s\n", strerror(errno));
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, VL53L1X_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire I2C bus access: %s\n", strerror(errno));
        close(g_i2c_fd);
        gpioTerminate();
        return 1;
    }

    if (vl53l1x_init(g_i2c_fd) < 0) {
        fprintf(stderr, "VL53L1X initialisation failed\n");
        close(g_i2c_fd);
        gpioTerminate();
        return 1;
    }

    if (mq_unlink("/var/lib/mq/default") < 0 && errno != ENOENT) {
        perror("mq_unlink");
        close(g_i2c_fd);
        gpioTerminate();
        return 1;
    }

    g_mq = mq_open("/var/lib/mq/default", O_CREAT | O_RDWR, 0666, 0);
    if (g_mq == (mqd_t)-1) {
        fprintf(stderr, "mq_open failed: %s\n", strerror(errno));
        close(g_i2c_fd);
        gpioTerminate();
        return 1;
    }

    if (mq_send(g_mq, "Distance Reading", 10, MQ_DUPSAFE) == -1) {
        fprintf(stderr, "Failed to create message queue: %s\n", strerror(errno));
        mq_close(g_mq);
        g_mq = (mqd_t)-1;
        close(g_i2c_fd);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(GPIO_BUZZER, PI_OUTPUT);
    gpioWrite(GPIO_BUZZER, 0);

    printf("Starting distance monitoring. Press Ctrl+C to exit.\n");

    while (g_running) {
        int distance = 0;
        if (vl53l1x_read_distance(g_i2c_fd, &distance) == 0) {
            char message[64];
            snprintf(message, sizeof(message), "Distance: %d mm", distance);
            log_message(message);

            if (distance < DISTANCE_THRESHOLD) {
                gpioWrite(GPIO_BUZZER, 1);
            } else {
                gpioWrite(GPIO_BUZZER, 0);
            }
        } else {
            gpioWrite(GPIO_BUZZER, 0);
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nCleaning up...\n");
    gpioWrite(GPIO_BUZZER, 0);
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    if (g_mq != (mqd_t)-1) mq_close(g_mq);
    mq_unlink("/var/lib/mq/default");
    gpioTerminate();

    return 0;
}

