/*
 * Parking sensor for Raspberry Pi 3 Model B+
 * HC-SR04 ultrasonic sensor + buzzer on pigpio.
 *
 * Wiring (BCM numbering):
 *   TRIGGER -> GPIO 17 (output)
 *   ECHO    -> GPIO 27 (input, 1.8 kΩ pull-down recommended)
 *   BUZZER  -> GPIO 22 (output)
 *
 * Build:  gcc -O2 -Wall -o parking_sensor parking_sensor.c -lpigpio -lrt
 * Run:    sudo ./parking_sensor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      17
#define ECHO_PIN         27
#define BUZZER_PIN       22

#define SPEED_OF_SOUND   34300.0          /* cm/s at ~20 °C */
#define MIN_DISTANCE_CM  2.0
#define MAX_DISTANCE_CM  400.0
#define THRESHOLD_CM     30.0
#define POLL_DELAY_US    100000           /* 100 ms */
#define TRIGGER_PULSE_US 10               /* 10 µs HIGH pulse */

/* ------------------------------------------------------------------ */
/* Shared state between the ISR and the main thread                   */
/* ------------------------------------------------------------------ */

static volatile uint32_t g_start_tick = 0;
static volatile uint32_t g_end_tick   = 0;
static volatile bool     g_echo_seen  = false;
static volatile bool     g_new_data    = false;
static volatile bool     g_running     = true;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = false;
}

/* ------------------------------------------------------------------ */
/* pigpio alert callback (runs in pigpio thread)                       */
/* ------------------------------------------------------------------ */

static void echo_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        /* Rising edge: echo pulse starts */
        g_start_tick = tick;
        g_echo_seen  = false;
        g_new_data   = false;
    } else if (level == 0 && g_echo_seen) {
        /* Falling edge: echo pulse ends */
        g_end_tick = tick;
        g_echo_seen = false;
        g_new_data = true;
    }
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

static void trigger_sensor(void)
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

/*
 * Returns distance in cm, or -1.0 on timeout / no echo / out-of-range.
 * Uses pigpio's 32-bit microsecond tick, which wraps every ~71.6 min.
 */
static double measure_distance(void)
{
    g_echo_seen = false;
    g_new_data  = false;

    trigger_sensor();

    /* Wait for the echo callback to set g_new_data */
    while (!g_new_data) {
        gpioDelay(1000); /* 1 ms */
    }

    if (!g_echo_seen) {
        fprintf(stderr, "Error: echo pulse not received (sensor absent or wiring fault).\n");
        return -1.0;
    }

    uint32_t elapsed = g_end_tick - g_start_tick; /* correct 32-bit wrap */
    double distance = (elapsed / 1000000.0) * SPEED_OF_SOUND / 2.0;

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        fprintf(stderr, "Warning: distance %.2f cm out of valid range [%.0f-%.0f].\n",
                distance, MIN_DISTANCE_CM, MAX_DISTANCE_CM);
        return -1.0;
    }

    return distance;
}

static void control_buzzer(double distance)
{
    if (distance < THRESHOLD_CM) {
        gpioWrite(BUZZER_PIN, 1);
    } else {
        gpioWrite(BUZZER_PIN, 0);
    }
}

static void cleanup(void)
{
    gpioWrite(BUZZER_PIN, 0);
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO modes --- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: cannot set TRIGGER_PIN %d as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: cannot set ECHO_PIN %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: cannot set BUZZER_PIN %d as output.\n", BUZZER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Pull-down on echo pin (HC-SR04 echo idles low) --- */
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    /* --- Register alert callback for echo pin --- */
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) < 0) {
        fprintf(stderr, "Error: cannot register alert on ECHO_PIN %d.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handler for graceful shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Parking sensor started.  Trigger=GPIO%d  Echo=GPIO%d  Buzzer=GPIO%d\n",
           TRIGGER_PIN, ECHO_PIN, BUZZER_PIN);
    printf("Threshold: %.1f cm.  Press Ctrl+C to exit.\n", THRESHOLD_CM);

    /* --- Main polling loop --- */
    while (g_running) {
        double distance = measure_distance();

        if (distance < 0.0) {
            fprintf(stderr, "Warning: invalid reading, skipping cycle.\n");
        } else {
            printf("Distance: %.2f cm\n", distance);
            control_buzzer(distance);
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

