code:
/*
 * HC-SR04 Ultrasonic Distance Measurement
 * Board:  Raspberry Pi 4 Model B
 * Library: pigpio (modern GPIO API)
 *
 * Wiring:
 *   TRIG -> GPIO 23 (physical pin 16, BCM 23, output)
 *   ECHO -> GPIO 24 (physical pin 18, BCM 24, input, pull-down)
 *   VCC  -> 5 V (sensor module)
 *   GND  -> GND
 *
 * NOTE: The ECHO line is 5 V.  It MUST be level-shifted or divided
 *       to 3.3 V before reaching the Pi’s GPIO input.  The Pi’s
 *       input pins are 3.3 V tolerant only.
 *
 * Build:  gcc -O2 -Wall -Wextra -o hcsr04 hcsr04.c -lpigpio -lrt
 * Run:    sudo ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define TRIG_PIN        23
#define ECHO_PIN        24
#define TRIGGER_PULSE_US 10
#define SAMPLE_PERIOD_US 200000          /* 200 ms between triggers */
#define ECHO_TIMEOUT_US  60000           /* 60 ms max echo wait */
#define MIN_PULSE_US     100             /* noise threshold */
#define MAX_PULSE_US     30000           /* 30 m round-trip */
#define LOG_FILE         "distance_log.txt"

static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

/* Compute the difference between two 32-bit microsecond ticks
 * correctly handling the 32-bit wraparound (~72 min). */
static inline uint32_t tick_diff(uint32_t t1, uint32_t t2)
{
    return t2 - t1;          /* unsigned subtraction wraps correctly */
}

/* Return elapsed microseconds since the last echo edge. */
static inline uint32_t echo_elapsed(void)
{
    static uint32_t last_tick = 0;
    return tick_diff(gpioTick(), last_tick);
}

/* Generate a 10 µs HIGH pulse on TRIG. */
static void trigger_sensor(void)
{
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIG_PIN, 0);
}

/* Append a timestamped distance line to the log file. */
static void log_distance(double distance)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);

    if (g_log) {
        fprintf(g_log, "%s Distance: %.2f cm\n", ts, distance);
        fflush(g_log);
    }
    printf("%s Distance: %.2f cm\n", ts, distance);
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                        */
/* ------------------------------------------------------------------ */

/*
 * pigpio alert callback.
 *   level  0 = rising edge
 *   level  1 = falling edge
 *   tick   32-bit microsecond counter (wraps every ~72 min)
 */
static void echo_callback(int gpio, int level, uint32_t tick)
{
    (void)gpio;

    if (level == 1) {
        /* Rising edge: start of echo pulse */
        last_tick = tick;
    } else if (level == 0) {
        /* Falling edge: end of echo pulse */
        uint32_t elapsed = echo_elapsed();
        if (elapsed > ECHO_TIMEOUT_US) {
            /* No echo received within 60 ms — timeout */
            fprintf(stderr, "Warning: echo timeout (%u µs)\n", elapsed);
            return;
        }

        uint32_t pulse = tick_diff(last_tick, tick);
        if (pulse < MIN_PULSE_US) {
            /* Noise / spurious pulse */
            fprintf(stderr, "Warning: pulse %u µs below threshold\n", pulse);
            return;
        }

        if (pulse > MAX_PULSE_US) {
            /* Object out of range or no object detected */
            fprintf(stderr, "Warning: pulse %u µs exceeds max (%u µs)\n",
                    pulse, MAX_PULSE_US);
            return;
        }

        double distance = (double)pulse * 0.0343;   /* cm per µs */
        log_distance(distance);
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure GPIO pins ---- */
    if (gpioSetMode(TRIG_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: cannot set TRIG_PIN %d as output\n", TRIG_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: cannot set ECHO_PIN %d as input\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Pull-down so the line is defined when the sensor is disconnected. */
    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Warning: gpioSetPullUpDown failed on ECHO_PIN\n");
    }

    /* Ensure trigger starts LOW. */
    gpioWrite(TRIG_PIN, 0);
    gpioDelay(500000);   /* 500 ms settle */

    /* ---- Open log file ---- */
    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        fprintf(stderr, "Error: cannot open %s: %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Register alert callback ---- */
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) < 0) {
        fprintf(stderr, "Error: cannot register alert on ECHO_PIN %d\n", ECHO_PIN);
        fclose(g_log);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: sigaction(SIGTERM) failed: %s\n", strerror(errno));
    }

    printf("HC-SR04 distance measurement started.\n");
    printf("TRIG=GPIO%d  ECHO=GPIO%d  Log=%s\n", TRIG_PIN, ECHO_PIN, LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    /* ---- Main sampling loop ---- */
    while (g_running) {
        trigger_sensor();
        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* ---- Clean shutdown ---- */
    printf("\nShutting down...\n");
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);   /* unregister callback */
    gpioWrite(TRIG_PIN, 0);
    if (g_log) {
        fclose(g_log);
        g_log = NULL;
    }
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

