 *   ECHO -> GPIO 24 (physical pin 18, BCM 24, input, pull-down)
 *   VCC  -> 5 V (sensor module)
 *   GND  -> GND
 *
 * NOTE: The ECHO line is 5 V.  It MUST be level-shifted or divided
 *       to 3.3 V before reaching the Pi’s GPIO input.  The Pi’s
 *       input pins are 3.3 V tolerant only.
 *
 * Build:  gcc -O2 -Wall -Wextra -o hcsr04 hcsr04.c -lpigpio -lrt
 * Run:    sudo ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define TRIG_PIN        23
#define ECHO_PIN        24
#define TRIGGER_PULSE_US 10
#define SAMPLE_PERIOD_US 200000          /* 200 ms between triggers */
#define ECHO_TIMEOUT_US  60000           /* 60 ms max echo wait */
#define MIN_PULSE_US     100             /* noise threshold */
#define MAX_PULSE_US     30000           /* 30 m round-trip */
#define LOG_FILE         "distance_log.txt"

static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

/* Compute the difference between two 32-bit microsecond ticks
 * correctly handling the 32-bit wraparound (~72 min). */
static inline uint32_t tick_diff(uint32_t t1, uint32_t t2)
{
    return t2 - t1;          /* unsigned subtraction wraps correctly */
}

/* Return elapsed microseconds since the last echo edge. */
static inline uint32_t echo_elapsed(void)
{
    static uint32_t last_tick = 0;
    return tick_diff(gpioTick(), last_tick);
}

/* Generate a 10 µs HIGH pulse on TRIG. */
static void trigger_sensor(void)
{
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIG_PIN, 0);
}

/* Append a timestamped distance line to the log file. */
static void log_distance(double distance)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);

    if (g_log) {
        fprintf(g_log, "%s Distance: %.2f cm\n", ts, distance);
        fflush(g_log);
    }
    printf("%s Distance: %.2f cm\n", ts, distance);
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                        */
/* ------------------------------------------------------------------ */

/*
 * pigpio alert callback.
 *   level  0 = rising edge
 *   level  1 = falling edge
 *   tick   32-bit microsecond counter (wraps every ~72 min)
 */
static void echo_callback(int gpio, int level, uint32_t tick)
{
    (void)gpio;

    if (level == 1) {
        /* Rising edge: start of echo pulse */
        last_tick = tick;
    } else if (level == 0) {
        /* Falling edge: end of echo pulse */
        uint32_t elapsed = echo_elapsed();
        if (elapsed > ECHO_TIMEOUT_US) {
            /* No echo received within 60 ms — timeout */
            fprintf(stderr, "Warning: echo timeout (%u µs)\n", elapsed);
            return;
        }

        uint32_t pulse = tick_diff(last_tick, tick);
        if (pulse < MIN_PULSE_US) {
            /* Noise / spurious pulse */
            fprintf(stderr, "Warning: pulse %u µs below threshold\n", pulse);
            return;
        }

        if (pulse > MAX_PULSE_US) {
            /* Object out of range or no object detected */
            fprintf(stderr, "Warning: pulse %u µs exceeds max (%u µs)\n",
                    pulse, MAX_PULSE_US);
            return;
        }

        double distance = (double)pulse * 0.0343;   /* cm per µs */
        log_distance(distance);
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure GPIO pins ---- */
    if (gpioSetMode(TRIG_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: cannot set TRIG_PIN %d as output\n", TRIG_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: cannot set ECHO_PIN %d as input\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Pull-down so the line is defined when the sensor is disconnected. */
    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Warning: gpioSetPullUpDown failed on ECHO_PIN\n");
    }

    /* Ensure trigger starts LOW. */
    gpioWrite(TRIG_PIN, 0);
    gpioDelay(500000);   /* 500 ms settle */

    /* ---- Open log file ---- */
    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        fprintf(stderr, "Error: cannot open %s: %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Register alert callback ---- */
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) < 0) {
        fprintf(stderr, "Error: cannot register alert on ECHO_PIN %d\n", ECHO_PIN);
        fclose(g_log);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: sigaction(SIGTERM) failed: %s\n", strerror(errno));
    }

    printf("HC-SR04 distance measurement started.\n");
    printf("TRIG=GPIO%d  ECHO=GPIO%d  Log=%s\n", TRIG_PIN, ECHO_PIN, LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    /* ---- Main sampling loop ---- */
    while (g_running) {
        trigger_sensor();
        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* ---- Clean shutdown ---- */
    printf("\nShutting down...\n");
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);   /* unregister callback */
    gpioWrite(TRIG_PIN, 0);
    if (g_log) {
        fclose(g_log);
        g_log = NULL;
    }
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

code:
/*
 * Smart Parking Gate Controller for Raspberry Pi 4 Model B
 *
 * Hardware:
 *   - VL53L1X time-of-flight sensor on I2C bus 1 (GPIO2/SDA, GPIO3/SCL)
 *   - VL53L1X SHUTDOWN line tied to GPIO23 (BCM)
 *   - VL53L1X INTERRUPT line tied to GPIO24 (BCM)
 *   - Servo motor control on GPIO18 (BCM) using hardware PWM
 *
 * Behavior:
 *   - Opens gate when an object is detected within 50 cm (hysteresis: close at >60 cm)
 *   - Closes gate when no object is detected or object is >60 cm away
 *   - Logs gate state changes and distance readings to parking_log.txt
 *   - Handles SIGINT/SIGTERM for clean shutdown
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS          1
#define VL53L1X_ADDR     0x29
#define SHUTDOWN_PIN     23
#define INTERRUPT_PIN    24
#define SERVO_PIN        18

#define DISTANCE_THRESHOLD_OPEN  50   /* cm */
#define DISTANCE_THRESHOLD_CLOSE 60   /* cm */

#define LOG_FILE "parking_log.txt"

/* ----------------------------- VL53L1X Registers ----------------------------- */
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID  0x010F
#define VL53L1X_REG_SYSTEM_MODE_START        0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS      0x0089
#define VL53L1X_REG_RESULT_DISTANCE          0x0096

#define VL53L1X_MODEL_ID_EXPECTED 0xEA

/* ----------------------------- Globals ------------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ----------------------------- Prototypes -------------------------------- */
static int  vl53l1x_write16(int fd, uint16_t reg, uint8_t value);
static int  vl53l1x_read16(int fd, uint16_t reg, uint16_t *out);
static int  vl53l1x_read8(int fd, uint16_t reg, uint8_t *out);
static int  vl53l1x_init(int fd);
static int  vl53l1x_read_distance(int fd, uint16_t *distance_cm);
static void log_event(const char *event, uint16_t distance);
static void signal_handler(int sig);
static void cleanup(void);

/* ----------------------------- VL53L1X I2C Helpers ------------------------- */
static int vl53l1x_write16(int fd, uint16_t reg, uint8_t value) {
    uint8_t buf[3] = { (uint8_t)(reg >> 8), (uint8_t)(reg & 0xFF), value };
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "I2C write16 to 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int vl53l1x_read16(int fd, uint16_t reg, uint16_t *out) {
    uint8_t addr[2] = { (uint8_t)(reg >> 8), (uint8_t)(reg & 0xFF) };
    if (write(fd, addr, 2) != 2) {
        fprintf(stderr, "I2C write16-addr to 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t data[2];
    if (read(fd, data, 2) != 2) {
        fprintf(stderr, "I2C read16 from 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

static int vl53l1x_read8(int fd, uint16_t reg, uint8_t *out) {
    uint8_t addr[2] = { (uint8_t)(reg >> 8), (uint8_t)(reg & 0xFF) };
    if (write(fd, addr, 2) != 2) {
        fprintf(stderr, "I2C read8-addr to 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, out, 1) != 1) {
        fprintf(stderr, "I2C read8 from 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ----------------------------- VL53L1X Initialization ----------------------- */
static int vl53l1x_init(int fd) {
    uint16_t model_id = 0;
    if (vl53l1x_read16(fd, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "Failed to read VL53L1X model ID\n");
        return -1;
    }
    if (model_id != VL53L1X_MODEL_ID_EXPECTED) {
        fprintf(stderr, "VL53L1X model ID mismatch: got 0x%04X, expected 0x%02X\n",
                model_id, VL53L1X_MODEL_ID_EXPECTED);
        return -1;
    }
    printf("VL53L1X detected (model ID 0x%04X)\n", model_id);

    /* Start continuous ranging mode */
    if (vl53l1x_write16(fd, VL53L1X_REG_SYSTEM_MODE_START, 0x01) != 0) {
        fprintf(stderr, "Failed to start VL53L1X ranging\n");
        return -1;
    }
    return 0;
}

/* ----------------------------- Distance Reading ---------------------------- */
static int vl53l1x_read_distance(int fd, uint16_t *distance_cm) {
    uint8_t status = 0;
    if (vl53l1x_read8(fd, VL53L1X_REG_RESULT_RANGE_STATUS, &status) != 0) {
        return -1;
    }
    if ((status & 0x01) == 0) {
        /* No new data yet */
        return 1; /* not an error, just no data */
    }
    if (vl53l1x_read16(fd, VL53L1X_REG_RESULT_DISTANCE, distance_cm) != 0) {
        return -1;
    }
    return 0;
}

/* ----------------------------- Logging ------------------------------------- */
static void log_event(const char *event, uint16_t distance) {
    if (!g_log_fp) return;
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) return;
    fprintf(g_log_fp, "%04d-%02d-%02d %02d:%02d:%02d - %s - Distance: %u cm\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, event, distance);
    fflush(g_log_fp);
}

/* ----------------------------- Cleanup ------------------------------------- */
static void cleanup(void) {
    if (g_i2c_fd >= 0) {
        /* Stop ranging */
        (void)vl53l1x_write16(g_i2c_fd, VL53L1X_REG_SYSTEM_MODE_START, 0x00);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    /* Ensure servo is in a safe state */
    gpioServo(SERVO_PIN, 1500); /* 90 degrees */
    gpioTerminate();
}

/* ----------------------------- Signal Handler ------------------------------ */
static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Main ---------------------------------------- */
int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, VL53L1X_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                VL53L1X_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure SHUTDOWN and INTERRUPT pins */
    if (gpioSetMode(SHUTDOWN_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set SHUTDOWN_PIN mode\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(INTERRUPT_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set INTERRUPT_PIN mode\n");
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(SHUTDOWN_PIN, 1); /* sensor off during init */
    gpioSetPullUpDown(INTERRUPT_PIN, PI_PUD_UP);

    /* Initialize sensor */
    if (vl53l1x_init(g_i2c_fd) != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install signal handlers: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Smart Parking Gate Controller running. Press Ctrl+C to exit.\n");

    int gate_open = 0;
    uint16_t distance = 0;

    while (g_running) {
        int rc = vl53l1x_read_distance(g_i2c_fd, &distance);
        if (rc == 0) {
            printf("Distance: %u cm\n", distance);

            if (distance < DISTANCE_THRESHOLD_OPEN && !gate_open) {
                printf("Object detected - opening gate\n");
                log_event("Gate Opened", distance);
                gpioWrite(SHUTDOWN_PIN, 0);
                gpioServo(SERVO_PIN, 500); /* 25 degrees */
                gate_open = 1;
            } else if (distance > DISTANCE_THRESHOLD_CLOSE && gate_open) {
                printf("Object cleared - closing gate\n");
                log_event("Gate Closed", distance);
                gpioWrite(SHUTDOWN_PIN, 1);
                gpioServo(SERVO_PIN, 1500); /* 90 degrees */
                gate_open = 0;
            }
        } else if (rc < 0) {
            fprintf(stderr, "Sensor read error - attempting re-init\n");
            /* Brief pause before retry to avoid log spam */
            gpioDelay(100000); /* 100 ms */
            if (vl53l1x_init(g_i2c_fd) != 0) {
                fprintf(stderr, "Re-init failed, continuing to retry\n");
            }
        }

        gpioDelay(50000); /* 50 ms */
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

