#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS        1
#define VL53L1X_ADDR   0x29
#define GATE_PIN       18
#define INTERLOCK_PIN  19
#define DISTANCE_THRESHOLD_MM 200
#define POLL_INTERVAL_US 500000
#define LOG_FILE "gate_events.log"

/* VL53L1X 16-bit register addresses (pigpio i2cReadWordData sends the 16-bit
 * register address as two bytes, which the sensor expects for 16-bit
 * register accesses. */
#define VL53L1X_REG_SOFT_RESET              0x0000
#define VL53L1X_REG_SYSTEM_MODE_START       0x0001
#define VL53L1X_REG_RANGE_CONFIG_TIMING_BUDGET 0x0008
#define VL53L1X_REG_RESULT_RANGE_STATUS      0x0089
#define VL53L1X_REG_RESULT_DISTANCE          0x0096

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg16(int fd, uint16_t reg, uint8_t value) {
    uint8_t buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    if (write(fd, buf, 3) != 3) {
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint16_t reg, uint8_t *buf, int len) {
    uint8_t addr[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;
    if (write(fd, addr, 2) != 2) {
        return -1;
    }
    if (read(fd, buf, len) != len) {
        return -1;
    }
    return 0;
}

static int vl53l1x_init(int fd) {
    /* Soft reset */
    if (i2c_write_reg16(fd, VL53L1X_REG_SOFT_RESET, 0x00) < 0) {
        fprintf(stderr, "Error: VL53L1X soft reset write failed.\n");
        return -1;
    }
    usleep(10000);

    /* Start continuous ranging */
    if (i2c_write_reg16(fd, VL53L1X_REG_SYSTEM_MODE_START, 0x40) < 0) {
        fprintf(stderr, "Error: VL53L1X start ranging write failed.\n");
        return -1;
    }

    /* Timing budget: 50 ms (0x0032) */
    if (i2c_write_reg16(fd, VL53L1X_REG_RANGE_CONFIG_TIMING_BUDGET, 0x32) < 0) {
        fprintf(stderr, "Error: VL53L1X timing budget write failed.\n");
        return -1;
    }

    return 0;
}

static int read_distance(int fd, uint16_t *distance) {
    uint8_t status_buf[1];
    uint8_t dist_buf[2];

    /* Check range status */
    if (i2c_read_reg16(fd, VL53L1X_REG_RESULT_RANGE_STATUS, status_buf, 1) < 0) {
        return -1;
    }
    if ((status_buf[0] & 0x01) == 0) {
        return 1; /* No new data yet */
    }

    /* Read 2-byte distance */
    if (i2c_read_reg16(fd, VL53L1X_REG_RESULT_DISTANCE, dist_buf, 2) < 0) {
        return -1;
    }
    *distance = (dist_buf[0] << 8) | dist_buf[1];

    /* Clear interrupt by writing to range status */
    i2c_write_reg16(fd, VL53L1X_REG_RESULT_RANGE_STATUS, 0x01);
    return 0;
}

static void log_event(const char *event) {
    if (g_log == NULL) return;
    time_t now = time(NULL);
    struct tm tm_utc;
    gmtime_r(&now, &tm_utc);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);
    fprintf(g_log, "%s: %s\n", ts, event);
    fflush(g_log);
}

static void cleanup(void) {
    if (g_i2c_fd >= 0) {
        i2cClose(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_log != NULL) {
        fclose(g_log);
        g_log = NULL;
    }
    /* Ensure gate is closed before terminating pigpio */
    gpioWrite(GATE_PIN, 0);
    gpioWrite(INTERLOCK_PIN, 1);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus 1.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, VL53L1X_ADDR) < 0) {
        fprintf(stderr, "Error: Failed to acquire I2C bus 1 slave address 0x%02X.\n", VL53L1X_ADDR);
        cleanup();
        return EXIT_FAILURE;
    }

    if (vl53l1x_init(g_i2c_fd) < 0) {
        fprintf(stderr, "Error: VL53L1X initialization failed (sensor may be absent or bus error).\n");
        cleanup();
        return EXIT_FAILURE;
    }

    gpioSetMode(GATE_PIN, PI_OUTPUT);
    gpioSetMode(INTERLOCK_PIN, PI_OUTPUT);
    gpioWrite(GATE_PIN, 0);
    gpioWrite(INTERLOCK_PIN, 1);

    g_log = fopen(LOG_FILE, "a");
    if (g_log == NULL) {
        fprintf(stderr, "Error: Failed to open log file %s.\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Gate control system started. Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t distance = 0;
        int ret = read_distance(g_i2c_fd, &distance);

        if (ret == 0) {
            if (distance > 0 && distance < DISTANCE_THRESHOLD_MM) {
                gpioWrite(GATE_PIN, 1);
                gpioWrite(INTERLOCK_PIN, 0);
                log_event("Gate opened");
            } else {
                gpioWrite(GATE_PIN, 0);
                gpioWrite(INTERLOCK_PIN, 1);
                log_event("Gate closed");
            }
        } else if (ret < 0) {
            fprintf(stderr, "Error: Failed to read distance from VL53L1X.\n");
            log_event("Error: I2C read failure");
        }

        usleep(POLL_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

