/*
 * Raspberry Pi 4 Model B – VL53L1X ToF sensor + DC motor control
 *
 * Wiring:
 *   VL53L1X SDA  -> GPIO2 (I2C bus 1 SDA)
 *   VL53L1X SCL  -> GPIO3 (I2C bus 1 SCL)
 *   VL53L1X VDD  -> 3.3 V
 *   VL53L1X GND  -> GND
 *   Motor FWD   -> GPIO17
 *   Motor BWD   -> GPIO18
 *   Sensor TRIG -> GPIO24 (BCM) – rising edge triggers a reading
 *
 * Build:  gcc -O2 -Wall -o vl53l1x_motor vl53l1x_motor.c -lpigpio -lrt
 * Run:    sudo ./vl53l1x_motor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Configuration ---- */
#define I2C_BUS        1
#define MOTOR_FWD      17
#define MOTOR_BWD      18
#define TRIGGER_PIN    24

#define DISTANCE_LOW   100   /* mm  – forward  */
#define DISTANCE_HIGH  300   /* mm  – backward */
#define POLL_TIMEOUT   100    /* ms  – status-poll timeout */

/* VL53L1X register addresses (16-bit, big-endian on the bus) */
#define VL53L1X_REG_SOFT_RESET              0x0003
#define VL53L1X_REG_SYSTEM_MODE_START       0x0001
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR  0x0086
#define VL53L1X_REG_SYSTEM_INTERRUPT_STATUS 0x0089
#define VL53L1X_REG_RESULT_INTERRUPT_STATUS 0x0089
#define VL53L1X_REG_RESULT_DISTANCE         0x0096
#define VL53L1X_REG_RESULT_RANGE_STATUS      0x0089
#define VL53L1X_REG_SYSTEM_RANGE_CONFIG      0x0080
#define VL53L1X_REG_SYSTEM_INTERRUPT_CONFIG  0x0081
#define VL53L1X_REG_SYSTEM_RANGE_START       0x0000
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR   0x0086

#define VL53L1X_SOFT_RESET_CMD              0x00
#define VL53L1X_START_MEASUREMENT          0x01
#define VL53L1X_STOP_MEASUREMENT           0x00
#define VL53L1X_RANGE_CONFIG_DEFAULT       0x00
#define VL53L1X_INT_STATUS_DATA_READY     0x01

/* ---- Globals ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static int g_motor_fwd  = 0;
static int g_motor_bwd  = 0;

/* ---- Prototypes ---- */
static int  vl53l1x_write16(int handle, uint16_t reg, uint8_t value);
static int  vl53l1x_read16(int handle, uint16_t reg, uint8_t *buf, uint32_t len);
static int  vl53l1x_init(int handle);
static int  vl53l1x_read_distance(int handle, uint16_t *distance);
static void motor_forward(void);
static void motor_backward(void);
static void motor_stop(void);
static void trigger_distance_reading(void);
static void signal_handler(int sig);
static void cleanup(void);

/* ---- I2C helpers ---- */

/*
 * Write a single byte to a 16-bit register address.
 * The VL53L1X expects the 16-bit register address to be sent MSB-first
 * followed by the data byte.  pigpio's i2cWriteByteData sends [reg, val],
 * so we send [reg >> 8, reg & 0xFF, val].
 */
static int vl53l1x_write16(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;

    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "[VL53L1X] I2C write failed (reg=0x%04X, val=0x%02X)\n",
                reg, value);
        return -1;
    }
    return 0;
}

/*
 * Read `len` bytes starting at a 16-bit register address.
 * The VL53L1X returns data MSB-first: send [reg >> 8, reg & 0xFF] then
 * read `len` bytes back.
 */
static int vl53l1x_read16(int handle, uint16_t reg, uint8_t *buf, uint32_t len)
{
    char addr[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, addr, 2) != 2) {
        fprintf(stderr, "[VL53L1X] I2C write (addr) failed for reg=0x%04X\n", reg);
        return -1;
    }

    if (i2cReadDevice(handle, (char *)buf, len) != (int)len) {
        fprintf(stderr, "[VL53L1X] I2C read failed for reg=0x%04X (got %u of %u)\n",
                reg, len, (uint32_t)len);
        return -1;
    }
    return 0;
}

/* ---- VL53L1X driver ---- */

static int vl53l1x_init(int handle)
{
    /* Soft reset */
    if (vl53l1x_write16(handle, VL53L1X_REG_SOFT_RESET, VL53L1X_SOFT_RESET_CMD) != 0)
        return -1;
    gpioDelay(1000);  /* 1 ms */

    /* Clear any pending interrupt */
    if (vl53l1x_write16(handle, VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR,
                        VL53L1X_INT_STATUS_DATA_READY) != 0)
        return -1;

    /* Start continuous ranging (default range config) */
    if (vl53l1x_write16(handle, VL53L1X_REG_SYSTEM_RANGE_START,
                        VL53L1X_RANGE_CONFIG_DEFAULT) != 0)
        return -1;

    return 0;
}

/*
 * Trigger a single distance reading by asserting the TRIG pin.
 * Returns 0 on success, -1 on I2C error.
 */
static int trigger_distance_reading(void)
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(5);  /* >4.5 us trigger pulse */
    gpioWrite(TRIGGER_PIN, 0);
    return 0;
}

/*
 * Read distance in millimetres.
 * Returns 0 on success and stores distance in *distance, -1 on error.
 */
static int vl53l1x_read_distance(int handle, uint16_t *distance)
{
    uint8_t status_buf[1];
    uint8_t dist_buf[2];

    /* Poll status register until data-ready bit is set */
    for (int i = 0; i < POLL_TIMEOUT; i++) {
        if (vl53l1x_read16(handle, VL53L1X_REG_RESULT_INTERRUPT_STATUS,
                           status_buf, 1) != 0)
            return -1;

        if (status_buf[0] & VL53L1X_INT_STATUS_DATA_READY)
            break;

        gpioDelay(1000);  /* 1 ms */
    }

    if (!(status_buf[0] & VL53L1X_INT_STATUS_DATA_READY)) {
        fprintf(stderr, "[VL53L1X] Data-ready timeout\n");
        return -1;
    }

    /* Read 16-bit distance */
    if (vl53l1x_read16(handle, VL53L1X_REG_RESULT_DISTANCE, dist_buf, 2) != 0)
        return -1;

    *distance = ((uint16_t)dist_buf[0] << 8) | dist_buf[1];
    return 0;
}

/* ---- Motor control ---- */

static void motor_forward(void)
{
    if (g_motor_fwd == 0) {
        if (gpioWrite(MOTOR_FWD, 1) == 0 && gpioWrite(MOTOR_BWD, 0) == 0) {
            g_motor_fwd = 1;
            printf("Motor forward\n");
        } else {
            fprintf(stderr, "Failed to set motor forward\n");
        }
    }
}

static void motor_backward(void)
{
    if (g_motor_bwd == 0) {
        if (gpioWrite(MOTOR_BWD, 1) == 0 && gpioWrite(MOTOR_FWD, 0) == 0) {
            g_motor_bwd = 1;
            printf("Motor backward\n");
        } else {
            fprintf(stderr, "Failed to set motor backward\n");
        }
    }
}

static void motor_stop(void)
{
    if (g_motor_fwd == 1) {
        gpioWrite(MOTOR_FWD, 0);
        gpioWrite(MOTOR_BWD, 0);
        g_motor_fwd = 0;
        printf("Motor stopped\n");
    }
    if (g_motor_bwd == 1) {
        gpioWrite(MOTOR_BWD, 0);
        gpioWrite(MOTOR_FWD, 0);
        g_motor_bwd = 0;
        printf("Motor stopped\n");
    }
}

/* ---- ISR ---- */

static void trigger_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio; (void)level; (void)tick; (void)userdata;
    trigger_distance_reading();
}

/* ---- Signal handler ---- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Cleanup ---- */

static void cleanup(void)
{
    motor_stop();

    if (g_i2c_handle >= 0) {
        /* Stop measurement */
        (void)vl53l1x_write16(g_i2c_handle, VL53L1X_REG_SYSTEM_RANGE_START,
                              VL53L1X_STOP_MEASUREMENT);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }

    gpioTerminate();
}

/* ---- Main ---- */

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure motor pins */
    if (gpioSetMode(MOTOR_FWD, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_BWD, PI_OUTPUT) != 0 ||
        gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set motor GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure motor is off at start */
    motor_stop();

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, 0, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d (err=%d)\n", I2C_BUS, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (vl53l1x_init(g_i2c_handle) != 0) {
        fprintf(stderr, "VL53L1X initialisation failed – sensor may be absent or bus error\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register ISR on rising edge */
    if (gpioSetISRFuncEx(TRIGGER_PIN, RISING_EDGE, 0, trigger_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR on GPIO%d\n", TRIGGER_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("VL53L1X motor control running. Press Ctrl+C to exit.\n");

    int distance;
    int motor_state = 0;  /* 0 = stopped, 1 = forward, 2 = backward */

    while (g_running) {
        if (vl53l1x_read_distance(g_i2c_handle, &distance) == 0) {
            printf("Distance: %d mm\n", distance);

            if (distance < DISTANCE_LOW) {
                motor_forward();
                motor_state = 1;
            } else if (distance > DISTANCE_HIGH) {
                motor_backward();
                motor_state = 2;
            } else {
                motor_stop();
                motor_state = 0;
            }
        } else {
            fprintf(stderr, "Distance read failed – stopping motor for safety\n");
            motor_stop();
            motor_state = 0;
        }

        gpioDelay(100000);  /* 100 ms */
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

code:
/*
 * Proximity-based interactive art installation for Raspberry Pi 3 Model B+
 *
 * Hardware:
 *   - MPR121 capacitive touch sensor on /dev/i2c-1 (GPIO 2 = SDA, GPIO 3 = SCL)
 *   - 4-bit LED pattern on GPIO 17 (bit 0), GPIO 18 (bit 1), GPIO 27 (bit 2), GPIO 22 (bit 3)
 *
 * Build:
 *   gcc -O2 -Wall -o art_installation art_installation.c -lpigpio -lrt
 * Run:
 *   sudo ./art_installation
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS          "/dev/i2c-1"
#define MPR121_ADDR      0x60

/* MPR121 register addresses */
#define MPR121_TOUCHSTATUS_L  0x00
#define MPR121_TOUCHSTATUS_H  0x01
#define MPR121_ELECONFIG      0x5E
#define MPR121_SOFTRESET      0x80

/* LED GPIO pins (BCM numbering) */
#define LED_PIN_0   17
#define LED_PIN_1   18
#define LED_PIN_2   27
#define LED_PIN_3   22

/* Proximity threshold: any electrode with a non-zero bit in the 12-bit
 * touch status is considered "proximate". */
#define PROXIMITY_THRESHOLD 0x0FFF

/* Polling interval (microseconds) */
#define POLL_INTERVAL_US 50000

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ----------------------------- Prototypes ------------------------------- */
static void signal_handler(int sig);
static int  mpr121_write_reg(int fd, uint8_t reg, uint8_t value);
static int  mpr121_read_reg(int fd, uint8_t reg, uint8_t *value);
static int  mpr121_init(int fd);
static int  mpr121_read_touch(int fd, uint16_t *touch_status);
static void led_set_pattern(uint8_t pattern);
static void log_event(uint16_t touch_status);
static void cleanup(void);

/* ----------------------------- Signal handler --------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- I2C helpers ------------------------------- */
static int mpr121_write_reg(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int mpr121_read_reg(int fd, uint8_t reg, uint8_t *value)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ----------------------------- MPR121 initialization --------------------- */
static int mpr121_init(int fd)
{
    /* Soft reset */
    if (mpr121_write_reg(fd, MPR121_SOFTRESET, 0x63) < 0)
        return -1;
    usleep(10000); /* 10 ms settle after reset */

    /* Put sensor in stop mode so configuration changes take effect */
    if (mpr121_write_reg(fd, MPR121_ELECONFIG, 0x00) < 0)
        return -1;

    /* Enable all 12 electrodes, baseline tracking, 16 µA charge current */
    uint8_t config = 0x0C; /* ELECONFIG: CL=10 (16 µA), ELEPROX=12, ELE_EN=1 */
    if (mpr121_write_reg(fd, MPR121_ELECONFIG, config) < 0)
        return -1;

    return 0;
}

/* ----------------------------- Touch status read ------------------------ */
static int mpr121_read_touch(int fd, uint16_t *touch_status)
{
    uint8_t lo, hi;
    if (mpr121_read_reg(fd, MPR121_TOUCHSTATUS_L, &lo) < 0)
        return -1;
    if (mpr121_read_reg(fd, MPR121_TOUCHSTATUS_H, &hi) < 0)
        return -1;

    *touch_status = ((uint16_t)hi << 8) | lo;
    return 0;
}

/* ----------------------------- LED pattern -------------------------------- */
static void led_set_pattern(uint8_t pattern)
{
    gpioWrite(LED_PIN_0, (pattern >> 0) & 1);
    gpioWrite(LED_PIN_1, (pattern >> 1) & 1);
    gpioWrite(LED_PIN_2, (pattern >> 2) & 1);
    gpioWrite(LED_PIN_3, (pattern >> 3) & 1);
}

/* ----------------------------- Logging ----------------------------------- */
static void log_event(uint16_t touch_status)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(g_log_fp, "%s - Touch status: 0x%04X\n", timestamp, touch_status);
    fflush(g_log_fp);
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    /* gpioTerminate is safe to call even if some pins were never set */
    gpioTerminate();
}

/* ----------------------------- Main ------------------------------------- */
int main(void)
{
    /* Open log file */
    g_log_fp = fopen("art_installation.log", "a");
    if (!g_log_fp) {
        perror("Error opening log file");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("Error opening I2C bus " I2C_BUS);
        fclose(g_log_fp);
        g_log_fp = NULL;
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        perror("Error setting I2C slave address");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Verify sensor presence with a read-back of the soft-reset register */
    uint8_t soft_reset_val = 0;
    if (mpr121_read_reg(g_i2c_fd, MPR121_SOFTRESET, &soft_reset_val) < 0) {
        fprintf(stderr, "MPR121 not detected at address 0x%02X on %s\n",
                MPR121_ADDR, I2C_BUS);
        cleanup();
        return EXIT_FAILURE;
    }
    if (soft_reset_val != MPR121_SOFTRESET) {
        fprintf(stderr, "MPR121 soft-reset read-back mismatch: got 0x%02X, expected 0x%02X\n",
                soft_reset_val, MPR121_SOFTRESET);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize MPR121 */
    if (mpr121_init(g_i2c_fd) < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO pins */
    if (gpioSetMode(LED_PIN_0, PI_OUTPUT) < 0 ||
        gpioSetMode(LED_PIN_1, PI_OUTPUT) < 0 ||
        gpioSetMode(LED_PIN_2, PI_OUTPUT) < 0 ||
        gpioSetMode(LED_PIN_3, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set LED GPIO modes\n");
        cleanup();
        return EXIT_FAILURE;
    }
    led_set_pattern(0x00);

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
