/*
 * Proximity-based interactive art installation for Raspberry Pi 3 Model B+
 *
 * Hardware:
 *   - MPR121 capacitive touch sensor on /dev/i2c-1 (GPIO 2 = SDA, GPIO 3 = SCL)
 *   - 4-bit LED pattern on GPIO 17 (bit 0), GPIO 18 (bit 1), GPIO 27 (bit 2), GPIO 22 (bit 3)
 *
 * Build:
 *   gcc -O2 -Wall -o art_installation art_installation.c -lpigpio -lrt
 * Run:
 *   sudo ./art_installation
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS          "/dev/i2c-1"
#define MPR121_ADDR      0x60

/* MPR121 register addresses */
#define MPR121_TOUCHSTATUS_L  0x00
#define MPR121_TOUCHSTATUS_H  0x01
#define MPR121_ELECONFIG      0x5E
#define MPR121_SOFTRESET      0x80

/* LED GPIO pins (BCM numbering) */
#define LED_PIN_0   17
#define LED_PIN_1   18
#define LED_PIN_2   27
#define LED_PIN_3   22

/* Proximity threshold: any electrode with a non-zero bit in the 12-bit
 * touch status is considered "proximate". */
#define PROXIMITY_THRESHOLD 0x0FFF

/* Polling interval (microseconds) */
#define POLL_INTERVAL_US 50000

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ----------------------------- Prototypes ------------------------------- */
static void signal_handler(int sig);
static int  mpr121_write_reg(int fd, uint8_t reg, uint8_t value);
static int  mpr121_read_reg(int fd, uint8_t reg, uint8_t *value);
static int  mpr121_init(int fd);
static int  mpr121_read_touch(int fd, uint16_t *touch_status);
static void led_set_pattern(uint8_t pattern);
static void log_event(uint16_t touch_status);
static void cleanup(void);

/* ----------------------------- Signal handler --------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- I2C helpers ------------------------------- */
static int mpr121_write_reg(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int mpr121_read_reg(int fd, uint8_t reg, uint8_t *value)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ----------------------------- MPR121 initialization --------------------- */
static int mpr121_init(int fd)
{
    /* Soft reset */
    if (mpr121_write_reg(fd, MPR121_SOFTRESET, 0x63) < 0)
        return -1;
    usleep(10000); /* 10 ms settle after reset */

    /* Put sensor in stop mode so configuration changes take effect */
    if (mpr121_write_reg(fd, MPR121_ELECONFIG, 0x00) < 0)
        return -1;

    /* Enable all 12 electrodes, baseline tracking, 16 µA charge current */
    uint8_t config = 0x0C; /* ELECONFIG: CL=10 (16 µA), ELEPROX=12, ELE_EN=1 */
    if (mpr121_write_reg(fd, MPR121_ELECONFIG, config) < 0)
        return -1;

    return 0;
}

/* ----------------------------- Touch status read ------------------------ */
static int mpr121_read_touch(int fd, uint16_t *touch_status)
{
    uint8_t lo, hi;
    if (mpr121_read_reg(fd, MPR121_TOUCHSTATUS_L, &lo) < 0)
        return -1;
    if (mpr121_read_reg(fd, MPR121_TOUCHSTATUS_H, &hi) < 0)
        return -1;

    *touch_status = ((uint16_t)hi << 8) | lo;
    return 0;
}

/* ----------------------------- LED pattern -------------------------------- */
static void led_set_pattern(uint8_t pattern)
{
    gpioWrite(LED_PIN_0, (pattern >> 0) & 1);
    gpioWrite(LED_PIN_1, (pattern >> 1) & 1);
    gpioWrite(LED_PIN_2, (pattern >> 2) & 1);
    gpioWrite(LED_PIN_3, (pattern >> 3) & 1);
}

/* ----------------------------- Logging ----------------------------------- */
static void log_event(uint16_t touch_status)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(g_log_fp, "%s - Touch status: 0x%04X\n", timestamp, touch_status);
    fflush(g_log_fp);
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    /* gpioTerminate is safe to call even if some pins were never set */
    gpioTerminate();
}

/* ----------------------------- Main ------------------------------------- */
int main(void)
{
    /* Open log file */
    g_log_fp = fopen("art_installation.log", "a");
    if (!g_log_fp) {
        perror("Error opening log file");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("Error opening I2C bus " I2C_BUS);
        fclose(g_log_fp);
        g_log_fp = NULL;
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        perror("Error setting I2C slave address");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Verify sensor presence with a read-back of the soft-reset register */
    uint8_t soft_reset_val = 0;
    if (mpr121_read_reg(g_i2c_fd, MPR121_SOFTRESET, &soft_reset_val) < 0) {
        fprintf(stderr, "MPR121 not detected at address 0x%02X on %s\n",
                MPR121_ADDR, I2C_BUS);
        cleanup();
        return EXIT_FAILURE;
    }
    if (soft_reset_val != MPR121_SOFTRESET) {
        fprintf(stderr, "MPR121 soft-reset read-back mismatch: got 0x%02X, expected 0x%02X\n",
                soft_reset_val, MPR121_SOFTRESET);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize MPR121 */
    if (mpr121_init(g_i2c_fd) < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO pins */
    if (gpioSetMode(LED_PIN_0, PI_OUTPUT) < 0 ||
        gpioSetMode(LED_PIN_1, PI_OUTPUT) < 0 ||
        gpioSetMode(LED_PIN_2, PI_OUTPUT) < 0 ||
        gpioSetMode(LED_PIN_3, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set LED GPIO modes\n");
        cleanup();
        return EXIT_FAILURE;
    }
    led_set_pattern(0x00);

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Art installation running. Press Ctrl+C to exit.\n");
    printf("I2C bus: %s | MPR121 addr: 0x%02X | LEDs on GPIO %d, %d, %d, %d\n",
           I2C_BUS, MPR121_ADDR, LED_PIN_0, LED_PIN_1, LED_PIN_2, LED_PIN_3);

    /* Main polling loop */
    while (g_running) {
        uint16_t touch_status = 0;

        if (mpr121_read_touch(g_i2c_fd, &touch_status) < 0) {
            fprintf(stderr, "Touch sensor read error; continuing...\n");
            usleep(POLL_INTERVAL_US);
            continue;
        }

        /* Check if any electrode is proximate */
        uint8_t pattern = 0;
        for (uint16_t mask = PROXIMITY_THRESHOLD; mask != 0; mask >>= 1) {
            if (touch_status & mask) {
                pattern |= (uint8_t)(mask & 0x0F);
            }
        }

        led_set_pattern(pattern);
        log_event(touch_status);

        usleep(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

