/*
 * MPR121 Capacitive Proximity Detector for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   MPR121 SDA -> GPIO 2 (I2C bus 1 SDA)
 *   MPR121 SCL -> GPIO 3 (I2C bus 1 SCL)
 *   MPR121 VDD -> 3.3V
 *   MPR121 GND -> GND
 *   LED Anode -> GPIO 27 (BCM) via 330 ohm resistor
 *   LED Cathode -> GND
 *
 * Build: gcc -Wall -o proximity proximity.c -lpigpio -lrt
 * Run:   sudo ./proximity
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MPR121_ADDR 0x60
#define LED_GPIO 27

/* MPR121 Register Addresses */
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ECR           0x5E
#define MPR121_CONFIG1       0x5B
#define MPR121_CONFIG2       0x5C
#define MPR121_MHD_F        0x2B
#define MPR121_NHD_F        0x2C
#define MPR121_NCL_F        0x2D
#define MPR121_FDL_F        0x2E
#define MPR121_MHD_R        0x2F
#define MPR121_NHD_R        0x30
#define MPR121_NCL_R        0x31
#define MPR121_FDL_R        0x32
#define MPR121_E0TTH        0x41
#define MPR121_E0RTH        0x42
#define MPR121_DEBOUNCE     0x5B
#define MPR121_AFE_CONFIG   0x5D
#define MPR121_SOFTRESET    0x80

#define PROXIMITY_THRESHOLD 50
#define LED_ON_TIME_MS 1000
#define LOG_FILE "proximity.log"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int mpr121_write(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg=0x%02X, val=0x%02X): %d\n", reg, value, rc);
    }
    return rc;
}

static int mpr121_read(uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg=0x%02X): %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int mpr121_init(void) {
    uint8_t whoami = 0;

    /* Soft reset */
    if (mpr121_write(MPR121_SOFTRESET, 0x63) < 0) return -1;
    gpioDelay(10000); /* 10 ms settle */

    /* Verify device ID */
    if (mpr121_read(MPR121_SOFTRESET, &whoami) < 0) return -1;
    if (whoami != 0x63) {
        fprintf(stderr, "MPR121 not detected (ID=0x%02X, expected 0x63)\n", whoami);
        return -1;
    }

    /* AFE config: FFI=6 samples, SFI=4 samples, ESI=4 ms */
    if (mpr121_write(MPR121_AFE_CONFIG, 0x0C) < 0) return -1;

    /* Touch / release thresholds for all 12 electrodes */
    for (int i = 0; i < 12; i++) {
        if (mpr121_write(MPR121_E0TTH + (i * 2), 400) < 0) return -1;
        if (mpr121_write(MPR121_E0RTH + (i * 2), 200) < 0) return -1;
    }

    /* Debounce: 3 samples for touch, 3 for release */
    if (mpr121_write(MPR121_DEBOUNCE, 0x33) < 0) return -1;

    /* FFI=6, SFI=4, ESI=4 ms, baseline tracking enabled */
    if (mpr121_write(MPR121_CONFIG1, 0x10) < 0) return -1;

    /* FFI=6, SFI=4, ESI=4 ms, baseline tracking enabled */
    if (mpr121_write(MPR121_CONFIG2, 0x10) < 0) return -1;

    /* Enable 12 electrodes, baseline tracking */
    if (mpr121_write(MPR121_ECR, 0x8C) < 0) return -1;

    return 0;
}

static void log_proximity_event(void) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[64];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s: Proximity detected\n", ts);
    } else {
        fprintf(fp, "[timestamp error]: Proximity detected\n");
    }

    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (mpr121_init() < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    printf("Proximity detection started. Press Ctrl+C to exit.\n");

    while (running) {
        uint8_t touch_status = 0;
        if (mpr121_read(MPR121_TOUCHSTATUS_L, &touch_status) < 0) {
            gpioDelay(100000); /* 100 ms backoff on error */
            continue;
        }

        for (int i = 0; i < 12; i++) {
            if (touch_status & (1 << i)) {
                printf("Proximity detected on electrode %d\n", i);
                gpioWrite(LED_GPIO, 1);
                log_proximity_event();
                gpioDelay(LED_ON_TIME_MS * 1000);
                gpioWrite(LED_GPIO, 0);
                break;
            }
        }

        gpioDelay(50000); /* 50 ms poll interval */
    }

    printf("\nShutting down...\n");
    gpioWrite(LED_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

