/*
 * HC-SR04 ultrasonic distance measurement on Raspberry Pi Zero W.
 *
 * Wiring:
 *   TRIG -> GPIO17 (BCM)
 *   ECHO -> GPIO18 (BCM) via 1k/2k voltage divider (keeps Pi input at ~3.3 V)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o distance_log distance_log.c -lpigpio -lrt
 *   (run as root or with gpio group access)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIG_PIN        17
#define ECHO_PIN        18

#define TRIGGER_PULSE_US  10
#define SAMPLE_PERIOD_S   1.0
#define LOG_FILE_NAME     "distance_log.txt"

/* Speed of sound: 343 m/s = 0.0343 cm/us.  Distance = (time_us * 0.0343) / 2 */
#define SPEED_OF_SOUND_CM_PER_US  0.0343
#define DISTANCE_THRESHOLD_CM    400.0   /* 4 m — beyond sensor's rated range */

/* Sanity bounds for echo pulse width (us) */
#define MIN_PULSE_US  58
#define MAX_PULSE_US  25000

/* ISR state */
typedef struct {
    volatile uint32_t start_tick;
    volatile uint32_t end_tick;
    volatile bool     got_rising;
    volatile bool     got_falling;
} echo_state_t;

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* pigpio ISR callback — runs in a pigpio worker thread.               */
/* ------------------------------------------------------------------ */
static void echo_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    echo_state_t *st = (echo_state_t *)userdata;

    if (level == 1) {
        st->start_tick  = tick;
        st->got_rising  = true;
        st->got_falling = false;
    } else if (level == 0) {
        st->end_tick    = tick;
        st->got_falling = true;
    }
}

/* ------------------------------------------------------------------ */
/* Compute elapsed microseconds between two 32-bit ticks (handles wrap). */
/* ------------------------------------------------------------------ */
static uint32_t tick_diff(uint32_t t1, uint32_t t2)
{
    return t2 - t1;  /* unsigned subtraction wraps correctly */
}

/* ------------------------------------------------------------------ */
/* Trigger a 10 us pulse on TRIG.                                    */
/* ------------------------------------------------------------------ */
static void trigger_sensor(void)
{
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIG_PIN, 0);
}

/* ------------------------------------------------------------------ */
/* Convert pulse width (us) to distance (cm).                         */
/* ------------------------------------------------------------------ */
static double pulse_to_cm(uint32_t pulse_us)
{
    if (pulse_us == 0)
        return -1.0;
    return (double)pulse_us * SPEED_OF_SOUND_CM_PER_US / 2.0;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped reading to the log file.                      */
/* ------------------------------------------------------------------ */
static void log_distance(double distance_cm)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    if (g_log_file != NULL) {
        fprintf(g_log_file, "%s, Distance: %.2f cm\n", ts, distance_cm);
        fflush(g_log_file);
    } else {
        fprintf(stderr, "Log file not open\n");
    }
}

/* ------------------------------------------------------------------ */
/* pigpio cleanup — disable ISR and terminate pigpio.                */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, NULL, NULL);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Signal handlers ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure GPIO pins ---- */
    if (gpioSetMode(TRIG_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set TRIG_PIN %d as output\n", TRIG_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set ECHO_PIN %d as input\n", ECHO_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts LOW */
    gpioWrite(TRIG_PIN, 0);
    gpioDelay(50 * 1000);  /* 50 ms settle */

    /* ---- Register ISR ---- */
    if (gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, echo_callback, NULL) != 0) {
        fprintf(stderr, "Failed to register ISR on ECHO_PIN %d\n", ECHO_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        perror("fopen(" LOG_FILE_NAME ")");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance logger started.  TRIG=GPIO%d  ECHO=GPIO%d\n",
           TRIG_PIN, ECHO_PIN);
    printf("Logging to %s every %.1f s.  Press Ctrl-C to stop.\n",
           LOG_FILE_NAME, SAMPLE_PERIOD_S);

    /* ---- Main sampling loop ---- */
    while (g_running) {
        trigger_sensor();

        /* Wait for echo callback to complete (max ~50 ms) */
        gpioDelay(50000);

        echo_state_t *st = (echo_state_t *)gpioGetISRFuncData(ECHO_PIN);
        if (st == NULL) {
            fprintf(stderr, "gpioGetISRFuncData failed\n");
            break;
        }

        uint32_t pulse_us = tick_diff(st->start_tick, st->end_tick);

        if (pulse_us == 0) {
            fprintf(stderr, "Invalid pulse width (%u us)\n", pulse_us);
            continue;
        }

        if (pulse_us < MIN_PULSE_US || pulse_us > MAX_PULSE_US) {
            fprintf(stderr, "Pulse %u us out of range [%.0f, %.0f]\n",
                    pulse_us, MIN_PULSE_US, MAX_PULSE_US);
            continue;
        }

        double distance_cm = pulse_to_cm(pulse_us);

        if (distance_cm < 0.0) {
            fprintf(stderr, "No valid echo received\n");
            continue;
        }

        if (distance_cm > DISTANCE_THRESHOLD_CM) {
            fprintf(stderr, "Distance %.2f cm exceeds threshold %.1f cm\n",
                    distance_cm, DISTANCE_THRESHOLD_CM);
            continue;
        }

        log_distance(distance_cm);
    }

    /* ---- Cleanup ---- */
    printf("\nShutting down...\n");
    cleanup();
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    printf("Done.\n");
    return EXIT_SUCCESS;
}

