 *   VL53L1X SDA  -> GPIO2 (I2C bus 1 SDA)
 *   VL53L1X SCL  -> GPIO3 (I2C bus 1 SCL)
 *   VL53L1X XSHUT-> GPIO27 (BCM 27, active-low trigger)
 *   VL53L1X VDD  -> 3.3 V
 *   VL53L1X GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o vl53l1x_reader vl53l1x_reader.c -lm
 *
 * Run:
 *   sudo ./vl53l1x_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <syslog.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#include <pigpio.h>

/* ---- Configuration ---- */
#define I2C_BUS          1
#define VL53L1X_ADDR     0x29
#define XSHUT_PIN        27          /* BCM 27 */
#define POLL_DELAY_US    100000      /* 100 ms */
#define MAX_RETRIES      3

/* ---- VL53L1X register map (16-bit addresses, big-endian on the bus) ---- */
#define VL53L1X_REG_SOFT_RESET              0x0003
#define VL53L1X_REG_SYSTEM_MODE_START       0x0000
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR  0x0086
#define VL53L1X_REG_RESULT_INTERRUPT_STATUS 0x0089
#define VL53L1X_REG_RESULT_RANGE_STATUS     0x0089
#define VL53L1X_REG_RESULT_DISTANCE         0x0096

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit register address + 1-byte value (big-endian).       */
static int vl53l1x_write_reg16(int fd, uint16_t reg, uint8_t value)
{
    uint8_t buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        syslog(LOG_ERR, "I2C write to reg 0x%04X failed: %s",
               reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit register address + 1-byte value (big-endian).         */
static int vl53l1x_read_reg16(int fd, uint16_t reg, uint8_t *value)
{
    uint8_t addr[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;

    if (write(fd, addr, sizeof(addr)) != (ssize_t)sizeof(addr)) {
        syslog(LOG_ERR, "I2C write (addr) for reg 0x%04X failed: %s",
               reg, strerror(errno));
        return -1;
    }

    uint8_t val;
    if (read(fd, &val, 1) != 1) {
        syslog(LOG_ERR, "I2C read from reg 0x%04X failed: %s",
               reg, strerror(errno));
        return -1;
    }
    *value = val;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise the VL53L1X: soft reset, then start continuous ranging.   */
static int vl53l1x_init(int fd)
{
    /* Soft reset: write 0x00 to SOFT_RESET register. */
    if (vl53l1x_write_reg16(fd, VL53L1X_REG_SOFT_RESET, 0x00) < 0)
        return -1;

    /* Allow time for the device to boot. */
    usleep(10000);

    /* Start continuous ranging (bit 0 = 1). */
    if (vl53l1x_write_reg16(fd, VL53L1X_REG_SYSTEM_MODE_START, 0x01) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read distance in mm.  Returns -1 on error.                          */
static int vl53l1x_read_distance(int fd)
{
    uint8_t status = 0;

    /* Poll for data ready (bit 0 of RESULT_INTERRUPT_STATUS). */
    for (int i = 0; i < MAX_RETRIES; i++) {
        if (vl53l1x_read_reg16(fd, VL53L1X_REG_RESULT_INTERRUPT_STATUS, &status) < 0)
            return -1;
        if (status & 0x01)
            break;
        usleep(1000);
    }

    if (!(status & 0x01)) {
        syslog(LOG_ERR, "VL53L1X data-ready timeout");
        return -1;
    }

    /* Clear interrupt so the next measurement can be signalled. */
    if (vl53l1x_write_reg16(fd, VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0)
        return -1;

    /* Read distance (16-bit, big-endian). */
    uint8_t dist_buf[2];
    if (read(fd, dist_buf, sizeof(dist_buf)) != (ssize_t)sizeof(dist_buf)) {
        syslog(LOG_ERR, "I2C read of distance register failed: %s",
               strerror(errno));
        return -1;
    }

    return (int)((dist_buf[0] << 8) | dist_buf[1]);
}

/* ------------------------------------------------------------------ */
static void log_reading(int distance, int status)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    syslog(LOG_INFO, "%s Distance: %d mm, Status: %d",
           ts, distance, status);
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    gpioTerminate();
    closelog();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        syslog(LOG_ERR, "Failed to open /dev/i2c-1: %s", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, VL53L1X_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to set I2C slave address 0x%02X: %s",
               VL53L1X_ADDR, strerror(errno));
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Verify sensor presence ---- */
    uint8_t probe = 0;
    if (vl53l1x_read_reg16(g_i2c_fd, VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, &probe) < 0) {
        syslog(LOG_ERR, "VL53L1X not responding at address 0x%02X", VL53L1X_ADDR);
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Initialise sensor ---- */
    if (vl53l1x_init(g_i2c_fd) < 0) {
        syslog(LOG_ERR, "VL53L1X initialisation failed");
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "VL53L1X initialised at address 0x%02X", VL53L1X_ADDR);

    /* ---- GPIO27 as output, active-high (XSHUT active-low). */
    gpioSetMode(XSHUT_PIN, PI_OUTPUT);
    gpioWrite(XSHUT_PIN, 1);  /* sensor disabled while we configure */

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    syslog(LOG_INFO, "Starting VL53L1X readings (poll every %d ms)",
           POLL_DELAY_US / 1000);

    /* ---- Main loop ---- */
    while (g_running) {
        int distance = vl53l1x_read_distance(g_i2c_fd);

        if (distance >= 0) {
            log_reading(distance, 0);
        } else {
            log_reading(-1, -1);
        }

        usleep(POLL_DELAY_US);
    }

    syslog(LOG_INFO, "Shutting down...");
    cleanup();
    return EXIT_SUCCESS;
}

