/*
 * HC-SR04 Ultrasonic Distance Measurement with SG90 Servo Tracking
 * Board:  Raspberry Pi 4 Model B
 * Trigger: GPIO23 (BCM)  - HC-SR04 TRIG
 * Echo:    GPIO24 (BCM)  - HC-SR04 ECHO
 * Servo:   GPIO18 (BCM)  - SG90 signal (hardware PWM-capable)
 *
 * Build:  gcc -O2 -Wall -o distance_track distance_track.c -lpigpio -lrt
 * Run:    sudo ./distance_track
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define TRIGGER_PIN        23
#define ECHO_PIN           24
#define SERVO_PIN          18

#define SPEED_OF_SOUND_CM_S 34300.0f   /* cm/s at ~20 °C */
#define TRIGGER_PULSE_US    10          /* HC-SR04 trigger pulse width */
#define ECHO_TIMEOUT_US     30000       /* 30 ms max echo wait */
#define SAMPLE_PERIOD_US    100000      /* 100 ms between measurements */
#define SERVO_SETTLE_MS     50          /* time for servo to reach angle */
#define SERVO_CENTER_DEG    90          /* default center angle */
#define SERVO_MIN_DEG       0
#define SERVO_MAX_DEG       180
#define LOG_FILE_NAME       "distance_log.csv"

/* Shared state between callback and main thread */
static volatile uint32_t g_pulse_width = 0;
static volatile bool     g_new_pulse    = false;
static volatile sig_atomic_t g_running     = 1;

/* ----------------------------- Globals ----------------------------------- */
static FILE *g_log_fp = NULL;
static int    g_servo_angle = SERVO_CENTER_DEG;

/* ----------------------------- Prototypes -------------------------------- */
static void  echo_callback(int gpio, int level, uint32_t tick, void *userdata);
static void  signal_handler(int sig);
static void  cleanup(void);
static int   init_gpio(void);
static int   init_servo(void);
static int   set_servo_angle(int angle);
static float measure_distance(void);
static void  log_data(float distance, int angle);
static void  set_servo_to_angle(int angle);

/* ----------------------------- Echo Callback ----------------------------- */
static void echo_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio; (void)userdata;

    if (level == 1) {
        /* Rising edge: echo pulse starts */
        g_pulse_width = tick;
    } else if (level == 0) {
        /* Falling edge: echo pulse ends */
        if (g_pulse_width > 0) {
            /* pigpio tick is a 32-bit microsecond counter that wraps every ~71.6 min */
            uint32_t diff = tick - g_pulse_width;   /* correct across wrap */
            float distance = (float)diff * SPEED_OF_SOUND_CM_S / 2000000.0f;
            g_new_pulse = true;
            g_pulse_width = 0;
        }
    }
}

/* ----------------------------- Signal Handler ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    /* Stop servo PWM signal (0 = no signal) */
    if (g_servo_angle >= 0) {
        set_servo_angle(0);
    }

    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }

    gpioTerminate();
}

/* ----------------------------- GPIO Init --------------------------------- */
static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN %d as output.\n", TRIGGER_PIN);
        return -1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN %d as input.\n", ECHO_PIN);
        return -1;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set SERVO_PIN %d as output.\n", SERVO_PIN);
        return -1;
    }

    /* Ensure trigger starts LOW */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise TRIGGER_PIN LOW.\n");
        return -1;
    }

    /* Register echo interrupt callback */
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) < 0) {
        fprintf(stderr, "Error: failed to register echo callback on ECHO_PIN %d.\n", ECHO_PIN);
        return -1;
    }

    return 0;
}

/* ----------------------------- Servo Init --------------------------------- */
static int init_servo(void)
{
    /* gpioServo takes angle in microseconds (50 us = 0°, 2500 us = 180°) */
    if (gpioServo(SERVO_PIN, g_servo_angle * 1000) < 0) {
        fprintf(stderr, "Error: gpioServo failed for SERVO_PIN %d.\n", SERVO_PIN);
        return -1;
    }
    return 0;
}

/* ----------------------------- Set Servo Angle ---------------------------- */
static int set_servo_angle(int angle)
{
    if (angle < SERVO_MIN_DEG || angle > SERVO_MAX_DEG) {
        fprintf(stderr, "Error: angle %d out of range [%d, %d].\n",
                angle, SERVO_MIN_DEG, SERVO_MAX_DEG);
        return -1;
    }
    if (g_servo_angle != angle) {
        if (gpioServo(SERVO_PIN, angle * 1000) < 0) {
            fprintf(stderr, "Error: gpioServo failed for SERVO_PIN %d.\n", SERVO_PIN);
            return -1;
        }
        g_servo_angle = angle;
        return 0;
    }
    return 0;
}

/* ----------------------------- Measure Distance --------------------------- */
static float measure_distance(void)
{
    g_pulse_width = 0;
    g_new_pulse   = false;

    /* Issue 10 µs trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 1) failed.\n");
        return -1.0f;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) failed.\n");
        return -1.0f;
    }

    /* Wait for echo with timeout */
    uint32_t start = gpioTick();
    while (!g_new_pulse && g_running) {
        if ((gpioTick() - start) > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Warning: echo timeout (%u µs) - no object detected.\n",
                    ECHO_TIMEOUT_US);
            return -1.0f;
        }
        gpioDelay(100);  /* poll every 100 µs */
    }

    if (!g_new_pulse) {
        fprintf(stderr, "Warning: echo never arrived - sensor absent or wiring fault.\n");
        return -1.0f;
    }

    uint32_t pulse_us = gpioTick() - g_pulse_width;
    float distance = (float)pulse_us * SPEED_OF_SOUND_CM_S / 2000000.0f;

    if (distance < 2.0f || distance > 400.0f) {
        fprintf(stderr, "Warning: distance %.2f cm out of range [2, 400].\n", distance);
        return -1.0f;
    }

    return distance;
}

/* ----------------------------- Log Data ----------------------------------- */
static void log_data(float distance, int angle)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    fprintf(g_log_fp, "%s,%.2f,%d\n", ts, distance, angle);
    fflush(g_log_fp);
}

/* ----------------------------- Servo Track -------------------------------- */
static void set_servo_to_angle(int angle)
{
    if (angle < SERVO_MIN_DEG) angle = SERVO_MIN_DEG;
    if (angle > SERVO_MAX_DEG) angle = SERVO_MAX_DEG;

    /* Move servo to new position */
    if (set_servo_angle(angle) < 0) {
        fprintf(stderr, "Error: failed to set servo angle to %d.\n", angle);
        return;
    }

    /* Allow servo to settle */
    gpioDelay(SERVO_SETTLE_MS * 1000);

    /* Track the distance */
    float dist = measure_distance();
    if (dist < 0.0f) {
        fprintf(stderr, "Error: invalid distance reading, tracking to center.\n");
        set_servo_angle(SERVO_CENTER_DEG);
        return;
    }

    log_data(dist, angle);
}

/* ----------------------------- Main --------------------------------------- */
int main(void)
{
    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize GPIO */
    if (init_gpio() < 0) {
        return EXIT_FAILURE;
    }

    /* Initialize Servo */
    if (init_servo() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_fp = fopen(LOG_FILE_NAME, "a");
    if (g_log_fp == NULL) {
        perror("fopen(" LOG_FILE_NAME ")");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    fseek(g_log_fp, 0, SEEK_END);
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "Timestamp,Distance_cm,Angle_deg\n");
        fflush(g_log_fp);
    }

    printf("Distance tracking started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        float dist = measure_distance();
        if (dist < 0.0f) {
            fprintf(stderr, "Invalid distance reading, tracking to center.\n");
            set_servo_angle(SERVO_CENTER_DEG);
        } else {
            int angle = g_servo_angle;
            set_servo_to_angle(angle);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* Graceful shutdown */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

