/*
 * VL53L1X ToF sensor reader for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   VL53L1X SDA  -> GPIO2 (I2C bus 1 SDA)
 *   VL53L1X SCL -> GPIO3 (I2C bus 1 SCL)
 *   VL53L1X VDD -> 3.3 V
 *   VL53L1X GND -> GND
 *   Warning LED -> GPIO17 (BCM) via ~330 Ω resistor to GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o vl53l1x_reader vl53l1x_reader.c -lpigpio -lrt
 * Run:    sudo ./vl53l1x_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- VL53L1X constants (verified against datasheet / app note) ---- */
#define VL53L1X_ADDR             0x29
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID  0x010F
#define VL53L1X_REG_SYSTEM_MODE_START        0x0000
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR   0x0086
#define VL53L1X_REG_RESULT_INTERRUPT_STATUS 0x0089
#define VL53L1X_REG_RESULT_RANGE_STATUS     0x0089
#define VL53L1X_REG_RESULT_DISTANCE         0x0096
#define VL53L1X_REG_RESULT_RANGE_CONFIG     0x0082
#define VL53L1X_REG_SYSTEM_INTERRUPT_CONFIG 0x0083
#define VL53L1X_REG_SYSTEM_RANGE_CONFIG     0x0084
#define VL53L1X_REG_SYSTEM_RANGE_START      0x0000

#define EXPECTED_MODEL_ID            0xEA
#define BUFFER_SIZE                 10
#define WARNING_THRESHOLD_MM        200
#define POLL_DELAY_US               50000   /* 50 ms */
#define I2C_BUS                    1

/* ---- Application constants ---- */
#define LED_GPIO                     17
#define I2C_BUS                      I2C_BUS

/* ---- Data structures ---- */
typedef struct {
    int16_t distance_mm[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

/* ---- Globals ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static CircularBuffer g_buffer;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ---- */
static int i2c_write_reg8(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg8(int handle, uint16_t reg, uint8_t *value)
{
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, reg_buf, 2) < 0)
        return -1;
    char data;
    if (i2cReadDevice(handle, &data, 1) != 1)
        return -1;
    *value = (uint8_t)data;
    return 0;
}

static int i2c_read_reg16(int handle, uint16_t reg, int16_t *value)
{
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, reg_buf, 2) < 0)
        return -1;
    char data[2];
    if (i2cReadDevice(handle, data, 2) != 2)
        return -1;
    *value = (int16_t)(((uint16_t)data[0] << 8) | (uint8_t)data[1]);
    return 0;
}

/* ---- VL53L1X driver ---- */
static int vl53l1x_init(int handle)
{
    uint8_t model_id = 0;

    if (i2c_read_reg8(handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id) < 0) {
        fprintf(stderr, "Error: failed to read model ID from VL53L1X.\n");
        return -1;
    }
    if (model_id != EXPECTED_MODEL_ID) {
        fprintf(stderr, "Error: unexpected model ID 0x%02X (expected 0x%02X).\n",
                model_id, EXPECTED_MODEL_ID);
        return -1;
    }
    printf("VL53L1X detected (model ID 0x%02X).\n", model_id);

    /* Recommended ST initialization sequence */
    if (i2c_write_reg8(handle, 0x0207, 0x01) < 0) return -1; /* Set I2C standard mode */
    if (i2c_write_reg8(handle, 0x0208, 0x01) < 0) return -1; /* Set MSB first */
    if (i2c_write_reg8(handle, 0x0096, 0x00) < 0) return -1; /* Clear any config */
    if (i2c_write_reg8(handle, 0x0082, 0x01) < 0) return -1; /* Set range config */
    if (i2c_write_reg8(handle, 0x0083, 0x00) < 0) return -1; /* Clear interrupt config */
    if (i2c_write_reg8(handle, 0x0084, 0x00) < 0) return -1; /* Clear range config */
    if (i2c_write_reg8(handle, 0x0000, 0x00) < 0) return -1; /* Clear start */
    if (i2c_write_reg8(handle, 0x0001, 0x01) < 0) return -1; /* Start continuous mode */
    if (i2c_write_reg8(handle, 0x0086, 0x01) < 0) return -1; /* Enable interrupt */
    if (i2c_write_reg8(handle, 0x0000, 0x01) < 0) return -1; /* Start ranging */

    return 0;
}

static int vl53l1x_read_distance(int handle, int16_t *distance_mm)
{
    uint8_t status = 0;
    if (i2c_read_reg8(handle, VL53L1X_REG_RESULT_INTERRUPT_STATUS, &status) < 0)
        return -1;
    if ((status & 0x01) == 0) {
        /* No new data yet; return 0 so caller polls */
        return 0;
    }
    if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_DISTANCE, distance_mm) < 0)
        return -1;
    /* Clear interrupt so next measurement can trigger */
    if (i2c_write_reg8(handle, VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0)
        return -1;
    return 1;
}

/* ---- Circular buffer ---- */
static void buffer_add(CircularBuffer *buf, int16_t value)
{
    buf->distance_mm[buf->head] = value;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count < BUFFER_SIZE)
        buf->count++;
}

static void buffer_print(const CircularBuffer *buf)
{
    printf("\n--- Circular Buffer (last %d samples) ---\n", buf->count);
    for (int i = 0; i < buf->count; i++) {
        int idx = (buf->head - buf->count + i + BUFFER_SIZE) % BUFFER_SIZE;
        printf("  [%2d] %6d mm\n", i, buf->distance_mm[idx]);
    }
    printf("--- end ---\n\n");
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2c_write_reg8(g_i2c_handle, VL53L1X_REG_SYSTEM_MODE_START, 0x00);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

/* ---- Main ---- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO */
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (bus %d, addr 0x%02X): %d\n",
                I2C_BUS, VL53L1X_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (vl53l1x_init(g_i2c_handle) < 0) {
        fprintf(stderr, "Error: VL53L1X initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize buffer */
    g_buffer.head = 0;
    g_buffer.count = 0;

    /* Install signal handler */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("VL53L1X reader started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        int16_t distance = 0;
        int rc = vl53l1x_read_distance(g_i2c_handle, &distance);

        if (rc == 1) {
            buffer_add(&g_buffer, distance);
            int below = (distance < WARNING_THRESHOLD_MM) ? 1 : 0;
            gpioWrite(LED_GPIO, below);
            printf("Distance: %6d mm  LED: %s\n", distance, below ? "ON" : "OFF");
        } else if (rc < 0) {
            fprintf(stderr, "Warning: I2C read error, continuing...\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

