#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pthread.h>
#include <getopt.h>
#include <syslog.h>
#include <pigpio.h>

#define DEFAULT_I2C_ADDRESS 0x60
#define DEFAULT_THRESHOLD 1000
#define GPIO_PIN 27
#define LOG_FILE "proximity.log"
#define I2C_BUS 1

/* Si1102 register addresses (from datasheet) */
#define SI1102_REG_IRQ_ENABLE 0x00
#define SI1102_REG_IRQ_STATUS 0x01
#define SI1102_REG_PROX_DATA0 0x04
#define SI1102_REG_PROX_DATA1 0x05
#define SI1102_REG_PROX_CONFIG 0x07

/* Si1102 command codes (from datasheet) */
#define SI1102_CMD_PROX_INT_EN 0x01
#define SI1102_CMD_PROX_INT_DIS 0x00

static int i2c_address = DEFAULT_I2C_ADDRESS;
static int threshold = DEFAULT_THRESHOLD;
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t proximity_event = 0;
static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_error(const char *msg) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    syslog(LOG_ERR, "[%s] %s: %s", ts, msg, strerror(errno));
    fprintf(stderr, "[%s] %s: %s\n", ts, msg, strerror(errno));
}

static int i2c_write_reg(uint8_t reg, uint8_t value) {
    char buf[2] = { (char)reg, (char)value };
    if (i2cWriteDevice(i2c_handle, buf, 2) != 2) {
        log_error("I2C write failed");
        return -1;
    }
    return 0;
}

static int i2c_read_reg(uint8_t reg, uint8_t *value) {
    if (i2cWriteDevice(i2c_handle, (char *)&reg, 1) != 1) {
        log_error("I2C write (reg select) failed");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, (char *)value, 1) != 1) {
        log_error("I2C read failed");
        return -1;
    }
    return 0;
}

static int init_sensor(void) {
    if (i2c_write_reg(SI1102_REG_IRQ_ENABLE, SI1102_CMD_PROX_INT_DIS) != 0) {
        log_error("Failed to disable proximity interrupt");
        return -1;
    }
    if (i2c_write_reg(SI1102_REG_PROX_CONFIG, 0x00) != 0) {
        log_error("Failed to configure proximity sensor");
        return -1;
    }
    if (i2c_write_reg(SI1102_REG_IRQ_ENABLE, SI1102_CMD_PROX_INT_EN) != 0) {
        log_error("Failed to enable proximity interrupt");
        return -1;
    }
    return 0;
}

static void interrupt_handler(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; (void)level; (void)tick; (void)user;
    proximity_event = 1;
}

static void process_proximity_event(void) {
    uint8_t prox_data[2];
    if (i2c_read_reg(SI1102_REG_PROX_DATA0, prox_data) != 0) {
        return;
    }
    uint16_t proximity = (prox_data[1] << 8) | prox_data[0];

    pthread_mutex_lock(&log_mutex);
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    if (proximity <= threshold) {
        fprintf(log_file, "%s, Proximity: %u, Status: SAFE\n", ts, proximity);
    } else {
        fprintf(log_file, "%s, Proximity: %u, Status: ALERT\n", ts, proximity);
    }
    fflush(log_file);
    pthread_mutex_unlock(&log_mutex);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2c_write_reg(SI1102_REG_IRQ_ENABLE, SI1102_CMD_PROX_INT_DIS);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
    closelog();
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = (int)strtol(optarg, NULL, 0);
                break;
            case 't':
                threshold = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    openlog("proximity_sensor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting proximity sensor monitoring (addr=0x%02X, threshold=%d)", i2c_address, threshold);

    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, i2c_address, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C device");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (init_sensor() != 0) {
        log_error("Sensor initialization failed");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        log_error("Failed to set GPIO mode");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP) != 0) {
        log_error("Failed to set GPIO pull-up");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, interrupt_handler, NULL) != 0) {
        log_error("Failed to set GPIO interrupt handler");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        log_error("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        log_error("Failed to install SIGINT handler");
        cleanup();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Proximity sensor monitoring started (GPIO%d, addr=0x%02X, threshold=%d)", GPIO_PIN, i2c_address, threshold);

    while (running) {
        if (proximity_event) {
            proximity_event = 0;
            process_proximity_event();
        }
        gpioDelay(100000); /* 100 ms */
    }

    syslog(LOG_INFO, "Shutting down gracefully");
    cleanup();
    return EXIT_SUCCESS;
}

