/*
 * HC-SR04 Ultrasonic Theremin for Raspberry Pi Zero W
 *
 * Wiring:
 *   HC-SR04 TRIG -> GPIO23 (BCM)
 *   HC-SR04 ECHO -> GPIO24 (BCM)
 *   Speaker +    -> PWM0  (GPIO18, BCM)
 *   Speaker -    -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o theremin theremin.c -lpigpio -lrt
 *   (run as root or with gpio group access)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define TRIGGER_PIN      23
#define ECHO_PIN         24
#define PWM_PIN          18

#define MIN_DISTANCE_CM  2.0f
#define MAX_DISTANCE_CM  200.0f
#define MIN_FREQUENCY_HZ 200.0f
#define MAX_FREQUENCY_HZ 2000.0f
#define PWM_RANGE        1000
#define PWM_DUTY_50PCT   500
#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_MS  200
#define LOOP_DELAY_US    100000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Measure distance in cm. Returns -1.0 on timeout or error.
 */
static float measure_distance(void)
{
    uint32_t start_tick, end_tick, timeout_tick;

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) failed\n");
        return -1.0f;
    }
    gpioDelay(5);

    /* 10 µs trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 1) failed\n");
        return -1.0f;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) failed\n");
        return -1.0f;
    }

    /* Wait for echo rising edge (timeout) */
    timeout_tick = gpioTick() + (ECHO_TIMEOUT_MS * 1000);
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: Echo start timeout (sensor absent?)\n");
            return -1.0f;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge (timeout) */
    timeout_tick = gpioTick() + (ECHO_TIMEOUT_MS * 1000);
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: Echo end timeout\n");
            return -1.0f;
        }
    }
    end_tick = gpioTick();

    uint32_t diff = end_tick - start_tick;
    float distance = (float)diff / 58.0f; /* cm */

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        fprintf(stderr, "Warning: distance %.2f cm out of range [%.1f-%.1f]\n",
                distance, MIN_DISTANCE_CM, MAX_DISTANCE_CM);
        return -1.0f;
    }

    return distance;
}

/*
 * Map distance to frequency on a logarithmic scale.
 * Returns -1.0 if distance is invalid.
 */
static float distance_to_frequency(float distance)
{
    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM)
        return -1.0f;

    float ratio = (distance - MIN_DISTANCE_CM) /
                  (MAX_DISTANCE_CM - MIN_DISTANCE_CM);
    if (ratio <= 0.0f)
        return MIN_FREQUENCY_HZ;
    if (ratio >= 1.0f)
        return MAX_FREQUENCY_HZ;

    float freq = MIN_FREQUENCY_HZ +
                 powf(MAX_FREQUENCY_HZ / MIN_FREQUENCY_HZ,
                      1.0f - ratio);

    return freq;
}

/*
 * Generate a tone on the hardware PWM line.
 * frequency: 0 = silence, 1 = full volume.
 */
static void generate_tone(float frequency, int duty_cycle)
{
    if (frequency < 0.0f) {
        gpioPWM(PWM_PIN, 0);
        return;
    }

    if (frequency < 20.0f) {
        /* Below 20 Hz: use software PWM (gpioSetPWMfrequency) */
        if (gpioSetPWMfrequency(PWM_PIN, (int)frequency) < 0) {
            fprintf(stderr, "Error: gpioSetPWMfrequency(%d) failed\n", (int)frequency);
            return;
        }
        if (gpioPWM(PWM_PIN, duty_cycle) < 0) {
            fprintf(stderr, "Error: gpioPWM(%d) failed\n", duty_cycle);
        }
        return;
    }

    /* Hardware PWM: 50% duty cycle */
    if (gpioSetPWMfrequency(PWM_PIN, (int)frequency) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency(%d) failed\n", (int)frequency);
        return;
    }
    if (gpioPWM(PWM_PIN, PWM_DUTY_50PCT) < 0) {
        fprintf(stderr, "Error: gpioPWM(%d) failed\n", PWM_DUTY_50PCT);
    }
}

int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure trigger pin as output, initially low */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(TRIGGER, OUTPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure echo pin as input */
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(ECHO, INPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure PWM pin as output */
    if (gpioSetMode(PWM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(PWM, OUTPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure PWM is off initially */
    gpioPWM(PWM_PIN, 0);

    float current_frequency = 0.0f;
    int   current_duty_cycle = 0;

    while (g_running) {
        float distance = measure_distance();

        if (distance < 0.0f) {
            /* Error or timeout: preserve current frequency */
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        float frequency = distance_to_frequency(distance);

        if (frequency < 0.0f) {
            /* Invalid distance: preserve current frequency */
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        current_frequency = frequency;

        /* Map frequency to duty cycle (0 = silence, 1 = full volume) */
        int duty = (int)(current_frequency / 100.0f);
        if (duty > PWM_RANGE) duty = PWM_RANGE;
        if (duty < 0)         duty = 0;

        generate_tone(current_frequency, duty);

        gpioDelay(LOOP_DELAY_US);
    }

    /* Clean shutdown */
    gpioPWM(PWM_PIN, 0);
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();

    return EXIT_SUCCESS;
}

