code:
/*
 * Theremin-like instrument using an HC-SR04 ultrasonic sensor and a piezo buzzer.
 *
 * Board:  Raspberry Pi 3 Model B+
 * Library: pigpio (C API)
 *
 * Wiring:
 *   HC-SR04 TRIG -> GPIO23 (BCM)
 *   HC-SR04 ECHO -> GPIO24 (BCM) via 4.7 kΩ pull-down to GND
 *   Piezo buzzer -> PWM0 (GPIO18, BCM) via 330 Ω resistor
 *
 * Build:  gcc -O2 -Wall -o theremin theremin.c -lpigpio -lrt
 * Run:    sudo ./theremin
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define TRIGGER_PIN      23          /* BCM 23  - HC-SR04 trigger  */
#define ECHO_PIN         24          /* BCM 24  - HC-SR04 echo    */
#define PWM_PIN          18          /* BCM 18  - piezo buzzer    */

#define TRIGGER_PULSE_US 10          /* 10 µs high pulse            */
#define ECHO_TIMEOUT_US  100000      /* 100 ms max echo wait       */
#define LOOP_DELAY_US    10000       /* 10 ms between readings     */
#define MIN_DISTANCE_CM  5.0
#define MAX_DISTANCE_CM  50.0
#define MIN_FREQUENCY_HZ 200
#define MAX_FREQUENCY_HZ 2000

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;

/* --------------------------- Signal handler ------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- Distance measurement ----------------------- */
/*
 * Returns distance in cm, or -1.0 on timeout / error.
 * Uses pigpio's microsecond-timed gpioTick() for sub-microsecond resolution.
 */
static double measure_distance(void)
{
    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to write TRIG low\n");
        return -1.0;
    }
    gpioDelay(5);                       /* settle */

    /* 10 µs trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to write TRIG high\n");
        return -1.0;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to write TRIG low\n");
        return -1.0;
    }

    uint32_t start_tick = 0;
    uint32_t end_tick   = 0;
    uint32_t deadline  = gpioTick() + ECHO_TIMEOUT_US;

    /* Wait for echo rising edge */
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - deadline) >= 0) {
            fprintf(stderr, "Error: echo start timeout (sensor absent?)\n");
            return -1.0;
        }
        gpioDelay(20);
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge */
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - deadline) >= 0) {
            fprintf(stderr, "Error: echo end timeout\n");
            return -1.0;
        }
        gpioDelay(20);
    }
    end_tick = gpioTick();

    double elapsed_us = (double)(end_tick - start_tick);
    double distance   = elapsed_us / 58.0;   /* cm per µs round-trip */

    /* Sanity range check */
    if (distance < 2.0 || distance > 400.0) {
        fprintf(stderr, "Warning: distance %.2f cm out of valid range\n", distance);
        return -1.0;
    }
    return distance;
}

/* --------------------------- Frequency mapping ---------------------------- */
static int map_distance_to_frequency(double distance)
{
    if (distance < MIN_DISTANCE_CM) distance = MIN_DISTANCE_CM;
    if (distance > MAX_DISTANCE_CM) distance = MAX_DISTANCE_CM;

    double ratio = (distance - MIN_DISTANCE_CM) /
                   (MAX_DISTANCE_CM - MIN_DISTANCE_CM);

    int freq = (int)(MIN_FREQUENCY_HZ +
                     (ratio * (MAX_FREQUENCY_HZ - MIN_FREQUENCY_HZ)));

    if (freq < MIN_FREQUENCY_HZ) freq = MIN_FREQUENCY_HZ;
    if (freq > MAX_FREQUENCY_HZ) freq = MAX_FREQUENCY_HZ;

    return freq;
}

/* --------------------------- Buzzer tone generation ----------------------- */
/*
 * Generates a continuous tone at the requested frequency using pigpio's
 * hardware PWM on the buzzer pin.  Uses a 50 % duty cycle.
 */
static void generate_tone(int frequency)
{
    if (frequency <= 0) {
        gpioPWM(PWM_PIN, 0);
        return;
    }

    /* pigpio hardware PWM: range 0-255, frequency in Hz */
    if (gpioSetPWMfrequency(PWM_PIN, frequency) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency(%d) failed\n", frequency);
        return;
    }
    if (gpioSetPWMrange(PWM_PIN, 255) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange(%d) failed\n", 255);
        return;
    }
    if (gpioPWM(PWM_PIN, 128) < 0) {
        fprintf(stderr, "Error: gpioPWM(%d) failed\n", 128);
        return;
    }
}

/* --------------------------- Main loop ----------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO modes */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: cannot set TRIGGER_PIN %d as output\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: cannot set ECHO_PIN %d as input\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(PWM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: cannot set PWM_PIN %d as output\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(50);

    /* Install signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Theremin ready.  Press Ctrl+C to exit.\n");
    printf("  Trigger: BCM %d | Echo: BCM %d | Buzzer: BCM %d\n",
           TRIGGER_PIN, ECHO_PIN, PWM_PIN);
    printf("  Distance: %.1f-%.1f cm  ->  freq: %.0f-%.0f Hz\n",
           MIN_DISTANCE_CM, MAX_DISTANCE_CM,
           MIN_FREQUENCY_HZ, MAX_FREQUENCY_HZ);
    fflush(stdout);

    while (g_running) {
        double distance = measure_distance();

        if (distance < 0.0) {
            fprintf(stderr, "Error: distance measurement failed; "
                            "reusing last valid frequency\n");
            distance = -1.0;
        }

        int frequency = map_distance_to_frequency(distance);
        printf("Distance: %6.2f cm  |  Frequency: %4d Hz\n",
               distance, frequency);
        fflush(stdout);

        generate_tone(frequency);
        gpioDelay(LOOP_DELAY_US);
    }

    /* --------------------------- Cleanup --------------------------------- */
    printf("\nShutting down...\n");
    gpioPWM(PWM_PIN, 0);   /* stop buzzer */
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

