#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define TIMEOUT_US  50000   /* 50 ms */
#define MIN_CM      2.0
#define MAX_CM      400.0
#define LOOP_US     500000  /* 500 ms */
#define TRIGGER_US  10

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Measure distance in centimetres.
 * Returns >= 0 on success, -1.0 on timeout, -2.0 on read error.
 */
static double measure_distance(void)
{
    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger, 0) failed\n");
        return -2.0;
    }
    gpioDelay(1000);  /* 1 ms settle */

    /* 10 us trigger pulse */
    if (gpioTrigger(TRIGGER_PIN, TRIGGER_US, 1) < 0) {
        fprintf(stderr, "Error: gpioTrigger failed\n");
        return -2.0;
    }

    uint32_t start_tick = 0;
    uint32_t end_tick   = 0;
    uint32_t timeout_tick = gpioTick() + TIMEOUT_US;

    /* Wait for echo rising edge */
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: Echo timeout (no object detected)\n");
            return -1.0;
        }
        gpioDelay(10);
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge */
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: Echo timeout (stuck high)\n");
            return -1.0;
        }
        gpioDelay(10);
    }
    end_tick = gpioTick();

    double duration = (double)(end_tick - start_tick) / 1000000.0;

    /* distance = speed_of_sound * time / 2  (round trip) */
    double distance = (duration * 34300.0) / 2.0;

    if (distance < MIN_CM || distance > MAX_CM) {
        return -1.0;
    }

    return distance;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(trigger, OUTPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(echo, INPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger, 0) initialisation failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Warning: gpioSetPullUpDown(echo) failed\n");
    }

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (g_running) {
        double distance = measure_distance();

        if (distance < 0.0) {
            if (distance == -1.0) {
                printf("Invalid reading\n");
            } else {
                fprintf(stderr, "Error: GPIO read/write failure\n");
            }
        } else {
            printf("Distance: %.2f cm\n", distance);
            if (distance < 10.0) {
                printf("Too close!\n");
            }
        }
        fflush(stdout);

        gpioDelay(LOOP_US);
    }

    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

