#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

/* Configuration */
#define SPI_CHANNEL    0          /* CE0 (GPIO8) */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* Mode 0, active-low CS handled by pigpio */
#define GPIO_CS         8          /* BCM pin for manual CS control (optional) */
#define LOG_FILE       "distance_log.csv"
#define READ_INTERVAL  100000     /* microseconds (100 ms) */
#define MIN_DISTANCE   200        /* mm */
#define MAX_DISTANCE   5000       /* mm */

/* ICU-20201 register addresses (16-bit, big-endian on the bus) */
#define REG_DEVICE_ID  0x00
#define REG_RANGE      0x02
#define REG_CONFIG     0x04

/* Expected device ID for ICU-20201 */
#define ICU20201_DEV_ID 0x0204

/* Global resources for signal handler */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------------------------------------------ */
/* SPI transfer with manual CS control                                  */
/* ------------------------------------------------------------------ */
static int spi_transfer(uint8_t *tx, uint8_t *rx, int len)
{
    if (gpioWrite(GPIO_CS, 0) < 0) {
        fprintf(stderr, "gpioWrite(CS,0) failed: %s\n", strerror(errno));
        return -1;
    }

    int bytes = spiXfer(spi_handle, (char *)tx, (char *)rx, len);

    if (gpioWrite(GPIO_CS, 1) < 0) {
        fprintf(stderr, "gpioWrite(CS,1) failed: %s\n", strerror(errno));
        return -1;
    }

    if (bytes != len) {
        fprintf(stderr, "SPI transfer failed: expected %d bytes, got %d\n",
                len, bytes);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit register (big-endian on the bus)                      */
/* ------------------------------------------------------------------ */
static int read_register(uint8_t reg, uint16_t *value)
{
    uint8_t tx[3] = { (uint8_t)(reg | 0x80), 0x00, 0x00 };
    uint8_t rx[3] = { 0 };

    if (spi_transfer(tx, rx, 3) < 0)
        return -1;

    *value = ((uint16_t)rx[1] << 8) | rx[2];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit register (big-endian on the bus)                     */
/* ------------------------------------------------------------------ */
static int write_register(uint8_t reg, uint16_t value)
{
    uint8_t tx[3] = { (uint8_t)(reg & 0x7F), (uint8_t)(value >> 8), (uint8_t)(value & 0xFF) };
    uint8_t rx[3] = { 0 };

    if (spi_transfer(tx, rx, 3) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise the ICU-20201 sensor                                     */
/* ------------------------------------------------------------------ */
static int init_sensor(void)
{
    uint16_t dev_id = 0;

    if (read_register(REG_DEVICE_ID, &dev_id) < 0) {
        fprintf(stderr, "Failed to read device ID (sensor absent or bus error)\n");
        return -1;
    }

    if (dev_id != ICU20201_DEV_ID) {
        fprintf(stderr, "Unexpected device ID: 0x%04X (expected 0x%04X)\n",
                dev_id, ICU20201_DEV_ID);
        return -1;
    }

    /* Example configuration: range ~200–5000 mm, default settings */
    if (write_register(REG_CONFIG, 0x0001) < 0) {
        fprintf(stderr, "Failed to write configuration register\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read distance in millimetres                                        */
/* ------------------------------------------------------------------ */
static int read_distance(void)
{
    uint16_t range = 0;

    if (read_register(REG_RANGE, &range) < 0) {
        fprintf(stderr, "Failed to read range register\n");
        return -1;
    }

    /* Clamp to valid range */
    if (range < MIN_DISTANCE || range > MAX_DISTANCE) {
        fprintf(stderr, "Distance out of range: %u mm\n", range);
        return -1;
    }

    return (int)range;
}

/* ------------------------------------------------------------------ */
/* Log a reading to the CSV file                                       */
/* ------------------------------------------------------------------ */
static void log_data(int distance)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(log_file, "%s,%d\n", timestamp, distance);
    fflush(log_file);
}

/* ------------------------------------------------------------------ */
/* Cleanup resources                                                  */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialise pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI channel 0 at 1 MHz, mode 0 */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialise sensor */
    if (init_sensor() < 0) {
        fprintf(stderr, "Sensor initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,distance_mm\n");
        fflush(log_file);
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ICU-20201 distance logger started. Press Ctrl+C to stop.\n");

    /* Main loop */
    while (!terminate) {
        int distance = read_distance();
        if (distance >= 0) {
            log_data(distance);
        } else {
            fprintf(stderr, "Read error — continuing\n");
        }
        gpioDelay(READ_INTERVAL);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

