#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* Si1120 I2C address (7-bit, default) */
#define SI1120_ADDR 0x60

/* Si1120 register addresses */
#define SI1120_REG_PART_ID       0x00
#define SI1120_REG_HW_KEY       0x07
#define SI1120_REG_MEAS_RATE    0x08
#define SI1120_REG_ALS_RATE     0x09
#define SI1120_REG_ALS_VIS_DATA0 0x22
#define SI1120_REG_ALS_VIS_DATA1 0x23
#define SI1120_REG_PS1_DATA0    0x24
#define SI1120_REG_PS1_DATA1    0x25
#define SI1120_REG_COMMAND      0x30

/* Si1120 command values */
#define SI1120_CMD_RESET        0x01
#define SI1120_CMD_ALS_FORCE    0x0B

/* Expected part ID for Si1120 */
#define SI1120_PART_ID_EXPECTED  0x00

/* I2C bus on Raspberry Pi 4 Model B */
#define I2C_BUS 1

/* Sampling interval in microseconds (500 ms) */
#define SAMPLE_INTERVAL_US 500000

/* Retry parameters */
#define MAX_RETRIES 3
#define RETRY_DELAY_US 10000  /* 10 ms */

/* Globals for signal handler cleanup */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------------------------------------------ */
/* Write one byte to a Si1120 register with retry                     */
/* ------------------------------------------------------------------ */
static int si1120_write_reg(int handle, uint8_t reg, uint8_t value)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cWriteByteData(handle, reg, value);
        if (rc == 0)
            return 0;
        fprintf(stderr, "I2C write to reg 0x%02X failed (attempt %d/%d): %d\n",
                reg, attempt + 1, MAX_RETRIES, rc);
        gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Read one byte from a Si1120 register with retry                    */
/* ------------------------------------------------------------------ */
static int si1120_read_reg(int handle, uint8_t reg)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cReadByteData(handle, reg);
        if (rc >= 0)
            return rc;
        fprintf(stderr, "I2C read from reg 0x%02X failed (attempt %d/%d): %d\n",
                reg, attempt + 1, MAX_RETRIES, rc);
        gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Initialize the Si1120 sensor                                       */
/* ------------------------------------------------------------------ */
static int si1120_init(int handle)
{
    /* 1. Software reset via COMMAND register */
    if (si1120_write_reg(handle, SI1120_REG_COMMAND, SI1120_CMD_RESET) != 0) {
        fprintf(stderr, "Error: failed to send software reset command.\n");
        return -1;
    }
    gpioDelay(10000);  /* 10 ms settle after reset */

    /* 2. Verify part ID */
    int part_id = si1120_read_reg(handle, SI1120_REG_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Error: failed to read PART_ID register.\n");
        return -1;
    }
    if (part_id != SI1120_PART_ID_EXPECTED) {
        fprintf(stderr,
                "Error: unexpected PART_ID 0x%02X (expected 0x%02X). "
                "Wrong sensor or wrong address?\n",
                part_id, SI1120_PART_ID_EXPECTED);
        return -1;
    }
    printf("Si1120 detected (PART_ID = 0x%02X).\n", part_id);

    /* 3. Configure measurement rate (e.g., 0x0A = 10 samples/s) */
    if (si1120_write_reg(handle, SI1120_REG_MEAS_RATE, 0x0A) != 0) {
        fprintf(stderr, "Error: failed to set MEAS_RATE.\n");
        return -1;
    }

    /* 4. Configure ALS rate (e.g., 0x0A = 10 samples/s) */
    if (si1120_write_reg(handle, SI1120_REG_ALS_RATE, 0x0A) != 0) {
        fprintf(stderr, "Error: failed to set ALS_RATE.\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read ambient light and proximity data as 16-bit little-endian     */
/* values.  Returns 0 on success, -1 on I2C failure.                    */
/* ------------------------------------------------------------------ */
static int si1120_read_data(int handle, uint16_t *ambient_light, uint16_t *proximity)
{
    int als_low  = si1120_read_reg(handle, SI1120_REG_ALS_VIS_DATA0);
    int als_high = si1120_read_reg(handle, SI1120_REG_ALS_VIS_DATA1);
    int ps_low   = si1120_read_reg(handle, SI1120_REG_PS1_DATA0);
    int ps_high  = si1120_read_reg(handle, SI1120_REG_PS1_DATA1);

    if (als_low < 0 || als_high < 0 || ps_low < 0 || ps_high < 0) {
        fprintf(stderr, "Error: I2C read failure for sensor data.\n");
        return -1;
    }

    *ambient_light = (uint16_t)((als_high << 8) | als_low);
    *proximity     = (uint16_t)((ps_high << 8) | ps_low);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped reading to the log file                         */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, uint16_t ambient_light, uint16_t proximity)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[20];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed.\n");
        return -1;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed.\n");
        return -1;
    }

    if (fprintf(fp, "%s, Ambient Light: %u, Proximity: %u\n",
                timestamp, ambient_light, proximity) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed.\n");
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "Error: fflush failed.\n");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup all resources                                                */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the Si1120 address */
    i2c_handle = i2cOpen(I2C_BUS, SI1120_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (bus %d, addr 0x%02X): %d\n",
                I2C_BUS, SI1120_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the sensor */
    if (si1120_init(i2c_handle) != 0) {
        fprintf(stderr, "Error: Si1120 initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen("si1120_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: failed to open log file 'si1120_log.txt'.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to register SIGINT handler.\n");
    }

    printf("Logging Si1120 data to si1120_log.txt (Ctrl-C to stop)...\n");

    /* Main sampling loop */
    while (!terminate) {
        uint16_t ambient_light = 0;
        uint16_t proximity      = 0;

        if (si1120_read_data(i2c_handle, &ambient_light, &proximity) == 0) {
            if (log_data(log_file, ambient_light, proximity) != 0) {
                fprintf(stderr, "Warning: failed to log data.\n");
            }
        } else {
            fprintf(stderr, "Warning: sensor read failed, retrying next cycle.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

