#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* Si1182 register addresses */
#define SI1182_REG_PART_ID       0x00
#define SI1182_REG_MEAS_RATE     0x08
#define SI1182_REG_ALS_VIS_DATA0 0x22
#define SI1182_REG_PS1_DATA0     0x24

#define SI1182_PART_ID           0x82
#define SI1182_MEAS_RATE_100MS   0x0A

#define I2C_BUS                 "/dev/i2c-1"
#define LOG_FILE                "biometric_log.txt"
#define SAMPLE_INTERVAL_US      100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1)
        perror("sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) == -1)
        perror("sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s (wrote %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    n = read(fd, out, 1);
