#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

/* Si1145 I2C address (ADDR pin tied to GND) */
#define SI1145_ADDR 0x60

/* Si1145 register addresses */
#define SI1145_REG_PART_ID       0x00
#define SI1145_REG_HW_KEY       0x07
#define SI1145_REG_MEAS_RATE0   0x08
#define SI1145_REG_MEAS_RATE1   0x09
#define SI1145_REG_PS1_DATA0    0x22
#define SI1145_REG_PS1_DATA1    0x23
#define SI1145_REG_COMMAND      0x18

/* Si1145 command opcodes */
#define SI1145_CMD_RESET        0x01
#define SI1145_CMD_PS1_FORCE    0x0B

/* Timing constants (microseconds) */
#define SI1145_RESET_US         10000   /* 10 ms reset settle */
#define SI1145_PS1_FORCE_US    10000   /* 10 ms for PS1 force */
#define SAMPLE_INTERVAL_US     100000  /* 100 ms between samples */

/* Retry configuration */
#define MAX_RETRIES 3

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop can exit cleanly             */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a single byte to a Si1145 register; returns 0 on success,    */
/* -1 on failure.  Uses i2cWriteByteData().                             */
/* ------------------------------------------------------------------ */
static int si1145_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a single byte from a Si1145 register; returns 0 on success,   */
/* -1 on failure.  Uses i2cReadByteData().                               */
/* ------------------------------------------------------------------ */
static int si1145_read_reg(int handle, uint8_t reg)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %d\n", reg, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise the Si1145 sensor.                                        */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int si1145_init(int handle)
{
    /* 1. Software reset */
    if (si1145_write_reg(handle, SI1145_REG_COMMAND, SI1145_CMD_RESET) != 0) {
        fprintf(stderr, "[ERROR] Software reset write failed\n");
        return -1;
    }
    gpioDelay(SI1145_RESET_US);

    /* 2. Verify Part ID (expected 0x45 for Si1145) */
    int part_id = si1145_read_reg(handle, SI1145_REG_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "[ERROR] Cannot read Part ID\n");
        return -1;
    }
    if (part_id != 0x45) {
        fprintf(stderr, "[ERROR] Unexpected Part ID: 0x%02X (expected 0x45)\n", part_id);
        return -1;
    }
    printf("[INFO] Si1145 detected (Part ID 0x%02X)\n", part_id);

    /* 3. Write HW_KEY to enable proper operation */
    if (si1145_write_reg(handle, SI1145_REG_HW_KEY, 0x17) != 0) {
        fprintf(stderr, "[ERROR] Failed to write HW_KEY\n");
        return -1;
    }

    /* 4. Set measurement rate to 0 (manual / single-shot mode) */
    if (si1145_write_reg(handle, SI1145_REG_MEAS_RATE0, 0x00) != 0 ||
        si1145_write_reg(handle, SI1145_REG_MEAS_RATE1, 0x00) != 0) {
        fprintf(stderr, "[ERROR] Failed to set measurement rate\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read the 16-bit proximity value from PS1_DATA0/PS1_DATA1.           */
/* Returns 0 on success and stores value in *out; -1 on failure.       */
/* ------------------------------------------------------------------ */
static int si1145_read_proximity(int handle, uint16_t *out)
{
    int lo = si1145_read_reg(handle, SI1145_REG_PS1_DATA0);
    if (lo < 0) return -1;

    int hi = si1145_read_reg(handle, SI1145_REG_PS1_DATA1);
    if (hi < 0) return -1;

    *out = (uint16_t)((hi << 8) | lo);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped line to the log file.                          */
/* ------------------------------------------------------------------ */
static void log_line(const char *msg)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) return;

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    if (g_log_file) {
        fprintf(g_log_file, "%s: %s\n", ts, msg);
        fflush(g_log_file);
    }
    printf("%s: %s\n", ts, msg);
}

/* ------------------------------------------------------------------ */
/* Cleanup resources.                                                  */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialise pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus 1 at Si1145_ADDR --- */
    g_i2c_handle = i2cOpen(1, SI1145_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(1, 0x%02X) failed: %d\n",
                SI1145_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Initialise sensor --- */
    if (si1145_init(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] Si1145 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    g_log_file = fopen("proximity_log.txt", "a");
    if (!g_log_file) {
        fprintf(stderr, "[FATAL] Cannot open proximity_log.txt: %s\n",
                strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction failed: %s\n", strerror(errno));
    }

    printf("[INFO] Logging proximity data to proximity_log.txt (Ctrl-C to stop)\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        uint16_t proximity = 0;

        if (si1145_read_proximity(g_i2c_handle, &proximity) != 0) {
            char msg[128];
            snprintf(msg, sizeof(msg),
                     "[ERROR] Failed to read proximity after %d retries",
                     MAX_RETRIES);
            log_line(msg);
            /* Brief back-off before retrying */
            gpioDelay(100000); /* 100 ms */
            continue;
        }

        char log_msg[128];
        snprintf(log_msg, sizeof(log_msg),
                 "Proximity: %u", proximity);
        log_line(log_msg);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\n[INFO] Shutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

