#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define BUZZER_PIN  27

#define SPEED_OF_SOUND_CM_PER_US 0.0343
#define DISTANCE_THRESHOLD_CM   20.0
#define TRIGGER_PULSE_US        10
#define ECHO_TIMEOUT_US         30000
#define LOOP_DELAY_US           1000000

static volatile uint32_t g_start_tick = 0;
static volatile uint32_t g_end_tick   = 0;
static volatile bool      g_echo_seen  = false;
static volatile bool      g_echo_rising = false;
static volatile bool      g_echo_falling = false;
static volatile bool      g_echo_done   = false;

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void echo_callback(int gpio, int level, uint32_t tick)
{
    (void)gpio;

    if (level == 1) {
        g_echo_rising = true;
        g_echo_done   = false;
        g_echo_seen   = false;
        g_start_tick  = tick;
    } else if (level == 0) {
        if (g_echo_rising) {
            g_echo_falling = true;
            g_echo_done   = true;
            g_echo_rising = false;
            g_echo_seen   = true;
        }
        g_end_tick = tick;
    }
}

static void trigger_sensor(void)
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

static double calculate_distance(uint32_t pulse_width_us)
{
    return (double)pulse_width_us * SPEED_OF_SOUND_CM_PER_US / 2.0;
}

static void control_buzzer(double distance_cm)
{
    if (distance_cm < DISTANCE_THRESHOLD_CM) {
        gpioWrite(BUZZER_PIN, 1);
    } else {
        gpioWrite(BUZZER_PIN, 0);
    }
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN %d as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set BUZZER_PIN %d as output.\n", BUZZER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) < 0) {
        fprintf(stderr, "Error: failed to register alert callback on ECHO_PIN %d.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Warning: failed to set pull-down on ECHO_PIN %d.\n", ECHO_PIN);
    }

    if (gpioSetISRFuncEx(TRIGGER_PIN, RISING_EDGE, 0, NULL, NULL) < 0) {
        fprintf(stderr, "Error: failed to register ISR on TRIGGER_PIN %d.\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFuncEx(TRIGGER_PIN, FALLING_EDGE, 0, NULL, NULL) < 0) {
        fprintf(stderr, "Error: failed to register ISR on TRIGGER_PIN %d.\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler.\n");
    }

    printf("Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");

    while (g_running) {
        trigger_sensor();

        uint32_t start_wait = gpioTick();
        while (!g_echo_done && g_running) {
            if ((gpioTick() - start_wait) > ECHO_TIMEOUT_US) {
                fprintf(stderr, "Warning: echo timeout (no echo received).\n");
                break;
            }
            gpioDelay(100);
        }

        if (!g_echo_done) {
            continue;
        }

        uint32_t pulse_width = g_end_tick - g_start_tick;
        double distance = calculate_distance(pulse_width);

        printf("Distance: %.2f cm\n", distance);

        control_buzzer(distance);

        gpioDelay(LOOP_DELAY_US);
    }

    gpioSetISRFuncEx(TRIGGER_PIN, RISING_EDGE, 0, NULL, NULL);
    gpioSetISRFuncEx(TRIGGER_PIN, FALLING_EDGE, 0, NULL, NULL);
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);
    gpioWrite(BUZZER_PIN, 0);
    gpioTerminate();

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

