#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS        1
#define VL53L1X_ADDR   0x29
#define GPIO_GATE       18
#define DISTANCE_THRESHOLD_FAR  250
#define DISTANCE_THRESHOLD_NEAR  200
#define PWM_FREQUENCY   1000
#define PWM_RANGE       1000
#define LOG_FILE        "gate_log.txt"
#define POLL_DELAY_US   100000

/* VL53L1X register addresses */
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID  0x010F
#define VL53L1X_REG_SYSTEM_MODE_START       0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS     0x0089
#define VL53L1X_REG_RESULT_DISTANCE         0x0096

#define VL53L1X_MODEL_ID                      0xEACC
#define VL53L1X_RANGE_STATUS_DATA_READY      0x01

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg16(int fd, uint16_t reg, uint8_t value) {
    uint8_t buf[3] = { (uint8_t)(reg >> 8), (uint8_t)(reg & 0xFF), value };
    if (write(fd, buf, 3) != 3) return -1;
    return 0;
}

static int i2c_read_reg16(int fd, uint16_t reg, uint8_t *buf, int len) {
    uint8_t reg_buf[2] = { (uint8_t)(reg >> 8), (uint8_t)(reg & 0xFF) };
    if (write(fd, reg_buf, 2) != 2) return -1;
    if (read(fd, buf, len) != len) return -1;
    return 0;
}

