#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define SERVO_PIN   18

#define SPEED_OF_SOUND_CM_PER_US 0.0343
#define MIN_DISTANCE_CM 2.0
#define MAX_DISTANCE_CM 400.0
#define MIN_ANGLE_DEG 0
#define MAX_ANGLE_DEG 180
#define MIN_DISTANCE_CM_FOR_MIN_ANGLE 20.0
#define MAX_DISTANCE_CM_FOR_MAX_ANGLE 200.0
#define TIMEOUT_US 50000
#define MEASURE_DELAY_US 100000
#define SERVO_SETTLE_US 50000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set trigger pin %d as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set echo pin %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set servo pin %d as output.\n", SERVO_PIN);
        gpioTerminate();
        return -1;
    }

    /* Ensure trigger starts low */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(1000);

    return 0;
}

static void trigger_sensor(void) {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10);
    gpioWrite(TRIGGER_PIN, 0);
}

/*
 * Returns distance in cm, or -1.0 on timeout or sensor error.
 * Uses gpioTick() (microseconds) for timing.
 */
static float measure_distance(void) {
    uint32_t start_tick, end_tick, timeout_tick;

    /* Wait for echo rising edge */
    timeout_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if ((gpioTick() - timeout_tick) > TIMEOUT_US) {
            fprintf(stderr, "Warning: timeout waiting for echo rising edge.\n");
            return -1.0f;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge */
    timeout_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 1) {
        if ((gpioTick() - timeout_tick) > TIMEOUT_US) {
            fprintf(stderr, "Warning: timeout waiting for echo falling edge.\n");
            return -1.0f;
        }
    }
    end_tick = gpioTick();

    uint32_t diff = end_tick - start_tick;
    float distance = (float)diff * SPEED_OF_SOUND_CM_PER_US / 2.0f;

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        fprintf(stderr, "Warning: distance %.2f cm out of valid range [%.1f, %.1f].\n",
                distance, MIN_DISTANCE_CM, MAX_DISTANCE_CM);
        return -1.0f;
    }

    return distance;
}

static int calculate_angle(float distance) {
    if (distance < 0.0f) {
        return -1;
    }

    if (distance < MIN_DISTANCE_CM_FOR_MIN_ANGLE) {
        return MIN_ANGLE_DEG;
    }
    if (distance > MAX_DISTANCE_CM_FOR_MAX_ANGLE) {
        return MAX_ANGLE_DEG;
    }

    float angle = (distance - MIN_DISTANCE_CM_FOR_MIN_ANGLE) /
                   (MAX_DISTANCE_CM_FOR_MAX_ANGLE - MIN_DISTANCE_CM_FOR_MIN_ANGLE) *
                   (float)(MAX_ANGLE_DEG - MIN_ANGLE_DEG) + MIN_ANGLE_DEG;

    if (angle < MIN_ANGLE_DEG) angle = MIN_ANGLE_DEG;
    if (angle > MAX_ANGLE_DEG) angle = MAX_ANGLE_DEG;

    return (int)angle;
}

static int set_servo_angle(int angle) {
    if (angle < MIN_ANGLE_DEG || angle > MAX_ANGLE_DEG) {
        fprintf(stderr, "Error: angle %d out of range [%d, %d].\n",
                angle, MIN_ANGLE_DEG, MAX_ANGLE_DEG);
        return -1;
    }

    int pulse_width = 500 + (angle * 2000) / 180;
    if (gpioServo(SERVO_PIN, pulse_width) < 0) {
        fprintf(stderr, "Error: gpioServo failed for pulse %d.\n", pulse_width);
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    /* Stop servo (0°) */
    gpioServo(SERVO_PIN, 0);
    gpioDelay(SERVO_SETTLE_US);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float distance = measure_distance();

        if (distance < 0.0f) {
            printf("Distance: ERROR (timeout or out of range)\n");
        } else {
            int angle = calculate_angle(distance);
            if (angle < 0) {
                printf("Distance: %.2f cm, Angle: ERROR (out of range)\n", distance);
            } else {
                printf("Distance: %.2f cm, Angle: %d degrees\n", distance, angle);
                if (set_servo_angle(angle) != 0) {
                    fprintf(stderr, "Error: failed to set servo angle.\n");
                }
            }
        }

        gpioDelay(MEASURE_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

