#include <pigpio.h>

#define SI7005_ADDR 0x19
#define CONFIG_REG 0x01
#define HUMIDITY_REG 0x0B
#define I2C_BUS 1
#define CONVERSION_DELAY_US 10000
#define LOOP_DELAY_US 2000000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg(int handle, uint8_t reg, uint8_t value) {
    char buf[2] = { (char)reg, (char)value };
    if (i2cWriteDevice(handle, buf, 2) != 0) {
        return -1;
    }
    return 0;
}

static int i2c_read_reg(int handle, uint8_t reg, uint8_t *value) {
    char reg_buf[1] = { (char)reg };
    if (i2cWriteDevice(handle, reg_buf, 1) != 0) {
        return -1;
    }
    char data_buf[1];
    if (i2cReadDevice(handle, data_buf, 1) != 1) {
        return -1;
    }
    *value = (uint8_t)data_buf[0];
    return 0;
}

static int read_humidity(int handle, float *humidity) {
    uint8_t humidity_raw;
    if (i2c_read_reg(handle, HUMIDITY_REG, &humidity_raw) != 0) {
        return -1;
    }
    *humidity = (float)humidity_raw / 100.0f;
    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, SI7005_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X on bus %d\n", SI7005_ADDR, I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

