            fprintf(stderr, "Failed to read humidity. Re-initializing I2C.\n");
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(I2C_BUS, SI7005_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Failed to re-open I2C device. Exiting.\n");
                break;
            }
            if (i2c_write_reg(i2c_handle, CONFIG_REG, 0x01) != 0) {
                fprintf(stderr, "Failed to re-initialize sensor. Exiting.\n");
                break;
            }
        }
        gpioDelay(LOOP_DELAY_US);
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

