#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* MPU-6050 I2C address (AD0 tied to GND) */
#define MPU6050_ADDR 0x68

/* MPU-6050 registers */
#define MPU6050_WHO_AM_I   0x75
#define MPU6050_PWR_MGMT_1 0x6B
#define MPU6050_ACCEL_XOUT_H 0x3B
#define MPU6050_GYRO_XOUT_H  0x43

/* Expected WHO_AM_I value for MPU-6050 */
#define MPU6050_WHO_AM_I_VAL 0x68

/* I2C bus on Raspberry Pi 3 Model B+ */
#define I2C_BUS 1

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Read a single byte register; returns -1 on error */
static int mpu6050_read_reg(int handle, uint8_t reg, uint8_t *val)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read error at reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

/* Write a single byte register; returns -1 on error */
static int mpu6050_write_reg(int handle, uint8_t reg, uint8_t val)
{
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write error at reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    return 0;
}

/* Read 14 bytes of sensor data starting at ACCEL_XOUT_H; returns -1 on error */
static int mpu6050_read_raw_data(int handle, int16_t *ax, int16_t *ay, int16_t *az,
                                  int16_t *gx, int16_t *gy, int16_t *gz)
{
    uint8_t buf[14];
    int rc = i2cReadI2CBlockData(handle, MPU6050_ACCEL_XOUT_H, (char *)buf, 14);
    if (rc != 14) {
        fprintf(stderr, "I2C block read error: expected 14 bytes, got %d\n", rc);
        return -1;
    }

    *ax = (int16_t)((buf[0]  << 8) | buf[1]);
    *ay = (int16_t)((buf[2]  << 8) | buf[3]);
    *az = (int16_t)((buf[4]  << 8) | buf[5]);
    /* buf[6..7] = temperature (skipped) */
    *gx = (int16_t)((buf[8]  << 8) | buf[9]);
    *gy = (int16_t)((buf[10] << 8) | buf[11]);
    *gz = (int16_t)((buf[12] << 8) | buf[13]);
    return 0;
}

int main(void)
{
    int handle = -1;

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus 1 at MPU-6050 address --- */
    handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X: %d\n",
                I2C_BUS, MPU6050_ADDR, handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Verify sensor identity --- */
    uint8_t whoami = 0;
    if (mpu6050_read_reg(handle, MPU6050_WHO_AM_I, &whoami) != 0) {
        fprintf(stderr, "Cannot read WHO_AM_I — sensor absent or bus error\n");
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (whoami != MPU6050_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                whoami, MPU6050_WHO_AM_I_VAL);
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MPU-6050 detected (WHO_AM_I = 0x%02X). Starting data acquisition...\n",
           whoami);

    /* --- Start sensor: wake up, set to normal mode --- */
    if (mpu6050_write_reg(handle, MPU6050_PWR_MGMT_1, 0x00) != 0) {
        fprintf(stderr, "Failed to write PWR_MGMT_1\n");
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioDelay(100000); /* 100 ms settle time */

    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* --- Main acquisition loop --- */
    while (g_running) {
        int16_t ax, ay, az, gx, gy, gz;

        if (mpu6050_read_raw_data(handle, &ax, &ay, &az, &gx, &gy, &gz) == 0) {
            printf("Accel: X=%6d Y=%6d Z=%6d  |  Gyro: X=%6d Y=%6d Z=%6d\n",
                   ax, ay, az, gx, gy, gz);
        } else {
            fprintf(stderr, "Read error — continuing\n");
        }

        gpioDelay(100000); /* 100 ms */
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");
    if (handle >= 0) {
        i2cClose(handle);
    }
    gpioTerminate();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

