code:
/*
 * Raspberry Pi 4 Model B – SHT40 Temperature & Humidity Logger
 *
 * Wiring:
 *   SHT40 VDD  -> Pi 3V3  (pin 1)
 *   SHT40 GND  -> Pi GND  (pin 9)
 *   SHT40 SDA  -> Pi GPIO2 / I2C1 SDA (pin 3)
 *   SHT40 SCL  -> Pi GPIO3 / I2C1 SCL (pin 5)
 *
 * I2C bus 1, address 0x40 (ADDR pin tied to GND).
 *
 * Build:  gcc -O2 -Wall -Wextra -o sht40_logger sht40_logger.c -lpigpio -lrt
 * Run:    sudo ./sht40_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SHT40_ADDR     0x40
#define MEASURE_CMD    0x2C   /* High repeatability, clock stretching disabled */
#define MEASURE_DELAY_US 10000 /* 10 ms – covers the 7.5 ms max conversion time */
#define SAMPLE_PERIOD_S 5
#define MAX_RETRIES    3

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 as used by Sensirion: poly 0x31, init 0xFF, no final XOR       */
static bool sht40_crc_ok(const uint8_t *data, size_t len, uint8_t checksum)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return (crc == checksum);
}

/* ------------------------------------------------------------------ */
/* Returns 0 on success, -1 on I2C error, -2 on CRC mismatch.           */
static int sht40_read(int handle, float *temperature, float *humidity)
{
    uint8_t cmd = MEASURE_CMD;
    uint8_t buf[6];

    /* Send measurement command */
    if (i2cWriteDevice(handle, (char *)&cmd, 1) != 1) {
        fprintf(stderr, "[ERROR] I2C write failed (cmd 0x%02X)\n", cmd);
        return -1;
    }

    /* Wait for conversion to complete */
    gpioDelay(MEASURE_DELAY_US);

    /* Read 6 bytes: T_MSB T_LSB T_CRC  RH_MSB RH_LSB RH_CRC */
    if (i2cReadDevice(handle, (char *)buf, 6) != 6) {
        fprintf(stderr, "[ERROR] I2C read failed (expected 6 bytes)\n");
        return -1;
    }

    /* Validate CRCs */
    if (!sht40_crc_ok(&buf[0], 2, buf[2])) {
        fprintf(stderr, "[ERROR] Temperature CRC mismatch\n");
        return -2;
    }
    if (!sht40_crc_ok(&buf[3], 2, buf[5])) {
        fprintf(stderr, "[ERROR] Humidity CRC mismatch\n");
        return -2;
    }

    uint16_t t_raw = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t rh_raw = ((uint16_t)buf[3] << 8) | buf[4];

    *temperature = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *humidity    = 100.0f * (float)rh_raw / 65535.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    int handle = -1;
    int rc = EXIT_FAILURE;

    /* ---- Signal handling ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, SHT40_ADDR, handle);
        goto cleanup_gpio;
    }

    printf("SHT40 logger started on I2C bus %d, address 0x%02X.\n", I2C_BUS, SHT40_ADDR);
    printf("Sampling every %d seconds. Press Ctrl+C to exit.\n", SAMPLE_PERIOD_S);

    /* ---- Main loop ---- */
    while (g_running) {
        float temperature, humidity;

        int attempt;
        for (attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            int r = sht40_read(handle, &temperature, &humidity);
            if (r == 0) {
                printf("Temperature: %.2f °C, Humidity: %.2f %%\n",
                       temperature, humidity);
                fflush(stdout);
                break;
            }
            fprintf(stderr, "[WARN] Read attempt %d/%d failed, re-opening I2C bus.\n",
                    attempt + 1, MAX_RETRIES);
            i2cClose(handle);
            handle = -1;
            gpioDelay(100000); /* 100 ms back-off */
        }

        if (g_running) {
            /* If all retries failed, log the error and continue */
            fprintf(stderr, "[ERROR] All %d read attempts failed this cycle.\n", MAX_RETRIES);
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD_S * 10 && g_running; i++) {
            gpioDelay(100000);
        }
    }

    rc = EXIT_SUCCESS;

    /* ---- Graceful cleanup ---- */
    if (handle >= 0) {
        i2cClose(handle);
    }
    gpioTerminate();

    printf("\nExiting cleanly.\n");
    return rc;

cleanup_gpio:
    i2cClose(handle);
    gpioTerminate();
    return EXIT_FAILURE;
}

