#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define MLX90614_ADDR 0x60
#define MLX90614_REG_CONFIG 0x2400
#define MLX90614_REG_AMBIENT 0x2401
#define MLX90614_REG_OBJECT 0x2402
#define LOG_FILE "temperature_log.csv"
#define READ_INTERVAL 5

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write16(int fd, uint16_t reg, uint16_t value) {
    uint8_t buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (value >> 8) & 0xFF;
    buf[3] = value & 0xFF;
    if (write(fd, buf, 4) != 4) {
        return -1;
    }
    return 0;
}

static int i2c_read16(int fd, uint16_t reg, uint16_t *value) {
    uint8_t buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (write(fd, buf, 2) != 2) {
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        return -1;
    }
    *value = (buf[0] << 8) | buf[1];
    return 0;
}

static int read_temperature(int fd, uint16_t *ambient, uint16_t *object) {
    if (i2c_read16(fd, MLX90614_REG_AMBIENT, ambient) < 0) {
        return -1;
    }
    if (i2c_read16(fd, MLX90614_REG_OBJECT, object) < 0) {
        return -1;
    }
    return 0;
}

static int log_temperature(FILE *fp, uint16_t ambient, uint16_t object) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%u,%u\n", timestamp, ambient, object) < 0) {
        return -1;
    }
    fflush(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MLX90614_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (i2c_write16(i2c_fd, MLX90614_REG_CONFIG, 0x0000) < 0) {
        fprintf(stderr, "Failed to configure sensor\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,AmbientTemperature,ObjectTemperature\n");
        fflush(log_file);
    }

    printf("Starting temperature monitoring. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t ambient = 0, object = 0;

        if (read_temperature(i2c_fd, &ambient, &object) == 0) {
            if (log_temperature(log_file, ambient, object) != 0) {
                fprintf(stderr, "Error logging temperature.\n");
            }
        } else {
            fprintf(stderr, "Error reading temperature.\n");
        }

        for (int i = 0; i < READ_INTERVAL && running; i++) {
            sleep(1);
        }
    }

    printf("\nExiting gracefully...\n");
    if (log_file) {
        fclose(log_file);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    return EXIT_SUCCESS;
}

