#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define STS30_ADDR 0x15
#define LOG_FILE "enclosure_temp_log.txt"
#define ERROR_LOG_FILE "error_log.txt"
#define SAMPLE_INTERVAL_SEC 5

/* STS30-DIS commands */
#define STS30_CMD_MEASURE_TEMP 0x361C
#define STS30_CMD_READ_TEMP 0x361B
#define STS30_CMD_RESET 0x805D

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_fp = NULL;
static FILE *error_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_error(const char *msg) {
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];
    localtime_r(&now, &tm_info);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
    if (error_fp) {
        fprintf(error_fp, "%s: %s\n", ts, msg);
        fflush(error_fp);
    }
    fprintf(stderr, "%s: %s\n", ts, msg);
}

static int i2c_write_cmd(uint16_t cmd) {
    char buf[2] = { (char)(cmd >> 8), (char)(cmd & 0xFF) };
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        log_error("I2C write failed");
        return -1;
    }
    return 0;
}

static int i2c_read_data(uint8_t *buf, int len) {
    int n = i2cReadDevice(i2c_handle, (char *)buf, len);
    if (n != len) {
        log_error("I2C read failed");
        return -1;
    }
    return 0;
}

static int sts30_reset(void) {
    if (i2c_write_cmd(STS30_CMD_RESET) != 0) return -1;
    time_sleep(0.1);
    return 0;
}

static int sts30_read_temp(float *temp) {
    if (i2c_write_cmd(STS30_CMD_READ_TEMP) != 0) return -1;
    time_sleep(0.01);
    uint8_t buf[3];
    if (i2c_read_data(buf, 3) != 0) return -1;
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *temp = -45.0f + 175.0f * ((float)raw / 65536.0f);
    return 0;
}

static int log_temperature(float temp) {
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];
    localtime_r(&now, &tm_info);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
    if (fprintf(log_fp, "%s, %.2f\n", ts, temp) < 0) {
        log_error("Failed to write to log file");
        return -1;
    }
    fflush(log_fp);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_fp) { fclose(log_fp); log_fp = NULL; }
    if (error_fp) { fclose(error_fp); error_fp = NULL; }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, STS30_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X\n", STS30_ADDR);
        gpioTerminate();
        return 1;
    }

    if (sts30_reset() != 0) {
        fprintf(stderr, "STS30 reset failed; sensor may be absent or bus error\n");
        cleanup();
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    error_fp = fopen(ERROR_LOG_FILE, "a");
    if (!error_fp) {
        perror("Failed to open error log file");
        cleanup();
        return 1;
    }

    printf("STS30 logging started. Press Ctrl+C to stop.\n");

    while (running) {
        float temp;
        if (sts30_read_temp(&temp) == 0) {
            if (log_temperature(temp) != 0) {
                log_error("Failed to log temperature");
            }
        } else {
            log_error("STS30 read failed; skipping sample");
        }
        time_sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

