#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define SDP810_I2C_ADDR 0x29
#define LOG_FILE "pressure_log.csv"
#define SAMPLE_INTERVAL_SEC 1
#define MEASUREMENT_DELAY_MS 10

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        perror("i2c_write_cmd: write failed");
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        perror("i2c_read_bytes: read failed");
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "i2c_read_bytes: short read (%zd of %zu)\n", n, len);
        return -1;
    }
    return 0;
}

static int sdp810_init(int fd) {
    uint8_t init_cmd[] = {0x36, 0x07, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00};
    if (i2c_write_cmd(fd, 0x36) < 0) return -1;
    if (i2c_write_cmd(fd, 0x07) < 0) return -1;
    if (i2c_write_cmd(fd, 0x00) < 0) return -1;
    if (i2c_write_cmd(fd, 0x00) < 0) return -1;
    if (i2c_write_cmd(fd, 0x00) < 0) return -1;
    if (i2c_write_cmd(fd, 0x00) < 0) return -1;
    if (i2c_write_cmd(fd, 0x00) < 0) return -1;
    usleep(10000);
    return 0;
}

static int sdp810_read(int fd, float *pressure, float *temperature) {
    uint8_t data[9];
    if (i2c_read_bytes(fd, data, sizeof(data)) < 0) return -1;

    if (crc8(&data[0], 2) != data[2]) {
        fprintf(stderr, "CRC error: pressure\n");
        return -1;
    }
    if (crc8(&data[3], 2) != data[5]) {
        fprintf(stderr, "CRC error: temperature\n");
        return -1;
    }
    if (crc8(&data[6], 2) != data[8]) {
        fprintf(stderr, "CRC error: scale factor\n");
        return -1;
    }

    int16_t raw_pressure = (int16_t)((data[0] << 8) | data[1]);
    int16_t raw_temp = (int16_t)((data[3] << 8) | data[4]);
    int16_t scale_factor = (int16_t)((data[6] << 8) | data[7]);

    if (scale_factor == 0) {
        fprintf(stderr, "Invalid scale factor (0)\n");
        return -1;
    }

    *pressure = (float)raw_pressure / (float)scale_factor;
    *temperature = (float)raw_temp / 200.0f;
    return 0;
}

