    time_t now = time(NULL);
    struct tm tm_utc;
    gmtime_r(&now, &tm_utc);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);

    if (log_fp == NULL) {
        log_fp = fopen(LOG_FILE, "a");
        if (log_fp == NULL) {
            perror("fopen log file");
            return -1;
        }
        fseek(log_fp, 0, SEEK_END);
        if (ftell(log_fp) == 0) {
            fprintf(log_fp, "Timestamp,Pressure(Pa),Temperature(C)\n");
        }
    }

    if (fprintf(log_fp, "%s,%.4f,%.2f\n", ts, pressure, temperature) < 0) {
        perror("fprintf log");
        return -1;
    }
    fflush(log_fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction SIGINT");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction SIGTERM");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SDP810_I2C_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(i2c_fd);
        return 1;
    }

    if (sdp810_init(i2c_fd) < 0) {
        fprintf(stderr, "SDP810 init failed (sensor absent or bus error)\n");
        close(i2c_fd);
        return 1;
    }

    printf("SDP810 initialized. Logging to %s every %d second(s).\n", LOG_FILE, SAMPLE_INTERVAL_SEC);

    while (running) {
        float pressure, temperature;
        if (sdp810_read(i2c_fd, &pressure, &temperature) == 0) {
            if (log_data(pressure, temperature) < 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
        } else {
            fprintf(stderr, "Sensor read failed; continuing.\n");
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down cleanly.\n");
    if (log_fp) fclose(log_fp);
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

