#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SHT40_ADDR        0x40
#define SHT40_CMD_MEASURE 0xE3  /* high repeatability, clock stretching disabled */
#define SHT40_MEASURE_MS  10   /* datasheet: typ 8.5 ms, max 12 ms */
#define LOG_FILE          "sht40_log.txt"
#define SAMPLE_INTERVAL_S 5

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Sensirion CRC-8: polynomial 0x31, init 0xFF, no reflect, no final XOR */
static uint8_t sht_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint8_t cmd)
{
    if (write(fd, &cmd, 1) != 1) {
        perror("i2c_write_cmd: write failed");
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    size_t total = 0;
    while (total < len) {
        ssize_t n = read(fd, buf + total, len - total);
        if (n < 0) {
            perror("i2c_read_bytes: read failed");
            return -1;
        }
        if (n == 0) {
            fprintf(stderr, "i2c_read_bytes: unexpected EOF (sensor may be absent)\n");
            return -1;
        }
        total += (size_t)n;
    }
    return 0;
}

static int read_sht40(int fd, float *temp, float *hum)
{
    uint8_t data[6];

    if (i2c_write_cmd(fd, SHT40_CMD_MEASURE) < 0)
        return -1;

    usleep(SHT40_MEASURE_MS * 1000);

    if (i2c_read_bytes(fd, data, sizeof(data)) < 0)
        return -1;

    /* Validate CRCs for temperature and humidity words */
    if (sht_crc8(&data[0], 2) != data[2]) {
        fprintf(stderr, "SHT40: temperature CRC mismatch\n");
        return -1;
    }
    if (sht_crc8(&data[3], 2) != data[5]) {
        fprintf(stderr, "SHT40: humidity CRC mismatch\n");
        return -1;
    }

    uint16_t t_raw = ((uint16_t)data[0] << 8) | data[1];
    uint16_t h_raw = ((uint16_t)data[3] << 8) | data[4];

    *temp = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *hum  = 100.0f * (float)h_raw / 65535.0f;

    return 0;
}

static void log_data(FILE *fp, float temp, float hum)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Temperature: %.2f C, Humidity: %.2f %%\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, temp, hum);
    fflush(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open /dev/i2c-1");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, SHT40_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        return EXIT_FAILURE;
    }

    FILE *log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen " LOG_FILE);
        close(fd);
        return EXIT_FAILURE;
    }

    printf("SHT40 logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        float temp, hum;
        if (read_sht40(fd, &temp, &hum) == 0) {
            log_data(log_fp, temp, hum);
            printf("T=%.2f C  H=%.2f %%\n", temp, hum);
        } else {
            fprintf(stderr, "Read failed; will retry next cycle.\n");
        }
        sleep(SAMPLE_INTERVAL_S);
    }

    printf("\nShutting down cleanly.\n");
    fclose(log_fp);
    close(fd);
    return EXIT_SUCCESS;
}

