#define MEASURE_CMD    0x361C
#define LOG_FILE       "airflow.log"
#define SAMPLE_US      100000   /* 100 ms */
#define MAX_RETRIES    3
#define MEAS_DELAY_US  2000     /* 2 ms  */

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF)                       */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Trigger a continuous measurement                                  */
/* ------------------------------------------------------------------ */
static int sdp31_trigger(int handle)
{
    uint8_t cmd[2] = {
        (uint8_t)((MEASURE_CMD >> 8) & 0xFF),
        (uint8_t)(MEASURE_CMD & 0xFF)
    };
    int rc = i2cWriteDevice(handle, (char *)cmd, 2);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read 6 bytes of measurement data                                  */
/* ------------------------------------------------------------------ */
static int sdp31_read(int handle, float *pressure, float *temperature)
{
    uint8_t buf[6];
    int rc = i2cReadDevice(handle, (char *)buf, 6);
    if (rc != 6) {
        fprintf(stderr, "[ERROR] i2cReadDevice returned %d: %s\n",
                rc, rc < 0 ? strerror(errno) : "short read");
        return -1;
    }

    /* CRC checks */
    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "[ERROR] pressure CRC mismatch\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "[ERROR] temperature CRC mismatch\n");
        return -1;
    }

    int16_t raw_pressure = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_temp     = (int16_t)((buf[3] << 8) | buf[4]);

    *pressure    = (float)raw_pressure;   /* Pa  */
    *temperature = (float)raw_temp;        /* °C  */
    return 0;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped CSV line to the log file                       */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, float pressure, float temperature)
{
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "[ERROR] time() failed: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed\n");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "[ERROR] strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%.2f,%.2f\n", ts, pressure, temperature) < 0) {
        fprintf(stderr, "[ERROR] fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "[ERROR] fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] gpioInitialise failed\n");
        return EXIT_FAILURE;
    }

    /* ---- open I2C ---- */
    g_i2c_handle = i2cOpen(I2C_BUS, SDP31_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, SDP31_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- open log file ---- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- signals ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGINT) failed: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGTERM) failed: %s\n", strerror(errno));
    }

    /* ---- main loop ---- */
    while (g_running) {
        float pressure = 0.0f;
        float temperature = 0.0f;

        int success = 0;
        for (int attempt = 1; attempt <= MAX_RETRIES && g_running; attempt++) {
            if (sdp31_trigger(g_i2c_handle) == 0) {
                gpioDelay(MEAS_DELAY_US);
                if (sdp31_read(g_i2c_handle, &pressure, &temperature) == 0) {
                    success = 1;
                    break;
                }
            }
            if (attempt < MAX_RETRIES)
                gpioDelay((uint32_t)(attempt * 1000 * 1000)); /* 1 s, 2 s, 3 s */
        }

        if (success) {
            if (log_data(g_log_file, pressure, temperature) != 0)
                fprintf(stderr, "[WARN] logging failed\n");
        } else {
            fprintf(stderr, "[WARN] sensor read failed after %d attempts\n", MAX_RETRIES);
        }

        gpioDelay(SAMPLE_US);
    }

    /* ---- graceful shutdown ---- */
    fprintf(stderr, "\n[INFO] shutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

