#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI7015_ADDR 0x15
#define LOG_FILE "sensor_data.txt"
#define SAMPLE_INTERVAL_SEC 5
#define MEAS_TIMEOUT_MS 20

/* Si7015 No Hold Master commands (16-bit, big-endian on the bus) */
#define SI7015_CMD_TEMP_HOLD   0x3608
#define SI7015_CMD_HUM_HOLD    0x3808

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/*
 * Read a 16-bit big-endian command from the caller and write it to the
 * Si7015 using i2cWriteWordData.  Returns 0 on success, -1 on error.
 */
static int send_command(uint16_t cmd)
{
    if (i2cWriteWordData(g_i2c_handle, cmd) < 0) {
        fprintf(stderr, "Error: i2cWriteWordData(0x%04X) failed: %s\n",
                cmd, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read a 16-bit big-endian result from the Si7015 using i2cReadWordData.
 * Returns 0 on success and stores the value in *out; returns -1 on error.
 */
static int read_result(uint16_t *out)
{
    int raw = i2cReadWordData(g_i2c_handle, 0x0000);
    if (raw < 0) {
        fprintf(stderr, "Error: i2cReadWordData failed: %s\n", strerror(errno));
        return -1;
    }
    *out = (uint16_t)raw;
    return 0;
}

/*
 * Read temperature or humidity from the Si7015.
 * Returns 0 on success and stores the value in *out; returns -1 on error.
 */
static int read_measurement(uint16_t cmd, uint16_t *out)
{
    if (send_command(cmd) < 0)
        return -1;

    /* Si7015 No Hold Master conversion takes ~10 ms; poll up to MEAS_TIMEOUT_MS */
    for (int i = 0; i < MEAS_TIMEOUT_MS / 2; i++) {
        if (read_result(out) == 0)
            return 0;
        gpioDelay(1000); /* 1 ms */
    }

    fprintf(stderr, "Error: measurement timeout for command 0x%04X\n", cmd);
    return -1;
}

static int log_data(float temperature, float humidity)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Temperature: %.2f C, Humidity: %.2f %%\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            temperature, humidity);

    if (fclose(fp) != 0) {
        fprintf(stderr, "Warning: fclose(%s) failed: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SI7015_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, SI7015_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Si7015 sensor logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        uint16_t raw;
        float temperature = 0.0f;
        float humidity = 0.0f;

        if (read_measurement(SI7015_CMD_TEMP_HOLD, &raw) == 0) {
            temperature = -45.0f + 175.0f * ((float)raw / 65535.0f);
        } else {
            fprintf(stderr, "Error: temperature read failed\n");
        }

        if (read_measurement(SI7015_CMD_HUM_HOLD, &raw) == 0) {
            humidity = 100.0f * ((float)raw / 65535.0f);
        } else {
            fprintf(stderr, "Error: humidity read failed\n");
        }

        if (log_data(temperature, humidity) != 0) {
            fprintf(stderr, "Error: logging failed\n");
        }

        /* Sleep in 100 ms increments so SIGINT is caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_SEC * 10 && g_running; i++)
            gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

