#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SDP800_ADDR    0x48
#define LOG_FILE       "airflow_data.txt"
#define SAMPLE_MS      100
#define MEASURE_MS     45

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* CRC-8 polynomial 0x31, init 0xFF, as used by Sensirion SDP800 */
static uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int i2c_write(int fd, const uint8_t *buf, size_t len) {
    if (write(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "I2C read failed (got %zd of %zu): %s\n",
                n, len, strerror(errno));
        return -1;
    }
    return 0;
}

static int sdp800_trigger(int fd) {
    /* Continuous measurement trigger: 0x36 0x00 0x00 */
    uint8_t cmd[3] = {0x36, 0x00, 0x00};
    return i2c_write(fd, cmd, sizeof(cmd));
}

static int sdp800_read(int fd, float *pressure, float *temperature) {
    uint8_t raw[9];
    if (i2c_read(fd, raw, sizeof(raw)) != 0)
        return -1;

    /* Validate CRC for each 3-byte word */
    if (crc8(&raw[0], 2) != raw[2]) {
        fprintf(stderr, "Pressure CRC mismatch\n");
        return -1;
    }
    if (crc8(&raw[3], 2) != raw[5]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }
    if (crc8(&raw[6], 2) != raw[8]) {
        fprintf(stderr, "Scale-factor CRC mismatch\n");
        return -1;
    }

    int16_t raw_p = (int16_t)((raw[0] << 8) | raw[1]);
    int16_t raw_t = (int16_t)((raw[3] << 8) | raw[4]);
    int16_t scale = (int16_t)((raw[6] << 8) | raw[7]);

    if (scale == 0) {
        fprintf(stderr, "Invalid scale factor (0)\n");
        return -1;
    }

    *pressure = (float)raw_p / (float)scale;
    *temperature = (float)raw_t / 200.0f;
    return 0;
}

static void log_data(float pressure, float temperature) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[64];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s,%.2f,%.2f\n", ts, pressure, temperature);
    } else {
        fprintf(fp, "timestamp_error,%.2f,%.2f\n", pressure, temperature);
    }
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, SDP800_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                SDP800_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    /* Probe sensor by attempting a trigger */
    if (sdp800_trigger(fd) != 0) {
        fprintf(stderr, "SDP800 not responding at 0x%02X\n", SDP800_ADDR);
        close(fd);
        return 1;
    }

    FILE *fp = fopen(LOG_FILE, "r");
    if (!fp) {
        fp = fopen(LOG_FILE, "w");
        if (fp) {
            fprintf(fp, "timestamp,pressure_pa,temperature_c\n");
            fclose(fp);
        } else {
            fprintf(stderr, "Cannot create %s: %s\n", LOG_FILE, strerror(errno));
            close(fd);
            return 1;
        }
    } else {
        fclose(fp);
    }

    while (g_running) {
        if (sdp800_trigger(fd) != 0) {
            usleep(MEASURE_MS * 1000);
            continue;
        }
        usleep(MEASURE_MS * 1000);

        float pressure, temperature;
        if (sdp800_read(fd, &pressure, &temperature) != 0) {
            usleep(SAMPLE_MS * 1000);
            continue;
        }

        log_data(pressure, temperature);
        usleep(SAMPLE_MS * 1000);
    }

    close(fd);
    return 0;
}

