#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define STS30_ADDR     0x15
#define MEASURE_CMD    0x36
#define CONVERSION_MS  15
#define SAMPLE_PERIOD  5
#define LOG_FILE       "enclosure_temp_log.txt"
#define ERROR_LOG_FILE "error_log.txt"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void log_error(const char *msg) {
    FILE *fp = fopen(ERROR_LOG_FILE, "a");
    if (!fp) {
        perror("fopen(error_log)");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s: %s\n", ts, msg);
    }
    fclose(fp);
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int read_sts30(int handle, float *temp) {
    uint8_t cmd[1] = { MEASURE_CMD };
    uint8_t buf[3];

    if (i2cWriteDevice(handle, (char *)cmd, 1) != 0) {
        log_error("I2C write failed");
        return -1;
    }

    gpioDelay(CONVERSION_MS * 1000);

    if (i2cReadDevice(handle, (char *)buf, 3) != 3) {
        log_error("I2C read failed");
        return -1;
    }

    if (crc8(buf, 2) != buf[2]) {
        log_error("CRC mismatch");
        return -1;
    }

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *temp = -45.0f + 175.0f * (float)raw / 65535.0f;
    return 0;
}

static void log_reading(float temp) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(log)");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s, %.2f\n", ts, temp);
    }
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, STS30_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("STS30 logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        float temp;
        if (read_sts30(g_i2c_handle, &temp) == 0) {
            log_reading(temp);
            printf("Temperature: %.2f C\n", temp);
        } else {
            fprintf(stderr, "Read failed; continuing.\n");
        }
        gpioDelay(SAMPLE_PERIOD * 1000000);
    }

    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return 0;
}

