/*
 * Smart Greenhouse Monitor — SHT40 humidity & temperature logger
 * Board:  Raspberry Pi 3 Model B+
 * Bus:    /dev/i2c-1
 * Sensor: Sensirion SHT40 (fixed I2C address 0x15)
 * Log:    sht40_log.txt (timestamped CSV: timestamp,Temperature_C,Humidity_RH)
 *
 * Build:  gcc -O2 -Wall -Wextra -o sht40_monitor sht40_monitor.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SHT40_ADDR     0x15
#define LOG_FILE       "sht40_log.txt"
#define SAMPLE_PERIOD  5          /* seconds between readings */
#define MEAS_DELAY_US  9000       /* 9 ms — exceeds SHT40 max conversion time */

/* SHT40 high-repeatability measurement command (MSB first) */
#define CMD_MSB        0x2C
#define CMD_LSB        0x07

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Sensirion CRC-8 (poly 0x31, init 0xFF) — used for T, RH, and CRC words */
/* ------------------------------------------------------------------ */
static uint8_t sht40_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

/*
 * Write a 2-byte command to the SHT40.
 * Returns 0 on success, -1 on error.
 */
static int sht40_write_cmd(int fd, uint8_t msb, uint8_t lsb)
{
    uint8_t cmd[2] = { msb, lsb };
    if (write(fd, cmd, 2) != 2) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read 6 bytes from the SHT40 (T_MSB, T_LSB, T_CRC, RH_MSB, RH_LSB, RH_CRC).
 * Returns 0 on success, -1 on error.
 */
static int sht40_read_data(int fd, uint8_t *data)
{
    ssize_t n = read(fd, data, 6);
    if (n != 6) {
        fprintf(stderr, "I2C read failed (got %zd bytes): %s\n",
                n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Data validation                                                     */
/* ------------------------------------------------------------------ */
static int validate_temperature(const uint8_t *raw, float *temp_c)
{
    if (sht40_crc8(raw, 2) != raw[2]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }
    uint16_t t_raw = ((uint16_t)raw[0] << 8) | raw[1];
    *temp_c = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    return 0;
}

static int validate_humidity(const uint8_t *raw, float *rh)
{
    if (sht40_crc8(raw, 2) != raw[3]) {
        fprintf(stderr, "Humidity CRC mismatch\n");
        return -1;
    }
    uint16_t h_raw = ((uint16_t)raw[0] << 8) | raw[1];
    *rh = -6.0f + 125.0f * (float)h_raw / 65535.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_open(const char *path)
{
    g_log_fp = fopen(path, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", path, strerror(errno));
        return -1;
    }
    return 0;
}

static void log_reading(float temp_c, float rh)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    if (fprintf(g_log_fp, "%s,%.2f,%.2f\n", ts, temp_c, rh) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
    } else {
        fflush(g_log_fp);
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = i2c_open(I2C_BUS, SHT40_ADDR);
    if (g_i2c_fd < 0)
        return EXIT_FAILURE;

    if (log_open(LOG_FILE) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

