        uint8_t data[6];

        if (sht40_write_cmd(g_i2c_fd, CMD_MSB, CMD_LSB) < 0) {
            fprintf(stderr, "Measurement command failed; retrying next cycle.\n");
            sleep(SAMPLE_PERIOD);
