/*
 * SDP800-500Pa differential pressure monitor for Raspberry Pi 3 Model B+.
 *
 * Wiring:
 *   SDP800 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   SDP800 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   SDP800 VDD  -> 3.3 V (pin 1)
 *   SDP800 GND  -> GND  (pin 6)
 *
 * Build:  gcc -O2 -Wall -Wextra -o airflow_monitor airflow_monitor.c
 * Run:    ./airflow_monitor   (requires r/w access to /dev/i2c-1)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SDP800_ADDR    0x48
#define LOG_FILE       "airflow_data.txt"
#define SAMPLE_PERIOD  1          /* seconds between samples */
#define MEAS_DELAY_MS  1          /* SDP800 needs >=1 ms after start */
#define MAX_RETRIES    3

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log   = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF)                        */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Millisecond sleep                                                  */
/* ------------------------------------------------------------------ */
static void sleep_ms(unsigned int ms)
{
    struct timespec ts = {
        .tv_sec  = ms / 1000,
        .tv_nsec = (long)(ms % 1000) * 1000000L
    };
    nanosleep(&ts, NULL);
}

/* ------------------------------------------------------------------ */
/* Read one 6-byte measurement frame from the SDP800                  */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int sdp800_read(int fd, float *pressure, float *temperature)
{
    uint8_t buf[6];

    if (read(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }

    /* CRC checks */
    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Pressure CRC mismatch\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }

    int16_t raw_pressure    = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_temperature = (int16_t)((buf[3] << 8) | buf[4]);

    *pressure    = (float)raw_pressure    / 100.0f;   /* Pa */
    *temperature = (float)raw_temperature / 100.0f;   /* °C  */

    return 0;
}

/* ------------------------------------------------------------------ */
/* Append one CSV line                                               */
/* ------------------------------------------------------------------ */
static int log_sample(FILE *fp, float pressure, float temperature)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.2f,%.2f\n", ts, pressure, temperature) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log) {
        fclose(g_log);
        g_log = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SDP800_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                SDP800_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Start continuous measurement */
    uint8_t cmd[2] = { 0x36, 0x00 };   /* continuous measurement, no averaging */
    if (write(g_i2c_fd, cmd, sizeof(cmd)) != (ssize_t)sizeof(cmd)) {
        fprintf(stderr, "Failed to send start-measurement command: %s\n",
                strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    sleep_ms(MEAS_DELAY_MS);

    printf("SDP800 monitoring started. Logging to %s. Press Ctrl+C to stop.\n",
           LOG_FILE);

    int consecutive_errors = 0;

    while (g_running) {
        float pressure = 0.0f, temperature = 0.0f;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (sdp800_read(g_i2c_fd, &pressure, &temperature) == 0) {
                ok = 1;
                break;
            }
            sleep_ms(10);
        }

        if (ok) {
            if (log_sample(g_log, pressure, temperature) != 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
            printf("Pressure: %.2f Pa, Temperature: %.2f °C\n",
                   pressure, temperature);
        } else {
            consecutive_errors++;
            fprintf(stderr, "Sensor read failed (%d consecutive)\n",
                    consecutive_errors);
            if (consecutive_errors >= 10) {
                fprintf(stderr, "Too many consecutive failures; aborting.\n");
                break;
            }
        }

        if (g_running)
            sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

