        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SDP800_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                SDP800_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Start continuous measurement */
    uint8_t cmd[2] = { 0x36, 0x00 };   /* continuous measurement, no averaging */
    if (write(g_i2c_fd, cmd, sizeof(cmd)) != (ssize_t)sizeof(cmd)) {
        fprintf(stderr, "Failed to send start-measurement command: %s\n",
                strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    sleep_ms(MEAS_DELAY_MS);

    printf("SDP800 monitoring started. Logging to %s. Press Ctrl+C to stop.\n",
           LOG_FILE);

    int consecutive_errors = 0;

    while (g_running) {
        float pressure = 0.0f, temperature = 0.0f;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (sdp800_read(g_i2c_fd, &pressure, &temperature) == 0) {
                ok = 1;
                break;
            }
            sleep_ms(10);
        }

        if (ok) {
            if (log_sample(g_log, pressure, temperature) != 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
            printf("Pressure: %.2f Pa, Temperature: %.2f °C\n",
                   pressure, temperature);
        } else {
            consecutive_errors++;
            fprintf(stderr, "Sensor read failed (%d consecutive)\n",
                    consecutive_errors);
            if (consecutive_errors >= 10) {
                fprintf(stderr, "Too many consecutive failures; aborting.\n");
                break;
            }
        }

        if (g_running)
            sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

