#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SI7021_ADDR    0x40
#define FAN_GPIO       18
#define TEMP_REG       0x88
#define HUM_REG        0x8E
#define HUMIDITY_REG   0x8C
#define TEMP_LSB       0
#define TEMP_MSB       1
#define HUMIDITY_LSB   0
#define HUMIDITY_MSB   1
#define BUFFER_SIZE    60
#define RETRY_COUNT    3
#define RETRY_DELAY_US 10000
#define SAMPLE_INTERVAL_S 2
#define FAN_ON_TEMP    28.0f
#define FAN_OFF_TEMP   27.0f
#define FAN_HOLD_MS    100

typedef struct {
    time_t timestamp;
    float  temperature;
} Reading;

static Reading buffer[BUFFER_SIZE];
static int  buffer_index = 0;
static int  buffer_count = 0;
static int  i2c_handle = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void sleep_ms(unsigned ms) {
    gpioDelay((unsigned)ms * 1000);
}

static int read_si7021(float *temperature, float *humidity) {
    char reg = TEMP_REG;
    char data[2];
    int  result;

    result = i2cWriteDevice(i2c_handle, &reg, 1);
    if (result < 0) {
        fprintf(stderr, "I2C write error (reg select): %d\n", result);
        return -1;
    }

    result = i2cReadDevice(i2c_handle, data, 2);
    if (result < 0) {
        fprintf(stderr, "I2C read error: %d\n", result);
        return -1;
    }
    if (result != 2) {
        fprintf(stderr, "I2C short read: %d bytes\n", result);
        return -1;
    }

    int16_t raw_temp = (int16_t)((data[TEMP_MSB] << TEMP_LSB) | (data[TEMP_LSB] >> 8));
    int16_t raw_hum  = (int16_t)((data[HUMIDITY_MSB] << HUMIDITY_LSB) | (data[HUMIDITY_LSB] >> 8));

    *temperature = (float)raw_temp / 100.0f;
    *humidity    = (float)raw_hum / 100.0f;
    return 0;
}

static void add_reading(float temperature) {
    time(&buffer[buffer_index].timestamp);
    buffer[buffer_index].temperature = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
}

static void print_latest(float temperature) {
    int idx = (buffer_index - 1 + BUFFER_SIZE) % BUFFER_SIZE;
    char ts[32];
    struct tm tm_info;
    localtime_r(&buffer[idx].timestamp, &tm_info);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
    printf("[%s] Temperature: %.2f C\n", ts, temperature);
    fflush(stdout);
}

static void control_fan(float temperature) {
    static bool fan_on = false;
    if (temperature > FAN_ON_TEMP && !fan_on) {
        if (gpioWrite(FAN_GPIO, 1) == 0) {
            fan_on = true;
            printf("Fan ON\n");
        } else {
            fprintf(stderr, "Failed to turn fan ON\n");
        }
    } else if (temperature < FAN_OFF_TEMP && fan_on) {
        if (gpioWrite(FAN_GPIO, 0) == 0) {
            fan_on = false;
            printf("Fan OFF\n");
        } else {
            fprintf(stderr, "Failed to turn fan OFF\n");
        }
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(FAN_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    float temperature, humidity;
    int  result;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %d\n", SI7021_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", FAN_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(FAN_GPIO, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Si7021 monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        result = read_si7021(&temperature, &humidity);
        if (result == 0) {
            add_reading(temperature);
            print_latest(temperature);
            control_fan(temperature);
        } else {
            fprintf(stderr, "Read failed; retrying in %d ms...\n", RETRY_DELAY_US / 1000);
            sleep_ms(RETRY_DELAY_US);
        }

        if (running) {
            sleep_ms(SAMPLE_INTERVAL_S * 1000);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

