#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SCD40_I2C_ADDR 0x60
#define SCD40_CMD_START_PERIODIC 0x0010
#define SCD40_CMD_STOP_PERIODIC 0x0011
#define SCD40_CMD_READ_MEASUREMENT 0x0020
#define SCD40_DATA_READY_MASK 0x0001
#define SCD40_DATA_READY 0x01
#define SCD40_MEASUREMENT_INTERVAL 5
#define SCD40_STARTUP_DELAY 1
#define LOG_FILE "air_quality.log"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int scd40_write_command(uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    int rc = i2cWriteDevice(i2c_handle, (char *)buf, 2);
    if (rc < 0) {
        fprintf(stderr, "Error: i2cWriteDevice failed for command 0x%04X (rc=%d)\n", cmd, rc);
        return -1;
    }
    return 0;
}

static int scd40_read_measurement(uint8_t *buf, int len) {
    int rc = i2cReadDevice(i2c_handle, (char *)buf, len);
    if (rc != len) {
        fprintf(stderr, "Error: i2cReadDevice failed (rc=%d, expected %d)\n", rc, len);
        return -1;
    }
    return 0;
}

static int scd40_data_ready(void) {
    uint8_t buf[1];
    if (scd40_write_command(SCD40_CMD_READ_MEASUREMENT) < 0)
        return -1;
    gpioDelay(2000);
    if (scd40_read_measurement(buf, 1) < 0)
        return -1;
    return (buf[0] & SCD40_DATA_READY_MASK) ? 1 : 0;
}

static int scd40_read_measurement(int *co2, float *temp, float *rh) {
    uint8_t buf[9];
    if (scd40_write_command(SCD40_CMD_READ_MEASUREMENT) < 0)
        return -1;
    gpioDelay(2000);
    if (scd40_read_measurement(buf, 9) < 0)
        return -1;

    for (int i = 0; i < 6; i++) {
        if (crc8(&buf[i * 2], 2) != buf[i * 2 + 2]) {
            fprintf(stderr, "Error: CRC mismatch on word %d\n", i);
            return -1;
        }
    }

    int co2_raw = (buf[0] << 8) | buf[1];
    *co2 = co2_raw;
    int temp_raw = (buf[3] << 8) | buf[4];
    *temp = temp_raw / 100.0f;
    int rh_raw = (buf[6] << 8) | buf[7];
    *rh = rh_raw / 100.0f;
    return 0;
}

static void log_data(int co2, float temp, float rh) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s,%d,%.2f,%.2f\n", ts, co2, temp, rh);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, SCD40_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (rc=%d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: cannot open %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    if (scd40_write_command(SCD40_CMD_START_PERIODIC) < 0) {
        fprintf(stderr, "Error: failed to start periodic measurement\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioDelay(SCD40_STARTUP_DELAY * 1000000);

    while (running) {
        int ready = scd40_data_ready();
        if (ready < 0) {
            fprintf(stderr, "Error: data-ready check failed\n");
            gpioDelay(SCD40_MEASUREMENT_INTERVAL * 1000000);
            continue;
        }
        if (ready == 0) {
            gpioDelay(SCD40_MEASUREMENT_INTERVAL * 1000000);
            continue;
        }

        int co2;
        float temp, rh;
        if (scd40_read_measurement(&co2, &temp, &rh) < 0) {
            fprintf(stderr, "Error: measurement read failed\n");
            gpioDelay(SCD40_MEASUREMENT_INTERVAL * 1000000);
            continue;
        }

        log_data(co2, temp, rh);
        printf("CO2: %d ppm, Temp: %.2f C, RH: %.2f %%\n", co2, temp, rh);

        gpioDelay(SCD40_MEASUREMENT_INTERVAL * 1000000);
    }

    if (scd40_write_command(SCD40_CMD_STOP_PERIODIC) < 0)
        fprintf(stderr, "Warning: failed to stop periodic measurement\n");
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();
    return 0;
}

