            gpioDelay(SCD40_MEASUREMENT_INTERVAL * 1000000);
            continue;
        }
        if (ready == 0) {
            gpioDelay(SCD40_MEASUREMENT_INTERVAL * 1000000);
            continue;
        }

        int co2;
        float temp, rh;
        if (scd40_read_measurement(&co2, &temp, &rh) < 0) {
            fprintf(stderr, "Error: measurement read failed\n");
            gpioDelay(SCD40_MEASUREMENT_INTERVAL * 1000000);
            continue;
        }

        log_data(co2, temp, rh);
        printf("CO2: %d ppm, Temp: %.2f C, RH: %.2f %%\n", co2, temp, rh);

        gpioDelay(SCD40_MEASUREMENT_INTERVAL * 1000000);
    }

    if (scd40_write_command(SCD40_CMD_STOP_PERIODIC) < 0)
        fprintf(stderr, "Warning: failed to stop periodic measurement\n");
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();
    return 0;
}

