#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS        "/dev/i2c-1"
#define SCD40_ADDR     0x60
#define CO2_THRESHOLD  1000
#define LED_GPIO       17
#define BUFFER_SIZE    20
#define POLL_INTERVAL  5

/* SCD40 command set (16-bit, big-endian on the bus) */
#define CMD_START      0x361F
#define CMD_STOP       0x362F
#define CMD_READ_MEAS  0x361B

typedef struct {
    uint16_t co2;
    uint16_t temperature;
    uint16_t humidity;
    bool valid;
} sensor_data_t;

static sensor_data_t ring_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int i2c_fd = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* CRC-8 polynomial 0x31, init 0xFF, as used by Sensirion SCD4x */
static uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int i2c_write_cmd(uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write failed (cmd 0x%04X): %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_data(uint16_t *co2, uint16_t *temp, uint16_t *hum) {
    uint8_t buf[9];
    ssize_t n = read(i2c_fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C read failed: expected %zu bytes, got %zd (%s)\n",
                sizeof(buf), n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }

    /* SCD40 measurement frame: 3 words, each 2 data bytes + 1 CRC byte */
    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on CO2 word\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "CRC mismatch on temperature word\n");
        return -1;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "CRC mismatch on humidity word\n");
        return -1;
    }

    *co2  = (uint16_t)((buf[0] << 8) | buf[1]);
    *temp = (uint16_t)((buf[3] << 8) | buf[4]);
    *hum  = (uint16_t)((buf[6] << 8) | buf[7]);
    return 0;
}

static void add_to_buffer(uint16_t co2, uint16_t temp, uint16_t hum) {
    ring_buffer[buffer_index].co2  = co2;
    ring_buffer[buffer_index].temperature = temp;
    ring_buffer[buffer_index].humidity = hum;
    ring_buffer[buffer_index].valid = true;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

static void print_buffer(void) {
    printf("\n--- Ring Buffer (%d entries) ---\n", BUFFER_SIZE);
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int idx = (buffer_index + i) % BUFFER_SIZE;
        if (ring_buffer[idx].valid) {
            printf("  [%2d] CO2=%u ppm  T=%u C  RH=%u %%\n",
                   i, ring_buffer[idx].co2,
                   ring_buffer[idx].temperature,
                   ring_buffer[idx].humidity);
        } else {
            printf("  [%2d]  (invalid)\n", i);
        }
    }
    printf("--------------------------------\n");
    fflush(stdout);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SCD40_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                SCD40_ADDR, strerror(errno));
        close(i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Start continuous measurement mode */
    if (i2c_write_cmd(CMD_START) != 0) {
        fprintf(stderr, "Failed to start SCD40; sensor may be absent or bus error.\n");
        close(i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Allow first measurement to complete */
    sleep(1);

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    printf("SCD40 monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t co2, temp, hum;
        if (i2c_read_data(&co2, &temp, &hum) == 0) {
            add_to_buffer(co2, temp, hum);
            printf("CO2: %u ppm  T: %u C  RH: %u %%\n", co2, temp, hum);
            if (co2 > CO2_THRESHOLD)
                gpioWrite(LED_GPIO, 1);
            else
                gpioWrite(LED_GPIO, 0);
        } else {
            fprintf(stderr, "Sensor read failed; continuing.\n");
        }
        sleep(POLL_INTERVAL);
    }

    /* Graceful shutdown */
    gpioWrite(LED_GPIO, 0);
    i2c_write_cmd(CMD_STOP);
    close(i2c_fd);
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

