/*
 * TMP05 digital temperature sensor reader for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   TMP05 VCC  -> 3.3 V (pin 1)
 *   TMP05 GND  -> GND   (pin 9)
 *   TMP05 OUT  -> GPIO4 (BCM, physical pin 7)
 *
 * The TMP05 output is a PWM-style square wave where the high-pulse
 * width scales linearly with temperature (TL = 0.5 ms/°C, TH = 0.5 ms/°C).
 * T = (TH - TL) / 0.5  (°C)
 *
 * Build:  gcc -O2 -Wall -Wextra -o tmp05_reader tmp05_reader.c -lpigpio -lrt
 * Run:    sudo ./tmp05_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN        4
#define LOG_FILE        "temperature_log.txt"
#define SAMPLE_INTERVAL 5          /* seconds between readings */
#define EDGE_TIMEOUT_US 50000      /* 50 ms per edge wait */
#define MAX_CONSEC_ERR 3            /* consecutive failures before log entry */
#define MIN_TEMP_C      (-40.0f)
#define MAX_TEMP_C      (150.0f)

static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Busy-wait for a level on the GPIO line with a timeout.               */
/* Returns 0 on success, -1 on timeout.                                 */
/* ------------------------------------------------------------------ */
static int wait_level(int gpio, int level, uint32_t timeout_us)
{
    uint32_t start = gpioTick();
    while (gpioRead(gpio) != level) {
        if ((gpioTick() - start) >= timeout_us)
            return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Measure the high-pulse width in microseconds.                        */
/* ------------------------------------------------------------------ */
static uint32_t measure_high_pulse(int gpio)
{
    if (wait_level(gpio, 1, EDGE_TIMEOUT_US) < 0)
        return 0;

    uint32_t start = gpioTick();
    if (wait_level(gpio, 0, EDGE_TIMEOUT_US) < 0)
        return 0;

    return (uint32_t)(gpioTick() - start);
}

/* ------------------------------------------------------------------ */
/* Compute temperature in degrees Celsius from high/low widths.         */
/* Returns 0 on success, -1 on division-by-zero, -2 on invalid range.  */
/* ------------------------------------------------------------------ */
static int compute_temperature(uint32_t high_us, uint32_t low_us,
                               float *temp_c)
{
    if (high_us == 0 && low_us == 0)
        return -1;                       /* division by zero */

    if (high_us == 0 || low_us == 0) {
        return -2;                        /* invalid pulse pattern */
    }

    float th = (float)high_us / 1000.0f;
    float tl = (float)low_us / 1000.0f;

    if (th <= 0.0f || tl <= 0.0f || th >= 100.0f || tl >= 100.0f)
        return -2;

    *temp_c = (th - tl) / 0.5f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Write a timestamped temperature reading to the log file.             */
/* ------------------------------------------------------------------ */
static void log_temperature(float temp_c)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }

    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);

    if (fprintf(g_log, "%s, %.2f\n", ts, temp_c) < 0) {
        perror("fprintf to log file failed");
    } else {
        fflush(g_log);
    }
}

/* ------------------------------------------------------------------ */
/* Check whether a reading is within the TMP05 valid range.           */
/* ------------------------------------------------------------------ */
static bool is_valid(float temp_c)
{
    return (temp_c >= MIN_TEMP_C && temp_c <= MAX_TEMP_C);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Signal handling ------------------------------------------- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---------------------------------------- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Open log file -------------------------------------------- */
    g_log = fopen(LOG_FILE, "a");
    if (g_log == NULL) {
        perror("fopen(" LOG_FILE ")");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Configure GPIO4 as input ---------------------------------- */
    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_INPUT) failed\n", GPIO_PIN);
        fclose(g_log);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Enable internal pull-down so the line is defined when the
     * TMP05 output is idle (low). */
    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "gpioSetPullUpDown(%d, PI_PUD_DOWN) failed\n",
                GPIO_PIN);
        fclose(g_log);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("TMP05 reader started. GPIO%d, logging to %s every %d s.\n",
           GPIO_PIN, LOG_FILE, SAMPLE_INTERVAL);
    printf("Press Ctrl+C to exit.\n");

    int consecutive_errors = 0;

    /* ---- Main sampling loop ---------------------------------------- */
    while (g_running) {
        uint32_t high_us = 0, low_us = 0;

        /* Measure high pulse */
        if (measure_high_pulse(GPIO_PIN) < 0) {
            consecutive_errors++;
            fprintf(stderr, "Error: failed to measure high pulse\n");
            if (consecutive_errors >= MAX_CONSEC_ERR) {
                fprintf(stderr,
                        "SENSOR MALFUNCTION: %d consecutive failures\n",
                        consecutive_errors);
                fprintf(g_log, "SENSOR MALFUNCTION: %d consecutive failures\n",
                        consecutive_errors);
                fflush(g_log);
            }
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        /* Measure low pulse */
        if (measure_high_pulse(GPIO_PIN) < 0) {
            consecutive_errors++;
            fprintf(stderr, "Error: failed to measure low pulse\n");
            if (consecutive_errors >= MAX_CONSEC_ERR) {
                fprintf(stderr,
                        "SENSOR MALFUNCTION: %d consecutive failures\n",
                        consecutive_errors);
                fprintf(g_log, "SENSOR MALFUNCTION: %d consecutive failures\n",
                        consecutive_errors);
                fflush(g_log);
            }
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        float temp_c;
        int rc = compute_temperature(high_us, low_us, &temp_c);

        if (rc == 0) {
            if (!is_valid(temp_c)) {
                fprintf(stderr, "Warning: temperature %.2f C out of range\n",
                        temp_c);
                fprintf(g_log, "Warning: temperature %.2f C out of range\n",
                        temp_c);
                fflush(g_log);
            } else {
                log_temperature(temp_c);
                printf("Temperature: %.2f C\n", temp_c);
            }
        } else {
            fprintf(stderr, "Error: failed to compute temperature\n");
            fprintf(g_log, "Error: failed to compute temperature\n");
            fflush(g_log);
        }

        consecutive_errors = 0;
        sleep(SAMPLE_INTERVAL);
    }

    /* ---- Clean shutdown -------------------------------------------- */
    printf("\nShutting down...\n");
    if (g_log != NULL) {
        fclose(g_log);
        g_log = NULL;
    }
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

