#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SHT35_ADDR     0x15
#define MEASURE_CMD    0x2C  /* high repeatability, clock stretching disabled */
#define MEASURE_DELAY_US 15000  /* 15 ms */
#define RETRY_COUNT    3
#define RETRY_DELAY_US 1000000  /* 1 s */
#define SAMPLE_INTERVAL_US 5000000  /* 5 s */
#define OFFSET_SCALE    2.0f
#define OFFSET_AMPL     5.0f
#define OFFSET_PERIOD   3600.0f  /* 1 hour */
#define LOG_FILE        "environmental_data.txt"

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Sensirion CRC-8 (polynomial 0x31, init 0xFF)                        */
/* ------------------------------------------------------------------ */
static uint8_t sht_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Read SHT35 with retries and CRC validation                          */
/* ------------------------------------------------------------------ */
static bool read_sht35(float *temperature, float *humidity)
{
    uint8_t cmd[2] = { (uint8_t)(MEASURE_CMD >> 8), (uint8_t)(MEASURE_CMD & 0xFF) };
    uint8_t buf[6];
    int rc;

    for (int attempt = 0; attempt < RETRY_COUNT; attempt++) {
        rc = i2cWriteDevice(g_i2c_handle, (char *)cmd, 2);
        if (rc != 0) {
            fprintf(stderr, "[attempt %d] i2cWriteDevice failed (rc=%d)\n", attempt + 1, rc);
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        gpioDelay(MEASURE_DELAY_US);

        rc = i2cReadDevice(g_i2c_handle, (char *)buf, 6);
        if (rc != 6) {
            fprintf(stderr, "[attempt %d] i2cReadDevice returned %d\n", attempt + 1, rc);
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        /* Validate CRC for temperature word (bytes 0-1, CRC byte 2) */
        if (sht_crc8(buf, 2) != buf[2]) {
            fprintf(stderr, "[attempt %d] temperature CRC mismatch\n", attempt + 1);
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        /* Validate CRC for humidity word (bytes 3-4, CRC byte 5) */
        if (sht_crc8(buf + 3, 2) != buf[5]) {
            fprintf(stderr, "[attempt %d] humidity CRC mismatch\n", attempt + 1);
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        uint16_t t_raw = ((uint16_t)buf[0] << 8) | buf[1];
        uint16_t h_raw = ((uint16_t)buf[3] << 8) | buf[4];

        *temperature = -45.0f + 175.0f * (float)t_raw / 65535.0f;
        *humidity    = 100.0f * (float)h_raw / 65535.0f;

        return true;
    }

    fprintf(stderr, "Failed to read SHT35 after %d attempts.\n", RETRY_COUNT);
    return false;
}

/* ------------------------------------------------------------------ */
/* Simulated greenhouse offset (sinusoidal over 1-hour period)          */
/* ------------------------------------------------------------------ */
static float simulate_greenhouse_offset(float t, float h)
{
    float t_offset = OFFSET_SCALE * (sinf(t / OFFSET_PERIOD * 2.0f * M_PI) + 1.0f);
    float h_offset = OFFSET_AMPL * (sinf(h / OFFSET_PERIOD * 2.0f * M_PI) + 1.0f);

    return t_offset + t, h_offset + h;
}

/* ------------------------------------------------------------------ */
/* Log one reading with ISO-8601 UTC timestamp                          */
/* ------------------------------------------------------------------ */
static void log_data(float t, float h)
{
    time_t now = time(NULL);
    struct tm tm_utc;
    char ts[32];

    gmtime_r(&now, &tm_utc);
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);

    fprintf(g_log_file, "%s,%.2f,%.2f\n", ts, t, h);
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    float t, h;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (rc=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("fopen(" LOG_FILE ")");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fprintf(g_log_file, "# timestamp,temperature_c,humidity_rh\n");
    fflush(g_log_file);

    while (g_running) {
        if (read_sht35(&t, &h)) {
            t = simulate_greenhouse_offset(t, h);
            h = simulate_greenhouse_offset(h, t);
            log_data(t, h);
        } else {
            fprintf(stderr, "Sensor read failed; logging NaN values.\n");
            t = NAN;
            h = NAN;
            log_data(t, h);
        }

        /* Sleep in 100 ms slices so signals are caught promptly */
        for (int i = 0; i < 50 && g_running; i++)
            gpioDelay(100000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

