/*
 * SDP810-125Pa differential pressure sensor logger for Raspberry Pi 3 B+
 * I2C bus 1, address 0x48 (verified against datasheet).
 *
 * Build:  gcc -O2 -Wall -Wextra -o airflow airflow.c
 * Run:    ./airflow
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SDP810_ADDR     0x48
#define CSV_FILENAME    "airflow.csv"
#define SAMPLE_PERIOD_S 1
#define CONV_TIME_MS    45

/* SDP810 continuous measurement command (datasheet) */
static const uint8_t CMD_CONT_MEAS[2] = { 0x36, 0x08 };

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (polynomial 0x31, init 0xFF) — Sensirion datasheet            */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int fd, const uint8_t *cmd, size_t len)
{
    if (write(fd, cmd, len) != (ssize_t)len) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "I2C short read: got %zd, expected %zu\n", n, len);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor data structure                                               */
/* ------------------------------------------------------------------ */
typedef struct {
    float pressure;          /* pascals */
    float temperature;       /* degrees Celsius */
    int   valid;             /* 1 = OK, 0 = CRC error, -1 = bus error */
} sensor_data_t;

/* ------------------------------------------------------------------ */
/* Read one 9-byte measurement frame                                 */
/* ------------------------------------------------------------------ */
static sensor_data_t read_sdp810(int fd)
{
    sensor_data_t d = { .pressure = 0.0f, .temperature = 0.0f, .valid = 0 };
    uint8_t raw[9];

    if (i2c_read_block(fd, raw, sizeof(raw)) != 0)
        return d;

    /* CRC checks: bytes 0-2, 3-5, 6-8 each have an 8-bit CRC */
    if (crc8(&raw[0], 2) != raw[2]) {
        fprintf(stderr, "Pressure CRC mismatch\n");
        return d;
    }
    if (crc8(&raw[3], 2) != raw[5]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return d;
    }
    if (crc8(&raw[6], 2) != raw[8]) {
        fprintf(stderr, "Scale-factor CRC mismatch\n");
        return d;
    }

    int16_t raw_p = (int16_t)((raw[0] << 8) | raw[1]);
    int16_t raw_t = (int16_t)((raw[3] << 8) | raw[4]);
    int16_t raw_s = (int16_t)((raw[6] << 8) | raw[7]);

    /* SDP810 conversion formulas (datasheet) */
    d.pressure    = (float)raw_p / 100.0f;          /* pascals */
    d.temperature = (float)raw_t / 200.0f;           /* degrees Celsius */
    d.valid        = 1;
    return d;
}

/* ------------------------------------------------------------------ */
/* CSV logging                                                         */
/* ------------------------------------------------------------------ */
static int log_data(const char *filename, float pressure, float temperature)
{
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", filename, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.2f\n", ts, pressure, temperature);
    fclose(fp);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
