#include <pigpio.h>

#define I2C_BUS        1
#define SHT35_ADDR     0x15
#define MEASURE_CMD    0x2C
#define MEASURE_DELAY_US 15000   /* 15 ms — datasheet: typ 12.1 ms, max 15 ms */
#define SAMPLE_PERIOD_S 5
#define CSV_FILENAME   "environment.csv"

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* CRC-8 as used by Sensirion: polynomial 0x31, init 0xFF */
static uint8_t sht35_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/*
 * Read temperature (°C) and relative humidity (%RH) from the SHT35.
 * Returns 0 on success, -1 on I/O error, -2 on CRC mismatch.
 */
static int sht35_read(int handle, float *temperature, float *humidity)
{
    uint8_t cmd[1] = { MEASURE_CMD };
    uint8_t data[6];

    if (i2cWriteDevice(handle, (char *)cmd, 1) != 1) {
        fprintf(stderr, "Error: i2cWriteDevice failed: %s\n", strerror(errno));
        return -1;
    }

    gpioDelay(MEASURE_DELAY_US);

    if (i2cReadDevice(handle, (char *)data, 6) != 6) {
        fprintf(stderr, "Error: i2cReadDevice failed: %s\n", strerror(errno));
        return -1;
    }

    if (sht35_crc8(&data[0], 2) != data[2]) {
        fprintf(stderr, "Error: temperature CRC mismatch\n");
        return -2;
    }
    if (sht35_crc8(&data[3], 2) != data[5]) {
        fprintf(stderr, "Error: humidity CRC mismatch\n");
        return -2;
    }

    uint16_t t_raw = (uint16_t)((data[0] << 8) | data[1]);
    uint16_t h_raw = (uint16_t)((data[3] << 8) | data[4]);

    *temperature = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *humidity    = 100.0f * (float)h_raw / 65535.0f;

    return 0;
}

static int log_data(const char *filename, float temperature, float humidity)
{
    int needs_header = 0;
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        needs_header = 1;
    } else {
        fseek(fp, 0, SEEK_END);
        if (ftell(fp) == 0) needs_header = 1;
        fclose(fp);
    }

    fp = fopen(filename, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: cannot open %s: %s\n", filename, strerror(errno));
        return -1;
    }

    if (needs_header) {
        fprintf(fp, "timestamp,temperature_c,humidity_pct\n");
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        fclose(fp);
        return -1;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.2f\n", ts, temperature, humidity);
    fclose(fp);
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGTERM) failed: %s\n", strerror(errno));
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int handle = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Error: i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, SHT35_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("SHT35 sensor logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        float temperature, humidity;

        int rc = sht35_read(handle, &temperature, &humidity);
        if (rc == 0) {
            printf("Temperature: %.2f °C, Humidity: %.2f %%\n", temperature, humidity);
            if (log_data(CSV_FILENAME, temperature, humidity) != 0) {
                fprintf(stderr, "Warning: log_data failed\n");
            }
        } else {
            fprintf(stderr, "Warning: sensor read failed (code %d)\n", rc);
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD_S * 10 && g_running; i++) {
            gpioDelay(100000);
        }
    }

    i2cClose(handle);
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

