#define I2C_BUS        "/dev/i2c-1"
#define SI7021_ADDR    0x40
#define LOG_FILE       "environment.log"
#define POLL_INTERVAL  5
#define MEAS_TIMEOUT   100

#define CMD_RESET       0xB0
#define CMD_MEASURE    0xFA
#define CMD_READ_TEMP  0xBE
#define CMD_READ_HUM   0x57

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0x00;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint8_t cmd)
{
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write(0x%02X) failed: %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, int len)
{
    int n = read(fd, buf, len);
    if (n != len) {
        fprintf(stderr, "I2C read failed: expected %d, got %d (%s)\n",
                len, n, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_measurement(int fd, uint8_t cmd, float *out)
{
    if (i2c_write_cmd(fd, cmd) < 0)
        return -1;

    for (int i = 0; i < MEAS_TIMEOUT; i++) {
        uint8_t buf[3];
        if (i2c_read_bytes(fd, buf, 3) < 0)
            return -1;
        if (crc8(buf, 2) == buf[2])
            *out = (float)((uint16_t)buf[0] << 8 | buf[1]);
        usleep(10000);
    }
    return -2;
}

static int read_sensor(int fd, float *temp, float *hum)
{
    if (read_measurement(fd, CMD_READ_TEMP, temp) < 0)
        return -1;
    if (read_measurement(fd, CMD_READ_HUM, hum) < 0)
        return -1;
    return 0;
}

static void log_data(float temp, float hum)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s,%.2f,%.2f\n", ts, temp, hum);
    } else {
        fprintf(fp, "ERROR,ERROR,ERROR\n");
    }
    fclose(fp);
}

