        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                SI7021_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (i2c_write_cmd(fd, CMD_RESET) < 0) {
        fprintf(stderr, "Sensor reset failed; continuing anyway.\n");
    } else {
        usleep(15000);
    }

    while (g_running) {
        float temp, hum;
        int rc = read_sensor(fd, &temp, &hum);
        if (rc == 0) {
            log_data(temp, hum);
            printf("T=%.2f C  H=%.2f %%\n", temp, hum);
        } else if (rc == -1) {
            fprintf(stderr, "Sensor read error; issuing reset.\n");
            i2c_write_cmd(fd, CMD_RESET);
        } else {
            fprintf(stderr, "Measurement timeout.\n");
        }
        for (int i = 0; i < POLL_INTERVAL && g_running; i++)
            sleep(1);
    }

    close(fd);
    return 0;
}

