/*
 * SDP800-500Pa differential pressure logger for Raspberry Pi 3 Model B+
 * I2C bus 1, address 0x48, continuous measurement command 0x3608.
 * Logs timestamped pressure readings to pressure_log.txt every 5 s.
 *
 * Build:  gcc -O2 -Wall -Wextra -o sdp800_logger sdp800_logger.c -lpigpio -lrt
 * Run:    sudo ./sdp800_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS              1
#define SDP800_ADDR          0x48
#define MEASURE_CMD          0x3608
#define CONVERSION_TIME_US   45000   /* 45 ms */
#define SAMPLE_INTERVAL_S    5
#define LOG_FILE             "pressure_log.txt"
#define MAX_RETRIES          3

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF)                        */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Read one 9-byte measurement frame                                     */
/* ------------------------------------------------------------------ */
static int read_sdp800(int handle, float *pressure)
{
    uint8_t buf[9];
    int rc;

    rc = i2cReadDevice(handle, (char *)buf, sizeof(buf));
    if (rc != (int)sizeof(buf)) {
        fprintf(stderr, "[ERROR] I2C read failed (rc=%d)\n", rc);
        return -1;
    }

    /* Validate CRC for each 2-byte data word */
    for (int i = 0; i < 3; i++) {
        if (crc8(&buf[i * 3], 2) != buf[i * 3 + 2]) {
            fprintf(stderr, "[ERROR] CRC mismatch on word %d\n", i);
            return -1;
        }
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *pressure = (float)raw;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log a reading                                                       */
/* ------------------------------------------------------------------ */
static void log_pressure(FILE *fp, float pressure)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed\n");
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, %.2f Pa\n", ts, pressure);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    float pressure;
    int  attempt;

    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- open I2C ---- */
    g_i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed (rc=%d). Sensor absent or bus error.\n",
                g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- open log file ---- */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        fprintf(stderr, "[FATAL] Cannot open %s\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- signals ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("SDP800-500Pa logger started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_INTERVAL_S);
    printf("Press Ctrl-C to stop.\n");

    /* ---- main loop ---- */
    while (g_running) {
        attempt = 0;
        while (attempt < MAX_RETRIES && g_running) {
            if (read_sdp800(g_i2c_handle, &pressure) == 0) {
