#define HAFBLF0100A2AX5_REG_PRESSURE_LSB 0x01
#define HAFBLF0100A2AX5_REG_CONFIG 0x02

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3] = { reg, (uint8_t)(value >> 8), (uint8_t)(value & 0xFF) };
    if (write(fd, buf, 3) != 3) {
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        return -1;
    }
    *value = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int read_pressure(int fd, float *pressure) {
    uint16_t raw;
    if (i2c_read_reg16(fd, HAFBLF0100A2AX5_REG_PRESSURE_MSB, &raw) < 0) {
        return -1;
    }
    int16_t signed_raw = (int16_t)raw;
    *pressure = (float)signed_raw * 0.01f;
    return 0;
}

static void set_fan_speed(int gpio, int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 100) duty_cycle = 100;
    gpioPWM(gpio, duty_cycle);
}

static void log_data(float pressure) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s,%.2f\n", timestamp, pressure);
    fflush(log_file);
}

