        perror("Failed to acquire I2C bus access");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    if (i2c_write_reg16(i2c_fd, HAFBLF0100A2AX5_REG_CONFIG, 0x0000) < 0) {
        fprintf(stderr, "Failed to configure sensor\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMrange(FAN_GPIO, 100) < 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    printf("Starting airflow monitoring. Press Ctrl+C to exit.\n");

    while (running) {
        float pressure;
        if (read_pressure(i2c_fd, &pressure) < 0) {
            fprintf(stderr, "Error reading pressure from sensor\n");
        } else {
            int duty_cycle = (int)(pressure * 100.0f);
            if (duty_cycle < 0) duty_cycle = 0;
            if (duty_cycle > 100) duty_cycle = 100;
            set_fan_speed(FAN_GPIO, duty_cycle);
            log_data(pressure);
        }
        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    set_fan_speed(FAN_GPIO, 0);
    if (i2c_fd >= 0) close(i2c_fd);
    if (log_file != NULL) fclose(log_file);
    gpioTerminate();
    printf("Cleanup complete.\n");
    return 0;
}

