#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* LPS33HW register addresses */
#define LPS33HW_REG_PRESSURE_MSB   0x01
#define LPS33HW_REG_TEMP_MSB       0x03
#define LPS33HW_REG_CONFIG_REG     0x0F

/* Configuration: ODR = 1 Hz, STANDBY = 0, I2C mode */
#define LPS33HW_CONFIG_VALUE       0x00

/* I2C bus on Raspberry Pi 4 */
#define I2C_BUS 1
#define I2C_ADDR 0x19

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* Write a 16-bit value to a 16-bit register address */
static int write_reg16(int handle, uint8_t reg_msb, uint16_t value)
{
    char buf[3];
    buf[0] = (char)reg_msb;
    buf[1] = (char)(value >> 8);
    buf[2] = (char)(value & 0xFF);
    if (i2cWriteDevice(handle, buf, 3) != 3) {
        return -1;
    }
    return 0;
}

/* Read a 16-bit value from a 16-bit register address */
static int read_reg16(int handle, uint8_t reg_msb, uint16_t *out)
{
    char reg_buf[1];
    char data_buf[2];
    reg_buf[0] = (char)reg_msb;

    if (i2cWriteDevice(handle, reg_buf, 1) != 1) {
        return -1;
    }
    if (i2cReadDevice(handle, data_buf, 2) != 2) {
        return -1;
    }
    *out = ((uint16_t)(uint8_t)data_buf[0] << 8) | (uint8_t)data_buf[1];
    return 0;
}

/* Read pressure (hPa) and temperature (°C) from the LPS33HW */
static int read_sensor_data(int handle, float *pressure, float *temperature)
{
    uint16_t raw_pressure, raw_temperature;

    if (read_reg16(handle, LPS33HW_REG_PRESSURE_MSB, &raw_pressure) != 0) {
        return -1;
    }
    if (read_reg16(handle, LPS33HW_REG_TEMP_MSB, &raw_temperature) != 0) {
        return -1;
    }

    /* LPS33HW: pressure is 20-bit left-justified, temperature is 16-bit */
    int32_t pressure_raw = (int32_t)raw_pressure;
    if (pressure_raw & 0x80000) {
        pressure_raw |= 0xFFF00000; /* sign-extend */
    }
    *pressure = (float)pressure_raw / 4096.0f;

    int16_t temp_raw = (int16_t)raw_temperature;
    *temperature = (float)temp_raw / 100.0f;

    return 0;
}

/* Format current time as YYYY-MM-DD HH:MM:SS */
static void format_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime_r(&rawtime, buf);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", timeinfo);
}

/* Log a line to stderr and the log file */
static void log_line(const char *msg)
{
    char ts[32];
    format_timestamp(ts, sizeof(ts));

    fprintf(stderr, "%s - %s\n", ts, msg);
    if (log_file) {
        fprintf(log_file, "%s - %s\n", ts, msg);
        fflush(log_file);
    }
}

int main(void)
{
    float pressure, temperature;
    char timestamp[32];

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    i2c_handle = i2cOpen(I2C_BUS, LPS33HW_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d)\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_file = fopen("environmental_data.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error: cannot open environmental_data.txt\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure sensor: 1 Hz ODR, standby 0, I2C mode */
    if (write_reg16(i2c_handle, LPS33HW_REG_CONFIG_REG, LPS33HW_CONFIG_VALUE) != 0) {
        log_line("Error: failed to write LPS33HW config register");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Allow sensor to enter active mode */
    gpioDelay(100000); /* 100 ms */

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        log_line("Warning: could not install SIGINT handler");
    }

    log_line("LPS33HW environmental monitor started");

    /* Main sampling loop */
    while (!terminate) {
        if (read_sensor_data(i2c_handle, &pressure, &temperature) == 0) {
            log_line("Pressure: %.2f hPa, Temperature: %.2f °C", pressure, temperature);
        } else {
            log_line("Error: sensor read failed");
        }
        gpioDelay(1000000); /* 1 second */
    }

    /* Cleanup */
    log_line("Shutting down");
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

