#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x48
#define GPIO_LED       17
#define TEMP_THRESHOLD 28.0f
#define BUFFER_SIZE    10
#define SAMPLE_PERIOD  1.0f   /* seconds */

/* STLM75 register addresses (command bit auto-increment) */
#define STLM75_REG_TEMP  0x00
#define STLM75_CMD_TEMP  0x40

typedef struct {
    float  data[BUFFER_SIZE];
    size_t head;
    size_t count;
} CircularBuffer;

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cb_init(CircularBuffer *cb)
{
    cb->head  = 0;
    cb->count = 0;
}

static void cb_add(CircularBuffer *cb, float value)
{
    cb->data[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE)
        cb->count++;
}

static float cb_average(const CircularBuffer *cb)
{
    if (cb->count == 0)
        return 0.0f;
    float sum = 0.0f;
    for (size_t i = 0; i < cb->count; i++)
        sum += cb->data[i];
    return sum / (float)cb->count;
}

static int read_temperature(float *out_temp)
{
    char cmd = STLM75_CMD_TEMP;
    char buf[2];

    if (i2cWriteDevice(g_i2c_handle, &cmd, 1) != 0) {
        fprintf(stderr, "Error: I2C write failed (cmd 0x%02X).\n", cmd);
        return -1;
    }

    /* STLM75 conversion takes ~36 ms; wait 50 ms to be safe */
    time_sleep(0.05);

    if (i2cReadDevice(g_i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error: I2C read failed.\n");
        return -1;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *out_temp = (float)raw / 100.0f;
    return 0;
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(GPIO_LED, 0);
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_LED, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", GPIO_LED);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(GPIO_LED, 0);

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (bus %d, addr 0x%02X).\n",
                I2C_BUS, I2C_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    CircularBuffer temp_buffer;
    cb_init(&temp_buffer);

    while (g_running) {
        float temperature;
        if (read_temperature(&temperature) != 0) {
            fprintf(stderr, "Warning: temperature read failed, skipping sample.\n");
            time_sleep(SAMPLE_PERIOD);
            continue;
        }

        cb_add(&temp_buffer, temperature);
        float avg = cb_average(&temp_buffer);

        if (avg > TEMP_THRESHOLD) {
            gpioWrite(GPIO_LED, 1);
        } else {
            gpioWrite(GPIO_LED, 0);
        }

        printf("Temperature: %.2f °C, Average: %.2f °C, LED: %s\n",
               temperature, avg, (avg > TEMP_THRESHOLD) ? "ON" : "OFF");

        time_sleep(SAMPLE_PERIOD);
    }

    cleanup();
    return EXIT_SUCCESS;
}

