#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SDP32_ADDR             0x48
#define SDP32_DEFAULT_INTERVAL 1000
#define SDP32_READ_LEN         9
#define SDP32_MEAS_DELAY_US    20000
#define SDP32_CRC_POLY         0x31
#define SDP32_CRC_INIT         0xFF

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = SDP32_CRC_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ SDP32_CRC_POLY);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int sdp32_read(int handle, float *pressure, float *temperature, float *scale_factor)
{
    uint8_t buf[SDP32_READ_LEN];

    if (i2cReadDevice(handle, (char *)buf, SDP32_READ_LEN) != SDP32_READ_LEN) {
        fprintf(stderr, "Error: I2C read failed (sensor absent or bus error).\n");
        return -1;
    }

    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Error: Pressure CRC mismatch.\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Error: Temperature CRC mismatch.\n");
        return -1;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "Error: Scale-factor CRC mismatch.\n");
        return -1;
    }

    int16_t raw_pressure    = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_temperature = (int16_t)((buf[3] << 8) | buf[4]);
    int16_t raw_scale       = (int16_t)((buf[6] << 8) | buf[7]);

    *pressure    = (float)raw_pressure    / 100.0f;
    *temperature = (float)raw_temperature / 100.0f;
    *scale_factor = (float)raw_scale;

    return 0;
}

static void print_timestamp(void)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char buf[32];
    localtime_r(&now, &tm_info);
    strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &tm_info);
    printf("[%s] ", buf);
}

int main(int argc, char *argv[])
{
    int interval = SDP32_DEFAULT_INTERVAL;

    if (argc > 1) {
        long val = strtol(argv[1], NULL, 10);
        if (val <= 0) {
            fprintf(stderr, "Error: Invalid interval '%s'. Using default %d ms.\n",
                    argv[1], SDP32_DEFAULT_INTERVAL);
            interval = SDP32_DEFAULT_INTERVAL;
        } else {
            interval = (int)val;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(1, SDP32_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device at 0x%02X (code %d).\n",
                SDP32_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("SDP32 differential pressure logger started. Interval: %d ms.\n", interval);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        float pressure, temperature, scale_factor;

        if (sdp32_read(g_i2c_handle, &pressure, &temperature, &scale_factor) == 0) {
            print_timestamp();
            printf("Pressure: %.2f Pa, Temperature: %.2f °C, Scale Factor: %.2f\n",
                   pressure, temperature, scale_factor);
        } else {
            fprintf(stderr, "Error: Sensor read failed; exiting.\n");
            break;
        }

        gpioDelay(SDP32_MEAS_DELAY_US);
    }

    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();

    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

