/*
 * SDP810-125Pa differential pressure sensor reader for Raspberry Pi 4.
 *
 * Wiring:
 *   SDP810 SDA  -> GPIO2 (BCM 2, physical pin 3)
 *   SDP810 SCL  -> GPIO3 (BCM 3, physical pin 5)
 *   SDP810 VDD  -> 3.3 V (physical pin 1)
 *   SDP810 GND  -> GND   (physical pin 9)
 *
 * I2C bus 1, address 0x6B (SDP810 default when ADDR pin tied to GND).
 *
 * Build:  gcc -O2 -Wall -Wextra -o sdp810_reader sdp810_reader.c -lpigpio -lrt
 * Run:    sudo ./sdp810_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SDP810_ADDR    0x6B
#define READ_INTERVAL  1.0          /* seconds between successful reads */
#define CONV_DELAY_US  45000        /* 45 ms – exceeds worst-case conversion time */

/* SDP810 9-byte measurement frame (MSB first):
 *   bytes 0-1 : pressure (differential) – 24-bit signed, 1/125 Pa LSB
 *   bytes 2-3 : temperature – 24-bit signed, 1/100 °C LSB
 *   bytes 4-5 : pressure scale factor
 *   bytes 6-7 : temperature scale factor
 *   byte 8   : CRC-8 (polynomial 0x31, init 0xFF) */
typedef struct {
    float pressure;          /* Pa */
    float temperature;       /* °C */
    int   valid;              /* 1 = good, 0 = CRC error, -1 = bus error */
} sdp810_data_t;

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 as used by Sensirion: poly 0x31, init 0xFF, no final XOR       */
static bool sdp810_crc8(const uint8_t *data, uint8_t len, uint8_t expected)
{
    uint8_t crc = 0xFF;
    for (uint8_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (uint8_t b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc == expected;
}

/* ------------------------------------------------------------------ */
/* Read one 9-byte frame and return a validated sdp810_data_t.        */
/* Returns 0 on success, -1 on bus error, -2 on CRC mismatch.          */
static int sdp810_read(int handle, sdp810_data_t *out)
{
    uint8_t buf[9];

    if (i2cReadDevice(handle, (char *)buf, sizeof(buf)) != (int)sizeof(buf)) {
        fprintf(stderr, "[ERROR] I2C read failed (bus error)\n");
        return -1;
