    /* Validate CRC on each 3-byte word */
    if (!sdp810_crc8(&buf[0], 2, buf[2])) {
        fprintf(stderr, "[ERROR] Pressure CRC mismatch\n");
        return -2;
    }
    if (!sdp810_crc8(&buf[3], 2, buf[5])) {
        fprintf(stderr, "[ERROR] Temperature CRC mismatch\n");
        return -2;
    }
    if (!sdp810_crc8(&buf[6], 2, buf[8])) {
        fprintf(stderr, "[ERROR] Scale-factor CRC mismatch\n");
        return -2;
    }

    /* Assemble 24-bit signed values (big-endian, two's complement) */
    int32_t raw_p = (int32_t)((uint32_t)buf[0] << 16 |
                              (uint32_t)buf[1] << 8  |
                               (uint32_t)buf[2]);
    int32_t raw_t = (int32_t)((uint32_t)buf[3] << 16 |
                              (uint32_t)buf[4] << 8  |
                               (uint32_t)buf[5]);

    /* SDP810-125Pa: 1 LSB = 1/125 Pa  (pressure) */
    /* SDP810-100C:   1 LSB = 1/100 °C  (temperature) */
    out->pressure    = (float)raw_p / 125.0f;
    out->temperature = (float)raw_t / 100.0f;
    out->valid       = 1;
    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- open I2C bus ------------------------------------------------ */
    g_i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed (handle %d) – sensor absent or bus error\n",
                g_i2c_handle);
