    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("SDP810-125Pa reader started (I2C bus %d, addr 0x%02X).\n",
           I2C_BUS, SDP810_ADDR);
    printf("Press Ctrl-C to exit.\n");

    /* --- main loop ---------------------------------------------------- */
    while (g_running) {
