#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define HDC1000_ADDR   0x15
#define REG_TEMP_LOW   0x00
#define REG_HUM_LOW    0x02
#define REG_CONFIG     0x03
#define REG_STATUS     0x04
#define REG_CTRL       0x0E
#define REG_DRDY       0x0F

#define CTRL_MEASURE   0x01
#define STATUS_DRDY    0x01
#define STATUS_ERROR   0x0C

#define CONV_DELAY_MS  20
#define LOOP_DELAY_MS  5000

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_write_byte(reg=0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_byte write(reg=0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "i2c_read_byte read(reg=0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_word(int fd, uint8_t reg, uint16_t *val)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_word write(reg=0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_read_word read(reg=0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    *val = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int hdc1000_init(int fd)
{
    if (i2c_write_byte(fd, REG_CONFIG, 0x00) < 0) return -1;
    if (i2c_write_byte(fd, REG_CTRL, 0x00) < 0) return -1;
    return 0;
}

static int hdc1000_read(int fd, float *temp, float *hum)
{
    uint8_t status;
    uint16_t t_raw, h_raw;

    /* Trigger a 14-bit temperature + humidity conversion */
    if (i2c_write_byte(fd, REG_CTRL, CTRL_MEASURE) < 0) return -1;
    usleep(CONV_DELAY_MS * 1000);

    /* Poll DRDY bit (bit 0 of STATUS) */
    for (int i = 0; i < 10; i++) {
        if (i2c_read_byte(fd, REG_STATUS, &status) < 0) return -1;
        if (status & STATUS_DRDY) break;
        usleep(10000);
    }
    if (!(status & STATUS_DRDY)) {
        fprintf(stderr, "HDC1000: conversion timeout\n");
        return -1;
    }

    if (i2c_read_word(fd, REG_TEMP_LOW, &t_raw) < 0) return -1;
    if (i2c_read_word(fd, REG_HUM_LOW, &h_raw) < 0) return -1;

    *temp = ((float)t_raw / 65536.0f) * 165.0f - 40.0f;
    *hum  = ((float)h_raw / 65536.0f) * 100.0f;
    return 0;
}

int main(void)
{
    int fd = -1;
    float temp, hum;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return 1;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, HDC1000_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n", HDC1000_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (hdc1000_init(fd) < 0) {
        fprintf(stderr, "HDC1000 init failed (sensor absent or bus error)\n");
        close(fd);
        return 1;
    }

    printf("HDC1000 initialized on %s (addr 0x%02X). Reading every %d ms...\n",
           I2C_BUS, HDC1000_ADDR, LOOP_DELAY_MS);

    while (g_running) {
        if (hdc1000_read(fd, &temp, &hum) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temp, hum);
        } else {
            fprintf(stderr, "Read failed; continuing...\n");
        }
        usleep(LOOP_DELAY_MS * 1000);
    }

    if (fd >= 0) close(fd);
    printf("\nExiting cleanly.\n");
    return 0;
}

