#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x49
#define TEMP_REG       0x00
#define CONV_REG       0x01
#define CONV_DELAY_US  10000   /* 10 ms conversion wait */
#define SAMPLE_PERIOD  5       /* seconds between samples */
#define MAX_RETRIES    3

static volatile sig_atomic_t g_terminate = 0;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_terminate = 1;
}

static int read_temperature(float *temperature)
{
    char buf[2];
    int  result;
    int  retries = 0;

    while (retries < MAX_RETRIES) {
        /* Read conversion register to trigger a new measurement */
        result = i2cWriteByteData(g_i2c_handle, CONV_REG, 0x00);
        if (result < 0) {
            fprintf(stderr, "I2C write failed (trigger): %s\n", pigpio_error(result));
            retries++;
            if (retries < MAX_RETRIES) {
                gpioDelay(100000); /* 100 ms backoff */
            }
            continue;
        }

        gpioDelay(CONV_DELAY_US);

        /* Read 2 bytes of temperature data */
        result = i2cReadI2CBlockData(g_i2c_handle, TEMP_REG, buf, 2);
        if (result < 0) {
            fprintf(stderr, "I2C read failed: %s\n", pigpio_error(result));
            retries++;
            if (retries < MAX_RETRIES) {
                gpioDelay(100000);
            }
            continue;
        }

        if (result != 2) {
            fprintf(stderr, "Short read: got %d bytes, expected 2\n", result);
            retries++;
            if (retries < MAX_RETRIES) {
                gpioDelay(100000);
            }
            continue;
        }

        int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
        *temperature = (float)raw / 100.0f;
        return 0;
    }

    fprintf(stderr, "Temperature read failed after %d retries.\n", MAX_RETRIES);
    return -1;
}

static void log_temperature(float temperature)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char time_str[32];

    if (localtime_r(&now, &tm_info) != NULL) {
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", &tm_info);
        printf("[%s] Temperature: %.2f °C\n", time_str, temperature);
    } else {
        printf("Temperature: %.2f °C\n", temperature);
    }
    fflush(stdout);
}

int main(void)
{
    float temperature;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

