#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x48
#define READ_INTERVAL  500000   /* microseconds (500 ms) */
#define MAX_RETRIES    3

/* MLX90833 register addresses (16-bit, big-endian on the bus) */
#define MLX90833_REG_PRS_B2  0x00
#define MLX90833_REG_PRS_B1  0x01
#define MLX90833_REG_PRS_B0  0x02
#define MLX90833_REG_PRS_XL  0x03
#define MLX90833_REG_PRS_L   0x04
#define MLX90833_REG_PRS_H   0x05
#define MLX90833_REG_PRS_XH  0x06
#define MLX90833_REG_PRS_CFG 0x07

/* Pressure configuration: 50 Hz ODR, 14-bit resolution, continuous mode */
#define MLX90833_PRS_CFG_VAL 0x0000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop can exit cleanly             */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit value to a 16-bit register address                  */
/* ------------------------------------------------------------------ */
static int write_reg16(int handle, uint16_t reg, uint16_t value)
{
    char buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (value >> 8) & 0xFF;
    buf[3] = value & 0xFF;

    if (i2cWriteDevice(handle, buf, 4) != 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice failed for reg 0x%04X\n", reg);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit value from a 16-bit register address                 */
/* ------------------------------------------------------------------ */
static int read_reg16(int handle, uint16_t reg, uint16_t *out)
{
    char reg_buf[2];
    char data_buf[2];

    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, reg_buf, 2) != 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice (reg select) failed for 0x%04X\n", reg);
        return -1;
    }

    if (i2cReadDevice(handle, data_buf, 2) != 2) {
        fprintf(stderr, "[ERROR] i2cReadDevice failed for reg 0x%04X\n", reg);
        return -1;
    }

    *out = ((uint16_t)(uint8_t)data_buf[0] << 8) | (uint8_t)data_buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the MLX90833 sensor                                     */
/* ------------------------------------------------------------------ */
static int initialize_sensor(int handle)
{
    if (write_reg16(handle, MLX90833_REG_PRS_CFG, MLX90833_PRS_CFG_VAL) != 0)
        return -1;

    /* Allow the sensor to settle after configuration */
    gpioDelay(100000); /* 100 ms */
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read absolute pressure from the MLX90833                            */
/* Returns 0 on success, -1 on error                                  */
/* ------------------------------------------------------------------ */
static int read_pressure(int handle, float *pressure)
{
    uint16_t b2, b1, b0, xl, l, h, xh;

    if (read_reg16(handle, MLX90833_REG_PRS_B2, &b2) != 0) return -1;
    if (read_reg16(handle, MLX90833_REG_PRS_B1, &b1) != 0) return -1;
    if (read_reg16(handle, MLX90833_REG_PRS_B0, &b0) != 0) return -1;
    if (read_reg16(handle, MLX90833_REG_PRS_XL, &xl) != 0) return -1;
    if (read_reg16(handle, MLX90833_REG_PRS_L, &l) != 0) return -1;
    if (read_reg16(handle, MLX90833_REG_PRS_H, &h) != 0) return -1;
    if (read_reg16(handle, MLX90833_REG_PRS_XH, &xh) != 0) return -1;

    /* Assemble 32-bit raw pressure value (14-bit left-justified) */
    uint32_t raw = ((uint32_t)b2 << 22) | ((uint32_t)b1 << 11) |
                   ((uint32_t)b0 << 0)  | ((uint32_t)xl << 14) |
                   ((uint32_t)l << 2)   | ((uint32_t)h >> 2);

    /* Arithmetic right-shift to get the 14-bit signed value */
    int32_t signed_raw = (int32_t)raw >> 18;

    /* Sign-extend if negative (14-bit two's complement) */
    if (signed_raw & 0x2000) {
        signed_raw |= 0xFFFFC000;
    }

    /* Convert to Pascals (assuming 14-bit resolution, 50 Hz ODR) */
    *pressure = (float)signed_raw * 0.5f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup resources                                                  */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed (bus %d, addr 0x%02X): %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (initialize_sensor(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] Sensor initialization failed — check wiring and address\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGTERM)");
    }

    printf("MLX90833 pressure sensor reader started (I2C bus %d, addr 0x%02X).\n",
           I2C_BUS, I2C_ADDR);
    printf("Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        float pressure;

        if (read_pressure(g_i2c_handle, &pressure) == 0) {
            time_t now = time(NULL);
            struct tm tm_info;
            char timestamp[32];

            if (localtime_r(&now, &tm_info) != NULL) {
                strftime(timestamp, sizeof(timestamp),
                         "%Y-%m-%d %H:%M:%S", &tm_info);
            } else {
                strncpy(timestamp, "UNKNOWN", sizeof(timestamp));
                timestamp[sizeof(timestamp) - 1] = '\0';
            }

            printf("[%s] Pressure: %.2f Pa\n", timestamp, pressure);
            fflush(stdout);
        } else {
            fprintf(stderr, "[ERROR] Failed to read pressure.\n");
        }

        /* Sleep 500 ms (interruptible by signals) */
        gpioDelay(READ_INTERVAL);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

