#define ICP10101_ADDR  0x29
#define MEASURE_CMD    0x36
#define MEASURE_DELAY_US 7000
#define LOOP_DELAY_US   5000000
#define READ_LEN        6

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int init_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, ICP10101_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %s\n",
                I2C_BUS, ICP10101_ADDR, strerror(errno));
        return -1;
    }
    return 0;
}

static int trigger_measurement(void)
{
    char cmd = MEASURE_CMD;
    if (i2cWriteDevice(g_i2c_handle, &cmd, 1) != 0) {
        fprintf(stderr, "Error triggering measurement: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_raw_data(uint8_t *buf, int len)
{
    int n = i2cReadDevice(g_i2c_handle, (char *)buf, len);
    if (n != len) {
        fprintf(stderr, "Error reading data: expected %d bytes, got %d: %s\n",
                len, n, strerror(errno));
        return -1;
    }
    return 0;
}

static void convert_data(const uint8_t *buf, float *temperature, float *pressure)
{
    uint16_t raw_pressure    = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t raw_temperature = ((uint16_t)buf[2] << 8) | buf[3];

    *pressure    = (float)raw_pressure    / 100.0f;
    *temperature = (float)raw_temperature / 200.0f;
}

static void log_data(float temperature, float pressure)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info);

    printf("%s - Temperature: %.2f C, Pressure: %.2f Pa\n",
           ts, temperature, pressure);
