#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MLX90819_ADDR  0x48
#define MLX90819_REG_PRS 0x00
#define SAMPLE_INTERVAL_S 1

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo) {
    (void)signo;
    g_running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_pressure(int fd, float *pressure) {
    uint8_t lo, hi;
    if (i2c_read_reg8(fd, MLX90819_REG_PRS, &lo) < 0) return -1;
    if (i2c_read_reg8(fd, MLX90819_REG_PRS + 1, &hi) < 0) return -1;
    uint16_t raw = ((uint16_t)hi << 8) | lo;
    *pressure = (float)raw / 100.0f;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MLX90819_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                MLX90819_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    printf("MLX90819 pressure sensor reader started on %s (addr 0x%02X).\n",
           I2C_BUS, MLX90819_ADDR);
    fflush(stdout);

    while (g_running) {
        float pressure;
        if (read_pressure(fd, &pressure) == 0) {
            time_t now = time(NULL);
            struct tm tmv;
            char ts[32];
            if (localtime_r(&now, &tmv) != NULL &&
                strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tmv) > 0) {
                printf("%s Pressure: %.2f Pa\n", ts, pressure);
                fflush(stdout);
            } else {
                printf("[timestamp error] Pressure: %.2f Pa\n", pressure);
                fflush(stdout);
            }
        } else {
            fprintf(stderr, "Failed to read pressure.\n");
        }
        sleep(SAMPLE_INTERVAL_S);
    }

    printf("\nExiting cleanly.\n");
    close(fd);
    return EXIT_SUCCESS;
}

