#define LOG_FILE       "pressure_log.csv"
#define SAMPLE_US      1000000
#define SAFE_MIN_KPA   200.0f
#define SAFE_MAX_KPA   250.0f
#define MAX_RETRIES    1

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

typedef struct {
    float pressure_kPa;
    int   valid;
} sensor_data_t;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int init_i2c(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_pressure(float *pressure_kPa)
{
    char buf[2];
    int  rc;

    rc = i2cReadI2CBlockData(g_i2c_handle, PRESSURE_REG, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "I2C read failed (rc=%d): %s\n", rc, strerror(errno));
        return -1;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | (uint8_t)buf[1]);
    *pressure_kPa = (float)raw / 100.0f;
    return 0;
}

static int log_data(float pressure_kPa)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    if (fprintf(g_log_file, "%s,%.2f\n", ts, pressure_kPa) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void check_safe(float pressure_kPa)
{
    if (pressure_kPa < SAFE_MIN_KPA || pressure_kPa > SAFE_MAX_KPA) {
        fprintf(stderr,
                "WARNING: Pressure %.2f kPa outside safe range [%.1f, %.1f] kPa\n",
                pressure_kPa, SAFE_MIN_KPA, SAFE_MAX_KPA);
    }
}

static void cleanup(void)
{
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    fseek(g_log_file, 0, SEEK_END);
    long file_size = ftell(g_log_file);
    if (file_size == 0) {
        if (fprintf(g_log_file, "timestamp,pressure_kPa\n") < 0) {
            fprintf(stderr, "Failed to write CSV header: %s\n", strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
        fflush(g_log_file);
    }

    sensor_data_t data;
    int consecutive_failures = 0;

    while (g_running) {
        if (read_pressure(&data.pressure_kPa) == 0) {
            consecutive_failures = 0;
            log_data(data.pressure_kPa);
            check_safe(data.pressure_kPa);
        } else {
            consecutive_failures++;
            fprintf(stderr, "Read failed (%d consecutive). Re-initialising I2C...\n",
                    consecutive_failures);
            if (init_i2c() != 0) {
                fprintf(stderr, "I2C re-init failed. Exiting.\n");
                break;
            }
            if (consecutive_failures >= MAX_RETRIES) {
                fprintf(stderr, "Max retries (%d) reached. Exiting.\n", MAX_RETRIES);
                break;
            }
            continue;
        }

        gpioDelay(SAMPLE_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

