/*
 * MLX90824 SENT pressure sensor reader for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   MLX90824 SW  -> GPIO4 (BCM 4, physical pin 7)
 *   MLX90824 VCC -> 3.3 V (physical pin 1)
 *   MLX90824 GND -> GND   (physical pin 6)
 *
 * The SENT protocol uses a 3 us tick time (3 us = 3000 us).  A valid
 * nibble pulse width must be between 12 and 271 ticks (36-813 us).
 * A synchronization pulse of 56 ticks (168 us) starts a SENT frame.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o sent_pressure sent_pressure.c -lpigpio -lrt
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN        4
#define LOG_FILE        "pressure_log.txt"
#define TICK_US         3000          /* 3 us tick time */
#define SYNC_TICKS      56            /* sync pulse: 168 us */
#define MIN_NIBBLE_TICKS 12           /* 36 us */
#define MAX_NIBBLE_TICKS 271          /* 813 us */
#define MAX_NIBBLES     4             /* status + 3 data + checksum */
#define READ_TIMEOUT_US 1000000       /* 1 s timeout waiting for frame */
#define LOOP_DELAY_US   100000        /* 100 ms between readings */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

/* Return 1 if pulse width is within the valid SENT range, 0 otherwise. */
static int is_valid_pulse_width(unsigned int width)
{
    return (width >= MIN_NIBBLE_TICKS && width <= MAX_NIBBLE_TICKS);
}

/* Read a SENT nibble from the current pulse width.  Returns 0-15, or -1 on error. */
static int read_nibble(unsigned int *width)
{
    if (!is_valid_pulse_width(width))
        return -1;

    /* SENT nibbles are encoded as the number of ticks in the pulse. */
    return (int)width;
}

/* Read a SENT frame from the current pulse width.  Returns 0 on success,
 * -1 on timeout, -2 on checksum error, -3 on out-of-range nibble. */
static int read_sent_frame(unsigned int *nibbles)
{
    unsigned int count = 0;
    unsigned int pulse_width = 0;

    /* Wait for the sync pulse (56 ticks). */
    while (count < SYNC_TICKS && g_running) {
        pulse_width = gpioTick() - gpioTick();
        count++;
        if (pulse_width > READ_TIMEOUT_US)
            return -1;
        gpioDelay(20);  /* 20 us granularity */
    }

    if (count < SYNC_TICKS) {
        fprintf(stderr, "SENT: sync pulse too short (%u ticks)\n", count);
        return -1;
    }

    /* Read the status nibble (nibble 0). */
    int status = read_nibble(&pulse_width);
    if (status < 0) {
        fprintf(stderr, "SENT: failed to read status nibble\n");
        return -1;
    }

    /* Read the three data nibbles (nibbles 1-3). */
    for (int i = 1; i <= 3; i++) {
        int n = read_nibble(&pulse_width);
        if (n < 0) {
            fprintf(stderr, "SENT: failed to read nibble %d\n", i);
            return -1;
        }
        nibbles[i - 1] = n;
    }

    /* Read the checksum nibble (nibble 4). */
    int checksum = read_nibble(&pulse_width);
    if (checksum < 0) {
        fprintf(stderr, "SENT: failed to read checksum nibble\n");
        return -1;
    }

    /* Validate checksum: nibble 0 + nibbles 1-3 should equal nibble 4. */
    if (status != (checksum & 0xF)) {
        fprintf(stderr, "SENT: checksum mismatch (status=0x%X, calc=0x%X)\n",
                status, checksum);
        return -2;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_pressure(float pressure)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return;
    }
    fprintf(fp, "%s, Pressure: %.2f Pa\n", timestamp, pressure);
    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers for clean shutdown. */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio. */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO4 as input with pull-up (SENT line is open-drain). */
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    printf("MLX90824 SENT pressure sensor reader started.\n");
    printf("GPIO%d, logging to %s. Press Ctrl+C to exit.\n",
           GPIO_PIN, LOG_FILE);

    unsigned int nibbles[MAX_NIBBLES];
    int consecutive_errors = 0;

    while (g_running) {
        int rc = read_sent_frame(nibbles);

        if (rc == 0) {
            /* Assemble pressure (Pa) from the four nibbles. */
            unsigned int pressure_raw = ((unsigned int)(nibbles[1] & 0x0F) << 12) |
                                        ((unsigned int)(nibbles[2] & 0x0F) << 8) |
                                        ((unsigned int)(nibbles[3] & 0x0F) << 4) |
                                        ((unsigned int)(nibbles[3] & 0x0F));

            float pressure = (float)pressure_raw / 100.0f;

            log_pressure(pressure);
            printf("Pressure: %.2f Pa\n", pressure);

            consecutive_errors = 0;
        } else if (rc == -1) {
            /* Timeout: sensor absent or not responding. */
            fprintf(stderr, "SENT: no frame received within %d us\n",
                    READ_TIMEOUT_US);
            consecutive_errors++;
        } else if (rc == -2) {
            /* Checksum error: bus noise or wiring fault. */
            fprintf(stderr, "SENT: checksum mismatch\n");
            consecutive_errors++;
        } else {
            /* rc == -3: out-of-range nibble. */
            fprintf(stderr, "SENT: out-of-range nibble (%u ticks)\n",
                    nibbles[1]);
            consecutive_errors++;
        }

        if (consecutive_errors > 10) {
            fprintf(stderr, "SENT: too many consecutive errors (%d), aborting.\n",
                    consecutive_errors);
            break;
        }

        gpioDelay(LOOP_DELAY_US);
    }

    /* Clean up. */
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

