    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio. */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO4 as input with pull-up (SENT line is open-drain). */
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    printf("MLX90824 SENT pressure sensor reader started.\n");
    printf("GPIO%d, logging to %s. Press Ctrl+C to exit.\n",
           GPIO_PIN, LOG_FILE);

    unsigned int nibbles[MAX_NIBBLES];
    int consecutive_errors = 0;

    while (g_running) {
        int rc = read_sent_frame(nibbles);

        if (rc == 0) {
            /* Assemble pressure (Pa) from the four nibbles. */
            unsigned int pressure_raw = ((unsigned int)(nibbles[1] & 0x0F) << 12) |
                                        ((unsigned int)(nibbles[2] & 0x0F) << 8) |
                                        ((unsigned int)(nibbles[3] & 0x0F) << 4) |
                                        ((unsigned int)(nibbles[3] & 0x0F));

            float pressure = (float)pressure_raw / 100.0f;

            log_pressure(pressure);
            printf("Pressure: %.2f Pa\n", pressure);

            consecutive_errors = 0;
        } else if (rc == -1) {
            /* Timeout: sensor absent or not responding. */
            fprintf(stderr, "SENT: no frame received within %d us\n",
                    READ_TIMEOUT_US);
            consecutive_errors++;
        } else if (rc == -2) {
            /* Checksum error: bus noise or wiring fault. */
            fprintf(stderr, "SENT: checksum mismatch\n");
            consecutive_errors++;
        } else {
            /* rc == -3: out-of-range nibble. */
            fprintf(stderr, "SENT: out-of-range nibble (%u ticks)\n",
                    nibbles[1]);
            consecutive_errors++;
        }

        if (consecutive_errors > 10) {
            fprintf(stderr, "SENT: too many consecutive errors (%d), aborting.\n",
                    consecutive_errors);
            break;
        }

        gpioDelay(LOOP_DELAY_US);
    }

    /* Clean up. */
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

