#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SHT40_ADDR             0x40
#define SHT40_CMD_MEASURE      0x2C
#define SHT40_MEASURE_DELAY_US 9000
#define SAMPLE_INTERVAL_US     5000000
#define LOG_FILE_NAME          "environmental_data.txt"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ---- CRC-8 (Sensirion polynomial 0x31, init 0xFF) ---- */
static uint8_t sht40_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int init_i2c(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    g_i2c_handle = i2cOpen(1, SHT40_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d).\n", g_i2c_handle);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int read_sht40(float *temperature, float *humidity)
{
    uint8_t cmd = SHT40_CMD_MEASURE;
    uint8_t data[6];

    if (i2cWriteDevice(g_i2c_handle, (char *)&cmd, 1) != 0) {
        fprintf(stderr, "Error: I2C write failed.\n");
        return -1;
    }

    gpioDelay(SHT40_MEASURE_DELAY_US);

    if (i2cReadDevice(g_i2c_handle, (char *)data, 6) != 6) {
        fprintf(stderr, "Error: I2C read failed.\n");
        return -1;
    }

    if (sht40_crc8(&data[0], 2) != data[2]) {
        fprintf(stderr, "Error: temperature CRC mismatch.\n");
        return -1;
    }
    if (sht40_crc8(&data[3], 2) != data[5]) {
        fprintf(stderr, "Error: humidity CRC mismatch.\n");
        return -1;
    }

    uint16_t t_raw = ((uint16_t)data[0] << 8) | data[1];
    uint16_t h_raw = ((uint16_t)data[3] << 8) | data[4];

    *temperature = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *humidity   = 100.0f * (float)h_raw / 65535.0f;

    return 0;
}

static int log_data(float temperature, float humidity)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(g_log_file, "%s, Temperature: %.2f C, Humidity: %.2f %%\n",
                timestamp, temperature, humidity) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed.\n");
        return -1;
    }
    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "Error: fflush of log file failed.\n");
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        perror("fopen(" LOG_FILE_NAME ")");
        cleanup();
        return EXIT_FAILURE;
    }

    while (g_running) {
        float temperature, humidity;

        if (read_sht40(&temperature, &humidity) == 0) {
            if (log_data(temperature, humidity) != 0) {
                fprintf(stderr, "Warning: logging failed, continuing.\n");
            }
        } else {
            fprintf(stderr, "Warning: sensor read failed, will retry.\n");
        }

        /* Sleep in 100 ms increments so SIGINT is caught promptly */
        for (int i = 0; i < 50 && g_running; i++) {
            gpioDelay(100000);
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

