#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TMP117_REG_TEMP 0x00
#define BUFFER_SIZE 100
#define LOG_FILE "temperature_log.dat"
#define SAMPLE_INTERVAL_SEC 5

typedef struct {
    float temperature;
    time_t timestamp;
} TemperatureData;

typedef struct {
    TemperatureData data[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static int i2c_handle = -1;
static CircularBuffer buffer;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at bus %d addr 0x%02X: %d\n",
                I2C_BUS, TMP117_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int read_temperature(float *temperature) {
    char reg = TMP117_REG_TEMP;
    char buf[2];

    if (i2cWriteDevice(i2c_handle, &reg, 1) != 0) {
        fprintf(stderr, "Error writing register address to I2C device\n");
        return -1;
    }

    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error reading temperature from I2C device\n");
        return -1;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *temperature = (float)raw * 0.0078125f;
    return 0;
}

static void add_to_buffer(CircularBuffer *buf, float temperature, time_t timestamp) {
    buf->data[buf->head].temperature = temperature;
    buf->data[buf->head].timestamp = timestamp;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count < BUFFER_SIZE) buf->count++;
}

static int write_buffer_to_file(const CircularBuffer *buf, const char *filename) {
    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        perror("Error opening file for writing");
        return -1;
    }

    size_t elements_written = fwrite(buf->data, sizeof(TemperatureData), buf->count, fp);
    if (elements_written != (size_t)buf->count) {
        fprintf(stderr, "Error writing to file: wrote %zu of %d elements\n",
                elements_written, buf->count);
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("Error closing file");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    buffer.head = 0;
    buffer.count = 0;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float temperature;
    time_t current_time;

    while (!terminate) {
        if (read_temperature(&temperature) == 0) {
            time(&current_time);
            add_to_buffer(&buffer, temperature, current_time);
        } else {
            fprintf(stderr, "Error reading temperature, skipping sample\n");
        }

        if (write_buffer_to_file(&buffer, LOG_FILE) != 0) {
            fprintf(stderr, "Error writing buffer to file\n");
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    if (write_buffer_to_file(&buffer, LOG_FILE) != 0) {
        fprintf(stderr, "Error writing buffer to file on exit\n");
    }

    cleanup();
    return 0;
}

