#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <stdint.h>
#include <pigpio.h>

#define DHT11_GPIO 4
#define DHT11_MAX_BITS 40
#define DHT11_MIN_INTERVAL 1000000  /* microseconds between reads */
#define DHT11_TIMEOUT_US 1000       /* per-phase timeout */
#define DHT11_START_LOW_US 20000    /* 20 ms low to start signal */
#define DHT11_START_HIGH_US 30      /* 30 us high to release line */
#define DHT11_RESP_LOW_US 80        /* 80 us low response */
#define DHT11_RESP_HIGH_US 80       /* 80 us high response */
#define DHT11_BIT_LOW_US 50         /* 50 us low for each bit */
#define DHT11_BIT_ONE_HIGH_US 70    /* ~70 us high for '1' */
#define DHT11_BIT_ZERO_HIGH_US 26   /* ~26 us high for '0' */
#define DHT11_TIMEOUT 0

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void log_message(const char *msg) {
    if (!g_log_file) return;
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(g_log_file, "%04d-%02d-%02dT%02d:%02d:%02d %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
        fflush(g_log_file);
    }
}

static void log_error(int status, const char *msg) {
    char buf[256];
    snprintf(buf, sizeof(buf), "Error: %s (status=%d)", msg, status);
    log_message(buf);
}

static void log_reading(float humidity, float temperature) {
    char buf[256];
    snprintf(buf, sizeof(buf), "Humidity: %.1f%%, Temperature: %.1fC", humidity, temperature);
    log_message(buf);
}

/*
 * Wait for the line to reach the requested level with a timeout.
 * Returns 0 on success, -1 on timeout.
 */
static int wait_level(int gpio, int level, uint32_t timeout_us) {
    uint32_t start = gpioTick();
    while (gpioRead(gpio) != level) {
        if ((gpioTick() - start) > timeout_us) return -1;
    }
    return 0;
}

/*
 * Read one bit from the DHT11.
 * Returns 0 on success, -1 on timeout, -2 on checksum error.
 */
static int read_bit(int gpio, uint32_t *out) {
    /* Low phase: wait for line to go low (response or data bit start) */
    if (wait_level(gpio, 0, DHT11_TIMEOUT_US) < 0) return -1;
    /* High phase: measure high duration to determine bit value */
    uint32_t start = gpioTick();
    if (wait_level(gpio, 1, DHT11_TIMEOUT_US) < 0) return -1;
    uint32_t high_us = gpioTick() - start;
    if (high_us < DHT11_BIT_LOW_US) return -1;
    /* If high pulse is too long, sensor is likely absent or stuck */
    if (high_us > DHT11_BIT_ONE_HIGH_US + 20) return -2;
    *out = (high_us > DHT11_BIT_ONE_HIGH_US) ? 1 : 0;
    return 0;
}

/*
 * Read the DHT11 sensor.
 * Returns 0 on success, -1 on timeout, -2 on checksum error.
 */
static int read_dht11(int gpio, float *humidity, float *temperature) {
    uint32_t bits[DHT11_MAX_BITS];
    int bit_idx = 0;

    /* --- Start signal --- */
    if (gpioSetMode(gpio, PI_OUTPUT) < 0) return -1;
    if (gpioWrite(gpio, 0) < 0) return -1;
    gpioDelay(DHT11_START_LOW_US);
    if (gpioWrite(gpio, 1) < 0) return -1;
    gpioDelay(DHT11_START_HIGH_US);

    /* --- Wait for sensor response --- */
    if (wait_level(gpio, 0, DHT11_TIMEOUT_US) < 0) return -1;
    if (wait_level(gpio, 1, DHT11_TIMEOUT_US) < 0) return -1;

    /* --- Read 40 data bits --- */
    for (int i = 0; i < DHT11_MAX_BITS; i++) {
        if (read_bit(gpio, &bits[i]) < 0) {
            if (i < DHT11_MAX_BITS - 1) {
                log_error(i, "bit read timeout");
                return -1;
            }
            return -1;
        }
        bit_idx++;
    }

    /* --- Decode --- */
    uint8_t humidity_raw = 0, temp_raw = 0;
    for (int i = 0; i < 8; i++) {
        humidity_raw = (humidity_raw << 1) | bits[i];
        temp_raw = (temp_raw << 1) | bits[i + 8];
    }

    /* --- Checksum --- */
    uint8_t checksum = (uint8_t)(humidity_raw + temp_raw);
    if (checksum != bits[7] || bits[6] != 0) {
        log_error(1, "checksum error");
        return -1;
    }

    *humidity = (float)humidity_raw / 10.0f;
    *temperature = (float)temp_raw / 10.0f;
    return 0;
}

int main(void) {
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    g_log_file = fopen("dht11_readings.txt", "a");
    if (!g_log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Register signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        log_error(2, "sigaction failed");
        fclose(g_log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Main loop --- */
    while (g_running) {
        float humidity = 0.0f, temperature = 0.0f;
        int rc = read_dht11(DHT11_GPIO, &humidity, &temperature);

        if (rc == 0) {
            log_reading(humidity, temperature);
        } else if (rc == -1) {
            log_error(3, "sensor read timeout");
        } else {
            log_error(4, "sensor read checksum error");
        }

        /* Sleep for the minimum interval, checking g_running every 100 ms */
        for (int i = 0; i < DHT11_MIN_INTERVAL / 100 && g_running; i++) {
            gpioDelay(100000);
        }
    }

    /* --- Cleanup --- */
    gpioTerminate();
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    return EXIT_SUCCESS;
}

