#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SHT31_ADDR             0x40
#define SHT31_MEASURE_TEMP_HOLD 0x2C
#define SHT31_MEASURE_HUM_HOLD  0x2E
#define SHT31_MEASURE_CMD      0x34
#define SHT31_CRC8_POLY        0x31
#define SHT31_CRC8_INIT        0xFF
#define SHT31_MEAS_DELAY_US    15000
#define LOG_INTERVAL_US        5000000
#define MAX_RETRIES            3

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static uint8_t sht31_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = SHT31_CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ SHT31_CRC8_POLY);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int sht31_read_measurement(int handle, uint8_t cmd, uint16_t *out)
{
    char buf[6];

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2cWriteByte(handle, cmd) < 0) {
            fprintf(stderr, "[attempt %d] I2C write failed (cmd 0x%02X)\n", attempt + 1, cmd);
            gpioDelay(10000);
            continue;
        }

        gpioDelay(SHT31_MEAS_DELAY_US);

        if (i2cReadDevice(handle, buf, 6) != 6) {
            fprintf(stderr, "[attempt %d] I2C read failed (cmd 0x%02X)\n", attempt + 1, cmd);
            gpioDelay(10000);
            continue;
        }

        if (sht31_crc8((uint8_t *)buf, 2) != (uint8_t)buf[2]) {
            fprintf(stderr, "[attempt %d] Temperature CRC mismatch (cmd 0x%02X)\n", attempt + 1, cmd);
            gpioDelay(10000);
            continue;
        }
        if (sht31_crc8((uint8_t *)buf + 3, 2) != (uint8_t)buf[5]) {
            fprintf(stderr, "[attempt %d] Humidity CRC mismatch (cmd 0x%02X)\n", attempt + 1, cmd);
            gpioDelay(10000);
            continue;
        }

        *out = ((uint16_t)(buf[0] << 8)) | (uint16_t)buf[1];
        return 0;
    }

    fprintf(stderr, "[attempt %d] Failed to read measurement after %d retries (cmd 0x%02X)\n",
            MAX_RETRIES + 1, MAX_RETRIES, cmd);
    return -1;
}

static int sht31_read_temperature_humidity(int handle, float *temperature, float *humidity)
{
    uint16_t raw_t, raw_h;

    if (sht31_read_measurement(handle, SHT31_MEASURE_TEMP_HOLD, &raw_t) != 0)
        return -1;

    if (sht31_read_measurement(handle, SHT31_MEASURE_HUM_HOLD, &raw_h) != 0)
        return -1;

    *temperature = -45.0f + 175.0f * (float)raw_t / 65535.0f;
    *humidity    = 100.0f * (float)raw_h / 65535.0f;

    return 0;
}

static void log_data(FILE *fp, float temperature, float humidity)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "[log] localtime_r failed\n");
        return;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.2f\n", ts, temperature, humidity);
    fflush(fp);
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(1, SHT31_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at addr 0x%02X: %d\n", SHT31_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen("sht31d_data.log", "a");
    if (!g_log_file) {
        perror("fopen(sht31d_data.log)");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fprintf(g_log_file, "# timestamp,temperature_c,humidity_pct\n");
    fflush(g_log_file);

    while (g_running) {
        float temperature, humidity;
        if (sht31_read_temperature_humidity(g_i2c_handle, &temperature, &humidity) == 0) {
            log_data(g_log_file, temperature, humidity);
        } else {
            time_t t = time(NULL);
            struct tm tm;
            if (localtime_r(&t, &tm) == NULL) {
                fprintf(stderr, "[main] localtime_r failed\n");
            } else {
                char ts[32];
                strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
                fprintf(g_log_file, "%s,ERROR,ERROR\n", ts);
                fflush(g_log_file);
                fprintf(stderr, "[%s] Sensor read failed; continuing\n", ts);
            }
        }
        gpioDelay(LOG_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

