/*
 * ADPD105 dual-sensor CCT logger for Raspberry Pi Zero W
 *
 * Wiring:
 *   ADPD105 #1 SDA -> GPIO2 (I2C1 SDA, pin 3)
 *   ADPD105 #1 SCL -> GPIO3 (I2C1 SCL, pin 5)
 *   ADPD105 #1 VDD -> 3.3 V
 *   ADPD105 #1 GND -> GND
 *   ADPD105 #2 SDA -> GPIO2 (I2C1 SDA, pin 3)
 *   ADPD105 #2 SCL -> GPIO3 (I2C1 SCL, pin 5)
 *   ADPD105 #2 VDD -> 3.3 V
 *   ADPD105 #2 GND -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o cct_logger cct_logger.c -lpigpio -lrt
 * Run:    sudo ./cct_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

/* ---- ADPD105 register map (simplified subset) ---- */
#define ADPD105_REG_PART_ID       0x00
#define ADPD105_REG_HW_ID         0x01
#define ADPD105_REG_SEQ_ID        0x02
#define ADPD105_REG_INT_CFG       0x03
#define ADPD105_REG_INT_STATUS    0x04
#define ADPD105_REG_PARAM_WR      0x0F
#define ADPD105_REG_COMMAND       0x10
#define ADPD105_REG_RESPONSE     0x11
#define ADPD105_REG_DATA0         0x12
#define ADPD105_REG_DATA1         0x13
#define ADPD105_REG_DATA2         0x14
#define ADPD105_REG_DATA3         0x15

#define ADPD105_PART_ID_VAL       0x05
#define ADPD105_HW_ID_VAL         0x01
#define ADPD105_CMD_RESET         0x01
#define ADPD105_CMD_PARAM_QUERY   0x80
#define ADPD105_CMD_PARAM_SET     0xA0
#define ADPD105_CMD_ALS_FORCE     0x0F

#define I2C_BUS 1
#define SAMPLE_INTERVAL_S 1
#define LOG_FILE "cct_log.csv"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle1 = -1;
static int g_i2c_handle2 = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_byte(int handle, uint8_t reg, uint8_t value)
{
    char buf[2] = { (char)reg, (char)value };
    if (i2cWriteDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "[I2C] write reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint8_t len)
{
    if (i2cWriteDevice(handle, (char *)&reg, 1) != 1) {
        fprintf(stderr, "[I2C] write reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (i2cReadDevice(handle, (char *)buf, len) != len) {
        fprintf(stderr, "[I2C] read reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* ADPD105 sensor driver                                              */
/* ------------------------------------------------------------------ */
static int adpd105_init(int handle)
{
    uint8_t part_id = 0, hw_id = 0;

    if (i2c_read_block(handle, ADPD105_REG_PART_ID, &part_id, 1) != 0)
        return -1;
    if (part_id != ADPD105_PART_ID_VAL) {
        fprintf(stderr, "[ADPD105] unexpected PART_ID 0x%02X (expected 0x%02X)\n",
                part_id, ADPD105_PART_ID_VAL);
        return -1;
    }

    if (i2c_read_block(handle, ADPD105_REG_HW_ID, &hw_id, 1) != 0)
        return -1;
    if (hw_id != ADPD105_HW_ID_VAL) {
        fprintf(stderr, "[ADPD105] unexpected HW_ID 0x%02X (expected 0x%02X)\n",
                hw_id, ADPD105_HW_ID_VAL);
        return -1;
    }

    /* Reset */
    if (i2c_write_byte(handle, ADPD105_REG_COMMAND, ADPD105_CMD_RESET) != 0)
        return -1;
    gpioDelay(10000); /* 10 ms settle */

    /* Clear any pending interrupt */
    if (i2c_write_byte(handle, ADPD105_REG_INT_CFG, 0x00) != 0)
        return -1;

    return 0;
}

static int adpd105_read_data(int handle, uint16_t *r0, uint16_t *r1,
                             uint16_t *r2, uint16_t *r3)
{
    uint8_t data[8];

    if (i2c_read_block(handle, ADPD105_REG_DATA0, data, 8) != 0)
        return -1;

    *r0 = (uint16_t)((data[1] << 8) | data[0]);
    *r1 = (uint16_t)((data[3] << 8) | data[2]);
    *r2 = (uint16_t)((data[5] << 8) | data[4]);
    *r3 = (uint16_t)((data[7] << 8) | data[6]);

    return 0;
}

static int adpd105_set_param(int handle, uint8_t param, uint8_t value)
{
    if (i2c_write_byte(handle, ADPD105_REG_PARAM_WR, value) != 0)
        return -1;
    if (i2c_write_byte(handle, ADPD105_REG_COMMAND, ADPD105_CMD_PARAM_SET | param) != 0)
        return -1;
    gpioDelay(10000); /* 10 ms */
    return 0;
}

/* ------------------------------------------------------------------ */
/* CCT calculation                                                    */
/* ------------------------------------------------------------------ */
static float calculate_cct(uint16_t r0, uint16_t r1, uint16_t r2, uint16_t r3)
{
    /* Simplified correlated colour temperature approximation
     * using the ADPD105's photometric response. */
    float r = (float)(r0 + r1 + r2 + r3) / 4.0f;
    float b = (float)(r0 + r2) / 2.0f;
    float g = (float)(r1 + r3) / 2.0f;

    float x = (r - 0.332f) / 0.418f;
    float y = (b - 0.272f) / 0.516f;
    float z = (g - 0.299f) / 0.604f;

    float cct = 449.0f * x + 352.6f * y + 193.0f * z;
    return cct;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_cct(float cct)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "[LOG] cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        fprintf(stderr, "[LOG] localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f\n", ts, cct);
    fclose(fp);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle1 >= 0) {
        i2cClose(g_i2c_handle1);
        g_i2c_handle1 = -1;
    }
    if (g_i2c_handle2 >= 0) {
        i2cClose(g_i2c_handle2);
        g_i2c_handle2 = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle1 = i2cOpen(I2C_BUS, 0x80, 0);
    if (g_i2c_handle1 < 0) {
        fprintf(stderr, "i2cOpen sensor 1 failed (handle %d)\n", g_i2c_handle1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_i2c_handle2 = i2cOpen(I2C_BUS, 0x81, 0);
    if (g_i2c_handle2 < 0) {
        fprintf(stderr, "i2cOpen sensor 2 failed (handle %d)\n", g_i2c_handle2);
        i2cClose(g_i2c_handle1);
        g_i2c_handle1 = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (adpd105_init(g_i2c_handle1) != 0) {
        fprintf(stderr, "Sensor 1 init failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (adpd105_init(g_i2c_handle2) != 0) {
        fprintf(stderr, "Sensor 2 init failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("CCT logger started. Logging to %s every %d s. Press Ctrl+C to exit.\n",
           LOG_FILE, SAMPLE_INTERVAL_S);

    while (g_running) {
        uint16_t r0 = 0, r1 = 0, r2 = 0, r3 = 0;

        if (adpd105_read_data(g_i2c_handle1, &r0, &r1, &r2, &r3) != 0) {
            fprintf(stderr, "Sensor 1 read error — skipping cycle\n");
        } else if (adpd105_read_data(g_i2c_handle2, &r0, &r1, &r2, &r3) != 0) {
            fprintf(stderr, "Sensor 2 read error — skipping cycle\n");
        } else {
            float cct1 = calculate_cct(r0, r1, r2, r3);
            float cct2 = calculate_cct(r0, r1, r2, r3);

            float avg_cct = (cct1 + cct2) / 2.0f;

            if (log_cct(avg_cct) != 0)
                fprintf(stderr, "Logging failed — continuing\n");

            printf("CCT1: %.2f K | CCT2: %.2f K | Avg CCT: %.2f K\n",
                   cct1, cct2, avg_cct);
        }

        sleep(SAMPLE_INTERVAL_S);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

