#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/*
 * MLX90824 absolute pressure sensor driver (pigpio / I2C).
 *
 * Wiring (Raspberry Pi 4 Model B):
 *   MLX90824 SDA  -> GPIO 2  (I2C bus 1)
 *   MLX90824 SCL  -> GPIO 3  (I2C bus 1)
 *   MLX90824 VDD  -> 3.3 V
 *   MLX90824 GND  -> GND
 *
 * The MLX90824 is an absolute pressure sensor with a 16-bit register
 * interface.  A full read returns 3 bytes: pressure (2 bytes, big-endian),
 * temperature (2 bytes, big-endian), and scale factor (2 bytes, big-endian).
 */

#define I2C_BUS        1
#define I2C_ADDR       0x48
#define LOG_FILE       "pressure_log.txt"
#define READ_INTERVAL  2          /* seconds between read cycles */
#define MAX_RETRIES    3

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                   */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    struct tm tmv;
    if (localtime_r(&now, &tmv) != NULL)
        strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tmv);
    else
        snprintf(buf, len, "1970-01-01T00:00:00");
}

/* ------------------------------------------------------------------ */
/* Sensor read                                                         */
/* ------------------------------------------------------------------ */
/*
 * Returns 0 on success, -1 on I2C error, -2 on sensor-absent (no ACK).
 */
static int read_sensor(int handle, float *pressure, float *temperature)
{
    char buf[6];
    int  rc;

    /*
     * The MLX90824 returns 6 bytes per read:
     *   bytes 0-1 : pressure (big-endian)
     *   bytes 2-3 : temperature (big-endian)
     *   bytes 4-5 : scale factor (big-endian)
     */
    rc = i2cReadDevice(handle, buf, 6);
    if (rc != 6) {
        fprintf(stderr, "[ERROR] i2cReadDevice returned %d (expected 6)\n", rc);
        return -1;
    }

    uint16_t p_raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    uint16_t t_raw = ((uint16_t)(uint8_t)buf[2] << 8) | (uint8_t)buf[3];
    uint16_t s_raw = ((uint16_t)(uint8_t)buf[4] << 8) | (uint8_t)buf[5];

    /*
     * Per the MLX90824 datasheet:
     *   pressure (Pa) = p_raw * 0.01
     *   temperature (°C) = t_raw * 0.01
     *   scale factor = s_raw * 0.01
     */
    *pressure    = (float)p_raw * 0.01f;
    *temperature = (float)t_raw * 0.01f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, float pressure, float temperature)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));
    fprintf(fp, "%s,%.2f,%.2f\n", ts, pressure, temperature);
    fflush(fp);
}

static void log_error(FILE *fp, const char *msg)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));
    fprintf(fp, "%s,ERROR,%s\n", ts, msg);
    fflush(fp);
    fprintf(stderr, "[%s] %s\n", ts, msg);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    float pressure, temperature;
    int  rc;

    /* --- pigpio init ------------------------------------------------- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- open I2C --------------------------------------------------- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed (handle=%d). "
                        "Sensor may be absent at 0x%02X on bus %d.\n",
                        g_i2c_handle, I2C_ADDR, I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- open log file ---------------------------------------------- */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("[FATAL] fopen(" LOG_FILE ")");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- signal handlers -------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* --- main loop -------------------------------------------------- */
    while (g_running) {
        rc = read_sensor(g_i2c_handle, &pressure, &temperature);
        if (rc == 0) {
            log_data(g_log_file, pressure, temperature);
        } else if (rc == -1) {
            log_error(g_log_file, "I2C read failure");
        } else {
            log_error(g_log_file, "Sensor absent (no ACK)");
        }

        /* sleep READ_INTERVAL seconds, checking g_running each second */
        for (int i = 0; i < READ_INTERVAL && g_running; i++)
            sleep(1);
    }

    /* --- graceful shutdown ------------------------------------------ */
    cleanup();
    return EXIT_SUCCESS;
}

