    while (g_running) {
        rc = read_sensor(g_i2c_handle, &pressure, &temperature);
        if (rc == 0) {
            log_data(g_log_file, pressure, temperature);
        } else if (rc == -1) {
            log_error(g_log_file, "I2C read failure");
        } else {
            log_error(g_log_file, "Sensor absent (no ACK)");
        }

        /* sleep READ_INTERVAL seconds, checking g_running each second */
        for (int i = 0; i < READ_INTERVAL && g_running; i++)
            sleep(1);
    }

    /* --- graceful shutdown ------------------------------------------ */
    cleanup();
    return EXIT_SUCCESS;
}

