/*
 * LM75B temperature monitor with hysteresis fan control on Raspberry Pi 4.
 *
 * Hardware:
 *   - LM75B temperature sensor on I2C bus 1 (GPIO2=SDA, GPIO3=SCL), address 0x48.
 *   - Cooling fan on GPIO18 (BCM) via a logic-level MOSFET or relay module.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o lm75b_fan lm75b_fan.c -li2c
 *
 * Run:
 *   sudo ./lm75b_fan   (root needed for /dev/i2c-1 and /sys/gpio access)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS          1
#define LM75B_ADDR       0x48
#define FAN_GPIO         18
#define BUFFER_SIZE      60
#define TEMP_THRESHOLD_ON 28.0f
#define TEMP_THRESHOLD_OFF 26.0f
#define POLL_INTERVAL_S  1

/* LM75B register addresses (command byte 0x10 + reg) */
#define LM75B_REG_TEMP   0x00
#define LM75B_REG_CONFIG 0x01

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd   = -1;
static int      g_pigpio_inited = 0;

/* Circular buffer */
typedef struct {
    float  data[BUFFER_SIZE];
    size_t head;
    size_t count;
} CircularBuffer;

static CircularBuffer g_temp_buffer;

/* ----------------------------- Prototypes -------------------------------- */
static void signal_handler(int sig);
static int  init_i2c(void);
static int  init_gpio(void);
static int  read_temperature(float *out);
static void add_temperature(float temp);
static float calculate_average(void);
static void control_fan(float avg_temp);
static void cleanup(void);

/* ----------------------------- Implementation ----------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int init_i2c(void)
{
    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(/dev/i2c-1): %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, LM75B_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                LM75B_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return -1;
    }

    /* Probe: read the config register to confirm the sensor is present. */
    uint8_t cfg = 0;
    if (read(g_i2c_fd, &cfg, 1) != 1) {
        fprintf(stderr, "LM75B not responding at 0x%02X: %s\n",
                LM75B_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return -1;
    }

    return 0;
}

static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise() failed\n");
        return -1;
    }
    g_pigpio_inited = 1;

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT) failed\n", FAN_GPIO);
        return -1;
    }

    /* Start with fan off. */
    if (gpioWrite(FAN_GPIO, 0) < 0) {
        fprintf(stderr, "gpioWrite(%d, 0) failed\n", FAN_GPIO);
        return -1;
    }
    return 0;
}

/*
 * Read temperature from LM75B.
 * Returns 0 on success and stores Celsius in *out; -1 on error.
 */
static int read_temperature(float *out)
{
    uint8_t cmd = LM75B_REG_TEMP | 0x10;   /* read temp, no register */
    uint8_t buf[2];

    if (write(g_i2c_fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write (temp cmd) failed: %s\n", strerror(errno));
        return -1;
    }

    /* LM75B needs a brief conversion delay after issuing the read command. */
    usleep(2000);

    ssize_t n = read(g_i2c_fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "I2C read (temp) failed: got %zd bytes, %s\n",
                n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *out = (float)raw / 16.0f;
    return 0;
}

static void add_temperature(float temp)
{
    g_temp_buffer.data[g_temp_buffer.head] = temp;
    g_temp_buffer.head = (g_temp_buffer.head + 1) % BUFFER_SIZE;
    if (g_temp_buffer.count < BUFFER_SIZE)
        g_temp_buffer.count++;
}

static float calculate_average(void)
{
    if (g_temp_buffer.count == 0)
        return 0.0f;

    float sum = 0.0f;
    for (size_t i = 0; i < g_temp_buffer.count; i++)
        sum += g_temp_buffer.data[i];

    return sum / (float)g_temp_buffer.count;
}

static void control_fan(float avg_temp)
{
    static bool fan_on = false;

    if (avg_temp > TEMP_THRESHOLD_ON && !fan_on) {
        if (gpioWrite(FAN_GPIO, 1) == 0) {
            fan_on = true;
            printf("Fan ON  (avg %.2f C > %.1f C)\n", avg_temp, TEMP_THRESHOLD_ON);
        } else {
            fprintf(stderr, "gpioWrite(%d, 1) failed\n", FAN_GPIO);
        }
    } else if (avg_temp < TEMP_THRESHOLD_OFF && fan_on) {
        if (gpioWrite(FAN_GPIO, 0) == 0) {
            fan_on = false;
            printf("Fan OFF (avg %.2f C < %.1f C)\n", avg_temp, TEMP_THRESHOLD_OFF);
        } else {
            fprintf(stderr, "gpioWrite(%d, 0) failed\n", FAN_GPIO);
        }
    }
}

static void cleanup(void)
{
    if (g_pigpio_inited) {
        gpioWrite(FAN_GPIO, 0);
        gpioTerminate();
        g_pigpio_inited = 0;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (init_i2c() < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("LM75B temperature monitor started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float temp;
        if (read_temperature(&temp) == 0) {
            add_temperature(temp);
            float avg = calculate_average();
            printf("Temperature: %.2f C  |  Average: %.2f C\n", temp, avg);
            control_fan(avg);
        } else {
            fprintf(stderr, "Temperature read failed; will retry next cycle.\n");
        }

        sleep(POLL_INTERVAL_S);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

