#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x48
#define LOG_FILE       "airflow.log"
#define PRESSURE_THRESHOLD 5.0f
#define SAMPLE_PERIOD_US 1000000
#define MEASURE_DELAY_US 45000

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* Sensirion CRC-8: polynomial 0x31, init 0xFF */
static uint8_t sensirion_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

static int init_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        return -1;
    }
    return 0;
}

static int read_sensor(float *pressure, float *temperature)
{
    uint8_t cmd[2] = {0x36, 0x08}; /* continuous measurement, mass flow */
    uint8_t buf[9];

    if (i2cWriteDevice(g_i2c_handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error writing measurement command to I2C\n");
        return -1;
    }

    gpioDelay(MEASURE_DELAY_US);

    int rd = i2cReadDevice(g_i2c_handle, (char *)buf, 9);
    if (rd != 9) {
        fprintf(stderr, "Error reading 9 bytes from I2C (got %d)\n", rd);
        return -1;
    }

    /* Validate CRC for each 2-byte data word */
    for (int i = 0; i < 9; i += 3) {
        if (sensirion_crc8(&buf[i], 2) != buf[i + 2]) {
            fprintf(stderr, "CRC mismatch on word %d\n", i / 3);
            return -1;
        }
    }

    int16_t raw_pressure    = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_temperature = (int16_t)((buf[3] << 8) | buf[4]);

    *pressure    = (float)raw_pressure    / 100.0f;
    *temperature = (float)raw_temperature / 200.0f;

    return 0;
}

static void log_data(float pressure, float temperature)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    fprintf(g_log_file, "%s,%.2f,%.2f\n", ts, pressure, temperature);
    fflush(g_log_file);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("Error opening log file");
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(g_log_file, "# timestamp,differential_pressure_Pa,temperature_C\n");
    fflush(g_log_file);

    while (g_running) {
        float pressure, temperature;

        if (read_sensor(&pressure, &temperature) == 0) {
            log_data(pressure, temperature);

            if (pressure > PRESSURE_THRESHOLD) {
                fprintf(stderr, "WARNING: Pressure %.2f Pa exceeds threshold %.2f Pa\n",
                        pressure, PRESSURE_THRESHOLD);
            }
        } else {
            fprintf(stderr, "Sensor read failed; continuing\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

