#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS        "/dev/i2c-1"
#define STTS2004_ADDR  0x48
#define GPIO_LED       17
#define TEMP_THRESHOLD_HIGH  28.0f
#define TEMP_THRESHOLD_LOW   27.0f
#define POLL_INTERVAL_US  1000000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read temperature from STTS2004.
 * Returns 0 on success and stores Celsius in *temp_c;
 * returns -1 on error.
 */
static int read_temperature(int fd, float *temp_c)
{
    uint8_t buf[2];
    ssize_t n;

    /* Trigger a single-shot conversion by writing 0x00 to the control register */
    if (write(fd, (uint8_t[]){0x00}, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }

    /* Small delay so the conversion completes */
    usleep(10000);

    /* Read 2 bytes from the temperature register (0x00) */
    n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "I2C read failed: expected 2 bytes, got %zd (%s)\n",
                n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *temp_c = (float)raw / 100.0f;
    return 0;
}

int main(void)
{
    int i2c_fd = -1;
    int pigpio_initialized = 0;
    int led_state = 0;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }
    pigpio_initialized = 1;

    /* Configure LED pin as output */
    if (gpioSetMode(GPIO_LED, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", GPIO_LED);
        goto cleanup;
    }

    /* Open I2C bus */
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        goto cleanup;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, STTS2004_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                STTS2004_ADDR, strerror(errno));
        goto cleanup;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float temperature;

        if (read_temperature(i2c_fd, &temperature) == 0) {
            printf("Temperature: %.2f °C\n", temperature);

            if (temperature > TEMP_THRESHOLD_HIGH && !led_state) {
                if (gpioWrite(GPIO_LED, 1) == 0) {
                    led_state = 1;
                    printf("Temperature above threshold, LED ON\n");
                } else {
                    fprintf(stderr, "Failed to set GPIO%d high\n", GPIO_LED);
                }
            } else if (temperature < TEMP_THRESHOLD_LOW && led_state) {
                if (gpioWrite(GPIO_LED, 0) == 0) {
                    led_state = 0;
                    printf("Temperature below threshold, LED OFF\n");
                } else {
                    fprintf(stderr, "Failed to set GPIO%d low\n", GPIO_LED);
                }
            }
        } else {
            fprintf(stderr, "Failed to read temperature. Exiting.\n");
            break;
        }

        usleep(POLL_INTERVAL_US);
    }

cleanup:
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (pigpio_initialized) {
        gpioWrite(GPIO_LED, 0);
        gpioTerminate();
    }

    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

