#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x40
#define LOG_FILE       "environment.log"
#define SAMPLE_PERIOD  60
#define MEASURE_DELAY  20000   /* microseconds (20 ms) */
#define MAX_RETRIES    3

/* Si7021 commands (MSB first) */
#define CMD_MEASURE_RH_NOHOLD  0xE0
#define CMD_MEASURE_TEMP_NOHOLD 0xE1
#define CMD_READ_TEMP_PREV     0xE0
#define CMD_READ_ID_1          0xFA
#define CMD_READ_ID_2          0x0F
#define CMD_RESET              0xFE

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int handle, uint8_t cmd)
{
    char buf[1] = { (char)cmd };
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cWriteDevice(handle, buf, 1);
        if (rc == 1)
            return 0;
        fprintf(stderr, "[WARN] i2cWriteDevice(0x%02X) attempt %d failed: %s\n",
                cmd, attempt + 1, strerror(errno));
        gpioDelay(10000); /* 10 ms back-off */
    }
    return -1;
}

static int i2c_read_bytes(int handle, uint8_t *buf, int len)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cReadDevice(handle, (char *)buf, len);
        if (rc == len)
            return 0;
        fprintf(stderr, "[WARN] i2cReadDevice(0x%02X) attempt %d failed: %s\n",
                (len == 1) ? CMD_READ_ID_1 : CMD_READ_ID_2,
                attempt + 1, strerror(errno));
        gpioDelay(10000);
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Sensor operations                                                   */
/* ------------------------------------------------------------------ */
static int read_sensor_id(int handle, uint8_t *id)
{
    if (i2c_write_cmd(handle, CMD_READ_ID_1) != 0)
        return -1;
    gpioDelay(10000);
    if (i2c_read_bytes(handle, id, 1) != 0)
        return -1;
    *id = (uint8_t)id[0];
    return 0;
}

static int read_sensor_rev(int handle, uint8_t *rev)
{
    if (i2c_write_cmd(handle, CMD_READ_ID_2) != 0)
        return -1;
    gpioDelay(10000);
    if (i2c_read_bytes(handle, rev, 1) != 0)
        return -1;
    *rev = (uint8_t)rev[0];
    return 0;
}

static int read_raw_temp(int handle, int32_t *raw)
{
    if (i2c_write_cmd(handle, CMD_MEASURE_TEMP_NOHOLD) != 0)
        return -1;
    gpioDelay(MEASURE_DELAY);
    uint8_t buf[2];
    if (i2c_read_bytes(handle, buf, 2) != 0)
        return -1;
    *raw = ((int32_t)buf[0] << 8) | buf[1];
    return 0;
}

static int read_raw_hum(int handle, int32_t *raw)
{
    if (i2c_write_cmd(handle, CMD_MEASURE_RH_NOHOLD) != 0)
        return -1;
    gpioDelay(MEASURE_DELAY);
    uint8_t buf[2];
    if (i2c_read_bytes(handle, buf, 2) != 0)
        return -1;
    *raw = ((int32_t)buf[0] << 8) | buf[1];
    return 0;
}

static int read_prev_temp(int handle, int32_t *raw)
{
    if (i2c_write_cmd(handle, CMD_READ_TEMP_PREV) != 0)
        return -1;
    gpioDelay(10000);
    uint8_t buf[2];
    if (i2c_read_bytes(handle, buf, 2) != 0)
        return -1;
    *raw = ((int32_t)buf[0] << 8) | buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_line(const char *line)
{
    if (g_log_file) {
        fprintf(g_log_file, "%s\n", line);
        fflush(g_log_file);
    }
    printf("%s\n", line);
}

static void log_error(const char *msg)
{
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(stderr, "[%s] ERROR: %s\n", ts, msg);
    if (g_log_file) {
        fprintf(g_log_file, "%s ERROR: %s\n", ts, msg);
        fflush(g_log_file);
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
