    uint8_t sensor_id = 0;
    uint8_t rev = 0;
    int32_t raw_t = 0, raw_h = 0;

    if (read_sensor_id(g_i2c_handle, &sensor_id) != 0) {
        log_error("Sensor ID read failed — sensor absent or bus error");
        cleanup();
