    }
    printf("Si7021 detected (ID=0x%02X, rev=0x%02X)\n", sensor_id, rev);

    if (read_sensor_rev(g_i2c_handle, &rev) != 0) {
        log_error("Sensor revision read failed");
        cleanup();
        return EXIT_FAILURE;
    }
    printf("Si7021 revision: 0x%02X\n", rev);

    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("fopen(" LOG_FILE ")");
        cleanup();
        return EXIT_FAILURE;
    }

    log_line("timestamp,temperature_c,humidity_pct");

    while (g_running) {
        int32_t prev_temp = 0;
        int ok = 0;

        if (read_raw_temp(g_i2c_handle, &raw_t) == 0) {
            ok = 1;
