#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define STS40_ADDR     0x48
#define LOG_FILE       "temperature_log.txt"
#define SAMPLE_PERIOD  5
#define CONV_DELAY_MS  10

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* Sensirion CRC8: polynomial 0x31, init 0xFF, no reflect, no final XOR */
static uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int i2c_open(const char *bus, uint8_t addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("open I2C bus");
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        return -1;
    }
    return fd;
}

static int read_sts40(int fd, float *temp) {
    uint8_t buf[3];
    ssize_t n = read(fd, buf, sizeof(buf));
    if (n != 3) {
        if (n < 0)
            perror("read STS40");
        else
            fprintf(stderr, "STS40: short read (%zd bytes)\n", n);
        return -1;
    }
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "STS40: CRC mismatch\n");
        return -1;
    }
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *temp = -45.0f + 175.0f * (float)raw / 65535.0f;
    return 0;
}

static void log_temperature(FILE *fp, float temp) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        return;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s, %.2f\n", ts, temp);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = i2c_open(I2C_BUS, STS40_ADDR);
    if (fd < 0)
        return EXIT_FAILURE;

    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        close(fd);
        return EXIT_FAILURE;
    }

    while (g_running) {
        float temp;
        if (read_sts40(fd, &temp) == 0) {
            log_temperature(fp, temp);
        } else {
            fprintf(stderr, "Skipping log entry due to read error.\n");
        }
        /* Sleep SAMPLE_PERIOD seconds, but wake early on signal */
        for (int s = 0; s < SAMPLE_PERIOD && g_running; s++)
            sleep(1);
    }

    fclose(fp);
    close(fd);
    return EXIT_SUCCESS;
}

