#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SDP810_ADDR 0x29
#define MEASURE_CMD 0x361C
#define MEASURE_DELAY_US 50000
#define LOG_FILE "hvac_pressure_log.txt"
#define SAMPLE_INTERVAL_US 1000000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int init_sdp810(void) {
    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device (pigpio error %d)\n", i2c_handle);
        return -1;
    }

    if (i2cWriteWordData(i2c_handle, 0x00, MEASURE_CMD) < 0) {
        fprintf(stderr, "Error writing measurement command\n");
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    return 0;
}

static int read_sdp810(float *pressure, float *temperature) {
    uint8_t buffer[9];
    int result = i2cReadDevice(i2c_handle, (char *)buffer, 9);
    if (result != 9) {
        fprintf(stderr, "Error reading from I2C device (got %d bytes, expected 9)\n", result);
        return -1;
    }

    if (crc8(&buffer[0], 2) != buffer[2]) {
        fprintf(stderr, "CRC error in pressure data\n");
        return -1;
    }
    if (crc8(&buffer[3], 2) != buffer[5]) {
        fprintf(stderr, "CRC error in temperature data\n");
        return -1;
    }
    if (crc8(&buffer[6], 3) != buffer[8]) {
        fprintf(stderr, "CRC error in scale factor data\n");
        return -1;
    }

    int16_t raw_pressure = (buffer[0] << 8) | buffer[1];
    int16_t raw_temperature = (buffer[3] << 8) | buffer[4];
    int16_t scale_factor = (buffer[6] << 8) | buffer[7];

    if (scale_factor == 0) {
        fprintf(stderr, "Invalid scale factor (0)\n");
        return -1;
    }

    *pressure = (float)raw_pressure / (float)scale_factor;
    *temperature = (float)raw_temperature / 200.0f;

    return 0;
}

static void log_data(float pressure, float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

