#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SCD40_I2C_ADDR 0x60
#define I2C_BUS "/dev/i2c-1"
#define LOG_DIR "/var/log/scd40_data"
#define ERROR_LOG_DIR "/var/log/scd40_error.log"
#define CSV_FILE "scd40_data.csv"
#define BUFFER_SIZE 100
#define READ_INTERVAL_SEC 5
#define LOG_INTERVAL_SEC 60
#define STARTUP_DELAY_SEC 1

#define SCD40_CMD_START_PERIODIC_MEASUREMENT 0x36
#define SCD40_CMD_STOP_PERIODIC_MEASUREMENT 0x37

#define SCD40_MEASUREMENT_INTERVAL 5
#define SCD40_DATA_READY_INTERVAL 0x0F

typedef struct {
    uint16_t co2;
    float temperature;
    float humidity;
} sensor_data_t;

typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} circular_buffer_t;

static int i2c_fd = -1;
static volatile sig_atomic_t running = 1;
static pthread_t logging_thread;
static circular_buffer_t co2_buffer;
static int buffer_count = 0;

static void log_error(const char *message) {
    FILE *fp = fopen(ERROR_LOG_DIR "/scd40_error.log", "a");
    if (!fp) {
        perror("Error opening error log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int i2c_write_cmd(uint8_t cmd) {
    uint8_t buf[2] = {0x00, cmd};
    if (write(i2c_fd, buf, 2) != 2) {
        log_error("I2C write command failed");
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(uint8_t *buf, int len) {
    if (read(i2c_fd, buf, len) != len) {
        log_error("I2C read failed");
        return -1;
    }
    return 0;
}

static int read_scd40_data(sensor_data_t *data) {
    uint8_t buf[9];
    if (i2c_read_bytes(buf, 9) < 0)
        return -1;

    if (crc8(&buf[0], 2) != buf[2]) {
        log_error("CO2 CRC mismatch");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        log_error("Temperature CRC mismatch");
        return -1;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        log_error("Humidity CRC mismatch");
        return -1;
    }

    uint16_t co2_raw = (buf[0] << 8) | buf[1];
    uint16_t temp_raw = (buf[3] << 8) | buf[4];
    uint16_t hum_raw = (buf[6] << 8) | buf[7];

    data->co2 = co2_raw;
    data->temperature = -45.0f + 175.0f * (float)temp_raw / 65535.0f;
    data->humidity = 100.0f * (float)hum_raw / 65535.0f;

    return 0;
}

static void buffer_add(sensor_data_t data) {
    pthread_mutex_lock(&co2_buffer.mutex);
    co2_buffer.data[co2_buffer.head] = data;
    co2_buffer.head = (co2_buffer.head + 1) % BUFFER_SIZE;
    if (co2_buffer.count < BUFFER_SIZE)
        co2_buffer.count++;
    else
        co2_buffer.tail = (co2_buffer.tail + 1) % BUFFER_SIZE;
    pthread_mutex_unlock(&co2_buffer.mutex);
}

static void *logging_thread_func(void *arg) {
    (void)arg;
    while (running) {
        sleep(LOG_INTERVAL_SEC);
        if (running) {
            pthread_mutex_lock(&co2_buffer.mutex);
            int count = co2_buffer.count;
            int start = (co2_buffer.tail + BUFFER_SIZE - count) % BUFFER_SIZE;
            pthread_mutex_unlock(&co2_buffer.mutex);

            FILE *fp = fopen(LOG_DIR "/scd40_data.csv", "a");
            if (!fp) {
                log_error("Failed to open CSV file");
                return NULL;
            }

            fseek(fp, 0, SEEK_END);
            long fsize = ftell(fp);
            if (fsize == 0) {
                fprintf(fp, "Timestamp,CO2,Temp,Humidity\n");
            }

            for (int i = 0; i < count; i++) {
                int idx = (start + i) % BUFFER_SIZE;
                sensor_data_t data = co2_buffer.data[idx];
                time_t t = time(NULL);
                struct tm tm = *localtime(&t);
                char timestamp[64];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

                fprintf(fp, "%s,%u,%.2f,%.2f\n", timestamp, data.co2, data.temperature, data.humidity);
            }

            fclose(fp);
            buffer_count = 0;
        }
    }
    return NULL;
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (i2c_fd >= 0) {
        i2c_write_cmd(SCD40_CMD_STOP_PERIODIC_MEASUREMENT);
        close(i2c_fd);
        i2c_fd = -1;
    }
    pthread_join(logging_thread, NULL);
    pthread_mutex_destroy(&co2_buffer.mutex);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SCD40_I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    if (i2c_write_cmd(SCD40_CMD_START_PERIODIC_MEASUREMENT) < 0) {
        close(i2c_fd);
        return 1;
    }

    sleep(STARTUP_DELAY_SEC);

    if (mkdir(LOG_DIR, 0755) != 0) {
        perror("Failed to create log directory");
        close(i2c_fd);
        return 1;
    }

    if (mkdir(ERROR_LOG_DIR, 0755) != 0) {
        perror("Failed to create error log directory");
    }

    if (pthread_create(&logging_thread, NULL, logging_thread_func, NULL) != 0) {
        perror("Failed to create logging thread");
        close(i2c_fd);
        return 1;
    }

    while (running) {
        sensor_data_t data;
        if (read_scd40_data(&data) == 0) {
            buffer_add(data);
            printf("CO2: %u ppm, Temp: %.2f C, Humidity: %.2f %%\n",
                   data.co2, data.temperature, data.humidity);
        } else {
            log_error("Failed to read sensor data");
        }

        for (int i = 0; i < READ_INTERVAL_SEC && running; i++)
            sleep(1);
    }

    pthread_join(logging_thread, NULL);
    cleanup();
    printf("Program terminated gracefully.\n");
    return 0;
}

