#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define ICP10125_ADDR  0x49
#define GPIO_CHIP      "gpiochip4"
#define GPIO_LED       17
#define PRESSURE_THRESHOLD 95000
#define POLL_INTERVAL_US 1000000
#define LED_BLINK_US    500000
#define LED_BLINK_HALF_US (LED_BLINK_US / 2)
#define TRIGGER_DELAY_US 20000
#define READ_LEN        6

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int i2c_read_bytes(int fd, uint8_t addr, uint8_t *buf, int len) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "I2C_SLAVE ioctl failed: %s\n", strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "I2C short read: got %zd of %d\n", n, len);
        return -1;
    }
    return 0;
}

static int read_sensor(int fd, uint16_t *pressure, uint16_t *temperature) {
    uint8_t data[READ_LEN];
    if (i2c_read_bytes(fd, ICP10125_ADDR, data, READ_LEN) < 0)
        return -1;

    if (crc8(data, 2) != data[2]) {
        fprintf(stderr, "Pressure CRC mismatch\n");
        return -1;
    }
    if (crc8(data + 3, 2) != data[5]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }

    *pressure    = ((uint16_t)data[0] << 8) | data[1];
    *temperature = ((uint16_t)data[3] << 8) | data[4];
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Cannot open %s: %s\n", GPIO_CHIP, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_line *led = gpiod_chip_get_line(chip, GPIO_LED);
    if (!led) {
        fprintf(stderr, "Cannot get GPIO line %d: %s\n", GPIO_LED, strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(led, "icp10125_led", 0) < 0) {
        fprintf(stderr, "Cannot request GPIO line %d as output: %s\n", GPIO_LED, strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    printf("ICP-10125 pressure monitor started. Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t pressure, temperature;

        if (read_sensor(i2c_fd, &pressure, &temperature) < 0) {
            fprintf(stderr, "Sensor read error; retrying in 1 s...\n");
            usleep(POLL_INTERVAL_US);
            continue;
        }

        printf("Pressure: %u Pa, Temperature: %u C\n", pressure, temperature);

        bool led_on = false;
        if (pressure < PRESSURE_THRESHOLD) {
            led_on = true;
            printf("Pressure below threshold (%u Pa). LED warning active.\n", pressure);
        }

        if (gpiod_line_set_value(led, led_on ? 1 : 0) < 0) {
            fprintf(stderr, "GPIO write failed: %s\n", strerror(errno));
        }

        if (led_on) {
            usleep(LED_BLINK_HALF_US);
            if (g_running)
                usleep(LED_BLINK_HALF_US);
        } else {
            usleep(LED_BLINK_HALF_US);
            if (g_running)
                usleep(LED_BLINK_HALF_US);
        }

        usleep(TRIGGER_DELAY_US);
    }

    printf("\nShutting down...\n");
    gpiod_line_set_value(led, 0);
    gpiod_line_release(led);
    gpiod_chip_close(chip);
    close(i2c_fd);
    printf("Resources released. Goodbye.\n");
    return EXIT_SUCCESS;
}

