#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <sys/time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x15
#define PORT 8080
#define MAX_RETRIES 3
#define MEASUREMENT_DELAY_US 10000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static int server_fd = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int read_sht40(int handle, float *temperature, float *humidity) {
    unsigned char cmd = 0x2E;
    unsigned char data[6];
    int result;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        result = i2cWriteDevice(handle, (char *)&cmd, 1);
        if (result != 0) {
            fprintf(stderr, "I2C write failed (attempt %d): %s\n", attempt + 1, strerror(errno));
            gpioDelay(100000);
            continue;
        }

        gpioDelay(MEASUREMENT_DELAY_US);

        result = i2cReadDevice(handle, (char *)data, 6);
        if (result != 6) {
            fprintf(stderr, "I2C read failed (attempt %d): %s\n", attempt + 1, strerror(errno));
            gpioDelay(100000);
            continue;
        }

        unsigned int temp_raw = (data[0] << 8) | data[1];
        unsigned int hum_raw = (data[3] << 8) | data[4];

        *temperature = -45.0f + 175.0f * (float)temp_raw / 65535.0f;
        *humidity = 100.0f * (float)hum_raw / 65535.0f;

        if (*humidity > 100.0f) *humidity = 100.0f;
        if (*humidity < 0.0f) *humidity = 0.0f;

        return 0;
    }

    return -1;
}

void send_data(float temperature, float humidity) {
    char html[1024];
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    snprintf(html, sizeof(html),
             "HTTP/1.1 200 OK\r\n"
             "Content-Type: text/html\r\n"
             "Content-Length: %zu\r\n"
             "Connection: close\r\n"
             "\r\n"
             "<!DOCTYPE html><html><head><title>SHT40 Data</title>"
             "<meta charset=\"UTF-8\"></head><body>"
             "<h1>SHT40 Data</h1>"
             "<p>Timestamp: %s</p>"
             "<p>Temperature: %.2f &deg;C</p>"
             "<p>Humidity: %.2f %%</p>"
             "</body></html>",
             strlen(html),
             temperature,
             humidity);

    if (send(server_fd, html, strlen(html), 0) < 0) {
        perror("send failed");
    }
}

void handle_client(int client_fd) {
    char buffer[1024];
    ssize_t bytes_received;

    while ((bytes_received = recv(client_fd, buffer, sizeof(buffer) - 1, 0)) > 0) {
        buffer[bytes_received] = '\0';
        printf("Received: %s", buffer);
        send_data(25.0f, 75.0f);
    }

    if (bytes_received < 0) {
        perror("recv failed");
    }
    close(client_fd);
}

int main() {
    float temperature, humidity;
    int new_socket;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        perror("socket failed");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt failed");
        close(server_fd);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sockaddr_in address;
    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        close(server_fd);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (listen(server_fd, 3) < 0) {
        perror("listen failed");
        close(server_fd);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Server listening on port %d\n", PORT);

    while (running) {
        if (read_sht40(i2c_handle, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f &deg;C, Humidity: %.2f %%\n", temperature, humidity);
            send_data(temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read SHT40 sensor after %d retries\n", MAX_RETRIES);
        }

        new_socket = accept(server_fd, NULL, NULL);
        if (new_socket < 0) {
            if (errno == EINTR) continue;
            perror("accept failed");
        }

        handle_client(new_socket);
    }

    printf("\nShutting down gracefully...\n");
    close(server_fd);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

