#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define TMP102_ADDR    0x48
#define LOG_FILE       "temperature_log.csv"
#define SAMPLE_PERIOD  5.0

/* TMP102 register addresses */
#define TMP102_REG_TEMP  0x00
#define TMP102_REG_CONFIG 0x01

/* Config: 12-bit resolution, continuous conversion, no alert */
#define TMP102_CONFIG    0x84

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int init_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, TMP102_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %s\n",
                I2C_BUS, TMP102_ADDR, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_temperature(float *temperature)
{
    char buf[2];
    int rc;

    /* Trigger a conversion by writing the config register */
    rc = i2cWriteByteData(g_i2c_handle, TMP102_REG_CONFIG, TMP102_CONFIG);
    if (rc < 0) {
        fprintf(stderr, "Error writing TMP102 config: %s\n", strerror(errno));
        return -1;
    }

    /* Wait for the conversion to complete (max ~26 ms for 12-bit) */
    gpioDelay(30000); /* 30 ms */

    /* Read 2 bytes from the temperature register */
    rc = i2cReadI2CBlockData(g_i2c_handle, TMP102_REG_TEMP, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "Error reading TMP102 data: %s\n", strerror(errno));
        return -1;
    }

    /* TMP102 is a two's-complement 12-bit value left-justified in 16 bits */
    int16_t raw = (int16_t)((buf[0] << 8) | (uint8_t)buf[1]);
    raw >>= 4; /* Right-align the 12-bit result */

    *temperature = (float)raw / 16.0f;
    return 0;
}

static int log_temperature(float temperature)
{
    FILE *fp;
    time_t t;
    struct tm tm_info;
    char timestamp[32];

    t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "Error getting time: %s\n", strerror(errno));
        return -1;
    }

    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error converting time: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        return -1;
    }

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    if (fprintf(fp, "%s,%.2f\n", timestamp, temperature) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    float temperature;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler: %s\n", strerror(errno));
    }

    printf("TMP102 temperature logger started. Press Ctrl+C to exit.\n");

    while (g_running) {
        if (read_temperature(&temperature) == 0) {
            if (log_temperature(temperature) != 0) {
                fprintf(stderr, "Failed to log temperature.\n");
            } else {
                printf("Temperature: %.2f C\n", temperature);
            }
        } else {
            fprintf(stderr, "Failed to read temperature.\n");
        }

        /* Sleep in small increments so SIGINT is caught promptly */
        for (int i = 0; i < 50 && g_running; i++) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    printf("\nShutting down...\n");

    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }

    gpioTerminate();

    return EXIT_SUCCESS;
}

