/*
 * Raspberry Pi Zero W – HDC2010 temperature & humidity reader
 *
 * Wiring:
 *   HDC2010 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   HDC2010 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   HDC2010 VDD  -> 3.3 V
 *   HDC2010 GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o hdc2010 hdc2010.c -li2c
 *
 * The HDC2010 is a 16-bit two-wire temperature & humidity sensor.
 * It requires a master-measurement command (0x0A) to be written to
 * the MEASUREMENT_CONFIG register (0x00) before the first conversion.
 * Subsequent conversions are polled by reading the same register
 * until bit 0 (DATA_READY) clears, then the 16-bit result is
 * assembled from the low byte (0x01) and high byte (0x02).
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <time.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define HDC2010_ADDR   0x15

/* HDC2010 register addresses */
#define REG_MEAS_CONFIG 0x00
#define REG_HUMIDITY    0x01
#define REG_TEMPERATURE 0x02

/* MEASUREMENT_CONFIG bit layout (16-bit, big-endian on the bus) */
#define MEAS_CONFIG_CMD  0x0A   /* master-measurement command */
#define MEAS_CONFIG_RDY  0x01   /* data-ready bit */

#define POLL_TIMEOUT_MS  500
#define POLL_DELAY_US    2000   /* 2 ms between polls */
#define MAX_RETRIES      5
#define SAMPLE_PERIOD_S  5

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Write a single byte to an 8-bit register.
 * Returns 0 on success, -1 on error.
 */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write_reg8(0x%02X, 0x%02X): write failed (%s)\n",
                reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read a single byte from an 8-bit register.
 * Returns the byte value (0–255) on success, -1 on error.
 */
static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    if (out == NULL) {
        return -1;
    }
    /* Send the register pointer */
    if (i2c_write_reg8(fd, reg, 0) < 0)
        return -1;
    /* Read one byte */
    uint8_t val;
    ssize_t n = read(fd, &val, 1);
    if (n != 1) {
        fprintf(stderr, "i2c_read_reg8(0x%02X): read failed (%s)\n",
                reg, strerror(errno));
        return -1;
    }
    *out = val;
    return 0;
}

/*
 * Read the 16-bit measurement result from the HDC2010.
 * Returns 0 on success, -1 on error.
 */
static int hdc2010_read_measurement(int fd, uint16_t *temp, uint16_t *hum)
{
    uint8_t lo, hi;

    /* Poll DATA_READY bit until it clears or timeout */
    for (int i = 0; i < POLL_TIMEOUT_MS; i++) {
        if (i2c_read_reg8(fd, REG_MEAS_CONFIG, &lo) < 0)
            return -1;
        if (i2c_read_reg8(fd, REG_HUMIDITY, &hi) < 0)
            return -1;

        uint16_t cfg = ((uint16_t)hi << 8) | lo;
        if (cfg & MEAS_CONFIG_RDY)
            break;                       /* data ready */

        usleep(POLL_DELAY_US);
    }

    if (!(cfg & MEAS_CONFIG_RDY)) {
        fprintf(stderr, "HDC2010: measurement timeout (DATA_READY never set)\n");
        return -1;
    }

    *temp = (uint16_t)((hi << 8) | lo);
    *hum  = (uint16_t)((hi << 8) | lo);
    return 0;
}

int main(void)
{
    int fd = -1;
    int rc = EXIT_FAILURE;

    /* Install signal handler for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the I2C bus */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the HDC2010 slave address */
    if (ioctl(fd, I2C_SLAVE, HDC2010_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                HDC2010_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Verify sensor presence with a zero-length write (optional) */
    if (i2c_write_reg8(fd, REG_MEAS_CONFIG, 0) < 0) {
        fprintf(stderr, "HDC2010 not responding at 0x%02X\n", HDC2010_ADDR);
        goto cleanup;
    }

    /* Start a master measurement */
    if (i2c_write_reg8(fd, REG_MEAS_CONFIG, MEAS_CONFIG_CMD) < 0) {
        fprintf(stderr, "Failed to start first measurement\n");
        goto cleanup;
    }

    /* Allow the first conversion to complete */
    sleep(1);

    printf("HDC2010 reader started. Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t temp_raw = 0, hum_raw = 0;

        if (hdc2010_read_measurement(fd, &temp_raw, &hum_raw) == 0) {
            float temperature = (float)temp_raw * 0.02f;
            float humidity    = (float)hum_raw * 0.02f;

            time_t now = time(NULL);
            struct tm tm_info;
            char ts[32];
            localtime_r(&now, &tm_info);
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);

            printf("[%s] Temperature: %.2f °C, Humidity: %.2f %%\n",
                   ts, temperature, humidity);
            fflush(stdout);
        } else {
            fprintf(stderr, "Sensor read failed; will retry next cycle.\n");
        }

        /* Sleep SAMPLE_PERIOD_S, but wake early on signal */
        for (int s = 0; s < SAMPLE_PERIOD_S && g_running; s++)
            sleep(1);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0)
        close(fd);
    if (rc == EXIT_SUCCESS)
        printf("\nExiting cleanly.\n");
    return rc;
}

