/*
 * SDP800-500Pa differential pressure sensor reader for Raspberry Pi 3 Model B+
 * I2C bus 1, address 0x48 (ADDR_MSB = 0x48, ADDR_LSB = 0x00).
 * Reads 6 bytes every 500 ms: P_MSB, P_LSB, P_CRC, T_MSB, T_LSB, T_CRC.
 * CRC-8: polynomial 0x31, initial value 0xFF.
 *
 * Build: gcc -O2 -Wall -Wextra -o sdp800 sdp800.c -li2c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SDP800_ADDR    0x48
#define MEAS_DELAY_MS  45
#define LOOP_DELAY_MS  500
#define NUM_BYTES      6

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* CRC-8 as used by Sensirion: poly 0x31, init 0xFF */
static bool crc8_ok(const uint8_t *data, size_t len, uint8_t expected)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc == expected;
}

static int i2c_write(int fd, const uint8_t *buf, size_t len)
{
    ssize_t n = write(fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "I2C write short: %zd of %zu bytes\n", n, len);
        return -1;
    }
    return 0;
}

static int i2c_read(int fd, uint8_t *buf, size_t len)
{
    size_t got = 0;
    while (got < len) {
        ssize_t n = read(fd, buf + got, len - got);
        if (n < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
            return -1;
        }
        if (n == 0) {
            fprintf(stderr, "I2C read: unexpected EOF (sensor absent?)\n");
            return -1;
        }
        got += (size_t)n;
    }
    return 0;
}

static int sdp800_read(int fd, int16_t *pressure, int16_t *temperature)
{
    uint8_t buf[NUM_BYTES];

    if (i2c_write(fd, (uint8_t[]){0x36, 0x00}, 2) < 0)
        return -1;

    /* SDP800 measurement command: 0x36 0x00 */
    if (i2c_write(fd, (uint8_t[]){0x36, 0x00}, 2) < 0)
        return -1;

    usleep(MEAS_DELAY_MS * 1000);

    if (i2c_read(fd, buf, NUM_BYTES) < 0)
        return -1;

    if (!crc8_ok(buf, 2, buf[2])) {
        fprintf(stderr, "Pressure CRC mismatch\n");
        return -1;
    }
    if (!crc8_ok(buf + 3, 2, buf[5])) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }

    *pressure    = (int16_t)((buf[0] << 8) | buf[1]);
    *temperature = (int16_t)((buf[3] << 8) | buf[4]);
    return 0;
}

int main(void)
{
    int fd = -1;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, SDP800_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n",
                SDP800_ADDR, strerror(errno));
        goto cleanup;
    }

    printf("SDP800-500Pa reader started on %s (addr 0x%02X).\n",
           I2C_BUS, SDP800_ADDR);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        int16_t p = 0, t = 0;

        if (sdp800_read(fd, &p, &t) == 0) {
            printf("Pressure: %6d Pa | Temperature: %6d °C\n", p, t);
        } else {
            fprintf(stderr, "Read failed; continuing.\n");
        }

        usleep(LOOP_DELAY_MS * 1000);
    }

    printf("\nExiting cleanly.\n");
    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0)
        close(fd);
    return rc;
}

