/*
 * reflow_pid.c — Raspberry Pi 3 Model B+ reflow oven controller
 *
 * Hardware:
 *   MAX6675 thermocouple amplifier on SPI0 (CE0 / GPIO8, SCLK / GPIO11,
 *   MOSI / GPIO10, MISO / GPIO9), VDD 3.3 V, GND common with Pi
 *   Solid-state relay (SSR) on GPIO17 (BCM) — active-high module
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o reflow_pid reflow_pid.c -lpigpio -lrt
 *   (requires pigpio daemon or -lpigpio-static)
 *
 * Run:
 *   sudo ./reflow_pid
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL    0          /* SPI0 CE0 (GPIO8) */
#define SPI_SPEED_HZ   1000000    /* 1 MHz — MAX6675 supports up to 5 MHz */
#define SPI_FLAGS      0          /* Mode 0, active-low CE, 8-bit words */

#define SSR_GPIO       17         /* BCM 17 — active-high SSR control */

#define LOG_FILE       "reflow_log.csv"
#define PROFILE_FILE   "profile.txt"

#define SAMPLE_PERIOD_US 1000000  /* 1 Hz */
#define INTEGRAL_LIMIT   256       /* 1 << 8 — 8-bit signed wraparound */

/* PID gains (tuned for ~260 °C reflow) */
#define KP 1.0
#define KI 0.1
#define KD 0.01

/* SSR duty-cycle range (0.0 .. 1.0) */
#define SSR_RANGE 100.0

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;
static FILE *g_prof_fp = NULL;
static int g_spi_handle = -1;

/* PID state */
typedef struct {
    double integral;
    double prev_error;
} pid_state_t;

static pid_state_t g_pid = {0.0, 0.0};

/* --------------------------- Forward declarations ------------------------ */
static void signal_handler(int sig);
static int  read_max6675(int handle, double *temp_c);
static double pid_control(double setpoint, double current,
                           double *integral, double *prev_err,
                           double dt);
static double load_profile(const char *path, double *times, double *temps,
                            int *n);
static void apply_pid(double setpoint, double current,
                      double *integral, double *prev_err,
                      double dt, double *out);
static void log_data(double temp_c, double duty);
static void cleanup(void);

/* ------------------------------- Signal handler -------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- MAX6675 read ------------------------------- */
/*
 * MAX6675 SPI protocol (3 bytes, mode 0, MSB-first):
 *   tx[0] = 0x01                 (start bit)
 *   tx[1] = 0x00                 (clock in previous reading)
 *   tx[2] = 0x00                 (dummy, clocks out 8 data bits)
 *   rx[1] bits 1:0 + rx[2] bits 7:0 = 14-bit thermocouple result
 *   rx[2] bit 8 = 0 → valid reading
 */
static int read_max6675(int handle, double *temp_c)
{
    char tx[3] = { 0x01, 0x00, 0x00 };
    char rx[3] = { 0 };

    if (spiXfer(handle, tx, rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    uint8_t msb = (uint8_t)rx[1] >> 2;   /* bits 1:0 of rx[1] */
    uint8_t lsb = (uint8_t)(rx[2] & 0x03); /* bits 7:4 of rx[2] */
    uint16_t raw = (uint16_t)((msb << 8) | lsb);

    /* 0.25 °C per LSB (datasheet) */
    *temp_c = (double)raw * 0.25;
    return 0;
}

/* --------------------------- PID control -------------------------------- */
static double pid_control(double setpoint, double current,
                           double *integral, double *prev_err,
                           double dt)
{
    double error = setpoint - current;

    *integral += error * dt;
    if (*integral >  INTEGRAL_LIMIT) *integral =  INTEGRAL_LIMIT;
    if (*integral < -INTEGRAL_LIMIT) *integral = -INTEGRAL_LIMIT;

    double deriv = KP * error + KI * (*integral) + KD * error * dt;

    *prev_err = error;
    return deriv;
}

/* --------------------------- Profile loader ----------------------------- */
static double load_profile(const char *path, double *times, double *temps,
                            int *n)
{
    FILE *fp = fopen(path, "r");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", path, strerror(errno));
        return 0.0;
    }

    char line[256];
    int n_lines = 0;
    while (fgets(line, sizeof(line), fp) != NULL) {
        if (sscanf(line, "%lf,%lf", times[n_lines], temps[n_lines]) == 2) {
            n_lines++;
        } else {
            fprintf(stderr, "Malformed line %d: %s", n_lines, line);
            fclose(fp);
            return 0.0;
        }
    }

    fclose(fp);
    *n = n_lines;
    return 1.0;
}

/* --------------------------- SSR mapping -------------------------------- */
static double map(double v, double in_min, double in_max,
                  double out_min, double out_max)
{
    return (v - in_min) * (out_max - out_min) / (in_max - in_min) + out_min;
}

/* --------------------------- Logging ------------------------------------ */
static void log_data(double temp_c, double duty)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    fprintf(g_log_fp, "%s,%.2f,%.2f\n", ts, temp_c, duty);
    fflush(g_log_fp);
}

/* --------------------------- Cleanup ------------------------------------- */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_prof_fp) {
        fclose(g_prof_fp);
        g_prof_fp = NULL;
    }
    /* Ensure SSR is off before terminating pigpio */
    gpioWrite(SSR_GPIO, 0);
    gpioTerminate();
}

/* --------------------------------- Main ---------------------------------- */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- SPI init (CE0 / GPIO8) --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED_HZ, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- SSR GPIO setup --- */
    if (gpioSetMode(SSR_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for GPIO%d\n", SSR_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(SSR_GPIO, 0);   /* SSR off at startup */

    /* --- Log file --- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    fprintf(g_log_fp, "# timestamp,temperature_c,duty_cycle\n");
    fflush(g_log_fp);

    /* --- Profile file --- */
    g_prof_fp = fopen(PROFILE_FILE, "r");
    if (!g_prof_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", PROFILE_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    double times[256] = {0.0};
    double temps[256] = {0.0};
    int n = load_profile(PROFILE_FILE, times, temps, &n);
    if (n == 0) {
        fprintf(stderr, "No valid profile data found\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (n > 0) {
        fprintf(g_prof_fp, "# Profile: %d points\n", n);
        for (int i = 0; i < n; i++) {
            fprintf(g_prof_fp, "time%d,%.2f\n", i, temps[i]);
        }
        fflush(g_prof_fp);
    } else {
        fprintf(g_prof_fp, "# Profile: %d points\n", n);
        for (int i = 0; i < n; i++) {
            fprintf(g_prof_fp, "time%d,%.2f\n", i, times[i]);
        }
        fflush(g_prof_fp);
    }
    fclose(g_prof_fp);
    g_prof_fp = NULL;

    /* --- Signals --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* --- Main loop --- */
    double target_temp = 260.0;   /* example reflow profile peak */
    double prev_error = 0.0;
    double integral = 0.0;
    double duty = 0.0;
    double dt = 1.0;               /* 1 s sample period */
    double current_temp = 0.0;
    int profile_idx = 0;

    while (g_running) {
        double t = (double)time(NULL) / 60.0;   /* seconds */

        /* --- Read thermocouple --- */
        if (read_max6675(g_spi_handle, &current_temp) != 0) {
            fprintf(stderr, "Thermocouple read error — SSR off, retrying\n");
            gpioWrite(SSR_GPIO, 0);
            gpioDelay(1000000);   /* 1 s back-off */
            continue;
        }

        /* --- PID --- */
        double pid_out = pid_control(target_temp, current_temp,
                                     &g_pid.integral, &g_pid.prev_err, dt);

        /* --- SSR mapping --- */
        duty = map(pid_out, 0.0, 1.0, 0.0, SSR_RANGE);

        /* --- Clamp duty to valid range --- */
        if (duty < 0.0) duty = 0.0;
        if (duty > SSR_RANGE) duty = SSR_RANGE;

        /* --- Apply PID --- */
        apply_pid(target_temp, current_temp,
                  &g_pid.integral, &g_pid.prev_err, dt, &duty);

        /* --- Log --- */
        log_data(current_temp, duty);

        /* --- Profile interpolation --- */
        if (profile_idx < n) {
            double t_target = times[profile_idx];
            double temp_target = temps[profile_idx];
            double dt_target = (t - t_target) / (double)(profile_idx + 1);
            double duty_target = 0.0;
            pid_control(temp_target, 0.0,
                        &g_pid.integral, &g_pid.prev_err, dt_target, &duty_target);
            duty = duty_target;
        } else {
            /* End of profile — hold last point */
            duty = 0.0;
        }

        /* --- SSR control --- */
        gpioWrite(SSR_GPIO, duty > 0.0 ? 1 : 0);

        /* --- Display --- */
        printf("t=%.2fs  T=%.2fC  d=%.2f  (%.0f%%)\n",
               t, current_temp, duty, duty * 100.0);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

