#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define AHT20_ADDR             0x38
#define AHT20_MEASURE_CMD      0x2C
#define AHT20_HUMIDITY_MSB     0x00
#define AHT20_HUMIDITY_LSB     0x01
#define AHT20_HUMIDITY_X2      0x02
#define AHT20_HUMIDITY_X4      0x03
#define AHT20_HUMIDITY_X8      0x04
#define AHT20_STATUS           0x05
#define AHT20_CALIB            0x06
#define AHT20_HUMIDITY_CAL     0x07
#define AHT20_TEMP_MSB         0x08
#define AHT20_TEMP_LSB         0x09
#define AHT20_TEMP_X2          0x0A
#define AHT20_TEMP_X4          0x0B
#define AHT20_TEMP_X8          0x0C
#define AHT20_TEMP_CAL         0x0D
#define AHT20_TEMP_HUMIDITY_CAL 0x0E
#define AHT20_CMD_BIT          0x80
#define AHT20_MEASURE_DELAY_US 80000
#define DEHUMIDIFIER_GPIO      17
#define HUMIDITY_THRESHOLD_HIGH 60.0f
#define HUMIDITY_THRESHOLD_LOW  55.0f
#define POLL_INTERVAL_S        5
#define MAX_RETRIES            3
#define RETRY_DELAY_US         10000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t byte) {
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, int len) {
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int aht20_trigger_measurement(int fd) {
    return i2c_write_byte(fd, AHT20_MEASURE_CMD | AHT20_CMD_BIT);
}

static int aht20_read_humidity(int fd, float *humidity) {
    uint8_t data[6];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (aht20_trigger_measurement(fd) < 0) {
            retries++;
            usleep(RETRY_DELAY_US);
            continue;
        }

        usleep(AHT20_MEASURE_DELAY_US);

        if (i2c_read_bytes(fd, data, 6) < 0) {
            retries++;
            usleep(RETRY_DELAY_US);
            continue;
        }

        if ((data[0] & 0x80) != 0) {
            fprintf(stderr, "AHT20 status: not calibrated (0x%02X)\n", data[0]);
            retries++;
            usleep(RETRY_DELAY_US);
            continue;
        }

        uint16_t raw = ((uint16_t)data[0] << 8) | data[1];
        *humidity = (float)raw / 16384.0f;
        return 0;
    }

    fprintf(stderr, "AHT20 read failed after %d retries\n", MAX_RETRIES);
    return -1;
}

static void control_dehumidifier(int gpio_pin, float humidity) {
    if (humidity > HUMIDITY_THRESHOLD_HIGH) {
        gpioWrite(gpio_pin, 1);
        printf("Dehumidifier ON (Humidity: %.2f%%)\n", humidity);
    } else if (humidity < HUMIDITY_THRESHOLD_LOW) {
        gpioWrite(gpio_pin, 0);
        printf("Dehumidifier OFF (Humidity: %.2f%%)\n", humidity);
    }
}

static void log_data(float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] Humidity: %.2f%%\n", timestamp, humidity);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(DEHUMIDIFIER_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", DEHUMIDIFIER_GPIO);
        gpioTerminate();
        return 1;
    }
    gpioWrite(DEHUMIDIFIER_GPIO, 0);

    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, AHT20_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                AHT20_ADDR, strerror(errno));
        close(g_i2c_fd);
        gpioTerminate();
        return 1;
    }

    printf("AHT20 humidity monitor started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float humidity;
        if (aht20_read_humidity(g_i2c_fd, &humidity) == 0) {
            log_data(humidity);
            control_dehumidifier(DEHUMIDIFIER_GPIO, humidity);
        } else {
            fprintf(stderr, "Sensor read failed; continuing.\n");
        }

        for (int i = 0; i < POLL_INTERVAL_S && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    gpioWrite(DEHUMIDIFIER_GPIO, 0);
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
    }
    gpioTerminate();
    return 0;
}

