#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <syslog.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define HTU21D_ADDR 0x40
#define API_ENDPOINT "http://api.example.com/humidity"
#define POLL_INTERVAL 60
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_bytes(int fd, unsigned char *buf, int len) {
    int total = 0;
    while (total < len) {
        ssize_t n = read(fd, buf + total, len - total);
        if (n < 0) {
            if (errno == EINTR) continue;
            return -1;
        }
        if (n == 0) return -1;
        total += n;
    }
    return 0;
}

static int i2c_write_bytes(int fd, const unsigned char *buf, int len) {
    int total = 0;
    while (total < len) {
        ssize_t n = write(fd, buf + total, len - total);
        if (n < 0) {
            if (errno == EINTR) continue;
            return -1;
        }
        if (n == 0) return -1;
        total += n;
    }
    return 0;
}

static int read_humidity(int fd, float *humidity) {
    unsigned char cmd = 0x2C;
    unsigned char data[4];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2c_write_bytes(fd, &cmd, 1) < 0) {
            syslog(LOG_ERR, "I2C write failed (attempt %d): %s", retries + 1, strerror(errno));
            retries++;
            sleep(1);
            continue;
        }

        usleep(20000);

        if (i2c_read_bytes(fd, data, 4) < 0) {
            syslog(LOG_ERR, "I2C read failed (attempt %d): %s", retries + 1, strerror(errno));
            retries++;
            sleep(1);
            continue;
        }

        if (data[3] != ((data[0] + data[1] + data[2]) & 0xFF)) {
            syslog(LOG_ERR, "CRC mismatch (attempt %d)", retries + 1);
            retries++;
            sleep(1);
            continue;
        }

        int raw = (data[0] << 8) | data[1];
        *humidity = (float)raw / 10.0f;
        return 0;
    }

    syslog(LOG_ERR, "Failed to read humidity after %d attempts", MAX_RETRIES);
    return -1;
}

static int send_http_request(int sockfd, const char *json_data) {
    char request[1024];
    int len = snprintf(request, sizeof(request), "POST %s HTTP/1.1\r\nHost: api.example.com\r\nContent-Type: application/json\r\nContent-Length: %d\r\nConnection: close\r\n\r\n%s",
                       API_ENDPOINT, strlen(json_data), json_data);
    if (len < 0 || (size_t)len >= sizeof(request)) {
        syslog(LOG_ERR, "HTTP request buffer overflow");
        return -1;
    }

    if (send(sockfd, request, len, 0) < 0) {
        syslog(LOG_ERR, "send() failed: %s", strerror(errno));
        return -1;
    }

    char resp[1024];
    ssize_t n = recv(sockfd, resp, sizeof(resp) - 1, 0);
    if (n < 0) {
        syslog(LOG_ERR, "recv() failed: %s", strerror(errno));
        return -1;
    }
    if (n == 0) {
        syslog(LOG_WARNING, "Server closed connection without sending response");
        return 0;
    }
    resp[n] = '\0';

    char *newline = strpbrk(resp, "\r\n");
    if (newline) *newline = '\0';
    if (strstr(resp, "HTTP/1.") == NULL) {
        syslog(LOG_ERR, "Server did not send HTTP headers");
        return -1;
    }

    char *body = strstr(resp, "Content-Length:");
    if (body) {
        body += strlen("Content-Length:");
        while (*body == ' ') body++;
        char *endptr;
        long plen = strtol(body, &endptr, 10);
        if (endptr == body) {
            syslog(LOG_ERR, "Invalid Content-Length in response");
            return -1;
        }
        if (plen != n - strlen(resp)) {
            syslog(LOG_ERR, "Response Content-Length mismatch: got %ld, expected %d", plen, n - strlen(resp));
            return -1;
        }
    }

    return 0;
}

int main(void) {
    openlog("humidity_sensor", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "sigaction failed: %s", strerror(errno));
        closelog();
        return 1;
    }

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        syslog(LOG_ERR, "Failed to open %s: %s", I2C_BUS, strerror(errno));
        closelog();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to set I2C slave address 0x%02X: %s", HTU21D_ADDR, strerror(errno));
        close(i2c_fd);
        closelog();
        return 1;
    }

    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        syslog(LOG_ERR, "socket() failed: %s", strerror(errno));
        close(i2c_fd);
        closelog();
        return 1;
    }

    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(80);
    if (inet_pton(AF_INET, "api.example.com", &server_addr.sin_addr) <= 0) {
        syslog(LOG_ERR, "inet_pton() failed: %s", strerror(errno));
        close(sockfd);
        close(i2c_fd);
        closelog();
        return 1;
    }

    syslog(LOG_INFO, "Starting humidity sensor monitoring (interval: %d seconds)", POLL_INTERVAL);

    while (running) {
        float humidity;
        if (read_humidity(i2c_fd, &humidity) == 0) {
            char json_data[128];
            snprintf(json_data, sizeof(json_data), "{\"humidity\":%.2f}", humidity);

            if (send_http_request(sockfd, json_data) == 0) {
                syslog(LOG_INFO, "Humidity: %.2f%%, posted to API", humidity);
            } else {
                syslog(LOG_ERR, "Failed to send HTTP request");
            }
        } else {
            syslog(LOG_ERR, "Failed to read humidity from sensor");
        }

        for (int i = 0; i < POLL_INTERVAL && running; i++) {
            sleep(1);
        }
    }

    syslog(LOG_INFO, "Shutting down gracefully");
    close(sockfd);
    close(i2c_fd);
    closelog();
    return 0;
}

