#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BMP280_I2C_ADDR 0x76
#define I2C_BUS 1
#define LOG_FILE "pressure_log.txt"
#define SEA_LEVEL_PRESSURE_HPA 1013.25
#define PRESSURE_HIGH_THRESHOLD 1020.0
#define PRESSURE_LOW_THRESHOLD 980.0
#define SAMPLE_INTERVAL_US 2000000
#define CONVERSION_DELAY_US 10000
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_calibration_data(int handle, uint16_t *dig_T1, int16_t *dig_T2, int16_t *dig_T3,
                                 uint16_t *dig_P1, int16_t *dig_P2, int16_t *dig_P3,
                                 int16_t *dig_P4, int16_t *dig_P5, int16_t *dig_P6,
                                 int16_t *dig_P7, int16_t *dig_P8, int16_t *dig_P9) {
    uint8_t buf[24];
    if (i2cReadI2CBlockData(handle, 0x88, (char *)buf, 24) != 24) {
        return -1;
    }
    *dig_T1 = (uint16_t)(buf[0] | (buf[1] << 8));
    *dig_T2 = (int16_t)(buf[2] | (buf[3] << 8));
    *dig_T3 = (int16_t)(buf[4] | (buf[5] << 8));
    *dig_P1 = (uint16_t)(buf[6] | (buf[7] << 8));
    *dig_P2 = (int16_t)(buf[8] | (buf[9] << 8));
    *dig_P3 = (int16_t)(buf[10] | (buf[11] << 8));
    *dig_P4 = (int16_t)(buf[12] | (buf[13] << 8));
    *dig_P5 = (int16_t)(buf[14] | (buf[15] << 8));
    *dig_P6 = (int16_t)(buf[16] | (buf[17] << 8));
    *dig_P7 = (int16_t)(buf[18] | (buf[19] << 8));
    *dig_P8 = (int16_t)(buf[20] | (buf[21] << 8));
    *dig_P9 = (int16_t)(buf[22] | (buf[23] << 8));
    return 0;
}

static int read_raw_data(int handle, int32_t *raw_temp, int32_t *raw_press) {
    uint8_t buf[6];
    if (i2cReadI2CBlockData(handle, 0xF7, (char *)buf, 6) != 6) {
        return -1;
    }
    *raw_press = (int32_t)((buf[0] << 12) | (buf[1] << 4) | (buf[2] >> 4));
    *raw_temp = (int32_t)((buf[3] << 12) | (buf[4] << 4) | (buf[5] >> 4));
    return 0;
}

static double compensate_temperature(int32_t raw_temp, int32_t *t_fine) {
    double var1 = ((double)raw_temp / 16384.0 - (double)dig_T1 / 1024.0) * (double)dig_T2;
    double var2 = ((double)raw_temp / 131072.0 - (double)dig_T1 / 8192.0) *
                  ((double)raw_temp / 131072.0 - (double)dig_T1 / 8192.0) * (double)dig_T3;
    *t_fine = (int32_t)(var1 + var2);
    return (var1 + var2) / 5120.0;
}

static double compensate_pressure(int32_t raw_press, int32_t t_fine) {
    double var1 = (double)t_fine / 2.0 - 64000.0;
    double var2 = var1 * var1 * (double)dig_P6 / 32768.0;
    var2 = var2 + var1 * (double)dig_P5 * 2.0;
    var2 = (var2 / 4.0) + (double)dig_P4 * 65536.0;
    var1 = ((double)dig_P3 * var1 * var1 / 524288.0 + (double)dig_P2 * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0) * (double)dig_P1;
    if (var1 == 0.0) return 0.0;
    double p = 1048576.0 - (double)raw_press;
    p = (p - (var2 / 4096.0)) * 6250.0 / var1;
    var1 = (double)dig_P9 * p * p / 2147483648.0;
    var2 = p * (double)dig_P8 / 32768.0;
    p = p + (var1 + var2 + (double)dig_P7) / 16.0;
    return p;
}

static int log_pressure(double pressure) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
