#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <signal.h>
#include <errno.h>
#include <stdint.h>

#define TMP117_ADDR 0x48
#define AHT20_ADDR  0x29
#define PIR_CHIP    "gpiochip4"
#define PIR_LINE    17
#define I2C_DEV     "/dev/i2c-1"
#define LOG_FILE    "sensor_data.csv"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10
#define SAMPLE_INTERVAL_S 1

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read(int fd, uint8_t addr, uint8_t *buf, size_t len) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "I2C_SLAVE ioctl failed for 0x%02X: %s\n", addr, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed for 0x%02X (got %zd of %zu): %s\n",
                addr, n, len, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_tmp117(int fd, float *temp) {
    uint8_t buf[2];
    if (i2c_read(fd, TMP117_ADDR, buf, 2) < 0) return -1;
    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *temp = (float)raw * 0.0078125f;
    return 0;
}

static int read_aht20(int fd, float *hum) {
    uint8_t buf[7];
    if (i2c_read(fd, AHT20_ADDR, buf, 7) < 0) return -1;
    uint32_t tick = ((uint32_t)buf[0] << 24) | ((uint32_t)buf[1] << 16) |
                    ((uint32_t)buf[2] << 8)  | (uint32_t)buf[3];
    tick >>= 2;
    if (tick == 0) return -1;
    uint32_t hum_raw = tick * 0.0001f;
    *hum = (float)hum_raw;
    return 0;
}

static int read_pir(struct gpiod_line *line, int *motion) {
    int val = gpiod_line_get_value(line);
    if (val < 0) {
        fprintf(stderr, "gpiod_line_get_value failed: %s\n", strerror(errno));
        return -1;
    }
    *motion = val;
    return 0;
}

static void log_data(float temp, float hum, int motion) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.2f,%d\n", ts, temp, hum, motion);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_DEV, strerror(errno));
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(PIR_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", PIR_CHIP, strerror(errno));
        close(i2c_fd);
        return 1;
    }
    struct gpiod_line *pir_line = gpiod_chip_get_line(chip, PIR_LINE);
    if (!pir_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", PIR_LINE, strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }
    if (gpiod_line_request_input(pir_line, "pir_sensor") < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as input: %s\n", PIR_LINE, strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    printf("Starting sensor logging. Press Ctrl+C to exit.\n");

    while (running) {
        float temp = 0.0f, hum = 0.0f;
        int motion = 0;
        int ok = 1;

        if (read_tmp117(i2c_fd, &temp) < 0) {
            fprintf(stderr, "TMP117 read failed\n");
            ok = 0;
        }
        if (read_aht20(i2c_fd, &hum) < 0) {
            fprintf(stderr, "AHT20 read failed\n");
            ok = 0;
        }
        if (read_pir(pir_line, &motion) < 0) {
            fprintf(stderr, "PIR read failed\n");
            ok = 0;
        }

        if (ok) {
            log_data(temp, hum, motion);
            printf("Logged: %.2f C, %.2f %%, Motion: %s\n",
                   temp, hum, motion ? "YES" : "NO");
        } else {
            fprintf(stderr, "Skipping log due to sensor failure\n");
        }

        for (int i = 0; i < MAX_RETRIES && running; i++) {
            sleep(RETRY_DELAY_MS / 1000);
        }
    }

    printf("\nShutting down...\n");
    gpiod_line_release(pir_line);
    gpiod_chip_close(chip);
    close(i2c_fd);
    printf("Resources released. Exiting.\n");
    return 0;
}

