#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <math.h>
#include <pigpio.h>

#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

#define PWM_RANGE 255
#define SAMPLE_INTERVAL_US 500000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void set_led_color(int red, int green, int blue)
{
    /* Common-anode: 0 = full brightness, 255 = off */
    gpioPWM(RED_PIN,   red);
    gpioPWM(GREEN_PIN, green);
    gpioPWM(BLUE_PIN,  blue);
}

static void turn_led_off(void)
{
    gpioPWM(RED_PIN,   0);
    gpioPWM(GREEN_PIN, 0);
    gpioPWM(BLUE_PIN,  0);
}

static int read_cpu_load(void)
{
    FILE *fp = fopen("/proc/stat", "r");
    if (!fp) {
        fprintf(stderr, "Error opening /proc/stat: %s\n", strerror(errno));
        return -1;
    }

    char line[256];
    if (!fgets(line, sizeof(line), fp)) {
        fprintf(stderr, "Error reading /proc/stat: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);

    /* Parse the CPU time fields */
    char *endptr;
    long long user = 0, nice = 0, system = 0, idle = 0, iowait = 0, irq = 0, softirq = 0, steal = 0, guest = 0, guest_nice = 0;

    if (sscanf(line, "cpu  %lld %lld %lld %lld %lld %lld %lld %lld %lld %lld",
               &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice) != 10) {
        fprintf(stderr, "Error parsing /proc/stat CPU time\n");
        return -1;
    }

    static long long prev_user = 0, prev_nice = 0, prev_system = 0,
                  prev_idle = 0, prev_iowait = 0, prev_irq = 0,
                  prev_softirq = 0, prev_steal = 0, prev_guest = 0,
                  prev_guest_nice = 0;

    long long now_user, now_nice, now_system, now_idle, now_iowait,
           now_irq, now_softirq, now_steal, now_guest, now_guest_nice;

    if (sscanf(line, "cpu  %lld %lld %lld %lld %lld %lld %lld %lld %lld",
               &now_user, &now_nice, &now_system, &now_idle, &now_iowait,
               &now_irq, &now_softirq, &now_steal, &now_guest, &now_guest_nice) != 10) {
        fprintf(stderr, "Error parsing /proc/stat CPU time\n");
        return -1;
    }

    /* Calculate deltas */
    long long delta_user  = now_user  - prev_user;
    long long delta_nice = now_nice - prev_nice;
    long long delta_system = now_system - prev_system;
    long long delta_idle  = now_idle  - prev_idle;
    long long delta_iowait = now_iowait - prev_iowait;
    long long delta_irq   = now_irq   - prev_irq;
    long long delta_softirq= now_softirq - prev_softirq;
    long long delta_steal  = now_steal  - prev_steal;
    long long delta_guest  = now_guest  - prev_guest;
    long long delta_guest_nice = now_guest_nice - prev_guest_nice;

    prev_user  = now_user;
    prev_nice = now_nice;
    prev_system = now_system;
    prev_idle  = now_idle;
    prev_iowait = now_iowait;
    prev_irq   = now_irq;
    prev_softirq = now_softirq;
    prev_steal  = now_steal;
    prev_guest  = now_guest;
    prev_guest_nice = now_guest_nice;

    /* Calculate percentages (excluding idle time) */
    double total_non_idle = delta_user + delta_nice + delta_system +
                           delta_steal + delta_guest + delta_guest_nice;
    if (total_non_idle == 0) {
        fprintf(stderr, "Error: total non-idle CPU time is zero\n");
        return -1;
    }

    double cpu_load = (double)(delta_user + delta_nice + delta_system)
                     / total_non_idle * 100.0;

    if (cpu_load < 0.0) cpu_load = 0.0;
    if (cpu_load > 100.0) cpu_load = 100.0;

    return (int)cpu_load;
}

int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error installing SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error installing SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Configure GPIO pins as outputs */
    if (gpioSetMode(RED_PIN,   PI_OUTPUT) != 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(BLUE_PIN,  PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO modes\n");
        gpioTerminate();
        return 1;
    }

    /* Set PWM range to 0-255 for common-anode LED */
    if (gpioSetPWMrange(RED_PIN,   PWM_RANGE) != 0 ||
        gpioSetPWMrange(GREEN_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(BLUE_PIN,  PWM_RANGE) != 0) {
        fprintf(stderr, "Error setting PWM range\n");
        gpioTerminate();
        return 1;
    }

    /* Set PWM frequency to 1000 Hz (standard for common-anode RGB LEDs) */
    if (gpioSetPWMfrequency(RED_PIN,   1000) != 0 ||
        gpioSetPWMfrequency(GREEN_PIN, 1000) != 0 ||
        gpioSetPWMfrequency(BLUE_PIN,  1000) != 0) {
        fprintf(stderr, "Error setting PWM frequency\n");
        gpioTerminate();
        return 1;
    }

    /* Ensure LED is off initially */
    turn_led_off();

    printf("CPU Load Monitor started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int cpu_load = read_cpu_load();

        if (cpu_load < 0) {
            /* Error already printed; keep running */
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        /* Map CPU load to RGB color (0=green, 50=yellow, 100=red) */
        int red   = (int)((cpu_load / 50.0) * 255);
        int green = (int)((100.0 - (cpu_load / 50.0) * 2.0) * 255);
        int blue  = 0;

        if (red   > 255) red   = 255;
        if (green > 255) green = 255;
        if (blue  > 255) blue  = 255;

        set_led_color(red, green, blue);

        printf("CPU Load: %d%%  |  R:%d  G:%d  B:%d\n", cpu_load, red, green, blue);

        usleep(SAMPLE_INTERVAL_US);
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    turn_led_off();
    gpioTerminate();
    printf("Done.\n");

    return 0;
}

