#define BMP280_I2C_ADDR 0x76
#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_PRESSURE_MSB 0xF7
#define BMP280_REG_CONTROL_MEAS 0xF4
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_ID 0xD0
#define BMP280_CHIP_ID 0x58
#define BMP280_RESET_CMD 0xB6
#define BMP280_RESET_DELAY_US 1000
#define BMP280_MEAS_DELAY_US 10000
#define BMP280_CONFIG_DEFAULT 0x00
#define BMP280_CTRL_MEAS_DEFAULT 0x25
#define SERVER_IP "192.168.1.100"
