#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define SPI_CHANNEL    0
#define SPI_SPEED      500000
#define SPI_FLAGS      0
#define FAN_GPIO       18
#define PWM_FREQ       1000
#define PWM_RANGE      255
#define BUFFER_SIZE    20
#define SAMPLE_PERIOD  1.0

#define TEMP_MIN       25.0f
#define TEMP_MAX       60.0f
#define FAN_MIN        0
#define FAN_MAX        255
#define FAN_STEP       50

#define TEMP_THRESHOLD  40.0f
#define FAN_STEP2       100

typedef struct {
    time_t timestamp;
    float  temperature;
    int    pwm_duty;
} FanData;

static FanData circular_buffer[BUFFER_SIZE];
static int  buffer_index = 0;
static int  buffer_count = 0;

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void add_to_buffer(float temperature, int pwm_duty) {
    time(&circular_buffer[buffer_index].timestamp);
    circular_buffer[buffer_index].temperature = temperature;
    circular_buffer[buffer_index].pwm_duty = pwm_duty;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
}

static void print_buffer(void) {
    printf("\n--- Fan Data Buffer (%d entries) ---\n", buffer_count);
    for (int i = 0; i < buffer_count; i++) {
        int idx = (buffer_index - buffer_count + i + BUFFER_SIZE) % BUFFER_SIZE;
        char tbuf[32];
        struct tm *tm = localtime(&circular_buffer[idx].timestamp);
        if (tm) {
            strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", tm);
        } else {
            strncpy(tbuf, "unknown", sizeof(tbuf) - 1);
            tbuf[sizeof(tbuf) - 1] = '\0';
        }
        printf("[%s] Temp=%.2f C  PWM=%d/%d\n",
               tbuf, circular_buffer[idx].temperature,
               circular_buffer[idx].pwm_duty, FAN_MAX);
    }
    printf("--- End of Buffer ---\n\n");
}

static int init_pigpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

static int init_spi(void) {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (channel %d, %d Hz): %s\n",
                SPI_CHANNEL, SPI_SPEED, pigpio_error(spi_handle));
        return -1;
    }
    return 0;
}

static int read_max31855(float *temperature) {
    unsigned char tx[4] = {0, 0, 0, 0};
    unsigned char rx[4] = {0, 0, 0, 0};

    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 4) != 4) {
        fprintf(stderr, "spiXfer failed: %s\n", pigpio_error(spi_handle));
        return -1;
    }

    uint32_t raw = ((uint32_t)rx[0] << 24) |
                   ((uint32_t)rx[1] << 16) |
                   ((uint32_t)rx[2] << 8)  |
                   ((uint32_t)rx[3]);

    if (raw & 0x00010000) {
        fprintf(stderr, "MAX31855 fault bit set (raw=0x%08X)\n", raw);
        return -1;
    }

    int32_t therm = (int32_t)(raw >> 18);
    *temperature = therm * 0.25f;
    return 0;
}

static int compute_fan_duty(float temperature) {
    if (temperature < TEMP_MIN) return FAN_MIN;
    if (temperature > TEMP_MAX) return FAN_MAX;

    if (temperature < TEMP_THRESHOLD) return FAN_MIN;
    if (temperature < TEMP_MAX) {
        int frac = (int)((temperature - TEMP_THRESHOLD) / (TEMP_MAX - TEMP_THRESHOLD) * FAN_STEP);
        if (frac < FAN_MIN) frac = FAN_MIN;
        if (frac > FAN_MAX) frac = FAN_MAX;
        return frac;
    }

    int frac = (int)((temperature - TEMP_THRESHOLD) / (TEMP_MAX - TEMP_THRESHOLD) * FAN_STEP2);
    if (frac < FAN_MIN) frac = FAN_MIN;
    if (frac > FAN_MAX) frac = FAN_MAX;
    return frac;
}

static void set_fan_speed(int pwm_duty) {
    if (gpioPWM(FAN_GPIO, pwm_duty) < 0) {
        fprintf(stderr, "gpioPWM failed on GPIO %d\n", FAN_GPIO);
    }
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioPWM(FAN_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }

    if (init_pigpio() != 0) return 1;

    if (init_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed on GPIO %d\n", FAN_GPIO);
        cleanup();
        return 1;
    }

    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQ) < 0) {
        fprintf(stderr, "gpioSetPWMfrequency failed on GPIO %d\n", FAN_GPIO);
        cleanup();
        return 1;
    }

    if (gpioSetPWMrange(FAN_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "gpioSetPWMrange failed on GPIO %d\n", FAN_GPIO);
        cleanup();
        return 1;
    }

    printf("Fan control started. Press Ctrl+C to exit.\n");

    while (running) {
        float temperature;
        if (read_max31855(&temperature) != 0) {
            fprintf(stderr, "Temperature read failed; skipping fan update.\n");
        } else {
            int pwm_duty = compute_fan_duty(temperature);
            set_fan_speed(pwm_duty);
            add_to_buffer(temperature, pwm_duty);
            printf("Temp=%.2f C  PWM=%d/%d\n", temperature, pwm_duty, FAN_MAX);
        }

        time_sleep(SAMPLE_PERIOD);
    }

    print_buffer();
    cleanup();
    return 0;
}

