#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BMP180_ADDR 0x77
#define INTERRUPT_PIN 2
#define LOG_FILE "altitude_log.txt"
#define OSS 3

static volatile sig_atomic_t logging_enabled = 0;
static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

static void interrupt_handler(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; (void)level; (void)tick; (void)user;
    logging_enabled = !logging_enabled;
    printf("Logging %s\n", logging_enabled ? "enabled" : "disabled");
}

static int read_calibration_data(int handle) {
    char buf[22];
    if (i2cReadDevice(handle, buf, 22) != 22) {
        fprintf(stderr, "Error: Failed to read calibration data\n");
        return -1;
    }
    ac1 = (int16_t)((buf[0] << 8) | buf[1]);
    ac2 = (int16_t)((buf[2] << 8) | buf[3]);
    ac3 = (int16_t)((buf[4] << 8) | buf[5]);
    ac4 = (uint16_t)((buf[6] << 8) | buf[7]);
    ac5 = (uint16_t)((buf[8] << 8) | buf[9]);
    ac6 = (uint16_t)((buf[10] << 8) | buf[11]);
    b1 = (int16_t)((buf[12] << 8) | buf[13]);
    b2 = (int16_t)((buf[14] << 8) | buf[15]);
    mb = (int16_t)((buf[16] << 8) | buf[17]);
    mc = (int16_t)((buf[18] << 8) | buf[19]);
    md = (int16_t)((buf[20] << 8) | buf[21]);
    return 0;
}

static int read_raw_temperature(int handle) {
    char buf[2];
    if (i2cWriteDevice(handle, "00", 2) != 2) {
        fprintf(stderr, "Error: Failed to write to I2C device for temperature\n");
        return -1;
    }
    gpioDelay(5000);
    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read from I2C device for temperature\n");
        return -1;
    }
    return (buf[0] << 8) | buf[1];
}

static int read_raw_pressure(int handle) {
    char buf[3];
    if (i2cWriteDevice(handle, "05", 3) != 3) {
        fprintf(stderr, "Error: Failed to write to I2C device for pressure\n");
        return -1;
    }
    gpioDelay(5000);
    if (i2cReadDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "Error: Failed to read from I2C device for pressure\n");
        return -1;
    }
    return ((buf[0] << 16) | (buf[1] << 8) | buf[2]) >> (8 - OSS);
}

static double calculate_temperature(int ut, int16_t *b5_out) {
    int32_t x1 = ((int32_t)ut - ac6) * ac5 >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + md);
    int32_t b5 = x1 + x2;
    *b5_out = b5;
    return ((b5 + 8) >> 4) / 10.0;
}

static double calculate_pressure(int up, int16_t b5) {
    int32_t b6 = b5 - 4000;
    int32_t x1 = (b2 * (b6 * b6 >> 12)) >> 11;
    int32_t x2 = (ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((ac1 * 4 + x3) << OSS) + 2) >> 2;
    x1 = (ac3 * b6) >> 13;
    x2 = (b1 * (b6 * b6 >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = (ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> OSS);
    int32_t p;
    if (b7 < 0x80000000) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p += (x1 + x2 + 3791) >> 4;
    return p / 100.0;
}

static void log_data(double temperature, double pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, pressure);
    fflush(log_file);
}

static void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (read_calibration_data(i2c_handle) != 0) {
        fprintf(stderr, "Error: Failed to read calibration data\n");
        cleanup();
        return 1;
    }

    gpioSetMode(INTERRUPT_PIN, PI_INPUT);
    gpioSetPullUpDown(INTERRUPT_PIN, PI_PUD_UP);
    if (gpioSetISRFuncEx(INTERRUPT_PIN, FALLING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set ISR function\n");
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("BMP180 logging started. Press Ctrl+C to exit.\n");

    while (running) {
        if (logging_enabled) {
            int ut = read_raw_temperature(i2c_handle);
            int16_t b5;
            if (ut < 0) {
                fprintf(stderr, "Error: Failed to read temperature\n");
            } else {
                double temperature = calculate_temperature(ut, &b5);
                int up = read_raw_pressure(i2c_handle);
                if (up < 0) {
                    fprintf(stderr, "Error: Failed to read pressure\n");
                } else {
                    double pressure = calculate_pressure(up, b5);
                    log_data(temperature, pressure);
                }
            }
        }
        gpioDelay(1000000);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return 0;
}

