#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED_HZ 1000000
#define SPI_BITS_PER_WORD 8
#define SPI_MODE 0

#define LOG_FILE "rtd_log.csv"
#define SAMPLE_INTERVAL_SEC 5

#define RTD_A 0.0039083
#define RTD_B -0.0000005775
#define RTD_C 0.000000000004183
#define RTD_R0 100.0

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int spi_init(void) {
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI max speed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    g_spi_fd = fd;
    return 0;
}

static int spi_transfer(uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_rtd_raw(uint16_t *raw) {
    uint8_t tx[4] = {0x00, 0x00, 0x00, 0x00};
    uint8_t rx[4] = {0};

    if (spi_transfer(tx, rx, 4) < 0) {
        return -1;
    }

    *raw = ((uint16_t)rx[0] << 8) | rx[1];
    return 0;
}

static int read_rtd_fault(uint8_t *fault) {
    uint8_t tx[2] = {0x00, 0x00};
    uint8_t rx[2] = {0};

    if (spi_transfer(tx, rx, 2) < 0) {
        return -1;
    }

    *fault = rx[0] & 0x07;
    return 0;
}

static float calculate_temperature(uint16_t raw) {
    if (raw == 0) {
        return -1000.0f;
    }

    uint8_t fault;
    if (read_rtd_fault(&fault) < 0) {
        return -1000.0f;
    }

    if (fault & 0x01) {
        fprintf(stderr, "RTD fault detected: 0x%02X\n", fault);
        return -1000.0f;
    }

    if (fault & 0x02) {
        fprintf(stderr, "RTD open circuit\n");
        return -1000.0f;
    }

    if (fault & 0x04) {
        fprintf(stderr, "RTD short circuit\n");
        return -1000.0f;
    }

    float rtd_resistance = (float)raw - 32768.0f;
    float rtd_temperature = (rtd_resistance - RTD_R0) / RTD_A;

    float t = rtd_temperature;
    float v = (t / 200.0f) - 1.0f;
    float c = v * v * v * 0.0000005775f - v * v * v * 0.000000000004183f;
    float b = v * v * v * 0.0039083f - v * v * v * 0.000000000004183f;

    if (c == 0.0f) {
        return -1000.0f;
    }

    float t_cvd = (b + c) / 8.0f;
    return t_cvd;
}

static int log_temperature(float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(g_log_fp, "%s,%.2f\n", timestamp, temperature) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (spi_init() < 0) {
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    fseek(g_log_fp, 0, SEEK_END);
    long file_size = ftell(g_log_fp);
    if (file_size == 0) {
        fprintf(g_log_fp, "Timestamp,Temperature (C)\n");
        fflush(g_log_fp);
    }

    printf("RTD monitoring started. Logging to %s every %d seconds. Press Ctrl+C to exit.\n",
           LOG_FILE, SAMPLE_INTERVAL_SEC);

    while (g_running) {
        uint16_t raw;
        if (read_rtd_raw(&raw) < 0) {
            fprintf(stderr, "Failed to read RTD data. Retrying in %d seconds.\n", SAMPLE_INTERVAL_SEC);
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        float temperature = calculate_temperature(raw);
        if (temperature < -900.0f) {
            fprintf(stderr, "Invalid temperature reading: %.2f\n", temperature);
        } else {
            if (log_temperature(temperature) < 0) {
                fprintf(stderr, "Failed to log temperature.\n");
            } else {
                printf("Temperature: %.2f C\n", temperature);
            }
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

