#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define BME280_I2C_ADDR 0x76
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "bme280_log.csv"
#define SAMPLE_INTERVAL_SEC 5

#define BME280_REG_ID 0xD0
#define BME280_REG_RESET 0xE0
#define BME280_REG_CTRL_HUM 0xF2
#define BME280_REG_STATUS 0xF3
#define BME280_REG_CTRL_MEAS 0xF4
#define BME280_REG_CONFIG 0xF5
#define BME280_REG_DATA 0xF7
#define BME280_REG_CALIB_00 0x88
#define BME280_REG_CALIB_26 0xE1

#define BME280_CHIP_ID 0x60

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static int16_t dig_T1, dig_T2, dig_T3;
static int16_t dig_P1, dig_P2, dig_P3, dig_P4, dig_P5, dig_P6, dig_P7, dig_P8, dig_P9;
static uint16_t dig_H1, dig_H3, dig_H6;
static int16_t dig_H2, dig_H4, dig_H5;
static int8_t dig_H6_T1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != (ssize_t)len) return -1;
    return 0;
}

static int read_calibration_data(int fd) {
    uint8_t c1[26], c2[7];
    if (i2c_read_block(fd, BME280_REG_CALIB_00, c1, 26) < 0) return -1;
    if (i2c_read_block(fd, BME280_REG_CALIB_26, c2, 7) < 0) return -1;

    dig_T1 = (c1[1] << 8) | c1[0];
    dig_T2 = (c1[3] << 8) | c1[2];
    dig_T3 = (c1[5] << 8) | c1[4];
    dig_P1 = (c1[7] << 8) | c1[6];
    dig_P2 = (c1[9] << 8) | c1[8];
    dig_P3 = (c1[11] << 8) | c1[10];
    dig_P4 = (c1[13] << 8) | c1[12];
    dig_P5 = (c1[15] << 8) | c1[14];
    dig_P6 = (c1[17] << 8) | c1[16];
    dig_P7 = (c1[19] << 8) | c1[18];
    dig_P8 = (c1[21] << 8) | c1[20];
    dig_P9 = (c1[23] << 8) | c1[22];
    dig_H1 = c1[25];
    dig_H2 = (c1[27] << 8) | c1[26];
    dig_H3 = c1[28];
    dig_H4 = (c1[29] << 4) | (c1[30] & 0x0F);
    dig_H5 = (c1[31] << 4) | (c1[30] >> 4);
    dig_H6 = c1[32];
    dig_H6_T1 = (int8_t)c1[33];
    return 0;
}

static int bme280_init(int fd) {
    uint8_t id;
    if (i2c_read_reg8(fd, BME280_REG_ID, &id) < 0) {
        fprintf(stderr, "Error reading chip ID: %s\n", strerror(errno));
        return -1;
    }
    if (id != BME280_CHIP_ID) {
        fprintf(stderr, "Invalid chip ID: 0x%02X (expected 0x%02X)\n", id, BME280_CHIP_ID);
        return -1;
    }

    if (i2c_write_reg8(fd, BME280_REG_RESET, 0xB6) < 0) {
        fprintf(stderr, "Error resetting sensor: %s\n", strerror(errno));
        return -1;
    }
    usleep(2000);

    if (i2c_write_reg8(fd, BME280_REG_CTRL_HUM, 0x01) < 0) {
        fprintf(stderr, "Error writing CTRL_HUM: %s\n", strerror(errno));
        return -1;
    }
    if (i2c_write_reg8(fd, BME280_REG_CONFIG, 0xA0) < 0) {
        fprintf(stderr, "Error writing CONFIG: %s\n", strerror(errno));
        return -1;
    }
    if (i2c_write_reg8(fd, BME280_REG_CTRL_MEAS, 0x27) < 0) {
        fprintf(stderr, "Error writing CTRL_MEAS: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_raw_data(int fd, int32_t *raw_t, int32_t *raw_p, int32_t *raw_h) {
    uint8_t data[8];
    if (i2c_read_block(fd, BME280_REG_DATA, data, 8) < 0) {
        fprintf(stderr, "Error reading data registers: %s\n", strerror(errno));
        return -1;
    }
    *raw_t = (int32_t)((data[3] << 12) | (data[4] << 4) | (data[5] >> 4));
    *raw_p = (int32_t)((data[6] << 12) | (data[7] << 4) | (data[5] >> 4));
    *raw_h = (int32_t)((data[0] << 8) | data[1]);
    return 0;
}

static float compensate_temperature(int32_t raw_t) {
    double var1 = ((double)raw_t / 16384.0 - (double)dig_T1 / 1024.0) * (double)dig_T2;
    double var2 = ((double)raw_t / 131072.0 - (double)dig_T1 / 8192.0) *
                  ((double)raw_t / 131072.0 - (double)dig_T1 / 8192.0) * (double)dig_T3;
    dig_T1 = (int16_t)(var1 + 128.0);
    dig_T2 = (int16_t)(var2 + 128.0);
    return (float)((var1 + var2) / 5120.0);
}

static float compensate_pressure(int32_t raw_p) {
    double var1 = ((double)raw_p / 16384.0 - (double)dig_P1 / 1024.0) *
                  ((double)raw_p / 16384.0 - (double)dig_P1 / 1024.0) * (double)dig_P6;
    double var2 = ((double)raw_p / 131072.0 - (double)dig_P1 / 8192.0) *
                  ((double)raw_p / 131072.0 - (double)dig_P1 / 8192.0) * (double)dig_P5;
    double var3 = ((double)raw_p / 16384.0 - (double)dig_P1 / 1024.0) *
                  ((double)raw_p / 131072.0 - (double)dig_P1 / 8192.0) * (double)dig_P4;
    double p = (double)raw_p + ((double)dig_P7 / 1.0) * (var1 + var2 + var3);
    p = fmodf(p, 16777215.0);
    p = (p * 3.0) / 256.0;
    var1 = ((double)dig_P8 / 1.0) * p * p * (double)dig_P9 / 2147483648.0;
    var2 = p * (double)dig_P10 / 1.0;
    p = p + (var1 + var2 + (double)dig_P11) / 16.0;
    return (float)p;
}

static float compensate_humidity(int32_t raw_h) {
    double var_H = ((double)raw_h) - (double)dig_H4 - ((double)dig_H5 / 16384.0) * (double)raw_h;
    var_H = var_H * (double)dig_H2 / 65536.0;
    var_H = var_H + ((double)dig_H6 / 131072.0) * var_H * (double)dig_H1;
    var_H = (var_H * (1.0 + var_H * (double)dig_H3 / 524288.0)) * (double)dig_H3 / 524288.0;
    var_H = var_H * (1.0 - (double)dig_H6 / 67108864.0) * (double)dig_H2 / 67108864.0;
    var_H = var_H * (1.0 + var_H * (double)dig_H4 / 2147483648.0);
    var_H = (var_H * 100.0) / (double)dig_H3;
    if (var_H > 100.0) var_H = 100.0;
    if (var_H < 0.0) var_H = 0.0;
    return (float)var_H;
}

static int log_data(float temp, float hum, float pres) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    if (fprintf(g_log_fp, "%s,%.2f,%.2f,%.2f\n", ts, temp, hum, pres) < 0) {
        fprintf(stderr, "Error writing to log: %s\n", strerror(errno));
        return -1;
    }
    fflush(g_log_fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, BME280_I2C_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    if (bme280_init(g_i2c_fd) < 0) {
        fprintf(stderr, "BME280 initialization failed.\n");
        close(g_i2c_fd);
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    fseek(g_log_fp, 0, SEEK_END);
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "Timestamp,Temperature(C),Humidity(%%),Pressure(hPa)\n");
        fflush(g_log_fp);
    }

    printf("BME280 initialized. Logging to %s every %d seconds. Press Ctrl+C to stop.\n",
           LOG_FILE, SAMPLE_INTERVAL_SEC);

    while (g_running) {
        int32_t raw_t, raw_p, raw_h;
        if (read_raw_data(g_i2c_fd, &raw_t, &raw_p, &raw_h) < 0) {
            fprintf(stderr, "Read failed, retrying in %d seconds...\n", SAMPLE_INTERVAL_SEC);
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        float temp = compensate_temperature(raw_t);
        float pres = compensate_pressure(raw_p);
        float hum = compensate_humidity(raw_h);

        if (log_data(temp, hum, pres) < 0) {
            fprintf(stderr, "Logging failed, continuing...\n");
        }

        printf("T: %.2f C, H: %.2f %%, P: %.2f hPa\n", temp, hum, pres);
        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down gracefully.\n");
    if (g_log_fp) fclose(g_log_fp);
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    return 0;
}

