static float compensate_pressure(int32_t raw_p) {
    double var1 = ((double)raw_p / 16384.0 - (double)dig_P1 / 1024.0) *
                  ((double)raw_p / 16384.0 - (double)dig_P1 / 1024.0) * (double)dig_P6;
    double var2 = ((double)raw_p / 131072.0 - (double)dig_P1 / 8192.0) *
                  ((double)raw_p / 131072.0 - (double)dig_P1 / 8192.0) * (double)dig_P5;
