#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <errno.h>
#include <string.h>
#include <pigpio.h>

#define BMP180_ADDR             0x77
#define BMP180_REG_CONTROL      0xF4
#define BMP180_REG_MSB          0xF6
#define BMP180_REG_LSB          0xF7
#define BMP180_REG_XLSB         0xF8
#define BMP180_REG_CAL_START    0xAA
#define BMP180_CAL_LEN          22
#define BMP180_CMD_TEMP         0x2E
#define BMP180_CMD_PRESSURE     0x34
#define BMP180_TEMP_CONV_US     4500
#define BMP180_PRESSURE_CONV_US 5000
#define BUFFER_SIZE             60
#define SAMPLE_INTERVAL_US      50000
#define ALERT_GPIO               24
#define PRESSURE_THRESHOLD_HPA   5.0
#define I2C_BUS                 1

typedef struct {
    time_t timestamp;
    int32_t pressure;
} PressureData;

typedef struct {
    PressureData data[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static CircularBuffer buffer;
static int32_t t_fine;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_calibration_data(int handle, int16_t *ac1, int16_t *ac2, int16_t *ac3, uint16_t *ac4, uint16_t *ac5, uint16_t *ac6, int16_t *b1, int16_t *b2, int16_t *mc, int16_t *md) {
    uint8_t cal[BMP180_CAL_LEN];
    if (i2cReadI2CBlockData(handle, BMP180_REG_CAL_START, (char *)cal, BMP180_CAL_LEN) != BMP180_CAL_LEN) {
        fprintf(stderr, "Error reading calibration data: %s\n", strerror(errno));
        return -1;
    }
    *ac1 = (int16_t)((cal[0]  << 8) | cal[1]);
    *ac2 = (int16_t)((cal[2]  << 8) | cal[3]);
    *ac3 = (int16_t)((cal[4]  << 8) | cal[5]);
    *ac4 = (uint16_t)((cal[6]  << 8) | cal[7]);
    *ac5 = (uint16_t)((cal[8]  << 8) | cal[9]);
    *ac6 = (uint16_t)((cal[10] << 8) | cal[11]);
    *b1  = (int16_t)((cal[12] << 8) | cal[13]);
    *b2  = (int16_t)((cal[14] << 8) | cal[15]);
    *mc  = (int16_t)((cal[16] << 8) | cal[17]);
    *md  = (int16_t)((cal[18] << 8) | cal[19]);
    return 0;
}

static int read_raw_temperature(int handle, int32_t *ut) {
    if (i2cWriteByteData(handle, BMP180_REG_CONTROL, BMP180_CMD_TEMP) < 0) {
        fprintf(stderr, "Error writing temperature command: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(BMP180_TEMP_CONV_US);
    int msb = i2cReadByteData(handle, BMP180_REG_MSB);
    int lsb = i2cReadByteData(handle, BMP180_REG_LSB);
    if (msb < 0 || lsb < 0) {
        fprintf(stderr, "Error reading temperature data: %s\n", strerror(errno));
        return -1;
    }
    *ut = (msb << 8) | lsb;
    return 0;
}

static int read_raw_pressure(int handle, int32_t *up) {
    if (i2cWriteByteData(handle, BMP180_REG_CONTROL, BMP180_CMD_PRESSURE) < 0) {
        fprintf(stderr, "Error writing pressure command: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(BMP180_PRESSURE_CONV_US);
    int msb = i2cReadByteData(handle, BMP180_REG_MSB);
    int lsb = i2cReadByteData(handle, BMP180_REG_LSB);
    int xlsb = i2cReadByteData(handle, BMP180_REG_XLSB);
    if (msb < 0 || lsb < 0 || xlsb < 0) {
        fprintf(stderr, "Error reading pressure data: %s\n", strerror(errno));
        return -1;
    }
    *up = ((msb << 16) | (lsb << 8) | xlsb) >> (8 - 0);
    return 0;
}

static int32_t compute_b5(int32_t ut, int32_t *b5_out) {
    int32_t x1 = ((ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    int32_t b5 = x1 + x2;
    if (b5_out) *b5_out = b5;
    return b5;
}

static int32_t calculate_pressure(int32_t up, int32_t b5) {
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x2 = ((int32_t)ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)ac1 * 4 + x3) << 0) + 2) >> 2);
    x1 = ((int32_t)ac3 * b6) >> 13;
    x2 = ((int32_t)b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> 0);
    int32_t p;
    if (b7 < 0x80000000UL) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);
    return p;
}

static void buffer_add(CircularBuffer *cb, time_t ts, int32_t pressure) {
    cb->data[cb->head].timestamp = ts;
    cb->data[cb->head].pressure = pressure;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
}

static double calculate_rolling_average(const CircularBuffer *cb) {
    if (cb->count == 0) return 0.0;
    double sum = 0.0;
    for (int i = 0; i < cb->count; i++) {
        int idx = (cb->head - cb->count + i + BUFFER_SIZE) % BUFFER_SIZE;
        sum += cb->data[idx].pressure;
    }
    return sum / (double)cb->count;
}

static void timer_callback(void *user_data) {
    (void)user_data;
    if (!running) return;
    int32_t ut, up, b5;
    if (read_raw_temperature(i2c_handle, &ut) < 0) {
        fprintf(stderr, "Temperature read failed\n");
        return;
    }
    if (read_raw_pressure(i2c_handle, &up) < 0) {
        fprintf(stderr, "Pressure read failed\n");
        return;
    }
    int32_t b5_val;
    compute_b5(ut, &b5_val);
    int32_t pressure = calculate_pressure(up, b5_val);
    time_t now = time(NULL);
    buffer_add(&buffer, now, pressure);
    double avg = calculate_rolling_average(&buffer);
    double diff = fabs(pressure - avg);
    if (diff > PRESSURE_THRESHOLD_HPA) {
        fprintf(stderr, "Alert: Pressure deviation %.2f hPa from average\n", diff);
        if (gpioWrite(ALERT_GPIO, 1) < 0) {
            fprintf(stderr, "Error setting alert GPIO: %s\n", strerror(errno));
        }
    } else {
        if (gpioWrite(ALERT_GPIO, 0) < 0) {
            fprintf(stderr, "Error clearing alert GPIO: %s\n", strerror(errno));
        }
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(I2C_BUS, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %s\n", I2C_BUS, BMP180_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }
    if (read_calibration_data(i2c_handle, &buffer.data[0].ac1, &buffer.data[0].ac2, &buffer.data[0].ac3, &buffer.data[0].ac4, &buffer.data[0].ac5, &buffer.data[0].ac6, &buffer.data[0].b1, &buffer.data[0].b2, &buffer.data[0].mc, &buffer.data[0].md) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    buffer.head = 0;
    buffer.count = 0;
    if (gpioSetMode(ALERT_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d as output: %s\n", ALERT_GPIO, strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioWrite(ALERT_GPIO, 0);
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    if (gpioSetTimerFuncEx(0, SAMPLE_INTERVAL_US, timer_callback, NULL) < 0) {
        fprintf(stderr, "Error setting timer: %s\n", strerror(errno));
        gpioWrite(ALERT_GPIO, 0);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    printf("BMP180 pressure monitoring started. Press Ctrl+C to exit.\n");
    while (running) {
        gpioDelay(100000);
    }
    printf("\nCleaning up...\n");
    gpioSetTimerFuncEx(0, 0, NULL, NULL);
    gpioWrite(ALERT_GPIO, 0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

