#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/pwm.h>

#define FAN_GPIO 18
#define PWM_FREQUENCY 25000
#define PWM_RANGE 255
#define TEMP_MIN 40.0
#define TEMP_MAX 70.0
#define LOG_FILE "fan_log.txt"
#define SLEEP_SECONDS 5

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signum) {
    (void)signum;
    program_running = 0;
}

static int read_temperature(float *temperature) {
    FILE *fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening temperature file: %s\n", strerror(errno));
        return -1;
    }

    char buffer[16];
    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        fprintf(stderr, "Error reading temperature file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    fclose(fp);
    char *endptr;
    long millideg = strtol(buffer, &endptr, 10);
    if (*endptr != '\n' && *endptr != '\0') {
        fprintf(stderr, "Error parsing temperature value\n");
        return -1;
    }

    *temperature = (float)millideg / 1000.0f;
    return 0;
}

static int calculate_duty_cycle(float temperature) {
    if (temperature <= TEMP_MIN) {
        return 0;
    } else if (temperature >= TEMP_MAX) {
        return PWM_RANGE;
    } else {
        float fraction = (temperature - TEMP_MIN) / (TEMP_MAX - TEMP_MIN);
        return (int)(fraction * PWM_RANGE);
    }
}

static int write_to_log_file(float temperature, int duty_cycle) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, Temperature: %.2f C, Duty Cycle: %d\n", timestamp, temperature, duty_cycle);
    fclose(fp);
    return 0;
}

static int initialize_pwm(void) {
    if (ioctl(FAN_GPIO, PWM_export, "fan_pwm") < 0) {
        fprintf(stderr, "Error exporting PWM: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(FAN_GPIO, PWM_set_mode, 1) < 0) {
        fprintf(stderr, "Error setting PWM mode: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(FAN_GPIO, PWM_set_frequency, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error setting PWM frequency: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(FAN_GPIO, PWM_set_range, PWM_RANGE) < 0) {
        fprintf(stderr, "Error setting PWM range: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(FAN_GPIO, PWM_set_period, 0) < 0) {
        fprintf(stderr, "Error setting PWM period: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void cleanup_pwm(void) {
    if (ioctl(FAN_GPIO, PWM_unexport, "fan_pwm") < 0) {
        fprintf(stderr, "Warning: Error unexporting PWM: %s\n", strerror(errno));
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (initialize_pwm() < 0) {
        fprintf(stderr, "PWM initialization failed. Exiting.\n");
        return 1;
    }

    printf("Fan control program started. Press Ctrl+C to exit.\n");

    while (program_running) {
        float temperature;
        if (read_temperature(&temperature) < 0) {
            fprintf(stderr, "Error reading temperature. Retrying in %d seconds.\n", SLEEP_SECONDS);
            sleep(SLEEP_SECONDS);
            continue;
        }

        int duty_cycle = calculate_duty_cycle(temperature);
        if (ioctl(FAN_GPIO, PWM_set_duty_cycle, duty_cycle) < 0) {
            fprintf(stderr, "Error setting PWM duty cycle: %s\n", strerror(errno));
        }

        if (write_to_log_file(temperature, duty_cycle) < 0) {
            fprintf(stderr, "Error writing to log file.\n");
        }

        printf("Temperature: %.2f C, Duty Cycle: %d\n", temperature, duty_cycle);

        for (int i = 0; i < SLEEP_SECONDS && program_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    cleanup_pwm();
    return 0;
}

