#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define BMP280_ADDR_DEFAULT  0x76
#define BMP280_ADDR_ALT      0x77
#define LOG_FILE          "weather_data.txt"
#define SAMPLE_INTERVAL_S  5

/* BMP280 registers */
#define BMP280_REG_TEMP_MSB   0xFA
#define BMP280_REG_PRESS_MSB  0xF7
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_CONFIG    0xF5
#define BMP280_REG_ID        0xD0

#define BMP280_CHIP_ID       0x58
#define BMP280_RESET_CMD     0xB6

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C primitives ---- */

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_write_reg8(0x%02X, 0x%02X) failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8: write reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8: read reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *val)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg16: write reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_read_reg16: read reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *val = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

/* ---- BMP280 ---- */

static int bmp280_init(int fd)
{
    uint8_t id;
    if (i2c_read_reg8(fd, BMP280_REG_ID, &id) < 0) {
        fprintf(stderr, "Cannot read BMP280 chip ID\n");
        return -1;
    }
    if (id != BMP280_CHIP_ID) {
        fprintf(stderr, "Unexpected chip ID 0x%02X (expected 0x%02X)\n",
                id, BMP280_CHIP_ID);
        return -1;
    }

    /* config: t_sb=0.5ms(000), filter=4(010), spi3w_en=0 -> 0x28 */
    if (i2c_write_reg8(fd, BMP280_REG_CONFIG, 0x28) < 0) {
        fprintf(stderr, "Failed to write config register\n");
        return -1;
    }

    /* ctrl_meas: osrs_t=x1(000), osrs_p=x1(000), mode=forced(01) -> 0x25 */
    if (i2c_write_reg8(fd, BMP280_REG_CTRL_MEAS, 0x25) < 0) {
        fprintf(stderr, "Failed to write ctrl_meas register\n");
        return -1;
    }

    return 0;
}

static int bmp280_read_raw(int fd, int32_t *raw_t, int32_t *raw_p)
{
    uint8_t ctrl = 0x25;  /* forced mode, osrs_t=x1, osrs_p=x1 */

    if (i2c_write_reg8(fd, BMP280_REG_CTRL_MEAS, ctrl) < 0) {
        return -1;
    }

    /* BMP280 forced mode: max conversion time ~5.5 ms */
    usleep(6000);

    if (i2c_read_reg16(fd, BMP280_REG_PRESS_MSB, raw_p) < 0) {
        return -1;
    }
    if (i2c_read_reg16(fd, BMP280_REG_TEMP_MSB, raw_t) < 0) {
        return -1;
    }
    return 0;
}

/* Bosch 64-bit compensation (datasheet §4.6.3, §4.6.4) */
static int32_t bmp280_compensate_temp(int32_t raw_t)
{
    int32_t var1, var2;
    var1 = ((((raw_t >> 3) - ((int32_t)76800)) * ((int32_t)32768)) >> 10);
    var2 = (((((raw_t >> 4) - ((int32_t)20480)) * ((int32_t)32768)) >> 10)
            + ((var1 >> 2) * ((int32_t)16384)));
    return (var2 * 2) / 4;
}

static uint32_t bmp280_compensate_press(int32_t raw_p)
{
    int32_t var1, var2;
    uint32_t p;
    var1 = (((int32_t)raw_p) - ((int32_t)32768));
    var2 = ((var1 >> 2) * ((int32_t)16384));
    var2 = var2 + ((var1 * var1) >> 11);
    var1 = (((int32_t)1048576 - (var1 >> 12)) * ((int32_t)3125));
    var2 = ((var2 * (int32_t)3125) >> 15);
    p = (uint32_t)((var1 + var2) >> 1);
    return p;
}

static int bmp280_read(int fd, float *temp_c, float *press_hpa)
{
    int32_t raw_t, raw_p;

    if (bmp280_read_raw(fd, &raw_t, &raw_p) < 0) {
        return -1;
    }

    *temp_c = (float)bmp280_compensate_temp(raw_t) / 100.0f;
    *press_hpa = (float)bmp280_compensate_press(raw_p) / 100.0f;
    return 0;
}

/* ---- Logging ---- */

static int log_data(float temp_c, float press_hpa)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        fprintf(stderr, "localtime_r failed\n");
        fclose(fp);
        return -1;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s, Temperature: %.2f °C, Pressure: %.2f hPa\n",
                ts, temp_c, press_hpa) < 0) {
        fprintf(stderr, "fprintf to %s failed: %s\n", LOG_FILE, strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose(%s) failed: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- Main ---- */

int main(void)
{
    int fd = -1;
    int addr = BMP280_ADDR_DEFAULT;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, BMP280_ADDR_DEFAULT) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n",
                BMP280_ADDR_DEFAULT, strerror(errno));
        goto cleanup;
    }

    if (bmp280_init(fd) < 0) {
        fprintf(stderr, "BMP280 init failed\n");
        goto cleanup;
    }

    printf("BMP280 initialized at 0x%02X on %s\n", BMP280_ADDR_DEFAULT, I2C_BUS);

    while (g_running) {
        float temp_c, press_hpa;

        if (bmp280_read(fd, &temp_c, &press_hpa) < 0) {
            fprintf(stderr, "BMP280 read failed; continuing\n");
        } else {
            printf("Temperature: %.2f °C, Pressure: %.2f hPa\n",
                   temp_c, press_hpa);
            if (log_data(temp_c, press_hpa) < 0) {
                fprintf(stderr, "Logging failed\n");
            }
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_S * 10 && g_running; i++) {
            usleep(100000);
        }
    }

    printf("\nExiting cleanly.\n");

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return 0;
}

