#define LM75_ADDR        0x49
#define LM75_TEMP_REG    0x00
#define LM75_CONFIG_REG  0x01
#define LM75_CONFIG_VAL  0x00
#define ALERT_LED_PIN    18
#define ALERT_LED_CONSUMER "lm75_alert"
#define BUFFER_SIZE      60
#define TEMP_THRESHOLD   28.0f
#define POLL_INTERVAL_US 1000000

typedef struct {
    float buffer[BUFFER_SIZE];
