#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 500000
#define SPI_MODE 1
#define SPI_BITS 8

#define PWM_GPIO 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000

#define DEFAULT_Kp 1.0
#define DEFAULT_Ki 0.1
#define DEFAULT_Kd 0.01
#define DEFAULT_TargetTemperature 25.0
#define MAX_TARGET_TEMPERATURE 80.0

#define PT100_NOMINAL_RESISTANCE 100.0
#define R_REF 430.0

#define CONFIG_FILE "config.json"
#define LOG_FILE "log.txt"

typedef struct {
    double target_temperature;
    double Kp;
    double Ki;
    double Kd;
} PIDParameters;

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static int pwm_duty = 0;
static int pwm_enabled = 0;
static double target_temperature = DEFAULT_TARGET_TEMPERATURE;
static double Kp = DEFAULT_Kp;
static double Ki = DEFAULT_Ki;
static double Kd = DEFAULT_Kd;

static void log_message(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp) {
        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, message);
        fclose(fp);
    }
    fprintf(stderr, "%s\n", message);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_config(const char *filename, PIDParameters *params) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        log_message("Error: Could not open config file");
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        char *key = strtok(line, ":");
        char *value = strtok(NULL, ":");
        if (!key || !value) continue;

        if (strcmp(key, "target_temperature") == 0) {
            params->target_temperature = atof(value);
        } else if (strcmp(key, "Kp") == 0) {
            params->Kp = atof(value);
        } else if (strcmp(key, "Ki") == 0) {
            params->Ki = atof(value);
        } else if (strcmp(key, "Kd") == 0) {
            params->Kd = atof(value);
        }
    }

    fclose(fp);
    return 0;
}

static int read_rtd_temperature(double *temperature) {
    unsigned char tx[4] = {0x00, 0x00, 0x00, 0x00};
    unsigned char rx[4] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 4,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .pad = 0
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        log_message("Error: SPI transfer failed");
        return -1;
    }

    if (rx[0] & 0x01) {
        log_message("Error: MAX31865 fault detected");
        return -1;
    }

    int16_t raw = (rx[1] << 8) | rx[2];
    *temperature = (raw * 0.25) / PT100_NOMINAL_RESISTANCE - 273.15;
    return 0;
}

static double calculate_pid(double current_temperature, double target_temperature, double *integral, double *previous_error, double dt) {
    double error = target_temperature - current_temperature;
    *integral += error * dt;
    double derivative = (error - *previous_error) / dt;
    double output = Kp * error + Ki * (*integral) + Kd * derivative;
    *previous_error = error;
    return output;
}

static void set_pwm_duty(double duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;

    if (duty_cycle != pwm_duty) {
        if (gpioPWM(PWM_GPIO, duty_cycle) == 0) {
            pwm_duty = duty_cycle;
            pwm_enabled = 1;
        } else {
            log_message("Error: Failed to set PWM duty cycle");
        }
    } else {
        pwm_enabled = 0;
    }
}

static void cleanup() {
    if (pwm_enabled) {
        set_pwm_duty(0);
        pwm_enabled = 0;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    gpioTerminate();
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error: Could not open SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        gpioTerminate();
        return 1;
    }

    unsigned char mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error: Could not set SPI mode: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    unsigned char bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error: Could not set SPI bits per word: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    unsigned int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error: Could not set SPI speed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    if (gpioSetMode(PWM_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Could not set GPIO %d as output\n", PWM_GPIO);
        cleanup();
        return 1;
    }

    if (gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: Could not set PWM frequency\n");
        cleanup();
        return 1;
    }

    if (gpioSetPWMrange(PWM_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: Could not set PWM range\n");
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (read_config(CONFIG_FILE, &PIDParameters) != 0) {
        target_temperature = DEFAULT_TARGET_TEMPERATURE;
        Kp = DEFAULT_Kp;
        Ki = DEFAULT_Ki;
        Kd = DEFAULT_Kd;
    }

    double integral = 0.0;
    double previous_error = 0.0;

    while (running) {
        double current_temperature;
        if (read_rtd_temperature(&current_temperature) != 0) {
            log_message("Error: Failed to read temperature from RTD");
            set_pwm_duty(0);
            break;
        }

        double pid_output = calculate_pid(current_temperature, target_temperature, &integral, &previous_error, 0.1);

        set_pwm_duty(pid_output);
        printf("Current Temperature: %.2f C, Target Temperature: %.2f C, PWM Duty: %.2f\n",
               current_temperature, target_temperature, pid_output);

        gpioDelay(100000);
    }

    cleanup();
    return 0;
}

