#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define BMP180_ADDR     0x77
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB    0xF6
#define BMP180_REG_LSB    0xF7
#define BMP180_REG_XLSB   0xF8
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1  0xB6
#define BMP180_REG_CAL_B2  0xB8
#define BMP180_REG_CAL_MB  0xBA
#define BMP180_REG_CAL_MC  0xBC
#define BMP180_REG_CAL_MD  0xBE

#define TEMP_THRESHOLD 30.0
#define PRESSURE_THRESHOLD 950.0
#define LOG_FILE "breach_log.txt"
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

typedef struct {
    int16_t  ac1, ac2, ac3, b1, b2, mb, mc, md;
    uint16_t ac4, ac5, ac6;
} bmp180_cal_t;

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != (ssize_t)len) return -1;
    return 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int read_calibration(int fd, bmp180_cal_t *cal) {
    uint8_t buf[22];
    if (i2c_read_reg(fd, BMP180_REG_CAL_AC1, buf, sizeof(buf)) != 0) return -1;
    cal->ac1 = (int16_t)((buf[0] << 8) | buf[1]);
    cal->ac2 = (int16_t)((buf[2] << 8) | buf[3]);
    cal->ac3 = (int16_t)((buf[4] << 8) | buf[5]);
    cal->ac4 = (uint16_t)((buf[6] << 8) | buf[7]);
    cal->ac5 = (uint16_t)((buf[8] << 8) | buf[9]);
    cal->ac6 = (uint16_t)((buf[10] << 8) | buf[11]);
    cal->b1  = (int16_t)((buf[12] << 8) | buf[13]);
    cal->b2  = (int16_t)((buf[14] << 8) | buf[15]);
    cal->mb  = (int16_t)((buf[16] << 8) | buf[17]);
    cal->mc  = (int16_t)((buf[18] << 8) | buf[19]);
    cal->md  = (int16_t)((buf[20] << 8) | buf[21]);
    return 0;
}

static int read_raw_temp(int fd, int32_t *ut) {
    if (i2c_write_reg(fd, BMP180_REG_CONTROL, 0x2E) != 0) return -1;
    usleep(5000);
    uint8_t buf[2];
    if (i2c_read_reg(fd, BMP180_REG_MSB, buf, 2) != 0) return -1;
    *ut = (int32_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_raw_pressure(int fd, int32_t *up) {
    if (i2c_write_reg(fd, BMP180_REG_CONTROL, 0x34) != 0) return -1;
    usleep(5000);
    uint8_t buf[3];
    if (i2c_read_reg(fd, BMP180_REG_MSB, buf, 3) != 0) return -1;
    *up = ((int32_t)(buf[0] << 16) | (buf[1] << 8) | buf[2]) >> 8;
    return 0;
}

static int32_t compute_b5(int32_t ut, const bmp180_cal_t *cal) {
    int32_t x1 = ((ut - (int32_t)cal->ac6) * (int32_t)cal->ac5) >> 15;
    int32_t x2 = ((int32_t)cal->mc << 11) / (x1 + (int32_t)cal->md);
    return x1 + x2;
}

static double compute_temperature(int32_t ut, const bmp180_cal_t *cal) {
    int32_t b5 = compute_b5(ut, cal);
    return ((b5 + 8) >> 4) / 10.0;
}

static double compute_pressure(int32_t up, int32_t ut, const bmp180_cal_t *cal) {
    int32_t b5 = compute_b5(ut, cal);
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)cal->b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x2 = ((int32_t)cal->ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((int32_t)cal->ac1 * 4 + x3) << 2) / 4;
    x1 = ((int32_t)cal->ac3 * b6) >> 13;
    x2 = ((int32_t)cal->b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)cal->ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> 3);
    int32_t p;
    if (b7 < 0x80000000) p = (b7 * 2) / b4;
    else p = (b7 / b4) * 2;
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p += (x1 + x2 + 3791) >> 4;
    return (double)p;
}

static int log_breach(double temp, double pressure) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) { perror("fopen"); return -1; }
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, temp, pressure);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) { perror("open i2c"); return 1; }
    if (ioctl(fd, I2C_SLAVE, BMP180_ADDR) < 0) {
        perror("ioctl I2C_SLAVE"); close(fd); return 1;
    }

    bmp180_cal_t cal;
    if (read_calibration(fd, &cal) != 0) {
        fprintf(stderr, "Failed to read BMP180 calibration data\n");
        close(fd); return 1;
    }

    printf("BMP180 monitoring started. Thresholds: Temp=%.1fC, Pressure=%.1fPa\n",
           TEMP_THRESHOLD, PRESSURE_THRESHOLD);

    while (running) {
        int32_t ut, up;
        int ok = 0;
        for (int r = 0; r < MAX_RETRIES && running; r++) {
            if (read_raw_temp(fd, &ut) == 0 && read_raw_pressure(fd, &up) == 0) {
                ok = 1;
                break;
            }
            fprintf(stderr, "I2C read error (attempt %d/%d)\n", r + 1, MAX_RETRIES);
            usleep(100000);
        }
        if (!ok) {
            fprintf(stderr, "Persistent I2C error, continuing\n");
            sleep(1);
            continue;
        }

        double temp = compute_temperature(ut, &cal);
        double press = compute_pressure(up, ut, &cal);

        if (temp > TEMP_THRESHOLD || press < PRESSURE_THRESHOLD) {
            printf("Breach: Temp=%.2fC, Pressure=%.2fPa\n", temp, press);
            if (log_breach(temp, press) != 0) {
                fprintf(stderr, "Failed to log breach\n");
            }
        }

        sleep(1);
    }

    printf("\nShutting down cleanly...\n");
    close(fd);
    return 0;
}

