#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BMP180_ADDR             0x77
#define BMP180_REG_CONTROL      0xF4
#define BMP180_REG_MSB          0xF6
#define BMP180_REG_CAL_START    0xAA
#define BMP180_CAL_LEN          22
#define BMP180_CMD_TEMP         0x2E
#define BMP180_CMD_PRESSURE_OSS0 0x34
#define FAN_GPIO                18
#define TEMP_THRESHOLD           30.0f
#define BUFFER_SIZE              60
#define SAMPLE_INTERVAL_US       500000
#define OSS                      0

typedef struct {
    int16_t  ac1, ac2, ac3, b1, b2, mb, mc, md;
    uint16_t ac4, ac5, ac6;
} bmp180_cal_t;

typedef struct {
    time_t timestamp;
    float  temperature;
    float  pressure;
} sensor_data_t;

static volatile sig_atomic_t g_running = 1;
static volatile sig_atomic_t g_fan_state = 0;
static int g_i2c_handle = -1;
static bmp180_cal_t g_cal;
static sensor_data_t g_buffer[BUFFER_SIZE];
static int g_buf_head = 0;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_calibration(int handle, bmp180_cal_t *cal) {
    uint8_t data[BMP180_CAL_LEN];
    if (i2cReadI2CBlockData(handle, BMP180_REG_CAL_START, (char *)data, BMP180_CAL_LEN) != BMP180_CAL_LEN) {
        fprintf(stderr, "Error: failed to read BMP180 calibration data\n");
        return -1;
    }
    cal->ac1 = (int16_t)((data[0]  << 8) | data[1]);
