/*
 * MAX31855 thermocouple heater controller for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   MAX31855 CS  -> GPIO8  (SPI0 CE0)
 *   MAX31855 SCLK-> GPIO11 (SPI0 SCLK)
 *   MAX31855 MISO-> GPIO9  (SPI0 MISO)
 *   MAX31855 SO   -> GPIO10 (SPI0 MOSI)
 *   MAX31855 VCC  -> 3.3 V
 *   MAX31855 GND  -> GND
 *   MAX31855 CLK  -> 3.3 V (internal oscillator)
 *   SSR control    -> GPIO17 (drives PWM-capable pin)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o heater_control heater_control.c -lpigpio -lrt
 * Run:
 *   sudo ./heater_control
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL    0          /* SPI0 CE0 (GPIO8)                    */
#define SPI_SPEED      2000000    /* 2 MHz                              */
#define SPI_FLAGS      0          /* Mode 0, active-low CE               */
#define HEATER_GPIO    17         /* GPIO17 – PWM-capable pin            */
#define PWM_RANGE      100        /* 0–100 % duty-cycle range            */
#define PWM_FREQ       1000       /* 1 kHz – typical for SSR drivers     */
#define TARGET_TEMP    25.0       /* °C                                   */
#define MAX_DUTY       80.0       /* % – safe maximum for SSR           */
#define LOG_FILE       "heater_log.csv"
#define SAMPLE_PERIOD  1.0        /* seconds between samples            */
#define MAX_SPI_RETRIES 3

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;
static int g_spi_handle = -1;

/* --------------------------- Function prototypes -------------------------- */
static int  read_max31855(int spi_handle, float *temperature);
static void set_heater_pwm(int gpio, float duty_cycle);
static void log_data(float temperature, float duty_cycle);
static void signal_handler(int sig);
static void cleanup(void);

/* ------------------------------- MAX31855 --------------------------------- */
/*
 * Read one 32-bit sample from the MAX31855.
 * Returns 0 on success and stores temperature in *temperature.
 * Returns -1 on SPI error or MAX31855 fault.
 */
static int read_max31855(int spi_handle, float *temperature)
{
    char tx[4] = {0, 0, 0, 0};
    char rx[4] = {0, 0, 0, 0};
    int  ret;
    int  raw;
    uint32_t val;

    for (int attempt = 0; attempt < MAX_SPI_RETRIES; ++attempt) {
        /* Select the device (active-low CE) */
        ret = spiXfer(spi_handle, tx, rx, 4);
        if (ret != 4) {
            fprintf(stderr, "[SPI] transfer failed (attempt %d/%d): %s\n",
                    attempt + 1, MAX_SPI_RETRIES, strerror(errno));
            gpioDelay(1000);
            continue;
        }

        /* Assemble 32-bit big-endian value */
        raw = ((uint32_t)(uint8_t)rx[0] << 24) |
              ((uint32_t)(uint8_t)rx[1] << 16) |
              ((uint32_t)(uint8_t)rx[2] <<  8) |
              ((uint32_t)(uint8_t)rx[3]);

        /* Fault bit (D16) – set when any fault condition exists */
        if (raw & 0x00010000) {
            fprintf(stderr, "[MAX31855] fault detected (raw=0x%08X): ",
                    raw);
            if (raw & 0x00000001) fprintf(stderr, "open circuit ");
            if (raw & 0x00000002) fprintf(stderr, "short to GND ");
            if (raw & 0x00000004) fprintf(stderr, "short to VCC ");
            fprintf(stderr, "\n");
            return -1;
        }

        /* Thermocouple temperature: bits 18..4, 14-bit signed, 0.25 °C / LSB */
        *temperature = (float)((raw >> 4) & 0x0FFF) / 16.0f;
        return 0;
    }

    fprintf(stderr, "[MAX31855] read failed after %d attempts\n", MAX_SPI_RETRIES);
    return -1;
}

/* ------------------------------ Heater ------------------------------------ */
static void set_heater_pwm(int gpio, float duty_cycle)
{
    if (duty_cycle < 0.0f)   duty_cycle = 0.0f;
    if (duty_cycle > 100.0f) duty_cycle = 100.0f;

    int pwm_value = (int)(duty_cycle * (float)PWM_RANGE / 100.0f);
    if (gpioPWM(gpio, pwm_value) < 0) {
        fprintf(stderr, "[PWM] gpioPWM failed on GPIO %d\n", gpio);
    }
}

/* ------------------------------ Logging ----------------------------------- */
static void log_data(float temperature, float duty_cycle)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t == NULL) {
        fprintf(stderr, "[LOG] localtime_r failed: %s\n", strerror(errno));
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);

    if (fprintf(g_log, "%s,%.2f,%.2f\n", ts, temperature, duty_cycle) < 0) {
        fprintf(stderr, "[LOG] fprintf failed: %s\n", strerror(errno));
        return;
    }
    if (fflush(g_log) != 0) {
        fprintf(stderr, "[LOG] fflush failed: %s\n", strerror(errno));
    }
}

/* ------------------------------- Signal ----------------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------ Cleanup ----------------------------------- */
static void cleanup(void)
{
    /* Ensure heater is off */
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    if (g_log != NULL) {
        fclose(g_log);
        g_log = NULL;
    }
    gpioTerminate();
}

/* --------------------------------- Main ----------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure heater GPIO for PWM */
    if (gpioSetMode(HEATER_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "[FATAL] gpioSetMode failed for GPIO %d\n", HEATER_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(HEATER_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "[FATAL] gpioSetPWMrange failed for GPIO %d\n", HEATER_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQ) < 0) {
        fprintf(stderr, "[FATAL] gpioSetPWMfrequency failed for GPIO %d\n", HEATER_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open SPI0 CE0 at 2 MHz, mode 0 */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "[FATAL] spiOpen failed (channel %d, %d Hz): %s\n",
                SPI_CHANNEL, SPI_SPEED, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log = fopen(LOG_FILE, "a");
    if (g_log == NULL) {
        fprintf(stderr, "[FATAL] Cannot open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log) == 0) {
        fprintf(g_log, "timestamp,temperature_c,duty_cycle_pct\n");
        fflush(g_log);
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGINT) failed: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGTERM) failed: %s\n", strerror(errno));
    }

    /* Main control loop */
    float integral = 0.0f;
    float previous_error = 0.0f;
    bool first_sample = true;

    while (g_running) {
        float temperature = 0.0f;
        int  spi_ok = 0;

        /* Read thermocouple with retries */
        for (int attempt = 0; attempt < MAX_SPI_RETRIES && g_running; ++attempt) {
            if (read_max31855(g_spi_handle, &temperature) == 0) {
                spi_ok = 1;
                break;
            }
            gpioDelay(100000); /* 100 ms back-off */
        }

        if (!spi_ok) {
            fprintf(stderr, "[ERROR] MAX31855 read failed – heater off, retrying next cycle\n");
            set_heater_pwm(HEATER_GPIO, 0.0f);
            log_data(0.0f, 0.0f);
            sleep(SAMPLE_PERIOD);
            continue;
        }

        /* PI controller with anti-windup */
        float error = TARGET_TEMP - temperature;
        integral += error;

        if (first_sample || previous_error == 0.0f) {
            /* Avoid windup on first sample */
            float new_duty = (int)(integral + 0.5f * error);
            if (new_duty < 0.0f)   new_duty = 0.0f;
            if (new_duty > MAX_DUTY) new_duty = MAX_DUTY;
            set_heater_pwm(HEATER_GPIO, new_duty);
            integral = new_duty;
            first_sample = false;
        } else {
            /* Anti-windup clamp */
            float new_duty = (int)(integral + 0.5f * error);
            if (new_duty < 0.0f)   new_duty = 0.0f;
            if (new_duty > MAX_DUTY) new_duty = MAX_DUTY;
            set_heater_pwm(HEATER_GPIO, new_duty);
            integral = new_duty;
        }

        log_data(temperature, (float)gpioGetPWMdutycycle(HEATER_GPIO) / (float)PWM_RANGE);
        sleep(SAMPLE_PERIOD);
    }

    /* Graceful shutdown */
    cleanup();
    return EXIT_SUCCESS;
}

