    if (fprintf(g_log, "%s,%.2f,%.2f\n", ts, temperature, duty_cycle) < 0) {
        fprintf(stderr, "[LOG] fprintf failed: %s\n", strerror(errno));
        return;
    }
    if (fflush(g_log) != 0) {
        fprintf(stderr, "[LOG] fflush failed: %s\n", strerror(errno));
    }
}

/* ------------------------------- Signal ----------------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------ Cleanup ----------------------------------- */
static void cleanup(void)
{
    /* Ensure heater is off */
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    if (g_log != NULL) {
        fclose(g_log);
        g_log = NULL;
    }
    gpioTerminate();
}

/* --------------------------------- Main ----------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure heater GPIO for PWM */
    if (gpioSetMode(HEATER_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "[FATAL] gpioSetMode failed for GPIO %d\n", HEATER_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(HEATER_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "[FATAL] gpioSetPWMrange failed for GPIO %d\n", HEATER_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQ) < 0) {
        fprintf(stderr, "[FATAL] gpioSetPWMfrequency failed for GPIO %d\n", HEATER_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open SPI0 CE0 at 2 MHz, mode 0 */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "[FATAL] spiOpen failed (channel %d, %d Hz): %s\n",
                SPI_CHANNEL, SPI_SPEED, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log = fopen(LOG_FILE, "a");
    if (g_log == NULL) {
        fprintf(stderr, "[FATAL] Cannot open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log) == 0) {
        fprintf(g_log, "timestamp,temperature_c,duty_cycle_pct\n");
        fflush(g_log);
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGINT) failed: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGTERM) failed: %s\n", strerror(errno));
    }

    /* Main control loop */
    float integral = 0.0f;
    float previous_error = 0.0f;
    bool first_sample = true;

    while (g_running) {
        float temperature = 0.0f;
        int  spi_ok = 0;

        /* Read thermocouple with retries */
        for (int attempt = 0; attempt < MAX_SPI_RETRIES && g_running; ++attempt) {
            if (read_max31855(g_spi_handle, &temperature) == 0) {
                spi_ok = 1;
                break;
            }
            gpioDelay(100000); /* 100 ms back-off */
        }

        if (!spi_ok) {
            fprintf(stderr, "[ERROR] MAX31855 read failed – heater off, retrying next cycle\n");
            set_heater_pwm(HEATER_GPIO, 0.0f);
            log_data(0.0f, 0.0f);
            sleep(SAMPLE_PERIOD);
            continue;
        }

        /* PI controller with anti-windup */
        float error = TARGET_TEMP - temperature;
        integral += error;

        if (first_sample || previous_error == 0.0f) {
            /* Avoid windup on first sample */
            float new_duty = (int)(integral + 0.5f * error);
            if (new_duty < 0.0f)   new_duty = 0.0f;
            if (new_duty > MAX_DUTY) new_duty = MAX_DUTY;
            set_heater_pwm(HEATER_GPIO, new_duty);
            integral = new_duty;
            first_sample = false;
        } else {
            /* Anti-windup clamp */
            float new_duty = (int)(integral + 0.5f * error);
            if (new_duty < 0.0f)   new_duty = 0.0f;
            if (new_duty > MAX_DUTY) new_duty = MAX_DUTY;
            set_heater_pwm(HEATER_GPIO, new_duty);
            integral = new_duty;
        }

        log_data(temperature, (float)gpioGetPWMdutycycle(HEATER_GPIO) / (float)PWM_RANGE);
        sleep(SAMPLE_PERIOD);
    }

    /* Graceful shutdown */
    cleanup();
    return EXIT_SUCCESS;
}

