#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

#define TEMP_FILE "cpu_temp.txt"
#define POLL_DELAY_US 500000
#define PWM_RANGE 255

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int set_pwm_channel(int pin, int duty)
{
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;

    if (gpioPWM(pin, duty) != 0) {
        fprintf(stderr, "Error: gpioPWM(%d, %d) failed\n", pin, duty);
        return -1;
    }
    return 0;
}

static int read_cpu_temp(int *temp_out)
{
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        perror("Error opening temperature file");
        return -1;
    }

    char buffer[32];
    size_t n = fread(buffer, 1, sizeof(buffer) - 1, fp);
    if (ferror(fp)) {
        perror("Error reading temperature file");
        fclose(fp);
        return -1;
    }
    buffer[n] = '\0';

    char *endptr;
    long millideg = strtol(buffer, &endptr, 10);
    if (endptr == buffer) {
        fprintf(stderr, "Error: temperature string is empty\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    if (millideg < 0 || millideg > 60000000) {
        fprintf(stderr, "Error: temperature out of range (%ld m°C)\n", millideg);
        return -1;
    }

    *temp_out = (int)millideg;
    return 0;
}

static void set_led_color(int red, int green, int blue)
{
    if (set_pwm_channel(RED_PIN, red) != 0) return;
    if (set_pwm_channel(GREEN_PIN, green) != 0) return;
    if (set_pwm_channel(BLUE_PIN, blue) != 0) return;
}

static void turn_off_all_channels(void)
{
    set_pwm_channel(RED_PIN, 255);
    set_pwm_channel(GREEN_PIN, 255);
    set_pwm_channel(BLUE_PIN, 255);
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RED_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(BLUE_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(RED_PIN, 1000) != 0 ||
        gpioSetPWMfrequency(GREEN_PIN, 1000) != 0 ||
        gpioSetPWMfrequency(BLUE_PIN, 1000) != 0) {
        fprintf(stderr, "Error: failed to set PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error: sigaction failed");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("CPU Temperature Monitor started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int cpu_temp;
        if (read_cpu_temp(&cpu_temp) != 0) {
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        int red, green, blue;
        if (cpu_temp < 40000) {
            red = 0;
            green = 0;
            blue = 255;
        } else if (cpu_temp < 60000) {
            red = 0;
            green = 255;
            blue = 0;
        } else {
            red = 255;
            green = 0;
            blue = 0;
        }

        set_led_color(red, green, blue);
        printf("CPU: %d m°C | R:%d G:%d B:%d\n", cpu_temp, red, green, blue);

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    turn_off_all_channels();
    gpioTerminate();
    return EXIT_SUCCESS;
}

