#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define DHT22_PIN 4
#define SERVER_URL "http://yourserver.com/api/humidity"
#define MAX_RETRIES 3
#define READ_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_dht22(int pin, float *temperature, float *humidity) {
    int data[40] = {0};
    int bit_idx = 0;
    int byte_idx = 0;
    int last_state = 1;
    int counter = 0;
    int timeout = 0;

    gpioSetMode(pin, PI_OUTPUT);
    gpioWrite(pin, 0);
    gpioDelay(2000);
    gpioWrite(pin, 1);
    gpioDelay(30);

    gpioSetMode(pin, PI_INPUT);
    gpioSetPullUpDown(pin, PI_PUD_UP);

    for (int i = 0; i < 85; i++) {
        counter = 0;
        while (gpioRead(pin) == last_state) {
            counter++;
            gpioDelay(1);
            if (counter == 255) break;
        }
        last_state = gpioRead(pin);

        if (counter == 255) {
            timeout++;
            if (timeout > 100) return -1;
            continue;
        }

        if (i > 0 && (i % 2 == 0)) {
            data[bit_idx / 8] <<= 1;
            if (counter > 16) data[bit_idx / 8] |= 1;
            bit_idx++;
            if (bit_idx % 8 == 0) byte_idx++;
        }

        if (bit_idx % 8 == 0 && byte_idx < 40) {
            data[byte_idx] = data[byte_idx] + ((i % 2 == 0) ? 1 : 0);
        }
    }

    if (bit_idx < 40) return -1;

    int checksum = data[0] + data[1] + data[2] + data[3] +
                    data[4] + data[5] + data[6] + data[7];

    if (checksum != data[38]) return -2;

    *humidity = (float)((data[2] << 8) | data[1]) / 10.0;
    *temperature = (float)(((data[3] << 8) | data[4]) / 10.0);

    if (data[3] & 0x08) *temperature = -*temperature;

    return 0;
}

static int send_http_request(const char *url, const char *json_data) {
    int sockfd = -1;
    struct sockaddr_in servaddr;
    char buffer[1024] = {0};
    socklen_t addrlen = sizeof(servaddr);

    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        perror("socket failed");
        return -1;
    }

    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(80);

    if (inet_pton(AF_INET, "127.0.0.1", &servaddr.sin_addr) <= 0) {
        perror("inet_pton failed");
        close(sockfd);
        return -1;
    }

    if (connect(sockfd, (struct sockaddr *)&servaddr, addrlen) < 0) {
        perror("connect failed");
        close(sockfd);
        return -1;
    }

    if (send(sockfd, json_data, strlen(json_data), 0) < 0) {
        perror("send failed");
        close(sockfd);
        return -1;
    }

    close(sockfd);
    return 0;
}

int main(void) {
    float temperature, humidity;
    char json_data[128];
    int retry_count = 0;
    int exit_code = 0;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    while (running) {
        retry_count = 0;
        int success = 0;

        while (retry_count < MAX_RETRIES && running) {
            if (read_dht22(DHT22_PIN, &temperature, &humidity) == 0) {
                success = 1;
                break;
            }
            retry_count++;
            if (retry_count < MAX_RETRIES) {
                fprintf(stderr, "DHT22 read failed (attempt %d/%d)\n", retry_count, MAX_RETRIES);
                gpioDelay(2000000);
            }
        }

        if (success) {
            snprintf(json_data, sizeof(json_data), "{\"temperature\":%.1f,\"humidity\":%.1f}", temperature, humidity);
            retry_count = 0;
            while (retry_count < MAX_RETRIES && running) {
                if (send_http_request(SERVER_URL, json_data) == 0) {
                    retry_count++;
                    break;
                }
                fprintf(stderr, "HTTP request failed (attempt %d/%d)\n", retry_count, MAX_RETRIES);
                retry_count++;
                if (retry_count < MAX_RETRIES) {
                    gpioDelay(1000000);
                }
            }
        } else {
            fprintf(stderr, "DHT22 sensor not responding or invalid data\n");
        }

        if (running) {
            sleep(READ_INTERVAL_SEC);
        }
    }

    gpioTerminate();
    return exit_code;
}

