#define BMP180_REG_CONTROL      0xF4
#define BMP180_REG_MSB          0xF6
#define BMP180_REG_LSB          0xF7
#define BMP180_REG_XLSB         0xF8
#define BMP180_REG_CAL_START    0xAA
#define BMP180_REG_CAL_END      0xAB
#define BMP180_OSS               3
#define BMP180_TEMP_WAIT_US     4500
#define BMP180_PRESS_WAIT_US    26000
#define DEBOUNCE_US             200000
#define LOG_INTERVAL_S           2
#define LOG_FILE                "pressure_log.txt"

static volatile sig_atomic_t g_running = 1;
static volatile sig_atomic_t g_logging_enabled = 0;
static volatile uint32_t     g_last_interrupt_tick = 0;
static int                   g_i2c_handle = -1;

typedef struct {
    int16_t  ac1, ac2, ac3, b1, b2, mb, mc, md;
    uint16_t ac4, ac5, ac6;
} bmp180_cal_t;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    if (i2cWriteByte(handle, reg) < 0) return -1;
    if (i2cReadDevice(handle, (char *)buf, len) != (int)len) return -1;
    return 0;
}

static int i2c_write_reg(int handle, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (i2cWriteDevice(handle, (char *)buf, 2) != 2) return -1;
    return 0;
}

static int read_calibration(int handle, bmp180_cal_t *cal) {
    uint8_t buf[22];
    if (i2c_read_reg(handle, BMP180_REG_CAL_START, buf, sizeof(buf)) != 0) return -1;
    cal->ac1 = (int16_t)((buf[0]  << 8) | buf[1]);
    cal->ac2 = (int16_t)((buf[2]  << 8) | buf[3]);
    cal->ac3 = (int16_t)((buf[4]  << 8) | buf[5]);
    cal->ac4 = (uint16_t)((buf[6]  << 8) | buf[7]);
    cal->ac5 = (uint16_t)((buf[8]  << 8) | buf[9]);
    cal->ac6 = (uint16_t)((buf[10] << 8) | buf[11]);
    cal->b1  = (int16_t)((buf[12] << 8) | buf[13]);
    cal->b2  = (int16_t)((buf[14] << 8) | buf[15]);
    cal->mb  = (int16_t)((buf[16] << 8) | buf[17]);
    cal->mc  = (int16_t)((buf[18] << 8) | buf[19]);
    cal->md  = (int16_t)((buf[20] << 8) | buf[21]);
    return 0;
}

static int read_raw_temp(int handle, int32_t *raw) {
    if (i2c_write_reg(handle, BMP180_REG_CONTROL, 0x2E) != 0) return -1;
    gpioDelay(BMP180_TEMP_WAIT_US);
    uint8_t buf[2];
    if (i2c_read_reg(handle, BMP180_REG_MSB, buf, 2) != 0) return -1;
    *raw = (int32_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_raw_pressure(int handle, int32_t *raw) {
    if (i2c_write_reg(handle, BMP180_REG_CONTROL, 0x34 + (BMP180_OSS << 6)) != 0) return -1;
    gpioDelay(BMP180_PRESS_WAIT_US);
    uint8_t buf[3];
    if (i2c_read_reg(handle, BMP180_REG_MSB, buf, 3) != 0) return -1;
    *raw = ((int32_t)buf[0] << 16 | (int32_t)buf[1] << 8 | (int32_t)buf[2]) >> (8 - BMP180_OSS);
    return 0;
}

static int32_t compute_b5(int32_t ut, const bmp180_cal_t *cal) {
    int32_t x1 = ((ut - (int32_t)cal->ac6) * (int32_t)cal->ac5) >> 15;
    int32_t x2 = ((int32_t)cal->mc << 11) / (x1 + (int32_t)cal->md);
    return x1 + x2;
}

static int32_t compute_pressure(int32_t up, int32_t b5, const bmp180_cal_t *cal) {
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)cal->b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x2 = ((int32_t)cal->ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)cal->ac1 * 4 + x3) << BMP180_OSS) + 2) >> 2);
    x1 = ((int32_t)cal->ac3 * b6) >> 13;
    x2 = ((int32_t)cal->b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)cal->ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> BMP180_OSS);
    int32_t p;
    if (b7 < 0x80000000UL) p = (b7 * 2) / b4;
    else                  p = (b7 / b4) * 2;
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);
    return p / 100.0;
}

static void interrupt_handler(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)level; (void)userdata;
    if (tick - g_last_interrupt_tick > DEBOUNCE_US) {
        g_last_interrupt_tick = tick;
        g_logging_enabled = !g_logging_enabled;
        printf("Logging %s\n", g_logging_enabled ? "enabled" : "disabled");
    }
}

static int log_pressure(double pressure) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) { perror("fopen"); return -1; }
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, %.2f hPa\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, pressure);
    fclose(fp);
    printf("Pressure logged: %.2f hPa\n", pressure);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) { fprintf(stderr, "pigpio init failed\n"); return 1; }

    g_i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (g_i2c_handle < 0) { fprintf(stderr, "i2cOpen failed: %d\n", g_i2c_handle); gpioTerminate(); return 1; }

    bmp180_cal_t cal;
    if (read_calibration(g_i2c_handle, &cal) != 0) {
        fprintf(stderr, "Failed to read BMP180 calibration data\n");
        i2cClose(g_i2c_handle); gpioTerminate(); return 1;
    }

    if (gpioSetMode(4, PI_INPUT) != 0) { fprintf(stderr, "gpioSetMode failed\n"); i2cClose(g_i2c_handle); gpioTerminate(); return 1; }
    if (gpioSetPullUpDown(4, PI_PUD_UP) != 0) { fprintf(stderr, "gpioSetPullUpDown failed\n"); i2cClose(g_i2c_handle); gpioTerminate(); return 1; }
    if (gpioSetAlertFuncEx(4, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "gpioSetAlertFuncEx failed\n");
        i2cClose(g_i2c_handle); gpioTerminate(); return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("BMP180 pressure logger started. Press button on GPIO 4 to toggle logging.\n");

    while (g_running) {
        if (g_logging_enabled) {
            int32_t ut, up;
            if (read_raw_temp(g_i2c_handle, &ut) != 0) {
                fprintf(stderr, "Temperature read error\n");
            } else if (read_raw_pressure(g_i2c_handle, &up) != 0) {
                fprintf(stderr, "Pressure read error\n");
            } else {
                int32_t b5 = compute_b5(ut, &cal);
                double pressure = compute_pressure(up, b5, &cal);
                log_pressure(pressure);
            }
        }
        gpioDelay(LOG_INTERVAL_S * 1000000);
    }

    printf("\nShutting down...\n");
    gpioSetAlertFuncEx(4, NULL, NULL);
    i2cClose(g_i2c_handle);
    gpioTerminate();
    return 0;
}

