/*
 * Raspberry Pi 5 Active Cooler Fan Controller
 *
 * Reads CPU temperature from /sys/class/thermal/thermal_zone0/temp
 * Reads cooling-device state from /sys/class/thermal/cooling_device0/cur_state
 * Applies a tiered fan-speed map and logs speed changes to /var/log/fan_control.log
 *
 * Build:  gcc -O2 -Wall -Wextra -o fan_control fan_control.c
 * Run:    sudo ./fan_control   (root needed for sysfs writes)
 */

#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <signal.h>
#include <stdarg.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#include <sys/stat.h>
#include <sys/types.h>

/* ----------------------------- Configuration ----------------------------- */
#define TEMP_FILE          "/sys/class/thermal/thermal_zone0/temp"
#define COOLING_DEV_FILE   "/sys/class/thermal/cooling_device0/cur_state"
#define LOG_FILE           "/var/log/fan_control.log"
#define POLL_INTERVAL_SEC  5
#define MAX_FAN_SPEED      3
#define TEMP_THRESHOLD_0   45   /* off  */
#define TEMP_THRESHOLD_1   55   /* speed 1 */
#define TEMP_THRESHOLD_2   65   /* speed 2 (max) */
#define COOLING_DEV_MAX    3

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;

/* --------------------------- Signal handling ------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

/* --------------------------- Logging ------------------------------------- */
static void log_message(const char *fmt, ...)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "log_open: %s\n", strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] ",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec);
    }

    va_list ap;
    va_start(ap, fmt);
    vfprintf(fp, fmt, ap);
    va_end(ap);

    fputc('\n', fp);
    fclose(fp);
}

/* --------------------------- Cooling-device helpers ----------------------- */
static int cooling_device_max_state(void)
{
    int fd = open(COOLING_DEV_FILE, O_RDONLY);
    if (fd < 0) {
        log_message("open cooling_device: %s", strerror(errno));
        return -1;
    }

    char buf[16];
    ssize_t n = read(fd, buf, sizeof(buf) - 1);
    close(fd);
    if (n <= 0) {
        log_message("read cooling_device: %s", strerror(errno));
        return -1;
    }
    buf[n] = '\0';

    /* Expected format: "state=N" where N is 0..MAX_FAN_SPEED */
    char *p = strstr(buf, "state=");
    if (!p) {
        log_message("missing state= in cooling_device");
        return -1;
    }
    p += 5;
    int val = atoi(p);
    if (val < 0 || val > COOLING_DEV_MAX) {
        log_message("invalid cooling_device state %d", val);
        return -1;
    }
    return val;
}

static int cooling_device_set_state(int state)
{
    if (state < 0 || state > COOLING_DEV_MAX) {
        log_message("invalid fan speed %d", state);
        return -1;
    }

    int fd = open(COOLING_DEV_FILE, O_WRONLY);
    if (fd < 0) {
        log_message("open cooling_device (write): %s", strerror(errno));
        return -1;
    }

    char buf[16];
    int len = snprintf(buf, sizeof(buf), "state=%d", state);
    if (write(fd, buf, (size_t)len) != len) {
        log_message("write cooling_device: %s", strerror(errno));
        close(fd);
        return -1;
    }

    if (close(fd) < 0) {
        log_message("close cooling_device: %s", strerror(errno));
        return -1;
    }
    return 0;
}

/* --------------------------- Temperature --------------------------------- */
static int read_cpu_temp(void)
{
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        log_message("open temp: %s", strerror(errno));
        return -1;
    }

    int millideg;
    if (fscanf(fp, "%d", &millideg) != 1) {
        log_message("parse temp: %s", strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);

    /* 1000 mK per degree Celsius */
    return millideg / 1000;
}

/* --------------------------- Fan speed map ------------------------------- */
static int fan_speed_map(int temp_c)
{
    if (temp_c < TEMP_THRESHOLD_0) return 0;
    if (temp_c < TEMP_THRESHOLD_1) return 1;
    if (temp_c < TEMP_THRESHOLD_2) return 2;
    return MAX_FAN_SPEED;
}

/* --------------------------- Main ----------------------------------------- */
int main(void)
{
    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Cooling-device max state */
    int cur = cooling_device_max_state();
    if (cur < 0) {
        log_message("initial cooling_device_max_state failed");
        return EXIT_FAILURE;
    }

    /* Log startup */
    log_message("Fan controller started (cooling_device=%d)", cur);

    int last_state = -1;

    while (g_running) {
        int temp = read_cpu_temp();
        if (temp < 0) {
            log_message("temp read failed; retrying next cycle");
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        int speed = fan_speed_map((int)temp);

        if (speed != last_state) {
            if (cooling_device_set_state(speed) < 0) {
                log_message("set cooling_device failed");
            } else {
                log_message("Fan speed set to %d", speed);
                last_state = speed;
            }
        }

        sleep(POLL_INTERVAL_SEC);
    }

    /* --------------------------- Graceful shutdown ----------------------- */
    log_message("Fan controller shutting down");
    cooling_device_set_state(0);
    log_message("Fan controller stopped (state=0)");
    return EXIT_SUCCESS;
}

