/*
 * Raspberry Pi Zero W – PID-controlled resistive heater via MAX31855
 *
 * Hardware:
 *   - MAX31855 on SPI0: CLK=GPIO11, CS=GPIO8/CE0, DO=GPIO9
 *   - Heater PWM on GPIO18 (hardware PWM, 1 kHz, 0–100 %)
 *
 * Build:
 *   gcc -O2 -Wall -o heater_pid heater_pid.c -lm
 *
 * Run:
 *   ./heater_pid
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define HEATER_GPIO          18
#define PWM_FREQUENCY        1000          /* Hz */
#define PWM_RANGE            100           /* 0–100 % */
#define SPI_DEVICE           "/dev/spidev0.0"
#define SPI_SPEED_HZ         500000        /* 500 kHz */
#define SPI_BITS_PER_WORD    8
#define LOG_FILE             "heater_log.txt"
#define SAMPLE_INTERVAL_S    1
#define MAX_RETRIES          3
#define MAX_TEMP             100.0f
#define MIN_TEMP             0.0f
#define TARGET_TEMP          50.0f

/* PID gains */
#define KP  1.0f
#define KI  0.1f
#define KD  0.01f

/* MAX31855 fault bits (D2..D0 of the 32-bit read) */
#define FAULT_OPEN_CIRCUIT  0x01
#define FAULT_SHORT_GND    0x02
#define FAULT_SHORT_VCC    0x04

typedef struct {
    float Kp;
    float Ki;
    float Kd;
    float integral;
    float previous_error;
} PIDController;

static volatile sig_atomic_t g_running = 1;
static int  g_spi_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void log_error(const char *msg)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];
    localtime_r(&t, &tm);
    strftime(ts, sizeof ts, "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(stderr, "[%s] ERROR: %s (errno %d: %s)\n",
            ts, msg, errno, strerror(errno));
}

/* ------------------------------------------------------------------ */
/* MAX31855 32-bit read: [D31..D18] thermocouple temp (14-bit signed),
 *                  [D17] reserved, [D16] fault, [D15..D4] internal
 *                  (14-bit signed), [D3] reserved, [D2..D0] fault bits. */
static int read_max31855(int fd, float *temp_out)
{
    uint8_t rx[4] = {0};
    struct spi_ioc_transfer tr = {
        .tx_buf        = 0,
        .rx_buf        = (unsigned long)rx,
        .len           = 4,
        .speed_hz      = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs   = 0,
        .cs_change     = 0,
    };

    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
            log_error("SPI transfer failed");
            usleep(10000);
            continue;
        }

        uint32_t raw = ((uint32_t)rx[0] << 24) |
                       ((uint32_t)rx[1] << 16) |
                       ((uint32_t)rx[2] <<  8) |
                       ((uint32_t)rx[3]);

        if (raw & 0x00010000) {                 /* bit 16 = fault */
            uint8_t faults = (raw >> 2) & 0x07; /* D2..D0 */
            if (faults & FAULT_OPEN_CIRCUIT)    log_error("MAX31855: open circuit");
            if (faults & FAULT_SHORT_GND)      log_error("MAX31855: short to GND");
            if (faults & FAULT_SHORT_VCC)      log_error("MAX31855: short to VCC");
            return -1;
        }

        /* Thermocouple temperature: bits 31..18, 14-bit signed */
        int16_t tc_raw = (int16_t)((raw >> 18) & 0x3FFF);
        if (tc_raw & 0x2000) tc_raw |= 0xC000;   /* sign-extend */

        *temp_out = (float)tc_raw / 256.0f;
        return 0;
    }

    return -1;
}

/* ------------------------------------------------------------------ */
static void set_heater_pwm(int duty)
{
    if (duty < 0)   duty = 0;
    if (duty > 100) duty = 100;

    int pwm_value = (duty * PWM_RANGE) / 100;
    if (gpioPWM(HEATER_GPIO, pwm_value) < 0)
        log_error("gpioPWM failed");
}

/* ------------------------------------------------------------------ */
static void pid_update(PIDController *pid, float current,
                       float target, float *integral_out,
                       float *prev_error_out)
{
    float error = target - current;
    *integral_out += error;
    float deriv = error - *prev_error_out;
    *prev_error_out = error;

    float output = (KP * error) + (KI * (*integral_out)) + (KD * deriv);
    if (output < 0.0f)   output = 0.0f;
    if (output > 100.0f) output = 100.0f;

    *integral_out = output;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    /* Ensure heater is off */
    gpioPWM(HEATER_GPIO, 0);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof sa);
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        log_error("sigaction failed");
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        log_error("Cannot open log file");
        return EXIT_FAILURE;
    }

    /* ---- Open SPI device ---- */
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
