#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define FAN_GPIO 18
#define PWM_FREQUENCY 25000
#define PWM_RANGE 100
#define LOG_FILE "cooling_log.csv"
#define POLL_INTERVAL 5
#define TEMP_MIN 40.0
#define TEMP_MAX 70.0
#define TEMP_MIN_DUTY 0
#define TEMP_MAX_DUTY 100

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int map_temperature_to_duty(double temp) {
    if (temp <= TEMP_MIN) return TEMP_MIN_DUTY;
    if (temp >= TEMP_MAX) return TEMP_MAX_DUTY;
    return (int)(((temp - TEMP_MIN) / (TEMP_MAX - TEMP_MIN)) * (TEMP_MAX_DUTY - TEMP_MIN_DUTY) + TEMP_MIN_DUTY);
}

static int set_fan_speed(double temp) {
    int duty = map_temperature_to_duty(temp);
    if (gpioPWM(FAN_GPIO, duty) != 0) {
        fprintf(stderr, "Error setting PWM duty cycle to %d: %s\n", duty, strerror(errno));
        return -1;
    }
    return 0;
}

static int log_data(double temp, int duty) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s,%.2f,%d\n", timestamp, temp, duty) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error registering SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", FAN_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error setting PWM frequency to %d Hz\n", PWM_FREQUENCY);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMrange(FAN_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Error setting PWM range to %d\n", PWM_RANGE);
        gpioTerminate();
        return 1;
    }

    if (gpioPWM(FAN_GPIO, 0) != 0) {
        fprintf(stderr, "Error initializing PWM to 0\n");
        gpioTerminate();
        return 1;
    }

    printf("Fan control started. Press Ctrl+C to exit.\n");

    while (running) {
        double temp = 25.0 + (rand() % 75.0);

        if (set_fan_speed(temp) != 0) {
            fprintf(stderr, "Failed to set fan speed, exiting.\n");
            break;
        }

        if (log_data(temp, gpioGetPWMdutycycle(FAN_GPIO)) != 0) {
            fprintf(stderr, "Failed to log data, exiting.\n");
            break;
        }

        printf("Temperature: %.2f °C, PWM Duty: %d%%\n", temp, gpioGetPWMdutycycle(FAN_GPIO));

        for (int i = 0; i < POLL_INTERVAL && running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    gpioPWM(FAN_GPIO, 0);
    gpioTerminate();
    printf("Fan stopped and GPIO cleaned up.\n");
    return 0;
}

