/*
 * Raspberry Pi Zero W – dual SLF3S-1300F liquid flow sensor logger
 *
 * Wiring:
 *   I2C bus 1 (GPIO2=SDA, GPIO3=SCL)
 *   Sensor 1: SDA->SDA1, SCL->SCL1, VDD->3V3, GND->GND
 *   Sensor 2: SDA->SDA2, SCL->SCL2, VDD->3V3, GND->GND
 *
 * The SLF3S-1300F is a 3-wire sensor; the multiplexer breakout (e.g.
 * Sensirion SF06) provides the I2C address selection and a common clock
 * so both sensors share the same I2C bus address.
 *
 * Build:  gcc -O2 -Wall -Wextra -o flow_logger flow_logger.c -li2c
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define LOG_FILE       "flow_log.txt"
#define POLL_INTERVAL  1          /* seconds between readings */
#define MAX_RETRIES    3          /* I2C read retries per sensor */
#define SLF3S_ADDR     0x3457     /* example 7-bit I2C address; adjust */
#define SLF3S_READ_LEN 3           /* 2 data bytes + 1 CRC byte */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF)                        */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

/*
 * Read exactly `len` bytes from the sensor.
 * Returns 0 on success, -1 on error.
 */
static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    size_t total = 0;
    for (int attempt = 1; attempt <= MAX_RETRIES; attempt++) {
        ssize_t n = read(fd, buf + total, len - total);
        if (n < 0) {
            fprintf(stderr, "read: %s (attempt %d/%d)\n",
                    strerror(errno), attempt, MAX_RETRIES);
            if (attempt < MAX_RETRIES)
                usleep(10000);          /* 10 ms back-off */
            continue;
        }
        if (n == 0) {
            fprintf(stderr, "read: unexpected EOF (attempt %d/%d)\n",
                    attempt, MAX_RETRIES);
            continue;
        }
        total += (size_t)n;
        if (total == len)
            return 0;
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Sensor read                                                         */
/* ------------------------------------------------------------------ */
typedef struct {
    int fd;
    int valid;          /* 1 = valid reading, 0 = error, -1 = CRC bad */
    int16_t flow;       /* signed flow rate (ml/s) */
} sensor_t;

static sensor_t read_sensor(int fd)
{
    sensor_t s = { .fd = fd, .valid = 0, .flow = 0 };
    uint8_t buf[SLF3S_READ_LEN];

    if (i2c_read_bytes(fd, buf, sizeof(buf)) != 0) {
        s.valid = -1;
        return s;
    }

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on sensor fd %d\n", fd);
        s.valid = -1;
        return s;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    s.flow = raw;
    s.valid = 1;
    return s;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_flow(int flow1, int flow2)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r: %s\n", strerror(errno));
        fclose(fp);
        return;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%d,%d\n", ts, flow1, flow2);
    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    int fd1 = i2c_open(I2C_BUS, SLF3S_ADDR);
    if (fd1 < 0)
        return EXIT_FAILURE;

    int fd2 = i2c_open(I2C_BUS, SLF3S_ADDR);
    if (fd2 < 0) {
        close(fd1);
        return EXIT_FAILURE;
    }

    printf("Flow logger started. Logging to %s every %d s.\n",
           LOG_FILE, POLL_INTERVAL);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        sensor_t s1 = read_sensor(fd1);
        sensor_t s2 = read_sensor(fd2);

        if (s1.valid) {
            log_flow(s1.flow, s2.flow);
            printf("Flow1: %d ml/s | Flow2: %d ml/s\n",
                   s1.flow, s2.flow);
        } else if (s2.valid) {
            log_flow(s2.flow, s1.flow);
            printf("Flow1: %d ml/s | Flow2: %d ml/s\n",
                   s2.flow, s1.flow);
        } else {
            fprintf(stderr, "No valid sensor reading this cycle.\n");
        }

        sleep(POLL_INTERVAL);
    }

    /* Clean shutdown */
    if (close(fd1) != 0)
        perror("close(fd1)");
    if (close(fd2) != 0)
        perror("close(fd2)");

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

