#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define GPIO_A 17
#define GPIO_B 18
#define LOG_FILE "encoder_log.txt"
#define PULSES_PER_REVOLUTION 360.0
#define DEGREES_PER_PULSE (360.0 / PULSES_PER_REVOLUTION)

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(GPIO_A, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input.\n", GPIO_A);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(GPIO_B, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input.\n", GPIO_B);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPullUpDown(GPIO_A, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO %d.\n", GPIO_A);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPullUpDown(GPIO_B, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO %d.\n", GPIO_B);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int read_encoder_state(int *state) {
    int a = gpioRead(GPIO_A);
    int b = gpioRead(GPIO_B);

    if (a < 0 || b < 0) {
        fprintf(stderr, "Error: failed to read GPIO pins.\n");
        return -1;
    }

    if (a == 1 && b == 0) {
        *state = 0;
    } else if (a == 0 && b == 1) {
        *state = 1;
    } else if (a == 1 && b == 1) {
        *state = 2;
    } else if (a == 0 && b == 0) {
        *state = 3;
    } else {
        *state = -1;
    }

    return 0;
}

static double calculate_position(int state) {
    switch (state) {
        case 0: return 0.0;
        case 1: return 90.0;
        case 2: return 180.0;
        case 3: return 270.0;
        default: return -1.0;
    }
}

static int log_position(double position) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "Error: failed to get current time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: failed to convert time.\n");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "Error: failed to format timestamp.\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s, Position: %.2f degrees\n", timestamp, position) < 0) {
        fprintf(stderr, "Error: failed to write to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error: failed to close log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (initialize_gpio() != 0) {
        return 1;
    }

    int last_state = -1;
    int current_state = -1;

    printf("Monitoring rotary encoder on GPIO%d and GPIO%d...\n", GPIO_A, GPIO_B);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        int new_state = -1;

        if (read_encoder_state(&new_state) != 0) {
            gpioDelay(100000);
            continue;
        }

        if (new_state != current_state) {
            current_state = new_state;
            double position = calculate_position(current_state);

            if (position != -1.0) {
                if (log_position(position) != 0) {
                    fprintf(stderr, "Warning: failed to log position.\n");
                }
            } else {
                fprintf(stderr, "Warning: invalid state %d, skipping log.\n", current_state);
            }

            printf("Position: %.2f degrees\n", position);
        }

        gpioDelay(10000);
    }

    printf("\nShutting down...\n");
    gpioTerminate();
    printf("Cleanup complete.\n");

    return 0;
}

