/*
 * ADPD144RI Red/IR Photometric Sensor Logger
 * Board:  Raspberry Pi 3 Model B+
 * Bus:    I2C bus 1 (GPIO2=SDA, GPIO3=SCL)
 * Sensor: Analog Devices ADPD144RI
 * Address: 0x48 (verified against datasheet)
 * LED:     GPIO17 (active-high)
 *
 * Build:  gcc -O2 -Wall -o adpd144ri_log adpd144ri_log.c -lpigpio -lrt
 * Run:    sudo ./adpd144ri_log
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS            1
#define I2C_ADDR           0x48          /* ADPD144RI default I2C address */
#define LED_GPIO           17
#define IR_THRESHOLD       2000          /* raw ADC count above this triggers LED */
#define SAMPLE_PERIOD_US   100000        /* 100 ms between samples */
#define LOG_FILE           "adpd144ri_log.txt"

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd = -1;
static FILE    *g_log_fp = NULL;

/* --------------------------- Forward declarations ------------------------ */
static void signal_handler(int sig);
static int  initialize(void);
static void cleanup(void);
static int  read_sensor(int fd, uint16_t *red, uint16_t *ir);
static void log_data(FILE *fp, uint16_t red, uint16_t ir);
static void control_led(int gpio, uint16_t ir);

/* ------------------------------- Signal handler -------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- Initialization ------------------------------- */
static int initialize(void)
{
    /* --- pigpio library --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] pigpio initialisation failed (code %d).\n",
                gpioInitialise());
        return -1;
    }

    /* --- I2C bus --- */
    g_i2c_fd = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_fd);
        gpioTerminate();
        return -1;
    }

    /* --- LED GPIO --- */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "[ERROR] gpioSetMode(%d, PI_OUTPUT) failed.\n", LED_GPIO);
        cleanup();
        return -1;
    }
    gpioWrite(LED_GPIO, 0);   /* LED off at startup */

    /* --- Log file --- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "[ERROR] fopen(%s) failed: %s\n",
                LOG_FILE, strerror(errno));
        cleanup();
        return -1;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "timestamp,red,ir\n");
        fflush(g_log_fp);
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGINT) failed: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGTERM) failed: %s\n", strerror(errno));
    }

    return 0;
}

/* --------------------------- Cleanup ------------------------------------- */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        i2cClose(g_i2c_fd);
        g_i2c_fd = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

/* --------------------------- Sensor read ------------------------------- */
/*
 * ADPD144RI raw data is 16-bit (two's complement) for both red and IR.
 * The sensor returns a 2-byte big-endian value per channel.
 */
static int read_sensor(int fd, uint16_t *red, uint16_t *ir)
{
    char buf[2];

    /* --- Read red channel --- */
    if (i2cReadDevice(fd, buf, 2) != 2) {
        fprintf(stderr, "[ERROR] i2cReadDevice(red) failed: %s\n",
                strerror(errno));
        return -1;
    }
    *red = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];

    /* --- Read IR channel --- */
    if (i2cReadDevice(fd, buf, 2) != 2) {
        fprintf(stderr, "[ERROR] i2cReadDevice(ir) failed: %s\n",
                strerror(errno));
        return -1;
    }
    *ir = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];

    return 0;
}

/* --------------------------- Logging ------------------------------------ */
static void log_data(FILE *fp, uint16_t red, uint16_t ir)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed.\n");
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    fprintf(fp, "%s,%u,%u\n", ts, red, ir);
    fflush(fp);
}

/* --------------------------- LED control ------------------------------- */
static void control_led(int gpio, uint16_t ir)
{
    int level = (ir > IR_THRESHOLD) ? 1 : 0;
    if (gpioWrite(gpio, level) < 0) {
        fprintf(stderr, "[WARN] gpioWrite(%d, %d) failed.\n", gpio, level);
    }
}

