int main(void)
{
    if (initialize() != 0) {
        return EXIT_FAILURE;
    }

    printf("ADPD144RI logger started.  Logging to %s  (Ctrl+C to stop)\n",
           LOG_FILE);

    while (g_running) {
        uint16_t red = 0, ir = 0;

        if (read_sensor(g_i2c_fd, &red, &ir) == 0) {
            log_data(g_log_fp, red, ir);
            control_led(LED_GPIO, ir);
        } else {
            fprintf(stderr, "[WARN] Sensor read failed; LED stays off.\n");
        }

        /* Sleep in small increments so signals are caught promptly */
        for (int i = 0; i < 10 && g_running; i++) {
            gpioDelay(10000);   /* 10 ms × 10 = 100 ms */
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

