#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define LOG_FILE "rpm_log.txt"
#define SAMPLE_INTERVAL_SEC 1.0

static volatile int pulse_count = 0;
static pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void isr_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)level; (void)tick; (void)userdata;
    pthread_mutex_lock(&pulse_mutex);
    pulse_count++;
    pthread_mutex_unlock(&pulse_mutex);
}

static double calculate_rpm(int pulses, double interval_sec) {
    if (interval_sec <= 0.0) return 0.0;
    return (double)pulses * (60.0 / interval_sec);
}

static void log_rpm(double rpm) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (log_file) {
        fprintf(log_file, "%s, RPM: %.2f\n", timestamp, rpm);
        fflush(log_file);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    if (gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, isr_callback, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set ISR for GPIO %d.\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: Cannot open log file '%s'.\n", LOG_FILE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to install signal handlers.\n");
    }

    printf("RPM monitoring started on GPIO %d. Press Ctrl+C to exit.\n", GPIO_PIN);

    while (running) {
        sleep(SAMPLE_INTERVAL_SEC);

        pthread_mutex_lock(&pulse_mutex);
        int pulses = pulse_count;
        pulse_count = 0;
        pthread_mutex_unlock(&pulse_mutex);

        if (pulses > 0) {
            double rpm = calculate_rpm(pulses, SAMPLE_INTERVAL_SEC);
            log_rpm(rpm);
            printf("RPM: %.2f\n", rpm);
        } else {
            log_rpm(0.0);
            printf("No pulses detected. Sensor may be disconnected or not rotating.\n");
        }
    }

    printf("\nShutting down gracefully...\n");

    gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, NULL, NULL);
    gpioTerminate();

    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }

    pthread_mutex_destroy(&pulse_mutex);

    return EXIT_SUCCESS;
}

