/*
 * ADPD144RI red+IR photometric sensor reader for Raspberry Pi 3 Model B+.
 *
 * Wiring:
 *   ADPD144RI SDA -> GPIO2 (I2C bus 1 SDA)
 *   ADPD144RI SCL -> GPIO3 (I2C bus 1 SCL)
 *   ADPD144RI VDD -> 3.3 V
 *   ADPD144RI GND -> GND
 *   LED anode    -> GPIO17 (via ~330 Ω resistor) -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o adpd144ri adpd144ri.c
 * Run:    ./adpd144ri   (creates adpd144ri_log.txt if it does not exist)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define ADPD144RI_ADDR 0x60
#define LED_PIN        17
#define IR_THRESHOLD   2000
#define LOG_FILE       "adpd144ri_log.txt"
#define SAMPLE_MS      100

/* ADPD144RI register map (16-bit addresses, big-endian on the bus). */
#define REG_MODE        0x0000
#define REG_INT_CFG     0x0002
#define REG_INT_STATUS  0x0004
#define REG_DATA        0x0006
#define REG_INT_CLEAR  0x0008

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static int i2c_write16(int fd, uint16_t reg, uint16_t val)
{
    uint8_t buf[4];
    buf[0] = (uint8_t)(reg >> 8);
    buf[1] = (uint8_t)(reg & 0xFF);
    buf[2] = (uint8_t)(val >> 8);
    buf[3] = (uint8_t)(val & 0xFF);

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write16 to 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read16(int fd, uint16_t reg, uint16_t *out)
{
    uint8_t addr[2];
    addr[0] = (uint8_t)(reg >> 8);
    addr[1] = (uint8_t)(reg & 0xFF);

    if (write(fd, addr, sizeof(addr)) != (ssize_t)sizeof(addr)) {
        fprintf(stderr, "I2C write (addr) for 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    uint8_t data[2];
    if (read(fd, data, sizeof(data)) != (ssize_t)sizeof(data)) {
        fprintf(stderr, "I2C read from 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *out = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

/* ------------------------------------------------------------------ */
static int adpd144ri_init(int fd)
{
    /* Put sensor into standby so configuration changes take effect. */
    if (i2c_write16(fd, REG_MODE, 0x0000) < 0)
        return -1;

    /* Clear any pending interrupt. */
    if (i2c_write16(fd, REG_INT_CLEAR, 0x0001) < 0)
        return -1;

    /* Enable IR interrupt on rising edge. */
    if (i2c_write16(fd, REG_INT_CFG, 0x0001) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
static int adpd144ri_read(int fd, uint16_t *red, uint16_t *ir)
{
    if (i2c_read16(fd, REG_DATA, red) < 0)
        return -1;

    if (i2c_read16(fd, REG_DATA + 2, ir) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, uint16_t red, uint16_t ir)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%u,%u\n", ts, red, ir);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open I2C bus. */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, ADPD144RI_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                ADPD144RI_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Probe: try a dummy read to confirm the sensor is present. */
    uint16_t probe;
    if (adpd144ri_read(g_i2c_fd, &probe, &probe) < 0) {
        fprintf(stderr, "ADPD144RI not responding at 0x%02X — check wiring.\n",
                ADPD144RI_ADDR);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize sensor. */
    if (adpd144ri_init(g_i2c_fd) < 0) {
        fprintf(stderr, "ADPD144RI initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file (append). */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure LED pin. */
    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d) failed: %s\n", LED_PIN, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    printf("ADPD144RI logging started.  Threshold = %d  Sample = %d ms\n",
           IR_THRESHOLD, SAMPLE_MS);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        uint16_t red, ir;

        if (adpd144ri_read(g_i2c_fd, &red, &ir) < 0) {
            fprintf(stderr, "Read error — continuing.\n");
            gpioWrite(LED_PIN, 0);
        } else {
            log_data(g_log_fp, red, ir);

            if (ir > IR_THRESHOLD) {
                gpioWrite(LED_PIN, 1);
                printf("IR > %d  LED ON\n", IR_THRESHOLD);
            } else {
                gpioWrite(LED_PIN, 0);
            }
        }

        /* Sleep in 10 ms slices so signals are caught promptly. */
        for (int ms = 0; ms < SAMPLE_MS && g_running; ms += 10)
            usleep(10 * 1000);
    }

    printf("\nShutting down...\n");
    gpioWrite(LED_PIN, 0);
    cleanup();
    return EXIT_SUCCESS;
}

