#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

#define AUDIO_INPUT_PIN 17
#define GAIN_SELECT_PIN 18
#define LOG_FILE "audio_log.txt"
#define POLL_DELAY_US 10000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(AUDIO_INPUT_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", AUDIO_INPUT_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(GAIN_SELECT_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", GAIN_SELECT_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(GAIN_SELECT_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to write GAIN select pin.\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void log_event(int level) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error: localtime_r failed.\n");
        fclose(fp);
        return;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error: strftime failed.\n");
        fclose(fp);
        return;
    }

    if (fprintf(fp, "%s LEVEL\n", timestamp) < 0) {
        fprintf(stderr, "Error: writing to log file failed.\n");
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error: closing log file failed: %s\n", strerror(errno));
    }

    printf("Logged: %s LEVEL\n", timestamp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: cannot register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: cannot register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Audio peak detection started. Sampling GPIO%d every %d us.\n", AUDIO_INPUT_PIN, POLL_DELAY_US);
    printf("Press Ctrl+C to exit.\n");

    int prev_level = -1;

    while (running) {
        int level = gpioRead(AUDIO_INPUT_PIN);
        if (level < 0) {
            fprintf(stderr, "Error: gpioRead failed on pin %d.\n", AUDIO_INPUT_PIN);
            break;
        }

        if (level != prev_level) {
            if (level == 1) {
                log_event(1);
            }
            prev_level = level;
        }

        gpioDelay(POLL_DELAY_US);
    }

    gpioTerminate();
    printf("\nAudio peak detection stopped.\n");
    return EXIT_SUCCESS;
}

