/*
 * Raspberry Pi Zero W – Sensirion SLF3S‑4000B Liquid Flow Sensor Monitor
 *
 * Wiring:
 *   SLF3S VDD  -> 3V3 (Pin 1)
 *   SLF3S GND  -> GND (Pin 9)
 *   SLF3S SDA  -> GPIO2 / I2C1 SDA (Pin 3)
 *   SLF3S SCL  -> GPIO3 / I2C1 SCL (Pin 5)
 *
 * I2C bus 1, address 0x3D (7-bit, default).  The sensor continuously
 * broadcasts a 3-byte measurement frame: [MSB, LSB, CRC8].
 *
 * Build:  gcc -O2 -Wall -Wextra -o flow_monitor flow_monitor.c -lpigpio -lrt
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x3D          /* SLF3S default 7-bit address */
#define LOG_FILE       "flow_log.csv"
#define SAMPLE_US      1000000       /* 1 s between readings */
#define MEAS_DELAY_US  10000         /* sensor needs ~10 ms after a read */

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_fp    = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF)                        */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Read one 3-byte measurement frame from the SLF3S                    */
/* Returns 0 on success, -1 on I2C error, -2 on CRC mismatch.          */
/* ------------------------------------------------------------------ */
static int read_flow_rate(int handle, uint16_t *out)
{
    uint8_t buf[3];

    /* i2cReadDevice returns the number of bytes read, or < 0 on error. */
    int n = i2cReadDevice(handle, (char *)buf, sizeof(buf));
    if (n != (int)sizeof(buf)) {
        fprintf(stderr, "[ERROR] i2cReadDevice returned %d (expected %zu)\n",
                n, sizeof(buf));
        return -1;
    }

    /* CRC check */
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "[ERROR] CRC mismatch (calc=0x%02X recv=0x%02X)\n",
                crc8(buf, 2), buf[2]);
        return -2;
    }

    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Append a CSV row                                                   */
/* ------------------------------------------------------------------ */
static void log_flow_rate(FILE *fp, uint16_t flow_rate)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed\n");
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%u\n", ts, (unsigned)flow_rate) < 0) {
        fprintf(stderr, "[ERROR] fprintf to log failed\n");
        return;
    }
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] gpioInitialise failed\n");
        return EXIT_FAILURE;
    }

    /* ---- open I2C ---- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- open log file (append) ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "[FATAL] Cannot open %s for append\n", LOG_FILE);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- signals ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGINT) failed\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGTERM) failed\n");
    }

    printf("Monitoring SLF3S-4000B on I2C bus %d, addr 0x%02X.  Ctrl-C to stop.\n",
           I2C_BUS, I2C_ADDR);

    /* ---- main loop ---- */
    while (g_running) {
        uint16_t flow_rate = 0;

        int rc = read_flow_rate(g_i2c_handle, &flow_rate);
        if (rc == 0) {
            log_flow_rate(g_log_fp, flow_rate);
        } else if (rc == -1) {
            /* I2C bus error – brief back-off, then retry. */
            gpioDelay(MEAS_DELAY_US);
            continue;
        } else if (rc == -2) {
            /* CRC failure – skip this sample. */
            gpioDelay(MEAS_DELAY_US);
            continue;
        } else {
            /* Unexpected error code. */
            fprintf(stderr, "[ERROR] read_flow_rate returned %d\n", rc);
            gpioDelay(MEAS_DELAY_US);
            continue;
        }

        /* Sleep SAMPLE_US, but wake early on signal. */
        for (int i = 0; i < 10 && g_running; i++)
            gpioDelay(100000);          /* 100 ms × 10 = 1 s */
    }

    /* ---- graceful shutdown ---- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

