#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x48
#define LOG_FILE "air_quality_log.csv"
#define SAMPLE_INTERVAL_SEC 5

/* MICS-VZ-89TE register addresses (16-bit, big-endian on the bus) */
#define REG_DEVICE_ID 0x00
#define REG_DATA_READY 0x01
#define REG_DATA 0x04
#define REG_CONFIG 0x0F

#define DEVICE_ID_VAL 0x89
#define DATA_READY_VAL 0x01
#define CONFIG_DEFAULT 0x00

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg16(int handle, uint16_t reg, uint16_t *val) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, buf, 2) != 0) return -1;
    if (i2cReadDevice(handle, buf, 2) != 2) return -1;
    *val = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

static int i2c_write_reg16(int handle, uint16_t reg, uint16_t val) {
    char buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (val >> 8) & 0xFF;
    buf[3] = val & 0xFF;
    return i2cWriteDevice(handle, buf, 4);
}

static int read_sensor_data(int handle, uint16_t *tvoc, uint16_t *eco2) {
    uint16_t ready, data;
    if (i2c_read_reg16(handle, REG_DATA_READY, &ready) != 0) {
        fprintf(stderr, "Error: failed to read DATA_READY register.\n");
        return -1;
    }
    if (!(ready & DATA_READY_VAL)) {
        fprintf(stderr, "Warning: sensor data not ready (0x%02X).\n", ready);
        return 1;
    }
    if (i2c_read_reg16(handle, REG_DATA, data) != 0) {
        fprintf(stderr, "Error: failed to read DATA register.\n");
        return -1;
    }
    *tvoc = data;
    *eco2 = data >> 8;
    return 0;
}

static int calculate_iaq(uint16_t tvoc, uint16_t eco2) {
    float tvoc_ppb = (float)tvoc;
    float eco2_ppm = (float)eco2;
    float iaq = 100.0f - (float)(tvoc_ppb + eco2_ppm) / 100.0f;
    if (iaq < 0.0f) iaq = 0.0f;
    if (iaq > 100.0f) iaq = 100.0f;
    return (int)iaq;
}

static int log_data(FILE *fp, int iaq, uint16_t tvoc, uint16_t eco2) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed.\n");
        return -1;
    }
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    if (fprintf(fp, "%s,%d,%u,%u\n", ts, iaq, tvoc, eco2) < 0) {
        fprintf(stderr, "Error: fprintf to log failed.\n");
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "Error: fflush failed.\n");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d).\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint16_t dev_id = 0;
    if (i2c_read_reg16(g_i2c_handle, REG_DEVICE_ID, &dev_id) != 0) {
        fprintf(stderr, "Error: cannot read device ID. Sensor absent or bus error.\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (dev_id != DEVICE_ID_VAL) {
        fprintf(stderr, "Error: unexpected device ID 0x%02X (expected 0x%02X).\n", dev_id, DEVICE_ID_VAL);
        cleanup();
        return EXIT_FAILURE;
    }
    printf("MICS-VZ-89TE detected (device ID 0x%02X).\n", dev_id);

    if (i2c_write_reg16(g_i2c_handle, REG_CONFIG, CONFIG_DEFAULT) != 0) {
        fprintf(stderr, "Error: failed to write CONFIG register.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s'.\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Logging to %s every %d seconds. Press Ctrl+C to stop.\n", LOG_FILE, SAMPLE_INTERVAL_SEC);

    while (g_running) {
        uint16_t tvoc = 0, eco2 = 0;
        int rc = read_sensor_data(g_i2c_handle, &tvoc, &eco2);
        if (rc == 0) {
            int iaq = calculate_iaq(tvoc, eco2);
            if (log_data(g_log_file, iaq, tvoc, eco2) != 0) {
                fprintf(stderr, "Warning: logging failed for this sample.\n");
            } else {
                printf("IAQ: %d, TVOC: %u ppb, eCO2: %u ppm\n", iaq, tvoc, eco2);
            }
        } else if (rc < 0) {
            fprintf(stderr, "Warning: I2C read error, skipping sample.\n");
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

