#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME      "gpiochip4"
#define GPIO_LINE_OFFSET    17
#define POLL_INTERVAL_MS    100
#define INTRUSION_TIMEOUT_S 5

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static int setup_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static void print_usage(const char *prog)
{
    fprintf(stderr,
        "Usage: %s [GPIO_LINE_OFFSET]\n"
        "  GPIO_LINE_OFFSET  BCM pin number for the TTP223B OUT line (default: %d)\n"
        "  -n NUM_SECONDS     Override the intrusion timeout (default: %d)\n"
        "  -h                 Show this help\n",
        prog, GPIO_LINE_OFFSET, INTRUSION_TIMEOUT_S);
}

int main(int argc, char *argv[])
{
    int line_offset = GPIO_LINE_OFFSET;
    int intrusion_timeout_s = INTRUSION_TIMEOUT_S;
    int opt;

    while ((opt = getopt(argc, argv, "n:h")) != -1) {
        switch (opt) {
        case 'n':
            intrusion_timeout_s = atoi(optarg);
            if (intrusion_timeout_s <= 0) {
                fprintf(stderr, "Invalid timeout value: %s\n", optarg);
                return EXIT_FAILURE;
            }
            break;
        case 'h':
            print_usage(argv[0]);
            return EXIT_SUCCESS;
        default:
            print_usage(argv[0]);
            return EXIT_FAILURE;
        }
    }

    if (setup_signal_handlers() == -1) {
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, line_offset);
    if (!line) {
        fprintf(stderr, "Failed to get line %d: %s\n", line_offset, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(line, "ttp223_tamper") < 0) {
        fprintf(stderr, "Failed to request line %d as input: %s\n",
                line_offset, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Monitoring TTP223B touch sensor on GPIO %d (BCM) for %d-second intrusions.\n",
           line_offset, intrusion_timeout_s);
    printf("Press Ctrl+C to exit.\n");

    struct timespec poll_ts = { 0, POLL_INTERVAL_MS * 1000000L };
    struct timespec intrusion_start = { 0, 0 };
    int first_read_ok = 0;

    while (program_running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            fprintf(stderr, "Failed to read line %d: %s\n", line_offset, strerror(errno));
            break;
        }

