static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static int setup_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static void print_usage(const char *prog)
{
    fprintf(stderr,
        "Usage: %s [GPIO_LINE_OFFSET]\n"
        "  GPIO_LINE_OFFSET  BCM pin number for the TTP223B OUT line (default: %d)\n"
        "  -n NUM_SECONDS     Override the intrusion timeout (default: %d)\n"
        "  -h                 Show this help\n",
        prog, GPIO_LINE_OFFSET, INTRUSION_TIMEOUT_S);
}

int main(int argc, char *argv[])
{
