/*
 * audio_capture.c — Raspberry Pi 4 Model B
 *
 * Continuously samples the INMP441 I2S MEMS microphone via ALSA and writes
 * 16-bit PCM data to audio_capture.pcm while asserting the L/R channel-
 * select line on GPIO 17 (BCM) to select the left channel.
 *
 * Build:  gcc -O2 -Wall -Wextra -o audio_capture audio_capture.c
 * Run:    ./audio_capture
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/soundcard.h>

#define I2S_DEVICE      "/dev/snd/pcmC0D0c"
#define OUTPUT_FILE     "audio_capture.pcm"
#define SAMPLE_RATE     48000
#define CHANNELS        2
#define NUM_CHANNELS    (CHANNELS * 2)
#define GPIO_CHANNEL    17
#define GPIO_CONSUMER   "audio_capture"
#define NUM_SAMPLES     1024
#define LOG_FILE        "audio_capture.log"

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_message(const char *msg)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(log)");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    } else {
        fprintf(fp, "[unknown time] %s\n", msg);
    }
    fclose(fp);
}

static int init_i2s(void)
{
    int fd = open(I2S_DEVICE, O_RDWR);
    if (fd < 0) {
        log_message("open(I2S_DEVICE) failed");
        return -1;
    }

    struct snd_pcm_hw_params *hw = NULL;
    int err = snd_pcm_hw_params_alloca(&hw);
    if (err < 0) {
        log_message("snd_pcm_hw_params_alloca failed");
        close(fd);
        return -1;
    }

    err = snd_pcm_hw_params_any(fd, hw);
    if (err < 0) {
        log_message("snd_pcm_hw_params_any failed");
        goto fail;
    }

    err = snd_pcm_hw_params_set_access(fd, hw, SND_PCM_ACCESS_RW_INTERLEAVED);
    if (err < 0) {
        log_message("set_access failed");
        goto fail;
    }

    err = snd_pcm_hw_params_set_format(fd, hw, SND_PCM_FORMAT_S16_LE);
    if (err < 0) {
        log_message("set_format failed");
        goto fail;
    }

    err = snd_pcm_hw_params_set_channels(fd, hw, CHANNELS);
    if (err < 0) {
        log_message("set_channels failed");
        goto fail;
    }

    err = snd_pcm_hw_params_set_rate_near(fd, hw, &SAMPLE_RATE, 0);
    if (err < 0) {
        log_message("set_rate_near failed");
        goto fail;
    }

    err = snd_pcm_hw_params(fd, hw);
    if (err < 0) {
        log_message("snd_pcm_hw_params failed");
        goto fail;
    }

    err = snd_pcm_prepare(fd);
    if (err < 0) {
        log_message("snd_pcm_prepare failed");
        goto fail;
    }

    return fd;

fail:
    snd_pcm_hw_params_free(hw);
    close(fd);
    return -1;
}

static int select_channel(int fd, int left)
{
    if (ioctl(fd, SNDCTL_DSP_SET_CHANNEL, left) < 0) {
        log_message("ioctl(SNDCTL_DSP_SET_CHANNEL) failed");
        return -1;
    }
    return 0;
}

static int read_audio(int fd, int16_t *samples, int num_samples)
{
    int frames = num_samples / NUM_CHANNELS;
    int err = 0;

    for (int i = 0; i < frames && !g_running; i++) {
        int n = (i < frames - 1) ? NUM_SAMPLES : num_samples - (frames - i - 1) * NUM_SAMPLES;
        int16_t *buf = malloc(n * sizeof(int16_t));
        if (!buf) {
            log_message("malloc failed");
            return -1;
        }

        int got = 0;
        while (got < n) {
            int r = snd_pcm_readi(fd, buf + got, n - got);
            if (r < 0) {
                log_message("snd_pcm_readi failed");
                free(buf);
                return -1;
            }
            if (r == 0) {
                log_message("snd_pcm_readi returned 0 (EOF) without reading samples)");
                free(buf);
                return -1;
            }
            got += r;
        }

        for (int j = 0; j < n; j++) {
            samples[j * NUM_CHANNELS + 0] = buf[j];
            samples[j * NUM_CHANNELS + 1] = buf[j];
        }
    }

    free(buf);
    return err;
}

static int write_audio_file(const char *filename, const int16_t *samples, int num_samples)
{
    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        log_message("fopen(OUTPUT_FILE) failed");
        return -1;
    }

    size_t written = fwrite(samples, sizeof(int16_t), num_samples, fp);
    if (written != (size_t)num_samples) {
        log_message("fwrite failed");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        log_message("fclose failed");
        return -1;
    }

    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    int fd = init_i2s();
    if (fd < 0) {
        return EXIT_FAILURE;
    }

    if (select_channel(fd, 1) < 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    int16_t *samples = malloc(NUM_SAMPLES * NUM_CHANNELS);
    if (!samples) {
        log_message("malloc failed");
        close(fd);
        return EXIT_FAILURE;
    }

    log_message("Audio capture started");

    while (g_running) {
        if (read_audio(fd, samples, NUM_SAMPLES) < 0) {
            log_message("Error reading audio samples");
            break;
        }

        if (write_audio_file(OUTPUT_FILE, samples, NUM_SAMPLES) < 0) {
            log_message("Error writing audio file");
            break;
        }

        usleep(100000);
    }

    log_message("Audio capture stopped");

    free(samples);
    close(fd);
    return EXIT_SUCCESS;
}

