#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define FLAME_SENSOR_PIN 4
#define FAN_PIN 18
#define PWM_FREQUENCY 100
#define DEBOUNCE_DELAY_US 50000
#define POLL_INTERVAL_US 50000
#define DEBOUNCE_TIMEOUT_US 1000000
#define LOG_FILE "flame_log.txt"

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_event(const char *event_type) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm tm_info;
    char timestamp[32];
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }
    fprintf(log_file, "%s: %s\n", timestamp, event_type);
    fflush(log_file);
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set flame sensor pin mode\n");
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(FAN_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set fan pin mode\n");
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMfrequency(FAN_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return -1;
    }
    if (gpioPWM(FAN_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialise PWM duty cycle\n");
        gpioTerminate();
        return -1;
    }
    return 0;
}

static void cleanup_gpio(void) {
    gpioPWM(FAN_PIN, 0);
    gpioWrite(FAN_PIN, 0);
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(FAN_PIN, PI_INPUT);
    gpioTerminate();
}

static int read_flame_sensor(void) {
    int value = gpioRead(FLAME_SENSOR_PIN);
    if (value < 0) {
        fprintf(stderr, "Failed to read flame sensor pin\n");
        return -1;
    }
    return value;
}

static void control_fan(int state) {
    if (gpioPWM(FAN_PIN, state) != 0) {
        fprintf(stderr, "Failed to set fan PWM duty cycle\n");
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return 1;
    }

    if (initialize_gpio() != 0) {
        fclose(log_file);
        return 1;
    }

    log_event("Program started");

    int last_flame_state = -1;
    uint32_t last_change_tick = 0;

    while (program_running) {
        int sensor_value = read_flame_sensor();
        if (sensor_value < 0) {
            log_event("Error reading flame sensor");
            gpioDelay(DEBOUNCE_TIMEOUT_US);
            continue;
        }

        uint32_t now_tick = gpioTick();
        if (sensor_value != last_flame_state) {
            if (sensor_value == 0) {
                if (last_flame_state != 0) {
                    log_event("Flame detected");
                    control_fan(1);
                }
            } else {
                if (last_flame_state == 0) {
                    log_event("Flame cleared");
                    control_fan(0);
                }
            }
            last_flame_state = sensor_value;
            last_change_tick = now_tick;
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    log_event("Program shutting down");
    cleanup_gpio();
    if (log_file) {
        fclose(log_file);
    }
    return 0;
}

