        uint32_t now_tick = gpioTick();
        if (sensor_value != last_flame_state) {
            if (sensor_value == 0) {
                if (last_flame_state != 0) {
                    log_event("Flame detected");
                    control_fan(1);
                }
            } else {
                if (last_flame_state == 0) {
                    log_event("Flame cleared");
                    control_fan(0);
                }
            }
            last_flame_state = sensor_value;
            last_change_tick = now_tick;
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    log_event("Program shutting down");
    cleanup_gpio();
    if (log_file) {
        fclose(log_file);
    }
    return 0;
}

