#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8

#define GPIO_TRIGGER 23
#define GPIO_DATA_READY 24

#define LOG_FILE "radar_data.bin"
#define FRAME_SIZE 32768
#define CONFIG_SIZE 128
#define MAGIC_NUMBER 0x4144

typedef struct {
    uint32_t start_frequency;
    uint32_t end_frequency;
    uint32_t num_chirps;
    uint32_t num_samples;
} radar_config_t;

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static FILE *log_file = NULL;
static radar_config_t config;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open SPI device");
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl SPI_IOC_WR_MODE");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("ioctl SPI_IOC_WR_BITS_PER_WORD");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl SPI_IOC_WR_MAX_SPEED_HZ");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

static int gpio_init(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_TRIGGER, PI_OUTPUT);
    gpioSetMode(GPIO_DATA_READY, PI_INPUT);
    gpioWrite(GPIO_TRIGGER, 0);
    gpioSetPullUpDown(GPIO_DATA_READY, PI_PUD_UP);

    return 0;
}

static int log_write_header(FILE *fp, const radar_config_t *cfg) {
    uint8_t magic[4] = {MAGIC_NUMBER, 0, 0, 0};
    if (fwrite(magic, 1, 4, fp) != 4) {
        perror("fwrite magic");
        return -1;
    }

    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
        perror("clock_gettime");
        return -1;
    }
    uint64_t ts_u64 = (uint64_t)ts.tv_sec * 1000000000ULL + (uint64_t)ts.tv_nsec / 1000ULL;

    uint8_t header[CONFIG_SIZE + 8];
    memcpy(header, &ts_u64, 8);
    memcpy(header + 8, &cfg->start_frequency, 4);
    memcpy(header + 12, &cfg->end_frequency, 4);
    memcpy(header + 16, &cfg->num_chirps, 4);
    memcpy(header + 20, &cfg->num_samples, 4);

    if (fwrite(header, 1, CONFIG_SIZE + 8, fp) != (CONFIG_SIZE + 8)) {
        perror("fwrite header");
        return -1;
    }

    return 0;
}

static int log_write_frame(FILE *fp, uint64_t frame_number, uint64_t timestamp) {
    uint8_t frame_header[4];
    memset(frame_header, 0, 4);
    frame_header[0] = MAGIC_NUMBER;
    frame_header[1] = 0;
    frame_header[2] = 0;
    frame_header[3] = 0;

    uint8_t frame_data[4];
    memset(frame_data, 0, 4);
    frame_data[0] = (uint8_t)frame_number;
    frame_data[1] = (uint8_t)(timestamp >> 32);
    frame_data[2] = (uint8_t)(timestamp >> 16);
    frame_data[3] = (uint8_t)(timestamp & 0xFFFF);

    if (fwrite(frame_header, 1, 4, fp) != 4) {
        perror("fwrite frame header");
        return -1;
    }
    if (fwrite(frame_data, 1, 4, fp) != 4) {
        perror("fwrite frame data");
        return -1;
    }

    return 0;
}

static int spi_transfer(uint8_t *tx, uint8_t *rx, int len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("ioctl SPI_IOC_MESSAGE");
        return -1;
    }
    return 0;
}

static int read_radar_data(uint8_t *data, int len) {
    uint8_t tx[FRAME_SIZE];
    uint8_t rx[FRAME_SIZE];

    memset(tx, 0, FRAME_SIZE);
    memset(rx, 0, FRAME_SIZE);

    if (spi_transfer(tx, rx, FRAME_SIZE) < 0) {
        return -1;
    }

    memcpy(data, rx, len);
    return 0;
}

static void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction SIGINT");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction SIGTERM");
        return 1;
    }

    if (gpio_init() < 0) {
        return 1;
    }

    if (spi_init() < 0) {
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "wb");
    if (log_file == NULL) {
        perror("fopen log");
        cleanup();
        return 1;
    }

    if (log_write_header(log_file, &config) < 0) {
        cleanup();
        return 1;
    }

    uint8_t data[FRAME_SIZE];
    uint64_t frame_number = 0;
    uint64_t timestamp = 0;

    while (running) {
        if (gpioRead(GPIO_DATA_READY) == 0) {
            if (read_radar_data(data, FRAME_SIZE) < 0) {
                fprintf(stderr, "SPI read error\n");
                break;
            }

            if (log_write_frame(log_file, frame_number, timestamp) < 0) {
                fprintf(stderr, "Log write error\n");
                break;
            }

            frame_number++;
            timestamp++;

            gpioWrite(GPIO_TRIGGER, 1);
            gpioDelay(1000);
            gpioWrite(GPIO_TRIGGER, 0);
        }

        gpioDelay(100000);
    }

    cleanup();
    return 0;
}

