/*
 * OPT3001 Ambient Light Sensor Reader for Raspberry Pi Zero W
 *
 * Wiring:
 *   OPT3001 SDA -> GPIO2 (I2C bus 1 SDA)
 *   OPT3001 SCL -> GPIO3 (I2C bus 1 SCL)
 *   OPT3001 VDD -> 3.3 V
 *   OPT3001 GND -> GND
 *
 * I2C bus: /dev/i2c-1
 * Build:  gcc -O2 -Wall -Wextra -o opt3001_reader opt3001_reader.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define OPT3001_ADDR   0x48
#define LOG_FILE       "light_data.txt"
#define CONV_TIME_MS   100

/* OPT3001 register addresses */
#define REG_RESULT     0x00
#define REG_CONFIG     0x01

/* Config register bits */
#define CFG_AUTO_INC   (1 << 1)
#define CFG_CONT_MODE  (1 << 0)
#define CFG_FULLSCALE  (1 << 2)
#define CFG_INT_POL   (1 << 3)
#define CFG_INT_MASK  (0x03 << 4)
#define CFG_INT_EN    (1 << 5)
#define CFG_MODE      (1 << 6)
#define CFG_ADC_MISC  (1 << 7)

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a 16-bit value to an 8-bit register (MSB first) */
static int i2c_write_reg16(int fd, uint8_t reg, uint16_t value)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(value >> 8);
    buf[2] = (uint8_t)(value & 0xFF);

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a 16-bit value from an 8-bit register (MSB first) */
static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t reg_buf = reg;
    uint8_t data[2];

    if (write(fd, &reg_buf, sizeof(reg_buf)) != (ssize_t)sizeof(reg_buf)) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (read(fd, data, sizeof(data)) != (ssize_t)sizeof(data)) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *out = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

static int opt3001_init(int fd)
{
    /* Clear config register (0x00) to start from a known state */
    if (i2c_write_reg16(fd, REG_CONFIG, 0x0000) < 0)
        return -1;

    /* Continuous conversion mode, auto-increment, full-scale */
    uint16_t config = CFG_CONT_MODE | CFG_AUTO_INC | CFG_FULLSCALE |
                      CFG_INT_POL | CFG_INT_MASK | CFG_INT_EN |
                      CFG_MODE | CFG_ADC_MISC;

    if (i2c_write_reg16(fd, REG_CONFIG, config) < 0)
        return -1;

    return 0;
}

static int opt3001_read_lux(int fd, float *lux_out)
{
    uint16_t raw;

    if (i2c_read_reg16(fd, REG_RESULT, &raw) < 0)
        return -1;

    /* Clear result register to allow next conversion */
    if (i2c_write_reg16(fd, REG_RESULT, 0x0000) < 0)
        return -1;

    /* 12-bit result in bits [15:4] */
    int16_t lux = (int16_t)((raw >> 4) & 0x0FFF);
    *lux_out = (float)lux;
    return 0;
}

static void log_data(float lux)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f\n", ts, lux);
    fclose(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, OPT3001_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n",
                OPT3001_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    if (opt3001_init(g_i2c_fd) < 0) {
        fprintf(stderr, "OPT3001 initialization failed (sensor absent or bus error)\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("OPT3001 initialized. Logging to %s every %d ms. Press Ctrl+C to stop.\n",
           LOG_FILE, CONV_TIME_MS);

    while (g_running) {
        float lux;
        if (opt3001_read_lux(g_i2c_fd, &lux) < 0) {
            fprintf(stderr, "Read error; continuing.\n");
        } else {
            log_data(lux);
            printf("Lux: %.2f\n", lux);
        }
        usleep(CONV_TIME_MS * 1000);
    }

    printf("\nShutting down cleanly...\n");
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return EXIT_SUCCESS;
}

