/*
 * flame_detect.c — SainSmart IR Flame Detection Sensor Module reader
 *
 * Board : Raspberry Pi 3 Model B+
 * Bus   : /dev/gpiochip0 (BCM GPIO numbering)
 * Sensor: SainSmart IR Flame Detection Module
 *   — DOUT line (active-low) on GPIO17 (BCM)
 *   — VCC  on 3V3, GND on GND
 *
 * Build: gcc -Wall -Wextra -O2 -o flame_detect flame_detect.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME   "gpiochip0"
#define GPIO_LINE_OFFSET 17          /* BCM 17 */
#define POLL_TIMEOUT_MS  1000        /* 1 s poll interval */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void install_sigint_handler(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
    }
}

/* ------------------------------------------------------------------ */
static void print_timestamp(void)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        perror("time()");
        return;
    }
    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        perror("localtime_r");
        return;
    }
    char buf[32];
    if (strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }
    printf("%s", buf);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_request *req = NULL;
    struct gpiod_line_settings *settings = NULL;
    struct gpiod_line_config *line_cfg = NULL;
    struct gpiod_request_config *req_cfg = NULL;
    int ret = EXIT_FAILURE;

    install_sigint_handler();

    /* ---- Open the GPIO chip ---------------------------------------- */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n",
                GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Configure the line as input with pull-up bias -------------- */
    settings = gpiod_line_settings_new();
    if (settings == NULL) {
        fprintf(stderr, "gpiod_line_settings_new failed: %s\n",
                strerror(errno));
        goto cleanup;
    }

    gpiod_line_settings_set_direction(settings, GPIOD_LINE_DIRECTION_INPUT);
    gpiod_line_settings_set_bias(settings, GPIOD_LINE_BIAS_PULL_UP);

    line_cfg = gpiod_line_config_new();
    if (line_cfg == NULL) {
        fprintf(stderr, "gpiod_line_config_new failed: %s\n",
                strerror(errno));
        goto cleanup;
    }

    unsigned int offset = GPIO_LINE_OFFSET;
    if (gpiod_line_config_add_line_settings(line_cfg, &offset, 1,
                                            settings) != 0) {
        fprintf(stderr, "gpiod_line_config_add_line_settings failed: %s\n",
                strerror(errno));
        goto cleanup;
    }

    /* ---- Request exclusive access to the line ---------------------- */
    req_cfg = gpiod_request_config_new();
    if (req_cfg == NULL) {
        fprintf(stderr, "gpiod_request_config_new failed: %s\n",
                strerror(errno));
        goto cleanup;
    }
    gpiod_request_config_set_consumer(req_cfg, "flame_detect");

    req = gpiod_chip_request_lines(chip, req_cfg, line_cfg);
    if (req == NULL) {
        fprintf(stderr, "gpiod_chip_request_lines failed: %s\n",
                strerror(errno));
        goto cleanup;
    }

    printf("Flame detection started on %s line %u (BCM).\n",
           GPIO_CHIP_NAME, GPIO_LINE_OFFSET);
    printf("Press Ctrl+C to exit.\n");

    /* ---- Main polling loop ---------------------------------------- */
    while (g_running) {
        int value = gpiod_line_request_get_value(req, GPIO_LINE_OFFSET);
        if (value < 0) {
            fprintf(stderr, "gpiod_line_request_get_value failed: %s\n",
                    strerror(errno));
            /* Brief pause before retrying to avoid log flooding */
            usleep(POLL_TIMEOUT_MS * 1000);
            continue;
        }

        printf("Flame Detected: %s\n",
               (value == 0) ? "YES" : "NO");

        /* Sleep 1 s, but wake early on signal */
        for (int i = 0; i < 10 && g_running; i++) {
            usleep(100 * 1000);          /* 100 ms */
        }
    }

    printf("\nExiting gracefully...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (req != NULL) {
        gpiod_line_request_release(req);
    }
    if (req_cfg != NULL) {
        gpiod_request_config_free(req_cfg);
    }
    if (line_cfg != NULL) {
        gpiod_line_config_free(line_cfg);
    }
    if (settings != NULL) {
        gpiod_line_settings_free(settings);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    return ret;
}

