/*
 * KY-033 3-Way Tracing Sensor reader for Raspberry Pi Zero W
 *
 * Wiring (BCM numbering):
 *   Left  output -> GPIO17 (physical pin 11)
 *   Center output -> GPIO18 (physical pin 12)
 *   Right output -> GPIO27 (physical pin 13)
 *   VCC         -> 3.3 V (physical pin 1)
 *   GND         -> GND   (physical pin 9)
 *
 * Build:  gcc -O2 -Wall -Wextra -o ky033 ky033.c -lpigpio -lrt
 * Run:    sudo ./ky033
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <pigpio.h>

#define LEFT_PIN    17
#define CENTER_PIN  18
#define RIGHT_PIN   27

#define POLL_US      50000          /* 50 ms polling interval            */
#define MAX_READS    100            /* max consecutive read failures     */

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static volatile sig_atomic_t g_terminate = 0;

static void signal_handler(int sig)
{
    (void)sig;
    g_terminate = 1;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

/*
 * Read a single GPIO pin.  Returns 0 or 1 on success, -1 on error.
 */
static int read_pin(unsigned pin)
{
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "gpioRead failed on pin %u: %s\n",
                pin, pigpio_error(v));
        return -1;
    }
    return v;
}

/*
 * Read all three sensor outputs.  Returns 0 on success, -1 on error.
 */
static int read_all_outputs(int left, int center, int right)
{
    int lv = read_pin(left);
    int cv = read_pin(center);
    int rv = read_pin(right);

    if (lv < 0 || cv < 0 || rv < 0) {
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* --- Install signal handlers for graceful shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure pins as inputs --- */
    if (gpioSetMode(LEFT_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(LEFT_PIN=%u, PI_INPUT) failed\n",
                LEFT_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(CENTER_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(CENTER_PIN=%u, PI_INPUT) failed\n",
                CENTER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(RIGHT_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(RIGHT_PIN=%u, PI_INPUT) failed\n",
                RIGHT_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Enable internal pull-downs so disconnected pins read LOW --- */
    gpioSetPullUpDown(LEFT_PIN, PI_PUD_DOWN);
    gpioSetPullUpDown(CENTER_PIN, PI_PUD_DOWN);
    gpioSetPullUpDown(RIGHT_PIN, PI_PUD_DOWN);

    printf("KY-033 3-Way Tracing Sensor Reader\n");
    printf("Left: GPIO%d  Center: GPIO%d  Right: GPIO%d\n",
           LEFT_PIN, CENTER_PIN, RIGHT_PIN);
    printf("Press Ctrl+C to exit.\n\n");

    int consecutive_errors = 0;

    /* --- Main polling loop --- */
    while (!g_terminate) {
        int all = read_all_outputs(LEFT_PIN, CENTER_PIN, RIGHT_PIN);

        if (all < 0) {
            consecutive_errors++;
            if (consecutive_errors >= MAX_READS) {
                fprintf(stderr, "Too many consecutive read failures; aborting.\n");
                break;
            }
            fprintf(stderr, "Read error #%d\n", consecutive_errors);
        } else {
            consecutive_errors = 0;
            printf("Left: %d, Center: %d, Right: %d\n",
                   all & 1, (all >> 1) & 1, (all >> 2) & 1);
        }

        usleep(POLL_US);
    }

    /* --- Graceful shutdown --- */
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

