#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define NUM_CHANNELS 8
#define POLL_DELAY_US 100000  /* 100 ms */

static const int channel_pins[NUM_CHANNELS] = {2, 3, 4, 5, 6, 7, 8, 9};

static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

static void print_timestamp(void)
{
    time_t rawtime;
    struct tm timeinfo;
    char buffer[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", &timeinfo);
    printf("[%s] ", buffer);
}

int main(void)
{
    int line_handles[NUM_CHANNELS];
    int i;
    int ret;

    /* Register signal handler for graceful shutdown */
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error: cannot register SIGINT handler.\n");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d).\n", ret);
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip (GPIO chip 0 on Raspberry Pi Zero W) */
    ret = gpioSetMode(0, PI_OUTPUT);
    if (ret < 0) {
        fprintf(stderr, "Error: failed to set GPIO chip 0 as output (code %d).\n", ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Request each channel as an input */
    for (i = 0; i < NUM_CHANNELS; i++) {
        line_handles[i] = gpioSetMode(channel_pins[i], PI_INPUT);
        if (line_handles[i] < 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as input (code %d).\n",
                    channel_pins[i], line_handles[i]);
            for (int j = 0; j < i; j++) {
                gpioSetMode(channel_pins[j], PI_OUTPUT);
            }
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    printf("TTP226 8-channel touch sensor reader started. Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (!terminate) {
        for (i = 0; i < NUM_CHANNELS; i++) {
            int value = gpioRead(line_handles[i]);
            if (value < 0) {
                fprintf(stderr, "Error: failed to read GPIO %d (code %d).\n",
                        channel_pins[i], value);
                continue;
            }
            print_timestamp();
            printf("Channel %d: %d\n", i + 1, value);
        }
        fflush(stdout);
        gpioDelay(POLL_DELAY_US);
    }

    /* Cleanup: release all line handles and terminate pigpio */
    for (i = 0; i < NUM_CHANNELS; i++) {
        gpioSetMode(channel_pins[i], PI_INPUT);  /* best-effort return to input */
    }
    gpioTerminate();

    printf("\nProgram terminated gracefully.\n");
    return EXIT_SUCCESS;
}

