    if (ret < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (code %d).\n", ret);
        return EXIT_FAILURE;
    }

    /* Configure sensor pins as inputs with pull-down resistors */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpioSetMode(sensor_pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as input.\n", sensor_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPullUpDown(sensor_pins[i], PI_PUD_DOWN) != 0) {
            fprintf(stderr, "Error: failed to set pull-down on GPIO %d.\n", sensor_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    printf("TTP226 8-channel touch sensor reader started.\n");
    printf("Pins: GPIO %d-%d\n", sensor_pins[0], sensor_pins[NUM_CHANNELS - 1]);
    printf("Sampling every %d ms. Press Ctrl+C to exit.\n\n", SAMPLE_INTERVAL_US / 1000);

    /* Main sampling loop */
    while (running) {
        int sensor_values[NUM_CHANNELS];
        int read_result;

        read_result = gpioRead(sensor_pins[0]);
        if (read_result < 0) {
            fprintf(stderr, "Error: failed to read GPIO %d.\n", sensor_pins[0]);
            break;
        }
        sensor_values[0] = read_result;

        for (int i = 1; i < NUM_CHANNELS; i++) {
            read_result = gpioRead(sensor_pins[i]);
            if (read_result < 0) {
                fprintf(stderr, "Error: failed to read GPIO %d.\n", sensor_pins[i]);
                break;
            }
            sensor_values[i] = read_result;
        }

        printf("[%+03d ms] CH1=%d CH2=%d CH3=%d CH4=%d CH5=%d CH6=%d CH7=%d CH8=%d\n",
               SAMPLE_INTERVAL_US / 1000,
               sensor_values[0], sensor_values[1], sensor_values[2],
               sensor_values[3], sensor_values[4], sensor_values[5],
               sensor_values[6], sensor_values[7]);

        fflush(stdout);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Clean shutdown: ensure API call is invoked */
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

