/*
 * TMAG5110 Hall-Effect Latch Sensor Reader for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   Sensor 1 OUT -> BCM GPIO4 (physical pin 7)
 *   Sensor 2 OUT -> BCM GPIO5 (physical pin 29)
 *   VCC          -> 3.3 V (physical pin 1)
 *   GND          -> GND   (physical pin 9)
 *
 * The TMAG5110 output is open-drain with an external pull-up resistor.
 *   - Output LOW  (0)  = magnet detected (latch asserted)
 *   - Output HIGH (1)  = no magnet (latch de-asserted)
 *
 * Build:
 *   gcc -Wall -o hall_effect hall_effect.c -lthe_driver_library -lrt
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

#include <gpiod.h>

#define SENSOR1_PIN  4   /* BCM GPIO4  */
#define SENSOR2_PIN  5   /* BCM GPIO5  */
#define POLL_INTERVAL_MS 500

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

int main(void)
{
