/*
 * TTP226 8-channel capacitive touch sensor reader for Raspberry Pi 4 Model B.
 *
 * Wiring (BCM numbering):
 *   CH1 -> GPIO2  (physical pin 3)
 *   CH2 -> GPIO3  (physical pin 5)
 *   CH3 -> GPIO4  (physical pin 7)
 *   CH4 -> GPIO17 (physical pin 11)
 *   CH5 -> GPIO27 (physical pin 13)
 *   CH6 -> GPIO22 (physical pin 15)
 *   CH7 -> GPIO10 (physical pin 19)
 *   CH8 -> GPIO9  (physical pin 21)
 *
 * Build:  gcc -O2 -Wall -Wextra -o ttp226 ttp226.c -lpigpio -lrt
 * Run:    sudo ./ttp226
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define NUM_CHANNELS 8
#define POLL_DELAY_US 50000          /* 50 ms */
#define TIMESTAMP_LEN 32

static const int channel_pins[NUM_CHANNELS] = {
    2, 3, 4, 17, 27, 22, 10, 9
};

/* ------------------------------------------------------------------ */
/* Globals for signal-handler cleanup                                  */
/* ------------------------------------------------------------------ */
static volatile sig_atomic_t g_running = 1;
static int g_pigpio_ready = 0;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

/* Returns 0 on success, -1 on failure. */
static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }
    g_pigpio_ready = 1;

    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpioSetMode(channel_pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode failed for BCM pin %d.\n",
                    channel_pins[i]);
            return -1;
        }
        /* TTP226 modules typically drive the line high when idle; the
         * Pi's internal pull-up/pull-down is disabled by default, so
         * an external pull-up is assumed. */
        if (gpioSetPullUpDown(channel_pins[i], PI_PUD_OFF) != 0) {
            fprintf(stderr, "Warning: gpioSetPullUpDown failed for BCM pin %d.\n",
                    channel_pins[i]);
        }
    }
    return 0;
}

/* Returns 0 on success, -1 on failure. */
static int read_all_channels(uint8_t *channel_states)
{
    for (int i = 0; i < NUM_CHANNELS; i++) {
        int level = gpioRead(channel_pins[i]);
        if (level < 0) {
            fprintf(stderr, "Error: gpioRead failed for BCM pin %d.\n",
                    channel_pins[i]);
            return -1;
        }
        channel_states[i] = (uint8_t)level;
    }
    return 0;
}

/* Returns 0 on success, -1 on failure. */
static int generate_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm timeinfo;

    if (time(&rawtime) == (time_t)-1) {
        perror("time");
        return -1;
    }
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        perror("localtime_r");
        return -1;
    }
    if (strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed.\n");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    uint8_t channel_states[NUM_CHANNELS];
    char timestamp[TIMESTAMP_LEN];

    /* Install signal handlers for graceful shutdown. */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("TTP226 touch sensor reader started. Press Ctrl-C to exit.\n");
    fflush(stdout);

    while (g_running) {
        if (read_all_channels(channel_states) != 0) {
            fprintf(stderr, "Error: failed to read channel states.\n");
            break;
        }

        if (generate_timestamp(timestamp, sizeof(timestamp)) != 0) {
            fprintf(stderr, "Error: failed to generate timestamp.\n");
            break;
        }

        printf("%s,%u,%u,%u,%u,%u,%u,%u\n",
               timestamp,
               channel_states[0], channel_states[1],
               channel_states[2], channel_states[3],
               channel_states[4], channel_states[5],
               channel_states[6], channel_states[7]);
        fflush(stdout);

        gpioDelay(POLL_DELAY_US);
    }

    /* ---- Graceful cleanup ---- */
    if (g_pigpio_ready) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            gpioSetPullUpDown(channel_pins[i], PI_PUD_OFF);
            gpioSetMode(channel_pins[i], PI_INPUT);
        }
        gpioTerminate();
        g_pigpio_ready = 0;
    }

    printf("\nProgram terminated gracefully.\n");
    return EXIT_SUCCESS;
}

