#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TILT_SENSOR_PIN 4
#define POLL_DELAY_US   100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

int main(void)
{
    /* Install SIGINT handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (code %d).\n", gpioInitialise());
        return EXIT_FAILURE;
    }

    /* Configure GPIO4 as input with internal pull-up */
    if (gpioSetMode(TILT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for pin %d.\n", TILT_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(TILT_SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for pin %d.\n", TILT_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Allow pull-up to settle */
    gpioDelay(10000);  /* 10 ms */

    printf("Tilt sensor monitoring started on GPIO%d.\n", TILT_SENSOR_PIN);
    printf("Press Ctrl-C to exit.\n");
    fflush(stdout);

    int last_state = -1;  /* Unknown initial state */

    while (g_running) {
        int tilt_state = gpioRead(TILT_SENSOR_PIN);

        if (tilt_state < 0) {
            fprintf(stderr, "Error: gpioRead failed on pin %d (code %d).\n",
                    TILT_SENSOR_PIN, tilt_state);
            break;
        }

        /* Log state change and flush immediately so output is not
         * interleaved with the 100 ms poll delay. */
        if (tilt_state != last_state) {
            if (tilt_state == 0) {
                printf("Tilted\n");
            } else {
                printf("Not Tilted\n");
            }
            fflush(stdout);
            last_state = tilt_state;
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* Clean shutdown */
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

