#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SI1145_ADDR 0x60
#define I2C_BUS "/dev/i2c-1"
#define CSV_FILE "uv_als_log.csv"
#define SAMPLE_INTERVAL_SEC 1

/* Si1145 register addresses */
#define SI1145_REG_PART_ID       0x00
#define SI1145_REG_HW_KEY        0x07
#define SI1145_REG_MEAS_RATE0    0x08
#define SI1145_REG_ALS_VIS_DATA0 0x22
#define SI1145_REG_UV_INDEX0     0x2C
#define SI1145_REG_COMMAND       0x18

/* Si1145 command opcodes */
#define SI1145_CMD_RESET         0x01
#define SI1145_CMD_ALS_FORCE     0x06
#define SI1145_CMD_PS_FORCE      0x05
#define SI1145_CMD_ALS_PS_FORCE  0x07

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        return -1;
    }
    return 0;
}

static int si1145_init(int fd) {
    uint8_t part_id;
    if (i2c_read_reg8(fd, SI1145_REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "Error: Failed to read PART_ID register.\n");
        return -1;
    }
    if (part_id != 0x45) {
        fprintf(stderr, "Error: Unexpected PART_ID 0x%02X (expected 0x45).\n", part_id);
        return -1;
    }

    /* Reset the device */
    if (i2c_write_reg8(fd, SI1145_REG_COMMAND, SI1145_CMD_RESET) < 0) {
        fprintf(stderr, "Error: Failed to reset Si1145.\n");
        return -1;
    }
    usleep(10000); /* 10 ms settle time after reset */

    /* Write HW_KEY to enable proper operation */
    if (i2c_write_reg8(fd, SI1145_REG_HW_KEY, 0x17) < 0) {
        fprintf(stderr, "Error: Failed to write HW_KEY.\n");
        return -1;
    }

    /* Set measurement rate to 1 sample per second */
    if (i2c_write_reg8(fd, SI1145_REG_MEAS_RATE0, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to set measurement rate.\n");
        return -1;
    }

    return 0;
}

static int si1145_read_als(int fd, uint16_t *als) {
    uint8_t als_low, als_high;
    if (i2c_read_reg8(fd, SI1145_REG_ALS_VIS_DATA0, &als_low) < 0) {
        return -1;
    }
    if (i2c_read_reg8(fd, SI1145_REG_ALS_VIS_DATA0 + 1, &als_high) < 0) {
        return -1;
    }
    *als = ((uint16_t)als_high << 8) | als_low;
    return 0;
}

static int si1145_read_uv(int fd, uint16_t *uv) {
    uint8_t uv_low, uv_high;
    if (i2c_read_reg8(fd, SI1145_REG_UV_INDEX0, &uv_low) < 0) {
        return -1;
    }
    if (i2c_read_reg8(fd, SI1145_REG_UV_INDEX0 + 1, &uv_high) < 0) {
        return -1;
    }
    *uv = ((uint16_t)uv_high << 8) | uv_low;
    return 0;
}

static void log_data(FILE *fp, uint16_t uv, uint16_t als) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%u,%u\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, uv, als);
    fflush(fp);
}

static void cleanup(void) {
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("Error opening I2C bus " I2C_BUS);
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SI1145_ADDR) < 0) {
        perror("Error setting I2C slave address");
        cleanup();
        return EXIT_FAILURE;
    }

    if (si1145_init(g_i2c_fd) < 0) {
        fprintf(stderr, "Error: Si1145 initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(CSV_FILE, "a");
    if (g_log_fp == NULL) {
        perror("Error opening log file");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Si1145 initialized. Logging to %s. Press Ctrl+C to stop.\n", CSV_FILE);

    while (g_running) {
        uint16_t uv, als;

        if (si1145_read_uv(g_i2c_fd, &uv) < 0) {
            fprintf(stderr, "Error: Failed to read UV index.\n");
        } else if (si1145_read_als(g_i2c_fd, &als) < 0) {
            fprintf(stderr, "Error: Failed to read ALS data.\n");
        } else {
            printf("UV Index: %u, Visible Light: %u\n", uv, als);
            log_data(g_log_fp, uv, als);
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

