/*
 * Raspberry Pi 5 – Dual SLF3S-0600F Liquid Flow Sensor Logger
 *
 * Wiring:
 *   Sensor 1 SDA -> GPIO2 (I2C1 SDA)
 *   Sensor 1 SCL -> GPIO3 (I2C1 SCL)
 *   Sensor 1 VDD -> 3.3 V
 *   Sensor 1 GND -> GND
 *   Sensor 2 SDA -> GPIO2 (I2C1 SDA)
 *   Sensor 2 SCL -> GPIO3 (I2C1 SCL)
 *   Sensor 2 VDD -> 3.3 V
 *   Sensor 2 GND -> GND
 *   Alarm LED   -> GPIO17 (BCM) via ~330 Ω resistor to GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o flow_logger flow_logger.c -lpigpio -lrt
 * Run:    sudo ./flow_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define ALARM_GPIO     17
#define FLOW_THRESHOLD 0.5f   /* ml/min */
#define LOG_FILE       "flow_log.txt"
#define MEAS_DELAY_US  1000000 /* 1 s between measurements */
#define START_DELAY_US 100000  /* 100 ms after start command */

/* SLF3S-0600F 8-bit CRC: polynomial 0x31, initial value 0xFF */
#define CRC8_POLY 0x31
#define CRC8_INIT 0xFF

typedef struct {
    int      i2c_handle;
    float    flow_rate;
    bool     valid;
} sensor_data_t;

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Sensirion CRC-8 (polynomial 0x31, init 0xFF)                        */
/* ------------------------------------------------------------------ */
static uint8_t sensirion_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ CRC8_POLY : (crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int handle, uint8_t cmd)
{
    char buf[1] = { (char)cmd };
    if (i2cWriteDevice(handle, buf, 1) != 1) {
        fprintf(stderr, "[I2C] write cmd 0x%02X failed\n", cmd);
        return -1;
    }
    return 0;
}

static int i2c_read_block(int handle, uint8_t *buf, size_t len)
{
    int n = i2cReadDevice(handle, (char *)buf, len);
    if (n != (int)len) {
        fprintf(stderr, "[I2C] read expected %zu bytes, got %d\n", len, n);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor operations                                                   */
/* ------------------------------------------------------------------ */
static int sensor_start(int handle)
{
    if (i2c_write_cmd(handle, 0x36) != 0)   /* start continuous measurement */
        return -1;
    gpioDelay(START_DELAY_US);
    return 0;
}

static int sensor_read(int handle, sensor_data_t *data)
{
    uint8_t buf[9];
    if (i2c_read_block(handle, buf, sizeof(buf)) != 0)
        return -1;

    /* Bytes 0–1: flow rate (16-bit, big-endian) */
    uint16_t raw_flow = ((uint16_t)buf[0] << 8) | buf[1];
    /* Bytes 2–3: temperature (16-bit, big-endian) */
    uint16_t raw_temp = ((uint16_t)buf[2] << 8) | buf[3];
    /* Bytes 4–5: CRC temperature */
    uint8_t crc_temp = sensirion_crc8(buf + 2, 2);
    if (crc_temp != buf[4]) {
        fprintf(stderr, "[Sensor] temperature CRC mismatch\n");
        return -1;
    }
    /* Bytes 6–7: CRC flow */
    uint8_t crc_flow = sensirion_crc8(buf + 3, 2);
    if (crc_flow != buf[5]) {
        fprintf(stderr, "[Sensor] flow CRC mismatch\n");
        return -1;
    }
    /* Bytes 8–9: CRC scale factor */
    uint8_t crc_scale = sensirion_crc8(buf + 6, 2);
    if (crc_scale != buf[7]) {
        fprintf(stderr, "[Sensor] scale factor CRC mismatch\n");
        return -1;
    }

    /* SLF3S-0600F: flow rate = raw_flow / 100 */
    data->flow_rate = (float)raw_flow / 100.0f;
    data->valid = true;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, float avg_flow)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "[Log] localtime_r failed\n");
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Average Flow Rate: %.2f ml/min\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, avg_flow);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioWrite(ALARM_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- GPIO setup ---- */
    if (gpioSetMode(ALARM_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", ALARM_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(ALARM_GPIO, 0);

    /* ---- I2C open ---- */
    int h1 = i2cOpen(I2C_BUS, 0x40, 0);
    if (h1 < 0) {
        fprintf(stderr, "Failed to open I2C device 1 (0x%02X): %d\n", 0x40, h1);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    int h2 = i2cOpen(I2C_BUS, 0x41, 0);
    if (h2 < 0) {
        fprintf(stderr, "Failed to open I2C device 2 (0x%02X): %d\n", 0x41, h2);
        i2cClose(h1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Sensor init ---- */
    if (sensor_start(h1) != 0 || sensor_start(h2) != 0) {
        fprintf(stderr, "Failed to start one or both sensors\n");
        i2cClose(h1);
        i2cClose(h2);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Log file ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("fopen(" LOG_FILE ")");
        i2cClose(h1);
        i2cClose(h2);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Signals ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    sensor_data_t s1 = { .i2c_handle = h1, .flow_rate = 0.0f, .valid = false };
    sensor_data_t s2 = { .i2c_handle = h2, .flow_rate = 0.0f, .valid = false };

    /* ---- Main loop ---- */
    while (g_running) {
        bool ok1 = false, ok2 = false;
        int err1 = 0, err2 = 0;

        /* Sensor 1 */
        if (sensor_read(s1.i2c_handle, &s1) == 0) {
            ok1 = true;
            s1.valid = true;
        } else {
            err1 = 1;
        }

        /* Sensor 2 */
        if (sensor_read(s2.i2c_handle, &s2) == 0) {
            ok2 = true;
            s2.valid = true;
        } else {
            err2 = 1;
        }

        if (!ok1 && !ok2) {
            fprintf(stderr, "[Main] Both sensors read failed; skipping cycle\n");
        } else if (!ok1) {
            fprintf(stderr, "[Main] Sensor 1 read failed\n");
        } else if (!ok2) {
            fprintf(stderr, "[Main] Sensor 2 read failed\n");
        }

        if (ok1 && ok2) {
            float sum = s1.flow_rate + s2.flow_rate;
            float avg = (sum > 0.0f) ? (sum / 2.0f) : 0.0f;
            log_data(g_log_fp, avg);

            if (avg < FLOW_THRESHOLD) {
                gpioWrite(ALARM_GPIO, 1);
                printf("[ALARM] Avg flow %.2f ml/min < %.2f ml/min\n",
                       avg, FLOW_THRESHOLD);
            } else {
                gpioWrite(ALARM_GPIO, 0);
            }
        }

        gpioDelay(MEAS_DELAY_US);
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

