#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define SENSOR_PIN 4
#define BUFFER_SIZE 100
#define POLL_DELAY_US 50000
#define TIMESTAMP_LEN 32

typedef struct {
    time_t timestamp;
    int    obstacle_detected;
} SensorData;

static SensorData circular_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void format_timestamp(char *buf, size_t len) {
    time_t now = time(NULL);
    struct tm tm_info;
    localtime_r(&now, &tm_info);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm_info);
}

static void add_to_buffer(time_t ts, int detected) {
    circular_buffer[buffer_index].timestamp = ts;
    circular_buffer[buffer_index].obstacle_detected = detected;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
}

static void dump_buffer(void) {
    int start = (buffer_count < BUFFER_SIZE) ? 0 : buffer_index;
    for (int i = 0; i < buffer_count; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        char ts[TIMESTAMP_LEN];
        format_timestamp(ts, sizeof(ts));
        printf("[%s] Obstacle: %s\n", ts,
               (circular_buffer[idx].obstacle_detected == 1) ? "Detected" : "None");
    }
    fflush(stdout);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO%d\n", SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Obstacle detection started on GPIO%d. Press Ctrl+C to exit.\n", SENSOR_PIN);

    while (program_running) {
        int level = gpioRead(SENSOR_PIN);
        if (level < 0) {
            fprintf(stderr, "gpioRead failed on GPIO%d: %s\n",
                    SENSOR_PIN, strerror(errno));
            break;
        }

        int detected = (level == 0) ? 1 : 0;
        add_to_buffer(time(NULL), detected);

        if (detected) {
            printf("Obstacle detected!\n");
            fflush(stdout);
        }

        gpioDelay(POLL_DELAY_US);
    }

    gpioTerminate();
    dump_buffer();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

