#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define D7S_ADDR       0x60
#define D7S_MODE_REG   0x08
#define D7S_X_REG       0x04
#define D7S_Y_REG       0x06
#define D7S_Z_REG       0x08
#define CSV_FILE        "fan_health.csv"
#define POLL_INTERVAL_MS 500
#define ACTIVATION_TIMEOUT_MS 1000

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo) {
    (void)signo;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int d7s_init(int fd) {
    if (i2c_write_reg8(fd, D7S_MODE_REG, 0x00) < 0) return -1;
    usleep(10000);
    if (i2c_write_reg8(fd, D7S_MODE_REG, 0x01) < 0) return -1;
    usleep(10000);
    return 0;
}

static int read_xyz(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t rx[6];
    if (i2c_read_reg8(fd, D7S_X_REG, &rx[0]) < 0) return -1;
    if (i2c_read_reg8(fd, D7S_Y_REG, &rx[2]) < 0) return -1;
    if (i2c_read_reg8(fd, D7S_Z_REG, &rx[4]) < 0) return -1;
    *x = (int16_t)((rx[0] << 8) | rx[1]);
    *y = (int16_t)((rx[2] << 8) | rx[3]);
    *z = (int16_t)((rx[4] << 8) | rx[5]);
    return 0;
}

static void timestamp_iso8601(char *buf, size_t len) {
    time_t t = time(NULL);
    struct tm tmv;
    localtime_r(&t, &tmv);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tmv);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, D7S_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n", D7S_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (d7s_init(fd) < 0) {
        fprintf(stderr, "D7S initialization failed.\n");
        close(fd);
        return 1;
    }

    int file_exists = (access(CSV_FILE, F_OK) == 0);
    FILE *fp = fopen(CSV_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", CSV_FILE, strerror(errno));
        close(fd);
        return 1;
    }
    if (!file_exists) {
        fprintf(fp, "timestamp,x,y,z\n");
        fflush(fp);
    }
    fclose(fp);

    printf("D7S vibration sensor monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int16_t x, y, z;
        if (read_xyz(fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Read error, retrying in %d ms...\n", POLL_INTERVAL_MS);
            usleep(POLL_INTERVAL_MS * 1000);
            continue;
        }

        char ts[32];
        timestamp_iso8601(ts, sizeof(ts));

        if (file_exists) {
            fprintf(fp, "%s,%d,%d,%d\n", ts, x, y, z);
            fflush(fp);
        } else {
            fprintf(stderr, "File %s not found; cannot append data.\n", CSV_FILE);
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    printf("\nShutting down cleanly.\n");
    close(fd);
    return 0;
}

