static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

int main(void)
{
    int rc;

    /* Install signal handlers for clean shutdown */
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal(SIGINT)");
        return EXIT_FAILURE;
    }
    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("signal(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    rc = gpioInitialise();
    if (rc < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (code %d).\n", rc);
        fprintf(stderr, "       Is the pigpio daemon running? Stop it first.\n");
        return EXIT_FAILURE;
    }

    /* Configure sensor pins as inputs */
    rc = gpioSetMode(SENSOR_1_PIN, PI_INPUT);
    if (rc != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input (code %d).\n",
                SENSOR_1_PIN, rc);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    rc = gpioSetMode(SENSOR_2_PIN, PI_INPUT);
    if (rc != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input (code %d).\n",
                SENSOR_2_PIN, rc);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure LED pin as output and ensure it starts OFF */
    rc = gpioSetMode(LED_PIN, PI_OUTPUT);
    if (rc != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output (code %d).\n",
                LED_PIN, rc);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    rc = gpioWrite(LED_PIN, 0);
    if (rc != 0) {
        fprintf(stderr, "Error: failed to initialize GPIO%d to LOW (code %d).\n",
                LED_PIN, rc);
        gpioTerminate();
        return EXIT_FAILURE;
    }

