                    s1, s2);
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        /* KY-032 OUT is active-LOW: LOW => obstacle detected */
        if (s1 == 0 || s2 == 0) {
            rc = gpioWrite(LED_PIN, 1);
            if (rc != 0) {
                fprintf(stderr, "Warning: failed to turn LED ON (code %d).\n",
                        rc);
            }
        } else {
            rc = gpioWrite(LED_PIN, 0);
            if (rc != 0) {
                fprintf(stderr, "Warning: failed to turn LED OFF (code %d).\n",
                        rc);
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    rc = gpioWrite(LED_PIN, 0);
    if (rc != 0) {
        fprintf(stderr, "Warning: failed to turn LED OFF during shutdown (code %d).\n",
                rc);
    }
    gpioTerminate();
    printf("Obstacle avoidance system stopped.\n");
    return EXIT_SUCCESS;
}

