#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define SENSOR_PIN 23
#define LOG_FILE "flood_log.txt"
#define POLL_INTERVAL_SEC 2
#define REINIT_DELAY_SEC 60

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    } else {
        fprintf(fp, "UNKNOWN %s\n", message);
    }
    fclose(fp);
}

static void log_error(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d ERROR: %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    } else {
        fprintf(fp, "UNKNOWN ERROR: %s\n", message);
    }
    fclose(fp);
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    if (gpioSetMode(SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPullUpDown(SENSOR_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on GPIO %d\n", SENSOR_PIN);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int read_sensor(void) {
    int value = gpioRead(SENSOR_PIN);
    if (value < 0) {
        fprintf(stderr, "Failed to read GPIO %d\n", SENSOR_PIN);
        return -1;
    }
    return value;
}

static void cleanup(void) {
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Water level monitoring started on GPIO %d. Press Ctrl+C to exit.\n", SENSOR_PIN);

    while (running) {
        int sensor_value = read_sensor();
        if (sensor_value < 0) {
            log_error("Sensor read failure; re-initializing GPIO in 60 seconds.");
            sleep(REINIT_DELAY_SEC);
            continue;
        }

        if (sensor_value == 1) {
            printf("ALERT: Water detected!\n");
            log_event("Water detected");
        }

        for (int i = 0; i < POLL_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    cleanup();
    printf("Water level monitoring stopped.\n");
    return EXIT_SUCCESS;
}

