#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pthread.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME      "gpiochip4"
#define GPIO_LINE_OFFSET    4          /* BCM GPIO4, physical pin 7 */
#define LOG_FILE            "rpm_log.txt"
#define SAMPLE_INTERVAL_SEC 1
#define WINDOW_SEC          1

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;
static struct gpiod_chip *g_chip = NULL;
static struct gpiod_line *g_line = NULL;
static pthread_mutex_t g_pulse_mutex = PTHREAD_MUTEX_INITIALIZER;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void pulse_callback(struct gpiod_line *line, int value, uint64_t ts)
{
    (void)ts;
    if (value == 1) {
        pthread_mutex_lock(&g_pulse_mutex);
        int count = atomic_fetch_add(&g_pulse_count, 1);
        pthread_mutex_unlock(&g_pulse_mutex);
    }
}

static int setup_gpio(void)
{
    g_chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!g_chip) {
        perror("gpiod_chip_open_by_name");
        return -1;
    }

    g_line = gpiod_chip_get_line(g_chip, GPIO_LINE_OFFSET);
    if (!g_line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(g_chip);
        g_chip = NULL;
        return -1;
    }

    if (gpiod_line_request_rising_edge_events(g_line, "mlx90217-rpm") < 0) {
        perror("gpiod_line_request_rising_edge_events");
        gpiod_chip_close(g_chip);
        g_chip = NULL;
        g_line = NULL;
        return -1;
    }

    /* Enable internal pull-up so the line reads HIGH when the sensor is absent */
    if (gpiod_line_request_output(g_line, "mlx90217-pullup", 1) < 0) {
        perror("gpiod_line_request_output (pull-up)");
        gpiod_line_release(g_line);
        gpiod_chip_close(g_chip);
        g_chip = NULL;
        g_line = NULL;
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void)
{
    if (g_line) {
        gpiod_line_release(g_line);
        g_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
}

static int setup_log(void)
{
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }
    return 0;
}

static void log_rpm(int rpm)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(g_log_fp, "%s %d\n", timestamp, rpm) < 0) {
        perror("fprintf");
    } else {
        fflush(g_log_fp);
    }

    printf("%s %d\n", timestamp, rpm);
}

int main(void)
{
    struct sigaction sa;
    struct gpiod_line_event event;
    struct timespec window_start, window_end;
    int pulse_count = 0;
    int last_count = 0;
    int first_window = 1;

    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (setup_gpio() < 0) {
        return EXIT_FAILURE;
    }

    if (setup_log() < 0) {
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    if (clock_gettime(CLOCK_MONOTONIC, &window_start) < 0) {
        perror("clock_gettime");
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_rising_edge_events(g_line, "mlx90217-rpm") < 0) {
        perror("gpiod_line_request_rising_edge_events (second time)");
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    if (clock_gettime(CLOCK_MONOTONIC, &window_end) < 0) {
        perror("clock_gettime");
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    while (g_running) {
        struct timespec now;
        if (clock_gettime(CLOCK_MONOTONIC, &now) < 0) {
            perror("clock_gettime");
            break;
        }

        if (now.tv_sec - window_start >= WINDOW_SEC) {
            if (first_window) {
                last_count = pulse_count;
                first_window = 0;
            }

            int delta = pulse_count - last_count;
            int rpm = (delta > 0) ? (60 * delta) / WINDOW_SEC : 0;

            log_rpm(rpm);

            if (clock_gettime(CLOCK_MONOTONIC, &window_start) < 0) {
                perror("clock_gettime");
                break;
            }
        }

        /* Sleep for the remainder of the sample interval */
        struct timespec sleep_ts;
        sleep_ts.tv_sec = SAMPLE_INTERVAL_SEC - (now.tv_sec - window_start);
        sleep_ts.tv_nsec = (now.tv_nsec - window_start.tv_nsec) + 1000000000L;
        if (sleep_ts.tv_nsec < 0) {
            sleep_ts.tv_sec--;
            sleep_ts.tv_nsec += 1000000000L;
        }
        nanosleep(&sleep_ts, NULL);
    }

    /* Disable the alert callback before tearing down */
    gpiod_line_release_alert(g_line);

    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }

    cleanup_gpio();
    return EXIT_SUCCESS;
}

