#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <errno.h>
#include <unistd.h>
#include <stdint.h>

#include <pigpio.h>

#define SENSOR_A_PIN 17
#define SENSOR_B_PIN 27
#define LOG_FILE "rotation_log.txt"
#define DEBOUNCE_US 1000
#define POLL_DELAY_US 10000

/* Quadrature state machine states */
typedef enum {
    Q_IDLE,
    Q_A_HIGH,
    Q_B_HIGH,
    Q_A_LOW,
    Q_B_LOW
} quadrature_state_t;

static quadrature_state_t g_quadrature_state = Q_IDLE;
static pthread_mutex_t g_state_mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t g_state_cond = PTHREAD_COND_INITIALIZER;
static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void log_rotation_event(const char *direction) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[40];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp),
             sizeof(timestamp) - strlen(timestamp),
             ".%03ld", ts.tv_nsec / 1000000);

    if (g_log_file != NULL) {
        fprintf(g_log_file, "%s - %s\n", timestamp, direction);
        fflush(g_log_file);
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

static void isr_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio;
    (void)tick;
    (void)userdata;

    if (level == PI_OFF) {
        return; /* Ignore inactive pin */
    }

    pthread_mutex_lock(&g_state_mutex);
    g_quadrature_state = (quadrature_state_t)level;
    pthread_cond_signal(&g_state_cond);
    pthread_mutex_unlock(&g_state_mutex);
}

static void *rotation_monitor_thread(void *arg) {
    (void)arg;

    if (gpioSetISRFuncEx(SENSOR_A_PIN, EITHER_EDGE, 0, isr_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR for sensor A (GPIO %d)\n", SENSOR_A_PIN);
        return NULL;
    }

    if (gpioSetISRFuncEx(SENSOR_B_PIN, EITHER_EDGE, 0, isr_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR for sensor B (GPIO %d)\n", SENSOR_B_PIN);
        gpioSetISRFuncEx(SENSOR_A_PIN, EITHER_EDGE, 0, NULL, NULL);
        return NULL;
    }

    pthread_mutex_lock(&g_state_mutex);
    g_quadrature_state = Q_IDLE;
    pthread_cond_signal(&g_state_cond);
    pthread_mutex_unlock(&g_state_mutex);

    while (g_running) {
        pthread_mutex_lock(&g_state_mutex);
        quadrature_state_t current = g_quadrature_state;
        pthread_mutex_unlock(&g_state_mutex);

        if (current == Q_IDLE) {
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        /* Quadrature decoding: A -> B = 90° electrical offset */
        if (current == Q_A_HIGH && g_quadrature_state == Q_B_HIGH) {
            log_rotation_event("Clockwise");
        } else if (current == Q_B_HIGH && g_quadrature_state == Q_A_HIGH) {
            log_rotation_event("Counter-clockwise");
        }

        /* Consume the event to prevent re-entry */
        g_quadrature_state = Q_IDLE;
        pthread_cond_signal(&g_state_cond);
    }

    gpioSetISRFuncEx(SENSOR_A_PIN, EITHER_EDGE, 0, NULL, NULL);
    gpioSetISRFuncEx(SENSOR_B_PIN, EITHER_EDGE, 0, NULL, NULL);
    pthread_mutex_lock(&g_state_mutex);
    g_quadrature_state = Q_IDLE;
    pthread_cond_signal(&g_state_cond);
    pthread_mutex_unlock(&g_state_mutex);
    return NULL;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_A_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_A_PIN);
        goto cleanup;
    }
    if (gpioSetMode(SENSOR_B_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_B_PIN);
        goto cleanup;
    }
    if (gpioSetPullUpDown(SENSOR_A_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", SENSOR_A_PIN);
        goto cleanup;
    }
    if (gpioSetPullUpDown(SENSOR_B_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", SENSOR_B_PIN);
        goto cleanup;
    }

    if (pthread_mutex_init(&g_state_mutex, NULL) != 0) {
        fprintf(stderr, "Mutex initialization failed\n");
        goto cleanup;
    }
    if (pthread_cond_init(&g_state_cond, NULL) != 0) {
        fprintf(stderr, "Condvar initialization failed\n");
        goto cleanup;
    }

    if (rotation_monitor_thread != NULL) {
        rotation_monitor_thread = pthread_create(NULL, NULL, rotation_monitor_thread, NULL);
        if (rotation_monitor_thread == NULL) {
            fprintf(stderr, "Failed to create rotation monitor thread\n");
            goto cleanup;
        }
    }

    printf("Rotation detection started. Press Ctrl+C to exit.\n");

    while (g_running) {
        gpioDelay(100000); /* 100 ms */
    }

cleanup:
    printf("\nShutting down...\n");
    pthread_mutex_lock(&g_state_mutex);
    g_running = 0;
    pthread_cond_signal(&g_state_cond);
    pthread_mutex_unlock(&g_state_mutex);

    if (rotation_monitor_thread != NULL) {
        pthread_join(rotation_monitor_thread, NULL);
    }

    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }

    gpioTerminate();
    pthread_mutex_destroy(&g_state_mutex);
    pthread_cond_destroy(&g_state_cond);
    return EXIT_SUCCESS;
}

