#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 23
#define LED_PIN          18
#define POLL_DELAY_US    50000   /* 50 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed: %s", strerror(errno));
        return -1;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO%d as input: %s", TOUCH_SENSOR_PIN, strerror(errno));
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO%d as output: %s", LED_PIN, strerror(errno));
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(LED_PIN, 0) != 0) {
        syslog(LOG_ERR, "Failed to initialise LED state on GPIO%d: %s", LED_PIN, strerror(errno));
        gpioTerminate();
        return -1;
    }

    syslog(LOG_INFO, "GPIO initialised: touch=GPIO%d, LED=GPIO%d", TOUCH_SENSOR_PIN, LED_PIN);
    return 0;
}

static void cleanup_gpio(void)
{
    syslog(LOG_INFO, "Cleaning up GPIO resources...");
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    syslog(LOG_INFO, "GPIO resources released.");
}

int main(void)
{
    openlog("touch_sensor_app", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to register SIGINT handler: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to register SIGTERM handler: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialisation failed, exiting.");
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Touch sensor application started.");

    while (g_running) {
        int sensor_value = gpioRead(TOUCH_SENSOR_PIN);
        if (sensor_value < 0) {
            syslog(LOG_ERR, "Failed to read touch sensor on GPIO%d: %s", TOUCH_SENSOR_PIN, strerror(errno));
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        if (sensor_value == 1) {
            if (gpioWrite(LED_PIN, 1) != 0) {
                syslog(LOG_ERR, "Failed to turn LED on GPIO%d: %s", LED_PIN, strerror(errno));
            } else {
                syslog(LOG_INFO, "Touch detected on GPIO%d, LED on GPIO%d turned ON", TOUCH_SENSOR_PIN, LED_PIN);
            }
        } else {
            if (gpioWrite(LED_PIN, 0) != 0) {
                syslog(LOG_ERR, "Failed to turn LED off GPIO%d: %s", LED_PIN, strerror(errno));
            } else {
                syslog(LOG_INFO, "Touch released on GPIO%d, LED on GPIO%d turned OFF", TOUCH_SENSOR_PIN, LED_PIN);
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    syslog(LOG_INFO, "Shutting down touch sensor application.");
    cleanup_gpio();
    closelog();
    return EXIT_SUCCESS;
}

