#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 17
#define LED_PIN          18
#define DEBOUNCE_US      50000   /* 50 ms in microseconds */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

int main(void)
{
    int rc;

    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    rc = gpioInitialise();
    if (rc < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d).\n", rc);
        return EXIT_FAILURE;
    }

    /* --- Configure LED pin as output and drive it LOW --- */
    rc = gpioSetMode(LED_PIN, PI_OUTPUT);
    if (rc != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output (code %d).\n",
                LED_PIN, rc);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    rc = gpioWrite(LED_PIN, 0);
    if (rc != 0) {
        fprintf(stderr, "Error: failed to write LOW to GPIO%d (code %d).\n",
                LED_PIN, rc);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Configure touch sensor pin as input --- */
    rc = gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    if (rc != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input (code %d).\n",
                TOUCH_SENSOR_PIN, rc);
        gpioWrite(LED_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Main event loop --- */
    while (running) {
        /* Wait for a rising edge on the touch sensor line */
        rc = gpioEventWait(TOUCH_SENSOR_PIN, RISING_EDGE, 0);
        if (rc < 0) {
            fprintf(stderr, "Error: gpioEventWait failed on GPIO%d (code %d).\n",
                    TOUCH_SENSOR_PIN, rc);
            break;
        }
        if (rc == 0) {
            /* Timeout — no event; loop and check running flag */
            continue;
        }

        /* Read the current state of the touch sensor */
        int touch_state = gpioRead(TOUCH_SENSOR_PIN);
        if (touch_state < 0) {
            fprintf(stderr, "Error: gpioRead failed on GPIO%d (code %d).\n",
                    TOUCH_SENSOR_PIN, touch_state);
            break;
        }

        /* Debounce: ignore additional edges for DEBOUNCE_US microseconds */
        gpioDelay(DEBOUNCE_US);

        /* Toggle the LED */
        int led_state = !gpioRead(LED_PIN);
        if (gpioWrite(LED_PIN, led_state) != 0) {
            fprintf(stderr, "Error: gpioWrite failed on GPIO%d (code %d).\n",
                    LED_PIN, led_state);
            break;
        }
    }

    /* --- Clean shutdown --- */
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

