#include <pigpio.h>

#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17
#define LED_1_PIN   27
#define LED_2_PIN   22
#define BUFFER_SIZE 100
#define DEBOUNCE_US 50000  /* 50 ms */

typedef struct {
    int sensor_pin;
    time_t timestamp;
    int state;
} LogEntry;

static LogEntry log_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;
static int overflow_count = 0;
static volatile sig_atomic_t shutdown_requested = 0;

static void signal_handler(int sig) {
    (void)sig;
    shutdown_requested = 1;
}

static void log_event(int sensor_pin, int state) {
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed\n");
        return;
    }

    log_buffer[buffer_index].sensor_pin = sensor_pin;
    log_buffer[buffer_index].timestamp = now;
    log_buffer[buffer_index].state = state;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    } else {
        overflow_count++;
    }
}

static void print_log(void) {
    printf("\n--- Log Buffer (overflows: %d) ---\n", overflow_count);
    int start = (buffer_count < BUFFER_SIZE) ? 0 : buffer_index;
    for (int i = 0; i < buffer_count; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        char tbuf[32];
        struct tm tm_info;
        if (localtime_r(&log_buffer[idx].timestamp, &tm_info) != NULL) {
            strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm_info);
        } else {
            snprintf(tbuf, sizeof(tbuf), "unknown");
        }
        printf("  [%2d] Sensor: %d  State: %d  Timestamp: %s\n",
               i, log_buffer[idx].sensor_pin,
               log_buffer[idx].state, tbuf);
    }
    printf("--- End of Log ---\n\n");
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SENSOR_1_PIN);
        return -1;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SENSOR_2_PIN);
        return -1;
    }
    if (gpioSetMode(LED_1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", LED_1_PIN);
        return -1;
    }
    if (gpioSetMode(LED_2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", LED_2_PIN);
        return -1;
    }

    /* Start with LEDs off */
    if (gpioWrite(LED_1_PIN, 0) != 0) {
        fprintf(stderr, "Failed to write GPIO%d\n", LED_1_PIN);
        return -1;
    }
    if (gpioWrite(LED_2_PIN, 0) != 0) {
        fprintf(stderr, "Failed to write GPIO%d\n", LED_2_PIN);
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void) {
    /* Best-effort LED off */
    gpioWrite(LED_1_PIN, 0);
    gpioWrite(LED_2_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");
    printf("  Sensor 1: GPIO%d  |  Sensor 2: GPIO%d  |  LED 1: GPIO%d  |  LED 2: GPIO%d\n",
           SENSOR_1_PIN, SENSOR_2_PIN, LED_1_PIN, LED_2_PIN);
    fflush(stdout);

    int prev_state_1 = -1;
    int prev_state_2 = -1;

    while (!shutdown_requested) {
        int state_1 = gpioRead(SENSOR_1_PIN);
        int state_2 = gpioRead(SENSOR_2_PIN);

        if (state_1 < 0 || state_2 < 0) {
            fprintf(stderr, "gpioRead failed (s1=%d, s2=%d)\n", state_1, state_2);
            gpioDelay(DEBOUNCE_US);
            continue;
        }

        /* Sensor 1 */
        if (state_1 != prev_state_1) {
            if (state_1 == 1) {
                if (gpioWrite(LED_1_PIN, 1) != 0) {
                    fprintf(stderr, "Failed to write LED 1\n");
                }
                log_event(SENSOR_1_PIN, 1);
                printf("Sensor 1 touched (state=%d)\n", state_1);
            } else {
                if (gpioWrite(LED_1_PIN, 0) != 0) {
                    fprintf(stderr, "Failed to write LED 1\n");
                }
                log_event(SENSOR_1_PIN, 0);
                printf("Sensor 1 released (state=%d)\n", state_1);
            }
            prev_state_1 = state_1;
        }

        /* Sensor 2 */
        if (state_2 != prev_state_2) {
            if (state_2 == 1) {
                if (gpioWrite(LED_2_PIN, 1) != 0) {
                    fprintf(stderr, "Failed to write LED 2\n");
                }
                log_event(SENSOR_2_PIN, 1);
                printf("Sensor 2 touched (state=%d)\n", state_2);
            } else {
                if (gpioWrite(LED_2_PIN, 0) != 0) {
                    fprintf(stderr, "Failed to write LED 2\n");
                }
                log_event(SENSOR_2_PIN, 0);
                printf("Sensor 2 released (state=%d)\n", state_2);
            }
            prev_state_2 = state_2;
        }

        gpioDelay(DEBOUNCE_US);
    }

    printf("\nShutting down...\n");
    print_log();
    cleanup_gpio();
    printf("Cleanup complete. Exiting.\n");
    return EXIT_SUCCESS;
}

