#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR1_PIN 17
#define SENSOR2_PIN 18
#define DEBOUNCE_MS 5
#define LOG_FILE "shaft_log.txt"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor(int pin) {
    int val = gpioRead(pin);
    if (val < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", pin, pigpio_error(val));
        return -1;
    }
    return val;
}

static void log_data(int s1, int s2) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%d,%d\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, s1, s2);
    } else {
        fprintf(stderr, "localtime_r failed\n");
    }
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(SENSOR1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR1_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SENSOR2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR2_PIN);
        gpioTerminate();
        return 1;
    }

    int prev1 = -1, prev2 = -1;
    int armed = 0;

    while (running) {
        int s1 = read_sensor(SENSOR1_PIN);
        int s2 = read_sensor(SENSOR2_PIN);

        if (s1 < 0 || s2 < 0) {
            gpioDelay(100000);
            continue;
        }

        if (armed) {
            if (s1 != prev1) {
                gpioDelay(DEBOUNCE_MS * 1000);
                s1 = read_sensor(SENSOR1_PIN);
                if (s1 < 0) {
                    gpioDelay(100000);
                    continue;
                }
                if (s1 != prev1) {
                    log_data(prev1, prev2);
                    prev1 = s1;
                    armed = 0;
                }
            }
            if (s2 != prev2) {
                gpioDelay(DEBOUNCE_MS * 1000);
                s2 = read_sensor(SENSOR2_PIN);
                if (s2 < 0) {
                    gpioDelay(100000);
                    continue;
                }
                if (s2 != prev2) {
                    log_data(prev1, prev2);
                    prev2 = s2;
                    armed = 0;
                }
            }
        } else {
            prev1 = s1;
            prev2 = s2;
            armed = 1;
        }

        if (armed) {
            int rpm = 60.0 / ((double)(s1 - prev1) + ((double)(s2 - prev2)));
            printf("RPM: %.2f\n", rpm);
        }

        gpioDelay(10000);
    }

    gpioTerminate();
    return 0;
}

