/*
 * seismic.c — Raspberry Pi 3 Model B+ seismic monitor using an Omron D7S‑A0011
 *
 * Wiring:
 *   SDA  -> GPIO2 (BCM 2, I2C bus 1)
 *   SCL  -> GPIO3 (BCM 3, I2C bus 1)
 *   LED  -> GPIO17 (BCM 17) via ~330 Ω resistor to GND
 *
 * Build:
 *   gcc -O2 -Wall -o seismic seismic.c -l<driver_library> -lm -lrt
 *
 * Threshold: 500 (Euclidean magnitude)
 * LED on-time: 1 s per event
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <math.h>
#include <unistd.h>

#include <pigpio.h>

/* ---- Configuration ---- */
#define I2C_BUS              1
#define I2C_ADDR             0x50          /* D7S-A0011 default I2C address */
#define LED_GPIO             17
#define VIBRATION_THRESHOLD  500
#define LED_ON_TIME_SEC      1
#define POLL_INTERVAL_US     100000        /* 100 ms */
#define MAX_RETRIES          3
#define LOG_FILE             "seismic_events.log"

/* D7S register addresses (16-bit, big-endian on the bus) */
#define REG_CTRL1            0x00
#define REG_X1_LSB           0x04
#define REG_X1_MSB           0x05
#define REG_X2_LSB           0x06
#define REG_X2_MSB           0x07
#define REG_X3_LSB           0x08
#define REG_X3_MSB           0x09
#define REG_Y1_LSB           0x0A
#define REG_Y1_MSB           0x0B
#define REG_Y2_LSB           0x0C
#define REG_Y2_MSB           0x0D
#define REG_Y3_LSB           0x0E
#define REG_Y3_MSB           0x0F

/* CTRL1 bit layout: PD=0x80 (power-down), ODR=0x40 (1 Hz), SIM=0x20 (SIM) */
#define CTRL1_POWER_DOWN     0x80
#define CTRL1_ODR_1HZ        0x40
#define CTRL1_SIM           0x20

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ---- */
static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (char)value;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cWriteDevice(handle, buf, 3);
        if (rc == 0)
            return 0;
        fprintf(stderr, "i2c_write_reg16(0x%04X, 0x%02X) attempt %d failed (rc=%d): %s\n",
                reg, value, attempt + 1, rc, strerror(errno));
        gpioDelay(10000); /* 10 ms back-off */
    }
    return -1;
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint32_t len)
{
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cWriteDevice(handle, reg_buf, 2);
        if (rc != 0) {
            fprintf(stderr, "i2c_read_reg16 write(0x%04X) attempt %d failed (rc=%d): %s\n",
                    reg, attempt + 1, rc, strerror(errno));
            gpioDelay(10000);
            continue;
        }

        rc = i2cReadDevice(handle, (char *)buf, len);
        if (rc == (int)len)
            return 0;
        fprintf(stderr, "i2c_read_reg16 read(0x%04X, %u) attempt %d failed (rc=%d): %s\n",
                reg, len, attempt + 1, rc, strerror(errno));
        gpioDelay(10000);
    }
    return -1;
}

/* ---- Sensor data ---- */
typedef struct {
    int16_t x1, x2, x3;
    int16_t y1, y2, y3;
} sensor_data_t;

static int init_sensor(int handle)
{
    uint8_t ctrl1 = 0;

    /* Verify sensor presence by reading CTRL1 */
    if (i2c_read_reg16(handle, REG_CTRL1, &ctrl1, 1) != 0) {
        fprintf(stderr, "Sensor not responding on I2C bus %d addr 0x%02X\n",
                I2C_BUS, I2C_ADDR);
        return -1;
    }

    /* Clear power-down bit and set 1 Hz ODR + SIM */
    if (i2c_write_reg16(handle, REG_CTRL1, CTRL1_POWER_DOWN | CTRL1_ODR_1HZ | CTRL1_SIM) != 0) {
        fprintf(stderr, "Failed to configure sensor CTRL1\n");
        return -1;
    }

    gpioDelay(50000); /* 50 ms settle */
    return 0;
}

static int read_sensor_data(int handle, sensor_data_t *data)
{
    uint8_t buf[18];

    if (i2c_read_reg16(handle, REG_X1_LSB, buf, sizeof(buf)) != 0)
        return -1;

    data->x1 = (int16_t)((buf[1] << 8) | buf[0]);
    data->x2 = (int16_t)((buf[3] << 8) | buf[2]);
    data->x3 = (int16_t)((buf[5] << 8) | buf[4]);
    data->y1 = (int16_t)((buf[7] << 8) | buf[6]);
    data->y2 = (int16_t)((buf[9] << 8) | buf[8]);
    data->y3 = (int16_t)((buf[11] << 8) | buf[10]);

    return 0;
}

static double calculate_magnitude(const sensor_data_t *d)
{
    double x1 = (double)d->x1;
    double x2 = (double)d->x2;
    double x3 = (double)d->x3;
    double y1 = (double)d->y1;
    double y2 = (double)d->y2;
    double y3 = (double)d->y3;

    double x_mag = sqrt(x1 * x1 + x2 * x2 + x3 * x3);
    double y_mag = sqrt(y1 * y1 + y2 * y2 + y3 * y3);

    return sqrt(x_mag * x_mag + y_mag * y_mag);
}

/* ---- Logging ---- */
static void log_event(FILE *fp, double magnitude)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f\n", ts, magnitude);
    fflush(fp);
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

/* ---- Main ---- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure LED */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d) failed\n", LED_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (init_sensor(g_i2c_handle) != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Seismic monitoring started. Threshold=%d, LED on GPIO%d. Ctrl+C to exit.\n",
           VIBRATION_THRESHOLD, LED_GPIO);

    /* Main loop */
    while (g_running) {
        sensor_data_t data;

        if (read_sensor_data(g_i2c_handle, &data) != 0) {
            fprintf(stderr, "Sensor read error — continuing\n");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        double magnitude = calculate_magnitude(&data);

        if (magnitude > VIBRATION_THRESHOLD) {
            log_event(g_log_file, magnitude);

            /* Turn LED on */
            gpioWrite(LED_GPIO, 1);
            gpioDelay(LED_ON_TIME_SEC * 1000000);
            gpioWrite(LED_GPIO, 0);
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

