#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define SENSOR3_PIN 27
#define SENSOR4_PIN 22
#define LED_PIN    18

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int setup_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    int pins[4] = { SENSOR1_PIN, SENSOR2_PIN, SENSOR3_PIN, SENSOR4_PIN };
    for (int i = 0; i < 4; i++) {
        if (gpioSetMode(pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO%d as input.\n", pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioSetPullUpDown(pins[i], PI_PUD_UP) != 0) {
            fprintf(stderr, "Warning: failed to set pull-up on GPIO%d.\n", pins[i]);
        }
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", LED_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise LED state on GPIO%d.\n", LED_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void)
{
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (setup_gpio() != 0) {
        return EXIT_FAILURE;
    }

    while (g_running) {
        int any_detected = 0;

        int v1 = gpioRead(SENSOR1_PIN);
        int v2 = gpioRead(SENSOR2_PIN);
        int v3 = gpioRead(SENSOR3_PIN);
        int v4 = gpioRead(SENSOR4_PIN);

        if (v1 < 0 || v2 < 0 || v3 < 0 || v4 < 0) {
            fprintf(stderr, "Error: failed to read sensor GPIOs.\n");
            break;
        }

        if (v1 == 0 || v2 == 0 || v3 == 0 || v4 == 0) {
            any_detected = 1;
        }

        if (gpioWrite(LED_PIN, any_detected) != 0) {
            fprintf(stderr, "Error: failed to write LED state on GPIO%d.\n", LED_PIN);
            break;
        }

        gpioDelay(50000); /* 50 ms */
    }

    cleanup_gpio();
    return EXIT_SUCCESS;
}

