/*
 * flame_monitor.c — Continuous flame sensor monitoring using libgpiod.
 *
 * Build:  gcc -O2 -Wall -Wextra -o flame_monitor flame_monitor.c -lgpiod
 * Run:    sudo ./flame_monitor
 *
 * Hardware (Raspberry Pi 3 Model B+):
 *   BCM GPIO 2, 3, 4, 17, 27  -> Keyes KY-026 digital output pins
 *   (physical pins 3, 5, 7, 11, 13)
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <syslog.h>
#include <gpiod.h>

#define NUM_SENSORS      5
#define DEBOUNCE_MS      50
#define POLL_INTERVAL_S  1
#define LOG_FILE         "/var/log/flame_events.log"

static const unsigned int sensor_pins[NUM_SENSORS] = {2, 3, 4, 17, 27};

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_event(int sensor_id, unsigned int pin)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        syslog(LOG_ERR, "time() failed: %s", strerror(errno));
        return;
    }

    struct tm tm_utc;
    if (gmtime_r(&now, &tm_utc) == NULL) {
        syslog(LOG_ERR, "gmtime_r() failed");
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        syslog(LOG_ERR, "strftime() failed");
        return;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        syslog(LOG_ERR, "Cannot open %s: %s", LOG_FILE, strerror(errno));
        return;
    }

    if (flock(fileno(fp), LOCK_EX) == -1) {
        syslog(LOG_ERR, "flock(LOCK_EX) failed: %s", strerror(errno));
        fclose(fp);
        return;
    }

    if (fprintf(fp, "%s - Sensor ID: %d (GPIO %u) - Flame Detected\n",
                ts, sensor_id, pin) < 0) {
        syslog(LOG_ERR, "fprintf() failed: %s", strerror(errno));
    } else {
        if (fflush(fp) == EOF) {
            syslog(LOG_ERR, "fflush() failed: %s", strerror(errno));
        }
    }

    if (flock(fileno(fp), LOCK_UN) == -1) {
        syslog(LOG_ERR, "flock(LOCK_UN) failed: %s", strerror(errno));
    }

    if (fclose(fp) != 0) {
        syslog(LOG_ERR, "fclose() failed: %s", strerror(errno));
    }

    syslog(LOG_INFO, "Flame detected on sensor %d (GPIO %u)", sensor_id, pin);
}

int main(void)
{
    openlog("flame_monitor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting flame monitor (libgpiod)");

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        syslog(LOG_ERR, "sigaction(SIGINT) failed: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        syslog(LOG_ERR, "sigaction(SIGTERM) failed: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "gpiod_chip_open_by_name(gpiochip0) failed: %s",
               strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_line *lines[NUM_SENSORS];
    for (int i = 0; i < NUM_SENSORS; i++) {
        lines[i] = NULL;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (!lines[i]) {
            syslog(LOG_ERR, "gpiod_chip_get_line(%u) failed: %s",
                   sensor_pins[i], strerror(errno));
            for (int j = 0; j < i; j++) {
                gpiod_line_release(lines[j]);
            }
            gpiod_chip_close(chip);
            closelog();
            return EXIT_FAILURE;
        }

        if (gpiod_line_request_input(lines[i], "flame_monitor") < 0) {
            syslog(LOG_ERR, "gpiod_line_request_input(%u) failed: %s",
                   sensor_pins[i], strerror(errno));
            for (int j = 0; j <= i; j++) {
                gpiod_line_release(lines[j]);
            }
            gpiod_chip_close(chip);
            closelog();
            return EXIT_FAILURE;
        }
    }

    syslog(LOG_INFO, "Monitoring %d flame sensors on BCM GPIO %u, %u, %u, %u, %u",
           NUM_SENSORS, sensor_pins[0], sensor_pins[1], sensor_pins[2],
           sensor_pins[3], sensor_pins[4]);

    int prev_state[NUM_SENSORS] = {1, 1, 1, 1, 1};

    while (g_running) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            int val = gpiod_line_get_value(lines[i]);
            if (val < 0) {
                syslog(LOG_ERR, "gpiod_line_get_value(%u) failed: %s",
                       sensor_pins[i], strerror(errno));
                continue;
            }

            if (val == 0 && prev_state[i] == 1) {
                /* Debounce: re-read after 50 ms */
                struct timespec ts = {0, DEBOUNCE_MS * 1000000L};
                nanosleep(&ts, NULL);
                int deb_val = gpiod_line_get_value(lines[i]);
                if (deb_val < 0) {
                    syslog(LOG_ERR, "gpiod_line_get_value(%u) (debounce) failed: %s",
                           sensor_pins[i], strerror(errno));
                    continue;
                }
                if (deb_val == 0) {
                    log_event(i + 1, sensor_pins[i]);
                }
            }
            prev_state[i] = val;
        }

        sleep(POLL_INTERVAL_S);
    }

    syslog(LOG_INFO, "Shutting down flame monitor");
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    gpiod_chip_close(chip);
    closelog();

    return EXIT_SUCCESS;
}

