 * Wiring (BCM GPIO):
 *   OUT0 -> GPIO5  (physical pin 29)
 *   OUT1 -> GPIO6  (physical pin 31)
 *   OUT2 -> GPIO13 (physical pin 33)
 *   OUT3 -> GPIO19 (physical pin 35)
 *   OUT4 -> GPIO26 (physical pin 37)
 *   OUT5 -> GPIO12 (physical pin 32)
 *   OUT6 -> GPIO16 (physical pin 36)
 *   OUT7 -> GPIO20 (physical pin 38)
 *
 * Build: gcc -Wall -Wextra -O2 -o ttp226 ttp226.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_US 50000   /* 50 ms */

static const unsigned int touch_pins[NUM_CHANNELS] = {
    5, 6, 13, 19, 26, 12, 16, 20
};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signum)
{
    (void)signum;
    program_running = 0;
}

static void print_timestamp(void)
{
    time_t rawtime;
    struct tm timeinfo;
    char buffer[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) != NULL &&
        strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%S", &timeinfo) > 0) {
        printf("[%s] ", buffer);
    } else {
        printf("[unknown-time] ");
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_CHANNELS];
    struct gpiod_line_request_config req_cfg;
    struct gpiod_line_request *request = NULL;
    int prev_state[NUM_CHANNELS];
    int ret = EXIT_FAILURE;

    memset(lines, 0, sizeof(lines));
    memset(prev_state, 0, sizeof(prev_state));

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi 3 B+) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Resolve each touch pin line */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, touch_pins[i]);
        if (lines[i] == NULL) {
            fprintf(stderr, "Failed to get GPIO line %u: %s\n",
                    touch_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    /* Configure all lines as inputs */
    memset(&req_cfg, 0, sizeof(req_cfg));
    req_cfg.consumer = "ttp226-touch-reader";
    req_cfg.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    if (gpiod_line_request_bulk(lines, NUM_CHANNELS, &req_cfg, 0) < 0) {
        fprintf(stderr, "Failed to request GPIO lines as inputs: %s\n",
                strerror(errno));
        goto cleanup;
    }

    printf("TTP226 touch sensor reader started. Press Ctrl-C to exit.\n");

    /* Main polling loop */
    while (program_running) {
        int current_state[NUM_CHANNELS];

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int val = gpiod_line_get_value(lines[i]);
            if (val < 0) {
                fprintf(stderr, "Failed to read GPIO line %u: %s\n",
                        touch_pins[i], strerror(errno));
                goto cleanup;
            }
            current_state[i] = val;
        }

        /* Log only on state change */
        for (int i = 0; i < NUM_CHANNELS; i++) {
            if (current_state[i] != prev_state[i]) {
                print_timestamp();
                printf("Channel %d (GPIO %u) %s\n",
                       i + 1, touch_pins[i],
                       current_state[i] ? "TOUCH_DETECTED" : "TOUCH_RELEASED");
                prev_state[i] = current_state[i];
            }
        }

        usleep(POLL_INTERVAL_US);
    }

    printf("\nShutting down cleanly.\n");
    ret = EXIT_SUCCESS;

cleanup:
    /* Release the line request (bulk release is safe on NULL chip) */
    if (request != NULL) {
        gpiod_line_request_release(request);
    }
    /* Lines are released automatically when the request is freed */
    return ret;
}

