#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS "/dev/i2c-1"
#define VEML7700_ADDR 0x30
#define VEML7700_CONFIG_REG 0x00
#define VEML7700_LUX_REG 0x04
#define GROW_LIGHT_GPIO 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000
#define LOG_FILE "grow_log.txt"
#define SAMPLE_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3] = { reg, (uint8_t)(value >> 8), (uint8_t)(value & 0xFF) };
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int veml7700_init(int fd) {
    if (i2c_write_reg16(fd, VEML7700_CONFIG_REG, 0x0000) < 0) {
        fprintf(stderr, "Failed to initialize VEML7700 (sensor absent or bus error)\n");
        return -1;
    }
    return 0;
}

static int veml7700_read_lux(int fd, uint16_t *lux) {
    return i2c_read_reg16(fd, VEML7700_LUX_REG, lux);
}

static int calculate_brightness(uint16_t lux) {
    if (lux < 100) return 100;
    if (lux < 500) return 75;
    if (lux < 1000) return 50;
    return 25;
}

static int set_led_brightness(int gpio, int brightness) {
    if (brightness < 0) brightness = 0;
    if (brightness > 100) brightness = 100;
    int duty = (brightness * PWM_RANGE) / 100;
    if (gpioPWM(gpio, duty) < 0) {
        fprintf(stderr, "gpioPWM failed on GPIO %d\n", gpio);
        return -1;
    }
    return 0;
}

static void log_data(FILE *fp, uint16_t lux, int brightness, int error_code) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s, Lux: %u, Brightness: %d, Error: %d\n", timestamp, lux, brightness, error_code);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handlers: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (veml7700_init(i2c_fd) < 0) {
        fprintf(stderr, "VEML7700 initialization failed. Check sensor wiring and I2C address.\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(GROW_LIGHT_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GROW_LIGHT_GPIO);
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(GROW_LIGHT_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", GROW_LIGHT_GPIO);
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMrange(GROW_LIGHT_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", GROW_LIGHT_GPIO);
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    printf("Grow light system started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t lux = 0;
        if (veml7700_read_lux(i2c_fd, &lux) < 0) {
            log_data(log_file, 0, 0, 1);
        } else {
            int brightness = calculate_brightness(lux);
            if (set_led_brightness(GROW_LIGHT_GPIO, brightness) < 0) {
                log_data(log_file, lux, brightness, 2);
            } else {
                log_data(log_file, lux, brightness, 0);
            }
        }
        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    set_led_brightness(GROW_LIGHT_GPIO, 0);
    if (i2c_fd >= 0) close(i2c_fd);
    if (log_file != NULL) fclose(log_file);
    gpioTerminate();
    printf("Cleanup complete.\n");
    return 0;
}

