#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_PIN 4          /* BCM GPIO4, physical pin 7 */
#define LOG_FILE "touch_log.txt"
#define DEBOUNCE_US 50000    /* 50 ms debounce window */
#define POLL_DELAY_US 10000  /* 10 ms polling interval */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop can exit cleanly             */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped touch event to the log file                    */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int log_touch_event(FILE *fp, int is_pressed)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }

    if (fprintf(fp, "%s: %s\n", timestamp, is_pressed ? "Touch Detected" : "Touch Released") < 0) {
        fprintf(stderr, "fprintf() to log file failed\n");
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush() failed\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — release GPIO resources and close file              */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    int last_state = 0;
    int current_state;
    int rc = EXIT_SUCCESS;

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure touch pin as input with pull-down ---- */
    if (gpioSetMode(TOUCH_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for pin %d\n", TOUCH_PIN);
        rc = EXIT_FAILURE;
        goto cleanup;
    }

    if (gpioSetPullUpDown(TOUCH_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "gpioSetPullUpDown failed for pin %d\n", TOUCH_PIN);
        rc = EXIT_FAILURE;
        goto cleanup;
    }

    /* ---- Open log file for appending ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        rc = EXIT_FAILURE;
        goto cleanup;
    }

    fprintf(stderr, "Touch sensor monitoring started on GPIO%d. "
                    "Logging to %s. Press Ctrl+C to exit.\n",
            TOUCH_PIN, LOG_FILE);

    /* ---- Main polling loop ---- */
    while (g_running) {
        current_state = gpioRead(TOUCH_PIN);

        if (current_state < 0) {
            fprintf(stderr, "gpioRead failed on pin %d\n", TOUCH_PIN);
            rc = EXIT_FAILURE;
            break;
        }

        /* Detect rising edge (touch pressed) and falling edge (touch released) */
        if (current_state == 1 && last_state == 0) {
            if (log_touch_event(g_log_fp, 1) != 0) {
                rc = EXIT_FAILURE;
                break;
            }
        } else if (current_state == 0 && last_state == 1) {
            if (log_touch_event(g_log_fp, 0) != 0) {
                rc = EXIT_FAILURE;
                break;
            }
        }

        last_state = current_state;
        gpioDelay(DEBOUNCE_US);   /* 50 ms debounce / debounce + poll */
    }

    /* ---- Graceful shutdown ---- */
    fprintf(stderr, "\nShutting down...\n");
    cleanup();
    return rc;
}

