#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SLF3S_ADDR     0x0C
#define SLF3S_CMD      0x36
#define SLF3S_READ_LEN 3
#define SLF3S_MEAS_MS  2
#define SAMPLE_MS      1000
#define LOG_FILE       "cooling_log.csv"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_flow_rate(int fd, float *flow_rate) {
    uint8_t buf[SLF3S_READ_LEN];
    if (i2c_read_bytes(fd, buf, sizeof(buf)) < 0)
        return -1;

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch: calc=0x%02X recv=0x%02X\n",
                crc8(buf, 2), buf[2]);
        return -2;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *flow_rate = (float)raw;
    return 0;
}

static void log_data(FILE *fp, float flow_rate, uint16_t flags, const char *status) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%s\n", ts, flow_rate, status);
    fflush(fp);
}

static void cleanup(void) {
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SLF3S_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                SLF3S_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    fseek(g_log_fp, 0, SEEK_END);
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "Timestamp,Flow Rate (ml/min),Status\n");
        fflush(g_log_fp);
    }

    printf("SLF3S monitoring started. Press Ctrl+C to stop.\n");

    while (g_running) {
        if (i2c_write_cmd(g_i2c_fd, SLF3S_CMD) < 0) {
            log_data(g_log_fp, 0.0f, 0, "ERROR");
            usleep(SAMPLE_MS * 1000);
            continue;
        }

        usleep(SLF3S_MEAS_MS * 1000);

        float flow_rate = 0.0f;
        int rc = read_flow_rate(g_i2c_fd, &flow_rate);
        if (rc == 0) {
            uint16_t flags = 0;
            if (i2c_read_bytes(g_i2c_fd, (uint8_t *)&flags, 2) < 0) {
                log_data(g_log_fp, 0.0f, 0, "ERROR");
                usleep(SAMPLE_MS * 1000);
                continue;
            }
            if (flow_rate < 0.0f || flow_rate > 100.0f) {
                log_data(g_log_fp, flow_rate, flags, "INVALID");
            } else {
                log_data(g_log_fp, flow_rate, flags, "OK");
            }
        } else if (rc == -2) {
            log_data(g_log_fp, 0.0f, 0, "CRC_ERROR");
        } else {
            log_data(g_log_fp, 0.0f, 0, "I2C_ERROR");
        }

        usleep(SAMPLE_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

