#include <stdbool.h>
#include <pigpio.h>

#define LEFT_SENSOR_PIN 17
#define MIDDLE_SENSOR_PIN 27
#define RIGHT_SENSOR_PIN 22
#define LOG_FILE_NAME "path_log.csv"
#define SAMPLE_INTERVAL_US 50000  /* 50 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int get_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm timeinfo;

    if (time(&rawtime) == (time_t)-1) {
        return -1;
    }
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        return -1;
    }
    if (strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        return -1;
    }
    return 0;
}

static int log_data(FILE *fp, const char *timestamp,
                    int left, int middle, int right)
{
    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, left, middle, right) < 0) {
        return -1;
    }
    if (fflush(fp) != 0) {
        return -1;
    }
    return 0;
}

int main(void)
{
    FILE *fp = NULL;
    int left_val = -1, middle_val = -1, right_val = -1;
    int left_pin = -1, middle_pin = -1, right_pin = -1;
    int rc = EXIT_FAILURE;

    /* --- Install signal handler for clean shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler: %s\n",
                strerror(errno));
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Open log file (append mode) --- */
    fp = fopen(LOG_FILE_NAME, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n",
                LOG_FILE_NAME, strerror(errno));
        goto cleanup_gpio;
    }

    /* --- Configure GPIO pins as inputs --- */
    left_pin = gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT);
    if (left_pin < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n",
                LEFT_SENSOR_PIN);
        goto cleanup_all;
    }
    middle_pin = gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT);
    if (middle_pin < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n",
                MIDDLE_SENSOR_PIN);
        goto cleanup_all;
    }
    right_pin = gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT);
    if (right_pin < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n",
                RIGHT_SENSOR_PIN);
        goto cleanup_all;
    }

    /* --- Verify each pin was accepted --- */
    if (left_pin < 0 || middle_pin < 0 || right_pin < 0) {
        fprintf(stderr, "Error: one or more GPIO pin configuration failed.\n");
        goto cleanup_all;
    }

    printf("Polling KY-033 sensors on GPIO17, GPIO27, GPIO22 every 50 ms.\n");
    printf("Logging to '%s'. Press Ctrl+C to stop.\n", LOG_FILE_NAME);

    /* --- Main polling loop --- */
    while (g_running) {
        char timestamp[32];

        if (get_timestamp(timestamp, sizeof(timestamp)) != 0) {
            fprintf(stderr, "Warning: failed to generate timestamp.\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        left_val = gpioRead(LEFT_SENSOR_PIN);
        middle_val = gpioRead(MIDDLE_SENSOR_PIN);
        right_val = gpioRead(RIGHT_SENSOR_PIN);

        if (left_val < 0 || middle_val < 0 || right_val < 0) {
            fprintf(stderr, "Warning: GPIO read error (L=%d M=%d R=%d).\n",
                    left_val, middle_val, right_val);
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        if (log_data(fp, timestamp, left_val, middle_val, right_val) != 0) {
            fprintf(stderr, "Warning: failed to write to log file.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down cleanly...\n");
    rc = EXIT_SUCCESS;

cleanup_all:
    gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT);
    gpioTerminate();

cleanup_gpio:
    if (fp != NULL) {
        fflush(fp);
        fclose(fp);
    }

    return rc;
}

