#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>

#define TOUCH_SENSOR_PIN 23
#define LED_PIN          24
#define LOG_FILE         "touch_log.txt"
#define POLL_TIMEOUT_MS  1000
#define CONSUMER         "touch-lamp"

static volatile sig_atomic_t program_running = 1;
static int log_fd = -1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static int log_touch_event(int led_state)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    char log_entry[128];
    int len = snprintf(log_entry, sizeof(log_entry), "%s - Touch detected, LED: %s\n",
                       timestamp, led_state ? "ON" : "OFF");
    if (len < 0 || (size_t)len >= sizeof(log_entry)) {
        fprintf(stderr, "log_entry formatting failed\n");
        return -1;
    }

    if (write(log_fd, log_entry, (size_t)len) != (ssize_t)len) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fsync(log_fd) == -1) {
        fprintf(stderr, "fsync failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd == -1) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(log_fd, FIONBIO, &0) == -1) {
        fprintf(stderr, "Failed to set log file to non-blocking: %s\n", strerror(errno));
        close(log_fd);
        return EXIT_FAILURE;
    }

    struct gpio_chip *chip = gpio_chip_open("/dev/gpiochip4");
    if (chip == NULL) {
        fprintf(stderr, "Failed to open /dev/gpiochip4: %s\n", strerror(errno));
        close(log_fd);
        return EXIT_FAILURE;
    }

    struct gpio_line *touch_line = gpio_chip_get_line(chip, TOUCH_SENSOR_PIN);
    if (touch_line == NULL) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", TOUCH_SENSOR_PIN, strerror(errno));
        gpio_chip_close(chip);
        close(log_fd);
        return EXIT_FAILURE;
    }

    struct gpio_line *led_line = gpio_chip_get_line(chip, LED_PIN);
    if (led_line == NULL) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", LED_PIN, strerror(errno));
        gpio_chip_close(chip);
        close(log_fd);
        return EXIT_FAILURE;
    }

    if (gpio_line_request_input(touch_line, CONSUMER) < 0) {
        fprintf(stderr, "Failed to request touch sensor line as input: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpio_line_request_output(led_line, CONSUMER, 0) < 0) {
        fprintf(stderr, "Failed to request LED line as output: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Touch-activated lamp started. Press Ctrl+C to exit.\n");

    while (program_running) {
        struct timespec ts = { .tv_sec = 0, .tv_nsec = POLL_TIMEOUT_MS * 1000000L };
        int ret = gpio_line_event_wait(touch_line, &ts);

        if (ret < 0) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "gpio_line_event_wait failed: %s\n", strerror(errno));
            break;
        }

        if (ret == 0) {
            continue;
        }

        struct gpio_event event;
        if (gpio_line_event_read(touch_line, &event) < 0) {
            fprintf(stderr, "gpio_line_event_read failed: %s\n", strerror(errno));
            continue;
        }

        if (event.event_type != GPIO_EVENT_RISING_EDGE) {
            continue;
        }

        int led_state = gpio_line_get_value(led_line);
        if (led_state < 0) {
            fprintf(stderr, "Failed to read LED state: %s\n", strerror(errno));
            continue;
        }

        if (log_touch_event(led_state) < 0) {
            fprintf(stderr, "Failed to log touch event\n");
        }

        if (gpio_line_set_value(led_line, led_state ? 1 : 0) < 0) {
            fprintf(stderr, "Failed to set LED state: %s\n", strerror(errno));
        }
    }

cleanup:
    gpio_line_release(touch_line);
    gpio_line_release(led_line);
    gpio_chip_close(chip);
    if (log_fd != -1) {
        close(log_fd);
    }

    printf("Touch-activated lamp stopped.\n");
    return EXIT_SUCCESS;
}

