 *   gcc -Wall -Wextra -O2 -o flame_alert flame_alert.c -lgpiod
 *
 * Run:
 *   sudo ./flame_alert
 */

#include <errno.h>
#include <gpiod.h>
#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#define FLAME_PIN  17
#define BUZZER_PIN 18
#define LOG_FILE   "alert_log.txt"
#define POLL_MS    100
#define BUZZER_MS  2000
#define CHIP_NAME  "gpiochip0"

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static void log_event(FILE *fp, const char *msg)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }
    if (fprintf(fp, "[%s] %s\n", ts, msg) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *flame_line = NULL;
    struct gpiod_line *buzzer_line = NULL;
    FILE *log_fp = NULL;
    int ret = EXIT_FAILURE;

    /* --- signal handling ------------------------------------------ */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- open log file --------------------------------------------- */
    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- open GPIO chip and request lines -------------------------- */
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open_by_name(%s) failed: %s\n",
                CHIP_NAME, strerror(errno));
        goto cleanup;
    }

    flame_line = gpiod_chip_get_line(chip, FLAME_PIN);
    if (!flame_line) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n",
                FLAME_PIN, strerror(errno));
        goto cleanup;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n",
                BUZZER_PIN, strerror(errno));
        goto cleanup;
    }

    /* buzzer as output, initial LOW */
    if (gpiod_line_request_output(buzzer_line, "flame_alert", 0) != 0) {
        fprintf(stderr, "gpiod_line_request_output(%d) failed: %s\n",
                BUZZER_PIN, strerror(errno));
        goto cleanup;
    }

    /* flame sensor as input */
    if (gpiod_line_request_input(flame_line, "flame_alert") != 0) {
        fprintf(stderr, "gpiod_line_request_input(%d) failed: %s\n",
                FLAME_PIN, strerror(errno));
        goto cleanup;
    }

    /* --- main loop ------------------------------------------------ */
    int prev_flame = gpiod_line_get_value(flame_line);
    if (prev_flame < 0) {
        fprintf(stderr, "Initial gpiod_line_get_value(%d) failed: %s\n",
                FLAME_PIN, strerror(errno));
        goto cleanup;
    }

    log_event(log_fp, "System started");
    printf("Flame detection system started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int cur = gpiod_line_get_value(flame_line);
        if (cur < 0) {
            fprintf(stderr, "gpiod_line_get_value(%d) failed: %s\n",
                    FLAME_PIN, strerror(errno));
            break;
        }

        /* detect HIGH -> LOW transition (flame detected) */
        if (cur == 0 && prev_flame != 0) {
            printf("Flame detected!\n");
            if (gpiod_line_set_value(buzzer_line, 1) != 0) {
                fprintf(stderr, "gpiod_line_set_value(buzzer, 1) failed: %s\n",
                        strerror(errno));
            }
            log_event(log_fp, "FLAME DETECTED");
            /* buzzer on for 2 s, but break into 100 ms slices so we
               can respond to signals promptly */
            for (int ms = 0; ms < BUZZER_MS && g_running; ms += POLL_MS) {
                usleep(POLL_MS * 1000);
            }
            if (gpiod_line_set_value(buzzer_line, 0) != 0) {
                fprintf(stderr, "gpiod_line_set_value(buzzer, 0) failed: %s\n",
                        strerror(errno));
            }
        }

        prev_flame = cur;
        usleep(POLL_MS * 1000);
    }

    /* --- clean shutdown -------------------------------------------- */
    printf("\nShutting down...\n");
    log_event(log_fp, "System stopped");
    ret = EXIT_SUCCESS;

cleanup:
    if (buzzer_line) {
        gpiod_line_set_value(buzzer_line, 0);
        gpiod_line_release(buzzer_line);
    }
    if (flame_line) {
        gpiod_line_release(flame_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_fp) {
        fclose(log_fp);
    }
    return ret;
}

