        gpioDelay(POLL_DELAY_US);
    }

    /* Cleanup */
    gpioWrite(LED_PIN, 0);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    printf("Touch sensor monitoring stopped.\n");
    return EXIT_SUCCESS;
}

