/*
 * TMAG5110A1 Hall-Effect Latch Sensor Monitor
 * Board:  Raspberry Pi 4 Model B
 * Library: pigpio (C API)
 *
 * Wiring:
 *   Sensor 1 OUT -> GPIO4  (BCM)
 *   Sensor 2 OUT -> GPIO17 (BCM)
 *   Sensor 3 OUT -> GPIO27 (BCM)
 *
 * The TMAG5110A1 has an open-drain output: the line is pulled low
 * when a south pole is present and released high when the magnet
 * is removed.  We poll every 100 ms and log state changes to
 * magnet_log.txt with ISO-8601 timestamps.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define SENSOR3_PIN 27

#define LOG_FILE "magnet_log.txt"
#define POLL_DELAY_US 100000  /* 100 ms */

/* ------------------------------------------------------------------ */
/* Globals                                                             */
/* ------------------------------------------------------------------ */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* GPIO setup                                                          */
/* ------------------------------------------------------------------ */

static int setup_gpio(int pin)
{
    if (gpioSetMode(pin, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_INPUT) failed\n", pin);
        return -1;
    }
    if (gpioSetPullUpDown(pin, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown(%d, PI_PUD_UP) failed\n", pin);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */

static void log_event(int sensor_id, int state)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z",
                 &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return;
    }

    if (fprintf(g_log_fp, "%s - Sensor %d: %s\n",
                timestamp, sensor_id, state ? "MAGNET_PRESENT" : "MAGNET_REMOVED") < 0) {
        fprintf(stderr, "Error: fprintf to log file failed\n");
        return;
    }
    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "Warning: fflush failed on log file\n");
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */

static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    int prev_state[3] = {1, 1, 1};   /* assume no magnet initially */
    int current_state[3];
    int i;

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Configure GPIO pins ---- */
    for (i = 0; i < 3; i++) {
        if (setup_gpio(SENSOR1_PIN + i) != 0) {
            cleanup();
            return EXIT_FAILURE;
        }
    }

    printf("Monitoring TMAG5110A1 sensors on GPIO4, GPIO17, GPIO27.\n");
    printf("Logging state changes to '%s'. Press Ctrl+C to exit.\n", LOG_FILE);

    /* ---- Main polling loop ---- */
    while (g_running) {
        for (i = 0; i < 3; i++) {
            int val = gpioRead(SENSOR1_PIN + i);
            if (val < 0) {
                fprintf(stderr, "Error: gpioRead(%d) failed\n", SENSOR1_PIN + i);
                continue;
            }

            /* TMAG5110A1 open-drain: low = magnet present, high = removed */
            current_state[i] = (val == 0) ? 0 : 1;

            if (current_state[i] != prev_state[i]) {
                log_event(i + 1, current_state[i]);
                prev_state[i] = current_state[i];
            }
        }
        gpioDelay(POLL_DELAY_US);
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

