/*
 * touch_counter.c — 8-channel TTP226 touch sensor → 8-bit binary counter
 *
 * Board : Raspberry Pi Zero W
 * Library: libgpiod (modern Linux GPIO character-device API)
 *
 * Wiring
 *   TTP226 OUT1..OUT8  -> BCM 5,6,7,8,9,10,11,12
 *   Binary counter OUT  -> BCM 17,18,19,20,21,22,23,24
 *
 * Build: gcc -O2 -Wall -Wextra -o touch_counter touch_counter.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define NUM_BITS     8
#define STABILIZE_MS 200
#define POLL_MS      10
#define LOG_FILE     "touch_log.txt"

static const unsigned int sensor_pins[NUM_CHANNELS] = {5, 6, 7, 8, 9, 10, 11, 12};
static const unsigned int counter_pins[NUM_BITS]   = {17, 18, 19, 20, 21, 22, 23, 24};

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static void sleep_ms(unsigned int ms)
{
    struct timespec ts = {
        .tv_sec  = ms / 1000,
        .tv_nsec = (long)(ms % 1000) * 1000000L
    };
    while (nanosleep(&ts, &ts) == -1 && errno == EINTR) {
        /* retry on signal interruption */
    }
}

static void log_event(int channel, int counter)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return;
    }

    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        fclose(fp);
        return;
    }

    struct tm tm_utc;
    if (gmtime_r(&now, &tm_utc) == NULL) {
        fprintf(stderr, "gmtime_r() failed\n");
        fclose(fp);
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return;
    }

    fprintf(fp, "%s, Channel: %d, Counter: %d\n", ts, channel, counter);
    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *sensor_lines[NUM_CHANNELS];
    struct gpiod_line *counter_lines[NUM_BITS];
    int ret = EXIT_FAILURE;

    memset(sensor_lines, 0, sizeof(sensor_lines));
    memset(counter_lines, 0, sizeof(counter_lines));

    /* --- signal handling ------------------------------------------ */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- open GPIO chip -------------------------------------------- */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- request sensor lines as inputs --------------------------------- */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        sensor_lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (!sensor_lines[i]) {
            fprintf(stderr, "Failed to get sensor line BCM %u: %s\n",
                    sensor_pins[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_input(sensor_lines[i], "ttp226-sensor") < 0) {
            fprintf(stderr, "Failed to request sensor line BCM %u as input: %s\n",
                    sensor_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    /* --- request counter lines as outputs, initial value 0 --------------- */
    for (int i = 0; i < NUM_BITS; i++) {
        counter_lines[i] = gpiod_chip_get_line(chip, counter_pins[i]);
        if (!counter_lines[i]) {
            fprintf(stderr, "Failed to get counter line BCM %u: %s\n",
                    counter_pins[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_output(counter_lines[i], "ttp226-counter", 0) < 0) {
            fprintf(stderr, "Failed to request counter line BCM %u as output: %s\n",
                    counter_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    /* --- stabilization delay ---------------------------------------- */
    printf("Waiting %d ms for sensor stabilization...\n", STABILIZE_MS);
    sleep_ms(STABILIZE_MS);

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    /* --- main polling loop ------------------------------------------- */
    while (g_running) {
        for (int c = 0; c < NUM_CHANNELS && g_running; c++) {
            int val = gpiod_line_get_value(sensor_lines[c]);
            if (val < 0) {
                fprintf(stderr, "Error reading sensor channel %d (BCM %u): %s\n",
                        c + 1, sensor_pins[c], strerror(errno));
                continue;
            }

            /* TTP226 OUT is active-high: 0 = idle, 1 = touched */
            if (val == 1) {
                int counter_val = gpiod_line_get_value(counter_lines[0]);
                if (counter_val < 0) {
                    fprintf(stderr, "Error reading counter bit 0 (BCM %u): %s\n",
                            counter_pins[0], strerror(errno));
                    continue;
                }

                int new_counter = counter_val + 1;
                if (new_counter > 255) {
                    new_counter = 0;
                }

                for (int b = 0; b < NUM_BITS; b++) {
                    int bit = (new_counter >> b) & 1;
                    if (gpiod_line_set_value(counter_lines[b], bit) < 0) {
                        fprintf(stderr, "Error writing counter bit %d (BCM %u): %s\n",
                                b, counter_pins[b], strerror(errno));
                    }
                }

                log_event(c + 1, new_counter);
                printf("Touch on channel %d | Counter: %d\n", c + 1, new_counter);
            }
        }

        sleep_ms(POLL_MS);
    }

    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;

cleanup:
    /* --- release all resources in reverse order ------------------------- */
    for (int i = 0; i < NUM_BITS; i++) {
        if (counter_lines[i]) {
            gpiod_line_set_value(counter_lines[i], 0);
            gpiod_line_release(counter_lines[i]);
        }
    }
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (sensor_lines[i]) {
            gpiod_line_release(sensor_lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return ret;
}

