                        fprintf(stderr, "Error writing counter bit %d (BCM %u): %s\n",
                                b, counter_pins[b], strerror(errno));
                    }
                }

                log_event(c + 1, new_counter);
                printf("Touch on channel %d | Counter: %d\n", c + 1, new_counter);
            }
        }

        sleep_ms(POLL_MS);
    }

    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;

cleanup:
    /* --- release all resources in reverse order ------------------------- */
    for (int i = 0; i < NUM_BITS; i++) {
        if (counter_lines[i]) {
            gpiod_line_set_value(counter_lines[i], 0);
            gpiod_line_release(counter_lines[i]);
        }
    }
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (sensor_lines[i]) {
            gpiod_line_release(sensor_lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return ret;
}

