#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_SENSORS 4
#define POLL_DELAY_US 100000  /* 100 ms */
#define LOG_FILE "tracking_log.csv"

static const int sensor_pins[NUM_SENSORS] = {17, 18, 27, 22};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d).\n", gpioInitialise());
        return -1;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        if (gpioSetMode(sensor_pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO%d as input.\n", sensor_pins[i]);
            gpioTerminate();
            return -1;
        }
        /* KY-033 modules have on-board pull resistors; enable internal pull-ups as a
         * safety guard in case the module is disconnected or the line is open. */
        if (gpioSetPullUpDown(sensor_pins[i], PI_PUD_UP) != 0) {
            fprintf(stderr, "Warning: failed to set pull-up on GPIO%d.\n", sensor_pins[i]);
        }
    }
    return 0;
}

static int read_sensor(int gpio_pin)
{
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error: failed to read GPIO%d (code %d).\n", gpio_pin, value);
        return -1;
    }
    /* Active-low: 0 = line/obstacle detected, 1 = clear. */
    return (value == 0) ? 1 : 0;
}

static int log_data(FILE *fp, int s1, int s2, int s3, int s4)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed.\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed.\n");
        return -1;
    }

    if (fprintf(fp, "%s,%d,%d,%d,%d\n", timestamp, s1, s2, s3, s4) < 0) {
        fprintf(stderr, "Error: failed to write to log file.\n");
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "Warning: fflush failed: %s\n", strerror(errno));
    }

    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty. */
    if (fseek(fp, 0, SEEK_END) != 0) {
        fprintf(stderr, "Warning: fseek failed: %s\n", strerror(errno));
    } else {
        long file_size = ftell(fp);
        if (file_size == 0) {
            if (fprintf(fp, "timestamp,sensor1,sensor2,sensor3,sensor4\n") < 0) {
                fprintf(stderr, "Error: failed to write header: %s\n", strerror(errno));
                fclose(fp);
                gpioTerminate();
                return EXIT_FAILURE;
            }
            fflush(fp);
        }
    }

    printf("Polling %d sensors every 100 ms. Press Ctrl+C to exit.\n", NUM_SENSORS);

    while (program_running) {
        int values[NUM_SENSORS];
        int read_error = 0;

        for (int i = 0; i < NUM_SENSORS; i++) {
            values[i] = read_sensor(sensor_pins[i]);
            if (values[i] < 0) {
                read_error = 1;
                break;
            }
        }

        if (read_error) {
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        if (log_data(fp, values[0], values[1], values[2], values[3]) != 0) {
            fprintf(stderr, "Error: failed to log data.\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down gracefully...\n");

    if (fclose(fp) != 0) {
        fprintf(stderr, "Warning: fclose failed: %s\n", strerror(errno));
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

