#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 18
#define LOG_FILE "/var/log/tilt_events.log"
#define DEBOUNCE_MS 50
#define POLL_MS    100

static volatile sig_atomic_t running = 1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_event(int sensor_num) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(log_fp, "%s, Sensor %d tilted\n", timestamp, sensor_num) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    int prev1 = 1, prev2 = 1;
    int cur1 = 1, cur2 = 1;
    int cur1_debounced = 1, cur2_debounced = 1;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SENSOR_1_GPIO);
        fclose(log_fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SENSOR_2_GPIO);
        fclose(log_fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_1_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO%d\n", SENSOR_1_GPIO);
        fclose(log_fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_2_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO%d\n", SENSOR_2_GPIO);
        fclose(log_fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Monitoring tilt sensors on GPIO%d and GPIO%d. Press Ctrl+C to exit.\n", SENSOR_1_GPIO, SENSOR_2_GPIO);

    while (running) {
        int v1 = gpioRead(SENSOR_1_GPIO);
        int v2 = gpioRead(SENSOR_2_GPIO);

        if (v1 < 0 || v2 < 0) {
            fprintf(stderr, "gpioRead error (s1=%d, s2=%d): %s\n", v1, v2, strerror(errno));
            gpioDelay(POLL_MS * 1000);
            continue;
        }

        if (v1 != prev1) {
            gpioDelay(DEBOUNCE_MS * 1000);
            cur1 = gpioRead(SENSOR_1_GPIO);
            if (cur1 < 0) {
                fprintf(stderr, "gpioRead error during debounce on GPIO%d: %s\n", SENSOR_1_GPIO, strerror(errno));
                prev1 = v1;
                continue;
            }
            if (cur1 != prev1) {
                cur1_debounced = cur1;
            }
        }

        if (v2 != prev2) {
            gpioDelay(DEBOUNCE_MS * 1000);
            cur2 = gpioRead(SENSOR_2_GPIO);
            if (cur2 < 0) {
                fprintf(stderr, "gpioRead error during debounce on GPIO%d: %s\n", SENSOR_2_GPIO, strerror(errno));
                prev2 = v2;
                continue;
            }
            if (cur2 != prev2) {
                cur2_debounced = cur2;
            }
        }

        if (cur1_debounced == 0 && prev1 == 1) {
            if (log_event(1) != 0) {
                fprintf(stderr, "Failed to log event for sensor 1\n");
            }
        }

        if (cur2_debounced == 0 && prev2 == 1) {
            if (log_event(2) != 0) {
                fprintf(stderr, "Failed to log event for sensor 2\n");
            }
        }

        prev1 = cur1;
        prev2 = cur2;
        gpioDelay(POLL_MS * 1000);
    }

    printf("\nShutting down...\n");
    if (log_fp != NULL) {
        fclose(log_fp);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

