#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MIC_PIN        4
#define LED_PIN        17
#define SAMPLE_PERIOD_US 125          /* 8 kHz polling */
#define LED_ON_MS      100
#define MAX_PEAKS      1000           /* guard against runaway accumulation */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void print_timestamp_ms(void)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char buf[32];
    strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &tm_info);
    printf("%s.%03ld", buf, ts.tv_nsec / 1000000L);
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MIC_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set MIC_PIN %d as input\n", MIC_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED_PIN %d as output\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialise LED_PIN %d to LOW\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        gpioWrite(LED_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("ICS-40180 peak detection started. MIC=BCM%d, LED=BCM%d\n",
           MIC_PIN, LED_PIN);
    printf("Press Ctrl+C to exit.\n");

    uint32_t next_tick = gpioTick();
    bool led_on = false;
    bool peak_queue_full = false;

    while (g_running) {
        uint32_t now = gpioTick();
        if (now >= next_tick) {
            next_tick += SAMPLE_PERIOD_US;
        }

        int mic = gpioRead(MIC_PIN);
        if (mic < 0) {
            fprintf(stderr, "gpioRead failed on MIC_PIN %d\n", MIC_PIN);
            break;
        }

        if (mic == 1) {
            if (!peak_queue_full) {
                peak_queue_full = true;
                struct timespec ts;
                clock_gettime(CLOCK_REALTIME, &ts);
                print_timestamp_ms();

                if (gpioWrite(LED_PIN, 1) != 0) {
                    fprintf(stderr, "gpioWrite HIGH failed on LED_PIN %d\n", LED_PIN);
                    break;
                }
                led_on = true;

                for (int i = 0; i < LED_ON_MS && g_running; i++) {
                    gpioDelay(1000); /* 1 ms */
                }

                if (gpioWrite(LED_PIN, 0) != 0) {
                    fprintf(stderr, "gpioWrite LOW failed on LED_PIN %d\n", LED_PIN);
                    break;
                }
                led_on = false;
            }
        }

        next_tick += SAMPLE_PERIOD_US;
    }

    /* Clean shutdown */
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

