/*
 * Si1175 ALS Heart-Rate Sensor Reader for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   Si1175 SDA -> GPIO2 (I2C bus 1 SDA)
 *   Si1175 SCL -> GPIO3 (I2C bus 1 SCL)
 *   Si1175 VDD -> 3.3 V
 *   Si1175 GND -> GND
 *
 * I2C bus: /dev/i2c-1
 * ALS data registers: 0x00 (LSB), 0x01 (MSB)
 *
 * Build: gcc -O2 -Wall -o si1175_als si1175_als.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define ALS_LSB_REG    0x00
#define ALS_MSB_REG    0x01
#define ALS_DATA_REG   0x02
#define ALS_DATA_SIZE  2
#define READ_INTERVAL_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg_lsb, uint8_t reg_msb, uint16_t *out)
{
    uint8_t lsb, msb;
    if (i2c_read_reg8(fd, reg_lsb, &lsb) < 0) return -1;
    if (i2c_read_reg8(fd, reg_msb, &msb) < 0) return -1;
    *out = ((uint16_t)msb << 8) | lsb;
    return 0;
}

int main(void)
{
    int fd = -1;
    int rc = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the I2C bus */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the Si1175 device */
    if (ioctl(fd, I2C_SLAVE, 0x00) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x00) failed: %s\n",
                strerror(errno));
        goto cleanup;
    }

    /* Probe: try reading the ALS data register to confirm sensor presence */
    uint8_t probe;
    if (i2c_read_reg8(fd, ALS_DATA_REG, &probe) < 0) {
        fprintf(stderr, "Si1175 not responding at 0x00 on %s\n",
                I2C_BUS);
        goto cleanup;
    }

    printf("Si1175 detected. Reading ALS data every 100 ms (Ctrl+C to stop)...\n");

    while (g_running) {
        uint16_t raw;
        if (i2c_read_reg16(fd, ALS_LSB_REG, ALS_MSB_REG, &raw) < 0) {
            fprintf(stderr, "Read error — continuing\n");
            usleep(READ_INTERVAL_US);
            continue;
        }

        printf("Raw ALS data: %u\n", raw);
        usleep(READ_INTERVAL_US);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
