static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *left_line = NULL;
    struct gpiod_line *middle_line = NULL;
    struct gpiod_line *right_line = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to install SIGINT handler");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi 3 B+) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        perror("Failed to open gpiochip0");
        return EXIT_FAILURE;
    }

    /* Get the three GPIO lines */
    left_line = gpiod_chip_get_line(chip, LEFT_PIN);
    if (left_line == NULL) {
        perror("Failed to get left line (GPIO2)");
        goto cleanup;
    }

    middle_line = gpiod_chip_get_line(chip, MIDDLE_PIN);
    if (middle_line == NULL) {
        perror("Failed to get middle line (GPIO3)");
        goto cleanup;
    }

    right_line = gpiod_chip_get_line(chip, RIGHT_PIN);
    if (right_line == NULL) {
        perror("Failed to get right line (GPIO4)");
        goto cleanup;
    }

    /* Request each line as input */
    if (gpiod_line_request_input(left_line, "keywish_sensor") < 0) {
        perror("Failed to request left line as input");
        goto cleanup;
    }

    if (gpiod_line_request_input(middle_line, "keywish_sensor") < 0) {
        perror("Failed to request middle line as input");
        goto cleanup;
    }

    if (gpiod_line_request_input(right_line, "keywish_sensor") < 0) {
        perror("Failed to request right line as input");
        goto cleanup;
    }

    printf("Keywish 3-Way Tracking Sensor Polling (Ctrl+C to exit)\n");

    /* Main polling loop */
    while (program_running) {
        int left_val = gpiod_line_get_value(left_line);
        int middle_val = gpiod_line_get_value(middle_line);
        int right_val = gpiod_line_get_value(right_line);

        if (left_val < 0) {
            perror("Error reading left line");
            goto cleanup;
        }
        if (middle_val < 0) {
            perror("Error reading middle line");
            goto cleanup;
        }
        if (right_val < 0) {
            perror("Error reading right line");
            goto cleanup;
        }

        printf("L:%d M:%d R:%d\n", left_val, middle_val, right_val);

        usleep(POLL_INTERVAL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip on every exit path */
    if (left_line) gpiod_line_release(left_line);
    if (middle_line) gpiod_line_release(middle_line);
    if (right_line) gpiod_line_release(right_line);
    if (chip) gpiod_chip_close(chip);

    return ret;
}

