/*
 * touch_poll.c — Poll 8-channel TTP226 capacitive touch sensor on a Raspberry Pi 3 Model B+
 *
 * Wiring (BCM numbering):
 *   TP1 -> GPIO5
 *   TP2 -> GPIO6
 *   TP3 -> GPIO13
 *   TP4 -> GPIO19
 *   TP5 -> GPIO26
 *   TP6 -> GPIO12
 *   TP7 -> GPIO16
 *   TP8 -> GPIO20
 *
 * Build: gcc -o touch_poll touch_poll.c -lrt
 * Run:   ./touch_poll
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <unistd.h>

#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_MS 200

static const unsigned int gpio_pins[NUM_CHANNELS] = {
    5, 6, 13, 19, 26, 12, 16, 20
};

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void print_timestamped(const char *msg)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
        return;
    }
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char buf[32];
    strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &tm_info);
    printf("[%s.%03ld] %s\n", buf, ts.tv_nsec / 1000000L, msg);
    fflush(stdout);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_CHANNELS];
    int ret = EXIT_FAILURE;

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Pi 3 B+) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire each line as input */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, gpio_pins[i]);
        if (lines[i] == NULL) {
            fprintf(stderr, "Failed to get GPIO line %u: %s\n",
                    gpio_pins[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_input(lines[i], "ttp226-touch") != 0) {
            fprintf(stderr, "Failed to request GPIO line %u as input: %s\n",
                    gpio_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    printf("TTP226 touch sensor polling started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (g_running) {
        int values[NUM_CHANNELS];
        bool read_error = false;

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int v = gpiod_line_get_value(lines[i]);
            if (v < 0) {
                fprintf(stderr, "Failed to read GPIO line %u: %s\n",
                        gpio_pins[i], strerror(errno));
                read_error = true;
                break;
            }
            values[i] = v;
        }

        if (!read_error) {
            print_timestamped("CH1=0 CH2=1 CH3=0 CH4=0 CH5=0 CH6=0 CH7=0 CH8=0");
        }

        /* Sleep 200 ms using nanosleep for portability */
        struct timespec ts_sleep;
        ts_sleep.tv_sec = 0;
        ts_sleep.tv_nsec = POLL_INTERVAL_MS * 1000000L;
        while (nanosleep(&ts_sleep, &ts_sleep) == -1 && errno == EINTR) {
            /* Retry if interrupted by signal */
        }
    }

    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (lines[i] != NULL) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    return ret;
}

