#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <errno.h>

#include <pigpio.h>

#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

#define PWM_FREQUENCY 1000
#define PWM_RANGE     255
#define NUM_CHANNELS  3
#define NUM_STEPS     50
#define FADE_DURATION 5

static volatile sig_atomic_t g_terminate = 0;

static void signal_handler(int sig)
{
    (void)sig;
    g_terminate = 1;
}

static void set_led_color(int r, int g, int b)
{
    if (gpioPWM(RED_PIN, r) < 0) {
        syslog(LOG_ERR, "gpioPWM failed on RED_PIN: %s", strerror(errno));
    }
    if (gpioPWM(GREEN_PIN, g) < 0) {
        syslog(LOG_ERR, "gpioPWM failed on GREEN_PIN: %s", strerror(errno));
    }
    if (gpioPWM(BLUE_PIN, b) < 0) {
        syslog(LOG_ERR, "gpioPWM failed on BLUE_PIN: %s", strerror(errno));
    }
}

static void fade_to_color(int r, int g, int b, int duration_seconds)
{
    if (duration_seconds <= 0) {
        set_led_color(r, g, b);
        return;
    }

    int delay_us = (duration_seconds * 1000000) / NUM_STEPS;
    int step = 0;

    while (step < NUM_STEPS && !g_terminate) {
        int dr = r;
        int dg = g;
        int db = b;

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int v = (dr * i) / NUM_CHANNELS;
            if (v < 0) v = 0;
            if (v > 255) v = 255;
            if (gpioPWM((uint32_t)RED_PIN, v) < 0) {
                syslog(LOG_ERR, "gpioPWM failed on RED_PIN: %s", strerror(errno));
            }
            if (gpioPWM((uint32_t)GREEN_PIN, v) < 0) {
                syslog(LOG_ERR, "gpioPWM failed on GREEN_PIN: %s", strerror(errno));
            }
            if (gpioPWM((uint32_t)BLUE_PIN, v) < 0) {
                syslog(LOG_ERR, "gpioPWM failed on BLUE_PIN: %s", strerror(errno));
            }
        }

        step++;
        usleep(delay_us);
    }

    set_led_color(r, g, b);
}

static void select_random_color(int *r, int *g, int *b)
{
    int r_val = rand() % 256;
    int g_val = rand() % 256;
    int b_val = rand() % 256;

    if (r_val < 0) r_val = 0;
    if (g_val < 0) g_val = 0;
    if (b_val < 0) b_val = 0;

    *r = r_val;
    *g = g_val;
    *b = b_val;
}

int main(void)
{
    openlog("rgb_fade", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        syslog(LOG_ERR, "sigaction(SIGINT) failed: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "sigaction(SIGTERM) failed: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

