        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(BLUE_PIN, PWM_FREQUENCY) < 0) {
        syslog(LOG_ERR, "gpioSetPWMfrequency failed on BLUE_PIN: %s", strerror(errno));
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(RED_PIN, PWM_RANGE) < 0) {
        syslog(LOG_ERR, "gpioSetPWMrange failed on RED_PIN: %s", strerror(errno));
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(GREEN_PIN, PWM_RANGE) < 0) {
        syslog(LOG_ERR, "gpioSetPWMrange failed on GREEN_PIN: %s", strerror(errno));
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
