/*
 * TCS34725 Color Sensor Reader with LED Threshold Indicator
 * Board:  Raspberry Pi 4 Model B
 * I2C bus: /dev/i2c-1  (BCM pins 2/3)
 * LED:    GPIO 17 (BCM)
 *
 * Build:  gcc -O2 -Wall -o tcs34725 tcs34725.c -lpigpio -lrt
 * Run:    sudo ./tcs34725
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

/* ---- TCS34725 register definitions ---- */
#define TCS34725_I2C_ADDR        0x29
#define TCS34725_COMMAND_BIT     0x80

#define TCS34725_ENABLE          0x00
#define TCS34725_ATIME           0x01
#define TCS34725_CONTROL         0x0F
#define TCS34725_ID              0x12
#define TCS34725_STATUS          0x13
#define TCS34725_CDATAL          0x14
#define TCS34725_RDATAL          0x16
#define TCS34725_GDATAL          0x18
#define TCS34725_BDATAL          0x1A

#define TCS34725_PON             0x01
#define TCS34725_AEN             0x02

/* ---- Configuration constants ---- */
#define I2C_BUS                 "/dev/i2c-1"
#define GPIO_LED                17
#define RED_THRESHOLD           200
#define POLL_DELAY_US           200000   /* 200 ms */
#define INTEGRATION_MS          154     /* ~154 ms integration */

/* ---- Globals for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static int g_gpio_initialized = 0;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to a TCS34725 register.                              */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int tcs_write_reg(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { (uint8_t)(reg | TCS34725_COMMAND_BIT), value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from a TCS34725 register.                              */
/* Returns the byte value (0-255) on success, -1 on error.              */
/* ------------------------------------------------------------------ */
static int tcs_read_reg(int fd, uint8_t reg)
{
    uint8_t cmd = (uint8_t)(reg | TCS34725_COMMAND_BIT);
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    uint8_t val;
    if (read(fd, &val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return (int)val;
}

/* ------------------------------------------------------------------ */
/* Initialise the TCS34725: power on, enable RGBC, set integration time.  */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int tcs34725_init(int fd)
{
    /* Power on */
    if (tcs_write_reg(fd, TCS34725_ENABLE, TCS34725_PON) != 0)
        return -1;
    gpioDelay(3000);  /* 3 ms power-up settling */

    /* Enable RGBC */
    if (tcs_write_reg(fd, TCS34725_ENABLE, TCS34725_PON | TCS34725_AEN) != 0)
        return -1;

    /* Integration time ~154 ms (ATIME = 0x00) */
    if (tcs_write_reg(fd, TCS34725_ATIME, 0x00) != 0)
        return -1;

    /* Set control register: enable RGBC, no gain, no multiplexing */
    if (tcs_write_reg(fd, TCS34725_CONTROL, 0x00) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read the four calibrated RGB+C channels.                             */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int tcs34725_read_channels(int fd, uint16_t *r, uint16_t *g,
                                  uint16_t *b, uint16_t *c)
{
    int r_val = tcs_read_reg(fd, TCS34725_RDATAL);
    int g_val = tcs_read_reg(fd, TCS34725_GDATAL);
    int b_val = tcs_read_reg(fd, TCS34725_BDATAL);
    int c_val = tcs_read_reg(fd, TCS34725_CDATAL);

    if (r_val < 0 || g_val < 0 || b_val < 0 || c_val < 0) {
        fprintf(stderr, "Failed to read sensor channels\n");
        return -1;
    }

    *r = (uint16_t)r_val;
    *g = (uint16_t)g_val;
    *b = (uint16_t)b_val;
    *c = (uint16_t)c_val;
    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        /* Power down the sensor before closing */
        (void)tcs_write_reg(g_i2c_fd, TCS34725_ENABLE, 0x00);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_gpio_initialized) {
        gpioWrite(GPIO_LED, 0);
        gpioTerminate();
        g_gpio_initialized = 0;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }
    g_gpio_initialized = 1;

    /* ---- Open I2C bus ---- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, TCS34725_I2C_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                TCS34725_I2C_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Sensor init ---- */
    if (tcs34725_init(g_i2c_fd) != 0) {
        fprintf(stderr, "TCS34725 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- LED GPIO setup ---- */
    if (gpioSetMode(GPIO_LED, PI_OUTPUT) != 0) {
        fprintf(stderr, "Cannot set GPIO %d as output\n", GPIO_LED);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(GPIO_LED, 0);

    printf("TCS34725 initialised. Polling every %d ms. Press Ctrl+C to exit.\n",
           POLL_DELAY_US / 1000);

    /* ---- Main loop ---- */
    while (g_running) {
        uint16_t r, g, b, c;

        if (tcs34725_read_channels(g_i2c_fd, &r, &g, &b, &c) != 0) {
            fprintf(stderr, "Read failed; re-initialising sensor...\n");
            (void)tcs_write_reg(g_i2c_fd, TCS34725_ENABLE, 0x00);
            gpioDelay(10000);  /* 10 ms power-down settle */
            if (tcs34725_init(g_i2c_fd) != 0) {
                fprintf(stderr, "Re-init failed; retrying in 1 s\n");
                gpioDelay(1000000);
                continue;
            }
            continue;
        }

        printf("R: %5u  G: %5u  B: %5u  C: %5u\n", r, g, b, c);

        if (r > RED_THRESHOLD)
            gpioWrite(GPIO_LED, 1);
        else
            gpioWrite(GPIO_LED, 0);

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

