/*
 * Raspberry Pi 4 Model B — BH1750 ambient light sensor → WS2812B LED strip
 *
 * Hardware:
 *   - BH1750 on I2C bus 1 (GPIO2=SDA, GPIO3=SCL), address 0x38
 *   - WS2812B data line on GPIO18 (BCM) using hardware PWM/wave output
 *     (no external library; the Pi's internal driver is exercised directly).
 *
 * Build:
 *   gcc -O2 -Wall -o light_led light_led.c
 *
 * Run:
 *   sudo ./light_led   (root needed for /dev/i2c-1 and hardware PWM)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define BH1750_ADDR    0x38
#define BH1750_CMD_CONT_HRES  0x10   /* continuous H-Resolution mode */
#define BH1750_CONV_MS        180    /* conversion time in ms */
#define PWM_GPIO        18       /* BCM 18 = hardware PWM0 */
#define NUM_LEDS       10
#define PWM_FREQ_HZ    800000   /* 800 kHz hardware PWM frequency */
#define PWM_RANGE      1000     /* duty-cycle resolution 0..1000 */

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Low-level I2C helpers                                              */
/* ------------------------------------------------------------------ */

static int i2c_write_cmd(int fd, uint8_t cmd)
{
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_n(int fd, uint8_t *buf, size_t n)
{
    size_t got = 0;
    while (got < n) {
        ssize_t r = read(fd, buf + got, n - got);
        if (r < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
            return -1;
        }
        if (r == 0) {
            fprintf(stderr, "I2C read: unexpected EOF (sensor absent?)\n");
            return -1;
        }
        got += (size_t)r;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* BH1750 measurement                                                */
/* ------------------------------------------------------------------ */

/*
 * Returns lux on success, or -1.0 on error/timeout.
 * Uses a 2-conversion strategy: first quick conversion (~120 ms),
 * then a full conversion (~180 ms) to confirm.
 */
static float bh1750_read_lux(int fd)
{
    uint8_t buf[2];

    /* Quick conversion — returns 0 or 1 lux */
    if (i2c_write_cmd(fd, BH1750_CMD_CONT_HRES) < 0)
        return -1.0f;

    usleep(120000);                       /* 120 ms */

    if (i2c_read_n(fd, buf, 2) < 0)
        return -1.0f;

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    float lux = (float)raw / 1.2f;       /* datasheet: lux = raw / 1.2 */
    return lux;
}

/* ------------------------------------------------------------------ */
/* WS2812B LED generation (hardware PWM, no external library)           */
/* ------------------------------------------------------------------ */

/*
 * Build a single WS2812B frame bit-banged via hardware PWM.
 * The Pi's internal driver is exercised directly: each bit is
 * encoded as a 1-bit PWM pulse of the correct width.
 */
static void ws2812b_build_frame(uint8_t *data, int len)
{
    if (len == 0 || len > 800) {
        fprintf(stderr, "WS2812B frame length %d out of range\n", len);
        return;
    }

    /* Each WS2812B bit is ~800 ns high and ~800 ns low.
     * The Pi's hardware PWM runs at 800 kHz, so a 1-bit pulse
     * is 1 us.  We use the hardware PWM to generate the exact
     * timing. */
    const int half_us = 500;            /* half a 1-bit pulse (us) */

    for (int i = 0; i < len; i++) {
        uint32_t val = 0;
        if (data[i] & 0x80) {
            val |= (1U << (3 - i));     /* MSB first */
        }

        /* Each byte: 24 bits, each bit = 1 us high + 1 us low */
        for (int b = 7; b >= 0; b--) {
            /* High phase: set duty cycle to half_us (1 us high) */
            if (val & (1U << b)) {
                if (ioctl(PWM_GPIO, PWM_SET_DUTY_CYCLE, half_us) < 0) {
                    fprintf(stderr, "PWM_SET_DUTY_CYCLE failed: %s\n",
                            strerror(errno));
                    return;
                }
            } else {
                /* Low phase: set duty cycle to 0 (off) */
                if (ioctl(PWM_GPIO, PWM_SET_DUTY_CYCLE, 0) < 0) {
                    fprintf(stderr, "PWM_SET_DUTY_CYCLE failed: %s\n",
                            strerror(errno));
                    return;
                }
            }
        }
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                               */
/* ------------------------------------------------------------------ */

int main(void)
{
    int i2c_fd = -1;
    int pwm_fd = -1;
    uint8_t led_data[NUM_LEDS * 3];   /* R, G, B per LED */
    int ret = EXIT_FAILURE;

    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                BH1750_ADDR, strerror(errno));
        goto cleanup;
    }

    /* ---- Open PWM GPIO ---- */
    pwm_fd = open(PWM_GPIO, O_RDWR);
    if (pwm_fd < 0) {
        fprintf(stderr, "Cannot open GPIO%d: %s\n", PWM_GPIO, strerror(errno));
        goto cleanup;
    }

    /* ---- Configure PWM: 800 kHz, range 1000 ---- */
    uint32_t pwm_freq = PWM_FREQ_HZ;
    uint32_t pwm_range = PWM_RANGE;
    if (ioctl(pwm_fd, PWM_SET_FREQUENCY, &pwm_freq) < 0) {
        fprintf(stderr, "PWM_SET_FREQUENCY failed: %s\n", strerror(errno));
        goto cleanup;
    }
    if (ioctl(pwm_fd, PWM_SET_RANGE, &pwm_range) < 0) {
        fprintf(stderr, "PWM_SET_RANGE failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* ---- Main loop ---- */
    while (g_running) {
        float lux = bh1750_read_lux(i2c_fd);

        if (lux < 0.0f) {
            fprintf(stderr, "BH1750 read error — retrying in 2 s\n");
            sleep(2);
            continue;
        }

        /* Logarithmic mapping: lux → brightness */
        float brightness = log10f(lux + 1.0f) / log10f(1000.0f) * 100.0f;

        /* Map brightness to LED color (0 = black, 100 = white) */
        for (int i = 0; i < NUM_LEDS; i++) {
            led_data[i * 3 + 0] = (uint8_t)(brightness * 255.0f);
            led_data[i * 3 + 1] = (uint8_t)(brightness * 255.0f);
            led_data[i * 3 + 2] = 0;   /* black */
        }

        ws2812b_build_frame(led_data, sizeof(led_data));

        /* Wait for the BH1750 conversion to complete */
        usleep(BH1750_CONV_MS * 1000);

        /* Clear the PWM output */
        if (ioctl(PWM_GPIO, PWM_SET_DUTY_CYCLE, 0) < 0) {
            fprintf(stderr, "PWM_CLEAR failed: %s\n", strerror(errno));
            goto cleanup;
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (pwm_fd >= 0) {
        /* Ensure PWM is off */
        if (ioctl(PWM_GPIO, PWM_SET_DUTY_CYCLE, 0) < 0) {
            fprintf(stderr, "PWM_CLEAR failed: %s\n", strerror(errno));
        }
        close(pwm_fd);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    return ret;
}

