code:
/*
 * Raspberry Pi Zero W – BH1750 ambient light sensor → APA102 LED strip
 *
 * Wiring:
 *   BH1750 SDA  → GPIO2 (pin 3, I2C bus 1)
 *   BH1750 SCL  → GPIO3 (pin 5, I2C bus 1)
 *   BH1750 VCC  → 3.3 V
 *   BH1750 GND  → GND
 *   APA102 DIN  → GPIO11 (pin 23, SPI0 SCLK)
 *   APA102 VCC  → 5 V (strip supports 5 V signalling)
 *   APA102 GND  → GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o light_led light_led.c -lm
 *
 * Run:
 *   ./light_led
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <math.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS          "/dev/i2c-1"
#define SPI_DEVICE       "/dev/spidev0.0"
#define SPI_SPEED_HZ     1000000U   /* 1 MHz – APA102 supports up to 5 MHz */
#define NUM_LEDS         10
#define SAMPLE_PERIOD_US 120000U    /* 120 ms between conversions */
#define MAX_RETRIES      3

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static int g_spi_fd = -1;

/* ----------------------------- Prototypes -------------------------------- */
static void signal_handler(int sig);
static int  init_i2c(void);
static int  init_spi(void);
static int  read_bh1750(uint16_t *brightness);
static int  scale_brightness(uint16_t brightness, uint32_t *led_data);
static int  send_led_data(const uint32_t *led_data, size_t len);
static void cleanup(void);

/* ----------------------------- Signal handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- I2C helpers ------------------------------- */
static int init_i2c(void)
{
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return -1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, 0x40) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x40): %s\n", strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return -1;
    }
    return 0;
}

/*
 * BH1750 single-shot mode, no register address – the device auto-increments
 * its register pointer after a power-on reset or a write of 0x00.
 * Returns 0 on success, -1 on error.
 */
static int read_bh1750(uint16_t *brightness)
{
    uint8_t buf[2];

    if (g_i2c_fd < 0)
        return -1;

    /* Trigger a single-shot conversion (no register, just a zero-length write). */
    if (write(g_i2c_fd, buf, 0) < 0) {
        fprintf(stderr, "BH1750 trigger write: %s\n", strerror(errno));
        return -1;
    }

    /* Wait for conversion to complete (max ~180 ms at 1 lux resolution). */
    usleep(SAMPLE_PERIOD_US);

    ssize_t n = read(g_i2c_fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "BH1750 read: expected 2 bytes, got %zd (%s)\n",
                n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }

    *brightness = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/* ----------------------------- SPI helpers ------------------------------- */
static int init_spi(void)
{
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE_0;
    uint8_t bits  = 8;
    uint32_t speed = SPI_SPEED_HZ;

    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        goto fail;
    }
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        goto fail;
    }
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        goto fail;
    }
    return 0;

fail:
    close(g_spi_fd);
    g_spi_fd = -1;
    return -1;
}

/*
 * APA102 expects a 32-bit zero start frame, followed by one 32-bit LED
 * frame per LED, followed by a 32-bit end frame.
 */
static int send_led_data(const uint32_t *led_data, size_t len)
{
    if (g_spi_fd < 0)
        return -1;

    size_t total = len + 1;          /* start frame + data + end frame */
    if (total > 512) {
        fprintf(stderr, "APA102 payload too large (%zu bytes)\n", total);
        return -1;
    }

    uint8_t tx[total];
    uint8_t rx[total] = {0};

    for (size_t i = 0; i < total; i++) {
        tx[i] = 0x00;                  /* zero start frame */
        if (i < len) {
            /* LED frame: 0x00 | brightness | blue | green | red */
            uint32_t frame = 0x00;
            frame |= (uint32_t)led_data[i];
            frame >>= 8;                /* blue */
            frame >>= 8;                /* green */
            frame >>= 8;                /* red */
            frame &= 0xFF;               /* clear upper byte */
            tx[i] |= (uint8_t)frame;
        }
    }

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = total;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = 8;
    tr.delay_usecs   = 0;

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    if (g_spi_fd >= 0) {
        /* Turn off all LEDs (brightness = 0, all fields = 0). */
        uint32_t off[NUM_LEDS];
        memset(off, 0, sizeof(off));
        send_led_data(off, sizeof(off));
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (init_i2c() < 0) {
        fprintf(stderr, "BH1750 init failed\n");
        return EXIT_FAILURE;
    }

    if (init_spi() < 0) {
        fprintf(stderr, "APA102 SPI init failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("BH1750 → APA102 running. Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t brightness = 0;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (read_bh1750(&brightness) == 0) {
                ok = 1;
                break;
            }
            usleep(10000);  /* 10 ms back-off before retry */
        }

        if (!ok) {
            fprintf(stderr, "BH1750 read failed after %d attempts; skipping cycle\n",
                    MAX_RETRIES);
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        uint32_t led_data[NUM_LEDS];
        scale_brightness(brightness, &led_data[0]);

        if (send_led_data(led_data, sizeof(led_data)) < 0) {
            fprintf(stderr, "Failed to send LED data\n");
        }

        usleep(SAMPLE_PERIOD_US);
    }

    cleanup();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

/* ----------------------------- Brightness scaling ------------------------- */
/*
 * BH1750 resolution: 0.5 lx at 1 lux resolution, 1 lx at 0.5 lux resolution.
 * Scale 0–65535 to 0–1000000 (APA102 full brightness range).
 */
static int scale_brightness(uint16_t brightness, uint32_t *led_data)
{
    float lux = (float)brightness / 65535.0f * 1.2f;  /* 1 lux ≈ 1.2 counts */
    if (lux < 0.0f) lux = 0.0f;
    if (lux > 100.0f) lux = 100.0f;

    uint32_t brightness_led = (uint32_t)(lux * 10000.0f);  /* 0–1000000 */

    for (int i = 0; i < NUM_LEDS; i++) {
        led_data[i] = 0x00000000U;  /* clear */
        led_data[i] |= (uint32_t)brightness_led;  /* brightness */
        led_data[i] &= 0xFF000000U;  /* clear upper byte */
    }
    return 0;
}

