/*
 * Raspberry Pi Zero W – BH1750 ambient light sensor → APA102 LED strip
 *
 * Wiring:
 *   BH1750 SDA  → GPIO2 (pin 3, I2C bus 1)
 *   BH1750 SCL  → GPIO3 (pin 5, I2C bus 1)
 *   BH1750 VCC  → 3.3 V
 *   BH1750 GND  → GND
 *   APA102 DIN  → GPIO11 (pin 23, SPI0 SCLK)
 *   APA102 VCC  → 5 V (strip supports 5 V signalling)
 *   APA102 GND  → GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o light_led light_led.c -lm
 *
 * Run:
 *   ./light_led
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <math.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS          "/dev/i2c-1"
#define SPI_DEVICE       "/dev/spidev0.0"
#define SPI_SPEED_HZ     1000000U   /* 1 MHz – APA102 supports up to 5 MHz */
#define NUM_LEDS         10
#define SAMPLE_PERIOD_US 120000U    /* 120 ms between conversions */
#define MAX_RETRIES      3

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static int g_spi_fd = -1;

/* ----------------------------- Prototypes -------------------------------- */
static void signal_handler(int sig);
static int  init_i2c(void);
static int  init_spi(void);
static int  read_bh1750(uint16_t *brightness);
static int  scale_brightness(uint16_t brightness, uint32_t *led_data);
static int  send_led_data(const uint32_t *led_data, size_t len);
static void cleanup(void);

/* ----------------------------- Signal handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- I2C helpers ------------------------------- */
static int init_i2c(void)
{
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return -1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, 0x40) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x40): %s\n", strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return -1;
    }
    return 0;
}

/*
 * BH1750 single-shot mode, no register address – the device auto-increments
 * its register pointer after a power-on reset or a write of 0x00.
 * Returns 0 on success, -1 on error.
 */
static int read_bh1750(uint16_t *brightness)
{
    uint8_t buf[2];

    if (g_i2c_fd < 0)
        return -1;

    /* Trigger a single-shot conversion (no register, just a zero-length write). */
    if (write(g_i2c_fd, buf, 0) < 0) {
        fprintf(stderr, "BH1750 trigger write: %s\n", strerror(errno));
        return -1;
    }

    /* Wait for conversion to complete (max ~180 ms at 1 lux resolution). */
    usleep(SAMPLE_PERIOD_US);

    ssize_t n = read(g_i2c_fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "BH1750 read: expected 2 bytes, got %zd (%s)\n",
                n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }

    *brightness = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/* ----------------------------- SPI helpers ------------------------------- */
static int init_spi(void)
{
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE_0;
    uint8_t bits  = 8;
    uint32_t speed = SPI_SPEED_HZ;

    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        goto fail;
    }
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        goto fail;
    }
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        goto fail;
    }
    return 0;

fail:
    close(g_spi_fd);
    g_spi_fd = -1;
    return -1;
}

/*
 * APA102 expects a 32-bit zero start frame, followed by one 32-bit LED
 * frame per LED, followed by a 32-bit end frame.
 */
static int send_led_data(const uint32_t *led_data, size_t len)
{
    if (g_spi_fd < 0)
        return -1;

    size_t total = len + 1;          /* start frame + data + end frame */
    if (total > 512) {
        fprintf(stderr, "APA102 payload too large (%zu bytes)\n", total);
        return -1;
    }

    uint8_t tx[total];
    uint8_t rx[total] = {0};

    for (size_t i = 0; i < total; i++) {
        tx[i] = 0x00;                  /* zero start frame */
        if (i < len) {
            /* LED frame: 0x00 | brightness | blue | green | red */
            uint32_t frame = 0x00;
            frame |= (uint32_t)led_data[i];
            frame >>= 8;                /* blue */
            frame >>= 8;                /* green */
            frame >>= 8;                /* red */
            frame &= 0xFF;               /* clear upper byte */
            tx[i] |= (uint8_t)frame;
        }
    }

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = total;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = 8;
    tr.delay_usecs   = 0;

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    if (g_spi_fd >= 0) {
        /* Turn off all LEDs (brightness = 0, all fields = 0). */
        uint32_t off[NUM_LEDS];
        memset(off, 0, sizeof(off));
        send_led_data(off, sizeof(off));
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (init_i2c() < 0) {
        fprintf(stderr, "BH1750 init failed\n");
        return EXIT_FAILURE;
    }

    if (init_spi() < 0) {
        fprintf(stderr, "APA102 SPI init failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("BH1750 → APA102 running. Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t brightness = 0;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (read_bh1750(&brightness) == 0) {
                ok = 1;
                break;
            }
            usleep(10000);  /* 10 ms back-off before retry */
        }

        if (!ok) {
            fprintf(stderr, "BH1750 read failed after %d attempts; skipping cycle\n",
                    MAX_RETRIES);
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        uint32_t led_data[NUM_LEDS];
        scale_brightness(brightness, &led_data[0]);

        if (send_led_data(led_data, sizeof(led_data)) < 0) {
            fprintf(stderr, "Failed to send LED data\n");
        }

        usleep(SAMPLE_PERIOD_US);
    }

    cleanup();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

/* ----------------------------- Brightness scaling ------------------------- */
/*
 * BH1750 resolution: 0.5 lx at 1 lux resolution, 1 lx at 0.5 lux resolution.
 * Scale 0–65535 to 0–1000000 (APA102 full brightness range).
 */
static int scale_brightness(uint16_t brightness, uint32_t *led_data)
{
    float lux = (float)brightness / 65535.0f * 1.2f;  /* 1 lux ≈ 1.2 counts */
    if (lux < 0.0f) lux = 0.0f;
    if (lux > 100.0f) lux = 100.0f;

    uint32_t brightness_led = (uint32_t)(lux * 10000.0f);  /* 0–1000000 */

    for (int i = 0; i < NUM_LEDS; i++) {
        led_data[i] = 0x00000000U;  /* clear */
        led_data[i] |= (uint32_t)brightness_led;  /* brightness */
        led_data[i] &= 0xFF000000U;  /* clear upper byte */
    }
    return 0;
}

code:
/*
 * Raspberry Pi 3 Model B+ — BH1750 ambient-light reader + APA102 LED strip.
 *
 * Hardware:
 *   - 3 × BH1750 on I2C bus 1 (addresses 0x38, 0x39, 0x3A)
 *   - APA102 LED strip on hardware SPI (MOSI=GPIO10, SCLK=GPIO11)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o light_led light_led.c -lpigpio -lrt
 *
 * Run:
 *   sudo ./light_led
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define NUM_SENSORS          3
#define SPI_CHANNEL          0          /* CE0 on GPIO8 */
#define SPI_SPEED_HZ         1000000    /* 1 MHz */
#define SPI_FLAGS            0          /* Mode 0, active-low CE */

#define BH1750_ADDR_1        0x38
#define BH1750_ADDR_2        0x39
#define BH1750_ADDR_3        0x3A

#define BH1750_CONV_MS       180        /* Conversion time per datasheet */
#define FADE_MS              500        /* Target brightness ramp */
#define LOOP_DELAY_MS        100        /* Cycle cadence */
#define MAX_READ_RETRIES     3          /* Consecutive failures before abort */

/* APA102: 4 bytes per LED, 3 LEDs per strip frame (RGB + global brightness). */
#define NUM_LEDS_PER_STRIP  3
#define APA102_FRAME_SIZE   (NUM_LEDS_PER_STRIP * 4)
#define APA102_STRIP_BYTES  (APA102_FRAME_SIZE * 4)  /* 48 bytes */

/* Global brightness range (0–255). */
#define BRIGHTNESS_MIN      0
#define BRIGHTNESS_MAX      255

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handles[NUM_SENSORS];
static int g_spi_handle = -1;
static int g_pigpio_inited = 0;

/* ----------------------------- Prototypes -------------------------------- */
static void signal_handler(int sig);
static int  init_pigpio(void);
static int  init_i2c_sensors(void);
static int  read_bh1750(int handle, uint8_t addr);
static int  read_all_sensors(int *out);
static int  compute_average(int *raw, int count, int *out);
static int  set_apa102_brightness(int brightness);
static void fade_apa102(int brightness);
static void cleanup(void);

/* ----------------------------- Signal ------------------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- pigpio ------------------------------------- */
static int init_pigpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }
    g_pigpio_inited = 1;
    return 0;
}

static void cleanup_pigpio(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    if (g_pigpio_inited) {
        gpioTerminate();
        g_pigpio_inited = 0;
    }
}

/* ----------------------------- I2C sensors -------------------------------- */
static int init_i2c_sensors(void)
{
    for (int i = 0; i < NUM_SENSORS; i++) {
        g_i2c_handles[i] = -1;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        int addr = BH1750_ADDR_1 + i;
        g_i2c_handles[i] = i2cOpen(I2C_BUS, addr, 0);
        if (g_i2c_handles[i] < 0) {
            fprintf(stderr, "Warning: BH1750 at 0x%02X not found (handle=%d).\n",
                    addr, g_i2c_handles[i]);
            g_i2c_handles[i] = -1;
        }
    }
    return 0;
}

/*
 * Read one BH1750.  Returns 0 on success (raw stored in *out), -1 on error.
 */
static int read_bh1750(int handle, uint8_t addr)
{
    if (handle < 0 || addr < 0) {
        return -1;
    }

    /* Issue a one-shot conversion command (0x10). */
    if (i2cWriteByte(handle, 0x10) < 0) {
        return -1;
    }

    /* Wait for conversion to complete. */
    gpioDelay(BH1750_CONV_MS * 1000);  /* microseconds */

    /* Read two bytes (high byte first). */
    char buf[2];
    int n = i2cReadDevice(handle, buf, 2);
    if (n != 2) {
        return -1;
    }

    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return (int)raw;
}

static int read_all_sensors(int *out)
{
    int count = 0;
    for (int i = 0; i < NUM_SENSORS; i++) {
        int v = read_bh1750(g_i2c_handles[i], (uint8_t)i);
        if (v < 0) {
            fprintf(stderr, "Warning: sensor %d (0x%02X) read failed.\n",
                    i, (uint8_t)i);
            continue;
        }
        out[count++] = v;
    }
    return count;
}

static int compute_average(int *raw, int count, int *out)
{
    if (count <= 0) {
        return 0;
    }
    long sum = 0;
    for (int i = 0; i < count; i++) {
        sum += raw[i];
    }
    *out = (int)(sum / count);
    return 0;
}

/* ----------------------------- APA102 ------------------------------------ */
static int set_apa102_brightness(int brightness)
{
    if (brightness < BRIGHTNESS_MIN) brightness = BRIGHTNESS_MIN;
    if (brightness > BRIGHTNESS_MAX) brightness = BRIGHTNESS_MAX;

    uint8_t frame[APA102_FRAME_SIZE];
    memset(frame, 0, sizeof(frame));

    /* Global brightness byte (0x00 = off, 0xFF = full). */
    frame[0] = 0x00;
    frame[1] = 0xFF;
    frame[2] = 0x00;
    frame[3] = 0xFF;

    for (int i = 0; i < NUM_LEDS_PER_STRIP; i++) {
        uint8_t r = 0, g = 0, b = 0;
        r = (uint8_t)((brightness * 255) / (float)NUM_LEDS_PER_STRIP);
        g = (uint8_t)((brightness * 255) / (float)NUM_LEDS_PER_STRIP);
        b = (uint8_t)((brightness * 255) / (float)NUM_LEDS_PER_STRIP);
        frame[4 + i * 4] = 0xE0 | (r & 0x1F);
        frame[5 + i * 4] = 0xE0 | (g & 0x1F);
        frame[6 + i * 4] = 0xE0 | (b & 0x1F);
    }

    if (g_spi_handle >= 0) {
        if (spiWrite(g_spi_handle, (char *)frame, sizeof(frame)) < 0) {
            fprintf(stderr, "Error: SPI write failed.\n");
            return -1;
        }
    }
    return 0;
}

static void fade_apa102(int brightness)
{
    static int current = 0;
    static int target = brightness;
    static int step = 0;

    if (current == target) {
        return;
    }

    if (current < target) {
        current += step;
    } else {
        current -= step;
    }

    if (current < 0) current = 0;
    if (current > target) current = target;

    if (set_apa102_brightness(current) < 0) {
        fprintf(stderr, "Error: failed to set brightness during fade.\n");
    }
    step = (step < 50) ? 50 : (step > 250) ? 250 : step + 50;
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* Install signal handlers for graceful shutdown. */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Initialize pigpio. */
    if (init_pigpio() < 0) {
        return EXIT_FAILURE;
    }

    /* Initialize I2C sensors. */
    if (init_i2c_sensors() < 0) {
        cleanup_pigpio();
        return EXIT_FAILURE;
    }

    /* Open SPI for APA102. */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED_HZ, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle=%d).\n", g_spi_handle);
        cleanup_pigpio();
        return EXIT_FAILURE;
    }

    printf("Starting light sensor + APA102 LED strip loop. Press Ctrl+C to exit.\n");

    while (g_running) {
        int raw[NUM_SENSORS];
        int count = read_all_sensors(raw);

        if (count == 0) {
            fprintf(stderr, "Error: no valid sensor readings. Skipping cycle.\n");
            gpioDelay(LOOP_DELAY_MS * 1000);
            continue;
        }

        if (compute_average(raw, count, NULL) < 0) {
            fprintf(stderr, "Error: average computation failed.\n");
            gpioDelay(LOOP_DELAY_MS * 1000);
            continue;
        }

        int target = (int)compute_average(raw, count, NULL);

        printf("Average light: %d\n", target);

        fade_apa102(target);
        gpioDelay(FADE_MS * 1000);  /* 500 ms fade */
    }

    /* Graceful shutdown. */
    printf("\nShutting down...\n");
    fade_apa102(0);
    cleanup_pigpio();
    return EXIT_SUCCESS;
}

