/*
 * Raspberry Pi 5 – VEML7700 ambient light sensor → WS2812B LED strip
 *
 * Hardware:
 *   VEML7700  I2C  →  GPIO2  (SDA), GPIO3  (SCL)
 *   WS2812B   GPIO18 (BCM) → DIN
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o light_led light_led.c -lpigpio -lrt
 *   (pigpio is the only external dependency; no wiringPi)
 *
 * Run:
 *   sudo ./light_led
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS            1
#define I2C_ADDR           0x40          /* VEML7700 default 7-bit address */
#define I2C_RETRIES        3
#define I2C_RETRY_DELAY_US 100000        /* 100 ms */
#define LOOP_DELAY_US      200000        /* 200 ms */
#define WS2812_GPIO        18            /* BCM 18 */
#define WS2812_STRIP_LEN   10           /* 10 LEDs */
#define WS2812_BIT_HALF_US 1             /* ~1 µs half-period at 800 kHz */
#define WS2812_THRESHOLD   128           /* 50 % of 256 */
#define GAMMA              2.2f
#define MAX_LUX            10000.0f      /* sensor max output */

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd = -1;
static bool     g_pigpio_inited = false;

/* ----------------------------- Prototypes -------------------------------- */
static int  init_i2c(void);
static int  read_lux(float *lux_out);
static uint8_t gamma_correct(float lux);
static void  set_led_strip(uint8_t brightness);
static void  signal_handler(int sig);
static void  cleanup(void);

/* ----------------------------- I2C init ----------------------------------- */
static int init_i2c(void)
{
    g_i2c_fd = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        return -1;
    }
    return 0;
}

/* ----------------------------- Read lux ---------------------------------- */
/*
 * VEML7700 single-ended channel 0, 16-bit, no interrupt.
 * Returns 0 on success, -1 on failure.
 */
static int read_lux(float *lux_out)
{
    for (int attempt = 0; attempt < I2C_RETRIES; ++attempt) {
        int raw = i2cReadWordData(g_i2c_fd, 0x00);
        if (raw >= 0) {
            uint16_t value = (uint16_t)raw;
            *lux_out = (float)value / MAX_LUX;
            return 0;
        }
        fprintf(stderr, "[WARN] i2cReadWordData attempt %d/%d failed: %s\n",
                attempt + 1, I2C_RETRIES, strerror(errno));
        if (attempt < I2C_RETRIES - 1)
            gpioDelay(I2C_RETRY_DELAY_US);
    }
    return -1;
}

/* ----------------------------- Gamma correction -------------------------- */
static uint8_t gamma_correct(float lux)
{
    if (lux < 0.0f) lux = 0.0f;
    if (lux > MAX_LUX) lux = MAX_LUX;
    return (uint8_t)(powf(lux, GAMMA) + 0.5f);
}

/* ----------------------------- LED strip update -------------------------- */
static void set_led_strip(uint8_t brightness)
{
    if (!g_pigpio_inited)
        return;

    /* Simple threshold-driven on/off: WS2812B expects 0 or 1 per bit. */
    if (brightness < 0)
        brightness = 0;
    if (brightness > 255)
        brightness = 255;

    uint8_t data[WS2812_STRIP_LEN * 3];
    for (int i = 0; i < WS2812_STRIP_LEN; ++i) {
        data[i * 3 + 0] = brightness;
        data[i * 3 + 1] = brightness;
        data[i * 3 + 2] = brightness;   /* repeat for data + clock */
    }

    /* Bit-bang at ~800 kHz (half-period ~1 µs). */
    for (int i = 0; i < WS2812_STRIP_LEN * 3; ++i) {
        uint8_t byte = data[i];
        for (int b = 7; b >= 0; --b) {
            int bit = (byte >> b) & 1;
            gpioWrite(WS2812_GPIO, bit);
            gpioDelay(WS2812_BIT_HALF_US);
        }
    }
}

/* ----------------------------- Signal handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Cleanup ------------------------------------ */
static void cleanup(void)
{
    if (g_pigpio_inited) {
        gpioWrite(WS2812_GPIO, 0);
        gpioTerminate();
        g_pigpio_inited = false;
    }
    if (g_i2c_fd >= 0) {
        i2cClose(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[ERROR] sigaction");
        return EXIT_FAILURE;
    }

    /* pigpio init */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] gpioInitialise() failed\n");
        return EXIT_FAILURE;
    }
    g_pigpio_inited = true;

    /* Configure LED GPIO */
    gpioSetMode(WS2812_GPIO, PI_OUTPUT);
    gpioWrite(WS2812_GPIO, 0);

    /* I2C init */
    if (init_i2c() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("VEML7700 (0x%02X) + WS2812B on GPIO%d. Ctrl+C to exit.\n",
           I2C_ADDR, WS2812_GPIO);

    while (g_running) {
        float lux = 0.0f;
        if (read_lux(&lux) != 0) {
            fprintf(stderr, "[ERROR] Failed to read lux after %d retries; "
                            "continuing with 0 lux.\n", I2C_RETRIES);
        } else {
            uint8_t brightness = gamma_correct(lux);
            printf("Lux: %.2f  Brightness: %u\n", lux, brightness);
            set_led_strip(brightness);
        }
        gpioDelay(LOOP_DELAY_US);
    }

    cleanup();
    printf("\n[INFO] Shutdown complete.\n");
    return EXIT_SUCCESS;
}

