#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 17
#define LED_PIN 18

#define BLINK_INTERVAL_MS 500
#define SELF_TEST_SAMPLES 5
#define SELF_TEST_INTERVAL_MS 100
#define POLL_INTERVAL_MS 50
#define RAPID_BLINK_MS 100
#define RAPID_BLINK_CYCLES 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *msg) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", ts, msg);
    fflush(stdout);
}

static int safe_set_mode(unsigned pin, unsigned mode) {
    if (gpioSetMode(pin, mode) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%u, %u) failed\n", pin, mode);
        return -1;
    }
    return 0;
}

static int safe_write(unsigned pin, unsigned level) {
    if (gpioWrite(pin, level) != 0) {
        fprintf(stderr, "Error: gpioWrite(%u, %u) failed\n", pin, level);
        return -1;
    }
    return 0;
}

static int safe_read(unsigned pin) {
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "Error: gpioRead(%u) failed\n", pin);
        return -1;
    }
    return v;
}

static void cleanup(void) {
    safe_write(LED_PIN, 0);
    safe_write(BUZZER_PIN, 0);
}

static void blink_led(int duration_ms) {
    for (int i = 0; i < 10 && running; i++) {
        safe_write(LED_PIN, 1);
        gpioDelay(duration_ms * 1000);
        safe_write(LED_PIN, 0);
        gpioDelay(duration_ms * 1000);
    }
}

static void buzzer_alert(void) {
    for (int i = 0; i < 3 && running; i++) {
        safe_write(BUZZER_PIN, 1);
        gpioDelay(200 * 1000);
        safe_write(BUZZER_PIN, 0);
        gpioDelay(200 * 1000);
        safe_write(BUZZER_PIN, 1);
        gpioDelay(600 * 1000);
        safe_write(BUZZER_PIN, 0);
        gpioDelay(200 * 1000);
    }
}

static void self_test(void) {
    log_event("Starting self-test...");

    for (int i = 0; i < 2 && running; i++) {
        blink_led(BLINK_INTERVAL_MS);
        for (int j = 0; j < SELF_TEST_SAMPLES && running; j++) {
            int v = safe_read(FLAME_SENSOR_PIN);
            if (v < 0) {
                log_event("Self-test read error during blink.");
                return;
            }
            if (v == 0) {
                log_event("Flame detected during blink.");
                break;
            }
        }
        if (!running) return;
        gpioDelay(100 * 1000);
    }

    if (safe_read(FLAME_SENSOR_PIN) == 0) {
        log_event("Flame detected after self-test.");
        blink_led(RAPID_BLINK_MS);
        buzzer_alert();
        cleanup();
        exit(1);
    }

    log_event("Self-test passed.");
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    if (safe_set_mode(FLAME_SENSOR_PIN, PI_INPUT) != 0 ||
        safe_set_mode(BUZZER_PIN, PI_OUTPUT) != 0 ||
        safe_set_mode(LED_PIN, PI_OUTPUT) != 0) {
        cleanup();
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup();
        gpioTerminate();
        return 1;
    }

    log_event("System started.");

    while (running) {
        int v = safe_read(FLAME_SENSOR_PIN);
        if (v < 0) {
            log_event("Error reading flame sensor.");
            gpioDelay(POLL_INTERVAL_MS * 1000);
            continue;
        }

        if (v == 0) {
            log_event("Flame detected.");
            safe_write(LED_PIN, 1);
            safe_write(BUZZER_PIN, 1);
        } else {
            safe_write(LED_PIN, 0);
            safe_write(BUZZER_PIN, 0);
        }

        gpioDelay(POLL_INTERVAL_MS * 1000);
    }

    log_event("System shutting down.");
    cleanup();
    gpioTerminate();
    return 0;
}

