#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS        "/dev/i2c-1"
#define BH1750_ADDR     0x77
#define GPIO_LED        17
#define BUFFER_SIZE     60
#define MIN_FREQ_HZ     0.5f
#define MAX_FREQ_HZ     5.0f
#define DARKNESS_LUX    1000.0f
#define SAMPLE_PERIOD_S 1

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write16(int fd, uint8_t reg, uint16_t val) {
    uint8_t buf[3] = { reg, (uint8_t)(val >> 8), (uint8_t)(val & 0xFF) };
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "I2C write16 to 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int bh1750_init(int fd) {
    if (i2c_write16(fd, 0x00, 0x01) < 0) return -1;
    usleep(180000);
    if (i2c_write16(fd, 0x07, 0x01) < 0) return -1;
    usleep(180000);
    if (i2c_write16(fd, 0x0F, 0x00) < 0) return -1;
    usleep(180000);
    return 0;
}

static int bh1750_read_lux(int fd, float *lux_out) {
    if (i2c_write16(fd, 0x00, 0x01) < 0) return -1;
    usleep(180000);
    uint8_t buf[2];
    ssize_t n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "BH1750 read failed: expected 2 bytes, got %zd (%s)\n", n, strerror(errno));
        return -1;
    }
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static void update_circular_buffer(float *buf, int *idx, int size, float value) {
    buf[*idx] = value;
    *idx = (*idx + 1) % size;
}

static float calculate_average(const float *buf, int size) {
    float sum = 0.0f;
    for (int i = 0; i < size; i++) sum += buf[i];
    return sum / (float)size;
}

static void set_led_frequency(float lux) {
    if (lux < 0.0f) lux = 0.0f;
    float freq = MIN_FREQ_HZ + (lux / DARKNESS_LUX) * (MAX_FREQ_HZ - MIN_FREQ_HZ);
    if (freq < MIN_FREQ_HZ) freq = MIN_FREQ_HZ;
    if (freq > MAX_FREQ_HZ) freq = MAX_FREQ_HZ;
    int period_us = (int)(1000000.0f / freq);
    if (period_us < 1) period_us = 1;
    if (period_us > 1000000) period_us = 1000000;
    if (gpioWrite(GPIO_LED, 1) < 0) {
        fprintf(stderr, "Failed to set LED high: %s\n", strerror(errno));
        return;
    }
    usleep(period_us / 2);
    if (gpioWrite(GPIO_LED, 0) < 0) {
        fprintf(stderr, "Failed to set LED low: %s\n", strerror(errno));
        return;
    }
    usleep(period_us / 2);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", BH1750_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (bh1750_init(i2c_fd) < 0) {
        fprintf(stderr, "BH1750 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    if (gpioSetMode(GPIO_LED, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output: %s\n", GPIO_LED, strerror(errno));
        close(i2c_fd);
        return 1;
    }
    if (gpioWrite(GPIO_LED, 0) < 0) {
        fprintf(stderr, "Failed to initialize GPIO%d low: %s\n", GPIO_LED, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    float lux_buffer[BUFFER_SIZE];
    int buffer_index = 0;
    int buffer_count = 0;

    while (g_running) {
        float lux;
        if (bh1750_read_lux(i2c_fd, &lux) < 0) {
            fprintf(stderr, "Sensor read failed, skipping sample.\n");
            sleep(SAMPLE_PERIOD_S);
            continue;
        }

        update_circular_buffer(lux_buffer, &buffer_index, BUFFER_SIZE, lux);
        buffer_count = BUFFER_SIZE;

        float avg = calculate_average(lux_buffer, buffer_count);

        printf("Lux: %.2f, Average: %.2f\n", lux, avg);

        set_led_frequency(avg);

        sleep(SAMPLE_PERIOD_S);
    }

    gpioWrite(GPIO_LED, 0);
    gpioSetMode(GPIO_LED, PI_INPUT);
    close(i2c_fd);
    gpioTerminate();
    printf("\nProgram terminated cleanly.\n");
    return 0;
}

