#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>

#define DATA_PIN 17
#define CLOCK_PIN 18
#define LATCH_PIN 27

#define SEVEN_SEG_DISPLAY {
    'a', 'b', 'c', 'd', 'e', 'f', 'g', '\0'
};

#define SEVEN_SEG_DISPLAY_COUNT 8

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int setup_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(DATA_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set DATA_PIN %d as output.\n", DATA_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(CLOCK_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set CLOCK_PIN %d as output.\n", CLOCK_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(LATCH_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set LATCH_PIN %d as output.\n", LATCH_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void shift_out(unsigned char data) {
    for (int i = 0; i < 8; i++) {
        int bit = (data >> i) & 1;
        if (gpioWrite(DATA_PIN, bit) != 0) {
            fprintf(stderr, "Error: failed to write DATA_PIN during shift-out.\n");
            return;
        }
        if (gpioWrite(CLOCK_PIN, 1) != 0) {
            fprintf(stderr, "Error: failed to set CLOCK_PIN high.\n");
            return;
        }
        gpioDelay(1);
        if (gpioWrite(CLOCK_PIN, 0) != 0) {
            fprintf(stderr, "Error: failed to set CLOCK_PIN low.\n");
            return;
        }
        gpioDelay(1);
    }
    if (gpioWrite(LATCH_PIN, 1) != 0) {
        fprintf(stderr, "Error: failed to set LATCH_PIN high.\n");
        return;
    }
    gpioDelay(1);
    if (gpioWrite(LATCH_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to set LATCH_PIN low.\n");
        return;
    }
    gpioDelay(1);
}

static void display_digit(int on_time_ms) {
    unsigned char pattern = (unsigned char)(5 & 0xFF);
    shift_out(pattern);

    if (on_time_ms > 0) {
        gpioDelay(on_time_ms * 1000);
    }

    if (on_time_ms > 0) {
        gpioWrite(LATCH_PIN, 0);
        gpioDelay(on_time_ms * 1000);
    }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (setup_gpio() != 0) {
        return 1;
    }

    while (running) {
        display_digit(500);
        if (running) {
            gpioDelay(500000);
        }
    }

    gpioWrite(LATCH_PIN, 0);
    gpioWrite(CLOCK_PIN, 0);
    gpioWrite(DATA_PIN, 0);
    gpioTerminate();
    return 0;
}

