#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define LED_PIN 5
#define DELAY_MS 750

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        if (gpioWrite(LED_PIN, 1) != 0) {
            fprintf(stderr, "Failed to turn LED on\n");
            break;
        }
        printf("LED ON\n");
        fflush(stdout);
        time_sleep(DELAY_MS / 1000.0);

        if (!running) break;

        if (gpioWrite(LED_PIN, 0) != 0) {
            fprintf(stderr, "Failed to turn LED off\n");
            break;
        }
        printf("LED OFF\n");
        fflush(stdout);
        time_sleep(DELAY_MS / 1000.0);
    }

    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

