static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int setup_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d).\n", gpioInitialise());
        return -1;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", LED_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", BUTTON_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPullUpDown(BUTTON_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error: failed to set pull-down on GPIO%d.\n", BUTTON_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise LED state on GPIO%d.\n", LED_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void) {
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (setup_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Press the button (GPIO%d) to blink the LED (GPIO%d) at %d ms intervals.\n",
           BUTTON_PIN, LED_PIN, BLINK_DELAY_MS);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        if (gpioRead(BUTTON_PIN) == 1) {
            if (gpioWrite(LED_PIN, 1) != 0) {
                fprintf(stderr, "Error: failed to turn LED on.\n");
                break;
            }
            gpioDelay(BLINK_DELAY_MS * 1000);
            if (!running) break;

            if (gpioWrite(LED_PIN, 0) != 0) {
                fprintf(stderr, "Error: failed to turn LED off.\n");
                break;
            }
            gpioDelay(BLINK_DELAY_MS * 1000);
        } else {
            if (gpioWrite(LED_PIN, 0) != 0) {
                fprintf(stderr, "Error: failed to turn LED off.\n");
                break;
            }
            gpioDelay(100 * 1000);
        }
    }

    cleanup_gpio();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

