#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* FXOS8700CQ I2C address (SA0 tied to GND) */
#define FXOS8700_ADDR 0x49

/* FXOS8700CQ register addresses */
#define FXOS8700_WHO_AM_I   0x0D
#define FXOS8700_WHO_AM_I_VAL 0x49
#define FXOS8700_CTRL_REG1  0x2A
#define FXOS8700_CTRL_REG2  0x2B
#define FXOS8700_M_CTRL_REG1 0x5B
#define FXOS8700_M_CTRL_REG2 0x5C
#define FXOS8700_OUT_X_MSB  0x01

/* ±2 g full-scale range */
#define FXOS8700_RANGE_2G  0x00

/* Impact threshold (raw units) */
#define IMPACT_THRESHOLD 100.0f

/* I2C bus on Raspberry Pi Zero W */
#define I2C_BUS 1

static int i2c_handle = -1;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

/* Write one byte to a register; returns 0 on success, -1 on error */
static int write_register(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg=0x%02X, val=0x%02X): %d\n",
                reg, value, rc);
        return -1;
    }
    return 0;
}

/* Read one byte from a register; returns 0 on success, -1 on error */
static int read_register(int handle, uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg=0x%02X): %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

/* Read a block of bytes starting at reg; returns 0 on success, -1 on error */
static int read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "I2C block read failed (reg=0x%02X, len=%u, got=%d)\n",
                reg, len, rc);
        return -1;
    }
    return 0;
}

/* Initialize the FXOS8700CQ; returns 0 on success, -1 on error */
static int init_fxos8700(int handle)
{
    uint8_t who_am_i = 0;

    /* Verify device identity */
    if (read_register(handle, FXOS8700_WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        return -1;
    }
    if (who_am_i != FXOS8700_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, FXOS8700_WHO_AM_I_VAL);
        return -1;
    }

    /* Standby mode: clear ACTIVE bit in CTRL_REG1 */
    if (write_register(handle, FXOS8700_CTRL_REG1, 0x00) != 0)
        return -1;

    /* Set magnetometer to ±4 g full-scale range */
    if (write_register(handle, FXOS8700_M_CTRL_REG1, 0x00) != 0)
        return -1;

    /* Set magnetometer to continuous-conversion mode */
    if (write_register(handle, FXOS8700_M_CTRL_REG2, 0x00) != 0)
        return -1;

    /* Set accelerometer to ±2 g full-scale range */
    if (write_register(handle, FXOS8700_CTRL_REG1, 0x00) != 0)
        return -1;

    /* Set accelerometer to continuous-conversion mode */
    if (write_register(handle, FXOS8700_CTRL_REG2, 0x00) != 0)
        return -1;

    /* Activate: ACTIVE bit in CTRL_REG1 */
    if (write_register(handle, FXOS8700_CTRL_REG1, 0x01) != 0)
        return -1;

    return 0;
}

/* Read acceleration data; returns 0 on success, -1 on error */
static int read_acceleration(int handle, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t buf[6];
    if (read_block(handle, FXOS8700_OUT_X_MSB, buf, 6) != 0)
        return -1;

    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

/* Compute acceleration magnitude in g */
static float calculate_magnitude(int16_t x, int16_t y, int16_t z)
{
    float x_g = (float)x / 32768.0f * 2.0f;
    float y_g = (float)y / 32768.0f * 2.0f;
    float z_g = (float)z / 32768.0f * 2.0f;
    return sqrtf(x_g * x_g + y_g * y_g + z_g * z_g);
}

/* Append impact event to log file */
static int log_impact(const char *filename, int16_t x, int16_t y, int16_t z, float magnitude)
{
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        perror("fopen");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%d,%d,%d,%.3f\n", timestamp, x, y, z, magnitude);
    fclose(fp);
    return 0;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, FXOS8700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_fxos8700(i2c_handle) != 0) {
        fprintf(stderr, "FXOS8700CQ initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Impact detection started. Press Ctrl-C to exit.\n");

    while (program_running) {
        int16_t x, y, z;

        if (read_acceleration(i2c_handle, &x, &y, &z) != 0) {
            fprintf(stderr, "Read error; continuing...\n");
            gpioDelay(50000); /* 50 ms */
            continue;
        }

        float magnitude = calculate_magnitude(x, y, z);

        if (magnitude > IMPACT_THRESHOLD) {
            printf("Impact detected! Magnitude: %.2f g\n", magnitude);
            if (log_impact("impact_log.txt", x, y, z, magnitude) != 0)
                fprintf(stderr, "Warning: failed to log impact event\n");
        }

        gpioDelay(50000); /* 50 ms */
    }

    printf("\nShutting down...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

