#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* L3G4200D register addresses */
#define L3G4200D_WHO_AM_I   0x0F
#define L3G4200D_CTRL_REG1  0x20
#define L3G4200D_CTRL_REG2  0x21
#define L3G4200D_CTRL_REG3  0x22
#define L3G4200D_CTRL_REG4  0x23
#define L3G4200D_OUT_X_L    0x28
#define L3G4200D_OUT_X_H    0x29
#define L3G4200D_OUT_Y_L    0x2A
#define L3G4200D_OUT_Y_H    0x2B
#define L3G4200D_OUT_Z_L    0x2C
#define L3G4200D_OUT_Z_H    0x2D

#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "gyro_log.txt"
#define SAMPLE_RATE_HZ 20
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)
#define CALIB_SAMPLES 100
#define THRESHOLD_DPS 50.0f

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

typedef struct {
    float x_offset;
    float y_offset;
    float z_offset;
} gyro_offsets_t;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (burst reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C burst read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int verify_who_am_i(int fd) {
    uint8_t who = 0;
    if (i2c_read_reg8(fd, L3G4200D_WHO_AM_I, &who) < 0) return -1;
    if (who != 0x3D) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x3D\n", who);
        return -1;
    }
    return 0;
}

static int init_gyroscope(int fd) {
    if (i2c_write_reg8(fd, L3G4200D_CTRL_REG1, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, L3G4200D_CTRL_REG2, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, L3G4200D_CTRL_REG3, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, L3G4200D_CTRL_REG4, 0x0C) < 0) return -1;
    return 0;
}

static int read_gyro_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (i2c_read_burst(fd, L3G4200D_OUT_X_L, buf, 6) < 0) return -1;
    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

static int calibrate_gyroscope(int fd, gyro_offsets_t *off) {
    int16_t x, y, z;
    float sx = 0.0f, sy = 0.0f, sz = 0.0f;
    int ok = 0;

    printf("Calibrating gyroscope (%d samples)...\n", CALIB_SAMPLES);
    for (int i = 0; i < CALIB_SAMPLES; i++) {
        if (read_gyro_data(fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Calibration read failed at sample %d\n", i);
            goto fail;
        }
        sx += x;
        sy += y;
        sz += z;
        usleep(10000);
        ok++;
    }
    if (ok == 0) goto fail;

    off->x_offset = (float)sx / ok;
    off->y_offset = (float)sy / ok;
    off->z_offset = (float)sz / ok;
    printf("Calibration complete. Offsets: X=%.2f, Y=%.2f, Z=%.2f\n",
           off->x_offset, off->y_offset, off->z_offset);
    return 0;

fail:
    fprintf(stderr, "Calibration failed.\n");
    return -1;
}

static void log_data(FILE *fp, float x, float y, float z) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) return;
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.2f,%.2f\n", ts, x, y, z);
    fflush(fp);
}

static void check_threshold(FILE *fp, float x, float y, float z) {
    if (fabsf(x) > THRESHOLD_DPS || fabsf(y) > THRESHOLD_DPS || fabsf(z) > THRESHOLD_DPS) {
        fprintf(stderr, "Alert: gyro exceeded threshold (%.2f, %.2f, %.2f) at %s\n",
                x, y, z, ctime(NULL));
        fprintf(fp, "ALERT: gyro exceeded threshold (%.2f, %.2f, %.2f) at %s\n",
                x, y, z, ctime(NULL));
        fflush(fp);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, 0x72) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x72: %s\n", strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    if (verify_who_am_i(g_i2c_fd) < 0) {
        fprintf(stderr, "Gyroscope not detected on bus.\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    if (init_gyroscope(g_i2c_fd) < 0) {
        fprintf(stderr, "Gyroscope initialization failed.\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    gyro_offsets_t off;
    if (calibrate_gyroscope(g_i2c_fd, &off) < 0) {
        fprintf(stderr, "Gyroscope calibration failed.\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("Logging to %s at %d Hz. Press Ctrl+C to stop.\n", LOG_FILE, SAMPLE_RATE_HZ);

    while (g_running) {
        int16_t x, y, z;
        if (read_gyro_data(g_i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Read error, retrying...\n");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }
