#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ADXL345 I2C address (AD0 tied to GND) */
#define ADXL345_ADDRESS 0x2D

/* ADXL345 register addresses */
#define ADXL345_DEVID       0x00
#define ADXL345_BW_RATE     0x2C
#define ADXL345_POWER_CTL   0x2D
#define ADXL345_DATAX0      0x32

/* Expected device ID */
#define ADXL345_DEVID_VALUE 0xE5

/* GPIO pin for LED (BCM numbering) */
#define LED_PIN 17

/* Threshold for acceleration (g) */
#define ACCEL_THRESHOLD 2.0

/* Sampling interval (microseconds) */
#define SAMPLE_INTERVAL_US 100000

/* Global variables for cleanup */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float x;
    float y;
    float z;
} accel_data_t;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Write a single byte to an ADXL345 register */
static int adxl_write_reg(uint8_t reg, uint8_t value) {
    char buf[2] = { (char)reg, (char)value };
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Error writing reg 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

/* Read a single byte from an ADXL345 register */
static int adxl_read_reg(uint8_t reg, uint8_t *value) {
    if (i2cWriteDevice(i2c_handle, (char *)&reg, 1) != 0) {
        fprintf(stderr, "Error selecting reg 0x%02X\n", reg);
        return -1;
    }
    if (i2cReadDevice(i2c_handle, (char *)value, 1) != 1) {
        fprintf(stderr, "Error reading reg 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

/* Initialize the ADXL345 accelerometer */
static int init_adxl345(void) {
    uint8_t devid = 0;

    /* Verify device ID */
    if (adxl_read_reg(ADXL345_DEVID, &devid) != 0) {
        return -1;
    }
    if (devid != ADXL345_DEVID_VALUE) {
        fprintf(stderr, "Unexpected device ID: 0x%02X (expected 0x%02X)\n",
                devid, ADXL345_DEVID_VALUE);
        return -1;
    }

    /* Set data rate to 100 Hz (0x0B) */
    if (adxl_write_reg(ADXL345_BW_RATE, 0x0B) != 0) {
        return -1;
    }

    /* Set full resolution mode (0x08) and enable measurement (0x08) */
    if (adxl_write_reg(ADXL345_POWER_CTL, 0x08) != 0) {
        return -1;
    }

    return 0;
}

/* Read acceleration data from the ADXL345 */
static int read_acceleration(accel_data_t *data) {
    uint8_t buf[6];
    int16_t x, y, z;

    if (i2cWriteDevice(i2c_handle, (char *)ADXL345_DATAX0, 0) != 0) {
        fprintf(stderr, "Error selecting data registers\n");
        return -1;
    }

    if (i2cReadDevice(i2c_handle, (char *)buf, 6) != 6) {
        fprintf(stderr, "Error reading acceleration data\n");
        return -1;
    }

    x = (int16_t)((buf[1] << 8) | buf[0]);
    y = (int16_t)((buf[3] << 8) | buf[2]);
    z = (int16_t)((buf[5] << 8) | buf[4]);

    data->x = (float)x / 8192.0f;  /* 4 mg/LSB => 1/8192 g */
    data->y = (float)y / 8192.0f;
    data->z = (float)z / 8192.0f;

    return 0;
}

/* Log acceleration data to file */
static void log_acceleration(accel_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, data.x, data.y, data.z);
    fflush(log_file);
}

/* Cleanup resources */
static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    accel_data_t data;
    int led_state = 0;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Open I2C bus 1 at ADXL345 address */
    i2c_handle = i2cOpen(1, ADXL345_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Initialize ADXL345 */
    if (init_adxl345() != 0) {
        fprintf(stderr, "ADXL345 initialisation failed\n");
        cleanup();
        return 1;
    }

    /* Configure LED pin as output and ensure it is off */
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    /* Open log file */
    log_file = fopen("accel_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    /* Set up signal handlers */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Starting data acquisition (Ctrl+C to stop)...\n");

    /* Main loop */
    while (!terminate) {
        if (read_acceleration(&data) == 0) {
            log_acceleration(data);

            /* Check acceleration threshold */
            if (fabsf(data.x) > ACCEL_THRESHOLD ||
                fabsf(data.y) > ACCEL_THRESHOLD ||
                fabsf(data.z) > ACCEL_THRESHOLD) {
                if (!led_state) {
                    gpioWrite(LED_PIN, 1);
                    led_state = 1;
                }
            } else {
                if (led_state) {
                    gpioWrite(LED_PIN, 0);
                    led_state = 0;
                }
            }
        } else {
            fprintf(stderr, "Error reading acceleration data\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

