#define LSM303_MAG_CNTL4   0x33
#define LSM303_MAG_CNTL5   0x34
#define LSM303_MAG_CNTL6   0x35
#define LSM303_MAG_CNTL7   0x36
#define LSM303_MAG_CNTL8   0x37
#define LSM303_MAG_CNTL9   0x38
#define LSM303_MAG_CNTL10  0x39
#define LSM303_MAG_CNTL11  0x3A
#define LSM303_MAG_CNTL12  0x3B
#define LSM303_MAG_CNTL13  0x3C
#define LSM303_MAG_CNTL14  0x3D
#define LSM303_MAG_CNTL15  0x3E
#define LSM303_MAG_CNTL16  0x3F

/* ---- Scaling factors ---- */
#define ACCEL_SCALE 0.000244f   /* 244 mg/LSB at ±2 g  */
#define MAG_SCALE   0.00014f    /* 14 mGauss/LSB at ±1.3 T */

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_accel = -1;
static int g_i2c_mag   = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ---- */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        perror("i2c_write_reg8: write");
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        perror("i2c_read_reg8: write");
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        perror("i2c_read_reg8: read");
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *val)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        perror("i2c_read_reg16: write");
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        perror("i2c_read_reg16: read");
        return -1;
    }
    *val = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

/* ---- Sensor init ---- */
static int init_lsm303(void)
{
    /* Open /dev/i2c-1 */
    int accel_fd = open("/dev/i2c-1", O_RDWR);
    if (accel_fd < 0) {
        perror("open /dev/i2c-1");
        return -1;
    }
    if (ioctl(accel_fd, I2C_SLAVE, LSM303_ADDR_ACCEL) < 0) {
        perror("ioctl I2C_SLAVE accel");
        close(accel_fd);
        return -1;
    }
    g_i2c_accel = accel_fd;

    int mag_fd = open("/dev/i2c-1", O_RDWR);
    if (mag_fd < 0) {
        perror("open /dev/i2c-1");
        close(accel_fd);
        return -1;
    }
    if (ioctl(mag_fd, I2C_SLAVE, LSM303_ADDR_MAG) < 0) {
        perror("ioctl I2C_SLAVE mag");
        close(accel_fd);
        close(mag_fd);
        return -1;
    }
    g_i2c_mag = mag_fd;

    /* Accelerometer: ±2 g, high-resolution off */
    if (i2c_write_reg8(g_i2c_accel, LSM303_ACCEL_XOUT_H, 0x00) < 0) {
        fprintf(stderr, "Failed to configure accelerometer\n");
        close(accel_fd);
        close(mag_fd);
        return -1;
    }
    /* Magnetometer: ±1.3 T, high-resolution off */
    if (i2c_write_reg8(g_i2c_mag, LSM303_MAG_CNTL2, 0x00) < 0) {
        fprintf(stderr, "Failed to configure magnetometer\n");
        close(accel_fd);
        close(mag_fd);
        return -1;
    }
    /* Enable both sensors */
    if (i2c_write_reg8(g_i2c_mag, LSM303_MAG_CNTL3, 0x01) < 0) {
        fprintf(stderr, "Failed to enable magnetometer\n");
        close(accel_fd);
        close(mag_fd);
        return -1;
    }
    return 0;
}

/* ---- Read raw samples ---- */
static int read_accel(int16_t *ax, int16_t *ay, int16_t *az)
{
    if (i2c_read_reg16(g_i2c_accel, LSM303_ACCEL_XOUT_H, ax) < 0) return -1;
    if (i2c_read_reg16(g_i2c_accel, LSM303_ACCEL_YOUT_H, ay) < 0) return -1;
    if (i2c_read_reg16(g_i2c_accel, LSM303_ACCEL_ZOUT_H, az) < 0) return -1;
    return 0;
}

static int read_mag(int16_t *mx, int16_t *my, int16_t *mz)
{
    uint8_t mr;
    if (i2c_read_reg8(g_i2c_mag, LSM303_MAG_MR_H, &mr) < 0) return -1;
    if (mr & 0x01) {
        if (i2c_write_reg8(g_i2c_mag, LSM303_MAG_CNTL3, 0x01) < 0) return -1;
    }
    if (i2c_read_reg16(g_i2c_mag, LSM303_MAG_CNTL6, mx) < 0) return -1;
    if (i2c_read_reg16(g_i2c_mag, LSM303_MAG_CNTL8, my) < 0) return -1;
    if (i2c_read_reg16(g_i2c_mag, LSM303_MAG_CNTL10, mz) < 0) return -1;
    return 0;
}

/* ---- Convert to physical units ---- */
static void convert(int16_t raw_ax, int16_t raw_ay, int16_t raw_az,
                    int16_t raw_mx, int16_t raw_my, int16_t raw_mz,
                    float *ax_g, float *ay_g, float *az_g,
                    float *mx_gauss, float *my_gauss, float *mz_gauss)
{
    *ax_g = (float)raw_ax * ACCEL_SCALE / 1000.0f;
    *ay_g = (float)raw_ay * ACCEL_SCALE / 1000.0f;
    *az_g = (float)raw_az * ACCEL_SCALE / 1000.0f;
    *mx_gauss = (float)raw_mx * MAG_SCALE / 1000.0f;
    *my_gauss = (float)raw_my * MAG_SCALE / 1000.0f;
    *mz_gauss = (float)raw_mz * MAG_SCALE / 1000.0f;
}

/* ---- Tilt-compensated heading ---- */
static float calc_heading(float ax, float ay, float az, float mx, float my, float mz)
{
    float roll = atan2f(ay, az);
    float pitch = atan2f(-ax, sqrtf(ay * ay + az * az));
    float heading = atan2f(-my, mx) * 180.0f / (float)M_PI;
    if (pitch < 0) pitch = -pitch;
    if (roll < 0) roll = -roll;
    float cos_roll = cosf(roll);
    float cos_pitch = cosf(pitch);
    float sin_roll = sinf(roll);
    float sin_pitch = sinf(pitch);
    float heading_comp = heading + roll * sin_pitch + pitch * sin_roll;
    if (heading_comp < 0) heading_comp += 360.0f;
    if (heading_comp >= 360.0f) heading_comp -= 360.0f;
    return heading_comp;
}

/* ---- Logging ---- */
static void log_data(float ax, float ay, float az,
                     float mx, float my, float mz,
                     float heading)
{
    FILE *fp = fopen("compass_log.txt", "a");
    if (!fp) {
        perror("fopen compass_log.txt");
        return;
    }
    fseek(fp, 0, SEEK_END);
    if (ftell(fp) == 0) {
        fprintf(fp, "timestamp,heading_g,ax_g,ay_g,az_g,mx_gauss,my_gauss,mz_gauss\n");
    }
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
            ts, heading, ax, ay, az, mx, my, mz);
    fclose(fp);
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_i2c_accel >= 0) {
        close(g_i2c_accel);
        g_i2c_accel = -1;
    }
    if (g_i2c_mag >= 0) {
        close(g_i2c_mag);
        g_i2c_mag = -1;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (init_lsm303() < 0) {
        fprintf(stderr, "LSM303DLHC init failed\n");
        gpioTerminate();
        return 1;
    }

    printf("LSM303DLHC initialised. Logging to compass_log.txt (Ctrl+C to stop)\n");

    while (g_running) {
        int16_t raw_ax, raw_ay, raw_az, raw_mx, raw_my, raw_mz;
        float ax_g, ay_g, az_g, mx_gauss, my_gauss, mz_gauss;
        float heading;

        if (read_accel(&raw_ax, &raw_ay, &raw_az) < 0 ||
            read_mag(&raw_mx, &raw_my, &raw_mz) < 0) {
            fprintf(stderr, "Sensor read error — skipping sample\n");
            gpioDelay(100000);
            continue;
        }

        convert(raw_ax, raw_ay, raw_az, raw_mx, raw_my, raw_mz,
                &ax_g, &ay_g, &az_g, &mx_gauss, &my_gauss, &mz_gauss);
        heading = calc_heading(ax_g, ay_g, az_g, mx_gauss, my_gauss, mz_gauss);

        log_data(ax_g, ay_g, az_g, mx_gauss, my_gauss, mz_gauss, heading);
        gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

