/*
 * VL6180X Time-of-Flight distance sensor reader for Raspberry Pi 3 Model B+.
 *
 * Wiring:
 *   VL6180X SDA  -> GPIO2 (I2C bus 1 SDA, pin 3)
 *   VL6180X SCL  -> GPIO3 (I2C bus 1 SCL, pin 5)
 *   VL6180X VDD  -> 3.3 V (pin 1)
 *   VL6180X GND  -> GND  (pin 6)
 *
 * Build:  gcc -O2 -Wall -o vl6180x_door vl6180x_door.c -lpigpio -lrt
 * Run:    sudo ./vl6180x_door
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- VL6180X constants (16-bit register addresses, big-endian on bus) ---- */
#define VL6180X_I2C_BUS        1
#define VL6180X_I2C_ADDR       0x39

#define REG_SYSTEM_START       0x0000
#define REG_SYSRANGE_START     0x0010
#define REG_RESULT_RANGE       0x0062
#define REG_RESULT_INT_STATUS  0x004F
#define REG_RESULT_INT_MASK    0x0046
#define REG_RESULT_RANGE_VAL   0x0062  /* redundant but explicit */

#define EXPECTED_RANGE_VAL     100     /* mm */
#define SAMPLE_PERIOD_US       100000  /* 100 ms */
#define INIT_RETRIES            3
#define INIT_RETRY_DELAY_US     100000

/* ---- Application constants ---- */
#define LOG_FILE_NAME           "distance_log.txt"
#define DOOR_OPEN_THRESHOLD_MM  100

/* ---- Globals for signal-safe cleanup ---- */
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;
static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit register address followed by a 16-bit value.        */
/* The VL6180X expects big-endian data on the bus.                    */
/* ------------------------------------------------------------------ */
static int vl6180x_write_reg16(uint16_t reg, uint16_t value)
{
    char buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (value >> 8) & 0xFF;
    buf[3] = value & 0xFF;
    return i2cWriteDevice(g_i2c_handle, buf, 4);
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit register.                                           */
/* ------------------------------------------------------------------ */
static int vl6180x_read_reg16(uint16_t reg, uint16_t *out)
{
    char addr[2];
    char data[2];

    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;

    if (i2cWriteDevice(g_i2c_handle, addr, 2) < 0)
        return -1;

    if (i2cReadDevice(g_i2c_handle, data, 2) != 2)
        return -1;

    *out = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise the VL6180X: mandatory sequence from the datasheet.      */
/* ------------------------------------------------------------------ */
static int vl6180x_init(void)
{
    int retries = 0;

    /* 1. Software reset: write 0x00 to SYSTEM_START (0x0000). */
    if (vl6180x_write_reg16(REG_SYSTEM_START, 0x0000) < 0) {
        fprintf(stderr, "VL6180X: software reset write failed (reg 0x0000)\n");
        return -1;
    }
    gpioDelay(10000);  /* 10 ms settle */

    /* 2. Mandatory sequence: write 0x00 to each of the first 16 registers. */
    for (uint16_t i = 0x0000; i <= 0x001F; i++) {
        if (vl6180x_write_reg16(i, 0x0000) < 0) {
            fprintf(stderr, "VL6180X: mandatory write failed at reg 0x%04X\n", i);
            return -1;
        }
    }

    /* 3. Set integration time (0x002C) to 0x0000 (shortest). */
    if (vl6180x_write_reg16(0x002C, 0x0000) < 0) {
        fprintf(stderr, "VL6180X: integration-time write failed\n");
        return -1;
    }

    /* 4. Start ranging: write 0x01 to SYSTEM_START (0x0000). */
    if (vl6180x_write_reg16(REG_SYSTEM_START, 0x0001) < 0) {
        fprintf(stderr, "VL6180X: start-ranging write failed\n");
        return -1;
    }

    gpioDelay(10000);  /* 10 ms for first measurement */
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read distance in mm. Returns -1 on error.                          */
/* ------------------------------------------------------------------ */
static int vl6180x_read_distance(void)
{
    uint16_t range_raw = 0;

    if (vl6180x_read_reg16(REG_RESULT_RANGE_VAL, &range_raw) < 0) {
        fprintf(stderr, "VL6180X: range read failed\n");
        return -1;
    }

    /* Clear interrupt by reading INT_STATUS (0x004F) then masking. */
    uint16_t int_status = 0;
    if (vl6180x_read_reg16(REG_RESULT_INT_STATUS, &int_status) < 0) {
        fprintf(stderr, "VL6180X: INT_STATUS read failed\n");
        return -1;
    }
    if (vl6180x_write_reg16(REG_RESULT_INT_MASK, int_status) < 0) {
        fprintf(stderr, "VL6180X: INT_MASK write failed\n");
        return -1;
    }

    return (int)range_raw;
}

/* ------------------------------------------------------------------ */
/* Log a reading with timestamp and door-state string.                */
/* ------------------------------------------------------------------ */
static void log_data(int distance, int door_state)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t == NULL) {
        strncpy(ts, "UNKNOWN", sizeof(ts) - 1);
        ts[sizeof(ts) - 1] = '\0';
    } else {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    }

    if (fprintf(g_log_file, "%s, Distance: %d mm, Door: %s\n",
                ts, distance, door_state ? "CLOSED" : "OPEN") < 0) {
        fprintf(stderr, "Log write failed\n");
    } else {
        fflush(g_log_file);
    }
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    g_i2c_handle = i2cOpen(VL6180X_I2C_BUS, VL6180X_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X (err %d)\n",
                VL6180X_I2C_BUS, VL6180X_I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Sensor init with retries ---- */
    int init_ok = 0;
    for (int attempt = 0; attempt < INIT_RETRIES; attempt++) {
        if (vl6180x_init() == 0) {
            init_ok = 1;
            break;
        }
        fprintf(stderr, "Init attempt %d/%d failed; retrying in %d ms\n",
                attempt + 1, INIT_RETRIES, INIT_RETRY_DELAY_US / 1000);
        gpioDelay(INIT_RETRY_DELAY_US);
    }

    if (!init_ok) {
        fprintf(stderr, "VL6180X not detected or init sequence failed after %d attempts.\n",
                INIT_RETRIES);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        perror("fopen(" LOG_FILE_NAME ")");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("VL6180X door monitor started. Logging to %s every %d ms.\n",
           LOG_FILE_NAME, SAMPLE_PERIOD_US / 1000);
    printf("Press Ctrl+C to exit.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        int distance = vl6180x_read_distance();

        if (distance < 0) {
            fprintf(stderr, "Read error — attempting re-initialisation...\n");
            if (vl6180x_init() < 0) {
                fprintf(stderr, "Re-init failed; will retry next cycle.\n");
            }
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        int door_state = (distance < DOOR_OPEN_THRESHOLD_MM) ? 1 : 0;

        log_data(distance, door_state);
        printf("Distance: %d mm, Door: %s\n", distance, door_state ? "CLOSED" : "OPEN");

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

