/*
 * IMP23ABSU TDOA Logger for Raspberry Pi 4 Model B
 *
 * Samples two IMP23ABSU ultrasonic MEMS microphones on I2C bus 1 at
 * 10 ms intervals, computes the time-difference-of-arrival (TDOA),
 * and appends CSV rows to audio_log.dat.
 *
 * Wiring:
 *   IMP23ABSU VDD  -> 3.3 V (Pin 1)
 *   IMP23ABSU GND  -> GND   (Pin 9)
 *   IMP23ABSU SDA  -> GPIO2 / I2C1 SDA (Pin 3)
 *   IMP23ABSU SCL  -> GPIO3 / I2C1 SCL (Pin 5)
 *
 * Build:  gcc -O2 -Wall -Wextra -o tdoa_logger tdoa_logger.c -lpigpio -lrt
 * Run:    sudo ./tdoa_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

/* ---- Configuration ---- */
#define I2C_BUS              1
#define SAMPLE_INTERVAL_US   10000   /* 10 ms */
#define LOG_FILE             "audio_log.dat"
#define NUM_SENSORS          2
#define MAX_RETRIES          3

/* IMP23ABSU register map (16-bit registers, big-endian on the bus) */
#define REG_DEVICE_ID        0x00
#define REG_DATA_READY       0x04
#define REG_DATA_OUT         0x06
#define REG_CTRL             0x0F

/* CTRL register bits */
#define CTRL_MEASURE         0x01
#define CTRL_INT_EN          0x02
#define CTRL_INT_CLEAR       0x04

/* Expected device ID for IMP23ABSU */
#define IMP23ABSU_DEV_ID     0x23

/* ---- Globals ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handles[NUM_SENSORS];
static FILE *g_log_file = NULL;
static int  g_pigpio_inited = 0;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ---- */
static int i2c_read_reg16(int handle, uint8_t reg, uint16_t *out)
{
    char buf[2];
    int  rc;

    rc = i2cWriteByte(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[I2C] write reg 0x%02X failed: %s\n",
                reg, pigpio_error(rc));
        return -1;
    }

    rc = i2cReadDevice(handle, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "[I2C] read reg 0x%02X failed: %s\n",
                reg, pigpio_error(rc));
        return -1;
    }

    *out = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

static int i2c_write_reg16(int handle, uint8_t reg, uint16_t val)
{
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)(val & 0xFF);
    buf[2] = (char)((val >> 8) & 0xFF);

    int rc = i2cWriteDevice(handle, buf, 3);
    if (rc < 0) {
        fprintf(stderr, "[I2C] write reg 0x%02X failed: %s\n",
                reg, pigpio_error(rc));
        return -1;
    }
    return 0;
}

/* ---- Sensor init ---- */
static int init_sensor(int handle)
{
    uint16_t id;

    if (i2c_read_reg16(handle, REG_DEVICE_ID, &id) != 0)
        return -1;

    if (id != IMP23ABSU_DEV_ID) {
        fprintf(stderr, "[Sensor] Unexpected device ID 0x%04X (expected 0x%04X)\n",
                id, IMP23ABSU_DEV_ID);
        return -1;
    }

    /* Clear any pending interrupt */
    if (i2c_write_reg16(handle, REG_CTRL, CTRL_INT_CLEAR) != 0)
        return -1;

    /* Start continuous measurement mode */
    if (i2c_write_reg16(handle, REG_CTRL, CTRL_MEASURE) != 0)
        return -1;

    return 0;
}

/* ---- Read one 16-bit sample ---- */
static int read_sample(int handle, int16_t *sample)
{
    uint16_t raw;

    if (i2c_read_reg16(handle, REG_DATA_OUT, &raw) != 0)
        return -1;

    *sample = (int16_t)raw;
    return 0;
}

/* ---- TDOA calculation ---- */
static double calc_tdoa(int16_t s1, int16_t s2)
{
    struct timespec ts1, ts2;
    double diff;

    if (clock_gettime(CLOCK_REALTIME, &ts1) != 0) {
        perror("clock_gettime");
        return -1.0;
    }
    if (clock_gettime(CLOCK_REALTIME, &ts2) != 0) {
        perror("clock_gettime");
        return -1.0;
    }

    diff = (double)(ts2.tv_sec  - ts1.tv_sec)
         + (double)(ts2.tv_nsec - ts1.tv_nsec) / 1e9;

    return diff;
}

/* ---- CSV logging ---- */
static int log_data(FILE *fp, double tdoa)
{
    struct timespec ts;
    struct tm tm_info;
    char ts_str[32];

    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return -1;
    }

    localtime_r(&ts.tv_sec, &tm_info);
    strftime(ts_str, sizeof(ts_str), "%Y-%m-%d %H:%M:%S", &tm_info);

    if (fprintf(fp, "%s.%03ld,%d,%d,%.6f\n",
                ts_str, ts.tv_nsec / 1000000,
                0, 1, tdoa) < 0) {
        perror("fprintf");
        return -1;
    }

    if (fflush(fp) != 0) {
        perror("fflush");
        return -1;
    }

    return 0;
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (g_i2c_handles[i] >= 0) {
            i2cClose(g_i2c_handles[i]);
            g_i2c_handles[i] = -1;
        }
    }

    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }

    if (g_pigpio_inited) {
        gpioTerminate();
        g_pigpio_inited = 0;
    }
}

/* ---- Main ---- */
int main(void)
{
    int  rc;
    int  handles[NUM_SENSORS];
    int  filled = 0;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }
    g_pigpio_inited = 1;

    /* Open I2C handles for both sensors */
    for (int i = 0; i < NUM_SENSORS; i++) {
        handles[i] = i2cOpen(I2C_BUS, 0x00 + i, 0);
        if (handles[i] < 0) {
            fprintf(stderr, "Failed to open I2C for sensor %d (rc=%d)\n",
                    i, handles[i]);
            cleanup();
            return EXIT_FAILURE;
        }
    }

    /* Initialize sensors */
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (init_sensor(handles[i]) != 0) {
            fprintf(stderr, "Sensor %d initialization failed\n", i);
            cleanup();
            return EXIT_FAILURE;
        }
    }

    /* Open log file */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("fopen");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "sec,nsec,sensor1,sensor2,tdoa\n");
        fflush(g_log_file);
    }

    /* Register signal handler */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("IMP23ABSU TDOA Logger started. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        int16_t s1 = 0, s2 = 0;
        double  tdoa = 0.0;
        int     ok = 0;

        for (int i = 0; i < NUM_SENSORS && g_running; i++) {
            if (read_sample(handles[i], &s1) != 0) {
                fprintf(stderr, "[Sensor %d] read failed; skipping sample\n", i + 1);
            } else {
                ok = 1;
                break;
            }
        }

        for (int i = 0; i < NUM_SENSORS && g_running; i++) {
            if (read_sample(handles[i], &s2) != 0) {
                fprintf(stderr, "[Sensor %d] read failed; skipping sample\n", i + 1);
            } else {
                ok = 1;
                break;
            }
        }

        if (ok) {
            tdoa = calc_tdoa(s1, s2);
            if (tdoa >= 0.0) {
                if (log_data(g_log_file, tdoa) != 0) {
                    fprintf(stderr, "Logging failed; continuing\n");
                }
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

