#define SPI_FLAGS      0x0003   /* mode 3: CPOL=1, CPHA=1 */
#define GYRO_SENS      0.005f   /* deg/sec/LSB */
#define ACCEL_SENS     0.00025f /* g/LSB */
#define SAMPLE_US      100000   /* 100 ms */
#define STALL_US       40000    /* 40 us stall time */
#define LOG_FILE       "imu_data.csv"

static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static FILE *g_log_file  = NULL;

static void cleanup(void)
{
    if (g_log_file) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int spi_read_register(uint8_t reg, int16_t *out)
{
    if (!out) return -1;

    /* ADIS16488A: send 16-bit command word where MSB = 0 */
    uint16_t cmd = 0x0000 | (reg << 8);
    char tx[2] = { (char)(cmd >> 8), (char)(cmd & 0xFF) };
    char rx[2] = { 0, 0 };

    if (spiXfer(g_spi_handle, tx, rx, 2) < 0) {
        fprintf(stderr, "spiXfer (cmd 0x%04X) failed: %s\n",
                cmd, strerror(errno));
        return -1;
    }

    gpioDelay(STALL_US);

    /* Read 16-bit data word from the same register */
    tx[0] = 0x00;
    tx[1] = 0x00;
    if (spiXfer(g_spi_handle, tx, rx, 2) < 0) {
        fprintf(stderr, "spiXfer (data 0x%04X) failed: %s\n",
                cmd, strerror(errno));
        return -1;
    }

    *out = (int16_t)(((uint16_t)rx[0] << 8) | (uint8_t)rx[1]);
    return 0;
}

static int read_imu_data(float *gyro_x, float *gyro_y, float *gyro_z,
                         float *accel_x, float *accel_y, float *accel_z)
{
    int16_t raw_g, raw_a;

    if (spi_read_register(0x04, &raw_g) < 0) return -1;
    if (spi_read_register(0x06, &raw_a) < 0) return -1;

    *gyro_x = (float)raw_g * GYRO_SENS;
    *gyro_y = (float)raw_g * GYRO_SENS * cosf(M_PI / 180.0f);
    *gyro_z = (float)raw_g * GYRO_SENS * sinf(M_PI / 180.0f);
    *accel_x = (float)raw_a * ACCEL_SENS;
    *accel_y = (float)raw_a * ACCEL_SENS * cosf(M_PI / 180.0f);
    *accel_z = (float)raw_a * ACCEL_SENS * sinf(M_PI / 180.0f);

    return 0;
}

