#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

/* ADIS16448 Register Addresses */
#define ADIS16448_REG_GYRO_XOUT_H  0x04
#define ADIS16448_REG_GYRO_YOUT_H  0x06
#define ADIS16448_REG_GYRO_ZOUT_H  0x08
#define ADIS16448_REG_ACCEL_XOUT_H 0x0A
#define ADIS16448_REG_ACCEL_YOUT_H 0x0C
#define ADIS16448_REG_ACCEL_ZOUT_H 0x0E

/* SPI Configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_MODE    0        /* SPI Mode 0 (CPOL=0, CPHA=0) */

/* Scaling factors (from ADIS16448 datasheet) */
#define GYRO_SCALE  0.05f   /* degrees/sec per LSB */
#define ACCEL_SCALE 0.00025f /* g per LSB */

/* Stall time required between the two 16-bit transfers (>= 40 us) */
#define STALL_US  50

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* Signal handler for Ctrl+C */
static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/*
 * ADIS16448 two-cycle read protocol:
 *   1. Send 16-bit register address with R/W bit (bit 15) set.
 *   2. After >= 40 us stall, send dummy 16-bit value to clock out data.
 *   3. Read 16-bit data from the bus.
 */
static int read_adis16448_register(uint8_t reg_addr, int16_t *out) {
    char tx_buf[2];
    char rx_buf[2];
    int  ret;

    /* Phase 1: send read command */
    tx_buf[0] = (char)(reg_addr | 0x80);  /* bit 7 = 1 for read */
    tx_buf[1] = 0x00;

    ret = spiXfer(g_spi_handle, tx_buf, rx_buf, 2);
    if (ret != 2) {
        fprintf(stderr, "SPI read command failed (reg 0x%02X): ret=%d\n", reg_addr, ret);
        return -1;
    }

    /* Stall to allow the sensor to prepare the data */
    gpioDelay(STALL_US);

    /* Phase 2: send dummy value to clock out data */
    tx_buf[0] = 0x00;
    tx_buf[1] = 0x00;

    ret = spiXfer(g_spi_handle, tx_buf, rx_buf, 2);
    if (ret != 2) {
        fprintf(stderr, "SPI dummy transfer failed (reg 0x%02X): ret=%d\n", reg_addr, ret);
        return -1;
    }

    /* Phase 3: read the 16-bit data */
    tx_buf[0] = 0x00;
    tx_buf[1] = 0x00;

    ret = spiXfer(g_spi_handle, tx_buf, rx_buf, 2);
    if (ret != 2) {
        fprintf(stderr, "SPI data read failed (reg 0x%02X): ret=%d\n", reg_addr, ret);
        return -1;
    }

    *out = (int16_t)(((uint16_t)(uint8_t)rx_buf[0] << 8) | (uint8_t)rx_buf[1]);
    return 0;
}

int main(void) {
    int16_t gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;
    float gyro_x_f, gyro_y_f, gyro_z_f, accel_x_f, accel_y_f, accel_z_f;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI channel 0 at 1 MHz, Mode 0 */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (g_spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set up signal handler for Ctrl+C */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("ADIS16448 IMU reader started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        if (read_adis16448_register(
                ADIS16448_REG_GYRO_XOUT_H,
                &gyro_x) != 0) {
            fprintf(stderr, "Error reading gyro data\n");
            break;
        }
        if (read_adis16448_register(
                ADIS16448_REG_GYRO_YOUT_H,
                &gyro_y) != 0) {
            fprintf(stderr, "Error reading gyro data\n");
            break;
        }
        if (read_adis16448_register(
                ADIS16448_REG_GYRO_ZOUT_H,
                &gyro_z) != 0) {
            fprintf(stderr, "Error reading gyro data\n");
            break;
        }
        if (read_adis16448_register(
                ADIS16448_REG_ACCEL_XOUT_H,
                &accel_x) != 0) {
            fprintf(stderr, "Error reading accel data\n");
            break;
        }
        if (read_adis16448_register(
                ADIS16448_REG_ACCEL_YOUT_H,
                &accel_y) != 0) {
            fprintf(stderr, "Error reading accel data\n");
            break;
        }
        if (read_adis16448_register(
                ADIS16448_REG_ACCEL_ZOUT_H,
                &accel_z) != 0) {
            fprintf(stderr, "Error reading accel data\n");
            break;
        }

        /* Convert raw values to physical units */
        gyro_x_f = (float)gyro_x * GYRO_SCALE;
        gyro_y_f = (float)gyro_y * GYRO_SCALE;
        gyro_z_f = (float)gyro_z * GYRO_SCALE;
        accel_x_f = (float)accel_x * ACCEL_SCALE;
        accel_y_f = (float)accel_y * ACCEL_SCALE;
        accel_z_f = (float)accel_z * ACCEL_SCALE;

        /* Print the data */
        printf("Gyro: X = %7.2f, Y = %7.2f, Z = %7.2f deg/s | Accel: X = %7.2f, Y = %7.2f, Z = %7.2f g\n",
               gyro_x_f, gyro_y_f, gyro_z_f, accel_x_f, accel_y_f, accel_z_f);

        /* Delay 100 ms */
        gpioDelay(100000);
    }

    /* Clean up */
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
    }
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

