/*
 * MPU-6886 6-axis IMU reader for Raspberry Pi 4 Model B
 * Bus: I2C-1 (GPIO2=SDA, GPIO3=SCL), address 0x68
 * Reads accel (±2g) and gyro (±250°/s) every 50 ms.
 *
 * Build:  gcc -O2 -Wall -o mpu6886 mpu6886.c -lm
 * Run:    ./mpu6886   (Ctrl-C to exit)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MPU6886_ADDR   0x68
#define REG_SMPLRT_DIV 0x19
#define REG_PWR_MGMT_1 0x6B
#define REG_ACCEL_XOUT_H 0x3B
