        close(g_fd);
        return EXIT_FAILURE;
    }

    printf("MPU-6886 initialized. Sampling every 50 ms. Press Ctrl-C to exit.\n");

    struct timespec sleep_ts = { 0, SAMPLE_PERIOD_US * 1000 };
    struct timespec rem;

    while (g_running) {
        int16_t ax, ay, az, gx, gy, gz;
        if (read_accel_gyro(g_fd, &ax, &ay, &az, &gx, &gy, &gz) == 0) {
            printf("Accel: X=%6d Y=%6d Z=%6d  |  Gyro: X=%6d Y=%6d Z=%6d\n",
                   ax, ay, az, gx, gy, gz);
        } else {
            fprintf(stderr, "Read failed after %d retries; continuing.\n", MAX_RETRIES);
        }
        nanosleep(&sleep_ts, &rem);
    }

    printf("\nExiting...\n");
    if (g_fd >= 0)
        close(g_fd);
    return EXIT_SUCCESS;
}

