#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <unistd.h>
#include <pigpio.h>

/* ADXL345 I2C address (AD0 tied to GND) */
#define ADXL345_ADDRESS 0x2D

/* ADXL345 registers */
#define ADXL345_DEVID       0x00
#define ADXL345_POWER_CTL   0x2D
#define ADXL345_DATA_FORMAT 0x31
#define ADXL345_DATAX0      0x32

/* Expected device ID */
#define ADXL345_DEVID_VALUE 0xE5

/* GPIO pin for LED (BCM numbering) */
#define LED_PIN 17

/* Impact threshold (2.5 g in full-resolution mode) */
#define IMPACT_THRESHOLD_G 2.5

/* Sampling interval (microseconds) */
#define SAMPLE_INTERVAL_US 10000

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_read_reg8(int handle, uint8_t reg, uint8_t *val)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read error at reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int i2c_write_reg8(int handle, uint8_t reg, uint8_t val)
{
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write error at reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* ADXL345 initialization                                              */
/* ------------------------------------------------------------------ */
static int adxl345_init(int handle)
{
    uint8_t devid = 0;

    /* Verify device identity */
    if (i2c_read_reg8(handle, ADXL345_DEVID, &devid) != 0) {
        fprintf(stderr, "Cannot read DEVID register — sensor absent or bus error.\n");
        return -1;
    }
    if (devid != ADXL345_DEVID_VALUE) {
        fprintf(stderr, "Unexpected DEVID: 0x%02X (expected 0x%02X).\n",
                devid, ADXL345_DEVID_VALUE);
        return -1;
    }

    /* Standby mode: clear measure bit so subsequent config writes take effect */
    if (i2c_write_reg8(handle, ADXL345_POWER_CTL, 0x00) != 0)
        return -1;

    /* Full-resolution mode, ±2 g range, left-justified off */
    if (i2c_write_reg8(handle, ADXL345_DATA_FORMAT, 0x0B) != 0)
        return -1;

    /* Enable measurement mode */
    if (i2c_write_reg8(handle, ADXL345_POWER_CTL, 0x08) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read 6 bytes of acceleration data (DATAX0..DATAZ1)                  */
/* ------------------------------------------------------------------ */
static int adxl345_read_acceleration(int handle, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t buf[6];

    int rc = i2cReadI2CBlockData(handle, ADXL345_DATAX0, (char *)buf, 6);
    if (rc != 6) {
        fprintf(stderr, "I2C block read error: rc=%d\n", rc);
        return -1;
    }

    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Compute magnitude in g                                          */
/* ------------------------------------------------------------------ */
static double calculate_magnitude_g(int16_t x, int16_t y, int16_t z)
{
    double xg = (double)x / 256.0;
    double yg = (double)y / 256.0;
    double zg = (double)z / 256.0;
    return sqrt(xg * xg + yg * yg + zg * zg) * 9.81;
}

/* ------------------------------------------------------------------ */
/* Log impact event                                                    */
/* ------------------------------------------------------------------ */
static void log_impact(FILE *fp, double magnitude, int16_t x, int16_t y, int16_t z)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Magnitude: %.2f g, X: %d, Y: %d, Z: %d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            magnitude, x, y, z);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int16_t x = 0, y = 0, z = 0;
    double magnitude = 0.0;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_file = fopen("impact_log.txt", "a");
    if (g_log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure LED pin */
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    /* Open I2C bus 1 at ADXL345 address */
    g_i2c_handle = i2cOpen(1, ADXL345_ADDRESS, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at address 0x%02X: %d\n",
                ADXL345_ADDRESS, g_i2c_handle);
        fclose(g_log_file);
        g_log_file = NULL;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (adxl345_init(g_i2c_handle) != 0) {
        fprintf(stderr, "ADXL345 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ADXL345 monitoring started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        if (adxl345_read_acceleration(g_i2c_handle, &x, &y, &z) == 0) {
            magnitude = calculate_magnitude_g(x, y, z);

            if (magnitude > IMPACT_THRESHOLD_G) {
                gpioWrite(LED_PIN, 1);
                gpioDelay(500000); /* 500 ms in microseconds */
                gpioWrite(LED_PIN, 0);

                log_impact(g_log_file, magnitude, x, y, z);
                printf("Impact detected: magnitude = %.2f g\n", magnitude);
            }
        } else {
            fprintf(stderr, "Sensor read error — continuing.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

