    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Magnitude: %.2f g, X: %d, Y: %d, Z: %d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            magnitude, x, y, z);
    fflush(fp);
