    if (adxl345_init(g_i2c_handle) != 0) {
        fprintf(stderr, "ADXL345 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ADXL345 monitoring started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        if (adxl345_read_acceleration(g_i2c_handle, &x, &y, &z) == 0) {
            magnitude = calculate_magnitude_g(x, y, z);

            if (magnitude > IMPACT_THRESHOLD_G) {
