/* ------------------------------------------------------------------ */
static int init_icm20602(void)
{
    int status;

    /* Verify device identity */
    status = i2cReadByteData(g_i2c_handle, WHO_AM_I);
    if (status < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %s\n",
                strerror(errno));
        return -1;
    }
    if (status != WHO_AM_I_VAL) {
