#define ACCEL_THRESHOLD 2.0          /* g */
#define ACCEL_SCALE    1024.0        /* counts per g for ±2 g range */
#define POLL_DELAY_US  100000        /* 100 ms */
#define LED_ON_US      500000        /* 500 ms */
#define ID_REG         0x0C          /* Identification register */
#define EXPECTED_ID    0x03          /* Expected device ID for MMA8451Q */

/* ---- Globals for cleanup ---- */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* ---- Read a single byte register ---- */
static int read_register(uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read error (reg 0x%02X): %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

/* ---- Write a single byte register ---- */
static int write_register(uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write error (reg 0x%02X, val 0x%02X): %d\n",
                reg, value, rc);
        return -1;
    }
    return 0;
}

/* ---- Initialize I2C and verify device identity ---- */
static int init_i2c(void)
{
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, i2c_handle);
        return -1;
    }

    uint8_t id = 0;
    if (read_register(ID_REG, &id) != 0) {
        fprintf(stderr, "Failed to read identification register\n");
        return -1;
    }

    if (id != EXPECTED_ID) {
        fprintf(stderr, "Unexpected device ID: 0x%02X (expected 0x%02X)\n",
                id, EXPECTED_ID);
        return -1;
    }

    printf("MMA8451Q detected (ID reg = 0x%02X)\n", id);
    return 0;
}

/* ---- Read acceleration (counts) ---- */
static int read_acceleration(int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t buf[6];
    int rc = i2cReadI2CBlockData(i2c_handle, 0x01, (char *)buf, 6);
    if (rc != 6) {
        fprintf(stderr, "Failed to read acceleration block: %d\n", rc);
        return -1;
    }

    /* MMA8451Q: 14-bit left-justified, two's complement */
    *x = (int16_t)((buf[1] << 8) | buf[0]) >> 2;
    *y = (int16_t)((buf[3] << 8) | buf[2]) >> 2;
    *z = (int16_t)((buf[5] << 8) | buf[4]) >> 2;
    return 0;
}

/* ---- Log a reading ---- */
static void log_impact(int16_t x, int16_t y, int16_t z)
{
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, X: %d, Y: %d, Z: %d\n", ts, x, y, z);
    fflush(log_file);
}

/* ---- Main ---- */
int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", LED_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open impact_log.txt");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Monitoring acceleration (threshold: %.1f g)... Press Ctrl+C to exit.\n",
           ACCEL_THRESHOLD);

    while (!terminate) {
        int16_t x, y, z;

        if (read_acceleration(&x, &y, &z) == 0) {
            float x_g = (float)x / ACCEL_SCALE;
            float y_g = (float)y / ACCEL_SCALE;
            float z_g = (float)z / ACCEL_SCALE;

            if (x_g > ACCEL_THRESHOLD || y_g > ACCEL_THRESHOLD || z_g > ACCEL_THRESHOLD) {
                printf("Impact detected! X: %.2f g, Y: %.2f g, Z: %.2f g\n",
                       x_g, y_g, z_g);
                gpioWrite(LED_PIN, 1);
                log_impact(x, y, z);
                gpioDelay(LED_ON_US);
                gpioWrite(LED_PIN, 0);
            }
        } else {
            fprintf(stderr, "Read error; continuing...\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

