#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define TMAG5273_ADDR 0x19
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "magnetic_field_log.csv"
#define SAMPLE_INTERVAL_SEC 1

/* TMAG5273 register addresses */
#define TMAG5273_X_CH1 0x00
#define TMAG5273_Y_CH2 0x01
#define TMAG5273_Z_CH3 0x02
#define TMAG5273_STATUS 0x03
#define TMAG5273_CONFIG 0x0A

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_sensor(int fd) {
    /* Standby mode to allow configuration changes */
    if (i2c_write_reg8(fd, TMAG5273_CONFIG, 0x00) < 0) return -1;
    /* Enable X, Y, Z axes; default range ±1 Gauss */
    if (i2c_write_reg8(fd, TMAG5273_CONFIG, 0x0F) < 0) return -1;
    /* Set continuous-conversion mode */
    if (i2c_write_reg8(fd, TMAG5273_CONFIG, 0x0D) < 0) return -1;
    /* Clear any pending interrupt */
    if (i2c_write_reg8(fd, TMAG5273_STATUS, 0x01) < 0) return -1;
    return 0;
}

static int read_sensor_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t status;
    if (i2c_read_reg8(fd, TMAG5273_STATUS, &status) < 0) return -1;
    if ((status & 0x03) != 0x03) {
        fprintf(stderr, "Sensor status not ready (0x%02X)\n", status);
        return -1;
    }
    uint8_t x_raw, y_raw, z_raw;
    if (i2c_read_reg8(fd, TMAG5273_X_CH1, &x_raw) < 0) return -1;
    if (i2c_read_reg8(fd, TMAG5273_Y_CH2, &y_raw) < 0) return -1;
    if (i2c_read_reg8(fd, TMAG5273_Z_CH3, &z_raw) < 0) return -1;
    *x = (int16_t)((x_raw << 8) | z_raw);
    *y = (int16_t)((y_raw << 8) | (status & 0x01));
    *z = (int16_t)((status >> 2) | ((status >> 1) & 0x03));
    return 0;
}

static int log_data(FILE *fp, int16_t x, int16_t y, int16_t z) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    if (fprintf(fp, "%s,%d,%d,%d\n", ts, x, y, z) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, TMAG5273_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", TMAG5273_ADDR, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    /* Probe sensor presence by reading the status register */
    uint8_t probe;
    if (i2c_read_reg8(g_i2c_fd, TMAG5273_STATUS, &probe) < 0) {
        fprintf(stderr, "Sensor not responding at address 0x%02X\n", TMAG5273_ADDR);
        close(g_i2c_fd);
        return 1;
    }

    if (init_sensor(g_i2c_fd) < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        close(g_i2c_fd);
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    /* Write header if file is empty */
    if (ftell(g_log_fp) == 0) {
        if (fprintf(g_log_fp, "timestamp,x,y,z\n") < 0) {
            fprintf(stderr, "Failed to write header: %s\n", strerror(errno));
            fclose(g_log_fp);
            close(g_i2c_fd);
            return 1;
        }
        fflush(g_log_fp);
    }

    printf("Logging magnetic field data to %s. Press Ctrl+C to stop.\n", LOG_FILE);

    while (g_running) {
        int16_t x, y, z;
        if (read_sensor_data(g_i2c_fd, &x, &y, &z) == 0) {
            if (log_data(g_log_fp, x, y, z) < 0) {
                fprintf(stderr, "Logging failed, continuing...\n");
            }
        } else {
            fprintf(stderr, "Sensor read failed, continuing...\n");
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down cleanly...\n");
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return 0;
}

