/*
 * ADXL345 Free-Fall Logger for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   ADXL345 SDA -> GPIO2 (physical pin 3, I2C bus 1)
 *   ADXL345 SCL -> GPIO3 (physical pin 5, I2C bus 1)
 *   ADXL345 INT1 -> GPIO17 (physical pin 11, BCM 17)
 *   ADXL345 VDD -> 3.3 V
 *   ADXL345 GND -> GND
 *
 * Build: gcc -O2 -Wall -o freefall freefall.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <gpiod.h>

/* ---- ADXL345 register definitions ---- */
#define ADXL345_ADDRESS        0x2D
#define ADXL345_DEVID          0x00
#define ADXL345_POWER_CTL      0x2D
#define ADXL345_DATA_FORMAT    0x31
#define ADXL345_DATAX0         0x32
#define ADXL345_INT_ENABLE     0x2E
#define ADXL345_INT_MAP        0x2F
#define ADXL345_INT_SOURCE     0x30

#define ADXL345_DEVID_VALUE    0xE5

/* ---- Configuration ---- */
#define I2C_BUS                "/dev/i2c-1"
#define GPIO_CHIP              "gpiochip4"   /* BCM GPIO on Pi 4 */
#define GPIO_LINE              17            /* BCM 17 */
#define LOG_FILE              "freefall_log.csv"
#define SAMPLE_PERIOD_US      10000         /* 10 ms */
#define FREEFALL_THRESHOLD     0.5f          /* g */

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;
static struct gpiod_chip  *g_chip = NULL;
static struct gpiod_line  *g_line = NULL;

/* ---- Signal handler ---- */
static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ---- */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- ADXL345 helpers ---- */
static int adxl345_init(int fd)
{
    uint8_t devid = 0;

    if (i2c_read_reg8(fd, ADXL345_DEVID, &devid) != 0)
        return -1;

    if (devid != ADXL345_DEVID_VALUE) {
        fprintf(stderr, "ADXL345 not detected (DEVID=0x%02X, expected 0x%02X)\n",
                devid, ADXL345_DEVID_VALUE);
        return -1;
    }

    /* Standby: clear measure bit, clear power-enable bit */
    if (i2c_write_reg8(fd, ADXL345_POWER_CTL, 0x00) != 0)
        return -1;

    /* Continuous mode, +/-2 g, left-justify */
    if (i2c_write_reg8(fd, ADXL345_DATA_FORMAT, 0x0B) != 0)
        return -1;

    /* Clear all interrupt maps */
    if (i2c_write_reg8(fd, ADXL345_INT_MAP, 0x00) != 0)
        return -1;

    /* Clear all interrupt sources */
    if (i2c_write_reg8(fd, ADXL345_INT_SOURCE, 0x00) != 0)
        return -1;

    /* Enable all interrupts */
    if (i2c_write_reg8(fd, ADXL345_INT_ENABLE, 0x0F) != 0)
        return -1;

    return 0;
}

static int adxl345_read_xyz(int fd, float *x, float *y, float *z)
{
    uint8_t buf[6];
    int16_t raw;

    if (write(fd, (uint8_t[]){ ADXL345_DATAX0 }, 1) != 1) {
        fprintf(stderr, "I2C write (reg select DATAX0) failed: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, buf, 6) != 6) {
        fprintf(stderr, "I2C read 6 bytes failed: %s\n", strerror(errno));
        return -1;
    }

    raw = (int16_t)((buf[1] << 8) | buf[0]);
    *x = (float)raw * 0.0039f;

    raw = (int16_t)((buf[3] << 8) | buf[2]);
    *y = (float)raw * 0.0039f;

    raw = (int16_t)((buf[5] << 8) | buf[4]);
    *z = (float)raw * 0.0039f;

    return 0;
}

/* ---- GPIO helpers ---- */
static int gpio_init(void)
{
    g_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!g_chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP, strerror(errno));
        return -1;
    }
    g_line = gpiod_chip_get_line(g_chip, GPIO_LINE);
    if (!g_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(g_chip);
        g_chip = NULL;
        return -1;
    }
    if (gpiod_line_request_falling_edge_events(g_line, "adxl345_freefall") < 0) {
        fprintf(stderr, "Failed to request falling-edge events on GPIO %d: %s\n",
                GPIO_LINE, strerror(errno));
        gpiod_chip_close(g_chip);
        g_chip = NULL;
        g_line = NULL;
        return -1;
    }
    return 0;
}

static void gpio_cleanup(void)
{
    if (g_line) {
        gpiod_line_release(g_line);
        g_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
}

/* ---- Logging ---- */
static int log_open(void)
{
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    /* Write header only if file is empty */
    if (fseek(g_log_fp, 0, SEEK_END) == 0) {
        long sz = ftell(g_log_fp);
        if (sz == 0)
            fprintf(g_log_fp, "Timestamp,X,Y,Z\n");
        rewind(g_log_fp);
    }
    return 0;
}

static void log_sample(float x, float y, float z)
{
    struct timespec ts;
    char tbuf[40];

    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm;
    localtime_r(&ts.tv_sec, &tm);
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(g_log_fp, "%s.%03ld,%.3f,%.3f,%.3f\n",
                tbuf, ts.tv_nsec / 1000000, x, y, z) < 0)
        fprintf(stderr, "Failed to write log entry: %s\n", strerror(errno));
    else
        fflush(g_log_fp);
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_line) {
        gpiod_line_set_event_handler(g_line, NULL);
        gpiod_line_release(g_line);
        g_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        /* Put sensor in standby before closing */
        (void)i2c_write_reg8(g_i2c_fd, ADXL345_POWER_CTL, 0x00);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ---- Main ---- */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install signal handlers: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Set slave address */
    if (ioctl(g_i2c_fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                ADXL345_ADDRESS, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (adxl345_init(g_i2c_fd) != 0) {
        fprintf(stderr, "ADXL345 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize GPIO */
    if (gpio_init() != 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    if (log_open() != 0) {
        fprintf(stderr, "Log file initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Free-fall detection started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        /* Block up to 100 ms waiting for an event */
        int rc = gpiod_line_event_wait(g_line, &(struct timespec){0, 100000000});
        if (rc < 0) {
            if (errno == EINTR)
                continue;
            fprintf(stderr, "GPIO event wait error: %s\n", strerror(errno));
            break;
        }
        if (rc == 0)
            continue;  /* timeout, loop and check g_running */

        /* Read the event to clear it */
        struct gpiod_line_event ev;
        if (gpiod_line_event_read(g_line, &ev) < 0) {
            fprintf(stderr, "Failed to read GPIO event: %s\n", strerror(errno));
            continue;
        }

        /* Only act on falling-edge (free-fall) */
        if (ev.event_type != GPIOD_LINE_EVENT_FALLING_EDGE)
            continue;

        float x, y, z;
        if (adxl345_read_xyz(g_i2c_fd, &x, &y, &z) != 0) {
            fprintf(stderr, "Sensor read error during free-fall\n");
            continue;
        }

        if (x < FREEFALL_THRESHOLD && y < FREEFALL_THRESHOLD && z < FREEFALL_THRESHOLD) {
            log_sample(x, y, z);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

