/*
 * LSM6DSR IMU reader for Raspberry Pi 3 Model B+
 * I2C bus 1: SDA=GPIO2, SCL=GPIO3
 * Output data rate: 104 Hz
 * Fall detection: IDLE -> FREEFALL (< 0.2 g) -> IMPACT (> 2.5 g within 1 s)
 * Build: gcc -O2 -Wall -o imu_fall imu_fall.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- LSM6DSR register definitions ---- */
#define LSM6DSR_WHO_AM_I   0x0F
#define LSM6DSR_WHO_AM_I_VAL 0x6A
#define LSM6DSR_CTRL1_XL   0x10
#define LSM6DSR_CTRL2_G    0x11
#define LSM6DSR_OUTX_L_G   0x22
#define LSM6DSR_OUTX_L_XL  0x28

/* ---- Configuration ---- */
#define I2C_BUS            "/dev/i2c-1"
#define LOG_FILE           "motion_log.txt"
#define SAMPLE_PERIOD_US   10000   /* 10 ms → 100 Hz internal → 104 Hz output */
#define FREEFALL_THRESHOLD 0.2f    /* g */
#define IMPACT_THRESHOLD   2.5f    /* g */
#define IMPACT_WINDOW_S    1.0     /* seconds */
#define ACCEL_RANGE        2.0f    /* ±2 g */
#define GYRO_RANGE         250.0f  /* ±250 dps */
#define WHO_AM_I_TIMEOUT   100     /* ms */

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ---- Signal handler ---- */
static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Millisecond sleep ---- */
static void sleep_ms(unsigned ms)
{
    struct timespec ts = { ms / 1000, (long)(ms % 1000) * 1000000L };
    nanosleep(&ts, NULL);
}

/* ---- I2C helpers ---- */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (burst reg 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C burst read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- Sensor init ---- */
static int init_lsm6dsr(int fd)
{
    uint8_t who;
    if (i2c_read_reg8(fd, LSM6DSR_WHO_AM_I, &who) < 0)
        return -1;
    if (who != LSM6DSR_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, LSM6DSR_WHO_AM_I_VAL);
        return -1;
    }

    /* Gyro: ODR=104 Hz (0x60), FS=±250 dps (0x00) → 0x60 */
    if (i2c_write_reg8(fd, LSM6DSR_CTRL2_G, 0x60) < 0)
        return -1;

    /* Accel: ODR=104 Hz (0x60), FS=±2 g (0x00) → 0x60 */
    if (i2c_write_reg8(fd, LSM6DSR_CTRL1_XL, 0x60) < 0)
        return -1;

    return 0;
}

/* ---- Read 6 bytes: accel X/Y/Z, gyro X/Y/Z ---- */
static int read_sensor(int fd, float *ax, float *ay, float *az,
                       float *gx, float *gy, float *gz)
{
    uint8_t buf[6];
    if (i2c_read_burst(fd, LSM6DSR_OUTX_L_XL, buf, 6) < 0)
        return -1;

    int16_t rx = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t ry = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t rz = (int16_t)((buf[5] << 8) | buf[4]);
    int16_t gx = (int16_t)((buf[6] << 8) | buf[7]);
    int16_t gy = (int16_t)((buf[8] << 8) | buf[9]);
    int16_t gz = (int16_t)((buf[10] << 8) | buf[11]);

    *ax = (float)rx / ACCEL_RANGE * 9.81f;
    *ay = (float)ry / ACCEL_RANGE * 9.81f;
    *az = (float)rz / ACCEL_RANGE * 9.81f;
    *gx = (float)gx / GYRO_RANGE * 1000.0f;
    *gy = (float)gy / GYRO_RANGE * 1000.0f;
    *gz = (float)gz / GYRO_RANGE * 1000.0f;
    return 0;
}

/* ---- Timestamp ---- */
static void get_timestamp(char *ts, size_t len)
{
    time_t t = time(NULL);
    struct tm tmv;
    localtime_r(&t, &tmv);
    strftime(ts, len, "%Y-%m-%d %H:%M:%S", &tmv);
}

/* ---- Logging ---- */
static void log_data(FILE *fp, float ax, float ay, float az,
                      float gx, float gy, float gz, const char *status)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));
    fprintf(fp, "%s,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f,%s\n",
            ts, ax, ay, az, gx, gy, gz, status);
    fflush(fp);
}

/* ---- Fall detection state machine ---- */
static void detect_fall(float ax, float ay, float az)
{
    static float prev_ax = 0.0f;
    static float prev_gx = 0.0f;
    static time_t last_impact = 0;
    static bool in_freefall = false;
    static bool in_impact = false;

    bool freefall = (fabsf(ax) < FREEFALL_THRESHOLD);

    if (freefall && !in_freefall) {
        in_freefall = true;
        if (in_impact) {
            time_t now = time(NULL);
            if (difftime(now, last_impact) >= IMPACT_WINDOW_S)
                in_impact = true;
        }
    } else if (!freefall && in_freefall) {
        in_freefall = false;
    } else if (freefall && in_freefall && in_impact) {
        in_impact = false;
    }

    if (in_impact) {
        char msg[128];
        snprintf(msg, sizeof(msg), "IMPACT: ax=%.3f ay=%.3f az=%.3f",
                 ax, ay, az);
        fprintf(stderr, "%s\n", msg);
    }
    prev_ax = ax;
    prev_gx = gx;
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ---- Main ---- */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, 0x19) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x19: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    if (init_lsm6dsr(g_i2c_fd) < 0) {
        fprintf(stderr, "LSM6DSR init failed\n");
        cleanup();
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    fprintf(g_log_fp, "# timestamp,ax_g,ay_g,az_g,gx_dps,gy_dps,gz_dps,status\n");
    fflush(g_log_fp);

    printf("LSM6DSR ready. Logging to %s. Ctrl+C to stop.\n", LOG_FILE);

    while (g_running) {
        float ax, ay, az, gx, gy, gz;
        if (read_sensor(g_i2c_fd, &ax, &ay, &az, &gx, &gy, &gz) < 0) {
            fprintf(stderr, "Sensor read error; retrying...\n");
            sleep_ms(100);
            continue;
        }

        detect_fall(ax, ay, az);
        log_data(g_log_fp, ax, ay, az, gx, gy, gz,
                 in_freefall ? "FREEFALL" : "IDLE",
                 in_impact ? "IMPACT" : "IDLE");

        sleep_ms(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly.\n");
    cleanup();
    return 0;
}

