/*
 * ADIS16266 Gyroscope SPI reader for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   ADIS16266 CS  -> GPIO8  (BCM 8, SPI CE0)
 *   ADIS16266 SDO -> GPIO9  (BCM 9, SPI MISO)
 *   ADIS16266 SDA -> GPIO10 (BCM 10, SPI MOSI)
 *   ADIS16266 SCL -> GPIO11 (BCM 11, SPI SCLK)
 *   ADIS16266 VDD -> 3.3 V
 *   ADIS16266 GND -> GND
 *
 * SPI: channel 0, CE0, mode 3 (CPOL=1, CPHA=1), 1 MHz, 8-bit words.
 * Scale factor: 0.0305 deg/sec/LSB (16-bit register, 2-byte transfer).
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U
#define SPI_MODE        SPI_MODE_3
#define SPI_BITS        8
#define SAMPLE_PERIOD_US 10000U   /* 10 ms */
#define SCALE_FACTOR    0.0305f   /* deg/sec/LSB */

#define WHO_AM_I_REG    0x00
#define WHO_AM_I_VAL    0x00

#define LOG_FILE        "gyro_log.csv"

static volatile sig_atomic_t g_running = 1;
static int  g_spi_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static void install_signal(int signo, void (*handler)(int))
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(signo, &sa, NULL) != 0)
        perror("sigaction");
}

/* ------------------------------------------------------------------ */
/* SPI helpers                                                         */
/* ------------------------------------------------------------------ */

/*
 * ADIS16266 SPI protocol:
 *   1. Write 2-byte register address (MSB first, bit7 = R/W).
 *   2. Read 2-byte response (MSB first).
 *   3. Response[0] is the status byte; data is in response[1].
 */
static int spi_xfer(int fd, const uint8_t *tx, uint8_t *rx, size_t len)
{
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = len;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read a 16-bit register from the ADIS16266.
 * Returns 0 on success and stores the value in *out; -1 on error.
 */
static int adis_read_reg16(int fd, uint8_t reg, int16_t *out)
{
    uint8_t tx[2] = { (uint8_t)(reg | 0x80), 0x00 };
    uint8_t rx[2] = { 0, 0 };

    if (spi_xfer(fd, tx, rx, sizeof(tx)) != 0)
        return -1;

    *out = (int16_t)((rx[0] << 8) | rx[1]);
    return 0;
}

/*
 * Write a 16-bit value to a register on the ADIS16266.
 * Returns 0 on success; -1 on error.
 */
static int adis_write_reg16(int fd, uint8_t reg, int16_t val)
{
    uint8_t tx[2] = { (uint8_t)(reg & 0x7F), (uint8_t)(val & 0xFF) };
    uint8_t rx[2] = { 0, 0 };

    if (spi_xfer(fd, tx, rx, sizeof(tx)) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_sample(FILE *fp, float rate)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    fprintf(fp, "%s,%.4f\n", ts, rate);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int16_t rate_raw;
    float rate_deg_s;

    /* ---- Signal handling ---- */
    install_signal(SIGINT, sigint_handler);

    /* ---- Open log file once ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("fopen(" LOG_FILE ")");
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "timestamp,angular_rate_deg_s\n");
        fflush(g_log_fp);
    }

    /* ---- Open SPI device ---- */
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        perror("open(" SPI_DEVICE ")");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Configure SPI ---- */
    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("SPI_IOC_WR_MODE");
        cleanup();
        return EXIT_FAILURE;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("SPI_IOC_WR_BITS_PER_WORD");
        cleanup();
        return EXIT_FAILURE;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("SPI_IOC_WR_MAX_SPEED_HZ");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Verify device identity ---- */
    int16_t who = 0;
    if (adis_read_reg16(g_spi_fd, WHO_AM_I_REG, &who) != 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register.\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%04X, expected 0x%04X\n",
                who, WHO_AM_I_VAL);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ADIS16266 detected (WHO_AM_I=0x%04X). Sampling at 10 ms.\n", who);

    /* ---- Main sampling loop ---- */
    while (g_running) {
        if (adis_read_reg16(g_spi_fd, 0x04, &rate_raw) != 0) {
            fprintf(stderr, "SPI read error; continuing.\n");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        rate_deg_s = (float)rate_raw * SCALE_FACTOR;
        log_sample(g_log_fp, rate_deg_s);

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly.\n");
    cleanup();
    return EXIT_SUCCESS;
}

