/*
 * GY-50 L3G4200D Gyroscope Logger for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   GY-50 VCC  -> Pi 3.3 V (Pin 1)
 *   GY-50 GND  -> Pi GND  (Pin 9)
 *   GY-50 SDA  -> Pi GPIO2 / I2C bus 1 SDA (Pin 3)
 *   GY-50 SCL  -> Pi GPIO3 / I2C bus 1 SCL (Pin 5)
 *
 * Build: gcc -O2 -Wall -o gyro_log gyro_log.c -lm
 * Run:   sudo ./gyro_log
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ---- L3G4200D constants (verified against ST datasheet) ---- */
#define I2C_BUS              1
#define I2C_ADDR             0x19          /* GY-50 SA0 tied to GND */
#define WHO_AM_I             0x0F
#define WHO_AM_I_VAL         0x50
#define CTRL_REG1            0x20
#define CTRL_REG4            0x23
#define OUT_X_L              0x28
#define OUT_X_H              0x29
#define OUT_Y_L              0x2A
#define OUT_Y_H              0x2B
#define OUT_Z_L              0x2C
#define OUT_Z_H              0x2D
#define SENSITIVITY          8.75f         /* mdps/LSB */
#define SAMPLE_PERIOD_US     10000         /* 10 ms */
#define LOG_FILE             "gyro_log.csv"
#define MAX_RETRIES          3

/* ---- Globals for cleanup ---- */
static int  i2c_handle = -1;
static FILE *log_file  = NULL;
static volatile sig_atomic_t terminate = 0;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ---- Millisecond sleep ---- */
static void delay_ms(unsigned int ms)
{
    gpioDelay((unsigned int)(ms * 1000));   /* microseconds */
}

/* ---- Write a byte to a register with retry ---- */
static int write_register(int handle, uint8_t reg, uint8_t value)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2cWriteByteData(handle, reg, value) == 0)
            return 0;
        fprintf(stderr, "I2C write to reg 0x%02X failed (attempt %d/%d): %s\n",
                reg, attempt + 1, MAX_RETRIES, strerror(errno));
        delay_ms(10);
    }
    return -1;
}

/* ---- Read a byte from a register ---- */
static int read_register(int handle, uint8_t reg, uint8_t *out)
{
    int v = i2cReadByteData(handle, reg);
    if (v < 0) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = (uint8_t)v;
    return 0;
}

/* ---- Initialize the L3G4200D ---- */
static int init_gyro(int handle)
{
    uint8_t who;

    /* Verify device identity */
    if (read_register(handle, WHO_AM_I, &who) != 0) {
        fprintf(stderr, "Cannot read WHO_AM_I — sensor absent or bus error.\n");
        return -1;
    }
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X.\n",
                who, WHO_AM_I_VAL);
        return -1;
    }

    /* Standby mode (CTRL_REG1 = 0x00) — safe to configure */
    if (write_register(handle, CTRL_REG1, 0x00) != 0) {
        fprintf(stderr, "Failed to set CTRL_REG1 standby.\n");
        return -1;
    }

    /* DLPF_CFG = 0x00 (default), 8.75 mdps/LSB sensitivity */
    if (write_register(handle, CTRL_REG4, 0x00) != 0) {
        fprintf(stderr, "Failed to set CTRL_REG4.\n");
        return -1;
    }

    return 0;
}

/* ---- Read raw 16-bit angular rate (little-endian) ---- */
static int read_gyro_data(int handle, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t xl, xh, yl, yh, zl, zh;

    if (read_register(handle, OUT_X_L, &xl) != 0) return -1;
    if (read_register(handle, OUT_X_H, &xh) != 0) return -1;
    if (read_register(handle, OUT_Y_L, &yl) != 0) return -1;
    if (read_register(handle, OUT_Y_H, &yh) != 0) return -1;
    if (read_register(handle, OUT_Z_L, &zl) != 0) return -1;
    if (read_register(handle, OUT_Z_H, &zh) != 0) return -1;

    *x = (int16_t)((uint16_t)xh << 8 | xl);
    *y = (int16_t)((uint16_t)yh << 8 | yl);
    *z = (int16_t)((uint16_t)zh << 8 | zl);
    return 0;
}

/* ---- Append a timestamped record to the CSV file ---- */
static int log_data(FILE *fp, const struct timespec *ts,
                    int16_t x, int16_t y, int16_t z)
{
    char ts_str[40];
    struct tm tm_info;

    localtime_r(&ts->tv_sec, &tm_info);
    strftime(ts_str, sizeof(ts_str), "%Y-%m-%d %H:%M:%S", &tm_info);
    size_t len = strlen(ts_str);
    snprintf(ts_str + len, sizeof(ts_str) - len, ".%09ld", ts->tv_nsec);

    if (fprintf(fp, "%s,%d,%d,%d\n", ts_str, x, y, z) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- Cleanup resources ---- */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    struct timespec ts;
    int16_t x, y, z;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize gyroscope */
    if (init_gyro(i2c_handle) != 0) {
        fprintf(stderr, "Gyroscope initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header */
    if (fprintf(log_file, "Timestamp,X,Y,Z\n") < 0) {
        fprintf(stderr, "Cannot write CSV header: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    fflush(log_file);

    /* Register signal handler */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Logging GY-50 data to %s (Ctrl+C to stop)...\n", LOG_FILE);

    /* Main sampling loop */
    while (!terminate) {
        if (read_gyro_data(i2c_handle, &x, &y, &z) == 0) {
            if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
                if (log_data(log_file, &ts, x, y, z) != 0) {
                    fprintf(stderr, "Logging failed; continuing.\n");
                }
            } else {
                fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
            }
        } else {
            fprintf(stderr, "Gyro read failed; continuing.\n");
        }
        delay_ms(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

