/*
 * vibration_monitor.c — Raspberry Pi 5
 *
 * Reads acceleration data from an Omron D7S-0001 vibration sensor
 * over I2C (/dev/i2c-1) and logs timestamped samples to
 * vibration_log.csv every 100 ms.
 *
 * Build:  gcc -O2 -Wall -Wextra -o vibration_monitor vibration_monitor.c
 * Run:    ./vibration_monitor   (Ctrl+C to stop)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define CSV_FILENAME   "vibration_log.csv"
#define SAMPLE_PERIOD_US 100000          /* 100 ms */
#define ERROR_VALUE     (-1000)          /* D7S-0001 error code */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

static int install_signal_handler(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    return sigaction(SIGINT, &sa, NULL);
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_open(const char *bus, const char *name)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, 0) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE): %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

/*
 * Read a 16-bit big-endian register from the D7S-0001.
 * Returns the register value (0–65535) or ERROR_VALUE on failure.
 */
static int d7s_read_reg16(int fd, uint8_t reg)
{
    uint8_t buf[2];

    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg 0x%02X): %s\n", reg, strerror(errno));
        return ERROR_VALUE;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read (reg 0x%02X): %s\n", reg, strerror(errno));
        return ERROR_VALUE;
    }
    return (int)((uint16_t)buf[0] | ((uint16_t)buf[1] << 8));
}

/* ------------------------------------------------------------------ */
/* CSV logging                                                         */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, int x, int y, int z)
{
    char ts[32];
    time_t now = time(NULL);
    struct tm tm_utc;

    if (gmtime_r(&now, &tm_utc) == NULL) {
        fprintf(stderr, "gmtime_r: %s\n", strerror(errno));
        return -1;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        fprintf(stderr, "strftime: buffer too small\n");
        return -1;
    }

    if (fprintf(fp, "%s,%d,%d,%d\n", ts, x, y, z) < 0) {
        fprintf(stderr, "fprintf: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int fd = -1;
    FILE *fp = NULL;
    int rc = EXIT_FAILURE;

    if (install_signal_handler() != 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = i2c_open(I2C_BUS, "d7s-0001");
    if (fd < 0) {
        return EXIT_FAILURE;
    }

    fp = fopen(CSV_FILENAME, "a");
    if (fp == NULL) {
        fprintf(stderr, "fopen(%s): %s\n", CSV_FILENAME, strerror(errno));
        goto cleanup;
    }

    /* Write header only if the file is empty */
    if (fseek(fp, 0, SEEK_END) != 0) {
        fprintf(stderr, "fseek: %s\n", strerror(errno));
        goto cleanup;
    }
    long sz = ftell(fp);
    if (sz == 0) {
        if (fprintf(fp, "Timestamp,X,Y,Z\n") < 0 || fflush(fp) != 0) {
            fprintf(stderr, "Header write: %s\n", strerror(errno));
            goto cleanup;
        }
    }

    printf("Vibration monitoring started. Press Ctrl+C to stop.\n");

    while (g_running) {
        int x = d7s_read_reg16(fd, 0x00);
        int y = d7s_read_reg16(fd, 0x01);
        int z = d7s_read_reg16(fd, 0x02);

        if (x == ERROR_VALUE || y == ERROR_VALUE || z == ERROR_VALUE) {
            fprintf(stderr, "Sensor read error — skipping sample.\n");
        } else {
            if (log_data(fp, x, y, z) != 0) {
                fprintf(stderr, "Logging error — continuing.\n");
            }
        }

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly.\n");
    rc = EXIT_SUCCESS;

cleanup:
    if (fp != NULL) {
        fclose(fp);
    }
    if (fd >= 0) {
        close(fd);
    }
    return rc;
}

