    while (program_running) {
        int s1 = gpioRead(SENSOR_1_PIN);
        int s2 = gpioRead(SENSOR_2_PIN);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "Error reading sensor values: s1=%d, s2=%d\n", s1, s2);
            break;
        }

        if (log_sensor_data(fp, s1, s2) != 0) {
            fprintf(stderr, "Error logging sensor data\n");
            break;
        }

        if (s1 == 1 && s2 == 1) {
            printf("Conveyor HALTED!\n");
            fflush(stdout);
        }

        gpioDelay(POLL_DELAY_US);
    }

    ret = EXIT_SUCCESS;

cleanup_all:
    if (fp != NULL) {
        fclose(fp);
    }
cleanup_gpio:
    gpioTerminate();
    return ret;
}

