#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* MMA8452Q register addresses */
#define MMA8452Q_WHO_AM_I   0x0F
#define MMA8452Q_CTRL_REG1  0x2A
#define MMA8452Q_CTRL_REG2  0x2B
#define MMA8452Q_CTRL_REG3  0x2C
#define MMA8452Q_CTRL_REG4  0x2D
#define MMA8452Q_OUT_X_L    0x01
#define MMA8452Q_OUT_X_H    0x02
#define MMA8452Q_OUT_Y_L    0x03
#define MMA8452Q_OUT_Y_H    0x04
#define MMA8452Q_OUT_Z_L    0x05
#define MMA8452Q_OUT_Z_H    0x06

#define MMA8452Q_WHO_AM_I_VAL 0x1D
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "fall_log.txt"
#define TILT_THRESHOLD 45.0f
#define POLL_DELAY_US 10000  /* 10 ms -> ~100 Hz */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C block read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_mma8452q(int fd)
{
    uint8_t who_am_i = 0;
    if (i2c_read_reg(fd, MMA8452Q_WHO_AM_I, &who_am_i) < 0)
        return -1;
    if (who_am_i != MMA8452Q_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, MMA8452Q_WHO_AM_I_VAL);
        return -1;
    }

    /* Standby mode: clear ACTIVE bit in CTRL_REG1 */
    if (i2c_write_reg(fd, MMA8452Q_CTRL_REG1, 0x00) < 0)
        return -1;

    /* 100 Hz data rate, 12-bit resolution, all axes enabled */
    if (i2c_write_reg(fd, MMA8452Q_CTRL_REG2, 0x20) < 0)
        return -1;

    /* 100 Hz data rate, 12-bit resolution, all axes enabled */
    if (i2c_write_reg(fd, MMA8452Q_CTRL_REG3, 0x00) < 0)
        return -1;

    /* 100 Hz data rate, 12-bit resolution, all axes enabled */
    if (i2c_write_reg(fd, MMA8452Q_CTRL_REG4, 0x00) < 0)
        return -1;

    /* Re-enter active mode */
    if (i2c_write_reg(fd, MMA8452Q_CTRL_REG1, 0x01) < 0)
        return -1;

    return 0;
}

static int read_accel(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t buf[6];
    if (i2c_read_block(fd, MMA8452Q_OUT_X_L, buf, sizeof(buf)) < 0)
        return -1;

    *x = (int16_t)((buf[1] << 8) | buf[0]) >> 4;
    *y = (int16_t)((buf[3] << 8) | buf[2]) >> 4;
    *z = (int16_t)((buf[5] << 8) | buf[4]) >> 4;
    return 0;
}

static float calculate_tilt(int16_t x, int16_t y, int16_t z)
{
    float fx = (float)x;
    float fy = (float)y;
    float fz = (float)z;
    return sqrtf(fx * fx + fy * fy + fz * fz);
}

static void log_data(FILE *fp, int16_t x, int16_t y, int16_t z)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%d,%d,%d\n", ts, x, y, z);
    fflush(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, 0x1D) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x1D: %s\n", strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    if (init_mma8452q(g_i2c_fd) < 0) {
        fprintf(stderr, "MMA8452Q initialization failed\n");
        close(g_i2c_fd);
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    printf("MMA8452Q initialized. Monitoring tilt (threshold %.1f degrees)...\n",
           TILT_THRESHOLD);

    while (g_running) {
        int16_t x, y, z;
        if (read_accel(g_i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Read error; continuing...\n");
            usleep(POLL_DELAY_US);
            continue;
        }

        float tilt = calculate_tilt(x, y, z);
        if (tilt > TILT_THRESHOLD) {
            log_data(g_log_fp, x, y, z);
            printf("Tilt %.2f degrees detected! Logged to %s\n", tilt, LOG_FILE);
        }

        usleep(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return 0;
}

