#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* LIS3MDL I2C address (SA0 tied to GND) */
#define LIS3MDL_ADDR 0x19

/* LIS3MDL register addresses */
#define LIS3MDL_CTRL_REG1 0x20
#define LIS3MDL_CTRL_REG2 0x21
#define LIS3MDL_CTRL_REG3 0x22
#define LIS3MDL_CTRL_REG4 0x23
#define LIS3MDL_OUT_X_L  0x28
#define LIS3MDL_OUT_X_H  0x29
#define LIS3MDL_OUT_Y_L  0x2A
#define LIS3MDL_OUT_Y_H  0x2B
#define LIS3MDL_OUT_Z_L  0x2C
#define LIS3MDL_OUT_Z_H  0x2D

/* ±4 gauss full-scale sensitivity: 0.146 mG per LSB */
#define LIS3MDL_SENSITIVITY_MG_PER_LSB 0.146f

/* Metal detector threshold in milliGauss */
#define METAL_THRESHOLD_MG 800.0f

/* Calibration constants (fixed offsets and scales) */
#define X_OFFSET 0.0f
#define X_SCALE  1.0f
#define Y_OFFSET 0.0f
#define Y_SCALE  1.0f
#define Z_OFFSET 0.0f
#define Z_SCALE  1.0f

#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "magnetic_log.txt"
#define SAMPLE_PERIOD_US 100000  /* 10 Hz */
#define MAX_RETRIES 3

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        return -1;
    }
    return 0;
}

static int init_lis3mdl(int fd)
{
    /* CTRL_REG1: 10 Hz data rate, all axes enabled, normal mode */
    if (i2c_write_reg8(fd, LIS3MDL_CTRL_REG1, 0x70) < 0) {
        return -1;
    }
    /* CTRL_REG2: ±4 gauss full-scale selection */
    if (i2c_write_reg8(fd, LIS3MDL_CTRL_REG2, 0x00) < 0) {
        return -1;
    }
    /* CTRL_REG3: continuous-conversion mode */
    if (i2c_write_reg8(fd, LIS3MDL_CTRL_REG3, 0x00) < 0) {
        return -1;
    }
    /* CTRL_REG4: no high-resolution mode */
    if (i2c_write_reg8(fd, LIS3MDL_CTRL_REG4, 0x00) < 0) {
        return -1;
    }
    return 0;
}

static int read_magnetometer(int fd, float *x, float *y, float *z)
{
    uint8_t xl, xh, yl, yh, zl, zh;

    if (i2c_read_reg8(fd, LIS3MDL_OUT_X_L, &xl) < 0) return -1;
    if (i2c_read_reg8(fd, LIS3MDL_OUT_X_H, &xh) < 0) return -1;
    if (i2c_read_reg8(fd, LIS3MDL_OUT_Y_L, &yl) < 0) return -1;
    if (i2c_read_reg8(fd, LIS3MDL_OUT_Y_H, &yh) < 0) return -1;
    if (i2c_read_reg8(fd, LIS3MDL_OUT_Z_L, &zl) < 0) return -1;
    if (i2c_read_reg8(fd, LIS3MDL_OUT_Z_H, &zh) < 0) return -1;

    int16_t raw_x = (int16_t)((xh << 8) | xl);
    int16_t raw_y = (int16_t)((yh << 8) | yl);
    int16_t raw_z = (int16_t)((zh << 8) | zl);

    *x = (float)raw_x * LIS3MDL_SENSITIVITY_MG_PER_LSB * X_SCALE - X_OFFSET;
    *y = (float)raw_y * LIS3MDL_SENSITIVITY_MG_PER_LSB * Y_SCALE - Y_OFFSET;
    *z = (float)raw_z * LIS3MDL_SENSITIVITY_MG_PER_LSB * Z_SCALE - Z_OFFSET;

    return 0;
}

static void log_data(FILE *fp, float x, float y, float z)
{
    fprintf(fp, "%.3f,%.3f,%.3f\n", x, y, z);
    fflush(fp);
}

static void check_metal_detector(float x, float y, float z)
{
    float magnitude = sqrtf(x * x + y * y + z * z);
    if (magnitude > METAL_THRESHOLD_MG) {
        fprintf(stderr, "Metal detector alert! Magnitude: %.2f mG\n", magnitude);
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open " I2C_BUS);
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, LIS3MDL_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    int init_ok = 0;
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (init_lis3mdl(g_i2c_fd) == 0) {
            init_ok = 1;
            break;
        }
        fprintf(stderr, "Init attempt %d/%d failed.\n", attempt + 1, MAX_RETRIES);
        if (attempt < MAX_RETRIES - 1) {
            usleep(100000);
        }
    }
    if (!init_ok) {
        fprintf(stderr, "LIS3MDL initialization failed after %d attempts.\n", MAX_RETRIES);
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("fopen " LOG_FILE);
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("LIS3MDL initialized. Logging to %s at 10 Hz. Press Ctrl+C to stop.\n", LOG_FILE);

    while (g_running) {
        float x, y, z;
        if (read_magnetometer(g_i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "I2C read error; re-initializing sensor.\n");
            close(g_i2c_fd);
            g_i2c_fd = -1;
            for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
                if (init_lis3mdl(g_i2c_fd) == 0) {
                    printf("Sensor re-initialized successfully.\n");
                    break;
                }
