/*
 * ADXL354B vibration logger for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   ADXL354B CS  -> GPIO8  (BCM 8, SPI CE0)
 *   ADXL354B SDO -> GPIO9  (BCM 9, SPI MISO)
 *   ADXL354B SDA -> GPIO10 (BCM 10, SPI MOSI)
 *   ADXL354B SCL -> GPIO11 (BCM 11, SPI SCLK)
 *   ADXL354B VDD -> 3.3 V
 *   ADXL354B GND -> GND
 *
 * Build: gcc -O2 -Wall -o vib_log vib_log.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <math.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

/* ---- ADXL354B register definitions (from datasheet) ---- */
#define ADXL354_REG_PARTID          0x00
#define ADXL354_REG_REVID           0x01
#define ADXL354_REG_XDATA_H         0x08
#define ADXL354_REG_XDATA_L         0x09
#define ADXL354_REG_YDATA_H         0x0A
#define ADXL354_REG_YDATA_L         0x0B
#define ADXL354_REG_ZDATA_H         0x0C
#define ADXL354_REG_ZDATA_L         0x0D
#define ADXL354_REG_STATUS          0x0B
#define ADXL354_REG_POWER_CTL       0x2D
#define ADXL354_REG_RESET           0x1F

#define ADXL354_RESET_VALUE        0x52
#define ADXL354_POWER_CTL_RUN      0x02
#define ADXL354_POWER_CTL_STAB     0x00
#define ADXL354_STATUS_STABLE      0x80

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U
#define SPI_MODE        SPI_MODE_0
#define SPI_BITS        8
#define LOG_FILE        "vibration_log.txt"
#define SAMPLE_PERIOD_US 100000U   /* 100 ms */
#define MAX_RETRIES     3

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_spi_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* SPI helpers                                                         */
/* ------------------------------------------------------------------ */

static int spi_xfer(int fd, uint8_t *tx, uint8_t *rx, size_t len)
{
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = len;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* ADXL354B register access via SPI                                 */
/* ------------------------------------------------------------------ */

static int adxl354_read_reg(int fd, uint8_t reg, uint8_t *val)
{
    uint8_t tx[2] = { (uint8_t)(reg | 0x80), 0x00 };
    uint8_t rx[2] = { 0, 0 };

    if (spi_xfer(fd, tx, rx, 2) < 0)
        return -1;

    *val = rx[1];
    return 0;
}

static int adxl354_write_reg(int fd, uint8_t reg, uint8_t val)
{
    uint8_t tx[2] = { (uint8_t)(reg & 0x7F), val };
    uint8_t rx[2] = { 0, 0 };

    if (spi_xfer(fd, tx, rx, 2) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor presence check                                               */
/* ------------------------------------------------------------------ */

static int adxl354_verify_partid(int fd)
{
    uint8_t partid = 0;
    if (adxl354_read_reg(fd, ADXL354_REG_PARTID, &partid) < 0) {
        fprintf(stderr, "Failed to read PARTID register.\n");
        return -1;
    }
    if (partid != 0x54) {
        fprintf(stderr, "Unexpected PARTID: 0x%02X (expected 0x54).\n", partid);
        return -1;
    }
    printf("ADXL354B detected (PARTID = 0x%02X).\n", partid);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Reset and configure the ADXL354B                                  */
/* ------------------------------------------------------------------ */

static int adxl354_init(int fd)
{
    /* 1. Software reset */
    if (adxl354_write_reg(fd, ADXL354_REG_RESET, ADXL354_RESET_VALUE) < 0) {
        fprintf(stderr, "Failed to write RESET register.\n");
        return -1;
    }
    usleep(1000);  /* datasheet: wait >= 1 ms after reset */

    /* 2. Clear RUN bit to enter standby */
    if (adxl354_write_reg(fd, ADXL354_REG_POWER_CTL, ADXL354_POWER_CTL_STAB) < 0) {
        fprintf(stderr, "Failed to clear RUN bit.\n");
        return -1;
    }

    /* 3. Wait for STABLE bit to set (device ready) */
    uint8_t status = 0;
    int waited = 0;
    do {
        if (adxl354_read_reg(fd, ADXL354_REG_STATUS, &status) < 0) {
            fprintf(stderr, "Failed to read STATUS register.\n");
            return -1;
        }
        if (status & ADXL354_STATUS_STABLE)
            break;
        usleep(1000);
        waited++;
    } while (waited < 100);  /* up to ~100 ms */

    if (!(status & ADXL354_STATUS_STABLE)) {
        fprintf(stderr, "ADXL354B not ready (STATUS=0x%02X).\n", status);
        return -1;
    }

    /* 4. Set RUN bit to start measurements */
    if (adxl354_write_reg(fd, ADXL354_REG_POWER_CTL, ADXL354_POWER_CTL_RUN) < 0) {
        fprintf(stderr, "Failed to set RUN bit.\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read 20-bit signed acceleration data                                */
/* ------------------------------------------------------------------ */

static int adxl354_read_xyz(int fd, int32_t *x, int32_t *y, int32_t *z)
{
    uint8_t tx[7] = { 0 };
    uint8_t rx[7] = { 0 };

    /* Read three consecutive bytes for each axis (auto-increment) */
    tx[0] = (uint8_t)(ADXL354_REG_XDATA_H | 0xC0);  /* bit7=1 read, bit6=1 multi-byte */
    tx[1] = (uint8_t)(ADXL354_REG_XDATA_H | 0xC0);
    tx[2] = (uint8_t)(ADXL354_REG_XDATA_H | 0xC0);
    tx[3] = (uint8_t)(ADXL354_REG_XDATA_H | 0xC0);
    tx[4] = (uint8_t)(ADXL354_REG_XDATA_H | 0xC0);
    tx[5] = (uint8_t)(ADXL354_REG_XDATA_H | 0xC0);
    tx[6] = (uint8_t)(ADXL354_REG_XDATA_H | 0xC0);

    if (spi_xfer(fd, tx, rx, 7) < 0) {
        fprintf(stderr, "SPI read error for X/Y/Z.\n");
        return -1;
    }

    /* 20-bit left-justified two's complement */
    int32_t raw_x = ((int32_t)rx[0] << 12) | ((int32_t)rx[1] << 4) | ((int32_t)rx[2] >> 4);
    int32_t raw_y = ((int32_t)rx[3] << 12) | ((int32_t)rx[4] << 4) | ((int32_t)rx[5] >> 4);
    int32_t raw_z = ((int32_t)rx[6] << 12) | ((int32_t)rx[7] << 4) | ((int32_t)rx[8] >> 4);

    /* Sign-extend from 20 bits to 32 bits */
    if (raw_x & 0x80000)
        raw_x |= 0xFFF00000;
    if (raw_y & 0x80000)
        raw_y |= 0xFFF00000;
    if (raw_z & 0x80000)
        raw_z |= 0xFFF00000;

    *x = raw_x;
    *y = raw_y;
    *z = raw_z;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */

static int log_open(const char *path)
{
    g_log_fp = fopen(path, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", path, strerror(errno));
        return -1;
    }
    return 0;
}

static void log_data(FILE *fp, int32_t x, int32_t y, int32_t z)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s, X: %d, Y: %d, Z: %d\n", ts, x, y, z);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */

static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open SPI device */
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", SPI_DEVICE, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Configure SPI mode */
    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure SPI bits per word */
    uint8_t bits = SPI_BITS;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure SPI max speed */
    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize ADXL354B */
    if (adxl354_init(g_spi_fd) < 0) {
        fprintf(stderr, "ADXL354B initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Verify sensor presence */
    if (adxl354_verify_partid(g_spi_fd) < 0) {
        fprintf(stderr, "ADXL354B not detected or SPI communication error.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    if (log_open(LOG_FILE) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Logging ADXL354B data to %s (Ctrl+C to stop)...\n", LOG_FILE);

    /* Main sampling loop */
    while (g_running) {
        int32_t x, y, z;
        if (adxl354_read_xyz(g_spi_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "SPI read error, retrying...\n");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        log_data(g_log_fp, x, y, z);
        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

