#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

/* ADIS16362 SPI Configuration */
#define SPI_CHANNEL 0
#define SPI_BAUD    1000000  /* 1 MHz */
#define SPI_FLAGS   0x0003   /* Mode 3: CPOL=1, CPHA=1, active-high, 8-bit */

/* ADIS16362 Register Addresses */
#define ADIS16362_REG_GYRO_XOUT_H  0x04
#define ADIS16362_REG_GYRO_YOUT_H  0x06
#define ADIS16362_REG_GYRO_ZOUT_H  0x08
#define ADIS16362_REG_ACC_XOUT_H   0x0A
#define ADIS16362_REG_ACC_YOUT_H   0x0C
#define ADIS16362_REG_ACC_ZOUT_H   0x0E

/* Scaling factors (from ADIS16362 datasheet) */
#define GYRO_SCALE  0.05f   /* degrees/sec per LSB */
#define ACCEL_SCALE 0.0025f /* g per LSB */

/* Global resources for signal handler cleanup */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Read a 16-bit register from the ADIS16362 via SPI.
 * The ADIS16362 SPI read protocol requires sending the address byte
 * with the MSB set (0x80 | reg) and then sending a dummy byte to clock
 * out the 16-bit data.  The data is returned on the *next* transfer.
 */
static int read_register(uint8_t reg, int16_t *out) {
    char tx[2], rx[2];
    int  ret;

    /* Phase 1: send address with MSB set */
    tx[0] = (char)(0x80 | reg);
    tx[1] = 0x00;
    ret = spiXfer(spi_handle, tx, rx, 2);
    if (ret != 2) {
        fprintf(stderr, "SPI write (addr 0x%02X) failed: %s\n",
                reg, pigpio_error(ret));
        return -1;
    }

    /* Phase 2: dummy transfer to clock out data */
    tx[0] = 0x00;
    tx[1] = 0x00;
    ret = spiXfer(spi_handle, tx, rx, 2);
    if (ret != 2) {
        fprintf(stderr, "SPI read (addr 0x%02X) failed: %s\n",
                reg, pigpio_error(ret));
        return -1;
    }

    /* Data is returned MSB first */
    *out = (int16_t)(((uint16_t)(uint8_t)rx[0] << 8) | (uint8_t)rx[1]);
    return 0;
}

/* Read all six degrees-of-freedom channels */
static int read_imu_data(int16_t gyro_x, int16_t gyro_y, int16_t gyro_z,
                         int16_t accel_x, int16_t accel_y, int16_t accel_z) {
    if (read_register(ADIS16362_REG_GYRO_XOUT_H, &gyro_x) != 0) return -1;
    if (read_register(ADIS16362_REG_GYRO_YOUT_H, &gyro_y) != 0) return -1;
    if (read_register(ADIS16362_REG_GYRO_ZOUT_H, &gyro_z) != 0) return -1;
    if (read_register(ADIS16362_REG_ACC_XOUT_H, &accel_x) != 0) return -1;
    if (read_register(ADIS16362_REG_ACC_YOUT_H, &accel_y) != 0) return -1;
    if (read_register(ADIS16362_REG_ACC_ZOUT_H, &accel_z) != 0) return -1;
    return 0;
}

/* Log one data record to the CSV file */
static void log_data(FILE *fp, int16_t gx, int16_t gy, int16_t gz,
                     int16_t ax, int16_t ay, int16_t az) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }

    fprintf(fp, "%ld.%09ld,%d,%d,%d,%d,%d,%d\n",
            (long)ts.tv_sec, ts.tv_nsec,
            gx, gy, gz, ax, ay, az);
    fflush(fp);
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI channel 0, CE0 (GPIO 8), 1 MHz, Mode 3 */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %s\n", pigpio_error(spi_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen("imu_log.csv", "a");
    if (log_file == NULL) {
        perror("fopen(imu_log.csv)");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,X_Gyro,Y_Gyro,Z_Gyro,X_Accel,Y_Accel,Z_Accel\n");
        fflush(log_file);
    }

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("ADIS16362 IMU logging started. Press Ctrl-C to stop.\n");

    /* Main sampling loop */
    while (!terminate) {
        int16_t gx, gy, gz, ax, ay, az;

        if (read_imu_data(gx, gy, gz, ax, ay, az) == 0) {
            log_data(log_file, gx, gy, gz, ax, ay, az);
        } else {
            fprintf(stderr, "IMU read error; skipping sample.\n");
        }

        /* 10 ms delay to approximate 100 Hz sampling */
        gpioDelay(10000);
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    if (log_file) {
        fflush(log_file);
        fclose(log_file);
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

