    line1 = gpiod_chip_get_line(chip, SENSOR1_OFFSET);
    if (line1 == NULL) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", SENSOR1_OFFSET, strerror(errno));
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, SENSOR2_OFFSET);
    if (line2 == NULL) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", SENSOR2_OFFSET, strerror(errno));
        goto cleanup;
    }

    /* --- Request both lines as inputs --- */
    if (gpiod_line_request_input(line1, "ky032_sensor1") < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as input: %s\n",
                SENSOR1_OFFSET, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(line2, "ky032_sensor2") < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as input: %s\n",
                SENSOR2_OFFSET, strerror(errno));
        goto cleanup;
    }

    printf("KY-032 obstacle-avoidance poll started.\n");
    printf("  Sensor 1: GPIO%d (physical pin 11)\n", SENSOR1_OFFSET);
    printf("  Sensor 2: GPIO%d (physical pin 13)\n", SENSOR2_OFFSET);
    printf("  Poll interval: %d ms\n", POLL_INTERVAL_US / 1000);
    printf("  Press Ctrl+C to exit.\n\n");

