    while (g_running) {
        int v1 = gpiod_line_get_value(line1);
        int v2 = gpiod_line_get_value(line2);

        if (v1 < 0 || v2 < 0) {
            fprintf(stderr, "Error reading sensor values: %s\n", strerror(errno));
            /* Brief pause before retrying to avoid log flooding */
            usleep(POLL_INTERVAL_US);
            continue;
        }

        print_timestamp();
        printf("Sensor 1: %d (obstacle: %s), Sensor 2: %d (obstacle: %s)\n",
               v1, v1 == 0 ? "DETECTED" : "clear",
               v2, v2 == 0 ? "DETECTED" : "clear");

        usleep(POLL_INTERVAL_US);
    }

    printf("\nShutting down cleanly...\n");
    rc = EXIT_SUCCESS;

cleanup:
    /* gpiod_line_release is safe to call even if the request failed. */
    if (line1 != NULL)
        gpiod_line_release(line1);
    if (line2 != NULL)
        gpiod_line_release(line2);
    if (chip != NULL)
        gpiod_chip_close(chip);

    return rc;
}

