/*
 * ADIS16266 Gyroscope SPI reader for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   ADIS16266 CS  -> GPIO8  (BCM 8, SPI0 CE0)
 *   ADIS16266 SDO -> GPIO9  (BCM 9, SPI0 MISO)
 *   ADIS16266 SDA -> GPIO10 (BCM 10, SPI0 MOSI)
 *   ADIS16266 SCL -> GPIO11 (BCM 11, SPI0 SCLK)
 *   ADIS16266 VDD -> 3.3 V
 *   ADIS16266 GND -> GND
 *
 * SPI: /dev/spidev0.0, 1 MHz, Mode 3 (CPOL=1, CPHA=1), MSB-first
 * Scale factor: 0.02 deg/sec per LSB (from datasheet)
 *
 * Build: gcc -O2 -Wall -o adis16266 adis16266.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U   /* 1 MHz */
#define SPI_MODE        SPI_MODE_3
#define SPI_BITS        8

#define ADIS16266_REG_XGYRO_OUT  0x04
#define ADIS16266_REG_YGYRO_OUT  0x05
#define ADIS16266_REG_ZGYRO_OUT  0x06
#define ADIS16266_REG_SMPL_PRD   0x02

#define SCALE_FACTOR 0.02f   /* deg/sec per LSB */

#define SAMPLE_PERIOD_US 100000U  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int spi_transfer(int fd, const uint8_t *tx, uint8_t *rx, size_t len)
{
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (uintptr_t)tx;
    tr.rx_buf        = (uintptr_t)rx;
    tr.len           = len;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int adis16266_read_register(int fd, uint8_t reg, uint8_t *value)
{
    uint8_t tx[2] = { (uint8_t)(reg | 0x80), 0x00 };
    uint8_t rx[2] = { 0, 0 };

    if (spi_transfer(fd, tx, rx, 2) < 0)
        return -1;

    if (spi_transfer(fd, tx, value, 1) < 0)
        return -1;

    return 0;
}

static int adis16266_write_register(int fd, uint8_t reg, uint8_t value)
{
    uint8_t tx[2] = { (uint8_t)(reg & 0x7F), value };
    uint8_t rx[2] = { 0, 0 };

    if (spi_transfer(fd, tx, rx, 2) < 0)
        return -1;

    return 0;
}

static int adis16266_read_gyro(int fd, float *x, float *y, float *z)
{
    uint8_t x_raw, y_raw, z_raw;

    if (adis16266_read_register(fd, ADIS16266_REG_XGYRO_OUT, &x_raw) < 0) {
        fprintf(stderr, "Failed to read X gyro: %s\n", strerror(errno));
        return -1;
    }
    if (adis16266_read_register(fd, ADIS16266_REG_YGYRO_OUT, &y_raw) < 0) {
        fprintf(stderr, "Failed to read Y gyro: %s\n", strerror(errno));
        return -1;
    }
    if (adis16266_read_register(fd, ADIS16266_REG_ZGYRO_OUT, &z_raw) < 0) {
        fprintf(stderr, "Failed to read Z gyro: %s\n", strerror(errno));
        return -1;
    }

    *x = (float)x_raw * SCALE_FACTOR;
    *y = (float)y_raw * SCALE_FACTOR;
    *z = (float)z_raw * SCALE_FACTOR;
    return 0;
}

static void log_gyro_data(float x, float y, float z)
{
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char time_str[32];
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", &tm_info);

    printf("[%s.%03ld] X: %+.4f deg/s, Y: %+.4f deg/s, Z: %+.4f deg/s\n",
           time_str, ts.tv_nsec / 1000000L, x, y, z);
    fflush(stdout);
}

int main(void)
{
    int fd = -1;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", SPI_DEVICE, strerror(errno));
        return EXIT_FAILURE;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE failed: %s\n", strerror(errno));
        goto cleanup;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD failed: %s\n", strerror(errno));
        goto cleanup;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Verify settings were accepted */
    uint32_t actual_speed = 0;
    if (ioctl(fd, SPI_IOC_RD_MAX_SPEED_HZ, &actual_speed) < 0) {
        fprintf(stderr, "SPI_IOC_RD_MAX_SPEED_HZ failed: %s\n", strerror(errno));
        goto cleanup;
    }
    if (actual_speed != SPI_SPEED_HZ) {
        fprintf(stderr, "Warning: requested %u Hz, got %u Hz\n",
                SPI_SPEED_HZ, actual_speed);
    }

    /* Set sample period register (0x02) to 100 ms (0x0064 = 100 * 64 us) */
    if (adis16266_write_register(fd, ADIS16266_REG_SMPL_PRD, 0x0064) < 0) {
        fprintf(stderr, "Failed to set sample period: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("ADIS16266 initialized. Sampling every 100 ms. Press Ctrl+C to exit.\n");

    while (g_running) {
        float x, y, z;
        if (adis16266_read_gyro(fd, &x, &y, &z) == 0) {
            log_gyro_data(x, y, z);
        } else {
            fprintf(stderr, "Gyro read failed; continuing.\n");
        }
        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nExiting cleanly.\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0)
        close(fd);
    return ret;
}

