#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <pigpio.h>

/* ---- LSM6DSR I2C address (SA0 tied to GND on the breakout) ---- */
#define LSM6DSR_ADDR 0x77

/* ---- LSM6DSR register addresses ---- */
#define LSM6DSR_WHO_AM_I   0x0F
#define LSM6DSR_CTRL1_XL   0x10
#define LSM6DSR_CTRL2_G    0x11
#define LSM6DSR_OUTX_L_G   0x22
#define LSM6DSR_OUTX_H_G   0x23
#define LSM6DSR_OUTY_L_G   0x24
#define LSM6DSR_OUTY_H_G   0x25
#define LSM6DSR_OUTZ_L_G   0x26
#define LSM6DSR_OUTZ_H_G   0x27
#define LSM6DSR_OUTX_L_XL  0x28
#define LSM6DSR_OUTX_H_XL  0x29
#define LSM6DSR_OUTY_L_XL  0x2A
#define LSM6DSR_OUTY_H_XL  0x2B
#define LSM6DSR_OUTZ_L_XL  0x2C
#define LSM6DSR_OUTZ_H_XL  0x2D

/* ---- Expected WHO_AM_I value for LSM6DSR ---- */
#define LSM6DSR_WHO_AM_I_VAL 0x6A

/* ---- Gyro full-scale ±250 °/s ---- */
#define GYRO_FS 250.0f

/* ---- Accel full-scale ±2 g ---- */
#define ACCEL_FS 2.0f

/* ---- Sensitivities (raw LSB per LSB) ---- */
#define ACCEL_SENSITIVITY 0.000244f
#define GYRO_SENSITIVITY  0.00875f

/* ---- Global state ---- */
static int i2c_handle = -1;
static volatile sig_atomic_t program_running = 1;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

/* ---- Cleanup helper ---- */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

/* ---- Verify device identity ---- */
static bool verify_who_am_i(int handle)
{
    int who = i2cReadByteData(handle, LSM6DSR_WHO_AM_I);
    if (who < 0) {
        fprintf(stderr, "Error: failed to read WHO_AM_I register: %s\n",
                strerror(errno));
        return false;
    }
    if (who != LSM6DSR_WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X)\n",
                who, LSM6DSR_WHO_AM_I_VAL);
        return false;
    }
    return true;
}

/* ---- Configure LSM6DSR ---- */
static bool configure_lsm6dsr(int handle)
{
    /* Gyro: ODR = 119 Hz (0x60), FS = ±250 °/s */
    if (i2cWriteByteData(handle, LSM6DSR_CTRL2_G, 0x60) < 0) {
        fprintf(stderr, "Error: failed to write CTRL2_G: %s\n", strerror(errno));
        return false;
    }
    /* Accel: ODR = 119 Hz (0x60), FS = ±2 g */
    if (i2cWriteByteData(handle, LSM6DSR_CTRL1_XL, 0x60) < 0) {
        fprintf(stderr, "Error: failed to write CTRL1_XL: %s\n", strerror(errno));
        return false;
    }
    return true;
}

/* ---- Read a single byte register ---- */
static bool read_byte(int handle, uint8_t reg, uint8_t *out)
{
    int v = i2cReadByteData(handle, reg);
    if (v < 0) {
        fprintf(stderr, "Error: failed to read register 0x%02X: %s\n",
                reg, strerror(errno));
        return false;
    }
    *out = (uint8_t)v;
    return true;
}

/* ---- Read a burst of bytes starting at reg ---- */
static bool read_burst(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    int n = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (n != (int)len) {
        fprintf(stderr, "Error: burst read of %u bytes from 0x%02X failed "
                "(got %d): %s\n", len, reg, n, strerror(errno));
        return false;
    }
    return true;
}

/* ---- Read a 16-bit little-endian axis ---- */
static bool read_axis(int handle, uint8_t reg_l, uint8_t reg_h,
                      float *out)
{
    uint8_t buf[2];
    if (!read_burst(handle, reg_l, buf, 2))
        return false;
    int16_t raw = (int16_t)((uint16_t)buf[0] | ((uint16_t)buf[1] << 8));
    *out = (float)raw * (ACCEL_SENSITIVITY * ACCEL_FS);
    return true;
}

/* ---- Read all six axes ---- */
static bool read_all_axes(int handle, float *ax, float *ay, float *az,
                          float *gx, float *gy, float *gz)
{
    if (!read_axis(handle, LSM6DSR_OUTX_L_XL, LSM6DSR_OUTX_H_XL, ax))
        return false;
    if (!read_axis(handle, LSM6DSR_OUTY_L_XL, LSM6DSR_OUTY_H_XL, ay))
        return false;
    if (!read_axis(handle, LSM6DSR_OUTZ_L_XL, LSM6DSR_OUTZ_H_XL, az))
        return false;
    if (!read_axis(handle, LSM6DSR_OUTX_L_G,  LSM6DSR_OUTX_H_G, gx))
        return false;
    if (!read_axis(handle, LSM6DSR_OUTY_L_G,  LSM6DSR_OUTY_H_G, gy))
        return false;
    if (!read_axis(handle, LSM6DSR_OUTZ_L_G,  LSM6DSR_OUTZ_H_G, gz))
        return false;
    return true;
}

/* ---- Print one sample line ---- */
static void print_sample(float ax, float ay, float az,
                         float gx, float gy, float gz)
{
    printf("Accel: X=%.3f Y=%.3f Z=%.3f  Gyro: X=%.3f Y=%.3f Z=%.3f\n",
           ax, ay, az, gx, gy, gz);
    fflush(stdout);
}

int main(void)
{
    /* Install SIGINT handler for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler: %s\n",
                strerror(errno));
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the LSM6DSR address */
    i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle %d): %s\n",
                i2c_handle, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Verify device identity */
    if (!verify_who_am_i(i2c_handle)) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure LSM6DSR */
    if (!configure_lsm6dsr(i2c_handle)) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("LSM6DSR initialised. Sampling every 100 ms. Press Ctrl+C to stop.\n");
    fflush(stdout);

    /* Main sampling loop */
    while (program_running) {
        float ax, ay, az, gx, gy, gz;
        if (read_all_axes(i2c_handle, &ax, &ay, &az, &gx, &gy, &gz)) {
            print_sample(ax, ay, az, gx, gy, gz);
        } else {
            fprintf(stderr, "Warning: sensor read failed, continuing...\n");
        }
        gpioDelay(100000); /* 100 ms in microseconds */
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

