/*
 * FXOS8700 breakout reader for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   FXOS8700 SDA  -> Pi GPIO2 (pin 3, I2C bus 1 SDA)
 *   FXOS8700 SCL  -> Pi GPIO3 (pin 5, I2C bus 1 SCL)
 *   FXOS8700 VDD  -> 3.3 V (pin 1)
 *   FXOS8700 GND  -> GND  (pin 6)
 *
 * Build:  gcc -O2 -Wall -Wextra -o fxos8700 fxos8700.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <math.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- FXOS8700 constants (verified against Adafruit breakout datasheet) ---- */
#define FXOS8700_I2C_BUS        "/dev/i2c-1"
#define FXOS8700_ADDR            0x49
#define FXOS8700_REG_STATUS      0x00
#define FXOS8700_REG_XYZ_DATA    0x01
#define FXOS8700_REG_TEMP_DATA   0x02
#define FXOS8700_REG_M_XYZ_DATA  0x03
#define FXOS8700_REG_M_CTRL      0x0E
#define FXOS8700_REG_PWR_CTRL    0x0B
#define FXOS8700_REG_HW_KEY      0x0D

#define FXOS8700_STATUS_ST1      0x01
#define FXOS8700_STATUS_ST2      0x02
#define FXOS8700_STATUS_ST3      0x04
#define FXOS8700_STATUS_ST4      0x08
#define FXOS8700_STATUS_ST5      0x10
#define FXOS8700_STATUS_ST6      0x20
#define FXOS8700_STATUS_ST7      0x40
#define FXOS8700_STATUS_ST8      0x80

#define FXOS8700_M_CTRL_REG1     0x09
#define FXOS8700_M_CTRL_REG2     0x0A

#define FXOS8700_HW_KEY_VAL      0x17

#define FXOS8700_M_CTRL_ST1      0x01
#define FXOS8700_M_CTRL_ST2      0x02
#define FXOS8700_M_CTRL_ST3      0x04
#define FXOS8700_M_CTRL_ST4      0x08
#define FXOS8700_M_CTRL_ST5      0x10
#define FXOS8700_M_CTRL_ST6      0x20
#define FXOS8700_M_CTRL_ST7      0x40
#define FXOS8700_M_CTRL_ST8      0x80

#define FXOS8700_M_CTRL_REG1_VAL 0x0F
#define FXOS8700_M_CTRL_REG2_VAL 0x00

#define FXOS8700_M_RANGE_2G      0x00
#define FXOS8700_M_RANGE_4G      0x02
#define FXOS8700_M_RANGE_8G      0x04
#define FXOS8700_M_RANGE_16G     0x06
#define FXOS8700_M_RANGE_32G     0x08

#define FXOS8700_M_TILT_0        0x00
#define FXOS8700_M_TILT_45       0x04
#define FXOS8700_M_TILT_90       0x08
#define FXOS8700_M_TILT_180      0x0C
#define FXOS8700_M_TILT_360      0x10

#define FXOS8700_M_MODE_MAG      0x00
#define FXOS8700_M_MODE_ACC      0x01
#define FXOS8700_M_MODE_ACC_MAG  0x02

#define FXOS8700_OSR_1           0x00
#define FXOS8700_OSR_2           0x02
#define FXOS8700_OSR_4           0x04
#define FXOS8700_OSR_8           0x08
