#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define ADXL345_ADDRESS 0x2D
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATA_FORMAT 0x31
#define ADXL345_DATAX0 0x32
#define ADXL345_BW_RATE 0x2C
#define ADXL345_THRESH_ACT 0x28
#define ADXL345_THRESH_INACT 0x29
#define ADXL345_FILTER_CTL 0x2F
#define ADXL345_DATA_FORMAT_VAL 0x0B
#define ADXL345_POWER_CTL_VAL 0x08
#define ADXL345_I2C_BUS 1
#define TILT_THRESHOLD 30.0
#define LOG_FILE "/var/log/tilt_events.log"
#define SAMPLE_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int adxl345_write_reg(int handle, uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "Error writing reg 0x%02X: %d\n", reg, rc);
    }
    return rc;
}

static int adxl345_read_regs(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc < 0) {
        fprintf(stderr, "Error reading reg 0x%02X: %d\n", reg, rc);
    }
    return rc;
}

static int adxl345_init(int handle) {
    if (adxl345_write_reg(handle, ADXL345_POWER_CTL, ADXL345_POWER_CTL_VAL) < 0) return -1;
    gpioDelay(10000);
    if (adxl345_write_reg(handle, ADXL345_DATA_FORMAT, ADXL345_DATA_FORMAT_VAL) < 0) return -1;
    if (adxl345_write_reg(handle, ADXL345_BW_RATE, 0x0A) < 0) return -1;
    if (adxl345_write_reg(handle, ADXL345_THRESH_ACT, 0x0A) < 0) return -1;
    if (adxl345_write_reg(handle, ADXL345_THRESH_INACT, 0x0A) < 0) return -1;
    if (adxl345_write_reg(handle, ADXL345_FILTER_CTL, 0x0A) < 0) return -1;
    return 0;
}

static int read_acceleration(int handle, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (adxl345_read_regs(handle, ADXL345_DATAX0, buf, 6) < 0) return -1;
    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

static double calculate_tilt_angle(int16_t x, int16_t y) {
