#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define SENSOR_PIN 17          /* BCM 17, physical pin 11 */
#define WINDOW_SECONDS 5
#define SAMPLE_INTERVAL_US 1000 /* 1 ms */
#define PAUSE_SECONDS 1

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void print_timestamped(const char *msg)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return;
    }
    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return;
    }
    char buf[32];
    if (strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return;
    }
    printf("[%s] %s\n", buf, msg);
    fflush(stdout);
}

int main(int argc, char *argv[])
{
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        fprintf(stderr, "  threshold  : minimum high-readings per window\n");
        fprintf(stderr, "  example: %s 5\n", argv[0]);
        return EXIT_FAILURE;
    }

    char *endptr = NULL;
    long threshold = strtol(argv[1], &endptr, 10);
    if (endptr == argv[1] || *endptr != '\0' || threshold < 0) {
        fprintf(stderr, "Invalid threshold: '%s'\n", argv[1]);
        return EXIT_FAILURE;
    }

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure sensor pin as input */
    if (gpioSetMode(SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_INPUT) failed\n", SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Monitoring KY-038 sound sensor on GPIO%d for %d seconds.\n", SENSOR_PIN, WINDOW_SECONDS);
    printf("Threshold: %ld high readings per window.\n", threshold);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    int high_count = 0;
    int exit_code = EXIT_SUCCESS;

    while (g_running) {
        for (int i = 0; i < WINDOW_SECONDS * 1000 && g_running; i++) {
            int level = gpioRead(SENSOR_PIN);
            if (level < 0) {
                fprintf(stderr, "gpioRead(%d) failed: %s\n", SENSOR_PIN, strerror(errno));
                exit_code = EXIT_FAILURE;
                break;
            }
            if (level == 1) {
                high_count++;
            }
            gpioDelay(SAMPLE_INTERVAL_US);
        }

        if (!g_running) {
            break;
        }

        if (high_count > threshold) {
            print_timestamped("ALERT");
        } else {
            print_timestamped("OK");
        }

        /* Pause for the remainder of the window, checking for shutdown */
        for (int s = 0; s < WINDOW_SECONDS && g_running; s++) {
            sleep(1);
        }
    }

    /* Clean up pigpio resources */
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return exit_code;
}

