#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME  "gpiochip4"
#define GPIO_A_OFFSET   17
#define GPIO_B_OFFSET   27
#define LOCK_DURATION   5
#define LOG_FILE        "access_log.txt"
#define NUM_DIGITS      6

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int generate_code(struct gpiod_line *a_line, struct gpiod_line *b_line)
{
    int code = rand() % 900000 + 100000;
    if (gpiod_line_set_value(a_line, 1) < 0) {
        fprintf(stderr, "Failed to set GPIO%d HIGH: %s\n", GPIO_A_OFFSET, strerror(errno));
        return -1;
    }
    if (gpiod_line_set_value(b_line, 1) < 0) {
        fprintf(stderr, "Failed to set GPIO%d HIGH: %s\n", GPIO_B_OFFSET, strerror(errno));
        gpiod_line_set_value(a_line, 0);
        return -1;
    }
    printf("Security code: %d\n", code);
    fflush(stdout);
    return 0;
}

static int read_code(int *code)
{
    char buf[32];
    printf("Enter the security code: ");
    fflush(stdout);
    if (fgets(buf, sizeof(buf), stdin) == NULL) {
        fprintf(stderr, "Error reading input: %s\n", strerror(errno));
        return -1;
    }
    buf[strcspn(buf, "\n")] = '\0';
    char *endptr;
    long val = strtol(buf, &endptr, 10);
    if (endptr == buf) {
        fprintf(stderr, "Invalid input. Please enter a numeric value.\n");
        return -1;
    }
    if (val < 100000 || val > 999999) {
        fprintf(stderr, "Invalid input. Value must be between 100000 and 999999.\n");
        return -1;
    }
    *code = (int)val;
    return 0;
}

static int check_code(int entered, int generated)
{
    if (entered == generated) {
        FILE *fp = fopen(LOG_FILE, "a");
        if (fp == NULL) {
            fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
            return -1;
        }
        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%d\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, entered);
        fclose(fp);
        printf("Access granted.\n");
        return 0;
    } else {
        printf("Access denied.\n");
        return -1;
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *a_line = NULL;
    struct gpiod_line *b_line = NULL;
    int ret = 1;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return 1;
    }

    a_line = gpiod_chip_get_line(chip, GPIO_A_OFFSET);
    if (a_line == NULL) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_A_OFFSET, strerror(errno));
        goto cleanup;
    }

    b_line = gpiod_chip_get_line(chip, GPIO_B_OFFSET);
    if (b_line == NULL) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_B_OFFSET, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(a_line, "door_access", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", GPIO_A_OFFSET, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(b_line, "door_access", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", GPIO_B_OFFSET, strerror(errno));
        goto cleanup;
    }

    if (generate_code(a_line, b_line) < 0) {
        goto cleanup;
    }

    int entered_code = 0;
    while (g_running) {
        if (read_code(&entered_code) == 0) {
            if (check_code(entered_code, generated_code) == 0) {
                break;
            }
        }
        sleep(1);
    }

    ret = 0;

cleanup:
    if (a_line) gpiod_line_set_value(a_line, 0);
    if (b_line) gpiod_line_set_value(b_line, 0);
    if (a_line) gpiod_line_release(a_line);
    if (b_line) gpiod_line_release(b_line);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

