#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* HMC5883L I2C address (SA0 tied to GND) */
#define HMC5883L_ADDR 0x03

/* HMC5883L register addresses */
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE     0x02
#define HMC5883L_DATA_X_MSB 0x03
#define HMC5883L_DATA_Z_MSB 0x05
#define HMC5883L_DATA_Y_MSB 0x07

/* Configuration values */
#define HMC5883L_CONFIG_A_DEFAULT 0x70
#define HMC5883L_CONFIG_B_DEFAULT 0x20
#define HMC5883L_MODE_CONTINUOUS 0x00

/* Hard-iron offset buffer size */
#define BUFFER_SIZE 100

/* Sampling interval in microseconds */
#define SAMPLE_INTERVAL_US 500000

/* Global variables */
static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

/* Structure to hold magnetometer data */
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} magnetometer_data_t;

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

/* Function to initialize the HMC5883L */
static int initialize_hmc5883l(int handle) {
    /* Write config register A */
    if (i2cWriteByteData(handle, HMC5883L_CONFIG_A, HMC5883L_CONFIG_A_DEFAULT) < 0) {
        fprintf(stderr, "Error writing to config register A\n");
        return -1;
    }

    /* Write config register B */
    if (i2cWriteByteData(handle, HMC5883L_CONFIG_B, HMC5883L_CONFIG_B_DEFAULT) < 0) {
        fprintf(stderr, "Error writing to config register B\n");
        return -1;
    }

    /* Set continuous measurement mode */
    if (i2cWriteByteData(handle, HMC5883L_MODE, HMC5883L_MODE_CONTINUOUS) < 0) {
        fprintf(stderr, "Error writing to mode register\n");
        return -1;
    }

    return 0;
}

/* Function to read raw magnetometer data */
static int read_raw_data(int handle, magnetometer_data_t *data) {
    char buffer[6];

    /* Read 6 bytes of data starting from X MSB */
    if (i2cReadI2CBlockData(handle, HMC5883L_DATA_X_MSB, buffer, 6) != 6) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }

    /* HMC5883L outputs data in X, Z, Y order */
    data->x = (int16_t)((buffer[0] << 8) | buffer[1]);
    data->z = (int16_t)((buffer[2] << 8) | buffer[3]);
    data->y = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

/* Function to calculate hard-iron offsets */
static void calculate_hard_iron_offsets(magnetometer_data_t *data, int *offsets, int *index) {
    if (*index >= BUFFER_SIZE) {
        *index = 0;
    }

    *offsets[*index] += (int16_t)data->x;
    *offsets[*index] += (int16_t)data->y;
    *offsets[*index] += (int16_t)data->z;

    (*index)++;
}

/* Function to apply hard-iron offsets to raw data */
static magnetometer_data_t apply_hard_iron_offsets(magnetometer_data_t raw_data, int offsets[], int index) {
    magnetometer_data_t corrected_data;

    corrected_data.x = raw_data.x - offsets[index];
    corrected_data.y = raw_data.y - offsets[index];
    corrected_data.z = raw_data.z - offsets[index];

    return corrected_data;
}

/* Function to print magnetometer data */
static void print_magnetometer_data(magnetometer_data_t data) {
    printf("X: %d, Y: %d, Z: %d\n", data.x, data.y, data.z);
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Open I2C bus 1 */
    i2c_handle = i2cOpen(1, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Initialize HMC5883L */
    if (initialize_hmc5883l(i2c_handle) < 0) {
        fprintf(stderr, "HMC5883L initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Set up signal handling */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Hard-iron offset buffer */
    int offsets[BUFFER_SIZE] = {0};
    int offset_index = 0;

    /* Main loop */
    while (!terminate) {
        magnetometer_data_t raw_data;

        /* Read raw data */
        if (read_raw_data(i2c_handle, &raw_data) == 0) {
            /* Calculate hard-iron offsets */
            calculate_hard_iron_offsets(&raw_data, offsets, &offset_index);

            /* Apply hard-iron offsets */
            magnetometer_data_t corrected_data = apply_hard_iron_offsets(raw_data, offsets, offset_index);

            /* Print corrected data */
            print_magnetometer_data(corrected_data);
        } else {
            fprintf(stderr, "Failed to read magnetometer data\n");
        }

        /* Wait for 500ms */
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Close I2C bus */
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }

    /* Terminate pigpio */
    gpioTerminate();

    return 0;
}

