/*
 * LSM303D tri-axial accelerometer monitor for Raspberry Pi Zero W.
 *
 * Wiring:
 *   LSM303D SDA  -> Pi GPIO2 (physical pin 3)
 *   LSM303D SCL  -> Pi GPIO3 (physical pin 5)
 *   LSM303D VDD  -> 3.3 V
 *   LSM303D GND  -> GND
 *   LSM303D INT1 -> Pi GPIO23 (physical pin 16)
 *
 * Build:  gcc -O2 -Wall -Wextra -o lsm303d_mon lsm303d_mon.c -lgpiod
 * Run:    ./lsm303d_mon
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- LSM303D constants (verified against the datasheet) ---- */
#define LSM303D_ADDR        0x19
#define LSM303D_ID_REG      0x0F
#define LSM303D_ID_VAL      0x49
#define LSM303D_CTRL_REG1   0x20
#define LSM303D_CTRL_REG4   0x23
#define LSM303D_OUT_X_L     0x08
#define LSM303D_OUT_X_H     0x09
#define LSM303D_OUT_Y_L     0x0A
#define LSM303D_OUT_Y_H     0x0B
#define LSM303D_OUT_Z_L     0x0C
#define LSM303D_OUT_Z_H     0x0D

#define ACCEL_SENSITIVITY   0.061f   /* mg per LSB at +/-2 g */
#define ACCEL_THRESHOLD_MG  2000.0f
#define BUFFER_SIZE         64
#define SAMPLE_PERIOD_US    10000   /* 10 ms */

/* ---- Application constants ---- */
#define I2C_DEV            "/dev/i2c-1"
#define GPIO_CHIP          "gpiochip4"   /* BCM GPIO23 on Pi Zero W */
#define GPIO_INT_OFFSET    23          /* BCM 23, physical pin 16 */
#define POLL_TIMEOUT_MS    1000

/* ---- Data structures ---- */
typedef struct {
    float x, y, z;
} accel_sample_t;

typedef struct {
    accel_sample_t samples[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

/* ---- Globals ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static circular_buffer_t g_buffer;

/* ---- Signal handler ---- */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ---- */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (burst reg 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C burst read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- LSM303D operations ---- */
static int lsm303d_init(int fd)
{
    uint8_t id = 0;
    if (i2c_read_reg8(fd, LSM303D_ID_REG, &id) != 0) {
        fprintf(stderr, "Cannot read LSM303D ID register.\n");
        return -1;
    }
    if (id != LSM303D_ID_VAL) {
        fprintf(stderr, "Unexpected LSM303D ID: 0x%02X (expected 0x%02X).\n",
                id, LSM303D_ID_VAL);
        return -1;
    }

    /* Standby mode so configuration writes take effect */
    if (i2c_write_reg8(fd, LSM303D_CTRL_REG1, 0x00) != 0)
        return -1;

    /* +/-2 g full-scale, 50 Hz ODR */
    if (i2c_write_reg8(fd, LSM303D_CTRL_REG1, 0x00) != 0)
        return -1;

    /* 2000 mg threshold, no duration */
    if (i2c_write_reg8(fd, LSM303D_CTRL_REG4, 0x00) != 0)
        return -1;

    return 0;
}

static int lsm303d_read_accel(int fd, accel_sample_t *out)
{
    uint8_t raw[6];
    if (i2c_read_burst(fd, LSM303D_OUT_X_L, raw, sizeof(raw)) != 0)
        return -1;

    int16_t x = (int16_t)((raw[1] << 8) | raw[0]);
    int16_t y = (int16_t)((raw[3] << 8) | raw[2]);
    int16_t z = (int16_t)((raw[5] << 8) | raw[4]);

    out->x = (float)x * ACCEL_SENSITIVITY;
    out->y = (float)y * ACCEL_SENSITIVITY;
    out->z = (float)z * ACCEL_SENSITIVITY;
    return 0;
}

/* ---- Circular buffer ---- */
static void buffer_init(circular_buffer_t *buf)
{
    buf->head = 0;
    buf->count = 0;
}

static void buffer_add(circular_buffer_t *buf, accel_sample_t s)
{
    buf->samples[buf->head] = s;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count < BUFFER_SIZE)
        buf->count++;
}

static void buffer_dump(const circular_buffer_t *buf, int n)
{
    if (n > buf->count)
        n = buf->count;
    int start = (buf->head - n + BUFFER_SIZE) % BUFFER_SIZE;
    for (int i = 0; i < n; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        printf("[%d]  X: %+.4f mg  Y: %+.4f mg  Z: %+.4f mg\n",
               i, buf->samples[idx].x, buf->samples[idx].y, buf->samples[idx].z);
    }
    printf("\n");
}

/* ---- Main ---- */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_DEV, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_DEV, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, LSM303D_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                LSM303D_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    if (lsm303d_init(g_i2c_fd) != 0) {
        fprintf(stderr, "LSM303D initialization failed.\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Configure GPIO23 as input with pull-up (INT1 is active-high) */
    struct gpio_chip *chip = gpio_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "gpio_chip_open(%s) failed: %s\n",
                GPIO_CHIP, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }
    struct gpio_line *int_line = gpio_chip_get_line(chip, GPIO_INT_OFFSET);
    if (!int_line) {
        fprintf(stderr, "gpio_chip_get_line(%d) failed: %s\n",
                GPIO_INT_OFFSET, strerror(errno));
        gpio_chip_close(chip);
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }
    if (gpio_line_request_input_flags(int_line, "lsm303d-mon",
                                      GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        fprintf(stderr, "gpio_line_request_input failed: %s\n", strerror(errno));
        gpio_chip_close(chip);
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    buffer_init(&g_buffer);
    printf("LSM303D monitoring started.  Sampling every %d us.  Ctrl-C to exit.\n",
           SAMPLE_PERIOD_US);

    while (g_running) {
        accel_sample_t sample;
        if (lsm303d_read_accel(g_i2c_fd, &sample) != 0) {
            /* I2C read failed — warn and skip this sample */
            continue;
        }
        buffer_add(&g_buffer, sample);

        /* Check INT1 for rising edge */
        static int prev_int = 0;
        int cur = gpio_line_get_value(int_line);
        if (cur == 1 && prev_int == 0) {
            buffer_dump(&g_buffer, BUFFER_SIZE);
            prev_int = 1;
        }
        gpio_line_set_value(int_line, 0);
        usleep(POLL_TIMEOUT_MS * 1000);
    }

    /* Graceful shutdown */
    printf("\nShutting down...\n");
    i2c_write_reg8(g_i2c_fd, LSM303D_CTRL_REG1, 0x00);   /* standby */
    gpio_line_set_value(int_line, 0);
    gpio_line_release(int_line);
    gpio_chip_close(chip);
    close(g_i2c_fd);
    printf("Resources released.  Exiting.\n");
    return EXIT_SUCCESS;
}

