/*
 * solenoid_toggle.c — Alternately drive two 12 V solenoids via TIP120s
 * on a Raspberry Pi 3 Model B+ using pigpio.
 *
 * Wiring:
 *   Solenoid 1 (GPIO17) — TIP120 gate -> solenoid coil
 *   Solenoid 2 (GPIO27) — TIP120 gate -> solenoid coil
 *   TIP120 collector -> 12 V supply
 *   TIP120 emitter -> solenoid common
 *   Flyback diode from solenoid coil to emitter.
 *
 * Build:  gcc -O2 -Wall -Wextra -o solenoid_toggle solenoid_toggle.c -lpigpio -lrt
 * Run:    sudo ./solenoid_toggle
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <time.h>
#include <pigpio.h>

#define SOLENOID_1_PIN 17
#define SOLENOID_2_PIN 27
#define DELAY_MS       500

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int safe_set_mode(unsigned pin, unsigned mode)
{
    if (gpioSetMode(pin, mode) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%u, %u) failed\n", pin, mode);
        return -1;
    }
    return 0;
}

static int safe_write(unsigned pin, unsigned level)
{
    if (gpioWrite(pin, level) != 0) {
        fprintf(stderr, "Error: gpioWrite(%u, %u) failed\n", pin, level);
        return -1;
    }
    return 0;
}

static int safe_release(unsigned pin)
{
    if (gpioWrite(pin, 0) != 0) {
        fprintf(stderr, "Error: gpioWrite(%u, 0) failed during release\n", pin);
        return -1;
    }
    return 0;
}

int main(void)
{
    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure pins as outputs, start LOW (solenoids de-energized) --- */
    if (safe_set_mode(SOLENOID_1_PIN, PI_OUTPUT) != 0 ||
        safe_set_mode(SOLENOID_2_PIN, PI_OUTPUT) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (safe_write(SOLENOID_1_PIN, 0) != 0 ||
        safe_write(SOLENOID_2_PIN, 0) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Solenoid toggle started. Press Ctrl+C to exit.\n");

    /* --- Main loop: alternate solenoids every 500 ms --- */
    while (g_running) {
        if (safe_write(SOLENOID_1_PIN, 1) != 0) break;
        if (safe_write(SOLENOID_2_PIN, 0) != 0) break;
        printf("Solenoid 1 ON | Solenoid 2 OFF\n");
        fflush(stdout);
        struct timespec ts = { .tv_sec = 0, .tv_nsec = DELAY_MS * 1000000L };
        nanosleep(&ts, NULL);

        if (!g_running) break;

        if (safe_write(SOLENOID_1_PIN, 0) != 0) break;
        if (safe_write(SOLENOID_2_PIN, 1) != 0) break;
        printf("Solenoid 1 OFF | Solenoid 2 ON\n");
        fflush(stdout);
        nanosleep(&ts, NULL);
    }

    /* --- Clean shutdown: de-energize both solenoids --- */
    if (safe_release(SOLENOID_1_PIN) != 0) {
        fprintf(stderr, "Warning: failed to release solenoid 1\n");
    }
    if (safe_release(SOLENOID_2_PIN) != 0) {
        fprintf(stderr, "Warning: failed to release solenoid 2\n");
    }

    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

