#define UART_PORT_0 "/dev/serial0"
#define UART_PORT_1 "/dev/serial1"
#define LOCK_RELAY_1_GPIO 17
#define LOCK_RELAY_2_GPIO 27
#define LOCK_DURATION_SEC 2
#define CODE_TO_LOCK 123456
#define READ_TIMEOUT_SEC 5
#define MAX_BUFFER_SIZE 256

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int init_uart(const char *port) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd < 0) {
        fprintf(stderr, "Error opening UART %s: %s\n", port, strerror(errno));
        return -1;
    }

    struct termios tty;
    memset(&tty, 0, sizeof(tty));
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error getting termios attributes for %s: %s\n", port, strerror(errno));
        close(fd);
        return -1;
    }

    cfsetispeed(&tty, B9600);
    cfsetospeed(&tty, B9600);

    tty.c_cflag = CS8 | CLOCAL | CREAD;
    tty.c_iflag = IGNPAR;
    tty.c_oflag = 0;
    tty.c_lflag = 0;

    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 5; /* 0.5s timeout */

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error setting termios attributes for %s: %s\n", port, strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

static int read_uart(int fd, char *buffer, size_t size) {
    fd_set readfds;
    struct timeval timeout;

    FD_ZERO(&readfds);
    FD_SET(fd, &readfds);

    timeout.tv_sec = READ_TIMEOUT_SEC;
    timeout.tv_usec = 0;

    int retval = select(fd + 1, &readfds, NULL, NULL, &timeout);
    if (retval < 0) {
        if (errno == EINTR) return 0;
        fprintf(stderr, "Error in select() for UART %s: %s\n", UART_PORT_0, strerror(errno));
        return -1;
    }
    if (retval == 0) {
        fprintf(stderr, "Timeout reading from UART %s\n", UART_PORT_0);
        return -1;
    }

    int bytes_read = read(fd, buffer, size - 1);
    if (bytes_read < 0) {
        fprintf(stderr, "Error reading from UART %s: %s\n", UART_PORT_0, strerror(errno));
        return -1;
    }
    if (bytes_read == 0) {
        fprintf(stderr, "Timeout reading from UART %s\n", UART_PORT_0);
        return -1;
    }

    buffer[bytes_read] = '\0';
    return 0;
}

static int is_digit(char c) {
    return (c >= '0' && c <= '9');
}

static int read_code(int fd, char *buffer, size_t size) {
    buffer[0] = '\0';
    int code_length = 0;

    while (code_length < size - 1) {
        if (!program_running) return -1;

        if (read_uart(fd, buffer + code_length, size - 1 - code_length) != 0) {
            return -1;
        }

        if (!is_digit(buffer[code_length])) {
            code_length = 0;
        } else {
            code_length++;
        }
    }

    return 0;
}

static int compare_codes(const char *code1, const char *code2) {
    return strcmp(code1, code2);
}

static int unlock_door_locks(struct gpiod_line *relay1, struct gpiod_line *relay2) {
    if (gpiod_line_set_value(relay1, 1) < 0) {
        fprintf(stderr, "Error setting relay 1 HIGH: %s\n", strerror(errno));
        return -1;
    }
    if (gpiod_line_set_value(relay2, 1) < 0) {
        fprintf(stderr, "Error setting relay 2 HIGH: %s\n", strerror(errno));
        gpiod_line_set_value(relay1, 0);
        return -1;
    }

    sleep(LOCK_DURATION_SEC);

    if (gpiod_line_set_value(relay1, 0) < 0) {
        fprintf(stderr, "Error setting relay 1 LOW: %s\n", strerror(errno));
        return -1;
    }
    if (gpiod_line_set_value(relay2, 0) < 0) {
        fprintf(stderr, "Error setting relay 2 LOW: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *relay1 = NULL;
    struct gpiod_line *relay2 = NULL;
    int uart_fd0 = -1, uart_fd1 = -1;
    int ret = 1;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error installing SIGINT handler: %s\n", strerror(errno));
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error installing SIGTERM handler: %s\n", strerror(errno));
        goto cleanup;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Error opening gpiochip4: %s\n", strerror(errno));
        goto cleanup;
    }

    relay1 = gpiod_chip_get_line(chip, LOCK_RELAY_1_GPIO);
    relay2 = gpiod_chip_get_line(chip, LOCK_RELAY_2_GPIO);
    if (!relay1 || !relay2) {
        fprintf(stderr, "Error getting GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(relay1, "door_lock", 0) < 0 ||
        gpiod_line_request_output(relay2, "door_lock", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO lines as output: %s\n", strerror(errno));
        goto cleanup;
    }

    uart_fd0 = init_uart(UART_PORT_0);
    if (uart_fd0 < 0) goto cleanup;

    uart_fd1 = init_uart(UART_PORT_1);
    if (uart_fd1 < 0) goto cleanup;

    printf("Door lock system started. Waiting for codes...\n");

    char code1_buf[MAX_BUFFER_SIZE];
    char code2_buf[MAX_BUFFER_SIZE];
    int code1_length = 0;
    int code2_length = 0;

    while (program_running) {
        if (read_code(uart_fd0, code1_buf, sizeof(code1_buf)) == 0) {
            code1_length = strlen(code1_buf);
            if (code1_length == 6) {
                if (compare_codes(code1_buf, code2_buf) == 0) {
                    if (compare_codes(code1_buf, CODE_TO_LOCK) == 0) {
                        printf("Codes match! Unlocking door lock.\n");
                        if (unlock_door_locks(relay1, relay2) == 0) {
                            printf("Door lock unlocked successfully.\n");
                        } else {
                            fprintf(stderr, "Error unlocking door lock.\n");
                        }
                    } else {
                        printf("Invalid code. Keeping door locked.\n");
                    }
                } else {
                    printf("Invalid code. Keeping door locked.\n");
                }
            } else {
                printf("Invalid code length. Keeping door locked.\n");
            }
        } else {
            fprintf(stderr, "Error reading code from UART 0. Retrying...\n");
        }
    }

    printf("Shutting down...\n");
    ret = 0;

cleanup:
    if (relay1) gpiod_line_set_value(relay1, 0);
    if (relay2) gpiod_line_set_value(relay2, 0);
    if (relay1) gpiod_line_release(relay1);
    if (relay2) gpiod_line_release(relay2);
    if (chip) gpiod_chip_close(chip);
    if (uart_fd0 >= 0) close(uart_fd0);
    if (uart_fd1 >= 0) close(uart_fd1);

    return ret;
}

