#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <syslog.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>

#define PIR_PIN 4
#define RELAY_PIN 17
#define POLL_INTERVAL_MS 50
#define RELAY_ACTIVE_MS 1000
#define FAILSAFE_TIMEOUT_S 10
#define GPIO_CHIP_NAME "gpiochip4"

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int gpio_request_line(unsigned int pin, const char *consumer) {
    int fd = open("/dev/gpiochip0", O_RDWR);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open gpiochip0: %s", strerror(errno));
        return -1;
    }

    if (ioctl(fd, GPIO_GET_LINE consumer, &pin) < 0) {
        syslog(LOG_ERR, "Failed to get GPIO line %u: %s", pin, strerror(errno));
        close(fd);
        return -1;
    }

    if (ioctl(fd, GPIO_request_output, consumer) < 0) {
        syslog(LOG_ERR, "Failed to request GPIO line %u as output: %s", pin, strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

static int gpio_set_value(int fd, unsigned int pin, int value) {
    if (pin > 31) {
        syslog(LOG_ERR, "Invalid GPIO pin %u", pin);
        return -1;
    }

    if (ioctl(fd, GPIO_SET_VALUE, pin, value) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO line %u to %d: %s", pin, value, strerror(errno));
        return -1;
    }

    return 0;
}

static void log_event(int priority, const char *message) {
    syslog(priority, "%s", message);
}

static void log_warning(const char *message) {
    syslog(LOG_WARNING, "%s", message);
}

static void log_shutdown_event(const char *message) {
    syslog(LOG_INFO, "%s", message);
}

int main(void) {
    openlog("motion_detector", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to register SIGINT handler: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to register SIGTERM handler: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    int relay_fd = gpio_request_line(RELAY_PIN, "door-strike-relay");
    if (relay_fd < 0) {
        closelog();
        return EXIT_FAILURE;
    }

    int pir_fd = gpio_request_line(PIR_PIN, "pir-sensor");
    if (pir_fd < 0) {
        log_event(LOG_ERR, "Failed to request PIR sensor line.");
        log_shutdown_event("Failed to request PIR sensor line.");
        gpio_set_value(relay_fd, RELAY_PIN, 0);
        close(relay_fd);
        closelog();
        return EXIT_FAILURE;
    }

    log_event(LOG_INFO, "Motion detector started.");

    time_t last_motion_time = 0;
    int relay_active = 0;

    while (program_running) {
        int pir_value = gpio_get_value(pir_fd, PIR_PIN);
        if (pir_value < 0) {
            log_event(LOG_ERR, "Failed to read PIR sensor.");
            usleep(POLL_INTERVAL_MS * 1000);
            continue;
        }

        if (pir_value == 1) {
            time_t now = time(NULL);
            if (last_motion_time == 0 || difftime(now, last_motion_time) > FAILSAFE_TIMEOUT_S) {
                log_event(LOG_WARNING, "PIR sensor HIGH for >10s. Possible malfunction.");
                log_shutdown_event("PIR sensor HIGH for >10s. Possible malfunction.");
                relay_active = 0;
            }

            if (!relay_active) {
                if (gpio_set_value(relay_fd, RELAY_PIN, 1) == 0) {
                    relay_active = 1;
                    log_event(LOG_INFO, "Relay activated.");
                } else {
                    log_event(LOG_ERR, "Failed to activate relay.");
                }
            }

            last_motion_time = now;
        } else {
            if (relay_active) {
                if (gpio_set_value(relay_fd, RELAY_PIN, 0) == 0) {
                    relay_active = 0;
                    log_event(LOG_INFO, "Relay deactivated.");
                } else {
                    log_event(LOG_ERR, "Failed to deactivate relay.");
                }
            }
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    log_event(LOG_INFO, "Motion detector shutting down.");
    log_shutdown_event("Motion detector shutting down.");

    gpio_set_value(relay_fd, RELAY_PIN, 0);
    close(relay_fd);
    close(pir_fd);
    closelog();

    return EXIT_SUCCESS;
}

