#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22
#define TIMER_ID 0
#define TIMER_INTERVAL 60
#define RELAY_ACTIVE_TIME 300
#define PAUSE_TIME 60
#define NUM_RELAYS 4

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t timer_fired = 0;

static const int relay_pins[NUM_RELAYS] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};

static void log_message(int priority, const char *message) {
    syslog(priority, "%s", message);
}

static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpioSetMode(relay_pins[i], PI_OUTPUT) != 0) {
            char msg[128];
            snprintf(msg, sizeof(msg), "Failed to set GPIO %d as output", relay_pins[i]);
            log_message(LOG_ERR, msg);
            gpioTerminate();
            return -1;
        }
        if (gpioWrite(relay_pins[i], 1) != 0) {
            char msg[128];
            snprintf(msg, sizeof(msg), "Failed to write HIGH to GPIO %d", relay_pins[i]);
            log_message(LOG_ERR, msg);
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

static void deactivate_all_relays(void) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpioWrite(relay_pins[i], 1);
    }
}

static void activate_relay(int relay_pin) {
    if (gpioWrite(relay_pin, 0) != 0) {
        log_message(LOG_ERR, "Failed to write LOW to relay pin");
        return;
    }
    log_message(LOG_INFO, "Relay on GPIO %d activated", relay_pin);
}

static void deactivate_relay(int relay_pin) {
    if (gpioWrite(relay_pin, 1) != 0) {
        log_message(LOG_ERR, "Failed to write HIGH to relay pin");
        return;
    }
    log_message(LOG_INFO, "Relay on GPIO %d deactivated", relay_pin);
}

static void irrigation_cycle(void) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (!running) break;

        log_message(LOG_INFO, "Starting irrigation cycle for relay %d", i + 1);

        activate_relay(relay_pins[i]);
        timer_fired = 1;

        for (int elapsed = 0; elapsed < RELAY_ACTIVE_TIME && running; elapsed += 5) {
            gpioDelay(5000000);
        }

        if (!running) break;

        deactivate_relay(relay_pins[i]);
        log_message(LOG_INFO, "Irrigation cycle for relay %d complete", i + 1);

        if (i < NUM_RELAYS - 1) {
            for (int pause = 0; pause < PAUSE_TIME && running; pause += 5) {
                gpioDelay(5000000);
            }
        }
    }
}

int main(void) {
    openlog("irrigation_system", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        log_message(LOG_ERR, "Failed to register signal handler");
        closelog();
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        closelog();
        return EXIT_FAILURE;
    }

    log_message(LOG_INFO, "Irrigation system started");

    while (running) {
        if (timer_fired) {
            irrigation_cycle();
            timer_fired = 0;
        }
        gpioDelay(1000000);
    }

    deactivate_all_relays();
    gpioTerminate();
    log_message(LOG_INFO, "Irrigation system stopped");
    closelog();
    return EXIT_SUCCESS;
}

