#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define I2C_BUS        "/dev/i2c-1"
#define MPU6050_ADDR   0x68
#define MPU6050_PWR_MGMT_1 0x6B
#define MPU6050_ACCEL_XOUT_H 0x3B
#define SAMPLE_RATE_HZ 100
#define BUFFER_SIZE 100
#define SAMPLE_PERIOD_NS (1000000000L / SAMPLE_RATE_HZ)

typedef struct {
    int16_t x, y, z;
} accel_sample_t;

typedef struct {
    accel_sample_t *buf;
    int head;
    int tail;
    int count;
    int fd;
} circular_buffer_t;

static volatile sig_atomic_t g_running = 1;
static circular_buffer_t g_buf;
static int g_fd = -1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *dst, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, dst, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int mpu6050_init(int fd) {
    if (i2c_write_byte(fd, MPU6050_PWR_MGMT_1, 0x00) < 0) return -1;
    usleep(100000);
    if (i2c_write_byte(fd, MPU6050_PWR_MGMT_1, 0x01) < 0) return -1;
    usleep(100000);
    return 0;
}

static int read_accel(int fd, accel_sample_t *out) {
    uint8_t buf[6];
    if (i2c_read_burst(fd, MPU6050_ACCEL_XOUT_H, buf, 6) < 0) return -1;
    out->x = (int16_t)((buf[0] << 8) | buf[1]);
    out->y = (int16_t)((buf[2] << 8) | buf[3]);
    out->z = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

static void cb_add(circular_buffer_t *cb, accel_sample_t s) {
    cb->buf[cb->head] = s;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count == BUFFER_SIZE) cb->tail = (cb->tail + 1) % BUFFER_SIZE;
    else cb->count++;
}

static int cb_get_latest(const circular_buffer_t *cb, accel_sample_t *out) {
    if (cb->count == 0) return -1;
    int idx = (cb->tail + BUFFER_SIZE - 1) % BUFFER_SIZE;
    *out = cb->buf[idx];
    return 0;
}

static int write_to_file(const char *path, const char *data) {
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", path, strerror(errno));
        return -1;
    }
    ssize_t n = write(fd, data, strlen(data));
    if (n < 0) {
        fprintf(stderr, "write(%s) failed: %s\n", path, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    g_fd = open(I2C_BUS, O_RDWR);
    if (g_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(g_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n", MPU6050_ADDR, strerror(errno));
        close(g_fd);
        return 1;
    }

    if (mpu6050_init(g_fd) < 0) {
        fprintf(stderr, "MPU6050 not detected or init failed.\n");
        close(g_fd);
        return 1;
    }

    memset(&g_buf, 0, sizeof(g_buf));
    g_buf.fd = g_fd;
    g_buf.head = 0;
    g_buf.tail = 0;
    g_buf.count = 0;

    struct sigevent sev;
    memset(&sev, 0, sizeof(sev));
    sev.sigev_notify = SIGEV_SIGNAL;
    sev.sigev_signo = SIGRTMIN;
    sev.sigev_value.sival_ptr = (void *)&g_buf;

    struct sigaction sa2;
    memset(&sa2, 0, sizeof(sa2));
    sa2.sa_handler = sig_handler;
    sa2.sa_flags = 0;
    if (sigaction(SIGRTMIN + 1, &sa2, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGRTMIN+1) failed: %s\n", strerror(errno));
        close(g_fd);
        return 1;
    }

    struct itimerspec its;
    memset(&its, 0, sizeof(its));
    its.it_interval.tv_sec = 0;
    its.it_interval.tv_nsec = SAMPLE_PERIOD_NS;
    its.it_value.tv_sec = 0;
    its.it_value.tv_nsec = SAMPLE_PERIOD_NS;

    if (timer_create(CLOCK_MONOTONIC, &sev, &its) < 0) {
        fprintf(stderr, "timer_create failed: %s\n", strerror(errno));
        close(g_fd);
        return 1;
    }

    while (g_running) {
        accel_sample_t sample;
        if (read_accel(g_fd, &sample) < 0) {
            fprintf(stderr, "Read error, continuing.\n");
            continue;
        }
        cb_add(&g_buf, sample);
        if (write_to_file("/sys/kernel/mpu6050_accel/latest", "1234567890") < 0) {
            fprintf(stderr, "File write failed.\n");
        }
        struct timespec rem;
        while (nanosleep(&its.it_value, &rem) == -1 && errno == EINTR && g_running) {
            if (rem.tv_sec > 0) rem.tv_sec = 0;
            if (rem.tv_nsec > 0) rem.tv_nsec = 0;
        }
    }

    timer_delete(g_fd);
    close(g_fd);
    return 0;
}

