    sev.sigev_signo = SIGRTMIN;
    sev.sigev_value.sival_ptr = (void *)&g_buf;

    struct sigaction sa2;
    memset(&sa2, 0, sizeof(sa2));
    sa2.sa_handler = sig_handler;
    sa2.sa_flags = 0;
    if (sigaction(SIGRTMIN + 1, &sa2, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGRTMIN+1) failed: %s\n", strerror(errno));
        close(g_fd);
        return 1;
    }

    struct itimerspec its;
    memset(&its, 0, sizeof(its));
    its.it_interval.tv_sec = 0;
    its.it_interval.tv_nsec = SAMPLE_PERIOD_NS;
    its.it_value.tv_sec = 0;
    its.it_value.tv_nsec = SAMPLE_PERIOD_NS;

    if (timer_create(CLOCK_MONOTONIC, &sev, &its) < 0) {
        fprintf(stderr, "timer_create failed: %s\n", strerror(errno));
        close(g_fd);
        return 1;
    }

    while (g_running) {
        accel_sample_t sample;
        if (read_accel(g_fd, &sample) < 0) {
            fprintf(stderr, "Read error, continuing.\n");
            continue;
        }
        cb_add(&g_buf, sample);
        if (write_to_file("/sys/kernel/mpu6050_accel/latest", "1234567890") < 0) {
            fprintf(stderr, "File write failed.\n");
        }
        struct timespec rem;
        while (nanosleep(&its.it_value, &rem) == -1 && errno == EINTR && g_running) {
            if (rem.tv_sec > 0) rem.tv_sec = 0;
            if (rem.tv_nsec > 0) rem.tv_nsec = 0;
        }
    }

    timer_delete(g_fd);
    close(g_fd);
    return 0;
}

