#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <unistd.h>
#include <gpiod.h>

#define RELAY1_PIN 18
#define RELAY2_PIN 23
#define RELAY3_PIN 24
#define RELAY4_PIN 25

#define INTERVAL_1 2
#define INTERVAL_2 3
#define INTERVAL_3 5
#define INTERVAL_4 7

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_relay(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting relay value: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int toggle_relay(struct gpiod_line *line) {
    int ret = set_relay(line, 1);
    if (ret < 0) return -1;
    sleep(1);
    ret = set_relay(line, 0);
    if (ret < 0) return -1;
    sleep(1);
    return 0;
}

static void cleanup(struct gpiod_chip *chip, struct gpiod_line *lines[]) {
    for (int i = 0; i < 4; i++) {
        if (lines[i]) {
            gpiod_line_set_value(lines[i], 0);
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) gpiod_chip_close(chip);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    struct gpiod_line *lines[4];
    int pins[4] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (int i = 0; i < 4; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Error getting GPIO line %d: %s\n", pins[i], strerror(errno));
            cleanup(chip, lines);
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < 4; i++) {
        if (gpiod_line_request_output(lines[i], "relay-toggle", 0) < 0) {
            fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", pins[i], strerror(errno));
            cleanup(chip, lines);
            return EXIT_FAILURE;
        }
    }

    struct timespec start, now;
    clock_gettime(CLOCK_MONOTONIC, &start);

    while (running) {
        for (int i = 0; i < 4; i++) {
            if (!running) break;
            if (toggle_relay(lines[i]) < 0) {
                fprintf(stderr, "Error toggling relay %d\n", i + 1);
                cleanup(chip, lines);
                return EXIT_FAILURE;
            }
        }

        clock_gettime(CLOCK_MONOTONIC, &now);
        double elapsed = (now.tv_sec - start.tv_sec) + (now.tv_nsec - start.tv_nsec) / 1e9;
        if (elapsed >= (double)INTERVALS[i]) {
            start = now;
        }
    }

    cleanup(chip, lines);
    return EXIT_SUCCESS;
}

