#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define BUFFER_SIZE 100
#define THRESHOLD 50.0f

typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

typedef struct {
    gyro_data_t data[BUFFER_SIZE];
    int head;
    int tail;
    int count;
} circular_buffer_t;

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write error (reg 0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write reg error: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int init_mpu6050(int fd) {
    if (i2c_write_byte(fd, 0x6B, 0x00) < 0) return -1;
    usleep(100000);
    if (i2c_write_byte(fd, 0x1F, 0x00) < 0) return -1;
    if (i2c_write_byte(fd, 0x1D, 0x00) < 0) return -1;
    if (i2c_write_byte(fd, 0x1E, 0x00) < 0) return -1;
    if (i2c_write_byte(fd, 0x19, 0x01) < 0) return -1;
    if (i2c_write_byte(fd, 0x1A, 0x0F) < 0) return -1;
    if (i2c_write_byte(fd, 0x1B, 0x00) < 0) return -1;
    if (i2c_write_byte(fd, 0x37, 0x00) < 0) return -1;
    if (i2c_write_byte(fd, 0x35, 0x00) < 0) return -1;
    if (i2c_write_byte(fd, 0x36, 0x00) < 0) return -1;
    if (i2c_write_byte(fd, 0x14, 0x08) < 0) return -1;
    if (i2c_write_byte(fd, 0x1F, 0x08) < 0) return -1;
    if (i2c_write_byte(fd, 0x1D, 0x00) < 0) return -1;
    if (i2c_write_byte(fd, 0x1E, 0x00) < 0) return -1;
    if (i2c_write_byte(fd, 0x19, 0x01) < 0) return -1;
    if (i2c_write_byte(fd, 0x1A, 0x0F) < 0) return -1;
    if (i2c_write_byte(fd, 0x1B, 0x00) < 0) return -1;
    if (i2c_write_byte(fd, 0x37, 0x00) < 0) return -1;
    if (i2c_write_byte(fd, 0x35, 0x00) < 0) return -1;
    if (i2c_write_byte(fd, 0x36, 0x00) < 0) return -1;
    return 0;
}

int read_gyro_data(int fd, gyro_data_t *data) {
    uint8_t buf[6];
    if (i2c_read_burst(fd, 0x43, buf, 6) < 0) return -1;
    int16_t raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_y = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t raw_z = (int16_t)((buf[4] << 8) | buf[5]);
    data->x = (float)raw_x / 131.0f;
    data->y = (float)raw_y / 131.0f;
    data->z = (float)raw_z / 131.0f;
    return 0;
}

void add_to_buffer(circular_buffer_t *buf, gyro_data_t data) {
    buf->data[buf->head] = data;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count < BUFFER_SIZE) buf->count++;
    if (buf->count == BUFFER_SIZE) buf->tail = (buf->tail + 1) % BUFFER_SIZE;
}

float calculate_magnitude(gyro_data_t data) {
    return sqrtf(data.x * data.x + data.y * data.y + data.z * data.z);
}

void check_threshold(gyro_data_t data, float threshold) {
    if (calculate_magnitude(data) > threshold) {
        printf("Threshold exceeded! Magnitude: %.2f\n", calculate_magnitude(data));
    }
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (init_mpu6050(i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize MPU6050\n");
        close(i2c_fd);
        return 1;
    }

    circular_buffer_t gyro_buffer;
    gyro_buffer.head = 0;
    gyro_buffer.tail = 0;
    gyro_buffer.count = 0;

    printf("Gyroscope data acquisition started. Press Ctrl+C to exit.\n");

    while (running) {
        gyro_data_t gyro_data;
        if (read_gyro_data(i2c_fd, &gyro_data) < 0) {
            fprintf(stderr, "Failed to read gyro data. Retrying...\n");
            usleep(100000);
            continue;
        }

        add_to_buffer(&gyro_buffer, gyro_data);
        check_threshold(gyro_data, THRESHOLD);

        usleep(10000);
    }

    printf("\nExiting gracefully...\n");
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

