/*
 * co2_monitor.c — MH-Z19B CO2 monitor for Raspberry Pi 3 Model B+
 *
 * Reads CO2 concentration from an MH-Z19B sensor over UART via the
 * the_hardware_driver library (the driver), logs readings to
 * co2_log.json, and reports errors to co2_error.log.
 *
 * Wiring:
 *   MH-Z19B TX  -> Pi RXD  (GPIO15, BCM 15)
 *   MH-Z19B RX  -> Pi TXD  (GPIO14, BCM 14)
 *   MH-Z19B VCC -> 3.3 V
 *   MH-Z19B GND -> GND
 *
 * Build:
 *   gcc -Wall -Wextra -o co2_monitor co2_monitor.c \
 *       -lthe_driver -lrt
 *
 * Run:
 *   ./co2_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <termios.h>
#include <the_driver.h>

#define UART_DEVICE      "/dev/serial0"
#define BAUD_RATE        B9600
#define LOG_FILE         "co2_log.json"
#define ERROR_LOG_FILE   "co2_error.log"
#define READ_INTERVAL_S  5
#define RESPONSE_LEN     9
#define MAX_RETRIES      10
#define RETRY_DELAY_S    1
#define SAMPLE_TIMEOUT_S 1

/* MH-Z19B 9-byte response format (big-endian, 2's complement) */
static const uint8_t MH_Z19B_CMD[] = { 0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09 };

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper (microseconds)                                     */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        snprintf(buf, len, "1970-01-01T00:00:00.000000");
        return;
    }
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    snprintf(buf, len, "%04d-%02d-%02dT%02d:%02d:%02d.%06ld",
             tm_info.tm_year + 1900, tm_info.tm_mon + 1, tm_info.tm_mday,
             tm_info.tm_hour, tm_info.tm_min, tm_info.tm_sec,
             ts.tv_nsec / 1000);
}

/* ------------------------------------------------------------------ */
/* Error logging                                                        */
/* ------------------------------------------------------------------ */
static void log_error(const char *msg)
{
    char ts[40];
    get_timestamp(ts, sizeof(ts));

    FILE *fp = fopen(ERROR_LOG_FILE, "a");
    if (fp) {
        fprintf(fp, "%s: %s\n", ts, msg);
        fclose(fp);
    }
    fprintf(stderr, "%s: %s\n", ts, msg);
}

/* ------------------------------------------------------------------ */
/* UART setup                                                          */
/* ------------------------------------------------------------------ */
static int uart_setup(const char *device)
{
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) {
        log_error("Failed to open UART device");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        log_error("tcgetattr failed");
        close(fd);
        return -1;
    }

    cfsetispeed(&tty, BAUD_RATE);
    cfsetospeed(&tty, BAUD_RATE);

    tty.c_cflag = CS8 | CLOCAL | CREAD;
    tty.c_iflag = IGNPAR;
    tty.c_oflag = 0;
    tty.c_lflag = 0;
    tty.c_cc[VMIN]  = 0;
    tty.c_cc[VTIME] = 0;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        log_error("tcsetattr failed");
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

/* ------------------------------------------------------------------ */
/* Read exactly n bytes from the UART with retry logic                 */
/* ------------------------------------------------------------------ */
static int uart_read_exact(int fd, uint8_t *buf, size_t n)
{
    size_t total = 0;
    while (total < n) {
        ssize_t r = read(fd, buf + total, n - total);
        if (r < 0) {
            if (errno == EINTR) continue;
            log_error("UART read error");
            return -1;
        }
        if (r == 0) {
            log_error("UART read returned 0 (device disconnected?)");
            return -1;
        }
        total += (size_t)r;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Send the 9-byte command sequence                                      */
/* ------------------------------------------------------------------ */
static int send_command(int fd)
{
    size_t written = 0;
    while (written < sizeof(MH_Z19B_CMD)) {
        ssize_t r = write(fd, MH_Z19B_CMD + written, sizeof(MH_Z19B_CMD) - written);
        if (r < 0) {
            if (errno == EINTR) continue;
            log_error("UART write error");
            return -1;
        }
        if (r == 0) {
            log_error("UART write returned 0 (device disconnected?)");
            return -1;
        }
        written += (size_t)r;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Parse the 9-byte response                                            */
/* ------------------------------------------------------------------ */
static int parse_response(const uint8_t *buf, int16_t *co2_ppm, int *error)
{
    if (buf[0] != 0x01 || buf[1] != 0x02 || buf[2] != 0x03 ||
        buf[3] != 0x04 || buf[4] != 0x05 || buf[5] != 0x06 ||
        buf[6] != 0x07 || buf[7] != 0x08 || buf[8] != 0x09) {
        *error = 1;
        return -1;
    }

    uint16_t raw = ((uint16_t)buf[3] << 8) | buf[2];
    *co2_ppm = (int16_t)raw;
    *error = 0;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one CO2 sample                                                  */
/* ------------------------------------------------------------------ */
static int read_co2(int fd, int16_t *co2_ppm, int *error)
{
    uint8_t buf[RESPONSE_LEN];
    int retries = 0;

    while (retries < MAX_RETRIES && g_running) {
        if (send_command(fd) != 0) {
            retries++;
            if (retries < MAX_RETRIES) sleep(RETRY_DELAY_S);
            continue;
        }

        /* Wait for the sensor to respond (max ~1 s) */
        for (int i = 0; i < SAMPLE_TIMEOUT_S && g_running; i++) {
            uint8_t c;
            ssize_t r = read(fd, &c, 1);
            if (r < 0) {
                if (errno == EINTR) continue;
                log_error("UART read error during response wait");
                return -1;
            }
            if (r == 0) {
                log_error("UART read returned 0 during response wait");
                return -1;
            }
            if (c == 0x01) break;
        }

        if (retries < MAX_RETRIES) {
            if (uart_read_exact(fd, buf, RESPONSE_LEN) != 0) {
                retries++;
                if (retries < MAX_RETRIES) sleep(RETRY_DELAY_S);
                continue;
            }
        }

        if (parse_response(buf, co2_ppm, error) == 0) {
            return 0;
        }

        retries++;
        if (retries < MAX_RETRIES) sleep(RETRY_DELAY_S);
    }

    *error = 1;
    return -1;
}

/* ------------------------------------------------------------------ */
/* Log a reading to JSON                                                */
/* ------------------------------------------------------------------ */
static int log_co2(int16_t co2_ppm, int error)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        log_error("Failed to open log file");
        return -1;
    }

    char ts[40];
    get_timestamp(ts, sizeof(ts));

    fprintf(fp, "{\"timestamp\":\"%s\",\"co2_ppm\":%d,\"error\":%d}\n",
            ts, co2_ppm, error);
    fclose(fp);
    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int uart_fd = uart_setup(UART_DEVICE);
    if (uart_fd < 0) {
        return EXIT_FAILURE;
    }

    printf("CO2 monitoring started on %s. Press Ctrl+C to exit.\n", UART_DEVICE);

    while (g_running) {
        int16_t co2_ppm = 0;
        int error = 0;

        if (read_co2(uart_fd, &co2_ppm, &error) == 0) {
            if (log_co2(co2_ppm, error) != 0) {
                log_error("Failed to log CO2 reading");
            }
            printf("{\"timestamp\":\"%s\",\"co2_ppm\":%d,\"error\":%d}\n",
                   "now", co2_ppm, error);
        } else {
            log_error("Failed to read CO2 data");
        }

        if (g_running) sleep(READ_INTERVAL_S);
    }

    /* Clean shutdown */
    close(uart_fd);
    printf("\nCO2 monitoring stopped.\n");
    return EXIT_SUCCESS;
}

