#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define I2C_BUS        1
#define HMC5883L_ADDR  0x03
#define GPIO_PIN       17
#define BUFFER_SIZE    100
#define TARGET_HEADING 90.0
#define DEVIATION_THRESHOLD 10.0
#define SAMPLE_DELAY_US 100000

/* HMC5883L registers */
#define HMC5883L_CONFIG_A   0x00
#define HMC5883L_CONFIG_B   0x01
#define HMC5883L_MODE       0x02
#define HMC5883L_DATA_X_MSB 0x03
#define HMC5883L_DATA_X_LSB 0x04
#define HMC5883L_DATA_Y_MSB 0x05
#define HMC5883L_DATA_Y_LSB 0x06
#define HMC5883L_DATA_Z_MSB 0x07
#define HMC5883L_DATA_Z_LSB 0x08

#define X_OFFSET 100
#define Y_OFFSET (-50)

typedef struct {
    float heading;
    int   index;
} HeadingData;

static HeadingData circular_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_hmc5883l(void) {
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_A, 0x70) < 0) {
        fprintf(stderr, "Error writing config register A\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_B, 0x20) < 0) {
        fprintf(stderr, "Error writing config register B\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, HMC5883L_MODE, 0x00) < 0) {
        fprintf(stderr, "Error writing mode register\n");
        return -1;
    }
    return 0;
}

static int read_magnetometer(float *x, float *y, float *z) {
    char data[6];
    if (i2cReadI2CBlockData(i2c_handle, HMC5883L_DATA_X_MSB, data, 6) != 6) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }
    int16_t raw_x = (int16_t)((data[0] << 8) | data[1]);
    int16_t raw_y = (int16_t)((data[2] << 8) | data[3]);
    int16_t raw_z = (int16_t)((data[4] << 8) | data[5]);
    *x = (float)raw_x * 0.796f - X_OFFSET;
    *y = (float)raw_y * 0.796f - Y_OFFSET;
    *z = (float)raw_z * 0.796f;
    return 0;
}

static float calculate_heading(float x, float y) {
    float heading = atan2f(y, x) * 180.0f / M_PI;
    if (heading < 0.0f) {
        heading += 360.0f;
    }
    return heading;
}

static void add_to_buffer(float heading) {
    circular_buffer[buffer_index].heading = heading;
    circular_buffer[buffer_index].index = buffer_index;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
}

static bool heading_within_threshold(float heading) {
    float deviation = fabsf(heading - TARGET_HEADING);
    return deviation < DEVIATION_THRESHOLD;
}

static void control_output(bool heading_within_threshold) {
    gpioWrite(GPIO_PIN, heading_within_threshold ? 1 : 0);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, HMC5883L_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (initialize_hmc5883l() < 0) {
        fprintf(stderr, "HMC5883L initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float x, y, z, heading;
    while (running) {
        if (read_magnetometer(&x, &y, &z) == 0) {
            heading = calculate_heading(x, y);
            add_to_buffer(heading);
            bool within = heading_within_threshold(heading);
            control_output(within);
            printf("Heading: %.2f degrees\n", heading);
        } else {
            fprintf(stderr, "Error reading magnetometer data. Retrying...\n");
            gpioWrite(GPIO_PIN, 0);
        }
        gpioDelay(SAMPLE_DELAY_US);
    }

    gpioWrite(GPIO_PIN, 0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    printf("\nProgram terminated gracefully.\n");
    return EXIT_SUCCESS;
}

