#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define BH1750_ADDR 0x38
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "lighting_log.txt"
#define RED_PIN 17
#define GREEN_PIN 27
#define BLUE_PIN 22
#define CONVERSION_DELAY_MS 120
#define POLL_INTERVAL_S 1

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *red_line = NULL;
static struct gpiod_line *green_line = NULL;
static struct gpiod_line *blue_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int bh1750_read_lux(int fd, float *lux_out) {
    uint8_t cmd = 0x10;
    if (write(fd, &cmd, 1) != 1) {
        return -1;
    }
    usleep(CONVERSION_DELAY_MS * 1000);
    uint8_t buf[2];
    ssize_t n = read(fd, buf, 2);
    if (n != 2) {
        return -1;
    }
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static void log_data(FILE *fp, float lux, int red, int green, int blue) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        return;
    }
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%d,%d,%d\n", ts, lux, red, green, blue);
    fflush(fp);
}

static void cleanup(void) {
    if (red_line) gpiod_line_release(red_line);
    if (green_line) gpiod_line_release(green_line);
    if (blue_line) gpiod_line_release(blue_line);
    if (chip) gpiod_chip_close(chip);
    if (i2c_fd >= 0) close(i2c_fd);
    if (log_fp) fclose(log_fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open I2C bus");
        return EXIT_FAILURE;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        cleanup();
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        cleanup();
        return EXIT_FAILURE;
    }
    red_line = gpiod_chip_get_line(chip, RED_PIN);
    green_line = gpiod_chip_get_line(chip, GREEN_PIN);
    blue_line = gpiod_chip_get_line(chip, BLUE_PIN);
    if (!red_line || !green_line || !blue_line) {
        perror("gpiod_chip_get_line");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(red_line, "rgb_lamp", 0) < 0 ||
        gpiod_line_request_output(green_line, "rgb_lamp", 0) < 0 ||
        gpiod_line_request_output(blue_line, "rgb_lamp", 0) < 0) {
        perror("gpiod_line_request_output");
        cleanup();
        return EXIT_FAILURE;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen log");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Starting RGB lamp control. Press Ctrl+C to exit.\n");

    while (running) {
        float lux;
        if (bh1750_read_lux(i2c_fd, &lux) < 0) {
            fprintf(stderr, "BH1750 read error\n");
            log_data(log_fp, -1.0f, 0, 0, 0);
        } else {
            int red = (lux < 50.0f) ? 1 : 0;
            int green = (lux < 150.0f) ? 1 : 0;
            int blue = (lux < 300.0f) ? 1 : 0;
            gpiod_line_set_value(red_line, red);
            gpiod_line_set_value(green_line, green);
            gpiod_line_set_value(blue_line, blue);
            log_data(log_fp, lux, red, green, blue);
        }
        sleep(POLL_INTERVAL_S);
    }

    printf("\nShutting down...\n");
    gpiod_line_set_value(red_line, 0);
    gpiod_line_set_value(green_line, 0);
    gpiod_line_set_value(blue_line, 0);
    cleanup();
    return EXIT_SUCCESS;
}

