#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23

#define PWM_FREQUENCY 1000
#define PWM_RANGE 255

#define DISTANCE_A 50
#define DISTANCE_B 50

#define LOOP_DELAY_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_motor_speed(int in1, int in2, int speed) {
    if (gpioWrite(in1, speed > 0 ? 1 : 0) < 0) {
        fprintf(stderr, "Error: gpioWrite failed on pin %d\n", in1);
        return -1;
    }
    if (gpioPWM(in2, speed) < 0) {
        fprintf(stderr, "Error: gpioPWM failed on pin %d\n", in2);
        return -1;
    }
    return 0;
}

static int set_motor_speed_b(int in3, int in4, int speed) {
    if (gpioWrite(in3, speed > 0 ? 1 : 0) < 0) {
        fprintf(stderr, "Error: gpioWrite failed on pin %d\n", in3);
        return -1;
    }
    if (gpioPWM(in4, speed) < 0) {
        fprintf(stderr, "Error: gpioPWM failed on pin %d\n", in4);
        return -1;
    }
    return 0;
}

static int control_motor(int in1, int in2, int distance, int *speed) {
    if (distance < DISTANCE_A) {
        *speed = 255;
    } else if (distance > DISTANCE_A + 10) {
        *speed = 0;
    } else {
        *speed = (int)(((float)(distance - DISTANCE_A) / 10.0f) * 255.0f);
    }
    return set_motor_speed(in1, in2, *speed);
}

static int control_motor_b(int in3, int in4, int distance, int *speed) {
    if (distance < DISTANCE_B) {
