#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_RELAYS 4
#define FADE_DURATION 1800   /* seconds (30 minutes) */
#define PWM_FREQUENCY 100    /* Hz */
#define PWM_RANGE 100        /* duty-cycle range 0-100 */

static const int relay_pins[NUM_RELAYS] = {4, 17, 27, 22};
static const char *schedule_file = "lighting_schedule.txt";

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpioSetMode(relay_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO%d as output\n", relay_pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioSetPWMfrequency(relay_pins[i], PWM_FREQUENCY) < 0) {
            fprintf(stderr, "Failed to set PWM frequency on GPIO%d\n", relay_pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioSetPWMrange(relay_pins[i], PWM_RANGE) != 0) {
            fprintf(stderr, "Failed to set PWM range on GPIO%d\n", relay_pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioPWM(relay_pins[i], 0) != 0) {
            fprintf(stderr, "Failed to initialise PWM on GPIO%d\n", relay_pins[i]);
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

static void cleanup_gpio(void)
{
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpioWrite(relay_pins[i], 0);
        gpioPWM(relay_pins[i], 0);
    }
    gpioTerminate();
}

static int read_schedule(const char *filename, int *relay_numbers, int *on_off)
{
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening schedule file '%s': %s\n", filename, strerror(errno));
        return -1;
    }

    char line[256];
    int line_num = 0;
    int prev_relay = -1;
    int prev_state = -1;

    while (fgets(line, sizeof(line), fp) != NULL) {
        line_num++;

        /* Strip trailing newline */
        size_t len = strlen(line);
        if (len > 0 && line[len-1] == '\n') {
            line[len-1] = '\0';
        }

        /* Parse HH:MM:SS,relay_number,on/off */
        char time_str[32];
        char relay_str[16];
        char on_off_str[8];

        if (sscanf(line, "%31[^:]:%5[^:]:%5[^:],%15s,%15s",
                   time_str, relay_str, on_off_str) == 4) {
            time_t t = time(NULL);
            struct tm tm;
