/*
 * Theremin for Raspberry Pi Zero W
 * HC-SR04 ultrasonic distance sensor -> PWM buzzer frequency
 *
 * Wiring:
 *   HC-SR04 TRIG -> GPIO23 (BCM)
 *   HC-SR04 ECHO -> GPIO24 (BCM)
 *   PWM buzzer   -> GPIO18 (BCM)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o theremin theremin.c -lpigpio -lrt
 *   (run as root or with gpio group access)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      23
#define ECHO_PIN         24
#define BUZZER_PIN       18

#define SPEED_OF_SOUND   34300.0   /* cm/s at ~20 °C */
#define MIN_DISTANCE_CM  2.0
#define MAX_DISTANCE_CM  400.0
#define MIN_FREQUENCY    20
#define MAX_FREQUENCY    2000
#define LOOP_DELAY_US    20000     /* 50 Hz */
#define MEASURE_DELAY_US 60000     /* 60 ms min between readings */
#define ECHO_TIMEOUT_US  30000     /* 30 ms max echo wait */
#define TRIGGER_PULSE_US 10

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Measure distance in cm. Returns -1.0 on timeout or sensor-absent.
 */
static double measure_distance(void)
{
    uint32_t start_tick, end_tick, timeout_tick;

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) failed\n");
        return -1.0;
    }
    gpioDelay(5);

    /* 10 µs trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 1) failed\n");
        return -1.0;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) failed\n");
        return -1.0;
    }

    /* Wait for echo rising edge (timeout if sensor absent) */
    timeout_tick = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: Echo start timeout (sensor absent?)\n");
            return -1.0;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge */
    timeout_tick = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: Echo end timeout\n");
            return -1.0;
        }
    }
    end_tick = gpioTick();

    double elapsed_us = (double)(end_tick - start_tick);
    double distance_cm = (elapsed_us * SPEED_OF_SOUND) / 2000000.0;

    /* Sanity range check */
    if (distance_cm < MIN_DISTANCE_CM || distance_cm > MAX_DISTANCE_CM) {
        fprintf(stderr, "Warning: distance %.2f cm out of range\n", distance_cm);
        return -1.0;
    }

    return distance_cm;
}

/*
 * Map distance to frequency, clamped to valid range.
 */
static int map_distance_to_frequency(double distance_cm)
{
    if (distance_cm < 0.0) {
        return 0;
    }

    double freq = (MAX_FREQUENCY - MIN_FREQUENCY) *
                  (1.0 - (distance_cm - MIN_DISTANCE_CM) /
                   (MAX_DISTANCE_CM - MIN_DISTANCE_CM));

    if (freq < MIN_FREQUENCY) freq = MIN_FREQUENCY;
    if (freq > MAX_FREQUENCY) freq = MAX_FREQUENCY;

    return (int)freq;
}

static void set_buzzer_frequency(int frequency)
{
    if (frequency < 0) {
        gpioPWM(BUZZER_PIN, 0);
        return;
    }

    if (gpioSetPWMfrequency(BUZZER_PIN, frequency) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency(%d) failed\n", frequency);
        return;
    }
    gpioPWM(BUZZER_PIN, 128); /* 50 % duty cycle */
}

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(TRIGGER) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(ECHO) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(BUZZER) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(100000); /* 100 ms settle */

    /* Install signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Theremin ready. Press Ctrl+C to exit.\n");

    while (g_running) {
        double distance = measure_distance();

        if (distance < 0.0) {
            fprintf(stderr, "Error: distance measurement failed\n");
        } else {
            int freq = map_distance_to_frequency(distance);
            set_buzzer_frequency(freq);
            printf("Distance: %.2f cm  Buzzer: %d Hz\n", distance, freq);
        }

        /* Enforce 60 ms minimum between readings */
        if (g_running) {
            gpioDelay(MEASURE_DELAY_US);
        }
    }

    /* Cleanup */
    gpioPWM(BUZZER_PIN, 0);
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
    printf("\nTheremin stopped.\n");
    return EXIT_SUCCESS;
}

