#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

#define PWM_FREQ  1000
#define PWM_RANGE 255

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo) {
    (void)signo;
    g_running = 0;
}

static int safe_set_mode(unsigned pin, unsigned mode) {
    if (gpioSetMode(pin, mode) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%u, %u) failed\n", pin, mode);
        return -1;
    }
    return 0;
}

static int safe_set_pwm(unsigned pin, unsigned range, unsigned freq) {
    if (gpioSetPWMfrequency(pin, freq) != freq) {
        fprintf(stderr, "Error: gpioSetPWMfrequency(%u, %u) failed\n", pin, freq);
        return -1;
    }
    if (gpioSetPWMrange(pin, range) != range) {
        fprintf(stderr, "Error: gpioSetPWMrange(%u, %u) failed\n", pin, range);
        return -1;
    }
    return 0;
}

static int safe_set_pwm_dutycycle(unsigned pin, unsigned duty) {
    if (gpioPWM(pin, duty) != 0) {
        fprintf(stderr, "Error: gpioPWM(%u, %u) failed\n", pin, duty);
        return -1;
    }
    return 0;
}

static int safe_pwm_off(unsigned pin) {
    if (gpioPWM(pin, 0) != 0) {
        fprintf(stderr, "Error: gpioPWM(%u, 0) failed\n", pin);
        return -1;
    }
    return 0;
}

static int safe_pwm_release(unsigned pin) {
    if (gpioPWM(pin, 0) != 0) {
        fprintf(stderr, "Error: gpioPWM(%u, 0) failed during release\n", pin);
        return -1;
    }
    return 0;
