#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MPU6050_ADDR   0x68
#define SAMPLE_MS      100
#define LOG_FILE       "gyro_log.txt"

/* MPU-6050 registers */
#define REG_PWR_MGMT_1 0x6B
#define REG_GYRO_XOUT_H 0x43
#define REG_WHO_AM_I    0x75

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int mpu6050_init(int fd)
{
    uint8_t who_am_i = 0;
    if (i2c_read_reg8(fd, REG_WHO_AM_I, &who_am_i) < 0)
        return -1;
    if (who_am_i != 0x68) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x68 (sensor absent?)\n", who_am_i);
        return -1;
    }
    if (i2c_write_reg8(fd, REG_PWR_MGMT_1, 0x00) < 0)
        return -1;
    return 0;
}

static int read_gyro(int fd, float *gx, float *gy, float *gz)
{
    uint8_t buf[6];
    if (read(fd, buf, 6) != 6) {
        fprintf(stderr, "Gyro read failed: %s\n", strerror(errno));
        return -1;
    }
    int16_t raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_y = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t raw_z = (int16_t)((buf[4] << 8) | buf[5]);
    *gx = (float)raw_x / 131.0f;
    *gy = (float)raw_y / 131.0f;
    *gz = (float)raw_z / 131.0f;
    return 0;
}

static void log_data(FILE *fp, float gx, float gy, float gz)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, gx, gy, gz);
    fflush(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    if (mpu6050_init(g_i2c_fd) < 0) {
        fprintf(stderr, "MPU-6050 initialization failed.\n");
        close(g_i2c_fd);
        return 1;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    printf("Logging MPU-6050 gyro data to %s (Ctrl+C to stop)...\n", LOG_FILE);

    while (g_running) {
        float gx, gy, gz;
        if (read_gyro(g_i2c_fd, &gx, &gy, &gz) == 0) {
            log_data(fp, gx, gy, gz);
        } else {
            fprintf(stderr, "Read error; continuing...\n");
        }
        usleep(SAMPLE_MS * 1000);
    }

    printf("\nShutting down...\n");
    fclose(fp);
    if (g_i2c_fd >= 0)
        close(g_i2c_fd);
    return 0;
}

