#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <stdbool.h>

#define BUTTON_PIN 17
#define BUZZER_PIN 18
#define DEBOUNCE_US 50000  /* 50 ms */
#define PWM_DUTY_50 500000  /* 50 % of 1,000,000 */

/* Musical note frequencies (Hz) — doorbell melody */
const int melody[] = {
    262, 294, 330, 349, 392, 440, 494, 523
};
const int melody_len = sizeof(melody) / sizeof(melody[0]);

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t button_pressed = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void button_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio;
    (void)level;
    (void)tick;
    (void)userdata;
    button_pressed = 1;
}

static int play_tone(int freq, int duration_ms) {
    if (freq <= 0) {
        fprintf(stderr, "Invalid frequency: %d\n", freq);
        return -1;
    }
    if (gpioSetPWMfrequency(BUZZER_PIN, freq) < 0) {
        fprintf(stderr, "Failed to set PWM frequency to %d Hz\n", freq);
        return -1;
    }
    if (gpioPWM(BUZZER_PIN, PWM_DUTY_50) < 0) {
        fprintf(stderr, "Failed to start PWM on buzzer\n");
        return -1;
    }
    gpioDelay(duration_ms * 1000);
    if (gpioPWM(BUZZER_PIN, 0) < 0) {
        fprintf(stderr, "Failed to stop PWM on buzzer\n");
        return -1;
    }
    return 0;
}

static void play_melody(void) {
    for (int i = 0; i < melody_len && running; i++) {
        if (button_pressed) {
            button_pressed = 0;
            if (gpioSetPWMfrequency(BUZZER_PIN, melody[i]) < 0) {
                fprintf(stderr, "Failed to set PWM frequency for note %d\n", melody[i]);
                return;
            }
            if (gpioPWM(BUZZER_PIN, PWM_DUTY_50) < 0) {
                fprintf(stderr, "Failed to start PWM for note %d\n", melody[i]);
                return;
            }
            gpioDelay(500);
            if (gpioPWM(BUZZER_PIN, 0) < 0) {
                fprintf(stderr, "Failed to stop PWM for note %d\n", melody[i]);
                return;
            }
            return;
        }
        if (play_tone(melody[i], 500) < 0) {
            fprintf(stderr, "Error playing tone %d\n", melody[i]);
            return;
        }
        gpioDelay(500);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(BUTTON_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set button pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up on button pin\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set buzzer pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(BUZZER_PIN, 1000000) < 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFuncEx(BUTTON_PIN, FALLING_EDGE, DEBOUNCE_US, button_isr, NULL) < 0) {
        fprintf(stderr, "Failed to set ISR for button pin\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Doorbell ready. Press the button (GPIO17) to play melody. Ctrl+C to exit.\n");

    while (running) {
        if (button_pressed) {
            button_pressed = 0;
            if (play_melody() == 0) {
                printf("Melody played.\n");
            } else {
                fprintf(stderr, "Melody playback interrupted.\n");
            }
        }
        gpioDelay(10000);  /* 10 ms poll interval */
    }

    gpioPWM(BUZZER_PIN, 0);
    gpioSetISRFuncEx(BUTTON_PIN, FALLING_EDGE, DEBOUNCE_US, NULL, NULL);
    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return EXIT_SUCCESS;
}

