#include <pigpio.h>

#define GPIO_PIN 17
#define WINDOW_SIZE 5
#define DEFAULT_POLL_TIMEOUT_MS 1000
#define LOG_FILE "vibration_events.log"

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }
    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", GPIO_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Warning: failed to set pull-down on GPIO%d.\n", GPIO_PIN);
    }
    return 0;
}

static int read_sensor(void) {
    int value = gpioRead(GPIO_PIN);
    if (value < 0) {
        fprintf(stderr, "Error: gpioRead failed on GPIO%d (rc=%d).\n", GPIO_PIN, value);
        return -1;
    }
    return value;
}

static void log_event(int value) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed.\n");
        return;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed.\n");
        return;
    }

    if (fprintf(log_file, "%s - Sensor Value: %d\n", timestamp, value) < 0) {
        fprintf(stderr, "Error: failed to write to log file: %s\n", strerror(errno));
        return;
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error: fflush failed: %s\n", strerror(errno));
    }
}

static void check_for_earthquake(void) {
    int count = 0;
    for (int i = 0; i < WINDOW_SIZE; i++) {
        count += (read_sensor() == 1) ? 1 : 0;
    }
    if (count >= 3) {
        printf("EARTHQUAKE ALERT!\n");
        fflush(stdout);
        log_event(1);
    }
}

int main(int argc, char *argv[]) {
    int poll_timeout_ms = DEFAULT_POLL_TIMEOUT_MS;

    if (argc > 1) {
        long val = strtol(argv[1], NULL, 10);
        if (val > 0) {
            poll_timeout_ms = (int)val;
        } else if (val < 0) {
            fprintf(stderr, "Error: invalid poll timeout value '%s'.\n", argv[1]);
            return EXIT_FAILURE;
        } else {
            fprintf(stderr, "Warning: poll timeout value is zero.\n");
        }
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction(SIGINT) failed: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction(SIGTERM) failed: %s\n", strerror(errno));
    }

    printf("Vibration sensor monitoring started on GPIO%d. Polling every %d ms.\n", GPIO_PIN, poll_timeout_ms);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    int window[WINDOW_SIZE];
    int window_index = 0;
    int window_filled = 0;

    while (program_running) {
        int sensor_value = read_sensor();
        if (sensor_value < 0) {
            gpioDelay(poll_timeout_ms * 1000);
            continue;
        }

        window[window_index] = sensor_value;
        window_index = (window_index + 1) % WINDOW_SIZE;
        if (window_filled < WINDOW_SIZE) {
            window_filled++;
        }

        check_for_earthquake();

        if (sensor_value == 1) {
            log_event(sensor_value);
        }

        gpioDelay(poll_timeout_ms * 1000);
    }

    printf("\nExiting gracefully...\n");
    if (log_file != NULL) {
        if (fclose(log_file) != 0) {
            fprintf(stderr, "Error: fclose failed: %s\n", strerror(errno));
        }
        log_file = NULL;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

