#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* LSM303DLHC magnetometer 7-bit I2C address */
#define LSM303_MAG_ADDR 0x09

/* LSM303DLHC magnetometer registers */
#define LSM303_MAG_WHO_AM_I   0x0F
#define LSM303_MAG_WHO_AM_I_VAL 0x49
#define LSM303_MAG_CTRL_REG1  0x20
#define LSM303_MAG_CTRL_REG2  0x21
#define LSM303_MAG_OUT_X_L    0x28
#define LSM303_MAG_OUT_X_H    0x29
#define LSM303_MAG_OUT_Y_L    0x2A
#define LSM303_MAG_OUT_Y_H    0x2B
#define LSM303_MAG_OUT_Z_L    0x2C
#define LSM303_MAG_OUT_Z_H    0x2D

/* Hard-iron calibration offsets */
#define X_OFFSET 10
#define Y_OFFSET (-5)
#define Z_OFFSET 20

#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "mag_log.csv"
#define SAMPLE_INTERVAL_SEC 1

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_magnetometer(int fd)
{
    uint8_t who_am_i = 0;
    if (i2c_read_reg8(fd, LSM303_MAG_WHO_AM_I, &who_am_i) < 0)
        return -1;
    if (who_am_i != LSM303_MAG_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, LSM303_MAG_WHO_AM_I_VAL);
        return -1;
    }

    /* Standby mode to allow register changes */
    if (i2c_write_reg8(fd, LSM303_MAG_CTRL_REG1, 0x00) < 0)
        return -1;
    /* 50 Hz output data rate, normal measurement mode */
    if (i2c_write_reg8(fd, LSM303_MAG_CTRL_REG2, 0x00) < 0)
        return -1;

    return 0;
}

static int read_magnetometer(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t xl, xh, yl, yh, zl, zh;
    if (i2c_read_reg8(fd, LSM303_MAG_OUT_X_L, &xl) < 0) return -1;
    if (i2c_read_reg8(fd, LSM303_MAG_OUT_X_H, &xh) < 0) return -1;
    if (i2c_read_reg8(fd, LSM303_MAG_OUT_Y_L, &yl) < 0) return -1;
    if (i2c_read_reg8(fd, LSM303_MAG_OUT_Y_H, &yh) < 0) return -1;
    if (i2c_read_reg8(fd, LSM303_MAG_OUT_Z_L, &zl) < 0) return -1;
    if (i2c_read_reg8(fd, LSM303_MAG_OUT_Z_H, &zh) < 0) return -1;

    *x = (int16_t)((xh << 8) | xl);
    *y = (int16_t)((yh << 8) | yl);
    *z = (int16_t)((zh << 8) | zl);
    return 0;
}

static void calibrate_magnetometer(int16_t raw_x, int16_t raw_y, int16_t raw_z,
                                    int16_t *x, int16_t *y, int16_t *z)
{
    *x = (int16_t)((raw_x - X_OFFSET) / 1000);
    *y = (int16_t)((raw_y - Y_OFFSET) / 1000);
    *z = (int16_t)((raw_z - Z_OFFSET) / 1000);
}

static const char *direction_from_heading(int heading)
{
    if (heading >= 0 && heading < 45) return "N";
    if (heading >= 45 && heading < 90) return "NE";
    if (heading >= 90 && heading < 135) return "E";
    if (heading >= 135 && heading < 180) return "SE";
    if (heading >= 180 && heading < 225) return "S";
    if (heading >= 225 && heading < 270) return "SW";
    if (heading >= 270 && heading < 315) return "W";
    if (heading >= 315 && heading < 360) return "NW";
    return "UNKNOWN";
}

static void log_data(FILE *fp, int16_t x, int16_t y, int16_t z, int heading)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%d,%d,%d,%d\n", ts, x, y, z, heading);
    fflush(fp);
}

static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, LSM303_MAG_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                LSM303_MAG_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    if (init_magnetometer(g_i2c_fd) < 0) {
        fprintf(stderr, "Magnetometer initialization failed.\n");
        cleanup();
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    /* Write header if file is empty */
    fseek(g_log_fp, 0, SEEK_END);
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "Timestamp,Calibrated X,Calibrated Y,Calibrated Z,Heading\n");
        fflush(g_log_fp);
    }

    printf("LSM303DLHC magnetometer logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        int16_t raw_x, raw_y, raw_z;
        if (read_magnetometer(g_i2c_fd, &raw_x, &raw_y, &raw_z) < 0) {
            fprintf(stderr, "Read error; skipping sample.\n");
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        int heading = (int)raw_x;
        int16_t x, y, z;
        calibrate_magnetometer(raw_x, raw_y, raw_z, &x, &y, &z);

        const char *dir = direction_from_heading(heading);
        printf("Heading: %d  |  %s  |  X: %d  Y: %d  Z: %d\n",
               heading, dir, x, y, z);

        log_data(g_log_fp, x, y, z, heading);

        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down cleanly.\n");
    cleanup();
    return 0;
}

