#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define DEBOUNCE_DELAY_MS 200
#define LOG_FILE "relay_log.json"

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t last_touch_tick = 0;
static volatile sig_atomic_t relay_state = 0;
static volatile sig_atomic_t log_written = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_state(int state) {
    FILE *fp = fopen(LOG_FILE, "r+");
    if (!fp) {
        fp = fopen(LOG_FILE, "w+");
        if (!fp) {
            perror("fopen");
            return -1;
        }
        fprintf(fp, "{\"timestamp\": \"1970-01-01T00:00:00Z\", \"relay_state\": \"OFF\"}");
        fflush(fp);
        log_written = 1;
    }

    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];
    localtime_r(&now, &tm_info);
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info);

    fprintf(fp, ", \"timestamp\": \"%s\", \"relay_state\": \"%s\"}",
            ts, state ? "ON" : "OFF");

    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }
    return 0;
}

static void touch_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    if (level != 1) return;

    uint32_t elapsed = tick - last_touch_tick;
    if (elapsed < DEBOUNCE_DELAY_MS * 1000) return;

    last_touch_tick = tick;
    relay_state = !relay_state;
    if (gpioWrite(RELAY_PIN, relay_state) != 0) {
        fprintf(stderr, "gpioWrite failed on relay pin\n");
    }

    if (log_state(relay_state) != 0) {
        fprintf(stderr, "Failed to log state change\n");
    }
}

static void cleanup(void) {
    gpioWrite(RELAY_PIN, 0);
    gpioSetAlertFuncEx(TOUCH_SENSOR_PIN, NULL, NULL);
    gpioTerminate();
    if (log_written) {
        FILE *fp = fopen(LOG_FILE, "r+");
        if (fp) {
            fprintf(fp, ", \"timestamp\": \"1970-01-01T00:00:00Z\", \"relay_state\": \"OFF\"}");
            fclose(fp);
        }
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set touch pin mode\n");
        cleanup();
        return 1;
    }
    if (gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on touch pin\n");
        cleanup();
        return 1;
    }
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set relay pin mode\n");
        cleanup();
        return 1;
    }
    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialise relay pin\n");
        cleanup();
        return 1;
    }

    if (gpioSetAlertFuncEx(TOUCH_SENSOR_PIN, touch_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function\n");
        cleanup();
        return 1;
    }

    printf("Monitoring touch sensor on GPIO%d, relay on GPIO%d. Press Ctrl+C to exit.\n",
           TOUCH_SENSOR_PIN, RELAY_PIN);

    while (running) {
        sleep(1);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

