#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RELAY1_PIN 17
#define RELAY2_PIN 23
#define RELAY3_PIN 24
#define RELAY4_PIN 25
#define MOISTURE_THRESHOLD 30
#define IRRIGATION_DURATION 5
#define GAP_BETWEEN_RELAYS 1
#define LOG_FILE "irrigation_log.txt"
#define POLL_INTERVAL 10

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO%d as output\n", pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioWrite(pins[i], 1) != 0) {
            fprintf(stderr, "Error: failed to set GPIO%d high\n", pins[i]);
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

static void deactivate_all_relays(void) {
    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
        gpioWrite(pins[i], 1);
    }
}

static void log_irrigation(int relay_num, int moisture_level) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: log file not open\n");
        return;
    }

    time_t now = time(NULL);
    struct tm tm_info;
    char timestamp[32];

    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return;
    }

    if (fprintf(log_file, "%s - Relay %d: Moisture level = %d\n", timestamp, relay_num, moisture_level) < 0) {
        fprintf(stderr, "Error: failed to write to log file\n");
        return;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error: failed to flush log file\n");
    }
}

static void simulate_moisture_reading(void) {
    return rand() % 101;
}

int main(void) {
    srand((unsigned int)time(NULL));

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (init_gpio() != 0) {
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        deactivate_all_relays();
        gpioTerminate();
        return 1;
    }

    printf("Smart Irrigation System started. Press Ctrl+C to exit.\n");

    while (running) {
        int moisture_level = simulate_moisture_reading();

        printf("Simulated moisture level: %d\n", moisture_level);

        if (moisture_level < MOISTURE_THRESHOLD) {
            printf("Moisture level below threshold. Activating relays.\n");

            for (int i = 0; i < 4; i++) {
                if (!running) break;

                if (gpioWrite(RELAY1_PIN, 0) != 0) {
                    fprintf(stderr, "Error: failed to activate relay 1\n");
                    break;
                }
                if (gpioWrite(RELAY2_PIN, 0) != 0) {
                    fprintf(stderr, "Error: failed to activate relay 2\n");
                    break;
                }
                if (gpioWrite(RELAY3_PIN, 0) != 0) {
                    fprintf(stderr, "Error: failed to activate relay 3\n");
                    break;
                }
                if (gpioWrite(RELAY4_PIN, 0) != 0) {
                    fprintf(stderr, "Error: failed to activate relay 4\n");
                    break;
                }

                log_irrigation(i + 1, moisture_level);

                for (int j = 0; j < GAP_BETWEEN_RELAYS && running; j++) {
                    gpioDelay(1000000);
                }

                if (gpioWrite(RELAY1_PIN, 1) != 0) {
                    fprintf(stderr, "Error: failed to deactivate relay 1\n");
                    break;
                }
                if (gpioWrite(RELAY2_PIN, 1) != 0) {
                    fprintf(stderr, "Error: failed to deactivate relay 2\n");
                    break;
                }
                if (gpioWrite(RELAY3_PIN, 1) != 0) {
                    fprintf(stderr, "Error: failed to deactivate relay 3\n");
                    break;
                }
                if (gpioWrite(RELAY4_PIN, 1) != 0) {
                    fprintf(stderr, "Error: failed to deactivate relay 4\n");
                    break;
                }
            }
        }

        for (int i = 0; i < POLL_INTERVAL && running; i++) {
            gpioDelay(1000000);
        }
    }

    printf("\nShutting down...\n");

    deactivate_all_relays();
    gpioTerminate();

    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    printf("Smart Irrigation System stopped.\n");

    return 0;
}

