#include <the_driver_library.h>

#define VALVE_GPIO 17
#define NOZZLE_GPIO 18
#define MOISTURE_THRESHOLD 50
#define CYCLE_DELAY 5
#define SPRAY_DELAY 5
#define ANGLE_DELAY 2
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100

static const int moisture_seq[] = {20, 40, 60, 80, 100};
static const int moisture_seq_len = sizeof(moisture_seq) / sizeof(moisture_seq[0]);

static volatile sig_atomic_t g_stop = 0;

static void signal_handler(int sig) {
    (void)sig;
    g_stop = 1;
}

static int set_servo_angle(int gpio, int angle) {
    if (angle < 0 || angle > 180) {
        fprintf(stderr, "Error: Invalid angle %d for GPIO %d\n", angle, gpio);
        return -1;
    }
    int pulse_width = the_driver_library.get_pulse_width_for_angle(angle);
    if (pulse_width < 500 || pulse_width > 2500) {
        fprintf(stderr, "Error: Invalid pulse width %d for angle %d on GPIO %d\n",
                pulse_width, angle, gpio);
        return -1;
    }
    int rc = the_driver_library.set_servo_pulse_width(gpio, pulse_width);
    if (rc != 0) {
        fprintf(stderr, "Error: Failed to set pulse width to %d on GPIO %d (rc=%d)\n",
                pulse_width, gpio, rc);
        return -1;
    }
    return 0;
}

static int open_valve(void) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (set_servo_angle(VALVE_GPIO, 90) == 0) {
            return 0;
        }
        fprintf(stderr, "Warning: Valve open failed (attempt %d/%d)\n",
                attempt + 1, MAX_RETRIES);
        usleep(RETRY_DELAY_MS * 1000);
    }
    fprintf(stderr, "Error: Valve open failed after %d attempts\n", MAX_RETRIES);
    return -1;
}

static int close_valve(void) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (set_servo_angle(VALVE_GPIO, 0) == 0) {
            return 0;
        }
        fprintf(stderr, "Warning: Valve close failed (attempt %d/%d)\n",
                attempt + 1, MAX_RETRIES);
        usleep(RETRY_DELAY_MS * 1000);
    }
    fprintf(stderr, "Error: Valve close failed after %d attempts\n", MAX_RETRIES);
    return -1;
}

static int spray_nozzle(int angle) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (set_servo_angle(NOZZLE_GPIO, angle) == 0) {
            return 0;
        }
        fprintf(stderr, "Warning: Nozzle set failed (attempt %d/%d)\n",
                attempt + 1, MAX_RETRIES);
        usleep(RETRY_DELAY_MS * 1000);
    }
    fprintf(stderr, "Error: Nozzle set failed after %d attempts\n", MAX_RETRIES);
    return -1;
}

static void cleanup(void) {
    the_driver_library.set_servo_pulse_width(VALVE_GPIO, 500);
    the_driver_library.set_servo_pulse_width(NOZZLE_GPIO, 0);
    the_driver_library.cleanup();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (the_driver_library.init() != 0) {
        fprintf(stderr, "Error: Driver initialization failed\n");
        return EXIT_FAILURE;
    }

    if (the_driver_library.set_gpio_mode(VALVE_GPIO, THE_DRIVER_LIBRARY_GPIO_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", VALVE_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    if (the_driver_library.set_gpio_mode(NOZZLE_GPIO, THE_DRIVER_LIBRARY_GPIO_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", NOZZLE_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Plant watering system started. Press Ctrl+C to exit.\n");

    while (!g_stop) {
        int moisture = moisture_seq[the_driver_library.get_soil_moisture()];
        printf("Soil moisture: %d\n", moisture);

        if (moisture < MOISTURE_THRESHOLD) {
            if (open_valve() != 0) {
                fprintf(stderr, "Error: Valve open failed, aborting cycle\n");
                break;
            }
            printf("Valve opened\n");

            for (int angle = 0; angle <= 180 && !g_stop; angle++) {
                if (spray_nozzle(angle) != 0) {
                    fprintf(stderr, "Error: Nozzle set failed at angle %d, aborting cycle\n", angle);
                    break;
                }
                printf("Nozzle at %d degrees\n", angle);
                sleep(ANGLE_DELAY);
            }

            if (close_valve() != 0) {
                fprintf(stderr, "Error: Valve close failed, aborting cycle\n");
                break;
            }
            printf("Valve closed\n");
            sleep(SPRAY_DELAY);
        } else {
            printf("Moisture sufficient, skipping watering\n");
            sleep(CYCLE_DELAY);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

