#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MPU6050_ADDR   0x68
#define SAMPLE_RATE_HZ 10
#define LOG_FILE       "gyro_log.txt"
#define SCALE_FACTOR   131.0f

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s (wrote %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s (got %zd of %zu)\n",
                reg, strerror(errno), n, len);
        return -1;
    }
    return 0;
}

static int init_mpu6050(int fd)
{
    if (i2c_write_byte(fd, 0x1E, 0x00) < 0) return -1;
    if (i2c_write_byte(fd, 0x1F, 0x00) < 0) return -1;
    if (i2c_write_byte(fd, 0x1A, 0x00) < 0) return -1;
    if (i2c_write_byte(fd, 0x1B, 0x00) < 0) return -1;
    if (i2c_write_byte(fd, 0x1C, 0x00) < 0) return -1;
    if (i2c_write_byte(fd, 0x1D, 0x00) < 0) return -1;
    if (i2c_write_byte(fd, 0x1E, 0x00) < 0) return -1;
    if (i2c_write_byte(fd, 0x1F, 0x00) < 0) return -1;
    if (i2c_write_byte(fd, 0x1A, 0x00) < 0) return -1;
    if (i2c_write_byte(fd, 0x1B, 0x00) < 0) return -1;
    if (i2c_write_byte(fd, 0x1C, 0x00) < 0) return -1;
    if (i2c_write_byte(fd, 0x1D, 0x00) < 0) return -1;
    return 0;
}

static int read_gyro_data(int fd, float *x, float *y, float *z)
{
    uint8_t buf[6];
    if (i2c_read_burst(fd, 0x43, buf, 6) < 0)
        return -1;

    int16_t raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_y = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t raw_z = (int16_t)((buf[4] << 8) | buf[5]);

    *x = (float)raw_x / SCALE_FACTOR;
    *y = (float)raw_y / SCALE_FACTOR;
    *z = (float)raw_z / SCALE_FACTOR;
    return 0;
}

static void log_data(FILE *fp, float x, float y, float z)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.3f,%.3f,%.3f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, x, y, z);
    fflush(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                MPU6050_ADDR, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    if (init_mpu6050(g_i2c_fd) < 0) {
        fprintf(stderr, "MPU-6050 initialization failed (sensor may be absent or bus error)\n");
        close(g_i2c_fd);
        return 1;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    printf("MPU-6050 logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        float x, y, z;
        if (read_gyro_data(g_i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Gyroscope read error; continuing.\n");
        } else {
            log_data(fp, x, y, z);
        }
        usleep(1000000 / SAMPLE_RATE_HZ);
    }

    printf("\nShutting down cleanly...\n");
    fclose(fp);
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return 0;
}

