#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define LOG_FILE    "distance_log.txt"
#define TIMEOUT_US  50000   /* 50 ms */
#define SAMPLE_US   1000000 /* 1 s  */
#define MEASURE_US  60000   /* 60 ms */

static volatile sig_atomic_t running = 1;
static FILE *log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set trigger pin %d as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set echo pin %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return -1;
    }

    /* Ensure trigger starts LOW */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise trigger pin LOW.\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void trigger_sensor(void)
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10);                 /* 10 µs pulse */
    gpioWrite(TRIGGER_PIN, 0);
}

/*
 * Wait for echo rising edge with a timeout.
 * Returns 1 on success, 0 on timeout, -1 on read error.
 */
static int wait_rising(void)
{
    uint32_t start = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int)(gpioTick() - start) > TIMEOUT_US) {
            return 0;                 /* timeout */
        }
    }
    return 1;
}

/*
 * Wait for echo falling edge with a timeout.
 * Returns 1 on success, 0 on timeout, -1 on read error.
 */
static int wait_falling(void)
{
    uint32_t start = gpioTick();
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int)(gpioTick() - start) > TIMEOUT_US) {
            return 0;                 /* timeout */
        }
    }
    return 1;
}

/*
 * Measure distance in centimetres.
 * Returns >= 0 on success, -1 on timeout/error.
 */
static int measure_distance(void)
{
    trigger_sensor();

    if (wait_rising() != 1) {
        fprintf(stderr, "Error: timeout waiting for echo rising edge.\n");
        return -1;
    }

    uint32_t pulse_start = gpioTick();

    if (wait_falling() != 1) {
        fprintf(stderr, "Error: timeout waiting for echo falling edge.\n");
        return -1;
    }

    uint32_t pulse_end = gpioTick();
    uint32_t duration = pulse_end - pulse_start;

    /* Speed of sound ≈ 343 m/s → 29 µs per cm */
    return (int)((double)duration / 0.000029);
}

static void log_distance(int distance)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (distance < 0) {
        fprintf(log_fp, "%s, -1\n", timestamp);
    } else {
        fprintf(log_fp, "%s, %d\n", timestamp, distance);
    }
    fflush(log_fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance logger started. Press Ctrl+C to exit.\n");

    while (running) {
        int distance = measure_distance();

        if (distance < 0) {
            fprintf(stderr, "Error reading distance.\n");
        } else {
            log_distance(distance);
            printf("Distance: %d cm\n", distance);
        }

        /* Sleep for the remainder of the 1 s interval */
        gpioDelay(SAMPLE_US - MEASURE_US);
    }

    printf("\nShutting down...\n");

    if (log_fp != NULL) {
        fclose(log_fp);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

