/*
 * Raspberry Pi 4 Model B – VL53L1X ToF distance reader with relay control.
 *
 * Hardware:
 *   - VL53L1X on I2C bus 1, default address 0x29 (ADDR pin tied to GND).
 *   - Relay on GPIO18 (BCM), active-HIGH.
 *
 * Behaviour:
 *   Polls the sensor every 100 ms, prints distance to stdout, and drives
 *   the relay HIGH when distance <= 50 cm, LOW otherwise.  On SIGINT the
 *   program exits cleanly, releasing all resources.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o vl53l1x_relay vl53l1x_relay.c -lpigpio -lrt
 * Run:
 *   sudo ./vl53l1x_relay
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS            1
#define VL53L1X_ADDR       0x29          /* ADDR pin tied to GND */
#define RELAY_GPIO         18            /* BCM 18 */
#define DISTANCE_THRESHOLD 50            /* cm */
#define POLL_DELAY_US      100000        /* 100 ms */
#define MAX_RETRIES        3

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ----------------------------- Signal handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- I2C helpers -------------------------------- */
static int i2c_write_reg8(int handle, uint8_t reg, uint8_t value)
{
    char buf[2] = { (char)reg, (char)value };
    if (i2cWriteDevice(handle, buf, 2) != 0) {
        fprintf(stderr, "[I2C] write reg 0x%02X failed\n", reg);
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int handle, uint8_t reg, uint8_t *out)
{
    if (i2cWriteDevice(handle, (char *)&reg, 1) != 0) {
        fprintf(stderr, "[I2C] write reg-select 0x%02X failed\n", reg);
        return -1;
    }
    if (i2cReadDevice(handle, (char *)out, 1) != 1) {
        fprintf(stderr, "[I2C] read reg 0x%02X failed\n", reg);
        return -1;
    }
    return 0;
}

/* ----------------------------- VL53L1X driver ----------------------------- */
/*
 * Minimal driver for the VL53L1X.
 * The sensor provides a 32-bit distance register (0x00) that holds the
 * distance in centimetres when a measurement is ready.
 * A full production driver would also manage the measurement queue,
 * configure the sensor, and interpret the status register.
 */
static int vl53l1x_read_distance(int handle, uint16_t *distance_cm)
{
    uint8_t status = 0;
    uint8_t dist_buf[2] = {0};

    /* Check if a new measurement is ready (bit 0 of status register). */
    if (i2c_read_reg8(handle, 0x00, &status) != 0)
        return -1;

    if ((status & 0x01) == 0) {
        /* No new data yet – return -1 so the caller can back off. */
        return -1;
    }

    /* Read 2 bytes from the distance register (0x00). */
    if (i2c_read_reg8(handle, 0x00, dist_buf) != 0)
        return -1;

    *distance_cm = ((uint16_t)dist_buf[0] << 8) | dist_buf[1];
    return 0;
}

/* ----------------------------- Main --------------------------------------- */
int main(void)
{
    /* --- Initialise pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus --- */
    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, VL53L1X_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Configure relay GPIO --- */
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, OUTPUT) failed\n", RELAY_GPIO);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);   /* Relay OFF at startup */

    /* --- Signal handling --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
