#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* MPU-6050 registers */
#define MPU6050_ADDR        0x68
#define PWR_MGMT_1         0x6B
#define GYRO_CONFIG_1      0x1B
#define GYRO_CONFIG_2      0x1C
#define GYRO_XOUT_H        0x43
#define ACCEL_XOUT_H       0x3B

#define I2C_BUS            "/dev/i2c-1"
#define SAMPLE_PERIOD_US   100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "write reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "write reg-select 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    n = read(fd, val, 1);
    if (n != 1) {
        fprintf(stderr, "read reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int mpu6050_init(int fd)
{
    if (i2c_write_reg8(fd, PWR_MGMT_1, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, GYRO_CONFIG_1, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, GYRO_CONFIG_2, 0x00) < 0) return -1;
    return 0;
}

static int mpu6050_read_gyro(int fd, int16_t *gx, int16_t *gy, int16_t *gz)
{
    uint8_t buf[6];
    ssize_t n = read(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "read gyro data failed: %s\n", strerror(errno));
        return -1;
    }
    *gx = (int16_t)((buf[0] << 8) | buf[1]);
    *gy = (int16_t)((buf[2] << 8) | buf[3]);
    *gz = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open %s failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n", MPU6050_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (mpu6050_init(fd) < 0) {
        fprintf(stderr, "MPU-6050 initialization failed (sensor absent or bus error)\n");
        close(fd);
        return EXIT_FAILURE;
    }

    printf("MPU-6050 initialized. Reading gyroscope data (Ctrl+C to exit)...\n");

    while (g_running) {
        int16_t gx, gy, gz;
        if (mpu6050_read_gyro(fd, &gx, &gy, &gz) == 0) {
            printf("Gyro: X=%6d dps, Y=%6d dps, Z=%6d dps\n", gx, gy, gz);
        } else {
            fprintf(stderr, "Gyro read error; continuing...\n");
        }
        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nExiting cleanly.\n");
    close(fd);
    return EXIT_SUCCESS;
}

