#define NUM_RELAYS 4
#define RELAY_ON_TIME_SEC 5
#define CYCLE_INTERVAL_SEC 86400
#define LOG_FILE "watering_log.txt"

static const unsigned int relay_pins[NUM_RELAYS] = {17, 18, 27, 22};
static const char *relay_names[NUM_RELAYS] = {"GPIO17", "GPIO18", "GPIO27", "GPIO22"};

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int log_cycle_start(const char *filename)
{
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    time_t rawtime = time(NULL);
    if (rawtime == (time_t)-1) {
        perror("time()");
        fclose(fp);
        return -1;
    }

    struct tm timeinfo;
    if (!localtime_r(&rawtime, &timeinfo)) {
        perror("localtime_r()");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s\n", timestamp) < 0) {
        perror("fprintf()");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose()");
        return -1;
    }

    printf("Cycle started at %s\n", timestamp);
    return 0;
}

