#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ---- Configuration ---- */
#define I2C_BUS        1
#define MPU6050_ADDR   0x68
#define LED_GPIO       17
#define THRESHOLD      250.0f   /* degrees/second */
#define BUFFER_SIZE    100
#define SAMPLE_PERIOD  50000    /* microseconds (50 ms) */
#define MAX_RETRIES    3

/* MPU-6050 registers */
#define REG_PWR_MGMT_1 0x6B
#define REG_GYRO_XOUT_H 0x43
#define REG_ACCEL_XOUT_H 0x3B

/* ---- Data structures ---- */
typedef struct {
    struct timespec timestamp;
    float x, y, z;
} gyro_data_t;

typedef struct {
    gyro_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

/* ---- Globals ---- */
static int i2c_handle = -1;
static circular_buffer_t gyro_buffer;
static volatile sig_atomic_t terminate = 0;

/* ---- Signal handler ---- */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* ---- I2C helpers ---- */
static int i2c_write_reg(uint8_t reg, uint8_t val) {
    char buf[2] = { (char)reg, (char)val };
    return i2cWriteDevice(i2c_handle, buf, 2);
}

static int i2c_read_regs(uint8_t reg, uint8_t *buf, uint8_t len) {
    char reg_buf[1] = { (char)reg };
    if (i2cWriteDevice(i2c_handle, reg_buf, 1) != 0)
        return -1;
    return i2cReadDevice(i2c_handle, (char *)buf, len);
}

/* ---- MPU-6050 initialization ---- */
static int init_mpu6050(void) {
    if (i2c_write_reg(REG_PWR_MGMT_1, 0x00) != 0) {
        fprintf(stderr, "Error: failed to write PWR_MGMT_1\n");
        return -1;
    }
    gpioDelay(100000); /* 100 ms startup delay */
    return 0;
}

/* ---- Read gyroscope ---- */
static int read_gyro_data(float *x, float *y, float *z) {
    uint8_t buf[6];
    if (i2c_read_regs(REG_GYRO_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error: failed to read gyro data\n");
        return -1;
    }
    int16_t raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_y = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t raw_z = (int16_t)((buf[4] << 8) | buf[5]);
    *x = (float)raw_x / 131.0f;
    *y = (float)raw_y / 131.0f;
    *z = (float)raw_z / 131.0f;
    return 0;
}

/* ---- Circular buffer ---- */
static void buffer_init(circular_buffer_t *buf) {
    buf->head = 0;
    buf->count = 0;
}

static void buffer_add(circular_buffer_t *buf, gyro_data_t d) {
    buf->data[buf->head] = d;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count < BUFFER_SIZE)
        buf->count++;
}

/* ---- Threshold check ---- */
static bool threshold_exceeded(float x, float y, float z) {
    return (fabsf(x) > THRESHOLD || fabsf(y) > THRESHOLD || fabsf(z) > THRESHOLD);
}

/* ---- Cleanup ---- */
static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

/* ---- Main ---- */
int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (handle=%d)\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_mpu6050() != 0) {
        fprintf(stderr, "Error: MPU-6050 init failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    buffer_init(&gyro_buffer);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float x, y, z;
    struct timespec ts;
    int retry_count = 0;

    while (!terminate) {
        if (read_gyro_data(&x, &y, &z) == 0) {
            clock_gettime(CLOCK_MONOTONIC, &ts);
            gyro_data_t d = { .timestamp = ts, .x = x, .y = y, .z = z };
            buffer_add(&gyro_buffer, d);
            retry_count = 0;
            if (threshold_exceeded(x, y, z))
                gpioWrite(LED_GPIO, 1);
            else
                gpioWrite(LED_GPIO, 0);
        } else {
            fprintf(stderr, "Warning: read failed, retrying...\n");
            retry_count++;
            if (retry_count >= MAX_RETRIES) {
                fprintf(stderr, "Error: max retries reached, exiting\n");
                break;
            }
            gpioDelay(100000); /* 100 ms backoff */
            if (i2c_handle >= 0) {
                i2cClose(i2c_handle);
                i2c_handle = -1;
            }
            if (gpioInitialise() < 0) {
                fprintf(stderr, "Error: pigpio re-init failed\n");
                break;
            }
            i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error: I2C re-open failed (handle=%d)\n", i2c_handle);
                break;
            }
            if (init_mpu6050() != 0) {
                fprintf(stderr, "Error: re-init MPU-6050 failed\n");
                break;
            }
        }
        gpioDelay(SAMPLE_PERIOD);
    }

    cleanup();
    return EXIT_SUCCESS;
}

