#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define GPIO_CHIP       "/dev/gpiochip0"
#define CS_LINE_OFFSET  8          /* BCM GPIO8 (SPI0 CE0) */
#define SPI_SPEED_HZ    1000000    /* 1 MHz */
#define SPI_MODE        SPI_MODE_0
#define SPI_BITS        8
#define SAMPLE_PERIOD_US 10000     /* 10 ms */
#define MAX_RETRIES     3
#define LOG_FILE        "gyro_log.txt"

static volatile sig_atomic_t g_running = 1;
static int  g_spi_fd = -1;
static struct gpiod_line *g_cs_line = NULL;
static struct gpiod_chip *g_chip = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int spi_init(void)
{
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1; return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1; return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1; return -1;
    }

    return 0;
}

static int gpio_init(void)
{
    g_chip = gpiod_chip_open(GPIO_CHIP);
    if (!g_chip) {
        fprintf(stderr, "gpiod_chip_open(%s): %s\n", GPIO_CHIP, strerror(errno));
        return -1;
    }

    g_cs_line = gpiod_chip_get_line(g_chip, CS_LINE_OFFSET);
    if (!g_cs_line) {
        fprintf(stderr, "gpiod_chip_get_line(%d): %s\n", CS_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(g_chip); g_chip = NULL; return -1;
    }

    if (gpiod_line_request_output(g_cs_line, "mpu9250_cs", 1) < 0) {
        fprintf(stderr, "gpiod_line_request_output: %s\n", strerror(errno));
        g_cs_line = NULL; gpiod_chip_close(g_chip); g_chip = NULL; return -1;
    }

    return 0;
}

static void gpio_cleanup(void)
{
    if (g_cs_line) {
        gpiod_line_set_value(g_cs_line, 1);
        gpiod_line_release(g_cs_line);
        g_cs_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
}

static int spi_transfer(uint8_t *tx, uint8_t *rx, size_t len)
{
    if (gpiod_line_set_value(g_cs_line, 0) < 0) {
        fprintf(stderr, "CS low: %s\n", strerror(errno));
        return -1;
    }

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = len;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE: %s\n", strerror(errno));
        gpiod_line_set_value(g_cs_line, 1);
        return -1;
    }

    if (gpiod_line_set_value(g_cs_line, 1) < 0) {
        fprintf(stderr, "CS high: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int read_gyro(int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t tx[6] = {0};
    uint8_t rx[6] = {0};

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (spi_transfer(tx, rx, sizeof(tx)) == 0) {
            *x = (int16_t)((rx[0] << 8) | rx[1]);
            *y = (int16_t)((rx[2] << 8) | rx[3]);
            *z = (int16_t)((rx[4] << 8) | rx[5]);
            return 0;
        }
        usleep(1000);
    }
    return -1;
}

static int log_data(FILE *fp, const struct timespec *ts, int16_t x, int16_t y, int16_t z)
{
    if (fprintf(fp, "%ld.%09ld,%d,%d,%d\n",
                (long)ts->tv_sec, ts->tv_nsec,
                x, y, z) < 0) {
        fprintf(stderr, "fprintf: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    gpio_cleanup();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM): %s\n", strerror(errno));
        return 1;
    }

    if (spi_init() < 0) {
        cleanup();
        return 1;
    }

    if (gpio_init() < 0) {
        cleanup();
        return 1;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    printf("Logging MPU-9250 gyro data to %s (Ctrl+C to stop)...\n", LOG_FILE);

    while (g_running) {
        struct timespec ts;
        if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
            fprintf(stderr, "clock_gettime: %s\n", strerror(errno));
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        int16_t x, y, z;
        if (read_gyro(&x, &y, &z) < 0) {
            fprintf(stderr, "Gyroscope read failed after %d retries; continuing.\n", MAX_RETRIES);
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        if (log_data(fp, &ts, x, y, z) < 0) {
            fprintf(stderr, "Logging failed; continuing.\n");
        }

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

