#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   3900000  /* 3.9 MHz, well within MPU-6050 SPI spec */
#define SPI_MODE    0
#define SPI_CS      8         /* CE0 on GPIO8 */

#define GYRO_XOUT_H 3
#define GYRO_YOUT_H 5
#define GYRO_ZOUT_H 7
#define GYRO_WHO_H  9

#define THRESHOLD 200.0f
#define LED_PIN    17
#define BUFFER_SIZE 64

typedef struct {
    struct timespec timestamp;
    float x;
    float y;
    float z;
} gyro_data_t;

typedef struct {
    gyro_data_t data[BUFFER_SIZE];
    int head;
    int tail;
    int count;
} circular_buffer_t;

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static circular_buffer_t gyro_buffer;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void init_circular_buffer(circular_buffer_t *cb) {
    cb->head = 0;
    cb->tail = 0;
    cb->count = 0;
}

static void add_to_buffer(circular_buffer_t *cb, gyro_data_t data) {
    cb->data[cb->head] = data;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count == BUFFER_SIZE) {
        cb->tail = (cb->tail + 1) % BUFFER_SIZE;
    } else {
        cb->count++;
    }
}

static int read_gyro_data(int handle, float *x, float *y, float *z) {
    char tx[7] = {0};
    char rx[7] = {0};

    tx[GYRO_XOUT_H] = 0x00;
    tx[GYRO_YOUT_H] = 0x00;
    tx[GYRO_ZOUT_H] = 0x00;
    tx[GYRO_WHO_H]  = 0x00;

    if (spiXfer(handle, tx, rx, 7) != 7) {
        return -1;
    }

    int16_t raw_x = (int16_t)(((uint16_t)(uint8_t)rx[2] << 8) | (uint8_t)rx[1]);
    int16_t raw_y = (int16_t)(((uint16_t)(uint8_t)rx[4] << 8) | (uint8_t)rx[3]);
    int16_t raw_z = (int16_t)(((uint16_t)(uint8_t)rx[6] << 8) | (uint8_t)rx[5]);

    *x = (float)raw_x / 131.0f;
    *y = (float)raw_y / 131.0f;
    *z = (float)raw_z / 131.0f;

    return 0;
}

static void check_threshold(float x, float y, float z) {
    if (fabsf(x) > THRESHOLD || fabsf(y) > THRESHOLD || fabsf(z) > THRESHOLD) {
        gpioWrite(LED_PIN, 1);
        gpioDelay(500000);
        gpioWrite(LED_PIN, 0);
        gpioDelay(500000);
    }
}

static void print_buffer(const circular_buffer_t *cb) {
    printf("\n");
    printf("Timestamp,X,Y,Z\n");
    for (int i = 0; i < cb->count; i++) {
        int idx = (cb->tail + i) % BUFFER_SIZE;
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        printf("%ld.%09ld,%.2f,%.2f,%.2f\n",
               (long)ts.tv_sec, ts.tv_nsec,
               cb->data[idx].x, cb->data[idx].y, cb->data[idx].z);
    }
    printf("\n");
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    init_circular_buffer(&gyro_buffer);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    float x, y, z;

    while (running) {
        if (read_gyro_data(spi_handle, &x, &y, &z) != 0) {
            fprintf(stderr, "Gyro read error\n");
            gpioDelay(100000);
            continue;
        }

        add_to_buffer(&gyro_buffer, (gyro_data_t){ .timestamp = {0, 0}, .x = x, .y = y, .z = z });

        check_threshold(x, y, z);

        gpioDelay(100000);
    }

    gpioWrite(LED_PIN, 0);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    print_buffer(&gyro_buffer);
    return EXIT_SUCCESS;
}

