#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* MPU-6050 I2C address (AD0 tied to GND) */
#define MPU6050_ADDR 0x68

/* MPU-6050 registers */
#define MPU6050_SMPLRT_DIV   0x19
#define MPU6050_CONFIG       0x1A
#define MPU6050_GYRO_CONFIG  0x1B
#define MPU6050_ACCEL_CONFIG 0x1C
#define MPU6050_ACCEL_XOUT_H 0x3B
#define MPU6050_GYRO_XOUT_H  0x43

/* LED GPIO pin (BCM numbering) */
#define LED_PIN 21

/* Tilt threshold (degrees) */
#define TILT_THRESHOLD 45.0

/* Sampling interval (microseconds) */
#define SAMPLE_INTERVAL_US 100000

/* Global variables */
static int i2c_handle = -1;
static volatile sig_atomic_t program_running = 1;

/* Function prototypes */
static int init_mpu6050(void);
static int read_raw_data(int16_t *ax, int16_t *ay, int16_t *az,
                         int16_t *gx, int16_t *gy, int16_t *gz);
static void process_data(int16_t ax, int16_t ay, int16_t az,
                         int16_t gx, int16_t gy, int16_t gz,
                         float *roll, float *pitch);
static void log_data(float roll, float pitch);
static void control_led(float roll, float pitch);
static void signal_handler(int signal);
static void cleanup(void);

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

/* Cleanup resources */
static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

/* Initialize MPU-6050 */
static int init_mpu6050(void) {
    /* Set sample rate divider to 7 (1 kHz / (1 + 7) = 125 Hz) */
    if (i2cWriteByteData(i2c_handle, MPU6050_SMPLRT_DIV, 7) < 0) {
        fprintf(stderr, "Error: Failed to set sample rate divider\n");
        return -1;
    }

    /* Set DLPF config (LPF bandwidth) */
    if (i2cWriteByteData(i2c_handle, MPU6050_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to set DLPF config\n");
        return -1;
    }

    /* Set gyro full scale range to +/- 250 degrees/sec */
    if (i2cWriteByteData(i2c_handle, MPU6050_GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to set gyro config\n");
        return -1;
    }

    /* Set accelerometer full scale range to +/- 2g */
    if (i2cWriteByteData(i2c_handle, MPU6050_ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to set accel config\n");
        return -1;
    }

    return 0;
}

/* Read raw accelerometer and gyroscope data */
static int read_raw_data(int16_t *ax, int16_t *ay, int16_t *az,
                         int16_t *gx, int16_t *gy, int16_t *gz) {
    char buf[14];

    /* Read 14 bytes starting from ACCEL_XOUT_H (0x3B) */
    if (i2cReadI2CBlockData(i2c_handle, MPU6050_ACCEL_XOUT_H, buf, 14) != 14) {
        fprintf(stderr, "Error: Failed to read sensor data\n");
        return -1;
    }

    /* Combine high and low bytes (big-endian) */
    *ax = (int16_t)((buf[0] << 8) | buf[1]);
    *ay = (int16_t)((buf[2] << 8) | buf[3]);
    *az = (int16_t)((buf[4] << 8) | buf[5]);
    *gx = (int16_t)((buf[8] << 8) | buf[9]);
    *gy = (int16_t)((buf[10] << 8) | buf[11]);
    *gz = (int16_t)((buf[12] << 8) | buf[13]);

    return 0;
}

/* Process raw data to get roll and pitch angles (degrees) */
static void process_data(int16_t ax, int16_t ay, int16_t az,
                         int16_t gx, int16_t gy, int16_t gz,
                         float *roll, float *pitch) {
    /* Convert raw values to g's (assuming +/- 2g range) */
    float ax_g = (float)ax / 16384.0f;
    float ay_g = (float)ay / 16384.0f;
    float az_g = (float)az / 16384.0f;
    float gx_g = (float)gx / 16384.0f;
    float gy_g = (float)gy / 16384.0f;
    float gz_g = (float)gz / 16384.0f;

    /* Calculate roll and pitch angles */
    *roll = atan2f(ay_g, az_g) * 180.0f / M_PI;
    *pitch = atan2f(-ax_g, sqrtf(gx_g * gx_g + gz_g * gz_g)) * 180.0f / M_PI;
}

