}

/* Control LED based on tilt threshold */
static void control_led(float roll, float pitch) {
    int led_state = (fabsf(roll) > TILT_THRESHOLD || fabsf(pitch) > TILT_THRESHOLD) ? 1 : 0;
    gpioWrite(LED_PIN, led_state);
}

int main(void) {
