#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SI1145_ADDR    0x60
#define GPIO_LED       17
#define MAX_RETRIES    3
#define RETRY_DELAY_MS 10
#define POLL_INTERVAL_MS 100

/* Si1145 register addresses (8-bit) */
#define REG_PART_ID     0x00
#define REG_HW_KEY      0x07
#define REG_ALS_VIS_DATA0 0x22
#define REG_PS1_DATA0   0x24
#define REG_COMMAND     0x18
#define CMD_RESET       0x01
#define CMD_ALS_FORCE   0x06
#define CMD_PS_FORCE    0x05

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int si1145_init(int fd) {
    uint8_t part_id;
    if (i2c_read_reg8(fd, REG_PART_ID, &part_id) < 0) return -1;
    if (part_id != 0x45) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x45)\n", part_id);
        return -1;
    }
    if (i2c_write_reg8(fd, REG_COMMAND, CMD_RESET) < 0) return -1;
    usleep(10000);
    if (i2c_write_reg8(fd, REG_HW_KEY, 0x17) < 0) return -1;
    return 0;
}

static int si1145_read_ambient_light(int fd, uint16_t *ambient) {
    uint8_t lo, hi;
    if (i2c_read_reg8(fd, REG_ALS_VIS_DATA0, &lo) < 0) return -1;
    if (i2c_read_reg8(fd, REG_ALS_VIS_DATA0 + 1, &hi) < 0) return -1;
    *ambient = (uint16_t)((hi << 8) | lo);
    return 0;
}

static int si1145_read_proximity(int fd, uint16_t *proximity) {
    uint8_t lo, hi;
    if (i2c_read_reg8(fd, REG_PS1_DATA0, &lo) < 0) return -1;
    if (i2c_read_reg8(fd, REG_PS1_DATA0 + 1, &hi) < 0) return -1;
    *proximity = (uint16_t)((hi << 8) | lo);
    return 0;
}

static void log_data(FILE *fp, uint16_t ambient, uint16_t proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(fp, "%s,AmbientLight:%u,Proximity:%u\n", timestamp, ambient, proximity);
    fflush(fp);
}

static void cleanup(void) {
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open " I2C_BUS);
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SI1145_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        cleanup();
        return EXIT_FAILURE;
    }

    if (si1145_init(g_i2c_fd) < 0) {
        fprintf(stderr, "Si1145 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_LED, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", GPIO_LED);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(GPIO_LED, 0);

    g_log_fp = fopen("biometric_log.txt", "a");
    if (!g_log_fp) {
        perror("fopen biometric_log.txt");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Si1145 monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t ambient = 0, proximity = 0;
        int retries = 0;
        int read_ok = 0;

        while (retries < MAX_RETRIES && g_running) {
            if (si1145_read_ambient_light(g_i2c_fd, &ambient) == 0 &&
                si1145_read_proximity(g_i2c_fd, &proximity) == 0) {
                read_ok = 1;
                break;
            }
            retries++;
            if (retries < MAX_RETRIES) {
                fprintf(stderr, "Read attempt %d/%d failed, retrying...\n", retries, MAX_RETRIES);
                usleep(RETRY_DELAY_MS * 1000);
            }
        }

        if (read_ok) {
            log_data(g_log_fp, ambient, proximity);
            if (proximity > 100) {
                gpioWrite(GPIO_LED, 1);
            } else {
                gpioWrite(GPIO_LED, 0);
            }
        } else {
            fprintf(stderr, "Failed to read sensor data after %d retries\n", MAX_RETRIES);
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");
    gpioWrite(GPIO_LED, 0);
    cleanup();
    return EXIT_SUCCESS;
}

