    terminate = 1;
}

/* ------------------------------------------------------------------ */
/* Read a single register from the ADXRS290                              */
/* Returns 0 on success, -1 on failure.                                 */
/* ------------------------------------------------------------------ */
static int read_register(uint8_t reg, int16_t *out)
{
    char tx[3];
    char rx[3];
    int  ret;

    /* Build the command: [reg | 0x80] [dummy] [dummy] */
    tx[0] = (char)(reg | 0x80);
    tx[1] = 0x00;
    tx[2] = 0x00;

    ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed for reg 0x%02X (ret=%d): %s\n",
                reg, ret, strerror(errno));
        return -1;
    }

    /* Response: rx[1] is the high byte, rx[2] is the low byte */
    *out = (int16_t)(((uint16_t)(uint8_t)rx[1] << 8) | (uint8_t)rx[2]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise SPI                                                        */
/* ------------------------------------------------------------------ */
static int init_spi(void)
{
    /* spiOpen flags: bits 0-1 = mode, bit 2 = active-low CE, 0 = active-high */
    unsigned flags = (SPI_MODE & 0x03) | 0x00;
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, flags);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise CSV file                                                   */
/* ------------------------------------------------------------------ */
static int init_csv(void)
{
    fp = fopen("gyro_data.csv", "w");
    if (!fp) {
        fprintf(stderr, "Failed to open gyro_data.csv: %s\n", strerror(errno));
        return -1;
    }
    fprintf(fp, "timestamp_x_raw_x_raw_y\n");
    fflush(fp);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                       */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (fp) {
        fflush(fp);
        fclose(fp);
        fp = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
