{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (init_spi() != 0) {
        cleanup();
        return 1;
    }

    if (init_csv() != 0) {
        cleanup();
        return 1;
    }

    int16_t x_raw, y_raw;
    struct timespec ts;
    char    timestamp[40];

    while (!terminate) {
        if (read_register(ADXRS290_REG_XGYRO_OUT, &x_raw) != 0) {
            fprintf(stderr, "Failed to read X gyro; re-initialising SPI...\n");
            for (int attempt = 0; attempt < MAX_RETRIES && !terminate; attempt++) {
                if (init_spi() == 0) {
                    break;
