        if (read_register(ADXRS290_REG_YGYRO_OUT, &y_raw) != 0) {
            fprintf(stderr, "Failed to read Y gyro; re-initialising SPI...\n");
            for (int attempt = 0; attempt < MAX_RETRIES && !terminate; attempt++) {
                if (init_spi() == 0) {
                    break;
