            continue;
        }

        if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
            fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
            continue;
        }

        snprintf(timestamp, sizeof(timestamp), "%ld.%06ld",
                 (long)ts.tv_sec, ts.tv_nsec / 1000);

        if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, x_raw, y_raw, 0) < 0) {
            fprintf(stderr, "Failed to write to CSV: %s\n", strerror(errno));
            break;
        }
        fflush(fp);

        gpioDelay(SAMPLE_DELAY_US);
    }

    cleanup();
    return 0;
}

