#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SENSOR_1_PIN 23
#define SENSOR_2_PIN 24
#define ALERT_PIN    17
#define EVENT_DURATION_MS 500
#define ALERT_DURATION_US 2000000
#define LOG_FILE "seismic_events.txt"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(void) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (log_file != NULL) {
        fprintf(log_file, "%s - Seismic event detected!\n", timestamp);
        fflush(log_file);
    } else {
        fprintf(stderr, "Log file not open\n");
    }
}

static void sensor_callback(int gpio, int level, uint32_t tick) {
    (void)tick;
    if (gpio == SENSOR_1_PIN && level == 1) {
        gpioWrite(ALERT_PIN, 1);
        log_event();
    } else if (gpio == SENSOR_2_PIN && level == 1) {
        gpioWrite(ALERT_PIN, 1);
        log_event();
    } else if (gpio == ALERT_PIN) {
        gpioWrite(ALERT_PIN, 0);
    }
}

static void cleanup(void) {
    gpioWrite(ALERT_PIN, 0);
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0 ||
        gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0 ||
        gpioSetMode(ALERT_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN);
    gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN);

    if (gpioWrite(ALERT_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialise alert pin LOW\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFuncEx(SENSOR_1_PIN, sensor_callback, NULL) != 0 ||
        gpioSetAlertFuncEx(SENSOR_2_PIN, sensor_callback, NULL) != 0 ||
        gpioSetAlertFuncEx(ALERT_PIN, sensor_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert callbacks\n");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to set signal handlers");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Seismic event detection started. Press Ctrl+C to exit.\n");

    uint32_t event_start_tick = 0;
    uint32_t event_end_tick   = 0;

    while (running) {
        gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

