/*
 * ADXRS290 dual-axis MEMS gyroscope reader for Raspberry Pi Zero W.
 *
 * SPI0:  CE0  -> GPIO8  (BCM)
 *        SCLK -> GPIO11 (BCM)
 *        MOSI -> GPIO10 (BCM)
 *        MISO -> GPIO9  (BCM)
 *   Mode: 0 (CPOL=0, CPHA=0)
 *   Speed: 1 MHz
 *
 * ADXRS290 register addressing: bit 7 = 1 for read, bit 6 = 1 for write.
 *   X-axis rate is a 16-bit signed value in the first two data bytes.
 *
 * Build:  gcc -O2 -Wall -Wextra -o gyro_monitor gyro_monitor.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U
#define SPI_MODE        SPI_MODE_0
#define SPI_BITS        8

#define BUFFER_SIZE     100
#define THRESHOLD       20.0f
#define LED_PIN         17
#define GPIO_CHIP       "gpiochip0"

#define ADXRS290_REG_XGYRO  0x04
#define ADXRS290_REG_STATUS 0x00

#define SAMPLE_PERIOD_US  10000U  /* 10 ms */

/* ------------------------------------------------------------------ */
/* Circular buffer                                                     */
/* ------------------------------------------------------------------ */

typedef struct {
    struct timespec timestamp;
    float rate;
} gyro_data_t;

typedef struct {
    gyro_data_t data[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t lock;
} circular_buffer_t;

static circular_buffer_t gyro_buffer;

static void cb_init(circular_buffer_t *cb)
{
    cb->head  = 0;
    cb->tail  = 0;
    cb->count = 0;
    pthread_mutex_init(&cb->lock, NULL);
}

static void cb_push(circular_buffer_t *cb, struct timespec ts, float rate)
{
    cb->data[cb->head].timestamp = ts;
    cb->data[cb->head].rate      = rate;

    cb->head = (cb->head + 1) % BUFFER_SIZE;

    if (cb->count == BUFFER_SIZE) {
        cb->tail = (cb->tail + 1) % BUFFER_SIZE;
    } else {
        cb->count++;
    }
}

/* ------------------------------------------------------------------ */
/* SPI helpers                                                         */
/* ------------------------------------------------------------------ */

static int spi_transfer(int fd, const uint8_t *tx, uint8_t *rx, size_t len)
{
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (uintptr_t)tx;
    tr.rx_buf        = (uintptr_t)rx;
    tr.len           = len;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int adxrs290_read_reg(int fd, uint8_t reg, uint8_t *val)
{
    uint8_t tx[2] = { (uint8_t)(reg | 0x80), 0x00 };
    uint8_t rx[2] = { 0, 0 };

    if (spi_transfer(fd, tx, rx, 2) < 0)
        return -1;

    *val = rx[1];
    return 0;
}

static int adxrs290_read_rate(int fd, float *rate)
{
    uint8_t status = 0;
    if (adxrs290_read_reg(fd, ADXRS290_REG_STATUS, &status) < 0)
        return -1;

    if ((status & 0x01) == 0) {
        fprintf(stderr, "ADXRS290 status bit 0 (X gyro ready) is clear.\n");
        return -1;
    }

    uint8_t data[2] = { 0, 0 };
    if (spi_transfer(fd, (uint8_t[]){ (uint8_t)(ADXRS290_REG_XGYRO | 0x80), 0x00 }, data, 2) < 0)
        return -1;

    int16_t raw = (int16_t)((data[0] << 8) | data[1]);
    *rate = (float)raw;
    return 0;
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                        */
/* ------------------------------------------------------------------ */

static struct gpiod_chip *open_gpio_chip(void)
{
    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP, strerror(errno));
        return NULL;
    }
    return chip;
}

static struct gpiod_line *open_led_line(struct gpiod_chip *chip)
{
    struct gpiod_line *line = gpiod_chip_get_line(chip, LED_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", LED_PIN, strerror(errno));
        return NULL;
    }
    if (gpiod_line_request_output(line, "adxrs290_led", 0) < 0) {
        fprintf(stderr, "Failed to request LED line as output: %s\n", strerror(errno));
        return NULL;
    }
    return line;
}

static void set_led(struct gpiod_line *line, bool on)
{
    if (line)
        gpiod_line_set_value(line, on ? 1 : 0);
}

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    int spi_fd = -1;
    struct gpiod_chip *gpio_chip = NULL;
    struct gpiod_line *led_line = NULL;
    int ret = EXIT_FAILURE;

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* ---- Open SPI device ---- */
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", SPI_DEVICE, strerror(errno));
        goto cleanup;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE failed: %s\n", strerror(errno));
        goto cleanup;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD failed: %s\n", strerror(errno));
        goto cleanup;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* ---- Open GPIO chip and LED line ---- */
    gpio_chip = open_gpio_chip();
    if (!gpio_chip) {
        goto cleanup;
    }

    led_line = open_led_line(gpio_chip);
    if (!led_line) {
        goto cleanup;
    }

    /* ---- Initialize circular buffer ---- */
    cb_init(&gyro_buffer);

    printf("ADXRS290 monitoring started.  Threshold = %.1f deg/s  LED=GPIO%d\n",
           THRESHOLD, LED_PIN);

    /* ---- Main loop ---- */
    while (g_running) {
        struct timespec ts;
        if (clock_gettime(CLOCK_MONOTONIC, &ts) < 0) {
            fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
            break;
        }

        float rate = 0.0f;
        if (adxrs290_read_rate(spi_fd, &rate) < 0) {
            fprintf(stderr, "ADXRS290 read error at %ld.%09ld\n",
                    (long)ts.tv_sec, ts.tv_nsec);
            continue;
        }

        cb_push(&gyro_buffer, ts, rate);

        bool over = (rate > THRESHOLD);
        set_led(led_line, over);

        printf("timestamp=%ld.%09ld  rate=%.2f  threshold=%.1f  LED=%s\n",
               (long)ts.tv_sec, ts.tv_nsec, rate, THRESHOLD, over ? "ON" : "OFF");

        usleep(SAMPLE_PERIOD_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (led_line)
        gpiod_line_set_value(led_line, 0);
    if (led_line)
        gpiod_line_release(led_line);
    if (gpio_chip)
        gpiod_chip_close(gpio_chip);
    if (spi_fd >= 0)
        close(spi_fd);

    pthread_mutex_destroy(&gyro_buffer.lock);
    printf("Exited cleanly.\n");
    return ret;
}

