/*
 * smart_sunset_simulator.c
 *
 * Raspberry Pi Zero W — smart sunset simulator for three relay-controlled
 * dimmable lamps on BCM GPIO17, GPIO18, GPIO27 (PWM-capable pins).
 *
 * Fades each lamp sequentially from 100 % to 0 % brightness over a
 * user-specified total duration (1–3600 s), then turns them all off.
 *
 * Build:  gcc -O2 -Wall -Wextra -o smart_sunset_simulator smart_sunset_simulator.c
 * Run:    ./smart_sunset_simulator <total_duration_seconds>
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <time.h>

#include <pigpio.h>

/* ---- Pin assignments (BCM numbering) ---- */
#define LAMP1_PIN 17
#define LAMP2_PIN 18
#define LAMP3_PIN 27

/* ---- Sunset parameters ---- */
#define FADE_DURATION_SECONDS  3600   /* default total duration */
#define FADE_STEP_SECONDS      5      /* step interval (1–60 s) */
#define FADE_STEP_PERCENT      100    /* 100 % -> 0 % */
#define PWM_FREQUENCY_HZ       100    /* 100 Hz hardware PWM */
#define PWM_RANGE              255    /* 0–255 duty-cycle */

/* ---- Globals for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static int g_pigpio_initialized = 0;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0)
        perror("sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) != 0)
        perror("sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
static void cleanup_all_lamps(void)
{
    if (g_pigpio_initialized) {
        gpioPWM(LAMP1_PIN, 0);
        gpioPWM(LAMP2_PIN, 0);
        gpioPWM(LAMP3_PIN, 0);
        gpioTerminate();
        g_pigpio_initialized = 0;
    }
}

/* ------------------------------------------------------------------ */
static void print_usage(const char *prog)
{
    fprintf(stderr,
        "Usage: %s <total_duration_seconds> (1–3600)\n"
        "  Fades three lamps sequentially from 100 % to 0 % over "
        "the specified duration, then turns them off.\n",
        prog);
}

/* ------------------------------------------------------------------ */
static int validate_duration(int duration)
{
    if (duration < 1 || duration > 3600) {
        fprintf(stderr,
            "Error: duration must be between 1 and 3600 seconds.\n"
            "  Got: %d\n", duration);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }
    g_pigpio_initialized = 1;

    int pins[] = { LAMP1_PIN, LAMP2_PIN, LAMP3_PIN };
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode(%d) failed.\n", pins[i]);
            return -1;
        }
        if (gpioSetPWMfrequency(pins[i], PWM_FREQUENCY_HZ) < 0) {
            fprintf(stderr, "Error: gpioSetPWMfrequency(%d) failed.\n", pins[i]);
            return -1;
        }
        if (gpioSetPWMrange(pins[i], PWM_RANGE) != 0) {
            fprintf(stderr, "Error: gpioSetPWMrange(%d) failed.\n", pins[i]);
            return -1;
        }
        if (gpioPWM(pins[i], 0) != 0) {
            fprintf(stderr, "Error: gpioPWM(%d, 0) failed.\n", pins[i]);
            return -1;
        }
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static void fade_lamp(int pin, int duration_seconds)
{
    if (duration_seconds <= 0) {
        gpioPWM(pin, 0);
        return;
    }

    int elapsed = 0;
    int step = FADE_STEP_SECONDS;
    int percent = FADE_STEP_PERCENT;

    while (elapsed < duration_seconds && g_running) {
        elapsed += step;
        int duty = (percent * PWM_RANGE) / 100;

        if (gpioPWM(pin, duty) != 0) {
            fprintf(stderr, "Warning: gpioPWM(%d, %d) failed.\n", pin, duty);
        }

        printf("Lamp on GPIO%d: %d/%d %%% (elapsed %d/%d s)\n",
               pin, duty, PWM_RANGE, elapsed, duration_seconds);

        percent -= step;
        if (percent < 0) {
            percent += PWM_RANGE;
            step = FADE_STEP_SECONDS;
        }

        if (elapsed < duration_seconds) {
            sleep(1);
        }
    }

    if (gpioPWM(pin, 0) != 0) {
        fprintf(stderr, "Warning: gpioPWM(%d, 0) failed.\n", pin);
    }
}

/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    if (argc != 2) {
        print_usage(argv[0]);
        return EXIT_FAILURE;
    }

    int total_duration = atoi(argv[1]);
    if (validate_duration(total_duration) != 0) {
        return EXIT_FAILURE;
    }

    install_signal_handlers();

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Smart Sunset Simulator started.\n");
    printf("Fading three lamps over %d seconds (step %d s).\n",
           total_duration, FADE_STEP_SECONDS);
    printf("Press Ctrl+C to abort early.\n");

    int lamp_count = 0;
    int lamp_index = 0;

    while (g_running && lamp_count < 3) {
        int pin = LAMP1_PIN + lamp_index;
        fade_lamp(pin, total_duration);
        lamp_index = (lamp_index + 1) % 3;
        lamp_count++;
    }

    printf("\nShutting down: turning off all lamps...\n");
    cleanup_all_lamps();
    printf("Done.\n");

    return EXIT_SUCCESS;
}

