#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FLAME_SENSOR_PIN 17
#define BUZZER_PIN 18
#define LED_PIN 23
#define LOG_FILE "flame_log.txt"
#define CONSECUTIVE_READINGS 3
#define READ_DELAY_US 50000  /* 50 ms */

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_flame_sensor(void) {
    int level = gpioRead(FLAME_SENSOR_PIN);
    if (level < 0) {
        fprintf(stderr, "Error: gpioRead failed on pin %d (rc=%d)\n",
                FLAME_SENSOR_PIN, level);
        return -1;
    }
    return level;
}

static int log_event(const char *message) {
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "Error: time() failed\n");
        return -1;
    }
    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "Error: localtime_r() failed\n");
        return -1;
    }
    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error: strftime() failed\n");
        return -1;
    }
    if (fprintf(log_file, "%s - %s\n", timestamp, message) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed\n");
        return -1;
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error: fflush failed\n");
        return -1;
    }
    return 0;
}

static int activate_alarm(void) {
    if (gpioWrite(BUZZER_PIN, 1) != 0) {
        fprintf(stderr, "Error: gpioWrite(BUZZER_PIN, 1) failed\n");
        return -1;
    }
    if (gpioWrite(LED_PIN, 1) != 0) {
        fprintf(stderr, "Error: gpioWrite(LED_PIN, 1) failed\n");
        gpioWrite(BUZZER_PIN, 0);
        return -1;
    }
    return 0;
}

static void deactivate_alarm(void) {
    if (gpioWrite(BUZZER_PIN, 0) != 0) {
        fprintf(stderr, "Error: gpioWrite(BUZZER_PIN, 0) failed\n");
    }
    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Error: gpioWrite(LED_PIN, 0) failed\n");
    }
}

static void cleanup(void) {
    deactivate_alarm();
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(FLAME_SENSOR_PIN) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(BUZZER_PIN) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(LED_PIN) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioWrite(BUZZER_PIN, 0) != 0 || gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Error: initial gpioWrite failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Flame detection system started. Press Ctrl+C to exit.\n");

    int flame_active = 0;
    int consecutive_low = 0;

    while (running) {
        int level = read_flame_sensor();
        if (level < 0) {
            fprintf(stderr, "Error reading flame sensor, exiting.\n");
            break;
        }

        if (level == 0) {
            consecutive_low++;
            if (consecutive_low >= CONSECUTIVE_READINGS && !flame_active) {
                printf("Flame detected!\n");
                if (log_event("Flame Detected") != 0) {
                    fprintf(stderr, "Warning: failed to log event\n");
                }
                if (activate_alarm() != 0) {
                    fprintf(stderr, "Warning: alarm activation failed\n");
                }
                flame_active = 1;
            }
        } else {
            consecutive_low = 0;
            if (flame_active) {
                deactivate_alarm();
                flame_active = 0;
            }
        }

        gpioDelay(READ_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

