#define LOG_FILE "dispense_log.txt"

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int log_dispense(int sol1_pin, int sol2_pin, int duration_ms) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%s - Solenoid 1 (GPIO%d): %d ms, Solenoid 2 (GPIO%d): %d ms\n",
            timestamp, sol1_pin, duration_ms, sol2_pin, duration_ms);

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int dispense(int sol1_pin, int sol2_pin, int duration_ms) {
    if (gpioWrite(sol1_pin, 1) < 0) {
        fprintf(stderr, "Failed to activate solenoid 1 (GPIO%d)\n", sol1_pin);
        return -1;
    }
    if (gpioWrite(sol2_pin, 0) < 0) {
        fprintf(stderr, "Failed to deactivate solenoid 2 (GPIO%d)\n", sol2_pin);
        gpioWrite(sol1_pin, 0);
        return -1;
    }

    gpioDelay(duration_ms * 1000);

    if (gpioWrite(sol1_pin, 0) < 0) {
        fprintf(stderr, "Failed to deactivate solenoid 1 (GPIO%d)\n", sol1_pin);
        return -1;
    }
    if (gpioWrite(sol2_pin, 1) < 0) {
        fprintf(stderr, "Failed to activate solenoid 2 (GPIO%d)\n", sol2_pin);
        return -1;
    }

    gpioDelay(duration_ms * 1000);

    if (gpioWrite(sol2_pin, 0) < 0) {
        fprintf(stderr, "Failed to deactivate solenoid 2 (GPIO%d)\n", sol2_pin);
        return -1;
    }
    if (gpioWrite(sol1_pin, 1) < 0) {
        fprintf(stderr, "Failed to deactivate solenoid 1 (GPIO%d)\n", sol1_pin);
        return -1;
    }

    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SOLENOID_1_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", SOLENOID_1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SOLENOID_2_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", SOLENOID_2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(SOLENOID_1_PIN, 0) < 0) {
        fprintf(stderr, "Failed to initialize solenoid 1 state\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(SOLENOID_2_PIN, 0) < 0) {
        fprintf(stderr, "Failed to initialize solenoid 2 state\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Pneumatic dispensing system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        if (dispense(SOLENOID_1_PIN, SOLENOID_2_PIN, DISPENSE_DURATION_MS) < 0) {
            fprintf(stderr, "Dispense operation failed\n");
            break;
        }

        if (log_dispense(SOLENOID_1_PIN, SOLENOID_2_PIN, DISPENSE_DURATION_MS) < 0) {
            fprintf(stderr, "Logging failed\n");
            break;
        }

        printf("Dispense complete. Waiting %d ms...\n", DISPENSE_INTERVAL_MS - DISPENSE_DURATION_MS);
        gpioDelay(DISPENSE_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");
    gpioWrite(SOLENOID_1_PIN, 0);
    gpioWrite(SOLENOID_2_PIN, 0);
    gpioTerminate();

    return EXIT_SUCCESS;
}

