#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <math.h>
#include <stdbool.h>
#include <pigpio.h>

/* Motor A pins (BCM numbering) */
#define MOTOR_A_FORWARD 17
#define MOTOR_A_BACKWARD 18

/* Motor B pins (BCM numbering) */
#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23

/* Enable pins (HIGH = PWM enabled) */
#define ENA 24
#define ENB 25

/* PWM range (pigpio hardware PWM supports 0-255 by default) */
#define PWM_RANGE 255

/* Obstacle avoidance threshold (cm) */
#define OBSTACLE_THRESHOLD 20.0

/* PID parameters */
#define KP 1.0
#define KI 0.01
#define KD 0.1

/* Log file path */
#define LOG_FILE "balance_log.txt"

/* Global state */
static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Motor helpers                                                       */
/* ------------------------------------------------------------------ */
static int motor_set_direction(int forward_pin, int backward_pin,
                               int forward, int backward)
{
    if (forward) {
        if (gpioWrite(forward_pin, 1) < 0) return -1;
        if (gpioWrite(backward_pin, 0) < 0) return -1;
    } else {
        if (gpioWrite(forward_pin, 0) < 0) return -1;
        if (gpioWrite(backward_pin, 1) < 0) return -1;
    }
    return 0;
}

static int motor_set_speed(int forward_pin, int backward_pin,
                           int speed)
{
    if (speed < 0) speed = 0;
    if (speed > PWM_RANGE) speed = PWM_RANGE;

    if (gpioPWM(forward_pin, speed) < 0) return -1;
    if (gpioPWM(backward_pin, speed) < 0) return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Motor abstraction                                                   */
/* ------------------------------------------------------------------ */
typedef struct {
    int forward_pin;
    int backward_pin;
} motor_t;

static int motor_init(motor_t *m, int forward_pin, int backward_pin)
{
    m->forward_pin = forward_pin;
    m->backward_pin = backward_pin;

    if (motor_set_direction(forward_pin, backward_pin, 0, 0) < 0) {
        fprintf(stderr, "Error: failed to initialize motor direction on GPIO%d\n",
                forward_pin);
        return -1;
    }
    if (motor_set_speed(forward_pin, backward_pin, 0) < 0) {
        fprintf(stderr, "Error: failed to initialize motor speed on GPIO%d\n",
                forward_pin);
        return -1;
    }
    return 0;
}

static void motor_stop(motor_t *m)
{
    (void)motor_set_speed(m->forward_pin, m->backward_pin, 0);
}

static int motor_drive(motor_t *m, double speed)
{
    if (speed < 0.0) speed = 0.0;
    if (speed > PWM_RANGE) speed = PWM_RANGE;

    if (motor_set_speed(m->forward_pin, m->backward_pin, (int)speed) < 0) {
        fprintf(stderr, "Error: failed to set motor speed to %.2f\n", speed);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Obstacle avoidance                                                 */
/* ------------------------------------------------------------------ */
static void obstacle_avoidance(double distance)
{
    if (distance < OBSTACLE_THRESHOLD) {
        printf("Obstacle detected! Distance: %.2f cm\n", distance);
        motor_set_direction(MOTOR_A_FORWARD, MOTOR_A_BACKWARD, 0, 1);
        motor_set_direction(MOTOR_B_FORWARD, MOTOR_B_BACKWARD, 0, 1);
        motor_set_speed(MOTOR_A_FORWARD, MOTOR_A_BACKWARD, 50);
        motor_set_speed(MOTOR_B_FORWARD, MOTOR_B_BACKWARD, 50);
    }
}

/* ------------------------------------------------------------------ */
/* PID control                                                         */
/* ------------------------------------------------------------------ */
static double pid_control(double setpoint, double actual,
                          double *integral, double *previous_error,
                          double dt, double *prev_integral,
                          double kp, double ki, double kd)
{
    double error = setpoint - actual;
    *integral += error * dt;
    double derivative = (error - *previous_error) / dt;

    double output = kp * error + ki * (*integral) + kd * derivative;

    *previous_error = error;
    *prev_integral = *integral;

    if (output < -PWM_RANGE) output = -PWM_RANGE;
    if (output > PWM_RANGE) output = PWM_RANGE;

    return output;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, double tilt_error, double distance,
                     double motor_a_speed, double motor_b_speed)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(fp, "%s,%.2f,%.2f,%.2f,%.2f\n",
            timestamp, tilt_error, distance, motor_a_speed, motor_b_speed);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    motor_stop(&motor_a);
    motor_stop(&motor_b);
    if (g_log) {
        fclose(g_log);
        g_log = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    /* Initialize motors */
    motor_t motor_a, motor_b;
    if (motor_init(&motor_a, MOTOR_A_FORWARD, MOTOR_A_BACKWARD) < 0 ||
        motor_init(&motor_b, MOTOR_B_FORWARD, MOTOR_B_BACKWARD) < 0) {
        fprintf(stderr, "Error: motor initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    /* Open log file */
    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    /* Register signal handler */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed: %s\n",
                strerror(errno));
    }

    /* Initialize PID state */
    double integral_a = 0.0, previous_error_a = 0.0;
    double integral_b = 0.0, previous_error_b = 0.0;
    double dt = 0.05;

    /* Main control loop */
    while (g_running) {
        /* Simulated sensor readings */
        double tilt_error = (rand() % 20) - 10.0;   /* -10.0 to +10.0 */
        double distance = (rand() % 400) + 2.0;     /* 2.0 to 400.0 */

        /* Obstacle avoidance */
        obstacle_avoidance(distance);

        /* PID control */
        double motor_a_speed = pid_control(tilt_error, 0.0,
                                          &integral_a, &previous_error_a,
                                          dt, &integral_b, KP, KI, KD);
        double motor_b_speed = pid_control(tilt_error, 0.0,
                                          &integral_a, &previous_error_a,
                                          dt, &integral_b, KP, KI, KD);

        /* Clamp speeds */
        if (motor_a_speed < 0.0) motor_a_speed = 0.0;
        if (motor_a_speed > PWM_RANGE) motor_a_speed = PWM_RANGE;
        if (motor_b_speed < 0.0) motor_b_speed = 0.0;
        if (motor_b_speed > PWM_RANGE) motor_b_speed = PWM_RANGE;

        /* Drive motors */
        motor_drive(&motor_a, motor_a_speed);
        motor_drive(&motor_b, motor_b_speed);

        /* Log data */
        log_data(g_log, tilt_error, distance, motor_a_speed, motor_b_speed);

        usleep(50000); /* 50 ms */
    }

    /* Graceful shutdown */
    printf("\nShutting down...\n");
    motor_stop(&motor_a);
    motor_stop(&motor_b);
    cleanup();
    return 0;
}

