/*
 * mood_light.c — Raspberry Pi 3 Model B+
 *
 * Captures audio via ALSA at 8000 Hz, 16-bit mono, computes RMS amplitude
 * every 10 ms, and maps it to a common-cathode RGB LED driven by software
 * PWM on GPIO17 (R), GPIO18 (G), GPIO27 (B) using the driver library API.
 *
 * Build:  gcc -O2 -Wall -Wextra -o mood_light mood_light.c -ldriver -lasound
 * Run:    ./mood_light [sensitivity]
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/soundcard.h>
#include <driver.h>

/* ---- Pin assignments (BCM numbering) ---- */
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

/* ---- ALSA parameters ---- */
#define SAMPLE_RATE   8000
#define CHANNELS      1
#define PERIOD_SIZE   1024
#define ALSA_DEVICE   "default"

/* ---- PWM / LED parameters ---- */
#define PWM_PERIOD_US  1000   /* 1 kHz software PWM carrier */
#define PWM_DUTY_MAX   255    /* 8-bit resolution */
#define PWM_DUTY_OFF   0
#define PWM_DUTY_ON    255

/* ---- Defaults ---- */
#define DEFAULT_SENSITIVITY 1.0f
#define RMS_WINDOW_MS       10

/* ---- Globals for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_alsa_fd = -1;
static int  g_driver_fd = -1;
static bool g_alsa_available = false;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits and cleans up.        */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup — release all resources.                                  */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_driver_fd >= 0) {
        driver_ledOff(Red_PIN, GREEN_PIN, BLUE_PIN);
        driver_close(g_driver_fd);
        g_driver_fd = -1;
    }
    if (g_alsa_fd >= 0) {
        if (close(g_alsa_fd) < 0)
            perror("close(alsa)");
        g_alsa_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Software PWM helpers (driver library).                             */
/* ------------------------------------------------------------------ */
static void driver_ledOff(int r, int g, int b)
{
    driver_output_set_value(r, 0);
    driver_output_set_value(g, 0);
    driver_output_set_value(b, 0);
}

static void driver_ledOn(int r, int g, int b, int duty)
{
    if (duty < 0) duty = 0;
    if (duty > PWM_DUTY_MAX) duty = PWM_DUTY_MAX;

    int v = (r * duty) + (g * (PWM_DUTY_MAX - duty)) + (b * (duty - PWM_DUTY_MAX));

    if (v < 0) v = 0;
    if (v > PWM_DUTY_MAX) v = PWM_DUTY_MAX;

    driver_output_set_value(r, v);
    driver_output_set_value(g, v);
    driver_output_set_value(b, v);
}

/* ------------------------------------------------------------------ */
/* ALSA helpers                                                         */
/* ------------------------------------------------------------------ */
static int init_alsa(void)
{
    int fd = open(ALSA_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", ALSA_DEVICE, strerror(errno));
        return -1;
    }

    struct snd_pcm_hw_params *hw = NULL;
    int err = snd_pcm_hw_params_alloca(&hw);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_hw_params_alloca: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    /* 8000 Hz, 16-bit, mono, interleaved */
    err = snd_pcm_hw_params_set_access(hw, SND_PCM_ACCESS_RW_INTERLEAVED);
    if (err < 0) { fprintf(stderr, "set_access: %s\n", strerror(errno)); goto fail; }
    err = snd_pcm_hw_params_set_format(hw, SND_PCM_FORMAT_S16_LE);
    if (err < 0) { fprintf(stderr, "set_format: %s\n", strerror(errno)); goto fail; }
    err = snd_pcm_hw_params_set_channels(hw, CHANNELS);
    if (err < 0) { fprintf(stderr, "set_channels: %s\n", strerror(errno)); goto fail; }
    err = snd_pcm_hw_params_set_rate(hw, SAMPLE_RATE);
    if (err < 0) { fprintf(stderr, "set_rate: %s\n", strerror(errno)); goto fail; }

    snd_pcm_hw_params_set_period_size(hw, PERIOD_SIZE);

    err = snd_pcm_hw_params(hw, 0);
    if (err < 0) { fprintf(stderr, "snd_pcm_hw_params: %s\n", strerror(errno)); goto fail; }

    err = snd_pcm_open(fd, "default", SND_PCM_STREAM_CAPTURE, 0);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_open: %s\n", strerror(errno));
        goto fail;
    }

    g_alsa_fd = fd;
    g_alsa_available = true;
    return 0;

fail:
    if (hw)  snd_pcm_hw_params_free(hw);
    close(fd);
    return -1;
}

static void close_alsa(void)
{
    if (g_alsa_fd >= 0) {
        if (snd_pcm_drain(g_alsa_fd) < 0)
            perror("snd_pcm_drain");
        if (close(g_alsa_fd) < 0)
            perror("close(alsa)");
        g_alsa_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Audio capture                                                       */
/* ------------------------------------------------------------------ */
static int capture_audio(float *buffer, int len)
{
    int err = snd_pcm_readi(g_alsa_fd, buffer, len);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_readi: %s\n", strerror(errno));
        return -1;
    }
    if (err != len) {
        fprintf(stderr, "snd_pcm_readi: short read (%d of %d)\n", err, len);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* RMS computation                                                     */
/* ------------------------------------------------------------------ */
static float compute_rms(const float *buf, int len)
{
    double sum_sq = 0.0;
    for (int i = 0; i < len; i++) {
        double v = (double)buf[i];
        sum_sq += v * v;
    }
    return (float)sqrt(sum_sq / (double)len);
}

/* ------------------------------------------------------------------ */
/* Color mapping                                                         */
/* ------------------------------------------------------------------ */
static void map_amplitude_to_color(float amplitude, int *r, int *g, int *b)
{
    /* Clamp to 0..255 */
    if (amplitude < 0.0f) amplitude = 0.0f;
    if (amplitude > 1.0f) amplitude = 1.0f;

    float norm = amplitude / 1.0f;   /* 0..1 */
    float r_v = norm * 255.0f;
    float g_v = norm * 255.0f;
    float b_v = norm * 255.0f;

    if (r_v < 0.0f) r_v = 0.0f;
    if (r_v > 255.0f) r_v = 255.0f;
    if (g_v < 0.0f) g_v = 0.0f;
    if (g_v > 255.0f) g_v = 255.0f;
    if (b_v < 0.0f) b_v = 0.0f;
    if (b_v > 255.0f) b_v = 255.0f;

    *r = (int)(r_v + 0.5f);
    *g = (int)(g_v + 0.5f);
    *b = (int)(b_v + 0.5f);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    const char *device = (argc > 1) ? argv[1] : ALSA_DEVICE;

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- ALSA availability ---- */
    if (init_alsa() < 0) {
        fprintf(stderr, "Audio capture unavailable (ALSA not configured).\n");
        return EXIT_FAILURE;
    }

    /* ---- Driver init ---- */
    g_driver_fd = driver_init();
    if (g_driver_fd < 0) {
        fprintf(stderr, "driver_init failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- GPIO setup ---- */
    if (driver_set_mode(Red_PIN,  DRIVER_MODE_OUTPUT) < 0 ||
        driver_set_mode(GREEN_PIN, DRIVER_MODE_OUTPUT) < 0 ||
        driver_set_mode(BLUE_PIN,  DRIVER_MODE_OUTPUT) < 0) {
        fprintf(stderr, "driver_set_mode failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Start with LEDs off */
    driver_ledOff(Red_PIN, GREEN_PIN, BLUE_PIN);

    /* ---- Main loop ---- */
    while (g_running) {
        float audio_buffer[PERIOD_SIZE];
        int  bytes_read = 0;

        while (bytes_read < PERIOD_SIZE && g_running) {
            int err = capture_audio(audio_buffer + bytes_read, PERIOD_SIZE - bytes_read);
            if (err < 0) {
                fprintf(stderr, "Audio capture error, resuming.\n");
                if (snd_pcm_prepare(g_alsa_fd) < 0)
                    perror("snd_pcm_prepare");
                continue;
            }
            bytes_read += err;
        }

        if (!g_running) break;

        float rms = compute_rms(audio_buffer, PERIOD_SIZE);
        int r, g, b;
        map_amplitude_to_color(rms, &r, &g, &b);

        driver_ledOn(Red_PIN, GREEN_PIN, BLUE_PIN, PWM_DUTY_ON);
        usleep(10000);   /* 10 ms */
        driver_ledOff(Red_PIN, GREEN_PIN, BLUE_PIN);

        usleep(10000);   /* 10 ms */
    }

    /* ---- Graceful shutdown ---- */
    driver_ledOff(Red_PIN, GREEN_PIN, BLUE_PIN);
    cleanup();
    return EXIT_SUCCESS;
}

