#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define TCS34725_ADDRESS 0x29
#define TCS34725_COMMAND_BIT 0x80
#define TCS34725_ENABLE 0x00
#define TCS34725_ATIME 0x01
#define TCS34725_CONTROL 0x0F
#define TCS34725_ID 0x12
#define TCS34725_CDATA 0x14
#define TCS34725_RDATA 0x16
#define TCS34725_GDATA 0x18
#define TCS34725_BDATA 0x1A

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int tcs34725_write_reg(uint8_t reg, uint8_t value) {
    char buf[2] = { (char)(reg | TCS34725_COMMAND_BIT), (char)value };
    if (i2cWriteDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error writing reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int tcs34725_init(void) {
    int id = i2cReadByteData(i2c_handle, TCS34725_ID);
    if (id < 0) {
        fprintf(stderr, "Error reading ID register: %s\n", strerror(errno));
        return -1;
    }
    if (id != 0x44) {
        fprintf(stderr, "Unexpected ID 0x%02X (expected 0x44)\n", id);
        return -1;
    }

    if (tcs34725_write_reg(TCS34725_ENABLE, 0x03) != 0) return -1;
    if (tcs34725_write_reg(TCS34725_ATIME, 0x33) != 0) return -1;
    if (tcs34725_write_reg(TCS34725_CONTROL, 0x03) != 0) return -1;
    return 0;
}

static int tcs34725_read_data(uint16_t *c, uint16_t *r, uint16_t *g, uint16_t *b) {
    char buf[8];
    if (i2cReadI2CBlockData(i2c_handle, TCS34725_CDATA, buf, 8) != 8) {
        fprintf(stderr, "Error reading color data: %s\n", strerror(errno));
        return -1;
    }
    *c = (uint16_t)((buf[1] << 8) | buf[0]);
    *r = (uint16_t)((buf[3] << 8) | buf[2]);
    *g = (uint16_t)((buf[5] << 8) | buf[4]);
    *b = (uint16_t)((buf[7] << 8) | buf[6]);
    return 0;
}

static void log_data(uint16_t c, uint16_t r, uint16_t g, uint16_t b) {
    time_t now = time(NULL);
    fprintf(fp, "%ld,%u,%u,%u\n", (long)now, c, r, g, b);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting up signal handlers: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, TCS34725_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (tcs34725_init() != 0) {
        fprintf(stderr, "TCS34725 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    fp = fopen("color_data.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "timestamp,c,r,g,b\n");
    }

    uint16_t c, r, g, b;
    while (running) {
        if (tcs34725_read_data(&c, &r, &g, &b) == 0) {
            log_data(c, r, g, b);
        } else {
            fprintf(stderr, "Sensor read failed, logging zeros\n");
            c = r = g = b = 0;
        }
        gpioDelay(500000);
    }

    fprintf(stderr, "\nShutting down cleanly...\n");
    if (fp) fclose(fp);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

