#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RELAY1_PIN 17
#define RELAY2_PIN 27
#define RELAY3_PIN 22
#define RELAY4_PIN 23

#define SUNRISE_DURATION 3600
#define DAYTIME_DURATION 3600 * 6
#define SUNSET_DURATION 3600
#define NIGHTTIME_DURATION 3600 * 14

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_all_relays(int state) {
    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (int i = 0; i < 4; i++) {
        if (gpioWrite(pins[i], state) != 0) {
            fprintf(stderr, "Error: gpioWrite failed on pin %d\n", pins[i]);
            return -1;
        }
    }
    return 0;
}

static int sunrise_phase(void) {
    for (int i = 0; i < SUNRISE_DURATION && running; i++) {
        int duty = (i * 255) / SUNRISE_DURATION;
        if (gpioWrite(RELAY1_PIN, duty > 0 ? 1 : 0) != 0 ||
            gpioWrite(RELAY2_PIN, duty > 0 ? 1 : 0) != 0 ||
            gpioWrite(RELAY3_PIN, duty > 0 ? 1 : 0) != 0 ||
            gpioWrite(RELAY4_PIN, duty > 0 ? 1 : 0) != 0) {
            fprintf(stderr, "Error: gpioWrite failed during sunrise\n");
            return -1;
        }
        gpioDelay(1000000);
    }
    return 0;
}

static int daytime_phase(void) {
    for (int i = 0; i < DAYTIME_DURATION && running; i++) {
        int duty = (i * 255) / DAYTIME_DURATION;
        if (gpioWrite(RELAY1_PIN, duty > 0 ? 1 : 0) != 0 ||
            gpioWrite(RELAY2_PIN, duty > 0 ? 1 : 0) != 0 ||
            gpioWrite(RELAY3_PIN, duty > 0 ? 1 : 0) != 0 ||
            gpioWrite(RELAY4_PIN, duty > 0 ? 1 : 0) != 0) {
            fprintf(stderr, "Error: gpioWrite failed during daytime\n");
            return -1;
        }
        gpioDelay(1000000);
    }
    return 0;
}

static int sunset_phase(void) {
    for (int i = 0; i < SUNSET_DURATION && running; i++) {
        int duty = (i * 255) / SUNSET_DURATION;
        if (gpioWrite(RELAY1_PIN, duty > 0 ? 1 : 0) != 0 ||
            gpioWrite(RELAY2_PIN, duty > 0 ? 1 : 0) != 0 ||
            gpioWrite(RELAY3_PIN, duty > 0 ? 1 : 0) != 0 ||
            gpioWrite(RELAY4_PIN, duty > 0 ? 1 : 0) != 0) {
            fprintf(stderr, "Error: gpioWrite failed during sunset\n");
            return -1;
        }
        gpioDelay(1000000);
    }
    return 0;
}

static int nighttime_phase(void) {
    for (int i = 0; i < NIGHTTIME_DURATION && running; i++) {
        int duty = (i * 255) / NIGHTTIME_DURATION;
        if (gpioWrite(RELAY1_PIN, duty > 0 ? 1 : 0) != 0 ||
            gpioWrite(RELAY2_PIN, duty > 0 ? 1 : 0) != 0 ||
            gpioWrite(RELAY3_PIN, duty > 0 ? 1 : 0) != 0 ||
            gpioWrite(RELAY4_PIN, duty > 0 ? 1 : 0) != 0) {
            fprintf(stderr, "Error: gpioWrite failed during nighttime\n");
            return -1;
        }
        gpioDelay(1000000);
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (int i = 0; i < 4; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode failed on pin %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioWrite(pins[i], 0) != 0) {
            fprintf(stderr, "Error: gpioWrite failed on pin %d during init\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    printf("Sunrise simulation started. Press Ctrl+C to exit.\n");

    while (running) {
        if (sunrise_phase() != 0) break;
        if (!running) break;
        if (daytime_phase() != 0) break;
        if (!running) break;
        if (sunset_phase() != 0) break;
        if (!running) break;
        if (nighttime_phase() != 0) break;
    }

    if (!running) {
        printf("\nShutting down...\n");
        set_all_relays(0);
        gpioTerminate();
        return EXIT_SUCCESS;
    }

    fprintf(stderr, "Error: signal received but running flag is still set\n");
    set_all_relays(0);
    gpioTerminate();
    return EXIT_FAILURE;
}

