#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_PIN 17
#define DEBOUNCE_MS 200
#define VIDEO_DURATION_SEC 5
#define VIDEO_DIR "/home/pi/videos"
#define LOG_FILE "/home/pi/logs/motion_log.txt"
#define POLL_TIMEOUT_MS 1000

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error: Failed to open GPIO chip %s: %s\n",
                GPIO_CHIP_NAME, strerror(errno));
        return -1;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error: Failed to get GPIO line %d: %s\n",
                GPIO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }

    if (gpiod_line_request_input(line, "ky033-motion") < 0) {
        fprintf(stderr, "Error: Failed to request GPIO line %d as input: %s\n",
                GPIO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        line = NULL;
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void) {
    if (line) {
        gpiod_line_release(line);
        line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

static int init_log(void) {
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file %s: %s\n",
                LOG_FILE, strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup_log(void) {
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

static int init_video_dir(void) {
    struct stat st;
    if (stat(VIDEO_DIR, &st) == -1) {
        if (errno != ENOENT) {
            fprintf(stderr, "Error: stat(%s) failed: %s\n",
                    VIDEO_DIR, strerror(errno));
            return -1;
        }
        if (mkdir(VIDEO_DIR, 0755) == -1 && errno != EEXIST) {
            fprintf(stderr, "Error: Failed to create directory %s: %s\n",
                    VIDEO_DIR, strerror(errno));
            return -1;
        }
    }
    return 0;
}

static int capture_video(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char filename[64];
    char command[256];
    int ret = -1;

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (!timeinfo) {
        fprintf(stderr, "Error: localtime() failed\n");
        return -1;
    }

    strftime(filename, sizeof(filename), "%Y%m%d_%H%M%S.h264", timeinfo);

    snprintf(command, sizeof(command),
             "raspivid -t %d -o %s", VIDEO_DURATION_SEC, filename);

    printf("Capturing video: %s\n", filename);

    int status = system(command);
    if (status == -1) {
        fprintf(stderr, "Error: system() failed to execute raspivid: %s\n",
                strerror(errno));
        return -1;
    }
    if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
        fprintf(stderr, "Error: raspivid exited with status %d\n",
                WIFEXITED(status) ? WEXITSTATUS(status) : -1);
        return -1;
    }

    printf("Video capture complete.\n");
    return 0;
}

static void log_motion_event(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (!timeinfo) {
        fprintf(stderr, "Error: localtime() failed\n");
