#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define MPU6050_PWR_MGMT_1 0x6B
#define MPU6050_GYRO_CONFIG 0x1B
#define MPU6050_GYRO_XOUT_H 0x43
#define GYRO_SCALE 131.0
#define LOG_FILE "gyro_log.csv"
#define SAMPLE_INTERVAL_US 10000
#define MAX_REINIT_ATTEMPTS 3

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int mpu6050_init(int fd) {
    if (i2c_write_reg8(fd, MPU6050_PWR_MGMT_1, 0x00) < 0) return -1;
    usleep(100000);
    if (i2c_write_reg8(fd, MPU6050_GYRO_CONFIG, 0x00) < 0) return -1;
    return 0;
}

static int mpu6050_read_gyro(int fd, float *x, float *y, float *z) {
    uint8_t buf[6];
    if (read(fd, buf, 6) != 6) {
        fprintf(stderr, "I2C read of gyro data failed: %s\n", strerror(errno));
        return -1;
    }
    int16_t raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_y = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t raw_z = (int16_t)((buf[4] << 8) | buf[5]);
    *x = (float)raw_x / GYRO_SCALE;
    *y = (float)raw_y / GYRO_SCALE;
    *z = (float)raw_z / GYRO_SCALE;
    return 0;
}

static void log_data(FILE *fp, time_t timestamp, float x, float y, float z) {
    struct tm *tm_info = localtime(&timestamp);
    char ts_str[32];
    strftime(ts_str, sizeof(ts_str), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(fp, "%s.%03ld,%.2f,%.2f,%.2f\n", ts_str, (long)(timestamp % 1000), x, y, z);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (mpu6050_init(i2c_fd) < 0) {
        fprintf(stderr, "MPU6050 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    fseek(log_fp, 0, SEEK_END);
    if (ftell(log_fp) == 0) {
        fprintf(log_fp, "timestamp,gyro_x_degps,gyro_y_degps,gyro_z_degps\n");
    }

    printf("Logging gyroscope data to %s. Press Ctrl+C to stop.\n", LOG_FILE);

    while (running) {
        float x, y, z;
        if (mpu6050_read_gyro(i2c_fd, &x, &y, &z) == 0) {
            time_t now = time(NULL);
            log_data(log_fp, now, x, y, z);
        } else {
            fprintf(stderr, "Gyroscope read failed. Re-initializing sensor...\n");
            for (int attempt = 0; attempt < MAX_REINIT_ATTEMPTS; attempt++) {
                if (mpu6050_init(i2c_fd) == 0) {
                    printf("Re-initialization successful (attempt %d/%d).\n", attempt + 1, MAX_REINIT_ATTEMPTS);
                    break;
                }
                fprintf(stderr, "Re-initialization attempt %d failed.\n", attempt + 1);
                if (attempt < MAX_REINIT_ATTEMPTS - 1) {
                    usleep(100000);
                }
            }
            if (attempt == MAX_REINIT_ATTEMPTS) {
                fprintf(stderr, "Max re-initialization attempts reached. Continuing with last valid data.\n");
            }
        }
        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    if (log_fp) fclose(log_fp);
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

