#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define RELAY_ZONE_1 4
#define RELAY_ZONE_2 17
#define RELAY_ZONE_3 27
#define RELAY_ZONE_4 22
#define MOISTURE_THRESHOLD 30
#define LOG_FILE "irrigation_log.txt"
#define SLEEP_DURATION 5

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    int pins[] = {RELAY_ZONE_1, RELAY_ZONE_2, RELAY_ZONE_3, RELAY_ZONE_4};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioWrite(pins[i], 1) != 0) {
            fprintf(stderr, "Error: failed to initialize GPIO %d HIGH\n", pins[i]);
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

static int read_moisture_sensor(int zone) {
    return (rand() % 100) + 30;
}

static void control_relay(int zone, int moisture_level) {
    int relay_pin = RELAY_ZONE_1 + (zone - 1);
    int state = (moisture_level < MOISTURE_THRESHOLD) ? 0 : 1;
    if (gpioWrite(relay_pin, state) != 0) {
        fprintf(stderr, "Error: failed to write GPIO %d\n", relay_pin);
    }
}

static void log_data(int moisture_level, int relay_states[]) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Moisture: %d, Relays: ", timestamp, moisture_level);
    for (int i = 0; i < 4; i++) {
        fprintf(log_file, "Zone%d=%s", i + 1,
                (relay_states[i] == 0) ? "ON" : "OFF");
    }
    fprintf(log_file, "\n");
    fflush(log_file);
}

static void cleanup(void) {
    for (int i = 0; i < 4; i++) {
        gpioWrite(RELAY_ZONE_1 + i, 1);
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (initialize_gpio() != 0) {
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    srand(time(NULL));

    int relay_states[4] = {0, 0, 0, 0};

    while (running) {
        int moisture_level = read_moisture_sensor(1);
        control_relay(1, moisture_level);
        relay_states[0] = 0;

        moisture_level = read_moisture_sensor(2);
        control_relay(2, moisture_level);
        relay_states[1] = 0;

        moisture_level = read_moisture_sensor(3);
        control_relay(3, moisture_level);
        relay_states[2] = 0;

        moisture_level = read_moisture_sensor(4);
        control_relay(4, moisture_level);
        relay_states[3] = 0;

        log_data(moisture_level, relay_states);
        sleep(SLEEP_DURATION);
    }

    cleanup();
    return 0;
}

