/*
 * ADXL345 Free-Fall Detector for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   ADXL345 SDA -> GPIO2 (I2C1 SDA, pin 3)
 *   ADXL345 SCL -> GPIO3 (I2C1 SCL, pin 5)
 *   ADXL345 VDD -> 3.3 V
 *   ADXL345 GND -> GND
 *   Alarm LED/Buzzer -> GPIO27 (BCM 27, pin 13) via ~330 Ω resistor
 *
 * Build: gcc -O2 -Wall -o freefall freefall.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- ADXL345 constants ---- */
#define ADXL345_I2C_ADDR      0x2D
#define ADXL345_REG_DEVID     0x00
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_DATA_FORMAT 0x31
#define ADXL345_REG_DATAX0    0x32
#define ADXL345_DEVID         0xE5
#define ADXL345_POWER_CTL_PON 0x08
#define ADXL345_DATA_FORMAT_BW_100_HZ 0x0B
#define ADXL345_BW_100_HZ     0x0B

/* ---- Application constants ---- */
#define I2C_BUS              "/dev/i2c-1"
#define ALARM_GPIO           27
#define FREEFALL_THRESHOLD   0.2f   /* g */
#define FREEFALL_DURATION    0.5    /* seconds */
#define CONFIRMATION_DELAY   0.5    /* seconds */
#define ALARM_DURATION       5.0    /* seconds */
#define POLL_INTERVAL_US     100000 /* 100 ms */
#define LOG_FILE             "freefall.log"

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to an 8-bit register. Returns 0 on success, -1 on error. */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write_reg8(0x%02X, 0x%02X) failed: %s (wrote %zd bytes)\n",
                reg, value, strerror(errno), n);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from an 8-bit register. Returns 0 on success, -1 on error. */
static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "i2c_read_reg8: write(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    n = read(fd, out, 1);
    if (n != 1) {
        fprintf(stderr, "i2c_read_reg8: read(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read 6 bytes of acceleration data starting at REG_DATAX0.
 * Returns 0 on success, -1 on error. */
static int read_acceleration(int fd, float *x, float *y, float *z)
{
    uint8_t buf[6];
    ssize_t n = read(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "read_acceleration: read failed: %s (got %zd bytes)\n",
                strerror(errno), n);
        return -1;
    }
    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);
    *x = (float)raw_x / 8192.0f;   /* 4 mg/LSB at ±2 g, 16-bit signed */
    *y = (float)raw_y / 8192.0f;
    *z = (float)raw_z / 8192.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
static bool is_freefall(float x, float y, float z)
{
    return (fabsf(x) < FREEFALL_THRESHOLD &&
            fabsf(y) < FREEFALL_THRESHOLD &&
            fabsf(z) < FREEFALL_THRESHOLD);
}

/* ------------------------------------------------------------------ */
static void log_freefall(float x, float y, float z)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "log_freefall: cannot open %s: %s\n",
                LOG_FILE, strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.3f,%.3f,%.3f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                x, y, z);
    }
    fclose(fp);
}

/* ------------------------------------------------------------------ */
static void trigger_alarm(void)
{
    if (g_i2c_fd >= 0) {
        fprintf(stderr, "Warning: I2C handle still open; closing.\n");
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_running) {
        printf("Free-fall detected! Triggering alarm on GPIO%d for %d s.\n",
               ALARM_GPIO, ALARM_DURATION);
        if (g_i2c_fd >= 0) {
            /* Put ADXL345 into standby to save power while alarm is active. */
            (void)i2c_write_reg8(g_i2c_fd, ADXL345_REG_POWER_CTL, 0x00);
        }
        if (g_i2c_fd >= 0) {
            if (ioctl(g_i2c_fd, I2C_SLAVE, ADXL345_I2C_ADDR) < 0) {
                fprintf(stderr, "ioctl(I2C_SLAVE) failed: %s\n", strerror(errno));
            } else {
                /* Re-open I2C to the ADXL345 so the alarm can be asserted. */
                (void)i2c_write_reg8(g_i2c_fd, ADXL345_REG_POWER_CTL, ADXL345_POWER_CTL_PON);
            }
        }
        if (g_i2c_fd >= 0) {
            (void)i2c_write_reg8(g_i2c_fd, ADXL345_REG_POWER_CTL, ADXL345_POWER_CTL_PON);
        }
        if (g_i2c_fd >= 0) {
            (void)i2c_write_reg8(g_i2c_fd, ADXL345_REG_DATA_FORMAT, ADXL345_BW_100_HZ);
        }
        if (g_i2c_fd >= 0) {
            (void)i2c_write_reg8(g_i2c_fd, ADXL345_REG_POWER_CTL, ADXL345_POWER_CTL_PON);
        }
        if (g_i2c_fd >= 0) {
            (void)i2c_write_reg8(g_i2c_fd, ADXL345_REG_DEVID, ADXL345_DEVID);
        }
        if (g_i2c_fd >= 0) {
            (void)i2c_write_reg8(g_i2c_fd, ADXL345_REG_DATA_FORMAT, ADXL345_BW_100_HZ);
        }
        if (g_i2c_fd >= 0) {
            (void)i2c_write_reg8(g_i2c_fd, ADXL345_REG_POWER_CTL, ADXL345_POWER_CTL_PON);
        }
        if (g_i2c_fd >= 0) {
            (void)i2c_write_reg8(g_i2c_fd, ADXL345_REG_DEVID, ADXL345_DEVID);
        }
        if (g_i2c_fd >= 0) {
            (void)i2c_write_reg8(g_i2c_fd, ADXL345_REG_DATA_FORMAT, ADXL345_BW_100_HZ);
        }
        if (g_i2c_fd >= 0) {
            (void)i2c_write_reg8(g_i2c_fd, ADXL345_REG_POWER_CTL, ADXL345_POWER_CTL_PON);
        }
        /* Use a separate thread for the alarm so the main loop can keep polling. */
        /* In a real production environment, the alarm would be handled by a
           dedicated thread or a hardware watchdog. For this example we just
           sleep in the main loop. */
        sleep(ALARM_DURATION);
        if (g_i2c_fd >= 0) {
            (void)i2c_write_reg8(g_i2c_fd, ADXL345_REG_POWER_CTL, 0x00);
        }
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Verify device identity ---- */
    uint8_t devid = 0;
    if (i2c_read_reg8(g_i2c_fd, ADXL345_REG_DEVID, &devid) < 0) {
        fprintf(stderr, "Cannot read DEVID register.\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }
    if (devid != ADXL345_DEVID) {
        fprintf(stderr, "ADXL345 not found (DEVID=0x%02X, expected 0x%02X).\n",
                devid, ADXL345_DEVID);
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* ---- Configure ADXL345 ---- */
    if (i2c_write_reg8(g_i2c_fd, ADXL345_REG_POWER_CTL, 0x00) < 0) {
        fprintf(stderr, "Cannot put ADXL345 in standby.\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }
    if (i2c_write_reg8(g_i2c_fd, ADXL345_REG_DATA_FORMAT, ADXL345_BW_100_HZ) < 0) {
        fprintf(stderr, "Cannot set data format.\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }
    if (i2c_write_reg8(g_i2c_fd, ADXL345_REG_POWER_CTL, ADXL345_POWER_CTL_PON) < 0) {
        fprintf(stderr, "Cannot power on ADXL345.\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* ---- Configure alarm GPIO ---- */
    if (gpioSetMode(ALARM_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d) failed.\n", ALARM_GPIO);
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }
    if (gpioWrite(ALARM_GPIO, 0) < 0) {
        fprintf(stderr, "gpioWrite(%d, 0) failed.\n", ALARM_GPIO);
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("ADXL345 free-fall detector running. Press Ctrl+C to exit.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        float x, y, z;
        if (read_acceleration(g_i2c_fd, &x, &y, &z) < 0) {
            /* I2C error: keep polling, don't abort. */
            usleep(POLL_INTERVAL_US);
            continue;
        }

        if (is_freefall(x, y, z)) {
            /* First detection: log and start alarm timer. */
            log_freefall(x, y, z);
            if (g_running) {
                time_t start = time(NULL);
                printf("Free-fall detected! Waiting %d s for confirmation...\n",
                       CONFIRMATION_DELAY);
                while (g_running) {
                    time_t now = time(NULL);
                    if (difftime(now, start) >= CONFIRMATION_DELAY) {
                        if (is_freefall(x, y, z)) {
                            printf("Free-fall confirmed!\n");
                            trigger_alarm();
                        }
                        break;
                    }
                    usleep(POLL_INTERVAL_US);
                }
            }
        }
        usleep(POLL_INTERVAL_US);
    }

    /* ---- Cleanup ---- */
    if (g_i2c_fd >= 0) {
        (void)i2c_write_reg8(g_i2c_fd, ADXL345_REG_POWER_CTL, 0x00);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    gpioWrite(ALARM_GPIO, 0);
    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

