/*
 * HC-SR04 ultrasonic distance measurement on Raspberry Pi Zero W.
 *
 * Wiring:
 *   HC-SR04 TRIG -> GPIO4  (BCM 4, physical pin 7)
 *   HC-SR04 ECHO -> GPIO18 (BCM 18, physical pin 12)
 *   HC-SR04 VCC  -> 5 V (physical pin 2 or 4)
 *   HC-SR04 GND  -> GND  (physical pin 6)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o hcsr04_log hcsr04_log.c -lpigpio -lpthread
 *
 * Run:
 *   sudo ./hcsr04_log
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

#define TRIGGER_PIN      4
#define ECHO_PIN         18

#define TRIGGER_PULSE_US 10
#define TRIGGER_CYCLE_US  200000   /* 200 ms between triggers */
#define ECHO_TIMEOUT_US   100000   /* 100 ms max echo wait */
#define MAX_PULSE_US      23200    /* ~4 m round-trip; datasheet: 23.2 ms max */
#define LOG_FILE_NAME     "distance_log.txt"

/* ------------------------------------------------------------------ */
/* Shared state between the ISR and the main thread                   */
/* ------------------------------------------------------------------ */

typedef struct {
    volatile uint32_t start_tick;
    volatile uint32_t end_tick;
    volatile bool     got_rising;
    volatile bool     got_falling;
    pthread_mutex_t  mtx;
} echo_state_t;

static echo_state_t g_echo;
static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

static void timestamp_ns(long *ts)
{
    struct timespec ts_local;
    if (clock_gettime(CLOCK_REALTIME, &ts_local) != 0) {
        *ts = 0;
        return;
    }
    *ts = (long)ts_local.tv_sec * 1000000000L + ts_local.tv_nsec;
}

static void log_error(const char *msg)
{
    FILE *fp = fopen(LOG_FILE_NAME, "a");
    if (fp) {
        fprintf(fp, "%ld,ERROR,%s\n", (long)timestamp_ns(&g_echo.start_tick), msg);
        fclose(fp);
    }
    fprintf(stderr, "%s\n", msg);
}

/* ------------------------------------------------------------------ */
/* ISR callbacks (pigpio dispatches these on its own thread)           */
/* ------------------------------------------------------------------ */

static void echo_rising_cb(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level != 1) return;

    echo_state_t *st = (echo_state_t *)userdata;
    pthread_mutex_lock(&st->mtx);

    if (st->got_rising) {
        /* Falling edge missing — timeout */
        pthread_mutex_unlock(&st->mtx);
        return;
    }

    st->start_tick  = tick;
    st->got_rising  = true;
    st->got_falling = false;

    pthread_mutex_unlock(&st->mtx);
}

static void echo_falling_cb(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level != 0) return;

    echo_state_t *st = (echo_state_t *)userdata;
    pthread_mutex_lock(&st->mtx);

    if (!st->got_rising) {
        pthread_mutex_unlock(&st->mtx);
        return;
    }

    st->end_tick    = tick;
    st->got_falling = true;

    pthread_mutex_unlock(&st->mtx);
}

/* ------------------------------------------------------------------ */
/* Trigger pulse generation                                          */
/* ------------------------------------------------------------------ */

static void trigger_pulse(void)
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

/* ------------------------------------------------------------------ */
/* Measurement                                                         */
/* ------------------------------------------------------------------ */

static bool measure_distance(double *distance_cm)
{
    echo_state_t *st = &g_echo;

    /* Reset state */
    pthread_mutex_lock(&st->mtx);
    st->start_tick  = 0;
    st->end_tick    = 0;
    st->got_rising  = false;
    st->got_falling = false;
    pthread_mutex_unlock(&st->mtx);

    /* Issue a fresh trigger */
    trigger_pulse();

    /* Wait for the echo with a timeout */
    uint32_t waited = 0;
    while (!st->got_falling && waited < ECHO_TIMEOUT_US) {
        gpioDelay(1000); /* 1 ms */
        waited += 1000;
    }

    if (!st->got_falling) {
        log_error("Echo timeout: no falling edge received within 100 ms");
        return false;
    }

    /* Compute pulse width (pigpio ticks are 32-bit microseconds) */
    uint32_t pw = st->end_tick - st->start_tick;

    if (pw > MAX_PULSE_US) {
        log_error("Invalid pulse width exceeds sensor range");
        return false;
    }

    /* distance = (pulse_us * 34300 cm/s) / 2 / 1e6 */
    *distance_cm = (double)pw * 0.01715;
    return true;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */

static void log_distance(double distance_cm)
{
    long ts;
    timestamp_ns(&ts);

    if (fprintf(g_log_fp, "%ld,%.2f\n", ts, distance_cm) < 0) {
        log_error("Failed to write to log file");
        return;
    }
    fflush(g_log_fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */

static void cleanup(void)
{
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);
    gpioSetAlertFuncEx(TRIGGER_PIN, NULL, NULL);

    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }

    gpioTerminate();
    pthread_mutex_destroy(&g_echo.mtx);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- GPIO configuration ---- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set TRIGGER_PIN %d as output\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set ECHO_PIN %d as input\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts LOW */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(50000); /* 50 ms settle */

    /* ---- Open log file ---- */
    g_log_fp = fopen(LOG_FILE_NAME, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Failed to open log file '%s'\n", LOG_FILE_NAME);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Mutex ---- */
    if (pthread_mutex_init(&g_echo.mtx, NULL) != 0) {
        log_error("Mutex init failed");
        fclose(g_log_fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Register ISR callbacks ---- */
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_rising_cb, NULL) != 0) {
        log_error("Failed to register rising-edge echo callback");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetAlertFuncEx(TRIGGER_PIN, echo_falling_cb, NULL) != 0) {
        log_error("Failed to register falling-edge trigger callback");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Signal handling ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        log_error("Failed to install SIGINT handler");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance logger started. Logging to '%s'. Press Ctrl+C to stop.\n",
           LOG_FILE_NAME);

    /* ---- Main loop ---- */
    while (g_running) {
        double distance_cm;

        if (measure_distance(&distance_cm)) {
            log_distance(distance_cm);
        }

        /* 200 ms between triggers (minus ~10 ms pulse width) */
        gpioDelay(TRIGGER_CYCLE_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

