code:
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* LIS3DH I2C address (SA0 tied to GND) */
#define LIS3DH_ADDR 0x19

/* LIS3DH register addresses */
#define LIS3DH_CTRL_REG1 0x20
#define LIS3DH_CTRL_REG4 0x23
#define LIS3DH_OUT_X_L  0x28
#define LIS3DH_WHO_AM_I 0x0F

/* Expected WHO_AM_I response */
#define LIS3DH_WHO_AM_I_VAL 0x33

/* Free-fall and impact thresholds (default: 0.2 g and 1.5 g) */
#define DEFAULT_FREEFALL_THRESHOLD 0.2
#define DEFAULT_IMPACT_THRESHOLD   1.5

/* Buzzer GPIO pin (BCM numbering) */
#define BUZZER_PIN 17

/* I2C bus on Raspberry Pi 5 */
#define I2C_BUS 1

/* I2C retry count */
#define I2C_RETRIES 3

/* Global state */
static int i2c_handle = -1;
static volatile sig_atomic_t program_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers with retry                                             */
/* ------------------------------------------------------------------ */
static int i2c_write_reg(uint8_t reg, uint8_t value)
{
    for (int attempt = 0; attempt < I2C_RETRIES; attempt++) {
        int rc = i2cWriteByteData(i2c_handle, reg, value);
        if (rc == 0)
            return 0;
        fprintf(stderr, "I2C write reg 0x%02X failed (attempt %d/%d): %d\n",
                reg, attempt + 1, I2C_RETRIES, rc);
        gpioDelay(10000); /* 10 ms back-off */
