#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MOTOR1_IN1 4
#define MOTOR1_IN2 17
#define MOTOR1_IN3 27
#define MOTOR1_IN4 22

#define MOTOR2_IN1 5
#define MOTOR2_IN2 6
#define MOTOR2_IN3 13
#define MOTOR2_IN4 19

#define STEP_DELAY_US 1000
#define STEPS_PER_REV 2048
#define GEAR_RATIO 64.0

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int safe_set_mode(unsigned gpio, unsigned mode) {
    if (gpioSetMode(gpio, mode) < 0) {
        fprintf(stderr, "Error: gpioSetMode(%u, %u) failed\n", gpio, mode);
        return -1;
    }
    return 0;
}

static int safe_write(unsigned gpio, unsigned level) {
    if (gpioWrite(gpio, level) < 0) {
        fprintf(stderr, "Error: gpioWrite(%u, %u) failed\n", gpio, level);
        return -1;
    }
    return 0;
}

static int safe_set_all_outputs(unsigned gpio1, unsigned gpio2, unsigned gpio3, unsigned gpio4) {
    if (safe_set_mode(gpio1, PI_OUTPUT) < 0) return -1;
    if (safe_set_mode(gpio2, PI_OUTPUT) < 0) return -1;
    if (safe_set_mode(gpio3, PI_OUTPUT) < 0) return -1;
    if (safe_set_mode(gpio4, PI_OUTPUT) < 0) return -1;
    return 0;
}

static int safe_write_all_outputs(unsigned gpio1, unsigned gpio2, unsigned gpio3, unsigned gpio4, unsigned level1, unsigned level2, unsigned level3, unsigned level4) {
    if (safe_write(gpio1, level1) < 0) return -1;
    if (safe_write(gpio2, level2) < 0) return -1;
    if (safe_write(gpio3, level3) < 0) return -1;
    if (safe_write(gpio4, level4) < 0) return -1;
    return 0;
}

static int initialize_motor(unsigned in1, unsigned in2, unsigned in3, unsigned in4) {
    if (safe_set_all_outputs(in1, in2, in3, in4) < 0) return -1;
    return 0;
}

static int step_motor(unsigned in1, unsigned in2, unsigned in3, unsigned in4, int direction) {
    if (direction == 0) {
        if (safe_write(in1, 0) < 0) return -1;
        if (safe_write(in2, 1) < 0) return -1;
        if (safe_write(in3, 0) < 0) return -1;
        if (safe_write(in4, 0) < 0) return -1;
        return 0;
    } else if (direction == 1) {
        if (safe_write(in1, 1) < 0) return -1;
        if (safe_write(in2, 0) < 0) return -1;
        if (safe_write(in3, 1) < 0) return -1;
        if (safe_write(in4, 0) < 0) return -1;
        return 0;
    } else {
        if (safe_write(in1, 0) < 0) return -1;
        if (safe_write(in2, 0) < 0) return -1;
        if (safe_write(in3, 1) < 0) return -1;
        if (safe_write(in4, 1) < 0) return -1;
        return 0;
    }
}

static int calculate_steps(float distance, float step_length) {
    return (int)(distance / step_length);
}

static int move_motor(unsigned in1, unsigned in2, unsigned in3, unsigned in4, float distance) {
    int steps = calculate_steps(distance, STEPS_PER_REV * GEAR_RATIO);
    for (int i = 0; i < steps && running; i++) {
        if (step_motor(in1, in2, in3, in4, i % 2) < 0) {
            fprintf(stderr, "Error: Failed to step motor\n");
            return -1;
        }
        gpioDelay(STEP_DELAY_US);
    }
    return steps;
}

static int move_square(float side_length) {
    if (move_motor(MOTOR1_IN1, MOTOR1_IN2, MOTOR1_IN3, MOTOR1_IN4, side_length) < 0) return -1;
    if (move_motor(MOTOR2_IN1, MOTOR2_IN2, MOTOR2_IN3, MOTOR2_IN4, side_length) < 0) return -1;
    return 0;
}

static void cleanup(void) {
    safe_write(MOTOR1_IN1, 0);
    safe_write(MOTOR1_IN2, 0);
    safe_write(MOTOR1_IN3, 0);
    safe_write(MOTOR1_IN4, 0);
    safe_write(MOTOR2_IN1, 0);
    safe_write(MOTOR2_IN2, 0);
    safe_write(MOTOR2_IN3, 0);
    safe_write(MOTOR2_IN4, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (initialize_motor(MOTOR1_IN1, MOTOR1_IN2, MOTOR1_IN3, MOTOR1_IN4) < 0) {
        fprintf(stderr, "Error: Motor 1 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (initialize_motor(MOTOR2_IN1, MOTOR2_IN2, MOTOR2_IN3, MOTOR2_IN4) < 0) {
        fprintf(stderr, "Error: Motor 2 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Moving 50mm square...\n");
    if (move_square(50.0) < 0) {
        fprintf(stderr, "Error: Motor movement failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Square moved.\n");
    cleanup();
    return EXIT_SUCCESS;
}

