#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* LIS3DH register addresses */
#define LIS3DH_REG_CTRL1   0x20
#define LIS3DH_REG_CTRL4   0x23
#define LIS3DH_REG_OUT_X_L 0x28
#define LIS3DH_REG_OUT_X_H 0x29
#define LIS3DH_REG_OUT_Y_L 0x2A
#define LIS3DH_REG_OUT_Y_H 0x2B
#define LIS3DH_REG_OUT_Z_L 0x2C
#define LIS3DH_REG_OUT_Z_H 0x2D

/* CTRL1: 0x57 = 1101 0111 -> 100 Hz ODR, ±2g, left-justified, normal mode */
#define CTRL1_VAL 0x57
/* CTRL4: 0x00 = 0000 0000 -> 100 Hz ODR, little-endian, no FIFO, no self-test */
#define CTRL4_VAL 0x00

#define LOG_FILE "/var/log/high_acceleration.log"
#define SAMPLE_INTERVAL_US 100000  /* 100 ms -> 10 Hz */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int write_register(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing register 0x%02X (pigpio rc=%d)\n", reg, rc);
    }
    return rc;
}

static int initialize_lis3dh(int handle)
{
    if (write_register(handle, LIS3DH_REG_CTRL1, CTRL1_VAL) < 0)
        return -1;
    if (write_register(handle, LIS3DH_REG_CTRL4, CTRL4_VAL) < 0)
        return -1;
    return 0;
}

static int read_acceleration(int handle, float *x, float *y, float *z)
{
    char raw[6];
    int rc = i2cReadI2CBlockData(handle, LIS3DH_REG_OUT_X_L, raw, 6);
    if (rc != 6) {
        fprintf(stderr, "Error reading acceleration block (rc=%d)\n", rc);
        *x = *y = *z = 0.0f;
        return -1;
    }
    int16_t x_raw = (int16_t)(((uint8_t)raw[1] << 8) | (uint8_t)raw[0]);
    int16_t y_raw = (int16_t)(((uint8_t)raw[3] << 8) | (uint8_t)raw[2]);
    int16_t z_raw = (int16_t)(((uint8_t)raw[5] << 8) | (uint8_t)raw[4]);
    *x = (float)x_raw / 16384.0f;  /* ±2g range, 12-bit left-justified */
    *y = (float)y_raw / 16384.0f;
    *z = (float)z_raw / 16384.0f;
    return 0;
}

static void log_data(float x, float y, float z, float threshold)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];
    localtime_r(&now, &tm_info);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);

    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }
    fprintf(fp, "%s, X: %.3f g, Y: %.3f g, Z: %.3f g\n", ts, x, y, z);
    fclose(fp);

    char cmd[256];
    snprintf(cmd, sizeof(cmd), "sudo shutdown -h now", threshold);
    int rc = system(cmd);
    if (rc == -1) {
        perror("system() failed to execute shutdown");
    } else if (rc != 0) {
        fprintf(stderr, "shutdown command returned non-zero exit code %d\n", rc);
    }
}

int main(int argc, char *argv[])
{
    int i2c_address = 0x19;  /* default address for LIS3DH */
    float threshold = 2.0f;

    if (argc > 1) {
        char *endptr = NULL;
        long val = strtol(argv[1], &endptr, 0);
        if (endptr == argv[1] || *endptr != '\0' || val < 0x08 || val > 0x77) {
            fprintf(stderr, "Invalid I2C address: %s\n", argv[1]);
            return EXIT_FAILURE;
        }
        i2c_address = (int)val;
    }
    if (argc > 2) {
        char *endptr = NULL;
        long val = strtol(argv[2], &endptr, 0);
        if (endptr == argv[2] || *endptr != '\0' || val <= 0.0f) {
            fprintf(stderr, "Invalid threshold: %s\n", argv[2]);
            return EXIT_FAILURE;
        }
        threshold = (float)val;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed (non-HW environment)\n");
        return EXIT_SUCCESS;
    }

    g_i2c_handle = i2cOpen(1, i2c_address, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at address 0x%02X (rc=%d)\n",
                i2c_address, g_i2c_handle);
        gpioTerminate();
        return EXIT_SUCCESS;
    }

    if (initialize_lis3dh(g_i2c_handle) < 0) {
        fprintf(stderr, "Error initializing LIS3DH at address 0x%02X\n", i2c_address);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_SUCCESS;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_SUCCESS;
    }

    printf("Monitoring acceleration at I2C 0x%02X, threshold %.2f g. Press Ctrl+C to exit.\n",
           i2c_address, threshold);

    while (g_running) {
        float x, y, z;
        if (read_acceleration(g_i2c_handle, &x, &y, &z) == 0) {
            if (fabsf(x) > threshold || fabsf(y) > threshold || fabsf(z) > threshold) {
                log_data(x, y, z, threshold);
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

