#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LEFT_SENSOR_PIN 4
#define CENTER_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27
#define ALERT_LED_PIN 22

#define BUFFER_SIZE 5
#define POLL_DELAY_US 10000
#define ALERT_LED_ON_US 2000000

typedef struct {
    int left;
    int center;
    int right;
} sensor_data_t;

static sensor_data_t circular_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void add_to_buffer(int left, int center, int right) {
    circular_buffer[buffer_index].left = left;
    circular_buffer[buffer_index].center = center;
    circular_buffer[buffer_index].right = right;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
}

static void check_alert_and_move(void) {
    int center_val = gpioRead(CENTER_SENSOR_PIN);
    if (center_val < 0) {
        fprintf(stderr, "Error: Failed to read center sensor (GPIO%d)\n", CENTER_SENSOR_PIN);
        return;
    }

    if (center_val == 1) {
        if (buffer_count >= 5) {
            add_to_buffer(gpioRead(LEFT_SENSOR_PIN), center_val, gpioRead(RIGHT_SENSOR_PIN));
            if (gpioWrite(ALERT_LED_PIN, 1) != 0) {
                fprintf(stderr, "Error: Failed to set alert LED HIGH\n");
            }
            gpioDelay(ALERT_LED_ON_US);
            if (gpioWrite(ALERT_LED_PIN, 0) != 0) {
                fprintf(stderr, "Error: Failed to set alert LED LOW\n");
            }
        }
    } else {
        if (gpioWrite(ALERT_LED_PIN, 0) != 0) {
            fprintf(stderr, "Error: Failed to reset alert LED\n");
        }
    }
}

static void turn_left(void) {
    gpioWrite(LEFT_SENSOR_PIN, 1);
    gpioWrite(RIGHT_SENSOR_PIN, 0);
}

static void turn_right(void) {
    gpioWrite(LEFT_SENSOR_PIN, 0);
    gpioWrite(RIGHT_SENSOR_PIN, 1);
}

static void move_forward(void) {
    gpioWrite(LEFT_SENSOR_PIN, 0);
    gpioWrite(RIGHT_SENSOR_PIN, 0);
}

static void stop_robot(void) {
    gpioWrite(LEFT_SENSOR_PIN, 0);
    gpioWrite(RIGHT_SENSOR_PIN, 0);
    gpioWrite(ALERT_LED_PIN, 0);
}

static void cleanup(void) {
    stop_robot();
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set left sensor pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(CENTER_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set center sensor pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set right sensor pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ALERT_LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set alert LED pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(LEFT_SENSOR_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Warning: Failed to set pull-down on left sensor pin\n");
    }
    if (gpioSetPullUpDown(CENTER_SENSOR_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Warning: Failed to set pull-down on center sensor pin\n");
    }
    if (gpioSetPullUpDown(RIGHT_SENSOR_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Warning: Failed to set pull-down on right sensor pin\n");
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
    }

    printf("Line following robot started. Press Ctrl+C to exit.\n");

    while (running) {
        int left_val = gpioRead(LEFT_SENSOR_PIN);
        int center_val = gpioRead(CENTER_SENSOR_PIN);
        int right_val = gpioRead(RIGHT_SENSOR_PIN);

        if (left_val < 0 || center_val < 0 || right_val < 0) {
            fprintf(stderr, "Error: GPIO read failure (L=%d, C=%d, R=%d)\n", left_val, center_val, right_val);
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        add_to_buffer(left_val, center_val, right_val);

        check_alert_and_move();

        if (center_val == 1) {
            move_forward();
        } else if (left_val == 0) {
            turn_left();
        } else if (right_val == 0) {
            turn_right();
        } else {
            stop_robot();
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

