    gpioWrite(RIGHT_SENSOR_PIN, 0);
}

static void stop_robot(void) {
    gpioWrite(LEFT_SENSOR_PIN, 0);
    gpioWrite(RIGHT_SENSOR_PIN, 0);
    gpioWrite(ALERT_LED_PIN, 0);
}

static void cleanup(void) {
    stop_robot();
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set left sensor pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(CENTER_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set center sensor pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set right sensor pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ALERT_LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set alert LED pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(LEFT_SENSOR_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Warning: Failed to set pull-down on left sensor pin\n");
    }
    if (gpioSetPullUpDown(CENTER_SENSOR_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Warning: Failed to set pull-down on center sensor pin\n");
    }
    if (gpioSetPullUpDown(RIGHT_SENSOR_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Warning: Failed to set pull-down on right sensor pin\n");
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
    }

    printf("Line following robot started. Press Ctrl+C to exit.\n");

    while (running) {
        int left_val = gpioRead(LEFT_SENSOR_PIN);
        int center_val = gpioRead(CENTER_SENSOR_PIN);
        int right_val = gpioRead(RIGHT_SENSOR_PIN);

        if (left_val < 0 || center_val < 0 || right_val < 0) {
            fprintf(stderr, "Error: GPIO read failure (L=%d, C=%d, R=%d)\n", left_val, center_val, right_val);
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        add_to_buffer(left_val, center_val, right_val);

        check_alert_and_move();

        if (center_val == 1) {
            move_forward();
        } else if (left_val == 0) {
            turn_left();
        } else if (right_val == 0) {
            turn_right();
        } else {
            stop_robot();
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

