#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <sys/select.h>
#include <pigpio.h>

#define RELAY_GPIO 18
#define PORT 5000
#define BUFFER_SIZE 1024
#define LOG_FILE "relay_log.txt"

static volatile sig_atomic_t running = 1;
static int server_fd = -1;
static int client_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_message(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm tm_info;
    char timestamp[32];
    if (localtime_r(&now, &tm_info) != NULL) {
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    } else {
        snprintf(timestamp, sizeof(timestamp), "UNKNOWN");
    }
    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file);
}

static int control_relay(int state) {
    int rc = gpioWrite(RELAY_GPIO, state);
    if (rc < 0) {
        char msg[128];
        snprintf(msg, sizeof(msg), "Error: gpioWrite(%d, %d) failed: %s",
                 RELAY_GPIO, state, pigpio_error(rc));
        log_message(msg);
        return -1;
    }
    char msg[128];
    snprintf(msg, sizeof(msg), "Relay set to %s", state == 1 ? "ON" : "OFF");
    log_message(msg);
    return 0;
}

static int handle_client(int client_fd) {
    char buffer[BUFFER_SIZE];
    ssize_t n = recv(client_fd, buffer, BUFFER_SIZE - 1, 0);
    if (n <= 0) {
        if (n < 0) {
            char msg[128];
            snprintf(msg, sizeof(msg), "Error: recv failed: %s", strerror(errno));
            log_message(msg);
        } else {
            log_message("Client disconnected");
        }
        return 0;
    }
    buffer[n] = '\0';
    buffer[strcspn(buffer, "\r\n")] = '\0';
    if (strcmp(buffer, "ON") == 0) {
        if (control_relay(1) == 0) {
            const char *msg = "Relay turned ON";
            send(client_fd, msg, strlen(msg), 0);
        } else {
            const char *msg = "Error: relay ON command failed";
            send(client_fd, msg, strlen(msg), 0);
        }
    } else if (strcmp(buffer, "OFF") == 0) {
        if (control_relay(0) == 0) {
            const char *msg = "Relay turned OFF";
            send(client_fd, msg, strlen(msg), 0);
        } else {
            const char *msg = "Error: relay OFF command failed";
            send(client_fd, msg, strlen(msg), 0);
        }
    } else {
        const char *msg = "Invalid command. Use ON or OFF.";
        send(client_fd, msg, strlen(msg), 0);
        log_message(msg);
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(RELAY_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to initialize relay to OFF\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        perror("Error creating socket");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt");
        close(server_fd);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sockaddr_in address;
    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("Error binding socket");
        close(server_fd);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (listen(server_fd, 3) < 0) {
        perror("Error listening");
        close(server_fd);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Listening on port %d...\n", PORT);

    while (running) {
        struct sockaddr_in client_addr;
        socklen_t addrlen = sizeof(client_addr);
        client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &addrlen);
        if (client_fd < 0) {
            if (errno == EINTR && !running) break;
            perror("Error accepting connection");
            continue;
        }

        char client_ip[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, &client_addr.sin_addr, client_ip, sizeof(client_ip));
        printf("Connection from %s:%d\n", client_ip, ntohs(client_addr.sin_port));

        char buffer[BUFFER_SIZE];
        while (running) {
            ssize_t n = recv(client_fd, buffer, BUFFER_SIZE - 1, 0);
            if (n <= 0) {
                if (n < 0) {
                    perror("Error receiving data");
                    break;
                }
                break;
            }
            buffer[n] = '\0';
            buffer[strcspn(buffer, "\r\n")] = '\0';
            handle_client(client_fd);
        }
        close(client_fd);
        client_fd = -1;
    }

    printf("\nShutting down...\n");
    if (client_fd >= 0) close(client_fd);
    if (server_fd >= 0) close(server_fd);
    if (log_file) fclose(log_file);
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

