        fprintf(stderr, "[FLOW] CRC mismatch on handle %d\n", handle);
        return -1;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *flow_out = (float)raw / 100.0f;
    return 0;
}

static void log_flow_rates(float f1, float f2)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("[LOG] fopen");
        return;
    }

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm;
    localtime_r(&ts.tv_sec, &tm);
    char tbuf[32];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s.%03ld, Sensor1: %.2f ml/min, Sensor2: %.2f ml/min\n",
            tbuf, ts.tv_nsec / 1000000L, f1, f2);
    fflush(fp);
    fclose(fp);
}

static void control_relay(bool relay_on)
{
    int rc = gpioWrite(RELAY_GPIO, relay_on ? 1 : 0);
    if (rc < 0) {
        fprintf(stderr, "[GPIO] write %d failed (rc=%d)\n", relay_on, rc);
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int h1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (h1 < 0) {
        fprintf(stderr, "Failed to open I2C for sensor 1 (rc=%d)\n", h1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int h2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (h2 < 0) {
        fprintf(stderr, "Failed to open I2C for sensor 2 (rc=%d)\n", h2);
        i2cClose(h1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (i2c_write_cmd(h1, 0x36) != 0 || i2c_write_cmd(h2, 0x36) != 0) {
        fprintf(stderr, "Failed to start measurement on one or both sensors\n");
        i2cClose(h1);
        i2cClose(h2);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);

    printf("Flow monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float f1 = 0.0f, f2 = 0.0f;
        int ok1 = read_flow_rate(h1, &f1);
        int ok2 = read_flow_rate(h2, &f2);

        if (ok1 == 0 && ok2 == 0) {
            log_flow_rates(f1, f2);
            bool below = (f1 < FLOW_THRESHOLD || f2 < FLOW_THRESHOLD);
            control_relay(below);
        } else {
            fprintf(stderr, "[MAIN] Sensor read error; skipping cycle\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(RELAY_GPIO, 0);
    i2cClose(h1);
    i2cClose(h2);
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

