#include <syslog.h>
#include <time.h>
#include <errno.h>
#include <pigpio.h>

#define RAIN_SENSOR_PIN 17
#define MOTOR_ENA_PIN   22
#define MOTOR_IN1_PIN   23
#define MOTOR_IN2_PIN   24

#define MOTOR_RUN_TIME_US 5000000  /* 5 seconds */
#define POLL_INTERVAL_US  200000   /* 200 ms */
#define DRY_THRESHOLD      3        /* 3 dry polls = 600 ms */

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static int motor_stop(void)
{
    int rc = 0;
    if (gpioWrite(MOTOR_IN1_PIN, 0) < 0) {
        syslog(LOG_ERR, "gpioWrite(IN1, 0) failed: %s", strerror(errno));
        rc = -1;
    }
    if (gpioWrite(MOTOR_IN2_PIN, 0) < 0) {
        syslog(LOG_ERR, "gpioWrite(IN2, 0) failed: %s", strerror(errno));
        rc = -1;
    }
    if (gpioWrite(MOTOR_ENA_PIN, 0) < 0) {
        syslog(LOG_ERR, "gpioWrite(ENA, 0) failed: %s", strerror(errno));
        rc = -1;
    }
    return rc;
}

static int motor_start(void)
{
    int rc = 0;
    rc = gpioWrite(MOTOR_IN1_PIN, 1);
    if (rc < 0) {
        syslog(LOG_ERR, "gpioWrite(IN1, 1) failed: %s", strerror(errno));
        return -1;
    }
    rc = gpioWrite(MOTOR_IN2_PIN, 0);
    if (rc < 0) {
        syslog(LOG_ERR, "gpioWrite(IN2, 0) failed: %s", strerror(errno));
        return -1;
    }
    rc = gpioWrite(MOTOR_ENA_PIN, 1);
    if (rc < 0) {
        syslog(LOG_ERR, "gpioWrite(ENA, 1) failed: %s", strerror(errno));
        return -1;
    }
    return rc;
}

static int motor_run(void)
{
    return motor_start();
}

static int motor_stop_and_cleanup(void)
{
    return motor_stop();
}

static int rain_detected(void)
{
    return (gpioRead(RAIN_SENSOR_PIN) == 0);
}

static int motor_sequence(void)
{
    syslog(LOG_INFO, "Rain detected - starting motor sequence");
    if (motor_start() < 0) {
        syslog(LOG_ERR, "Motor start failed - aborting sequence");
        return -1;
    }

    usleep(MOTOR_RUN_TIME_US);

    if (motor_stop_and_cleanup() < 0) {
        syslog(LOG_ERR, "Motor stop failed - aborting sequence");
        return -1;
    }

    syslog(LOG_INFO, "Motor sequence complete");
    return 0;
}

static void cleanup(void)
{
    motor_stop_and_cleanup();
    gpioTerminate();
    closelog();
}

int main(void)
{
    openlog("rain_window", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        syslog(LOG_ERR, "sigaction(SIGINT) failed: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "sigaction(SIGTERM) failed: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT) < 0) {
        syslog(LOG_ERR, "gpioSetMode(RAIN_SENSOR) failed: %s", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(RAIN_SENSOR_PIN, PI_PUD_UP) < 0) {
        syslog(LOG_ERR, "gpioSetPullUpDown(RAIN_SENSOR) failed: %s", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MOTOR_ENA_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "gpioSetMode(motor pins) failed: %s", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Rain sensor monitoring started (GPIO%d, GPIO%d, GPIO%d, GPIO%d)",
           RAIN_SENSOR_PIN, MOTOR_ENA_PIN, MOTOR_IN1_PIN, MOTOR_IN2_PIN);

    int dry_count = 0;
    int last_rain = 0;

    while (program_running) {
        int rain = rain_detected();
        if (rain < 0) {
            syslog(LOG_ERR, "gpioRead(RAIN_SENSOR) failed: %s", strerror(errno));
            usleep(POLL_INTERVAL_US);
            continue;
        }

        if (rain && !last_rain) {
            dry_count = 0;
        } else if (!rain && last_rain) {
            dry_count++;
        }

        if (dry_count >= DRY_THRESHOLD) {
            syslog(LOG_INFO, "Sensor dry for %d polls - suppressing further triggers",
                   dry_count);
            dry_count = 0;
        }

        if (rain && !last_rain) {
            syslog(LOG_INFO, "Rain detected - triggering motor sequence");
            if (motor_sequence() < 0) {
                syslog(LOG_ERR, "Motor sequence failed - aborting");
                program_running = 0;
            }
        }

        last_rain = rain;
        usleep(POLL_INTERVAL_US);
    }

    syslog(LOG_INFO, "Shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

