#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SERVO_PIN      18
#define LOCK_BUTTON    21
#define UNLOCK_BUTTON  22
#define SERVO_MIN_PULSE 1000
#define SERVO_MAX_PULSE 2000
#define SERVO_STOP_PULSE 0
#define POLL_DELAY_US   10000
#define DEBOUNCE_DELAY_US 50000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int set_servo_pulse(int pulse_width)
{
    if (gpioServo(SERVO_PIN, pulse_width) != 0) {
        fprintf(stderr, "Error: gpioServo failed for pulse width %d\n", pulse_width);
        return -1;
    }
    return 0;
}

static void stop_servo(void)
{
    if (set_servo_pulse(SERVO_STOP_PULSE) != 0)
        fprintf(stderr, "Warning: failed to stop servo during shutdown\n");
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR ||
        signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error: failed to install signal handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set SERVO_PIN %d as output\n", SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LOCK_BUTTON, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set LOCK_BUTTON %d as input\n", LOCK_BUTTON);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(UNLOCK_BUTTON, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set UNLOCK_BUTTON %d as input\n", UNLOCK_BUTTON);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on LOCK_BUTTON %d\n", LOCK_BUTTON);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on UNLOCK_BUTTON %d\n", UNLOCK_BUTTON);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (set_servo_pulse(SERVO_MIN_PULSE) != 0) {
        fprintf(stderr, "Error: failed to initialise servo to minimum pulse\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Servo door-lock controller started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int lock_pressed = (gpioRead(LOCK_BUTTON) == 0);
        int unlock_pressed = (gpioRead(UNLOCK_BUTTON) == 0);

        if (lock_pressed) {
            if (set_servo_pulse(SERVO_MAX_PULSE) != 0) {
                fprintf(stderr, "Error: failed to lock door\n");
            } else {
                printf("Door locked.\n");
            }
        }

        if (unlock_pressed) {
            if (set_servo_pulse(SERVO_MIN_PULSE) != 0) {
                fprintf(stderr, "Error: failed to unlock door\n");
            } else {
                printf("Door unlocked.\n");
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    stop_servo();
    gpioDelay(500000);
    gpioServo(SERVO_PIN, 0);
    gpioDelay(500000);

    printf("Servo door-lock controller stopped.\n");
    gpioTerminate();
    return EXIT_SUCCESS;
}

