/*
 * MPR121 Capacitive Touch Relay Toggle for Raspberry Pi 5
 *
 * Wiring:
 *   MPR121 SDA -> GPIO2 (I2C bus 1 SDA)
 *   MPR121 SCL -> GPIO3 (I2C bus 1 SCL)
 *   MPR121 ADDR-> GND  (I2C address 0x60)
 *   Relay IN  -> GPIO17 (BCM)
 *   Relay VCC -> 3.3V or 5V per relay module spec
 *   Relay GND -> GND
 *
 * Behavior:
 *   On a fresh rising-edge touch of electrode 0, toggles GPIO17 HIGH/LOW.
 *   Debounce: 200 ms on electrode 0 only.
 *   Relay is set OFF at startup and on normal exit.
 *   SIGINT/SIGTERM triggers a clean shutdown.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MPR121_ADDR    0x60

/* MPR121 register addresses */
#define MPR121_TOUCHSTATUS_L  0x00
#define MPR121_TOUCHSTATUS_H  0x01
#define MPR121_MHD_R         0x2B
#define MPR121_NHD_R         0x2C
#define MPR121_NCL_R         0x2D
#define MPR121_FDL_R         0x2E
#define MPR121_MHD_F         0x2F
#define MPR121_NHD_F         0x30
#define MPR121_NCL_F         0x31
#define MPR121_FDL_F         0x32
#define MPR121_E0TTH         0x41
#define MPR121_E0RTH         0x42
#define MPR121_DEBOUNCE      0x5B
#define MPR121_CONFIG1       0x5C
#define MPR121_CONFIG2       0x5D
#define MPR121_AUTO_CONFIG   0x7B
#define MPR121_SOFTRESET     0x80

#define RELAY_GPIO        17
#define DEBOUNCE_MS       200
#define POLL_DELAY_US     10000  /* 10 ms */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* MPR121 initialization                                               */
/* ------------------------------------------------------------------ */
static int mpr121_init(int fd)
{
    /* Soft reset */
    if (i2c_write_reg8(fd, MPR121_SOFTRESET, 0x63) < 0)
        return -1;
    usleep(10000);  /* 10 ms settle after reset */

    /* Baseline filtering – rising side */
    if (i2c_write_reg8(fd, MPR121_MHD_R, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_NHD_R, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_NCL_R, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_FDL_R, 0x00) < 0) return -1;

    /* Baseline filtering – falling side */
    if (i2c_write_reg8(fd, MPR121_MHD_F, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_NHD_F, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_NCL_F, 0xFF) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_FDL_F, 0x02) < 0) return -1;

    /* Touch / release thresholds for electrode 0 */
    if (i2c_write_reg8(fd, MPR121_E0TTH, 0x0F) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_E0RTH, 0x0A) < 0) return -1;

    /* Debounce: 3 samples for both touch and release */
    if (i2c_write_reg8(fd, MPR121_DEBOUNCE, 0x33) < 0)
        return -1;

    /* CONFIG1: FFI=6 samples, SFI=4 samples, CDC=16 µA */
    if (i2c_write_reg8(fd, MPR121_CONFIG1, 0x10) < 0)
        return -1;

    /* CONFIG2: CDT=0.5 µs, ESI=4 ms, ESI_R=0.5 µs */
    if (i2c_write_reg8(fd, MPR121_CONFIG2, 0x20) < 0)
        return -1;

    /* Auto-config: 12 electrodes, 0x0F range */
    if (i2c_write_reg8(fd, MPR121_AUTO_CONFIG, 0x0F) < 0)
        return -1;

    /* Enable 12 electrodes and enter run mode */
    if (i2c_write_reg8(fd, MPR121_AUTO_CONFIG, 0x0C) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Relay control                                                      */
/* ------------------------------------------------------------------ */
static int relay_set(int state)
{
    int ret = gpiod_line_set_value(RELAY_GPIO, state);
    if (ret < 0) {
        fprintf(stderr, "Failed to set relay GPIO %d: %s\n",
                RELAY_GPIO, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                            */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Ensure relay is OFF on exit */
    if (g_i2c_fd >= 0) {
        (void)i2c_write_reg8(g_i2c_fd, MPR121_AUTO_CONFIG, 0x00);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    /* Safe to call even if gpiod was never initialized */
    gpiod_line_set_value(RELAY_GPIO, 0);
}

/* ------------------------------------------------------------------ */
/* Main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install signal handlers: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Initialize GPIO for relay control */
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    struct gpiod_line *relay = gpiod_chip_get_line(chip, RELAY_GPIO);
    if (!relay) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n",
                RELAY_GPIO, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(relay, "mpr121-relay", 0) < 0) {
        fprintf(stderr, "Failed to request relay GPIO %d as output: %s\n",
                RELAY_GPIO, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    relay_set(0);

    /* Initialize I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n",
                I2C_BUS, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                MPR121_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize MPR121 */
    if (mpr121_init(g_i2c_fd) < 0) {
        fprintf(stderr, "MPR121 initialization failed (sensor may be absent or bus error)\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MPR121 initialized. Touch electrode 0 to toggle relay on GPIO%d.\n",
           RELAY_GPIO);
    printf("Press Ctrl+C to exit.\n");

    bool relay_state = false;
    bool last_touch = false;

    while (g_running) {
        uint8_t touch_status_low = 0, touch_status_high = 0;

        if (i2c_read_reg8(g_i2c_fd, MPR121_TOUCHSTATUS_L, &touch_status_low) < 0) {
            fprintf(stderr, "Error reading touch status low byte\n");
            break;
        }
        if (i2c_read_reg8(g_i2c_fd, MPR121_TOUCHSTATUS_H, &touch_status_high) < 0) {
            fprintf(stderr, "Error reading touch status high byte\n");
            break;
        }

        uint16_t touch_status = ((uint16_t)touch_status_high << 8) | touch_status_low;
        bool current_touch = (touch_status & 0x0FFF) != 0;

        /* Rising-edge detection on electrode 0 */
        if (current_touch && !last_touch && !relay_state) {
            relay_state = !relay_state;
            if (relay_set(relay_state) < 0) {
                break;
            }
            printf("Relay toggled to %s\n", relay_state ? "ON" : "OFF");
        }

        last_touch = current_touch;
        usleep(POLL_DELAY_US);
    }

    cleanup();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

