    if (i2c_write_reg8(fd, MPR121_E0RTH, 0x0A) < 0) return -1;

    /* Debounce: 3 samples for both touch and release */
    if (i2c_write_reg8(fd, MPR121_DEBOUNCE, 0x33) < 0)
        return -1;

    /* CONFIG1: FFI=6 samples, SFI=4 samples, CDC=16 µA */
    if (i2c_write_reg8(fd, MPR121_CONFIG1, 0x10) < 0)
        return -1;

    /* CONFIG2: CDT=0.5 µs, ESI=4 ms, ESI_R=0.5 µs */
    if (i2c_write_reg8(fd, MPR121_CONFIG2, 0x20) < 0)
        return -1;

    /* Auto-config: 12 electrodes, 0x0F range */
    if (i2c_write_reg8(fd, MPR121_AUTO_CONFIG, 0x0F) < 0)
        return -1;

    /* Enable 12 electrodes and enter run mode */
    if (i2c_write_reg8(fd, MPR121_AUTO_CONFIG, 0x0C) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Relay control                                                      */
/* ------------------------------------------------------------------ */
static int relay_set(int state)
{
    int ret = gpiod_line_set_value(RELAY_GPIO, state);
    if (ret < 0) {
        fprintf(stderr, "Failed to set relay GPIO %d: %s\n",
                RELAY_GPIO, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                            */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Ensure relay is OFF on exit */
    if (g_i2c_fd >= 0) {
        (void)i2c_write_reg8(g_i2c_fd, MPR121_AUTO_CONFIG, 0x00);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    /* Safe to call even if gpiod was never initialized */
    gpiod_line_set_value(RELAY_GPIO, 0);
}

/* ------------------------------------------------------------------ */
/* Main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install signal handlers: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Initialize GPIO for relay control */
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    struct gpiod_line *relay = gpiod_chip_get_line(chip, RELAY_GPIO);
    if (!relay) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n",
                RELAY_GPIO, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(relay, "mpr121-relay", 0) < 0) {
        fprintf(stderr, "Failed to request relay GPIO %d as output: %s\n",
                RELAY_GPIO, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    relay_set(0);

    /* Initialize I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n",
                I2C_BUS, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                MPR121_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize MPR121 */
    if (mpr121_init(g_i2c_fd) < 0) {
        fprintf(stderr, "MPR121 initialization failed (sensor may be absent or bus error)\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MPR121 initialized. Touch electrode 0 to toggle relay on GPIO%d.\n",
           RELAY_GPIO);
    printf("Press Ctrl+C to exit.\n");

    bool relay_state = false;
    bool last_touch = false;

    while (g_running) {
        uint8_t touch_status_low = 0, touch_status_high = 0;

        if (i2c_read_reg8(g_i2c_fd, MPR121_TOUCHSTATUS_L, &touch_status_low) < 0) {
            fprintf(stderr, "Error reading touch status low byte\n");
            break;
        }
        if (i2c_read_reg8(g_i2c_fd, MPR121_TOUCHSTATUS_H, &touch_status_high) < 0) {
            fprintf(stderr, "Error reading touch status high byte\n");
            break;
        }

        uint16_t touch_status = ((uint16_t)touch_status_high << 8) | touch_status_low;
        bool current_touch = (touch_status & 0x0FFF) != 0;

        /* Rising-edge detection on electrode 0 */
        if (current_touch && !last_touch && !relay_state) {
            relay_state = !relay_state;
            if (relay_set(relay_state) < 0) {
                break;
            }
            printf("Relay toggled to %s\n", relay_state ? "ON" : "OFF");
        }

        last_touch = current_touch;
        usleep(POLL_DELAY_US);
    }

    cleanup();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

