#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <syslog.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <fcntl.h>
#include <stdarg.h>
#include <pigpio.h>

#define SERVO_PIN      17
#define PIR_PIN        4
#define PORT           5000
#define LOG_FILE       "security.log"
#define PWM_FREQ       50
#define PWM_RANGE      2000
#define MIN_PULSE_US   1000
#define MAX_PULSE_US   2000
#define BUF_SIZE       1024

static volatile sig_atomic_t g_running = 1;
static int  g_server_fd = -1;
static FILE *g_log_fp   = NULL;

static void log_msg(const char *level, const char *msg, ...) {
    if (!g_log_fp) return;
    time_t now = time(NULL);
    struct tm tmv;
    char ts[32];
    if (localtime_r(&now, &tmv)) {
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tmv);
    } else {
        snprintf(ts, sizeof(ts), "UNKNOWN");
    }
    va_list ap;
    va_start(ap, msg);
    vsprintf(ts, msg, ap);
    va_end(ap);
    if (level) {
        fprintf(g_log_fp, "[%s] [%s] %s\n", ts, level, msg);
    } else {
        fprintf(g_log_fp, "[%s] %s\n", ts, msg);
    }
    fflush(g_log_fp);
}

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set SERVO_PIN %d as output", SERVO_PIN);
        return -1;
    }
    if (gpioSetMode(PIR_PIN, PI_INPUT) < 0) {
        syslog(LOG_ERR, "Failed to set PIR_PIN %d as input", PIR_PIN);
        return -1;
    }
    if (gpioSetPWMfrequency(SERVO_PIN, PWM_FREQ) < 0) {
        syslog(LOG_ERR, "Failed to set PWM frequency on SERVO_PIN");
        return -1;
    }
    if (gpioSetPWMrange(SERVO_PIN, PWM_RANGE) < 0) {
        syslog(LOG_ERR, "Failed to set PWM range on SERVO_PIN");
        return -1;
    }
    return 0;
}

static int set_servo_angle(int angle) {
    if (angle < 0 || angle > 180) {
        log_msg("ERROR", "Invalid servo angle: %d", angle);
        return -1;
    }
    int pulse = MIN_PULSE_US + (angle * (MAX_PULSE_US - MIN_PULSE_US) / 180);
    if (gpioServo(SERVO_PIN, pulse) < 0) {
        log_msg("ERROR", "gpioServo failed for angle %d", angle);
        return -1;
    }
    return 0;
}

static int read_pir(void) {
    int v = gpioRead(PIR_PIN);
    if (v < 0) {
        log_msg("ERROR", "gpioRead failed on PIR_PIN");
        return -1;
    }
    return v;
}

static int send_response(int fd, const char *msg) {
    if (send(fd, msg, strlen(msg), 0) < 0) {
        log_msg("ERROR", "send failed: %s", strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (g_server_fd >= 0) {
        close(g_server_fd);
        g_server_fd = -1;
    }
    if (g_log_fp) {
        log_msg("INFO", "Shutting down");
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
}

int main(void) {
    openlog("security_app", LOG_PID | LOG_CONS, LOG_USER);
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        syslog(LOG_ERR, "Cannot open log file %s: %s", LOG_FILE, strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }
    log_msg("INFO", "Starting security_app");

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        log_msg("ERROR", "sigaction failed: %s", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        log_msg("ERROR", "GPIO initialization failed, exiting");
        cleanup();
        return EXIT_FAILURE;
    }

    g_server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (g_server_fd < 0) {
        log_msg("ERROR", "socket failed: %s", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    int opt = 1;
    if (setsockopt(g_server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        log_msg("ERROR", "setsockopt failed: %s", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port = htons(PORT);

    if (bind(g_server_fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        log_msg("ERROR", "bind failed: %s", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (listen(g_server_fd, 3) < 0) {
        log_msg("ERROR", "listen failed: %s", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    log_msg("INFO", "Listening on port %d", PORT);

    while (g_running) {
        int client_fd = accept(g_server_fd, NULL, NULL);
        if (client_fd < 0) {
            if (errno == EINTR && !g_running) break;
            log_msg("ERROR", "accept failed: %s", strerror(errno));
            continue;
        }
        char ip[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, &addr.sin_addr, ip, sizeof(ip));
        char buf[BUF_SIZE];
        ssize_t n = recv(client_fd, buf, sizeof(buf) - 1, 0);
        if (n < 0) {
            log_msg("ERROR", "recv failed: %s", strerror(errno));
            close(client_fd);
            continue;
        }
        buf[n] = '\0';
        buf[strcspn(buf, "\r\n")] = '\0';

        char *cmd = strtok(buf, " \r\n");
        while (cmd && *cmd) {
            char *arg = strtok(NULL, " \r\n");
            if (!arg) break;
            if (strcmp(cmd, "servo") == 0) {
                int angle = atoi(arg);
                if (set_servo_angle(angle) == 0) {
                    char resp[64];
                    snprintf(resp, sizeof(resp), "Servo: %d", angle);
                    send_response(client_fd, resp);
                } else {
                    send_response(client_fd, "ERROR");
                }
            } else if (strcmp(cmd, "pir") == 0) {
                int pir = read_pir();
                if (pir < 0) {
                    send_response(client_fd, "ERROR");
                } else {
                    char resp[32];
                    snprintf(resp, sizeof(resp), "PIR:%d", pir);
                    send_response(client_fd, resp);
                }
            } else {
                log_msg("INFO", "Unknown command: %s", cmd);
            }
            cmd = strtok(NULL, " \r\n");
        }
        close(client_fd);
    }

    cleanup();
    return EXIT_SUCCESS;
}

