#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BH1750_ADDR             0x77
#define GROW_LIGHT_GPIO         23
#define LUX_THRESHOLD           150
#define SAMPLE_INTERVAL_SEC     2
#define BH1750_MEASURE_DELAY_US 120000  /* 120 ms per datasheet */
#define I2C_BUS                 1

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int bh1750_read_lux(int handle, float *lux_out)
{
    /* Send continuous-high-power mode measurement command (0x10) */
    if (i2cWriteByte(handle, 0x10) < 0) {
        fprintf(stderr, "BH1750: failed to send measurement command\n");
        return -1;
    }

    usleep(BH1750_MEASURE_DELAY_US);

    char buf[2];
    int n = i2cReadDevice(handle, buf, 2);
    if (n != 2) {
        fprintf(stderr, "BH1750: failed to read 2 bytes (got %d)\n", n);
        return -1;
    }

    unsigned int raw = ((unsigned int)(unsigned char)buf[0] << 8) |
                       (unsigned int)(unsigned char)buf[1];

    /* Per datasheet: lux = raw / 1.2 */
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static void log_data(FILE *fp, float lux)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s, %.2f\n", ts, lux);
    fflush(fp);
}

static void control_grow_light(int gpio, int lux)
{
    int level = (lux < LUX_THRESHOLD) ? 1 : 0;
    if (gpioWrite(gpio, level) < 0) {
        fprintf(stderr, "Warning: gpioWrite(%d, %d) failed\n", gpio, level);
    }
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    /* Ensure relay is off before terminating pigpio */
    gpioWrite(GROW_LIGHT_GPIO, 0);
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
