    if (g_log_file == NULL) {
        perror("fopen(grow_log.txt)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("BH1750 light monitor started. Sampling every %d s. Ctrl+C to exit.\n",
           SAMPLE_INTERVAL_SEC);

    while (g_running) {
        float lux = 0.0f;
        if (bh1750_read_lux(g_i2c_handle, &lux) == 0) {
            log_data(g_log_file, lux);
            control_grow_light(GROW_LIGHT_GPIO, lux);
            printf("Lux: %.2f\n", lux);
        } else {
            fprintf(stderr, "Sensor read error; will retry next cycle.\n");
            /* Ensure relay is off on sensor failure */
            gpioWrite(GROW_LIGHT_GPIO, 0);
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

