#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <getopt.h>
#include <syslog.h>
#include <pigpio.h>

#define HX711_DOUT 23
#define HX711_SCK  24
#define SOLENOID   25

#define DEFAULT_THRESHOLD 1000.0
#define DEFAULT_SCALE     1.0
#define DEFAULT_DURATION  500
#define NUM_READINGS      5
#define MAX_RETRIES       3
#define DOUT_TIMEOUT_US   1000000
#define POLL_INTERVAL_US  500000

static volatile sig_atomic_t running = 1;
static double threshold = DEFAULT_THRESHOLD;
static double scale = DEFAULT_SCALE;
static int duration_ms = DEFAULT_DURATION;
static double last_weight = 0.0;

static int sck_pin = HX711_SCK;
static int dout_pin = HX711_DOUT;
static int sol_pin = SOLENOID;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_hx711(int32_t *out) {
    if (gpioSetMode(dout_pin, PI_INPUT) < 0) return -1;
    if (gpioSetMode(sck_pin, PI_OUTPUT) < 0) return -1;
    if (gpioWrite(sck_pin, 0) < 0) return -1;

    uint32_t start = gpioTick();
    while (gpioRead(dout_pin) == 1) {
        if (gpioTick() - start > DOUT_TIMEOUT_US) {
            syslog(LOG_ERR, "HX711 DOUT timeout (waiting for LOW)");
            return -1;
        }
        gpioDelay(100);
    }

    uint32_t data = 0;
    for (int i = 0; i < 24; i++) {
        if (gpioWrite(sck_pin, 1) < 0) return -1;
        gpioDelay(1);
        data <<= 1;
        if (gpioRead(dout_pin) == 1) data |= 1;
        if (gpioWrite(sck_pin, 0) < 0) return -1;
        gpioDelay(1);
    }

    /* 25th pulse selects Channel A, gain 128 */
    if (gpioWrite(sck_pin, 1) < 0) return -1;
    gpioDelay(1);
    if (gpioWrite(sck_pin, 0) < 0) return -1;
    gpioDelay(1);

    if (out) *out = (int32_t)data;
    return 0;
}

static double average_readings(int num_readings) {
    double sum = 0.0;
    for (int i = 0; i < num_readings; i++) {
        int32_t raw;
        if (read_hx711(&raw) != 0) {
            syslog(LOG_ERR, "HX711 read failed during averaging");
            return 0.0;
        }
        sum += (double)raw;
        gpioDelay(1000);
    }
    return sum / num_readings;
}

static void control_solenoid(int activate) {
    if (gpioWrite(sol_pin, activate ? 1 : 0) < 0) {
        syslog(LOG_ERR, "Failed to write solenoid GPIO");
    }
}

static void cleanup(void) {
    gpioWrite(sol_pin, 0);
    gpioSetMode(sck_pin, PI_INPUT);
    gpioSetMode(dout_pin, PI_INPUT);
    gpioSetMode(sol_pin, PI_INPUT);
    gpioTerminate();
    closelog();
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "t:s:d:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                break;
            case 's':
                scale = atof(optarg);
                break;
            case 'd':
                duration_ms = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold_g] [-s scale] [-d duration_ms]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    openlog("weight_monitor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting weight monitor (threshold=%.1f, scale=%.2f, duration=%d ms)",
           threshold, scale, duration_ms);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to install signal handlers");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(sck_pin, PI_OUTPUT) < 0 || gpioSetMode(dout_pin, PI_INPUT) < 0 || gpioSetMode(sol_pin, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO modes");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioWrite(sck_pin, 0) < 0 || gpioWrite(sol_pin, 0) < 0) {
        syslog(LOG_ERR, "Failed to initialise GPIO states");
        cleanup();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Taring load cell...");
    int32_t raw;
    for (int i = 0; i < 10; i++) {
        if (read_hx711(&raw) != 0) {
            syslog(LOG_ERR, "Tare read failed, retrying");
            gpioDelay(100000);
            continue;
        }
        last_weight = (double)raw / scale;
        syslog(LOG_INFO, "Tare reading %d: %.2f g", i + 1, last_weight);
        gpioDelay(100000);
    }
    syslog(LOG_INFO, "Tare complete. Last weight: %.2f g", last_weight);

    while (running) {
        double weight = 0.0;
        for (int i = 0; i < NUM_READINGS; i++) {
            if (read_hx711(&raw) != 0) {
                syslog(LOG_ERR, "HX711 read failed during measurement");
                continue;
            }
            weight += (double)raw / scale;
            gpioDelay(1000);
        }
        weight /= NUM_READINGS;

        if (weight != last_weight) {
            last_weight = weight;
            syslog(LOG_INFO, "Weight: %.2f g", weight);
        }

        if (weight > threshold) {
            syslog(LOG_INFO, "Threshold exceeded, activating solenoid");
            control_solenoid(1);
            gpioDelay(200000);
            control_solenoid(0);
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    syslog(LOG_INFO, "Shutting down gracefully");
    cleanup();
    return EXIT_SUCCESS;
}

