#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <time.h>
#include <errno.h>
#include <stdbool.h>
#include <pigpio.h>

#define MQTT_CLIENT_ID      "relay_controller_1"
#define MQTT_BROKER_ADDRESS "localhost"
#define MQTT_BROKER_PORT    1883
#define MQTT_TOPIC          "home/lights/control"
#define GPIO_PIN            17
#define KEEPALIVE_SEC       60
#define RECONNECT_DELAY_SEC 5
#define MQTT_MSG_BUF_SIZE   256

static volatile sig_atomic_t g_running = 1;
static int g_mqtt_client = -1;

/* ------------------------------------------------------------------ */
/* Signal handler — graceful shutdown                                  */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging helper — all syslog messages are tagged                     */
/* ------------------------------------------------------------------ */
static void log_message(int priority, const char *message)
{
    syslog(priority, "%s", message);
}

/* ------------------------------------------------------------------ */
/* MQTT helpers                                                         */
/* ------------------------------------------------------------------ */
static int mqtt_connect(void)
{
    int rc;

    rc = mqtt_connect(g_mqtt_client, MQTT_BROKER_ADDRESS,
                      MQTT_BROKER_PORT, KEEPALIVE_SEC);
    if (rc != MQTT_CONNECT_SUCCESS) {
        log_message(LOG_ERR, "MQTT connect failed: %s", mqtt_strerror(rc));
        return -1;
    }

    log_message(LOG_INFO, "MQTT connected to broker");
    return 0;
}

static int mqtt_subscribe(void)
{
    int rc;

    rc = mqtt_subscribe(g_mqtt_client, MQTT_TOPIC, 1);
    if (rc != MQTT_SUBSCRIBE_SUCCESS) {
        log_message(LOG_ERR, "MQTT subscribe failed: %s", mqtt_strerror(rc));
        return -1;
    }

    log_message(LOG_INFO, "MQTT subscribed to %s", MQTT_TOPIC);
    return 0;
}

static void mqtt_disconnect(void)
{
    log_message(LOG_WARNING, "MQTT disconnected");
}

static void mqtt_error_handler(int rc, const char *message)
{
    log_message(LOG_ERR, "MQTT error: %s (rc=%d)", message, rc);
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                         */
/* ------------------------------------------------------------------ */
static int gpio_init(void)
{
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) != 0) {
        log_message(LOG_ERR, "Failed to set GPIO%d as output", GPIO_PIN);
        gpioTerminate();
        return -1;
    }

    /* Ensure relay starts in OFF state */
    if (gpioWrite(GPIO_PIN, 0) != 0) {
        log_message(LOG_ERR, "Failed to initialise GPIO%d LOW", GPIO_PIN);
        gpioTerminate();
        return -1;
    }

    log_message(LOG_INFO, "GPIO initialised on GPIO%d", GPIO_PIN);
    return 0;
}

static void gpio_set_relay(int state)
{
    if (gpioWrite(GPIO_PIN, state ? 1 : 0) != 0) {
        log_message(LOG_ERR, "Failed to write GPIO%d", GPIO_PIN);
    }
}

/* ------------------------------------------------------------------ */
/* Payload processing — relay control                                  */
/* ------------------------------------------------------------------ */
static void process_payload(const char *payload)
{
    if (payload == NULL || strlen(payload) == 0) {
        log_message(LOG_ERR, "Empty payload received");
        return;
    }

    if (strcmp(payload, "ON") == 0) {
        gpio_set_relay(1);
        log_message(LOG_INFO, "Relay ON (GPIO%d HIGH)", GPIO_PIN);
    } else if (strcmp(payload, "OFF") == 0) {
        gpio_set_relay(0);
        log_message(LOG_INFO, "Relay OFF (GPIO%d LOW)", GPIO_PIN);
    } else {
        log_message(LOG_ERR, "Invalid payload: %s", payload);
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_mqtt_client >= 0) {
        mqtt_disconnect();
        mqtt_destroy(g_mqtt_client);
        g_mqtt_client = -1;
    }

    gpioTerminate();
    closelog();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int rc;
    char buffer[MQTT_MSG_BUF_SIZE];
    time_t last_connect_time = 0;

    openlog(MQTT_CLIENT_ID, LOG_PID | LOG_CONS, LOG_USER);

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        log_message(LOG_ERR, "Failed to install signal handlers: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    /* Initialise GPIO */
    if (gpio_init() != 0) {
        closelog();
        return EXIT_FAILURE;
    }

    /* Initialise MQTT client */
    rc = mqtt_create(&g_mqtt_client, MQTT_CLIENT_ID, MQTT_BROKER_ADDRESS,
                     MQTT_BROKER_PORT, MQTT_MSG_BUF_SIZE, KEEPALIVE_SEC,
                     NULL, NULL);
    if (rc != MQTT_CLIENT_SUCCESS) {
        log_message(LOG_ERR, "MQTT client creation failed: %s", mqtt_strerror(rc));
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    /* Connect to broker */
    if (mqtt_connect() != 0) {
        log_message(LOG_ERR, "Initial MQTT connect failed — attempting reconnection");
        sleep(RECONNECT_DELAY_SEC);
        if (mqtt_connect() != 0) {
            log_message(LOG_ERR, "Reconnect failed — exiting");
            cleanup();
            return EXIT_FAILURE;
        }
    } else {
        last_connect_time = time(NULL);
    }

    /* Subscribe to topic */
    if (mqtt_subscribe() != 0) {
        log_message(LOG_ERR, "Initial MQTT subscribe failed — attempting reconnection");
        sleep(RECONNECT_DELAY_SEC);
        if (mqtt_subscribe() != 0) {
            log_message(LOG_ERR, "Reconnect subscribe failed — exiting");
            cleanup();
            return EXIT_FAILURE;
        }
    }

    /* Main loop */
    while (g_running) {
        rc = mqtt_read(g_mqtt_client, buffer, MQTT_MSG_BUF_SIZE - 1);
        if (rc == MQTT_READ_SUCCESS) {
            process_payload(buffer);
        } else if (rc == MQTT_READ_TIMEOUT) {
            log_message(LOG_WARNING, "MQTT read timeout — reconnection attempt");
            sleep(RECONNECT_DELAY_SEC);
            if (!g_running) break;
            if (mqtt_connect() != 0) {
                log_message(LOG_ERR, "Reconnect failed — exiting");
                cleanup();
                return EXIT_FAILURE;
            }
            if (mqtt_subscribe() != 0) {
                log_message(LOG_ERR, "Reconnect subscribe failed — exiting");
                cleanup();
                return EXIT_FAILURE;
            }
        } else {
            log_message(LOG_ERR, "MQTT read error: %s", mqtt_strerror(rc));
        }

        /* Sleep to avoid busy-waiting, but wake early on signal */
        for (int i = 0; i < 10 && g_running; i++) {
            sleep(1);
        }
    }

    /* Graceful shutdown */
    log_message(LOG_INFO, "Shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

