#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>

#define SERVO1_PIN 7
#define SERVO2_PIN 8
#define SERVO3_PIN 9
#define SERVO4_PIN 10
#define SERVO5_PIN 11

#define SERVO1_TARGET 1000
#define SERVO2_TARGET 1500
#define SERVO3_TARGET 2000
#define SERVO4_TARGET 500
#define SERVO5_TARGET 2500

#define PULSE_MIN 500
#define PULSE_MAX 2500
#define PULSE_STEP 500
#define HOLD_TIME 3

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_servo_pulse(int pin, int pulse_us) {
    if (pulse_us < PULSE_MIN || pulse_us > PULSE_MAX) {
        fprintf(stderr, "Error: pulse %d us out of range [%d, %d]\n",
                pulse_us, PULSE_MIN, PULSE_MAX);
        return -1;
    }
    if (gpioServo(pin, pulse_us) < 0) {
        fprintf(stderr, "Error: gpioServo failed on pin %d\n", pin);
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int pins[] = {SERVO1_PIN, SERVO2_PIN, SERVO3_PIN, SERVO4_PIN, SERVO5_PIN};
    const int num_pins = (int)(sizeof(pins) / sizeof(pins[0]));

    for (int i = 0; i < num_pins && running; i++) {
        int target = (i < 2) ? SERVO1_TARGET : SERVO2_TARGET;
        int pulse = target;

        if (set_servo_pulse(pins[i], pulse) != 0) {
            fprintf(stderr, "Error: failed to set servo %d\n", i + 1);
            for (int j = 0; j < i && running; j++) {
                gpioServo(pins[j], 0);
            }
            gpioTerminate();
            return EXIT_FAILURE;
        }

        printf("Moving servo %d to %d us\n", i + 1, target);

        for (int elapsed = 0; elapsed < HOLD_TIME && running; elapsed += 20) {
            usleep(20000);
        }

        if (set_servo_pulse(pins[i], 0) != 0) {
            fprintf(stderr, "Error: failed to stop servo %d\n", i + 1);
            for (int j = 0; j < i && running; j++) {
                gpioServo(pins[j], 0);
            }
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < num_pins && running; i++) {
        gpioServo(pins[i], 0);
    }

    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return EXIT_SUCCESS;
}

