        uint32_t a_stall = g_stall_count[0];
        uint32_t b_stall = g_stall_count[1];
        if (a_stall >= TICKS_PER_REV) {
            uint32_t elapsed = now - g_stall_start_tick[0];
            if (elapsed > STALL_TIMEOUT_S * 1000000) {
                printf("WARNING: Encoder A stall detected (ticks=%u, elapsed=%u s)\n",
                       a_stall, elapsed);
