/*
 * Raspberry Pi 3 Model B+ — Quadrature Encoder DC Motor Speed Control
 *
 * Hardware:
 *   DRV8833 H-bridge:
 *     IN1 -> GPIO17 (PWM)
 *     IN2 -> GPIO18 (direction)
 *     IN3 -> GPIO22 (PWM)
 *     IN4 -> GPIO23 (direction)
 *   Encoder A:
 *     Phase A -> GPIO4
 *     Phase B -> GPIO5
 *   Encoder B:
 *     Phase A -> GPIO6
 *     Phase B -> GPIO12
 *
 * Build:  gcc -O2 -Wall -o motor_control motor_control.c -lpigpio -lrt
 * Run:    sudo ./motor_control
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Pin assignments (BCM numbering) ---- */
#define MOTOR_A_PWM_PIN    17
#define MOTOR_A_DIR_PIN    18
#define MOTOR_B_PWM_PIN    22
#define MOTOR_B_DIR_PIN    23

#define ENCODER_A_PHASE_A  4
#define ENCODER_A_PHASE_B  5
#define ENCODER_B_PHASE_A  6
#define ENCODER_B_PHASE_B  12

/* ---- Motor parameters ---- */
#define TARGET_RPM          50.0
#define PWM_FREQUENCY_HZ   10000   /* 10 kHz */
#define PWM_RANGE          255
#define PWM_DUTY_MAX       255
#define PWM_DUTY_MIN       0
#define PWM_DUTY_STEP      1
#define LOOP_DELAY_US      100000  /* 100 ms */
#define STALL_TIMEOUT_S    2
#define TICKS_PER_REV      64
#define ENCODER_TICKS      1        /* 1 tick per rising edge */

/* ---- Global state ---- */
static volatile sig_atomic_t g_running = 1;
static volatile uint32_t g_encoder_ticks[2] = {0, 0};
static volatile uint32_t g_encoder_last_tick[2] = {0, 0};
static volatile uint32_t g_encoder_last_edge[2] = {0, 0};
static volatile uint32_t g_stall_start_tick[2] = {0, 0};
static volatile uint32_t g_stall_count[2] = {0, 0};

/* ---- PI controller state ---- */
typedef struct {
    double integral;
    double prev_error;
} PIController;

static PIController motor_a_controller = {0.0, 0.0};
static PIController motor_b_controller = {0.0, 0.0};

/* ---- Function prototypes ---- */
static void motor_a_forward(void);
static void motor_a_backward(void);
static void motor_b_forward(void);
static void motor_b_backward(void);
static void encoder_isr(int gpio, int level, uint32_t tick, void *user);
static void signal_handler(int sig);
static void cleanup(void);

/* ---- Motor control primitives ---- */
static void motor_a_forward(void) {
    gpioWrite(MOTOR_A_DIR_PIN, 1);
    gpioPWM(MOTOR_A_PWM_PIN, PWM_DUTY_MAX);
}

static void motor_a_backward(void) {
    gpioWrite(MOTOR_A_DIR_PIN, 0);
    gpioPWM(MOTOR_A_PWM_PIN, PWM_DUTY_MAX);
}

static void motor_b_forward(void) {
    gpioWrite(MOTOR_B_DIR_PIN, 1);
    gpioPWM(MOTOR_B_PWM_PIN, PWM_DUTY_MAX);
}

static void motor_b_backward(void) {
    gpioWrite(MOTOR_B_DIR_PIN, 0);
    gpioPWM(MOTOR_B_PWM_PIN, PWM_DUTY_MAX);
}

/* ---- Encoder ISR ---- */
static void encoder_isr(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio;
    (void)user;

    if (level == 1) {                       /* rising edge */
        uint32_t prev = g_encoder_last_tick[gpio];
        uint32_t cur  = tick;

        /* Detect stuck-high / stuck-low on the encoder line */
        if (cur == prev) {
            g_stall_count[gpio]++;
            if (g_stall_count[gpio] >= TICKS_PER_REV) {
                g_stall_start_tick[gpio] = tick;
                g_stall_count[gpio] = 0;
            }
        } else {
            g_encoder_last_tick[gpio] = cur;
            g_stall_count[gpio] = 0;
        }

        /* Update tick count for this encoder */
        g_encoder_ticks[gpio] += ENCODER_TICKS;
    }
}

/* ---- Signal handler ---- */
static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* ---- Cleanup ---- */
static void cleanup(void) {
    /* Stop motors and release PWM */
    motor_a_forward();
    motor_a_backward();
    motor_b_forward();
    motor_b_backward();
    gpioPWM(MOTOR_A_PWM_PIN, 0);
    gpioPWM(MOTOR_B_PWM_PIN, 0);
    gpioSetMode(MOTOR_A_PWM_PIN, PI_INPUT);
    gpioSetMode(MOTOR_A_DIR_PIN, PI_INPUT);
    gpioSetMode(MOTOR_B_PWM_PIN, PI_INPUT);
    gpioSetMode(MOTOR_B_DIR_PIN, PI_INPUT);

    /* Disable ISRs */
    gpioSetISRFuncEx(ENCODER_A_PHASE_A, EITHER_EDGE, 0, NULL, NULL);
    gpioSetISRFuncEx(ENCODER_A_PHASE_B, EITHER_EDGE, 0, NULL, NULL);
    gpioSetISRFuncEx(ENCODER_B_PHASE_A, EITHER_EDGE, 0, NULL, NULL);
    gpioSetISRFuncEx(ENCODER_B_PHASE_B, EITHER_EDGE, 0, NULL, NULL);

    gpioTerminate();
}

/* ---- Main ---- */
int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure motor pins */
    if (gpioSetMode(MOTOR_A_PWM_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_A_DIR_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_B_PWM_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_B_DIR_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set motor pin modes.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure encoder pins as inputs */
    if (gpioSetMode(ENCODER_A_PHASE_A, PI_INPUT) != 0 ||
        gpioSetMode(ENCODER_A_PHASE_B, PI_INPUT) != 0 ||
        gpioSetMode(ENCODER_B_PHASE_A, PI_INPUT) != 0 ||
        gpioSetMode(ENCODER_B_PHASE_B, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set encoder pin modes.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Set PWM frequency and range */
    if (gpioSetPWMfrequency(MOTOR_A_PWM_PIN, PWM_FREQUENCY_HZ) < 0 ||
        gpioSetPWMfrequency(MOTOR_B_PWM_PIN, PWM_FREQUENCY_HZ) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency.\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(MOTOR_A_PWM_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(MOTOR_B_PWM_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register ISRs for both edges of each encoder line */
    if (gpioSetISRFuncEx(ENCODER_A_PHASE_A, EITHER_EDGE, 0, encoder_isr, NULL) != 0 ||
        gpioSetISRFuncEx(ENCODER_A_PHASE_B, EITHER_EDGE, 0, encoder_isr, NULL) != 0 ||
        gpioSetISRFuncEx(ENCODER_B_PHASE_A, EITHER_EDGE, 0, encoder_isr, NULL) != 0 ||
        gpioSetISRFuncEx(ENCODER_B_PHASE_B, EITHER_EDGE, 0, encoder_isr, NULL) != 0) {
        fprintf(stderr, "Error: failed to register encoder ISRs.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to install signal handler.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Motor control started. Target RPM: %.1f\n", TARGET_RPM);
    printf("Press Ctrl+C to stop.\n");

    /* PI controller state */
    motor_a_controller.integral = 0.0;
    motor_a_controller.prev_error = 0.0;
    motor_b_controller.integral = 0.0;
    motor_b_controller.prev_error = 0.0;

    uint32_t last_print_tick = gpioTick();

    while (g_running) {
        uint32_t now = gpioTick();

        /* Stall detection */
        uint32_t a_stall = g_stall_count[0];
        uint32_t b_stall = g_stall_count[1];
        if (a_stall >= TICKS_PER_REV) {
            uint32_t elapsed = now - g_stall_start_tick[0];
            if (elapsed > STALL_TIMEOUT_S * 1000000) {
                printf("WARNING: Encoder A stall detected (ticks=%u, elapsed=%u s)\n",
                       a_stall, elapsed);
                g_stall_count[0] = 0;
                g_stall_start_tick[0] = 0;
            }
        }
        if (b_stall >= TICKS_PER_REV) {
            uint32_t elapsed = now - g_stall_start_tick[1];
            if (elapsed > STALL_TIMEOUT_S * 1000000) {
                printf("WARNING: Encoder B stall detected (ticks=%u, elapsed=%u s)\n",
                       b_stall, elapsed);
                g_stall_count[1] = 0;
                g_stall_start_tick[1] = 0;
            }
        }

        /* Update RPM */
        uint32_t a_ticks = g_encoder_ticks[0];
        uint32_t b_ticks = g_encoder_ticks[1];
        double rpm_a = (double)a_ticks / (double)TICKS_PER_REV * (60.0 / (double)LOOP_DELAY_US);
        double rpm_b = (double)b_ticks / (double)TICKS_PER_REV * (60.0 / (double)LOOP_DELAY_US);

        /* Update PI controller */
        double error_a = TARGET_RPM - rpm_a;
        double error_b = TARGET_RPM - rpm_b;

        motor_a_controller.integral += error_a * (double)LOOP_DELAY_US;
        motor_b_controller.integral += error_b * (double)LOOP_DELAY_US;

        double kp_a = 0.5;
        double kp_b = 0.5;
        double Kp = kp_a + kp_b;

        double output_a = Kp * error_a;
        double output_b = Kp * error_b;

        motor_a_controller.prev_error = error_a;
        motor_b_controller.prev_error = error_b;

        /* Apply anti-windup clamping */
        if (output_a > PWM_DUTY_MAX) output_a = PWM_DUTY_MAX;
        if (output_a < PWM_DUTY_MIN) output_a = PWM_DUTY_MIN;
        if (output_a > 0) {
            gpioPWM(MOTOR_A_PWM_PIN, (int)output_a);
        }

        if (output_b > PWM_DUTY_MAX) output_b = PWM_DUTY_MAX;
        if (output_b < PWM_DUTY_MIN) output_b = PWM_DUTY_MIN;
        if (output_b > 0) {
            gpioPWM(MOTOR_B_PWM_PIN, (int)output_b);
        }

        /* Print status */
        if ((now - last_print_tick) * 1000000 >= 1000000) {
            printf("Motor A: RPM=%.2f, PWM=%d\n", rpm_a, (int)g_encoder_ticks[0]);
            printf("Motor B: RPM=%.2f, PWM=%d\n", rpm_b, (int)g_encoder_ticks[1]);
            last_print_tick = now;
        }

        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
