#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BH1750_ADDR             0x77
#define BH1750_CMD_CONT_HR0_1X  0x10
#define BH1750_MEASUREMENT_MS   180
#define RELAY_GPIO              17
#define LUX_THRESHOLD_DUSK       50
#define LUX_THRESHOLD_DAWN       200
#define POLL_INTERVAL_S          5
#define LOG_FILE                "chicken_coop_log.txt"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);
    return 0;
}

static int init_i2c(void) {
    g_i2c_handle = i2cOpen(1, BH1750_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (addr 0x%02X): %d\n", BH1750_ADDR, g_i2c_handle);
        return -1;
    }
    return 0;
}

static int read_bh1750(float *lux_out) {
    char cmd = BH1750_CMD_CONT_HR0_1X;
    char buf[2];

    if (i2cWriteDevice(g_i2c_handle, &cmd, 1) != 0) {
        fprintf(stderr, "Error: i2cWriteDevice failed\n");
        return -1;
    }

    gpioDelay(BH1750_MEASUREMENT_MS * 1000);

    if (i2cReadDevice(g_i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error: i2cReadDevice failed\n");
        return -1;
    }

    unsigned int raw = ((unsigned int)(unsigned char)buf[0] << 8) | (unsigned char)buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static void log_data(float lux, int relay_state) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return;
    }

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (g_log_fp) {
        fprintf(g_log_fp, "%s: Lux = %.1f, Relay = %s\n", timestamp, lux, relay_state ? "ON" : "OFF");
        fflush(g_log_fp);
    }
}

static void control_relay(int lux) {
    static int relay_state = 0;
    if (lux < LUX_THRESHOLD_DUSK && !relay_state) {
        gpioWrite(RELAY_GPIO, 1);
        relay_state = 1;
        printf("Dusk detected: turning LED strip ON (Lux = %.1f)\n", lux);
    } else if (lux > LUX_THRESHOLD_DAWN && relay_state) {
        gpioWrite(RELAY_GPIO, 0);
        relay_state = 0;
        printf("Dawn detected: turning LED strip OFF (Lux = %.1f)\n", lux);
    }
}

static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("fopen log");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Monitoring ambient light on BH1750 @ 0x%02X. Press Ctrl+C to exit.\n", BH1750_ADDR);

    while (g_running) {
        float lux;
        if (read_bh1750(&lux) == 0) {
            log_data(lux, gpioRead(RELAY_GPIO));
            control_relay(lux);
        } else {
            fprintf(stderr, "Warning: sensor read failed; turning relay off for safety\n");
            gpioWrite(RELAY_GPIO, 0);
            log_data(-1.0f, 0);
        }

        for (int i = 0; i < POLL_INTERVAL_S && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

