    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("fopen log");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Monitoring ambient light on BH1750 @ 0x%02X. Press Ctrl+C to exit.\n", BH1750_ADDR);

    while (g_running) {
        float lux;
        if (read_bh1750(&lux) == 0) {
            log_data(lux, gpioRead(RELAY_GPIO));
            control_relay(lux);
        } else {
            fprintf(stderr, "Warning: sensor read failed; turning relay off for safety\n");
            gpioWrite(RELAY_GPIO, 0);
            log_data(-1.0f, 0);
        }

        for (int i = 0; i < POLL_INTERVAL_S && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

