#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define DEBOUNCE_DELAY_US 50000   /* 50 ms */
#define LOOP_DELAY_US 10000        /* 10 ms */
#define POLL_DELAY_US 1000         /* 1 ms */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_timestamp(const char *msg) {
    time_t now = time(NULL);
    struct tm tm_info;
    char buf[32];
    if (localtime_r(&now, &tm_info) != NULL &&
        strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%S", &tm_info) > 0) {
        printf("[%s] %s\n", buf, msg);
    } else {
        printf("[unknown] %s\n", msg);
    }
    fflush(stdout);
}

static int safe_set_mode(unsigned pin, unsigned mode) {
    if (gpioSetMode(pin, mode) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%u, %u) failed\n", pin, mode);
        return -1;
    }
    return 0;
}

static int safe_write(unsigned pin, unsigned level) {
    if (gpioWrite(pin, level) != 0) {
        fprintf(stderr, "Error: gpioWrite(%u, %u) failed\n", pin, level);
        return -1;
    }
    return 0;
}

static int safe_read(unsigned pin) {
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "Error: gpioRead(%u) failed\n", pin);
        return -1;
    }
    return v;
}

static int safe_set_pull(unsigned pin, unsigned pud) {
    if (gpioSetPullUpDown(pin, pud) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown(%u, %u) failed\n", pin, pud);
        return -1;
    }
    return 0;
}

static int safe_init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    if (safe_set_mode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) goto fail;
    if (safe_set_pull(TOUCH_SENSOR_PIN, PI_PUD_OFF) != 0) goto fail;
    if (safe_write(RELAY_PIN, 0) != 0) goto fail;

    return 0;

fail:
    gpioTerminate();
    return -1;
}

static void cleanup_gpio(void) {
    safe_write(RELAY_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (safe_init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    log_timestamp("Program started");

    int relay_state = 0;
    int last_touch = 0;
    int touch_active = 0;

    while (running) {
        int touch = safe_read(TOUCH_SENSOR_PIN);
        if (touch < 0) {
            log_timestamp("Error: failed to read touch sensor");
            break;
        }

        if (touch == 1 && !touch_active) {
            touch_active = 1;
            last_touch = 1;
            gpioDelay(DEBOUNCE_DELAY_US);
            touch = safe_read(TOUCH_SENSOR_PIN);
            if (touch < 0) {
                log_timestamp("Error: failed to read touch sensor after debounce");
                break;
            }
            if (touch == 1) {
                relay_state = !relay_state;
                if (safe_write(RELAY_PIN, relay_state) != 0) {
                    log_timestamp("Error: failed to write relay state");
                    break;
                }
                log_timestamp(relay_state ? "Relay ON" : "Relay OFF");
            }
            touch_active = 0;
        } else if (touch == 0 && touch_active) {
            touch_active = 0;
        }

        gpioDelay(POLL_DELAY_US);
    }

    log_timestamp("Program shutting down");
    cleanup_gpio();
    return EXIT_SUCCESS;
}

