#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <pigpio.h>

#define FLOW_SENSOR_PIN 17
#define SOLENOID Valve
#define SOLENOID_PIN 27
#define FLOW_THRESHOLD 5.0
#define FLOW_HYSTERESIS 0.5
#define DEBOUNCE_TIME 1.0
#define LOG_FILE "water_flow.log"

static volatile sig_atomic_t running = 1;
static volatile int pulse_count = 0;
static pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE *log_file = NULL;
static int solenoid_state = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void pulse_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    (void)tick;
    if (level == 1) {
        pthread_mutex_lock(&pulse_mutex);
        pulse_count++;
        pthread_mutex_unlock(&pulse_mutex);
    }
}

static double calculate_lpm(int pulses, double dt) {
    if (dt <= 0.0) return 0.0;
    return (double)pulses * 60.0 / dt;
}

static void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];
    localtime_r(&now, &tm_info);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
    if (log_file) {
        fprintf(log_file, "%s: %s\n", ts, event);
        fflush(log_file);
    }
    fprintf(stderr, "%s: %s\n", ts, event);
}

static void cleanup(void) {
    if (solenoid_state == 0) {
        gpioWrite(SOLENOID_PIN, 1);
        solenoid_state = 1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    pthread_mutex_destroy(&pulse_mutex);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set flow sensor pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set solenoid pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(SOLENOID_PIN, solenoid_state) != 0) {
        fprintf(stderr, "Failed to set initial solenoid state\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, DEBOUNCE_TIME, pulse_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR for flow sensor\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_event("Program started");

    while (running) {
        sleep(1);
        double dt = 1.0;
        int pulses = 0;
        pthread_mutex_lock(&pulse_mutex);
        pulses = pulse_count;
        pulse_count = 0;
        pthread_mutex_unlock(&pulse_mutex);

        if (dt > 0.0) {
            double lpm = calculate_lpm(pulses, dt);
            char msg[128];
            snprintf(msg, sizeof(msg), "Flow: %.2f LPM", lpm);
            log_event(msg);

            if (lpm > FLOW_THRESHOLD && solenoid_state == 1) {
                if (gpioWrite(SOLENOID_PIN, 0) == 0) {
                    solenoid_state = 0;
                    log_event("Solenoid valve closed");
                } else {
                    log_event("Error: Failed to close solenoid valve");
                }
            } else if (lpm < (FLOW_THRESHOLD - FLOW_HYSTERESIS) && solenoid_state == 0) {
                if (gpioWrite(SOLENOID_PIN, 1) == 0) {
                    solenoid_state = 1;
                    log_event("Solenoid valve opened");
                } else {
                    log_event("Error: Failed to open solenoid valve");
                }
            }
        }
    }

    log_event("Program shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

