#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define HX711_DATA_PIN 23
#define HX711_CLOCK_PIN 24
#define SERVO_PIN 18
#define DEFAULT_HOST "127.0.0.1"
#define DEFAULT_PORT 12345
#define DEFAULT_API_CALL "dispense_ingredient"
#define DEFAULT_CALIBRATION_FACTOR 1.0
#define DEFAULT_KNOWN_WEIGHT 100.0
#define DEFAULT_LOG_FILE "dispensing_log.json"
#define MAX_RETRIES 3
#define MAX_RETRIES_PER_READ 10
#define READ_TIMEOUT_US 1000000
#define DISPENSE_DELAY_US 1000000
#define SERVO_MIN_US 1000
#define SERVO_MAX_US 2000

static volatile sig_atomic_t running = 1;
static int server_fd = -1;
static int api_call_fd = -1;
static FILE *log_file = NULL;
static double calibration_factor = DEFAULT_CALIBRATION_FACTOR;
static double known_weight = DEFAULT_KNOWN_WEIGHT;
static char *host = DEFAULT_HOST;
static int port = DEFAULT_PORT;
static char *log_file_path = DEFAULT_LOG_FILE;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioWrite(SERVO_PIN, 0);
    return 0;
}

static int init_socket(void) {
    struct sockaddr_in address;
    int opt = 1;
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        return -1;
    }
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt failed");
        close(server_fd);
        return -1;
    }
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = inet_addr(host);
    address.sin_port = htons(port);
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        close(server_fd);
        return -1;
    }
    if (listen(server_fd, 3) < 0) {
        perror("listen failed");
        close(server_fd);
        return -1;
    }
    return 0;
}

static int init_log(void) {
    log_file = fopen(log_file_path, "a");
    if (!log_file) {
        perror("fopen log failed");
        return -1;
    }
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "[{\"timestamp\":\"\",\"target_weight\":0,\"actual_weight\":0,\"error\":\"\"}]\n");
    }
    return 0;
}

static int read_hx711(int32_t *raw_value) {
    int i;
    int data = 0;
    for (i = 0; i < MAX_RETRIES_PER_READ; i++) {
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1);
        data = gpioRead(HX711_DATA_PIN);
        if (data < 0) {
            fprintf(stderr, "gpioRead failed on DATA pin\n");
            return -1;
        }
        if (data == 0) break;
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1);
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1);
        if (i < MAX_RETRIES_PER_READ - 1) {
            gpioDelay(1);
        }
    }
    if (i >= MAX_RETRIES_PER_READ) {
        fprintf(stderr, "HX711 DATA pin stuck HIGH after %d attempts\n", i);
        return -1;
    }
    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1);
        data = gpioRead(HX711_DATA_PIN);
        if (data < 0) {
            fprintf(stderr, "gpioRead failed on DATA pin\n");
            return -1;
        }
        if (data == 1) {
            raw_value[i] = 1;
        } else {
            raw_value[i] = 0;
        }
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1);
    }
    if (raw_value[0] == 1) {
        raw_value[0] = 0;
    }
    return 0;
}

static double calibrate_weight(int32_t raw_value) {
    return (double)raw_value / known_weight * calibration_factor;
}

static int dispense_ingredient(double target_weight) {
    double actual_weight = calibrate_weight(raw_value);
    if (actual_weight < 0) {
        fprintf(stderr, "Invalid weight reading\n");
        return -1;
    }
    double pulse_width = (target_weight - actual_weight) * (SERVO_MAX_US - SERVO_MIN_US) / (actual_weight - known_weight);
    if (pulse_width < SERVO_MIN_US) pulse_width = SERVO_MIN_US;
    if (pulse_width > SERVO_MAX_US) pulse_width = SERVO_MAX_US;
    gpioServo(SERVO_PIN, pulse_width);
    gpioDelay(DISPENSE_DELAY_US);
    gpioServo(SERVO_PIN, 0);
    return 0;
}

static int log_event(double target_weight, double actual_weight, const char *error_msg) {
    time_t now = time(NULL);
