    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    int last_touch_state = 0;
    int relay_state = 0;
    int last_relay_state = 0;

    printf("Monitoring touch sensor on GPIO %d, relay on GPIO %d. Debounce: %d ms. Press Ctrl+C to exit.\n",
           TOUCH_SENSOR_PIN, RELAY_PIN, debounce_ms);
    fflush(stdout);

    while (running) {
        int touch_state = gpioRead(TOUCH_SENSOR_PIN);
        if (touch_state < 0) {
            fprintf(stderr, "Error: failed to read touch sensor pin\n");
            break;
        }

        if (touch_state == 1 && last_touch_state == 0) {
            gpioDelay(debounce_ms * 1000);
            int confirm_touch_state = gpioRead(TOUCH_SENSOR_PIN);
            if (confirm_touch_state == 1) {
                relay_state = !relay_state;
                if (gpioWrite(RELAY_PIN, relay_state) != 0) {
                    fprintf(stderr, "Error: failed to write relay pin\n");
                    break;
                }
                relay_state = !relay_state;
                last_relay_state = relay_state;
                log_state(relay_state);
            }
        }

        last_touch_state = touch_state;
        gpioDelay(POLL_DELAY_US);
    }

    cleanup_gpio();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

