/*
 * servo_keyboard.c — Adjust an SG90 servo via keyboard input on Raspberry Pi.
 *
 * Wiring:
 *   BCM 18 (physical pin 12) -> servo signal line
 *   5 V  -> servo VCC (red)
 *   GND  -> servo GND  (black)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o servo_keyboard servo_keyboard.c -lm
 *
 * Run:
 *   ./servo_keyboard
 */

#include <errno.h>
#include <fcntl.h>
#include <signal.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <termios.h>
#include <unistd.h>

#include <gpiod.h>

#define SERVO_PIN        18          /* BCM 18, physical pin 12 */
#define SERVO_FREQ_HZ    50          /* 50 Hz -> 20 ms period */
#define SERVO_MIN_US     500         /* 0°   */
#define SERVO_MAX_US     2500        /* 180° */
#define STEP_DEG         10
#define MIN_ANGLE        0
#define MAX_ANGLE        180
#define CONSUMER         "servo_keyboard"

static volatile sig_atomic_t g_stop = 0;

static void sigint_handler(int signo)
{
    (void)signo;
    g_stop = 1;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGQUIT, &sa, NULL) == -1) {
        perror("sigaction(SIGQUIT)");
        return -1;
    }
    return 0;
}

static int restore_terminal_settings(int fd)
{
    struct termios orig, cur;
    if (tcgetattr(fd, &orig) != 0) {
        perror("tcgetattr");
        return -1;
    }
    if (tcsetattr(fd, TCSANOW, &orig) != 0) {
        perror("tcsetattr");
        return -1;
    }
    return 0;
}

int main(void)
{
    int fd = -1;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int angle = 90;
    int rc = EXIT_SUCCESS;

    if (install_signal_handlers() != 0)
        return EXIT_FAILURE;

    /* --- Open the default gpiochip (gpiochip4 on Pi 5, gpiochip0 on Pi 4) --- */
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, SERVO_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(line, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    /* --- Open the terminal device for raw input --- */
    fd = open("/dev/tty", O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd == -1) {
        perror("open /dev/tty");
        goto cleanup;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("tcgetattr");
        goto cleanup;
    }

    /* Raw input: no echo, no canonical processing, no signals */
    tty.c_lflag &= ~(ICANON | ECHO | ECHOE | ECHONL | ISIG);
    tty.c_iflag &= ~(IXON | IXOFF | IXANY);
    tty.c_oflag &= ~OPOST;
    tty.c_cc[VMIN]  = 0;
    tty.c_cc[VTIME] = 0;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("tcsetattr");
        goto cleanup;
    }

    /* --- Main loop --- */
    while (!g_stop) {
        int c;
        ssize_t n = read(fd, &c, 1);
        if (n == -1) {
            if (errno == EINTR)
                continue;
            perror("read");
            goto cleanup;
        }
        if (n == 0) {
            /* VTIME expired with no input — just loop */
            continue;
        }

        switch (c) {
        case '+':
            angle += STEP_DEG;
            if (angle > MAX_ANGLE) angle = MAX_ANGLE;
            if (gpiod_line_set_value(line, 1) < 0) {
                perror("gpiod_line_set_value(high)");
                goto cleanup;
            }
            printf("Angle: %d°\n", angle);
            break;
        case '-':
            angle -= STEP_DEG;
            if (angle < MIN_ANGLE) angle = MIN_ANGLE;
            if (gpiod_line_set_value(line, 0) < 0) {
                perror("gpiod_line_set_value(low)");
                goto cleanup;
            }
            printf("Angle: %d°\n", angle);
            break;
        case 'q':
        case 'Q':
            g_stop = 1;
            break;
        default:
            if (c != '\n')
                printf("Invalid input '%c'.\n", c);
            break;
        }

        /* Generate a 20 ms pulse at the current angle */
        long pw = (long)angle * 1000L / MAX_ANGLE;   /* 0..20000 */
        if (gpiod_line_set_value(line, 1) < 0) {
            perror("gpiod_line_set_value(high)");
            goto cleanup;
        }
        usleep((useconds_t)pw);
        if (gpiod_line_set_value(line, 0) < 0) {
            perror("gpiod_line_set_value(low)");
            goto cleanup;
        }
    }

    /* --- Graceful shutdown: stop PWM pulses and restore terminal --- */
    if (gpiod_line_set_value(line, 0) < 0) {
        perror("gpiod_line_set_value(final off)");
        rc = EXIT_FAILURE;
    }
    if (restore_terminal_settings(fd) != 0)
        rc = EXIT_FAILURE;

cleanup:
    if (line)
        gpiod_line_release(line);
    if (chip)
        gpiod_chip_close(chip);
    if (fd != -1)
        close(fd);
    return rc;
}

