#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define HALL_SENSOR_GPIO 17
#define DEBOUNCE_US      2000   /* 2 ms debounce window */
#define SAMPLE_INTERVAL  5      /* seconds between RPM reports */
#define LOG_FILE         "motor_rpm.log"

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Monotonic clock (CLOCK_MONOTONIC)                                  */
/* ------------------------------------------------------------------ */
static double monotonic_seconds(void)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
        return -1.0;
    }
    return (double)ts.tv_sec + (double)ts.tv_nsec / 1.0e9;
}

/* ------------------------------------------------------------------ */
/* Pulse counter with debounce                                        */
/* ------------------------------------------------------------------ */
typedef struct {
    int      pulses;          /* number of rising edges since last report */
    uint32_t last_tick;       /* pigpio tick of the last accepted edge */
    uint32_t last_edge_tick;  /* pigpio tick of the most recent edge */
    int      edge_seen;       /* 1 if a rising edge was seen since boot */
} pulse_counter_t;

static void pulse_counter_init(pulse_counter_t *c)
{
    c->pulses      = 0;
    c->last_tick   = 0;
    c->last_edge_tick = 0;
    c->edge_seen   = 0;
}

static void pulse_counter_tick(pulse_counter_t *c, uint32_t tick)
{
    if (c->edge_seen) {
        if (tick >= c->last_edge_tick) {
            c->pulses++;
        }
    }
    c->last_edge_tick = tick;
}

/* ------------------------------------------------------------------ */
/* RPM calculation                                                     */
/* ------------------------------------------------------------------ */
static double calculate_rpm(const pulse_counter_t *c)
{
    double elapsed = monotonic_seconds();
    if (elapsed < 0.0)
        return -1.0;

    if (c->pulses == 0.0)
        return 0.0;

    double pulses_per_second = (double)c->pulses / elapsed;
    return 60.0 / pulses_per_second;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_rpm(double rpm, const char *filename)
{
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                filename, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        fclose(fp);
        return;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        fclose(fp);
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return;
    }

    fprintf(fp, "%s,%.2f\n", ts, rpm);
    fflush(fp);
    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- GPIO configuration ---- */
    if (gpioSetMode(HALL_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for GPIO %d\n", HALL_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(HALL_SENSOR_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown failed for GPIO %d\n", HALL_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- pulse counter ---- */
    pulse_counter_t counter;
    pulse_counter_init(&counter);

    /* ---- signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Monitoring motor RPM on GPIO %d (rising edge, pull-up).\n",
           HALL_SENSOR_GPIO);
    printf("Press Ctrl+C to exit.\n");

    /* ---- main loop ---- */
    while (g_running) {
        /* Sleep for the sample interval, interruptible by signals */
        unsigned int remaining = SAMPLE_INTERVAL;
        while (remaining > 0 && g_running) {
            unsigned int chunk = remaining > 100000 ? 100000 : remaining;
            gpioDelay(chunk);
            remaining -= chunk;
        }

        if (!g_running)
            break;

        /* Snapshot the counter */
        pulse_counter_t snapshot;
        pulse_counter_init(&snapshot);
        pulse_counter_tick(&snapshot, gpioTick());

        double rpm = calculate_rpm(&snapshot);

        if (rpm < 0.0) {
            fprintf(stderr, "Clock error — RPM calculation skipped.\n");
        } else {
            printf("RPM: %.2f\n", rpm);
            log_rpm(rpm, LOG_FILE);
        }
    }

    /* ---- cleanup ---- */
    gpioSetAlertFunc(HALL_SENSOR_GPIO, NULL);   /* unregister callback */
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

