        unsigned int remaining = SAMPLE_INTERVAL;
        while (remaining > 0 && g_running) {
            unsigned int chunk = remaining > 100000 ? 100000 : remaining;
            gpioDelay(chunk);
            remaining -= chunk;
        }

        if (!g_running)
            break;

        /* Snapshot the counter */
        pulse_counter_t snapshot;
        pulse_counter_init(&snapshot);
        pulse_counter_tick(&snapshot, gpioTick());

        double rpm = calculate_rpm(&snapshot);

        if (rpm < 0.0) {
            fprintf(stderr, "Clock error — RPM calculation skipped.\n");
        } else {
            printf("RPM: %.2f\n", rpm);
            log_rpm(rpm, LOG_FILE);
        }
    }

    /* ---- cleanup ---- */
    gpioSetAlertFunc(HALL_SENSOR_GPIO, NULL);   /* unregister callback */
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

