/*
 * Closed-loop proportional solenoid valve flow control for Raspberry Pi 4.
 *
 * Hardware:
 *   - ASCO RedHat 8210 proportional solenoid valve (PWM on GPIO 18, BCM)
 *   - YF-S201 flow sensor (analog output) on GPIO 24, BCM, rising-edge ISR
 *   - Valve enable/direction line on GPIO 23, BCM, active-high
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o flow_ctrl flow_ctrl.c -lpigpio -lrt
 *   (run as root or with gpio group access)
 *
 * Usage:
 *   ./flow_ctrl -t <target_flow_L_min>   (e.g., ./flow_ctrl -t 2.5)
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

/* ---- Pin assignments (BCM numbering) ---- */
#define VALVE_PWM_PIN    18
#define VALVE_ENABLE_PIN 23
#define FLOW_SENSOR_PIN  24

/* ---- Tuning constants ---- */
#define KP              1.0f
#define PWM_RANGE       255
#define SAMPLE_PERIOD_US 100000   /* 100 ms */
#define LOG_FILE        "flow_log.csv"

/* ---- Globals ---- */
static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

/* ---- Prototypes ---- */
static void signal_handler(int sig);
static int  initialize_gpio(void);
static int  read_flow_rate(float *flow_out);
static int  compute_duty_cycle(float flow_rate);
static void log_data(float flow_rate, int valve_position);
static void flow_isr(int gpio, int level, uint32_t tick, void *user);
static void cleanup(void);

/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    if (argc != 2) {
        fprintf(stderr, "Usage: %s -t <target_flow_L_min>\n", argv[0]);
        return EXIT_FAILURE;
    }

    float target_flow = 0.0f;
    if (sscanf(argv[1], "%f", &target_flow) != 1) {
        fprintf(stderr, "Invalid flow rate argument: '%s'\n", argv[1]);
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "timestamp_ms,flow_rate_L_min,valve_position\n");
        fflush(g_log_fp);
    }

    /* Enable valve and set PWM range */
    if (gpioPWM(VALVE_PWM_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialize PWM on GPIO %d\n", VALVE_PWM_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioWrite(VALVE_ENABLE_PIN, 1) != 0) {
        fprintf(stderr, "Failed to set GPIO %d high\n", VALVE_ENABLE_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register ISR on flow sensor pin (rising edge) */
    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, 0,
                         flow_isr, NULL) != 0) {
        fprintf(stderr, "Failed to register ISR on GPIO %d\n", FLOW_SENSOR_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Flow control started. Target: %.2f L/min. Press Ctrl+C to exit.\n",
           target_flow);

    /* Main control loop */
    while (g_running) {
        float flow_rate = 0.0f;
        if (read_flow_rate(&flow_rate) != 0) {
            fprintf(stderr, "Flow read error — continuing.\n");
        } else {
            int duty = compute_duty_cycle(flow_rate);
            if (duty < 0) {
                fprintf(stderr, "Duty cycle out of range (%d)\n", PWM_RANGE);
                duty = 0;
            }
            if (gpioPWM(VALVE_PWM_PIN, duty) != 0) {
                fprintf(stderr, "Failed to set PWM on GPIO %d\n", VALVE_PWM_PIN);
            }
            log_data(flow_rate, duty);
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* Graceful shutdown */
    printf("\nShutting down...\n");
    gpioPWM(VALVE_PWM_PIN, 0);
    gpioWrite(VALVE_ENABLE_PIN, 0);
    cleanup();
    return EXIT_SUCCESS;
}

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed.\n");
        return -1;
    }

    /* Configure PWM pin */
    if (gpioSetMode(VALVE_PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", VALVE_PWM_PIN);
        return -1;
    }
    if (gpioSetPWMrange(VALVE_PWM_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", VALVE_PWM_PIN);
        return -1;
    }
    if (gpioPWM(VALVE_PWM_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialize PWM duty cycle on GPIO %d\n",
                VALVE_PWM_PIN);
        return -1;
    }

    /* Configure enable pin as output, initially high */
    if (gpioSetMode(VALVE_ENABLE_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", VALVE_ENABLE_PIN);
        return -1;
    }
    if (gpioWrite(VALVE_ENABLE_PIN, 1) != 0) {
        fprintf(stderr, "Failed to set GPIO %d high\n", VALVE_ENABLE_PIN);
        return -1;
    }

    /* Configure flow sensor pin as input */
    if (gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", FLOW_SENSOR_PIN);
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
static int read_flow_rate(float *flow_out)
{
    /* pigpio ISR callback runs in a pigpio thread — keep it short */
    static uint32_t last_tick = 0;
    static int      last_level = 0;

    uint32_t now = gpioTick();
    if (now == last_tick && last_level == 1) {
        /* No new edge — return 0.0 */
        return 0;
    }
    last_tick = now;
    last_level = gpioRead(FLOW_SENSOR_PIN);

    /* Convert tick to microseconds (32-bit wraparound-safe) */
    uint32_t diff = now - last_tick;
    if (diff > 0) {
        float period_us = (float)diff;
        if (period_us > 0.0f) {
            float period_s  = period_us / 1.0e6f;
            float flow_rate = 60.0f / period_s;
            *flow_out = flow_rate;
            return 0;
        }
    }
    return 1;  /* error / no new data */
}

/* ------------------------------------------------------------------ */
static int compute_duty_cycle(float flow_rate)
{
    float error = target_flow - flow_rate;
    int   duty  = (int)(KP * error);
    if (duty < 0)   duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;
    return duty;
}

/* ------------------------------------------------------------------ */
static void log_data(float flow_rate, int valve_position)
{
    if (g_log_fp == NULL) return;

    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(g_log_fp, "%s.%03ld,%.2f,%d\n",
            timestamp, ts.tv_nsec / 1000000L, flow_rate, valve_position);
    fflush(g_log_fp);
}

/* ------------------------------------------------------------------ */
static void flow_isr(int gpio, int level, uint32_t tick, void *user)
{
    (void)gpio;
    (void)user;

    if (level == 1) {
        float flow_rate = 0.0f;
        if (read_flow_rate(&flow_rate) == 0) {
            int duty = compute_duty_cycle(flow_rate);
            if (gpioPWM(VALVE_PWM_PIN, duty) != 0) {
                fprintf(stderr, "PWM write failed in ISR\n");
            }
        }
    }
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Ensure valve is off and enable is low */
    gpioPWM(VALVE_PWM_PIN, 0);
    gpioWrite(VALVE_ENABLE_PIN, 0);

    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }

    gpioTerminate();
}

