#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <rfid.h>

#define LOCK1_GPIO 17
#define LOCK2_GPIO 27
#define BUTTON_GPIO 22
#define SPI_CHANNEL 0
#define SPI_SPEED 100000
#define LOG_FILE "/var/log/door_access.log"
#define TAG_LENGTH 10
#define DEBOUNCE_US 50000
#define LOCK_DISARM_TIME 5
#define POLL_DELAY_US 100000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];
    localtime_r(&now, &tm_info);
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info);
    fprintf(log_file, "%s: %s\n", ts, message);
    fflush(log_file);
}

static int read_rfid_tag(char *tag) {
    int ret;
    for (int attempt = 0; attempt < 4; attempt++) {
        ret = rfid_call(spi_handle, Rfid_ReadTag, (char *)tag, TAG_LENGTH);
        if (ret == 0) return 0;
        log_event("RFID read failed (attempt 1).");
        gpioDelay(10000);
    }
    log_event("RFID read failed after 4 attempts.");
    return -1;
}

static int verify_tag(const char *tag) {
    /* YM-180 10-byte tag: 2-byte header + 8-byte data */
    if (tag[0] != 0x01 || tag[1] != 0x02) return 0;
    for (int i = 0; i < 8; i++) {
        if (tag[i + 2] != (tag[i] ^ 0x08)) return 0;
    }
    return 1;
}

static void disengage_locks(void) {
    gpioWrite(LOCK1_GPIO, 0);
    gpioWrite(LOCK2_GPIO, 0);
    log_event("Locks disengaged.");
}

static void reengage_locks(void) {
    gpioWrite(LOCK1_GPIO, 1);
    gpioWrite(LOCK2_GPIO, 1);
    log_event("Locks re-engaged.");
}

static void cleanup(void) {
    disengage_locks();
    if (spi_handle >= 0) {
        rfid_close(spi_handle);
        spi_handle = -1;
    }
    if (log_file) {
        log_event("Program terminated.");
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    char tag[TAG_LENGTH];
    int button_pressed = 0;
    int lock_engaged = 1;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(LOCK1_GPIO, PI_OUTPUT) != 0 ||
        gpioSetMode(LOCK2_GPIO, PI_OUTPUT) != 0 ||
        gpioSetMode(BUTTON_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return 1;
    }

    gpioSetPullUpDown(BUTTON_GPIO, PI_PUD_UP);

    spi_handle = rfid_open(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "RFID open failed\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen log");
        rfid_close(spi_handle);
        spi_handle = -1;
        gpioTerminate();
        return 1;
    }

    log_event("Program started.");

    while (running) {
        if (rfid_read(spi_handle, tag, TAG_LENGTH) != 0) {
            log_event("RFID read error.");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        if (read_rfid_tag(tag) != 0) {
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        if (verify_tag(tag)) {
            log_event("Valid RFID tag read.");
            if (gpioRead(BUTTON_GPIO) == 0) {
                button_pressed = 1;
                log_event("Button pressed.");
            }
        } else {
            log_event("Invalid RFID tag.");
        }

        if (button_pressed) {
            button_pressed = 0;
            gpioDelay(DEBOUNCE_US);
            if (gpioRead(BUTTON_GPIO) == 0) {
                lock_engaged = 0;
                log_event("Button confirmed.");
            }
        }

        if (lock_engaged) {
            disengage_locks();
            log_event("Disarming locks.");
            gpioDelay(LOCK_DISARM_TIME * 1000000);
            reengage_locks();
            log_event("Locks re-engaged.");
        }

        gpioDelay(POLL_DELAY_US);
    }

    cleanup();
    return 0;
}

