#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <pthread.h>
#include <time.h>
#include <string.h>
#include <errno.h>
#include <math.h>
#include <gpiod.h>

#define MOTOR1_ENA 23
#define MOTOR1_IN1 24
#define MOTOR1_IN2 25
#define MOTOR2_ENB 12
#define MOTOR2_IN3 16
#define MOTOR2_IN4 20
#define ENCODER1_A 5
#define ENCODER1_B 6
#define ENCODER2_A 26
#define ENCODER2_B 19

#define PWM_PERIOD_NS 10000000  /* 100 Hz */
#define SAMPLE_PERIOD_NS 10000000  /* 100 ms */
#define TARGET_SPEED 60.0
#define MAX_SPEED 100.0
#define MIN_SPEED 0.0
#define MAX_DUTY 255
#define MIN_DUTY 0
#define LOG_FILE "motor_log.csv"

typedef struct {
    double Kp, Ki, Kd;
    double integral, previous_error;
} PIDController;

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *motor_lines[6];
static struct gpiod_line *encoder_lines[2];
static pthread_mutex_t motor_mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_mutex_t encoder_mutex = PTHREAD_MUTEX_INITIALIZER;
static double motor1_speed = 0.0, motor2_speed = 0.0;
static PIDController pid1 = {2.0, 0.1, 0.01, 0.0, 0.0};
static PIDController pid2 = {2.0, 0.1, 0.01, 0.0, 0.0};

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (log_file) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    for (int i = 0; i < 6; i++) {
        if (motor_lines[i]) {
            gpiod_line_release(motor_lines[i]);
            motor_lines[i] = NULL;
        }
    }
    for (int i = 0; i < 2; i++) {
        if (encoder_lines[i]) {
            gpiod_line_release(encoder_lines[i]);
            encoder_lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    motor_lines[0] = gpiod_chip_get_line(chip, MOTOR1_ENA);
    motor_lines[1] = gpiod_chip_get_line(chip, MOTOR1_IN1);
    motor_lines[2] = gpiod_chip_get_line(chip, MOTOR1_IN2);
    motor_lines[3] = gpiod_chip_get_line(chip, MOTOR2_ENB);
    motor_lines[4] = gpiod_chip_get_line(chip, MOTOR2_IN3);
    motor_lines[5] = gpiod_chip_get_line(chip, MOTOR2_IN4);

    encoder_lines[0] = gpiod_chip_get_line(chip, ENCODER1_A);
    encoder_lines[1] = gpiod_chip_get_line(chip, ENCODER1_B);
    encoder_lines[2] = gpiod_chip_get_line(chip, ENCODER2_A);
    encoder_lines[3] = gpiod_chip_get_line(chip, ENCODER2_B);

    if (!motor_lines[0] || !motor_lines[1] || !motor_lines[2] ||
        !motor_lines[3] || !motor_lines[4] || !motor_lines[5] ||
        !encoder_lines[0] || !encoder_lines[1] || !encoder_lines[2] || !encoder_lines[3]) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        cleanup();
        return -1;
    }

    if (gpiod_line_request_output(motor_lines[0], "motor1_ena", 0) < 0 ||
        gpiod_line_request_output(motor_lines[1], "motor1_in1", 0) < 0 ||
        gpiod_line_request_output(motor_lines[2], "motor1_in2", 0) < 0 ||
        gpiod_line_request_output(motor_lines[3], "motor2_enb", 0) < 0 ||
        gpiod_line_request_output(motor_lines[4], "motor2_in3", 0) < 0 ||
        gpiod_line_request_output(motor_lines[5], "motor2_in4", 0) < 0) {
        fprintf(stderr, "Failed to request motor output lines: %s\n", strerror(errno));
        cleanup();
        return -1;
    }

    if (gpiod_line_request_both_edges_events(encoder_lines[0], "encoder1_a") < 0 ||
        gpiod_line_request_both_edges_events(encoder_lines[1], "encoder1_b") < 0 ||
        gpiod_line_request_both_edges_events(encoder_lines[2], "encoder2_a") < 0 ||
        gpiod_line_request_both_edges_events(encoder_lines[3], "encoder2_b") < 0) {
        fprintf(stderr, "Failed to request encoder lines: %s\n", strerror(errno));
        cleanup();
        return -1;
    }

    return 0;
}

static int read_encoder(int *a, int *b) {
    int va, vb;
    va = gpiod_line_get_value(encoder_lines[0]);
    vb = gpiod_line_get_value(encoder_lines[1]);
    if (va < 0 || vb < 0) return -1;
    if (va == vb) return 0;
    if (va == 1) {
        *a = 1;
        *b = 0;
    } else {
        *a = 0;
        *b = 1;
    }
    return 1;
}

static void *encoder_thread(void *arg) {
    int *a1, *b1, *a2, *b2;
    a1 = (int *)arg;
    a2 = NULL;
    b1 = NULL;
    b2 = NULL;

    while (running) {
        int va1, vb1, va2, vb2;
        va1 = gpiod_line_get_value(encoder_lines[0]);
        vb1 = gpiod_line_get_value(encoder_lines[1]);
        va2 = gpiod_line_get_value(encoder_lines[2]);
        vb2 = gpiod_line_get_value(encoder_lines[3]);

        if (va1 < 0 || vb1 < 0 || va2 < 0 || vb2 < 0) {
            fprintf(stderr, "Encoder read error: %s\n", strerror(errno));
            break;
        }

        if (read_encoder(a1, b1) == 1) {
            if (a1 == 1 && b1 == 0) a1 = 0;
            else if (a1 == 0 && b1 == 1) a1 = 1;
        }
        if (read_encoder(a2, b2) == 1) {
            if (a2 == 1 && b2 == 0) a2 = 0;
            else if (a2 == 0 && b2 == 1) a2 = 1;
        }

        pthread_mutex_lock(&motor_mutex);
        motor1_speed += (double)a1 - (double)a2;
        motor2_speed += (double)a2 - (double)a1;
        pthread_mutex_unlock(&motor_mutex);

        pthread_mutex_lock(&encoder_mutex);
        if (a1) *a1 = a1;
        if (b1) *b1 = b1;
        if (a2) *a2 = a2;
        if (b2) *b2 = b2;
        pthread_mutex_unlock(&encoder_mutex);
    }
    return NULL;
}

static void set_motor_speed(int motor, double speed) {
    int duty;
    if (speed < MIN_SPEED) speed = MIN_SPEED;
    if (speed > MAX_SPEED) speed = MAX_SPEED;
    duty = (int)((speed / MAX_SPEED) * MAX_DUTY);
    if (duty < MIN_DUTY) duty = MIN_DUTY;
    if (duty > MAX_DUTY) duty = MAX_DUTY;

    pthread_mutex_lock(&motor_mutex);
    if (motor == 1) {
        gpiod_line_set_value(motor_lines[1], duty > 0 ? 1 : 0);
        gpiod_line_set_value(motor_lines[2], duty > 0 ? 1 : 0);
    } else {
        gpiod_line_set_value(motor_lines[3], duty > 0 ? 1 : 0);
        gpiod_line_set_value(motor_lines[4], duty > 0 ? 1 : 0);
        gpiod_line_set_value(motor_lines[5], duty > 0 ? 1 : 0);
    }
    pthread_mutex_unlock(&motor_mutex);
}

static double calculate_pid(double current, double target, double dt) {
    double error = target - current;
    pid1.integral += error * dt;
    pid1.previous_error = error;
    double derivative = (error - pid1.previous_error) / dt;
    double output = pid1.Kp * error + pid1.Ki * pid1.integral + pid1.Kd * derivative;
    pid1.integral = 0.0;
    return output;
}

static void log_data(double m1, double m2, double p1, double i1, double d1, double p2, double i2, double d2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n",
            timestamp, m1, m2, p1, i1, d1, p2, i2, d2);
    fflush(log_file);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_gpio() != 0) return 1;

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    fprintf(log_file, "Timestamp,Motor1_Speed,RPM,Motor1_P,Motor1_I,Motor1_D,Motor2_P,Motor2_I,Motor2_D\n");

    pthread_t e1, e2;
    if (pthread_create(&e1, NULL, encoder_thread, (void*)&motor1_speed) != 0) {
        fprintf(stderr, "Failed to create encoder thread 1: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    if (pthread_create(&e2, NULL, encoder_thread, (void*)&motor2_speed) != 0) {
        fprintf(stderr, "Failed to create encoder thread 2: %s\n", strerror(errno));
        running = 0;
        pthread_join(e1, NULL);
        cleanup();
        return 1;
    }

    struct timespec sleep_time = {0, SAMPLE_PERIOD_NS};
    while (running) {
        double p1, i1, d1, p2, i2, d2;
        p1 = pid1.calculate_pid(motor1_speed, TARGET_SPEED, sleep_time.tv_sec);
        i1 = pid1.integral;
        d1 = pid1.d;
        p2 = pid2.calculate_pid(motor2_speed, TARGET_SPEED, sleep_time.tv_sec);
        i2 = pid2.integral;
        d2 = pid2.d;

        set_motor_speed(1, motor1_speed);
        set_motor_speed(2, motor2_speed);
        log_data(motor1_speed, motor2_speed, p1, i1, d1, p2, i2, d2);

        nanosleep(&sleep_time, NULL);
    }

    pthread_join(e1, NULL);
    pthread_join(e2, NULL);
    cleanup();
    return 0;
}

