/*
 * MPR121 Capacitive Touch Sensor – Relay Control with Logging
 * Board:  Raspberry Pi 3 Model B+
 * Bus:    I2C bus 1 (GPIO2=SDA, GPIO3=SCL)
 * Relay:  GPIO17 (BCM) – active HIGH
 * Log:    relay_log.txt
 *
 * Build:  gcc -O2 -Wall -o mpr121_relay mpr121_relay.c -lpigpio -lrt
 * Run:    sudo ./mpr121_relay
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS            1
#define MPR121_ADDR        0x60          /* MPR121 default 7-bit address */
#define RELAY_GPIO         17            /* BCM 17 */
#define POLL_DELAY_US      50000         /* 50 ms */
#define LOG_FILE           "relay_log.txt"

/* MPR121 register addresses */
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_MHDR          0x2B
#define MPR121_NHDR          0x2C
#define MPR121_NCLR          0x2D
#define MPR121_FDLR          0x2E
#define MPR121_MHDF          0x2F
#define MPR121_NHDF          0x30
#define MPR121_NCLF          0x31
#define MPR121_FDLF          0x32
#define MPR121_NHDT          0x33
#define MPR121_NCLT          0x34
#define MPR121_FDLT          0x35
#define MPR121_E0TTH         0x41
#define MPR121_E0RTH         0x42
#define MPR121_DEBOUNCE      0x5B
#define MPR121_CONFIG1       0x5C
#define MPR121_CONFIG2       0x5D
#define MPR121_ECR           0x5E
#define MPR121_SOFTRESET     0x80

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* --------------------------- Function prototypes -------------------------- */
static int  mpr121_write(int handle, uint8_t reg, uint8_t value);
static int  mpr121_read(int handle, uint8_t reg, uint8_t *buf, uint8_t len);
static int  mpr121_init(int handle);
static int  relay_set(int state);
static void log_relay_state(int state);
static void signal_handler(int sig);

/* ------------------------------- I2C helpers ----------------------------- */
static int mpr121_write(int handle, uint8_t reg, uint8_t value)
{
    char buf[2] = { (char)reg, (char)value };
    if (i2cWriteDevice(handle, buf, 2) != 0) {
        fprintf(stderr, "[ERROR] I2C write to reg 0x%02X failed\n", reg);
        return -1;
    }
    return 0;
}

static int mpr121_read(int handle, uint8_t reg, uint8_t *buf, uint8_t len)
{
    if (i2cWriteDevice(handle, (char *)&reg, 1) != 0) {
        fprintf(stderr, "[ERROR] I2C write (reg select 0x%02X) failed\n", reg);
        return -1;
    }
    if (i2cReadDevice(handle, (char *)buf, len) != len) {
        fprintf(stderr, "[ERROR] I2C read from reg 0x%02X failed\n", reg);
        return -1;
    }
    return 0;
}

/* --------------------------- MPR121 init --------------------------------- */
static int mpr121_init(int handle)
{
    /* 1. Soft reset */
    if (mpr121_write(handle, MPR121_SOFTRESET, 0x63) != 0) return -1;
    gpioDelay(2000);  /* 2 ms settle after reset */

    /* 2. Configuration registers */
    if (mpr121_write(handle, MPR121_MHDR, 0x01) != 0) return -1;
    if (mpr121_write(handle, MPR121_NHDR, 0x01) != 0) return -1;
    if (mpr121_write(handle, MPR121_NCLR, 0x0E) != 0) return -1;
    if (mpr121_write(handle, MPR121_FDLR, 0x00) != 0) return -1;
    if (mpr121_write(handle, MPR121_MHDF, 0x01) != 0) return -1;
    if (mpr121_write(handle, MPR121_NHDF, 0x05) != 0) return -1;
    if (mpr121_write(handle, MPR121_NCLF, 0x01) != 0) return -1;
    if (mpr121_write(handle, MPR121_FDLF, 0x00) != 0) return -1;
    if (mpr121_write(handle, MPR121_NHDT, 0x00) != 0) return -1;
    if (mpr121_write(handle, MPR121_NCLT, 0x00) != 0) return -1;
    if (mpr121_write(handle, MPR121_FDLT, 0x00) != 0) return -1;

    /* 3. Touch / release thresholds for all 12 electrodes */
    for (int i = 0; i < 12; i++) {
        if (mpr121_write(handle, MPR121_E0TTH + (i * 2), 0x0F) != 0) return -1;
        if (mpr121_write(handle, MPR121_E0RTH + (i * 2), 0x0A) != 0) return -1;
    }

    /* 4. Debounce: 3 samples for both touch and release */
    if (mpr121_write(handle, MPR121_DEBOUNCE, 0x33) != 0) return -1;

    /* 5. FFI=00 (6 samples), CDC=16 µA, CDT=0.5 µs */
    if (mpr121_write(handle, MPR121_CONFIG1, 0x10) != 0) return -1;
    if (mpr121_write(handle, MPR121_CONFIG2, 0x20) != 0) return -1;

    /* 6. Enable 12 electrodes, baseline tracking */
    if (mpr121_write(handle, MPR121_ECR, 0x8C) != 0) return -1;

    return 0;
}

/* ------------------------------ Relay control ---------------------------- */
static int relay_set(int state)
{
    if (gpioWrite(RELAY_GPIO, state ? 1 : 0) != 0) {
        fprintf(stderr, "[ERROR] gpioWrite(%d) failed\n", RELAY_GPIO);
        return -1;
    }
    return 0;
}

/* ------------------------------ Logging ---------------------------------- */
static void log_relay_state(int state)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "[ERROR] Cannot open log file '%s'\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d – Relay: %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                state ? "ON" : "OFF");
    } else {
        fprintf(fp, "[timestamp error] – Relay: %s\n", state ? "ON" : "OFF");
    }

    fclose(fp);
}

/* ------------------------------- Signal handler --------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------------- Main ---------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, MPR121_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize MPR121 */
    if (mpr121_init(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] MPR121 initialization failed – sensor may be absent or bus error\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure relay GPIO */
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "[FATAL] gpioSetMode(%d, PI_OUTPUT) failed\n", RELAY_GPIO);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);  /* relay OFF at startup */

    /* Install signal handler */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGINT) failed; Ctrl-C will not shut down cleanly\n");
    }

    printf("MPR121 ready. Polling every %d µs. Press Ctrl-C to exit.\n",
           POLL_DELAY_US / 1000);

    int relay_state = 0;

    while (g_running) {
        uint8_t status[2];

        if (mpr121_read(g_i2c_handle, MPR121_TOUCHSTATUS_L, status, 2) != 0) {
            fprintf(stderr, "[ERROR] Touch status read failed – retrying\n");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        /* Touch any electrode -> relay ON; no touch -> relay OFF */
        int any_touched = (status[0] != 0x00);
        relay_state = any_touched ? 1 : 0;

        if (relay_set(relay_state) != 0) {
            fprintf(stderr, "[ERROR] relay_set failed\n");
        }

        log_relay_state(relay_state);

        gpioDelay(POLL_DELAY_US);
    }

    /* --------------------------- Graceful shutdown ----------------------- */
    printf("\nShutting down...\n");
    relay_set(0);  /* ensure relay is OFF */
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

