#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define VALVE1_GPIO 17
#define VALVE2_GPIO 18
#define LOG_FILE "valve_log.txt"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_event(const char *message) {
    time_t now = time(NULL);
    struct tm tm_info;
    char timestamp[32];

    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(log_file, "%s: %s\n", timestamp, message) < 0) {
        fprintf(stderr, "fprintf to log file failed\n");
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "fflush failed\n");
        return -1;
    }

    return 0;
}

static int activate_valve(int gpio_pin, int duration_ms) {
    if (gpioWrite(gpio_pin, 1) != 0) {
        fprintf(stderr, "Failed to set GPIO %d HIGH\n", gpio_pin);
        return -1;
    }

    gpioDelay(duration_ms * 1000);

    if (gpioWrite(gpio_pin, 0) != 0) {
        fprintf(stderr, "Failed to set GPIO %d LOW\n", gpio_pin);
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    /* Ensure valves are closed before releasing GPIO */
    gpioWrite(VALVE1_GPIO, 0);
    gpioWrite(VALVE2_GPIO, 0);

    gpioTerminate();
}

int main(void) {
    int rc;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    rc = gpioInitialise();
    if (rc < 0) {
        fprintf(stderr, "pigpio initialisation failed with code %d\n", rc);
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins as outputs */
    if (gpioSetMode(VALVE1_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", VALVE1_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(VALVE2_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", VALVE2_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Ensure valves start in the closed state */
    if (gpioWrite(VALVE1_GPIO, 0) != 0 || gpioWrite(VALVE2_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to initialize valve states\n");
        cleanup();
        return EXIT_FAILURE;
    }

    log_event("Water distribution system started");

    while (running) {
        if (activate_valve(VALVE1_GPIO, 500) != 0) {
            break;
        }
        if (log_event("Valve 1 activated for 500ms") != 0) {
            break;
        }
        gpioDelay(5000 * 1000); /* 5 seconds pause */

        if (!running) {
            break;
        }

        if (activate_valve(VALVE2_GPIO, 1000) != 0) {
            break;
        }
        if (log_event("Valve 2 activated for 1000ms") != 0) {
            break;
        }
        gpioDelay(10000 * 1000); /* 10 seconds pause */
    }

    cleanup();
    return EXIT_SUCCESS;
}

