#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MPR121_ADDR 0x60
#define RELAY_GPIO 17
#define I2C_BUS 1

/* MPR121 register addresses */
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_ELECONFIG0 0x5E
#define MPR121_MHDR 0x2B
#define MPR121_NHDR 0x2C
#define MPR121_NCLR 0x2D
#define MPR121_FDLR 0x2E
#define MPR121_MHDF 0x2F
#define MPR121_NHDF 0x30
#define MPR121_NCLF 0x31
#define MPR121_FDLF 0x32
#define MPR121_NHDT 0x33
#define MPR121_NCLT 0x34
#define MPR121_FDLT 0x35
#define MPR121_E0TTH 0x41
#define MPR121_E0RTH 0x42
#define MPR121_DEBOUNCE 0x5B
#define MPR121_CONFIG1 0x5C
#define MPR121_CONFIG2 0x5D
#define MPR121_ECR 0x5E

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int mpr121_write(uint8_t reg, uint8_t value) {
    char buf[2] = { (char)reg, (char)value };
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Error writing 0x%02X to register 0x%02X\n", value, reg);
        return -1;
    }
    return 0;
}

static int mpr121_read(uint8_t reg, uint8_t *value) {
    char reg_buf[1] = { (char)reg };
    if (i2cWriteDevice(i2c_handle, reg_buf, 1) != 0) {
        fprintf(stderr, "Error selecting register 0x%02X\n", reg);
        return -1;
    }
    char data_buf[1];
    if (i2cReadDevice(i2c_handle, data_buf, 1) != 1) {
        fprintf(stderr, "Error reading register 0x%02X\n", reg);
        return -1;
    }
    *value = (uint8_t)data_buf[0];
    return 0;
}

static int mpr121_init(void) {
    uint8_t whoami = 0;
    if (mpr121_read(MPR121_MHDR, &whoami) != 0) return -1;
    if (whoami != 0x10) {
        fprintf(stderr, "MPR121 not found (WHOAMI=0x%02X, expected 0x10)\n", whoami);
        return -1;
    }

    /* Stop mode */
    if (mpr121_write(MPR121_ECR, 0x00) != 0) return -1;

    /* FFI=6 samples, CDC=16µA, CDT=0.5µs */
    if (mpr121_write(MPR121_CONFIG2, 0x20) != 0) return -1;

    /* FDL=4 samples, SFI=4 samples, ESI=4ms */
    if (mpr121_write(MPR121_CONFIG1, 0x10) != 0) return -1;

    /* Debounce: ELE0=4 touches, ELE1=4 releases */
    if (mpr121_write(MPR121_DEBOUNCE, 0x24) != 0) return -1;

    /* Touch and release thresholds for all 12 electrodes */
    for (int i = 0; i < 12; i++) {
        if (mpr121_write(MPR121_E0TTH + (i * 2), 0x0F) != 0) return -1;
        if (mpr121_write(MPR121_E0RTH + (i * 2), 0x0A) != 0) return -1;
    }

    /* Filter settings */
    if (mpr121_write(MPR121_MHDR, 0x01) != 0) return -1;
    if (mpr121_write(MPR121_NHDR, 0x01) != 0) return -1;
    if (mpr121_write(MPR121_NCLR, 0x0E) != 0) return -1;
    if (mpr121_write(MPR121_FDLR, 0x00) != 0) return -1;
    if (mpr121_write(MPR121_MHDF, 0x01) != 0) return -1;
    if (mpr121_write(MPR121_NHDF, 0x05) != 0) return -1;
    if (mpr121_write(MPR121_NCLF, 0x01) != 0) return -1;
    if (mpr121_write(MPR121_FDLF, 0x00) != 0) return -1;
    if (mpr121_write(MPR121_NHDT, 0x00) != 0) return -1;
    if (mpr121_write(MPR121_NCLT, 0x00) != 0) return -1;
    if (mpr121_write(MPR121_FDLT, 0x00) != 0) return -1;

    /* Enable 12 electrodes, baseline tracking */
    if (mpr121_write(MPR121_ECR, 0x8C) != 0) return -1;

    /* 100ms stabilization delay */
    gpioDelay(100000);

    return 0;
}

static int read_touch_status(uint16_t *touch_status) {
    uint8_t low = 0, high = 0;
    if (mpr121_read(MPR121_TOUCHSTATUS_L, &low) != 0) return -1;
    if (mpr121_read(MPR121_TOUCHSTATUS_L + 1, &high) != 0) return -1;
    *touch_status = ((uint16_t)high << 8) | low;
    return 0;
}

static void toggle_relay(void) {
    static int relay_state = 0;
    relay_state = !relay_state;
    if (gpioWrite(RELAY_GPIO, relay_state) != 0) {
        fprintf(stderr, "Error writing relay GPIO %d\n", RELAY_GPIO);
    } else {
        printf("Relay toggled to %s\n", relay_state ? "ON" : "OFF");
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n", I2C_BUS, MPR121_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (mpr121_init() != 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", RELAY_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    uint16_t touch_status = 0;
    while (running) {
        if (read_touch_status(&touch_status) == 0) {
            for (int i = 0; i < 12; i++) {
                if (touch_status & (1 << i)) {
                    printf("Electrode %d touched\n", i);
                    toggle_relay();
                }
            }
        } else {
            fprintf(stderr, "Error reading touch status\n");
        }
        gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    gpioWrite(RELAY_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

