    if (mpr121_write(MPR121_NCLR, 0x0E) != 0) return -1;
    if (mpr121_write(MPR121_FDLR, 0x00) != 0) return -1;
    if (mpr121_write(MPR121_MHDF, 0x01) != 0) return -1;
    if (mpr121_write(MPR121_NHDF, 0x05) != 0) return -1;
    if (mpr121_write(MPR121_NCLF, 0x01) != 0) return -1;
    if (mpr121_write(MPR121_FDLF, 0x00) != 0) return -1;
    if (mpr121_write(MPR121_NHDT, 0x00) != 0) return -1;
    if (mpr121_write(MPR121_NCLT, 0x00) != 0) return -1;
    if (mpr121_write(MPR121_FDLT, 0x00) != 0) return -1;

    /* Enable 12 electrodes, baseline tracking */
    if (mpr121_write(MPR121_ECR, 0x8C) != 0) return -1;

    /* 100ms stabilization delay */
    gpioDelay(100000);

    return 0;
}

static int read_touch_status(uint16_t *touch_status) {
    uint8_t low = 0, high = 0;
    if (mpr121_read(MPR121_TOUCHSTATUS_L, &low) != 0) return -1;
    if (mpr121_read(MPR121_TOUCHSTATUS_L + 1, &high) != 0) return -1;
    *touch_status = ((uint16_t)high << 8) | low;
    return 0;
}

static void toggle_relay(void) {
    static int relay_state = 0;
    relay_state = !relay_state;
    if (gpioWrite(RELAY_GPIO, relay_state) != 0) {
        fprintf(stderr, "Error writing relay GPIO %d\n", RELAY_GPIO);
    } else {
        printf("Relay toggled to %s\n", relay_state ? "ON" : "OFF");
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n", I2C_BUS, MPR121_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (mpr121_init() != 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", RELAY_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    uint16_t touch_status = 0;
    while (running) {
        if (read_touch_status(&touch_status) == 0) {
            for (int i = 0; i < 12; i++) {
                if (touch_status & (1 << i)) {
                    printf("Electrode %d touched\n", i);
                    toggle_relay();
                }
            }
        } else {
            fprintf(stderr, "Error reading touch status\n");
        }
        gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    gpioWrite(RELAY_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

