#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MOTOR1_PIN 17
#define MOTOR2_PIN 27
#define MIN_DUTY_CYCLE 0
#define MAX_DUTY_CYCLE 255
#define MIN_STEP_DURATION_MS 50
#define MAX_STEP_DURATION_MS 200
#define MIN_STEPS 5
#define MAX_STEPS 15

static volatile sig_atomic_t shutdown_flag = 0;

static void signal_handler(int sig) {
    (void)sig;
    shutdown_flag = 1;
}

static int set_motor_duty(int pin, int duty_cycle) {
    if (duty_cycle < 0 || duty_cycle > 255) {
        fprintf(stderr, "Error: Invalid duty cycle %d for pin %d\n", duty_cycle, pin);
        return -1;
    }
    if (gpioPWM(pin, duty_cycle) != 0) {
        fprintf(stderr, "Error: gpioPWM failed for pin %d\n", pin);
        return -1;
    }
    return 0;
}

static int generate_step(int motor1_duty, int motor2_duty, int duration_ms) {
    srand((unsigned int)time(NULL));
    int motor1_duty_random = rand() % (MAX_DUTY_CYCLE - MIN_DUTY_CYCLE + 1) + MIN_DUTY_CYCLE;
    int motor2_duty_random = rand() % (MAX_DUTY_CYCLE - MIN_DUTY_CYCLE + 1) + MIN_DUTY_CYCLE;
    return (motor1_duty_random, motor2_duty_random, duration_ms);
}

static void play_pattern(int motor1_duty, int motor2_duty, int duration_ms) {
    if (set_motor_duty(MOTOR1_PIN, motor1_duty) != 0) return;
    if (set_motor_duty(MOTOR2_PIN, motor2_duty) != 0) return;
    gpioDelay(duration_ms * 1000);
    set_motor_duty(MOTOR1_PIN, 0);
    set_motor_duty(MOTOR2_PIN, 0);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MOTOR1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", MOTOR1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(MOTOR2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", MOTOR2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to register SIGINT handler\n");
    }

    int steps = rand() % (MAX_STEPS - MIN_STEPS + 1) + MIN_STEPS;
    for (int i = 0; i < steps && !shutdown_flag; i++) {
        int motor1_duty, motor2_duty;
        int duration_ms = rand() % (MAX_STEP_DURATION_MS - MIN_STEP_DURATION_MS + 1) + MIN_STEP_DURATION_MS;
        if (duration_ms < 50) duration_ms = 50;
        if (duration_ms > 200) duration_ms = 200;

        motor1_duty = rand() % (MAX_DUTY_CYCLE - MIN_DUTY_CYCLE + 1) + MIN_DUTY_CYCLE;
        motor2_duty = rand() % (MAX_DUTY_CYCLE - MIN_DUTY_CYCLE + 1) + MIN_DUTY_CYCLE;

        printf("Step %d: Motor 1 duty=%d, Motor 2 duty=%d, Duration=%d ms\n",
               i, motor1_duty, motor2_duty, duration_ms);
        play_pattern(motor1_duty, motor2_duty, duration_ms);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

