#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

#define DEFAULT_SCALE_FACTOR 1.0
#define DEFAULT_OFFSET 0.0
#define CALIBRATION_FILE "calibration.txt"
#define LOG_FILE "weight_log.txt"
#define READ_TIMEOUT_MS 500
#define SAMPLE_INTERVAL_US 500000
#define CALIBRATION_SAMPLES 100

static volatile sig_atomic_t running = 1;
static double scale_factor = DEFAULT_SCALE_FACTOR;
static double offset = DEFAULT_OFFSET;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_hx711(int data_pin, int clock_pin) {
    if (gpioSetMode(data_pin, PI_INPUT) < 0) return -1;
    if (gpioSetMode(clock_pin, PI_OUTPUT) < 0) return -1;

    int data = 0;
    int timeout = 0;

    while (data == 0 && timeout < READ_TIMEOUT_MS) {
        gpioWrite(clock_pin, 0);
        gpioDelay(1);
        data = gpioRead(data_pin);
        gpioWrite(clock_pin, 1);
        gpioDelay(1);
        timeout++;
    }

    if (timeout >= READ_TIMEOUT_MS) {
        fprintf(stderr, "HX711 read timeout\n");
        return -1;
    }

    gpioWrite(clock_pin, 0);
    gpioDelay(1);
    data = gpioRead(data_pin);
    gpioWrite(clock_pin, 1);
    gpioDelay(1);

    return data;
}

static double read_hx711_weight(int data_pin, int clock_pin) {
    int32_t raw = (read_hx711(data_pin, clock_pin) << 8) | read_hx711(data_pin, clock_pin);
    return (double)raw / 100.0;
}

static void log_data(double weight, double scale, double offset) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Weight: %.2f kg, Scale: %.4f, Offset: %.4f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            weight, scale, offset);
    fclose(fp);
}

static void calibrate_hx711(int data_pin, int clock_pin, int num_samples) {
    double sum = 0.0;
    int valid = 0;

    printf("Calibrating HX711 (keep zero load)...\n");
    for (int i = 0; i < num_samples; i++) {
        int raw = read_hx711(data_pin, clock_pin);
        if (raw == 0) {
            sum += raw;
            valid++;
        }
        gpioDelay(10000);
    }

    if (valid == 0) {
        fprintf(stderr, "Calibration failed: no valid readings\n");
        return;
    }

    scale_factor = sum / valid;
    offset = 0.0;
    printf("Calibration complete. Scale: %.4f, Offset: %.4f\n", scale_factor, offset);
}

static void load_calibration(double *scale, double *offset) {
    FILE *fp = fopen(CALIBRATION_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Calibration file not found. Using defaults.\n");
        *scale = DEFAULT_SCALE_FACTOR;
        *offset = DEFAULT_OFFSET;
        return;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        if (line[0] == '#' || line[0] == '\n' || line[0] == '\0') continue;
        char *eq = strchr(line, '=');
        if (!eq) continue;
        *eq = '\0';
        char *key = line;
        char *val = eq + 1;
        while (*key == ' ' || *key == '\t') key++;
        while (*val == ' ' || *val == '\t') val++;
        if (strcmp(key, "scale_factor") == 0) {
            *scale = atof(val);
        } else if (strcmp(key, "offset") == 0) {
            *offset = atof(val);
        }
    }

    fclose(fp);
}

static void save_calibration(double scale, double offset) {
    FILE *fp = fopen(CALIBRATION_FILE, "w");
    if (!fp) {
        fprintf(stderr, "Error opening calibration file for writing: %s\n", strerror(errno));
        return;
    }
    fprintf(fp, "scale_factor=%.4f\noffset=%.4f\n", scale, offset);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);
    gpioWrite(SOLENOID_PIN, 0);

    load_calibration(&scale_factor, &offset);

    calibrate_hx711(HX711_DATA_PIN, HX711_CLOCK_PIN, CALIBRATION_SAMPLES);

    printf("Starting weight monitoring. Press Ctrl+C to exit.\n");

    while (running) {
        double weight = read_hx711_weight(HX711_DATA_PIN, HX711_CLOCK_PIN);
        log_data(weight, scale_factor, offset);

        if (weight > 10.0) {
            printf("Weight %.2f kg exceeds threshold. Engaging solenoid.\n", weight);
            gpioWrite(SOLENOID_PIN, 1);
        } else {
            gpioWrite(SOLENOID_PIN, 0);
        }

        save_calibration(scale_factor, offset);
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    gpioWrite(SOLENOID_PIN, 0);
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return 0;
}

