#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <pigpio.h>

#define RAIN_SENSOR_PIN 4
#define MOTOR_IN1_PIN 17
#define MOTOR_IN2_PIN 18
#define MOTOR_PWM_PIN 27
#define PWM_FREQUENCY 1000
#define PWM_DUTY_CYCLE 150
#define DEBOUNCE_READINGS 5
#define DEBOUNCE_DELAY_US 50000
#define CHECK_INTERVAL_SEC 60
#define POST_CHECK_DELAY_SEC 60

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_event(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);
    fprintf(log_file, "[%s] %s\n", buf, message);
    fflush(log_file);
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    if (gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT) != 0) {
        syslog(LOG_ERR, "Failed to set rain sensor pin mode");
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_PWM_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set motor pin modes");
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(MOTOR_IN1_PIN, 0) != 0 ||
        gpioWrite(MOTOR_IN2_PIN, 0) != 0) {
        syslog(LOG_ERR, "Failed to initialise motor pins to LOW");
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMfrequency(MOTOR_PWM_PIN, PWM_FREQUENCY) < 0) {
        syslog(LOG_ERR, "Failed to set PWM frequency");
        gpioTerminate();
        return -1;
    }

    if (gpioPWM(MOTOR_PWM_PIN, 0) != 0) {
        syslog(LOG_ERR, "Failed to initialise PWM to 0");
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int read_rain_sensor(void) {
    int sum = 0;
    for (int i = 0; i < DEBOUNCE_READINGS; i++) {
        int reading = gpioRead(RAIN_SENSOR_PIN);
        if (reading < 0) {
            syslog(LOG_ERR, "Failed to read rain sensor (gpioRead returned %d)", reading);
            return -1;
        }
        sum += reading;
        if (i < DEBOUNCE_READINGS - 1) gpioDelay(DEBOUNCE_DELAY_US);
    }
    return (sum < (DEBOUNCE_READINGS / 2)) ? 1 : 0;
}

static int control_motor(int direction, int duration_sec) {
    if (direction != 0 && direction != 1) {
        syslog(LOG_ERR, "Invalid motor direction: %d", direction);
        return -1;
    }

    if (gpioWrite(MOTOR_IN1_PIN, direction) != 0 ||
        gpioWrite(MOTOR_IN2_PIN, !direction) != 0) {
        syslog(LOG_ERR, "Failed to set motor direction pins");
        return -1;
    }

    if (gpioPWM(MOTOR_PWM_PIN, PWM_DUTY_CYCLE) != 0) {
        syslog(LOG_ERR, "Failed to set PWM duty cycle");
        return -1;
    }

    for (int elapsed = 0; elapsed < duration_sec && program_running; elapsed++) {
        gpioDelay(1000000);
    }

    if (gpioPWM(MOTOR_PWM_PIN, 0) != 0) {
        syslog(LOG_ERR, "Failed to stop PWM");
        return -1;
    }

    if (gpioWrite(MOTOR_IN1_PIN, 0) != 0 ||
        gpioWrite(MOTOR_IN2_PIN, 0) != 0) {
        syslog(LOG_ERR, "Failed to reset motor direction pins");
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (log_file) {
        log_event("Program terminated");
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(MOTOR_IN1_PIN, 0);
    gpioWrite(MOTOR_IN2_PIN, 0);
    gpioPWM(MOTOR_PWM_PIN, 0);
    gpioTerminate();
    closelog();
}

int main(void) {
    openlog("window_control", LOG_PID | LOG_CONS, LOG_USER);

    log_file = fopen("/var/log/window_control.log", "a");
    if (!log_file) {
        syslog(LOG_ERR, "Failed to open log file");
        closelog();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to set signal handlers");
        fclose(log_file);
        closelog();
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting");
        fclose(log_file);
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Window control program started");

    while (program_running) {
        int rain = read_rain_sensor();
        if (rain < 0) {
            log_event("Error reading rain sensor");
        } else if (rain) {
            log_event("Rain detected");
            if (control_motor(1, 5) != 0) {
                log_event("Error controlling motor");
            } else {
                log_event("Motor stopped after 5 seconds");
            }
        }
        sleep(CHECK_INTERVAL_SEC);
        if (!program_running) break;
        sleep(POST_CHECK_DELAY_SEC);
    }

    cleanup();
    return EXIT_SUCCESS;
}

