#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define HX711_DT 23
#define HX711_SCK 24
#define SOLENOID_PIN 17
#define WEIGHT_THRESHOLD 100.0
#define LOCK_DURATION 5
#define SAMPLE_INTERVAL 1.0
#define HX711_TIMEOUT_US 1000000
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "[%s] %s\n", ts, message);
    fflush(log_file);
}

static int read_hx711(int32_t *out) {
    int32_t data = 0;
    int timeout = 0;

    while (gpioRead(HX711_DT) == 1) {
        gpioDelay(100);
        timeout++;
        if (timeout >= HX711_TIMEOUT_US) {
            log_event("Error: HX711 data line stuck high (timeout)");
            return -1;
        }
    }

    for (int i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK, 1);
        gpioDelay(1);
        data <<= 1;
        if (gpioRead(HX711_DT)) {
            data |= 1;
        }
        gpioWrite(HX711_SCK, 0);
        gpioDelay(1);
    }

    gpioWrite(HX711_SCK, 1);
    gpioDelay(1);
    gpioWrite(HX711_SCK, 0);
    gpioDelay(1);

    if (data & 0x800000) {
        data |= ~0xFFFFFF;
    }

    *out = data;
    return 0;
}

static double convert_to_weight(int32_t raw) {
    return (double)raw / 100.0;
}

static void activate_lock(int duration) {
    if (gpioWrite(SOLENOID_PIN, 1) < 0) {
        log_event("Error: Failed to activate solenoid");
        return;
    }
    log_event("Solenoid activated");
    gpioDelay(duration * 1000000);
    if (gpioWrite(SOLENOID_PIN, 0) < 0) {
        log_event("Error: Failed to deactivate solenoid");
    } else {
        log_event("Solenoid deactivated");
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set solenoid pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(SOLENOID_PIN, 0);

    if (gpioSetMode(HX711_DT, PI_INPUT) < 0 || gpioSetMode(HX711_SCK, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set HX711 pin modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("stock_events.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_event("Program started");

    while (running) {
        int32_t raw;
        int retries = 0;
        int success = 0;

        while (retries < MAX_RETRIES && !success) {
            if (read_hx711(&raw) == 0) {
                success = 1;
            } else {
                retries++;
                if (retries < MAX_RETRIES) {
                    gpioDelay(100000);
                }
            }
        }

        if (!success) {
            log_event("Error: HX711 read failed after retries");
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        double weight = convert_to_weight(raw);
        char log_msg[128];
        snprintf(log_msg, sizeof(log_msg), "Weight: %.2f g", weight);
        log_event(log_msg);

        if (weight < WEIGHT_THRESHOLD) {
            log_event("Weight below threshold, activating lock");
            activate_lock(LOCK_DURATION);
        }

        sleep(SAMPLE_INTERVAL);
    }

    log_event("Program exiting");
    gpioWrite(SOLENOID_PIN, 0);
    fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

