#define SOLENOID_PIN 27
#define CALIBRATION_FILE "calibration.txt"
#define SECURITY_LOG_FILE "security.log"
#define WEIGHT_THRESHOLD 5.0
#define SOLENOID_HOLD_TIME 5
#define HX711_TIMEOUT_US 100000
#define CLOCK_HIGH_DELAY_US 1
#define CLOCK_LOW_DELAY_US 1

static volatile sig_atomic_t running = 1;
static double calibration_factor = 1.0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_hx711_raw(int data_pin, int clock_pin) {
    int data = 0;
    int timeout = 0;

    gpioSetMode(data_pin, PI_INPUT);
    gpioSetMode(clock_pin, PI_OUTPUT);
    gpioWrite(clock_pin, 0);

    while (gpioRead(data_pin) == 0) {
        gpioDelay(1);
        timeout++;
        if (timeout > HX711_TIMEOUT_US) {
            fprintf(stderr, "HX711 timeout: data line stuck low\n");
            return -1;
        }
    }

    for (int i = 0; i < 24; i++) {
        gpioWrite(clock_pin, 1);
        gpioDelay(CLOCK_HIGH_DELAY_US);
        data <<= 1;
        if (gpioRead(data_pin)) {
            data |= 1;
        }
        gpioWrite(clock_pin, 0);
        gpioDelay(CLOCK_LOW_DELAY_US);
    }

    gpioWrite(clock_pin, 1);
    gpioDelay(CLOCK_HIGH_DELAY_US);
    gpioWrite(clock_pin, 0);
    gpioDelay(CLOCK_LOW_DELAY_US);

    if (data & 0x800000) {
        data |= ~0xFFFFFF;
    }

    return data;
}

static double calculate_weight(int raw_value, double factor) {
    return (double)raw_value * factor;
}

static int save_calibration_factor(double factor) {
    FILE *fp = fopen(CALIBRATION_FILE, "w");
    if (!fp) {
        fprintf(stderr, "Error opening calibration file: %s\n", strerror(errno));
        return -1;
    }
    fprintf(fp, "%.6f\n", factor);
    fclose(fp);
    return 0;
}

static int open_security_log(double weight) {
    FILE *fp = fopen(SECURITY_LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening security log: %s\n", strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s, %.4f kg\n", timestamp, weight);
    fclose(fp);
    return 0;
}

static void activate_solenoid(int pin, int duration) {
    gpioWrite(pin, 1);
    gpioDelay(duration * 1000000);
    gpioWrite(pin, 0);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    printf("Enter known weight in grams: ");
    if (scanf("%lf", &calibration_factor) != 1) {
        fprintf(stderr, "Invalid input. Using default calibration factor.\n");
        calibration_factor = 1.0;
    }

    printf("Place the known weight on the load cell and press Enter...");
    getchar();

    int raw_value = read_hx711_raw(HX711_DATA_PIN, HX711_CLOCK_PIN);
    if (raw_value == -1) {
        fprintf(stderr, "Failed to read initial HX711 value.\n");
        gpioTerminate();
        return 1;
    }

    double weight = calculate_weight(raw_value, calibration_factor);
    printf("Weight: %.4f kg\n", weight);

    while (running) {
        int raw = read_hx711_raw(HX711_DATA_PIN, HX711_CLOCK_PIN);
        if (raw == -1) {
            fprintf(stderr, "HX711 read error, retrying...\n");
            gpioDelay(100000);
            continue;
        }

        weight = calculate_weight(raw, calibration_factor);
        printf("Weight: %.4f kg\n", weight);

        if (weight > WEIGHT_THRESHOLD) {
            printf("Threshold exceeded! Activating solenoid.\n");
            save_calibration_factor(calibration_factor);
            open_security_log(weight);

            activate_solenoid(SOLENOID_PIN, SOLENOID_HOLD_TIME);

            printf("Solenoid deactivated.\n");
        }

        gpioDelay(100000);
    }

    gpioWrite(SOLENOID_PIN, 0);
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

