#include <errno.h>
#include <pigpio.h>

#define SENSOR_PIN 16
#define RELAY_PIN  20
#define LOG_FILE   "relay_events.log"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(int relay_state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        fclose(fp);
        return;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        fclose(fp);
        return;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return;
    }

    if (fprintf(fp, "%s - Relay: %s\n", timestamp,
                relay_state ? "ON" : "OFF") < 0) {
        fprintf(stderr, "Error writing to log file: %s\n",
                strerror(errno));
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n",
                strerror(errno));
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set sensor pin %d as input\n",
                SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set relay pin %d as output\n",
                RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialise relay pin %d to LOW\n",
                RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int relay_state = 0;
    int last_sensor = 1;  /* active-low: 1 = no obstacle */

    while (running) {
        int sensor_value = gpioRead(SENSOR_PIN);
        if (sensor_value < 0) {
            fprintf(stderr, "Error reading sensor pin %d: %s\n",
                    SENSOR_PIN, strerror(errno));
            gpioDelay(100000);
            continue;
        }

        /* Active-low sensor: 0 => obstacle detected */
        int obstacle = (sensor_value == 0);

        /* Toggle relay on state change */
        relay_state = !relay_state;
        if (gpioWrite(RELAY_PIN, relay_state) != 0) {
            fprintf(stderr, "Error writing relay pin %d: %s\n",
                    RELAY_PIN, strerror(errno));
            gpioDelay(100000);
            continue;
        }

        log_event(relay_state);

        last_sensor = sensor_value;
        gpioDelay(100000);  /* 100 ms */
    }

    /* Clean shutdown */
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

