#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PIR_PIN 17
#define BUZZER_PIN 18
#define BUZZER_DURATION_US 2000000  /* 2 seconds in microseconds */
#define POLL_INTERVAL_US 100000      /* 100 ms in microseconds */

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_motion(void) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[20];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return -1;
    }

    if (fprintf(log_file, "%s Motion detected\n", timestamp) < 0) {
        fprintf(stderr, "Error: failed to write to log file\n");
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Warning: fflush failed on log file\n");
    }

    return 0;
}

static int activate_buzzer(void) {
    if (gpioWrite(BUZZER_PIN, 1) != 0) {
        fprintf(stderr, "Error: failed to set buzzer HIGH\n");
        return -1;
    }

    usleep(BUZZER_DURATION_US);

    if (gpioWrite(BUZZER_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to set buzzer LOW\n");
        return -1;
    }

    return 0;
}

static int setup_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(PIR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set PIR pin %d as input\n", PIR_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set buzzer pin %d as output\n", BUZZER_PIN);
        gpioTerminate();
        return -1;
    }

    /* Ensure buzzer is off at startup */
    if (gpioWrite(BUZZER_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise buzzer pin %d LOW\n", BUZZER_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    /* Ensure buzzer is off before releasing resources */
    if (gpioWrite(BUZZER_PIN, 0) != 0) {
        fprintf(stderr, "Warning: failed to turn off buzzer during cleanup\n");
    }

    if (log_file != NULL) {
        if (fclose(log_file) != 0) {
            fprintf(stderr, "Warning: fclose failed on log file\n");
        }
        log_file = NULL;
    }

    gpioTerminate();
}

int main(void) {
    struct sigaction sa;

    /* Install signal handlers for graceful shutdown */
    memset(&sa, 0, sizeof(sa));
