#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME   "gpiochip0"
#define GPIO_LINE_OFFSET 18
#define CONFIG_FILE      "watering.conf"
#define MIN_DURATION_SEC 1
#define MAX_DURATION_SEC 3600
#define DEFAULT_DURATION_SEC 60

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int read_config(const char *filename, int *duration_sec)
{
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Error opening config file '%s': %s\n",
                filename, strerror(errno));
        return -1;
    }

    char line[256];
    if (!fgets(line, sizeof(line), fp)) {
        fprintf(stderr, "Error reading config file '%s': %s\n",
                filename, strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);

    /* Strip trailing newline */
    line[strcspn(line, "\r\n")] = '\0';

    if (strncmp(line, "duration=", 8) != 0) {
        fprintf(stderr, "Error: config file does not contain 'duration=' line\n");
        return -1;
    }

    char *endptr;
    long val = strtol(line + 8, &endptr, 10);
    if (endptr == line + 8 || *endptr != '\0' || val <= 0 || val > MAX_DURATION_SEC) {
        fprintf(stderr, "Error: invalid duration '%s' (must be %d-%d)\n",
                line + 8, MIN_DURATION_SEC, MAX_DURATION_SEC);
        return -1;
    }

    *duration_sec = (int)val;
    return 0;
}

static int set_valve(struct gpiod_line *line, int on)
{
    int ret = gpiod_line_set_value(line, on ? 1 : 0);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO value: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void sleep_interruptible(int seconds)
{
    struct timespec req = {
        .tv_sec  = seconds,
        .tv_nsec = 0
    };
    struct timespec rem;
    while (nanosleep(&req, &rem) == -1 && errno == EINTR) {
        if (!g_running)
            return;
        req = rem;
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int duration_sec = DEFAULT_DURATION_SEC;

    if (read_config(CONFIG_FILE, &duration_sec) != 0) {
        return EXIT_FAILURE;
    }

    /* Open GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n",
                GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request line as output, default value LOW (valve off) */
    if (gpiod_line_request_output(line, "watering-system", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Warning: failed to install SIGINT handler: %s\n",
                strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Warning: failed to install SIGTERM handler: %s\n",
                strerror(errno));
    }

    printf("Watering system started. Duration: %d seconds\n", duration_sec);
    printf("Valve on GPIO%d will be activated.\n", GPIO_LINE_OFFSET);
    printf("Press Ctrl+C to exit early.\n");

    /* Activate valve */
    if (set_valve(line, 1) != 0) {
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Valve activated. Watering for %d seconds...\n", duration_sec);

    /* Interruptible wait */
    sleep_interruptible(duration_sec);

    /* Deactivate valve */
    if (set_valve(line, 0) != 0) {
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Valve deactivated. Watering complete.\n");

    /* Clean up: ensure valve is off */
    gpiod_line_set_value(line, 0);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("Watering system stopped.\n");
    return EXIT_SUCCESS;
}

