#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

/* Sensor GPIO pins (BCM numbering) */
#define SENSOR_LEFT_PIN 4
#define SENSOR_MIDDLE_PIN 17
#define SENSOR_RIGHT_PIN 27

/* Motor PWM GPIO pins (BCM numbering) */
#define MOTOR_LEFT_PIN 22
#define MOTOR_RIGHT_PIN 23
#define MOTOR_FORWARD_PIN 24
#define MOTOR_BACKWARD_PIN 25

/* PWM frequency (Hz) */
#define PWM_FREQUENCY 1000

/* PWM range (0-255) */
#define PWM_RANGE 255

/* Base speed (0-255) */
#define BASE_SPEED 150

/* Log file name */
#define LOG_FILE "trace_log.txt"

/* Global variables */
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

/* Function prototypes */
static int initialize_gpio(void);
static int read_sensor(int gpio_pin);
static int set_motor_speed(int gpio_pin, int speed);
static void log_data(int left_sensor_value, int middle_sensor_value, int right_sensor_value, int left_motor_speed, int right_motor_speed);
static void signal_handler(int signal);
static void cleanup(void);

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

/* Initializes the pigpio library and configures GPIO pins */
static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return -1;
    }

    /* Set sensor pins as inputs */
    if (gpioSetMode(SENSOR_LEFT_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_LEFT_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(SENSOR_MIDDLE_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_MIDDLE_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(SENSOR_RIGHT_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_RIGHT_PIN);
        gpioTerminate();
        return -1;
    }

    /* Set motor PWM pins as outputs */
    if (gpioSetMode(MOTOR_LEFT_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", MOTOR_LEFT_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(MOTOR_RIGHT_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", MOTOR_RIGHT_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(MOTOR_FORWARD_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", MOTOR_FORWARD_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(MOTOR_BACKWARD_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", MOTOR_BACKWARD_PIN);
        gpioTerminate();
        return -1;
    }

    /* Set PWM frequency and range for motor pins */
    if (gpioSetPWMfrequency(MOTOR_LEFT_PIN, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", MOTOR_LEFT_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMfrequency(MOTOR_RIGHT_PIN, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", MOTOR_RIGHT_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMrange(MOTOR_LEFT_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range for GPIO %d\n", MOTOR_LEFT_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMrange(MOTOR_RIGHT_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range for GPIO %d\n", MOTOR_RIGHT_PIN);
        gpioTerminate();
        return -1;
    }

    /* Set initial motor speeds to 0 */
    if (gpioPWM(MOTOR_LEFT_PIN, 0) != 0) {
        fprintf(stderr, "Failed to set PWM for GPIO %d\n", MOTOR_LEFT_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioPWM(MOTOR_RIGHT_PIN, 0) != 0) {
        fprintf(stderr, "Failed to set PWM for GPIO %d\n", MOTOR_RIGHT_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

/* Reads the digital value from a GPIO pin */
static int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Failed to read GPIO %d: %s\n", gpio_pin, strerror(errno));
        return -1;
    }
    return value;
}

/* Sets the motor speed on a GPIO pin */
static int set_motor_speed(int gpio_pin, int speed) {
    if (speed < 0) speed = 0;
    if (speed > PWM_RANGE) speed = PWM_RANGE;

    if (gpioPWM(gpio_pin, speed) != 0) {
        fprintf(stderr, "Failed to set PWM for GPIO %d: %s\n", gpio_pin, strerror(errno));
        return -1;
    }
    return 0;
}

/* Logs the sensor data and motor speeds to a file */
static void log_data(int left_sensor_value, int middle_sensor_value, int right_sensor_value, int left_motor_speed, int right_motor_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Failed to get local time\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Left: %d, Middle: %d, Right: %d, Left Motor: %d, Right Motor: %d\n",
            timestamp, left_sensor_value, middle_sensor_value, right_sensor_value, left_motor_speed, right_motor_speed);
    fflush(log_file);
}

/* Cleans up resources before exiting */
static void cleanup(void) {
    /* Stop both motors */
    gpioPWM(MOTOR_LEFT_PIN, 0);
    gpioPWM(MOTOR_RIGHT_PIN, 0);

    /* Close the log file */
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    /* Terminate the pigpio library */
    gpioTerminate();
}

int main(void) {
    /* Install signal handler for Ctrl+C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install signal handler: %s\n", strerror(errno));
        return 1;
    }

    /* Initialize GPIO */
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    /* Open the log file */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    printf("Line following robot started. Press Ctrl+C to exit.\n");

    /* Main control loop */
    while (program_running) {
        int left_sensor_value = read_sensor(SENSOR_LEFT_PIN);
        int middle_sensor_value = read_sensor(SENSOR_MIDDLE_PIN);
        int right_sensor_value = read_sensor(SENSOR_RIGHT_PIN);

        if (left_sensor_value < 0 || middle_sensor_value < 0 || right_sensor_value < 0) {
            fprintf(stderr, "Error reading sensor values. Stopping motors and exiting.\n");
            break;
        }

        /* Control logic based on sensor values */
        int left_motor_speed = BASE_SPEED;
        int right_motor_speed = BASE_SPEED;

        if (middle_sensor_value == 0) {
            /* Drive straight */
            left_motor_speed = BASE_SPEED;
            right_motor_speed = BASE_SPEED;
        } else if (left_sensor_value == 0) {
            /* Turn right: slow down left motor */
            left_motor_speed = BASE_SPEED / 2;
            right_motor_speed = BASE_SPEED;
        } else if (right_sensor_value == 0) {
            /* Turn left: slow down right motor */
            left_motor_speed = BASE_SPEED;
            right_motor_speed = BASE_SPEED / 2;
        } else {
            /* No sensor activated: stop both motors */
            left_motor_speed = 0;
            right_motor_speed = 0;
        }

        /* Set motor speeds */
        if (set_motor_speed(MOTOR_LEFT_PIN, left_motor_speed) != 0) {
            fprintf(stderr, "Failed to set left motor speed\n");
            break;
        }
        if (set_motor_speed(MOTOR_RIGHT_PIN, right_motor_speed) != 0) {
            fprintf(stderr, "Failed to set right motor speed\n");
            break;
        }

        /* Log the data */
        log_data(left_sensor_value, middle_sensor_value, right_sensor_value, left_motor_speed, right_motor_speed);

        /* Delay for 10 milliseconds */
        gpioDelay(10000);
    }

    /* Cleanup */
    cleanup();

    printf("Program terminated.\n");
    return 0;
}

