#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS        "/dev/i2c-1"
#define BH1750_ADDR     0x38
#define RELAY_GPIO      23
#define LUX_THRESHOLD   150
#define MEASUREMENT_MS  180
#define LOG_FILE        "grow_log.txt"
#define POLL_DELAY_US   100000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void log_event(const char *msg) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm;
    localtime_r(&ts.tv_sec, &tm);
    char tbuf[32];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s.%03ld: %s\n", tbuf, ts.tv_nsec / 1000000, msg);
    fclose(fp);
}

static int init_i2c(void) {
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open i2c");
        return -1;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return -1;
    }
    return 0;
}

static int read_bh1750(uint16_t *lux_out) {
    uint8_t cmd = 0x10;
    if (write(g_i2c_fd, &cmd, 1) != 1) {
        return -1;
    }
    usleep(MEASUREMENT_MS * 1000);
    uint8_t buf[2];
    if (read(g_i2c_fd, buf, 2) != 2) {
        return -1;
    }
    *lux_out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static void control_relay(int on) {
    gpioWrite(RELAY_GPIO, on ? 1 : 0);
}

static void cleanup(void) {
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }

    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    control_relay(0);

    if (init_i2c() < 0) {
        gpioTerminate();
        return 1;
    }

    int relay_state = 0;
    while (g_running) {
        uint16_t lux = 0;
        if (read_bh1750(&lux) < 0) {
            log_event("I2C read error");
        } else {
            char msg[64];
            snprintf(msg, sizeof(msg), "Lux: %u", lux);
            log_event(msg);
            if (lux < LUX_THRESHOLD && relay_state == 0) {
                control_relay(1);
                relay_state = 1;
                log_event("Relay ON");
            } else if (lux >= LUX_THRESHOLD && relay_state == 1) {
                control_relay(0);
                relay_state = 0;
                log_event("Relay OFF");
            }
        }
        usleep(POLL_DELAY_US);
    }

    cleanup();
    return 0;
}

