#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SERVO_PIN 18
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22
#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500
#define SERVO_PULSE_WIDTH_LOCK 1000
#define SERVO_PULSE_WIDTH_UNLOCK 2000
#define DEBOUNCE_DELAY_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int safe_set_servo(int pin, int pulse_width) {
    if (pulse_width < SERVO_MIN_PULSE_WIDTH || pulse_width > SERVO_MAX_PULSE_WIDTH) {
        fprintf(stderr, "Error: pulse width %d out of range [%d, %d]\n",
                pulse_width, SERVO_MIN_PULSE_WIDTH, SERVO_MAX_PULSE_WIDTH);
        return -1;
    }
    if (gpioServo(pin, pulse_width) < 0) {
        fprintf(stderr, "Error: gpioServo failed for pin %d\n", pin);
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set SERVO_PIN %d as output\n", SERVO_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set LOCK_BUTTON_PIN %d as input\n", LOCK_BUTTON_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set UNLOCK_BUTTON_PIN %d as input\n", UNLOCK_BUTTON_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on LOCK_BUTTON_PIN\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on UNLOCK_BUTTON_PIN\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Door lock control started. Press Ctrl+C to exit.\n");

    while (running) {
        int lock_pressed = (gpioRead(LOCK_BUTTON_PIN) == 0);
        int unlock_pressed = (gpioRead(UNLOCK_BUTTON_PIN) == 0);

        if (lock_pressed) {
            if (safe_set_servo(SERVO_PIN, SERVO_PULSE_WIDTH_LOCK) == 0) {
                printf("Lock engaged (pulse width %d us)\n", SERVO_PULSE_WIDTH_LOCK);
            }
        } else {
            if (safe_set_servo(SERVO_PIN, 0) == 0) {
                printf("Lock disengaged\n");
            }
        }

        if (unlock_pressed) {
            if (safe_set_servo(SERVO_PIN, SERVO_PULSE_WIDTH_UNLOCK) == 0) {
                printf("Unlock engaged (pulse width %d us)\n", SERVO_PULSE_WIDTH_UNLOCK);
            }
        } else {
            if (safe_set_servo(SERVO_PIN, 0) == 0) {
                printf("Unlock disengaged\n");
            }
        }

        usleep(DEBOUNCE_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

