#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <time.h>
#include <sys/time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <zmq.h>

#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 27
#define ZMQ_PORT 5555
#define ZMQ_ADDRESS "tcp://localhost"
#define SOUND_ALERTS_TOPIC "SOUND_ALERTS"
#define POLL_INTERVAL_US 10000
#define ALARM_DURATION_US 1000000

static volatile sig_atomic_t running = 1;
static int sound_sensor_mode = 0;
static int alarm_node_mode = 0;
static int zmq_socket = -1;
static int zmq_context = -1;
static int gpio_chip = -1;
static int sound_line = -1;
static int led_line = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    gpio_chip = gpioInitialise();
    if (gpio_chip < 0) {
        fprintf(stderr, "Error: gpioInitialise failed (%d): %s\n", gpio_chip, strerror(errno));
        return -1;
    }

    sound_line = gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT);
    if (sound_line < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for sound sensor pin %d: %s\n", SOUND_SENSOR_PIN, strerror(errno));
        return -1;
    }

    led_line = gpioSetMode(ALARM_LED_PIN, PI_OUTPUT);
    if (led_line < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for alarm LED pin %d: %s\n", ALARM_LED_PIN, strerror(errno));
        return -1;
    }

    if (gpioWrite(led_line, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite failed for alarm LED pin %d: %s\n", ALARM_LED_PIN, strerror(errno));
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void) {
    if (led_line >= 0) {
        gpioWrite(led_line, 0);
        gpioSetMode(led_line, PI_INPUT);
    }
    if (sound_line >= 0) {
        gpioSetMode(sound_line, PI_INPUT);
    }
    if (gpio_chip >= 0) {
        gpioTerminate();
    }
}

static int init_zmq(void) {
    zmq_socket = zmq_socket(zmq_context, ZMQ_REP);
    if (zmq_socket < 0) {
        fprintf(stderr, "Error: zmq_socket failed: %s\n", strerror(errno));
        return -1;
    }

    int rc = zmq_bind(zmq_socket, ZMQ_ADDRESS);
    if (rc < 0) {
        fprintf(stderr, "Error: zmq_bind failed: %s\n", strerror(errno));
        zmq_close(zmq_socket);
        zmq_socket = -1;
        return -1;
    }

    return 0;
}

static void cleanup_zmq(void) {
    if (zmq_socket >= 0) {
        zmq_close(zmq_socket);
        zmq_socket = -1;
    }
    if (zmq_context >= 0) {
        zmq_close(zmq_context);
        zmq_context = -1;
    }
}

static int init(void) {
    if (init_gpio() < 0) {
        return -1;
    }

    if (init_zmq() < 0) {
        cleanup_gpio();
        return -1;
    }

    return 0;
}

static void publish_alert(void) {
    char buffer[64];
    struct timeval tv;
    gettimeofday(&tv, NULL);
    snprintf(buffer, sizeof(buffer), "%ld.%06ld", (long)tv.tv_sec, (long)tv.tv_usec);

    if (zmq_socket < 0) {
        fprintf(stderr, "Error: ZMQ socket not initialized\n");
        return;
    }

    if (zmq_send(zmq_socket, buffer, strlen(buffer), 0) < 0) {
        fprintf(stderr, "Error: zmq_send failed: %s\n", strerror(errno));
        return;
    }
}

static void alarm_node(void) {
    while (running) {
        zmq_msg_t msg;
        zmq_msg_init(&msg);
        int rc = zmq_recv(zmq_socket, &msg, 0, 0);
        if (rc < 0) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "Error: zmq_recv failed: %s\n", strerror(errno));
            break;
        }
        if (rc == 0) {
            continue;
        }

        char *buf = zmq_msg_data(&msg);
        if (buf) {
            printf("Received alert: %s\n", buf);
            if (gpioWrite(led_line, 1) < 0) {
                fprintf(stderr, "Error: gpioWrite failed for alarm LED pin %d: %s\n", ALARM_LED_PIN, strerror(errno));
            }
            gpioDelay(ALARM_DURATION_US);
            if (gpioWrite(led_line, 0) < 0) {
                fprintf(stderr, "Error: gpioWrite failed for alarm LED pin %d: %s\n", ALARM_LED_PIN, strerror(errno));
            }
        }
    }
}

static void sound_sensor(void) {
    while (running) {
        int val = gpioRead(SOUND_SENSOR_PIN);
        if (val < 0) {
            fprintf(stderr, "Error: gpioRead failed for sound sensor pin %d: %s\n", SOUND_SENSOR_PIN, strerror(errno));
            continue;
        }

        if (val == 0) {
            publish_alert();
        }

        gpioDelay(POLL_INTERVAL_US);
    }
}

int main(int argc, char *argv[]) {
    if (argc > 1) {
        if (strcmp(argv[1], "sound_sensor") == 0) {
            sound_sensor_mode = 1;
        } else if (strcmp(argv[1], "alarm_node") == 0) {
            alarm_node_mode = 1;
        } else {
            fprintf(stderr, "Usage: %s [sound_sensor | alarm_node]\n", argv[0]);
            return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (init() < 0) {
        fprintf(stderr, "Error: Initialization failed\n");
        return EXIT_FAILURE;
    }

    if (sound_sensor_mode) {
        printf("Sound sensor mode started. Polling GPIO%d every %d us...\n", SOUND_SENSOR_PIN, POLL_INTERVAL_US);
        sound_sensor();
    } else if (alarm_node_mode) {
        printf("Alarm node mode started. Listening on tcp://%s for topic %s...\n", ZMQ_ADDRESS, SOUND_ALERTS_TOPIC);
        alarm_node();
    } else {
        printf("Invalid mode. Exiting.\n");
        cleanup_gpio();
        cleanup_zmq();
        return EXIT_FAILURE;
    }

    printf("Shutting down...\n");
    cleanup_gpio();
    cleanup_zmq();
    return EXIT_SUCCESS;
}

