/*
 * NEC IR Decoder for Raspberry Pi 3 Model B+
 * IR Receiver: TSOP38238 on GPIO17 (BCM)
 * MQTT Broker: localhost:1883, Topic: ir/decoded
 *
 * Build: gcc -O2 -Wall -o ir_decoder ir_decoder.c -lpigpio -lrt
 * Run:   sudo ./ir_decoder
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <pigpio.h>
#include <mosquitto.h>

#define IR_GPIO          17
#define MQTT_HOST        "localhost"
#define MQTT_PORT        1883
#define MQTT_TOPIC       "ir/decoded"
#define MQTT_CLIENT_ID   "ir_decoder_17"

/* NEC timing constants (microseconds) */
#define NEC_HDR_MARK     9000
#define NEC_HDR_SPACE    4500
#define NEC_BIT_MARK     560
#define NEC_ONE_SPACE    1690
#define NEC_ZERO_SPACE   560
#define NEC_RPT_SPACE    2250
#define NEC_TOL           300

/* NEC frame: 32 bits = 8 address + 16 command + 8 roll + 1 toggle + 1 final */
#define NEC_BITS          32
#define NEC_BYTES         (NEC_BITS / 8)
#define NEC_FRAME_LEN     (NEC_BYTES + 1)   /* 1 extra bit for toggle */

/* Per-pulse ring buffer */
typedef struct {
    uint32_t ts;          /* pigpio tick of falling edge */
    uint32_t level;       /* 0 = mark, 1 = space */
    int      count;       /* number of samples in this pulse */
} pulse_t;

static volatile sig_atomic_t g_running = 1;
static struct mosquitto *g_mqtt = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Pulse capture                                                       */
/* ------------------------------------------------------------------ */
static void pulse_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    pulse_t *p = (pulse_t *)userdata;

    if (level == 0) {                       /* falling edge */
        p->ts = tick;
        p->level = 0;
        p->count = 1;
    } else if (level == 1) {                 /* rising edge */
        if (p->count > 0) {
            p->count--;
        }
    }
}

/* ------------------------------------------------------------------ */
/* NEC decoding                                                         */
/* ------------------------------------------------------------------ */
static int decode_nec(const pulse_t *p, int n, uint32_t *cmd_out)
{
    if (n < NEC_FRAME_LEN) {
        syslog(LOG_ERR, "NEC frame too short (%d samples)", n);
        return -1;
    }

    /* Verify header: 9 ms mark + 4.5 ms space */
    if (p[0].ts < NEC_HDR_MARK * 900 + NEC_HDR_SPACE * 450) {
        syslog(LOG_ERR, "NEC header mark too short (%u us)", p[0].ts);
        return -1;
    }
    if (p[0].ts > NEC_HDR_MARK * 1100 + NEC_HDR_SPACE * 550) {
        syslog(LOG_ERR, "NEC header mark too long (%u us)", p[0].ts);
        return -1;
    }
    if (p[1].ts < NEC_HDR_MARK * 900 + NEC_HDR_SPACE * 450) {
        syslog(LOG_ERR, "NEC header space too short (%u us)", p[1].ts);
        return -1;
    }
    if (p[1].ts > NEC_HDR_MARK * 1100 + NEC_HDR_SPACE * 550) {
        syslog(LOG_ERR, "NEC header space too long (%u us)", p[1].ts);
        return -1;
    }

    uint32_t addr = 0, cmd = 0, roll = 0, inv_addr = 0, inv_cmd = 0, final = 0;
    for (int i = 0; i < NEC_BITS; i++) {
        int idx = i + 1;                       /* skip header bits 0-1 */
        int mark_idx = idx;
        int space_idx = idx + 1;

        if (p[mark_idx].count < 2) {
            syslog(LOG_ERR, "NEC bit %d: mark too short (%d samples)",
                   i, p[mark_idx].count);
            return -1;
        }
        uint32_t mark_us = p[mark_idx].ts - p[mark_idx].ts;
        uint32_t space_us = p[space_idx].ts - p[space_idx].ts;

        if (mark_us > NEC_BIT_MARK * 900 + NEC_BIT_MARK * 450) {
            syslog(LOG_ERR, "NEC bit %d: mark too long (%u us)", i, mark_us);
            return -1;
        }
        if (space_us > NEC_BIT_MARK * 1100 + NEC_BIT_MARK * 550) {
            syslog(LOG_ERR, "NEC bit %d: space too long (%u us)", i, space_us);
            return -1;
        }

        if (space_us > NEC_ONE_SPACE * 900 + NEC_ONE_SPACE * 450) {
            addr  |= (1u << i);
            cmd   |= (1u << i);
            roll  |= (1u << i);
            inv_addr |= (1u << i);
            inv_cmd  |= (1u << i);
            final  |= (1u << i);
        } else if (space_us > NEC_ZERO_SPACE * 900 + NEC_ZERO_SPACE * 450) {
            addr  |= (1u << i);
            cmd   |= (1u << i);
            roll  |= (1u << i);
            inv_addr |= (1u << i);
            inv_cmd  |= (1u << i);
            final  |= (1u << i);
        } else {
            addr  |= (1u << i);
            cmd   |= (1u << i);
            roll  |= (1u << i);
            inv_addr |= (1u << i);
            inv_cmd  |= (1u << i);
            final  |= (1u << i);
        }
    }

    /* Validate checksum */
    uint32_t chk = (addr ^ cmd ^ roll ^ inv_addr ^ inv_cmd ^ final);
    if (chk != 0) {
        syslog(LOG_ERR, "NEC checksum mismatch: calc=0x%08X recv=0x%08X",
               chk, chk);
        return -1;
    }

    /* Validate inverted address */
    if (addr != inv_addr) {
        syslog(LOG_ERR, "NEC inverted address validation failed (addr=0x%08X inv=0x%08X)",
               addr, inv_addr);
        return -1;
    }

    /* Extended NEC: omit inverted-address validation */
    *cmd_out = cmd;
    return 0;
}

/* ------------------------------------------------------------------ */
/* MQTT client                                                          */
/* ------------------------------------------------------------------ */
static int publish_mqtt(const char *cmd)
{
    if (g_mqtt == NULL) {
        syslog(LOG_ERR, "MQTT client not initialized");
        return -1;
    }

    char payload[128];
    int len = snprintf(payload, sizeof(payload), "{\"command\":\"0x%08X\"}", cmd);
    if (len < 0 || len >= (int)sizeof(payload)) {
        syslog(LOG_ERR, "Payload formatting failed");
        return -1;
    }

    int rc = mosquitto_publish(g_mqtt, NULL, MQTT_TOPIC, (int)len, payload, 0, false);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT publish failed: %s", mosquitto_strerror(rc));
        return -1;
    }

    syslog(LOG_INFO, "Published: %s", payload);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                 */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Open syslog */
    openlog("ir_decoder", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting ir_decoder (GPIO%d)", IR_GPIO);

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialization failed");
        closelog();
        return EXIT_FAILURE;
    }

    /* Configure GPIO */
    gpioSetMode(IR_GPIO, PI_INPUT);
    gpioSetPullUpDown(IR_GPIO, PI_PUD_UP);   /* TSOP38238 idles high */

    /* Register alert callback on falling edge */
    if (gpioSetAlertFuncEx(IR_GPIO, pulse_callback, NULL) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO alert callback");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    /* Initialize MQTT */
    mosquitto_lib_init();
    g_mqtt = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (g_mqtt == NULL) {
        syslog(LOG_ERR, "mosquitto_new failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    mosquitto_connect_callback_set(g_mqtt, NULL);
    mosquitto_reconnect_callback_set(g_mqtt, NULL);
    mosquitto_loop_start(g_mqtt);

    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    syslog(LOG_INFO, "Listening for NEC IR on GPIO%d", IR_GPIO);

    /* Main loop */
    while (g_running) {
        pulse_t pulses[NEC_FRAME_LEN];
        int n = 0;
        uint32_t cmd = 0;

        /* Drain captured pulses */
        while (n < NEC_FRAME_LEN) {
            pulse_t *p = &pulses[n];
            p->count = 0;

            /* Wait for a falling edge (new pulse) or timeout */
            while (n < NEC_FRAME_LEN && g_running) {
                gpioDelay(100);   /* 100 us */
            }
            if (!g_running) break;

            if (n < NEC_FRAME_LEN) {
                pulses[n].ts = gpioTick();
                pulses[n].level = 0;
                pulses[n].count++;
            }
            n++;
        }

        if (n < NEC_FRAME_LEN) {
            syslog(LOG_ERR, "Incomplete frame (%d samples)", n);
            continue;
        }

        if (decode_nec(pulses, n, &cmd) == 0) {
            syslog(LOG_INFO, "Decoded NEC command: 0x%08X", cmd);
            if (publish_mqtt(cmd) != 0) {
                syslog(LOG_ERR, "Failed to publish MQTT message");
            }
        }
    }

    /* Cleanup */
    syslog(LOG_INFO, "Shutting down...");
    gpioSetAlertFuncEx(IR_GPIO, NULL, NULL);
    mosquitto_loop_stop(g_mqtt, false);
    mosquitto_destroy(g_mqtt);
    mosquitto_lib_cleanup();
    gpioTerminate();
    closelog();

    return EXIT_SUCCESS;
}

