#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/i2c-dev.h>

#define NUM_SENSORS 4
#define I2C_BUS "/dev/i2c-1"
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5005
#define BH1750_CONV_TIME_MS 180
#define LOOP_DELAY_MS 1000

static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int i2c_open(const char *bus, uint8_t addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int bh1750_read_lux(int fd, float *lux) {
    uint8_t cmd = 0x10; /* Continuous High-Resolution mode */
    ssize_t w = write(fd, &cmd, 1);
    if (w != 1) {
        fprintf(stderr, "Error writing to I2C device (addr 0x%02X): %s\n", addr, strerror(errno));
        return -1;
    }
    usleep(BH1750_CONV_TIME_MS * 1000);

    uint8_t buf[2];
    ssize_t r = read(fd, buf, 2);
    if (r != 2) {
        fprintf(stderr, "Error reading from I2C device (addr 0x%02X): %s\n", addr, strerror(errno));
        return -1;
    }

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux = (float)raw / 1.2f;
    return 0;
}

static int send_udp_multicast(int sockfd, const char *data) {
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    if (sendto(sockfd, data, strlen(data), 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        fprintf(stderr, "Error sending UDP multicast: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error installing signal handler: %s\n", strerror(errno));
        return 1;
    }

    int i2c_fds[NUM_SENSORS];
    for (int i = 0; i < NUM_SENSORS; i++) {
        i2c_fds[i] = i2c_open(I2C_BUS, (uint8_t)(i + 1));
        if (i2c_fds[i] < 0) {
            for (int j = 0; j < i; j++) {
                close(i2c_fds[j]);
            }
            return 1;
        }
    }

    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        fprintf(stderr, "Error creating socket: %s\n", strerror(errno));
        for (int i = 0; i < NUM_SENSORS; i++) {
            close(i2c_fds[i]);
        }
        return 1;
    }

    char data_string[256];
    int exit_code = 0;

    while (!terminate) {
        float lux_values[NUM_SENSORS];
        int read_errors = 0;

        for (int i = 0; i < NUM_SENSORS; i++) {
            if (bh1750_read_lux(i2c_fds[i], &lux_values[i]) < 0) {
                lux_values[i] = NAN;
                read_errors++;
            }
        }

        if (read_errors > 0) {
            snprintf(data_string, sizeof(data_string), "sensor_id,lux\n");
            for (int i = 0; i < NUM_SENSORS; i++) {
                if (lux_values[i] != NAN) {
                    snprintf(data_string + strlen(data_string), sizeof(data_string) - strlen(data_string), "%d,%.2f", i + 1, lux_values[i]);
                }
            }
            if (send_udp_multicast(sockfd, data_string) < 0) {
                exit_code = 1;
                break;
            }
        } else {
            snprintf(data_string, sizeof(data_string), "sensor_id,lux\n");
            for (int i = 0; i < NUM_SENSORS; i++) {
                if (lux_values[i] != NAN) {
                    snprintf(data_string + strlen(data_string), sizeof(data_string) - strlen(data_string), "%d,%.2f", i + 1, lux_values[i]);
                }
            }
            if (send_udp_multicast(sockfd, data_string) < 0) {
                exit_code = 1;
                break;
            }
        }

        usleep(LOOP_DELAY_MS * 1000);
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        if (i2c_fds[i] >= 0) {
            close(i2c_fds[i]);
        }
    }
    if (sockfd >= 0) {
        close(sockfd);
    }

    return exit_code;
}

