/*
 * AS7341 10-Channel Light/Color Sensor reader for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   AS7341 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   AS7341 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   AS7341 VDD  -> 3.3 V
 *   AS7341 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -o as7341_monitor as7341_monitor.c -lpigpio -lrt
 * Run:    sudo ./as7341_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

/* ---- AS7341 register map (per datasheet) ---- */
#define AS7341_I2C_BUS        1
#define AS7341_I2C_ADDR       0x60

#define AS7341_REG_ENABLE     0x00
#define AS7341_REG_HW_KEY     0x07
#define AS7341_REG_CFG6       0x0E
#define AS7341_REG_SP_EN      0x0F
#define AS7341_REG_CH_LIST    0x0A
#define AS7341_REG_ID         0x12

#define AS7341_ID_VALUE       0x00

#define AS7341_PON            0x01
#define AS7341_SMUX_CH_LIST   0x0C

#define AS7341_CH_LIST_F1     0x01
#define AS7341_CH_LIST_F2     0x02
#define AS7341_CH_LIST_F3     0x04
#define AS7341_CH_LIST_F4     0x08
#define AS7341_CH_LIST_F5     0x10
#define AS7341_CH_LIST_F6     0x20
#define AS7341_CH_LIST_F7     0x40
#define AS7341_CH_LIST_F8     0x80
#define AS7341_CH_LIST_CLEAR  0x01
#define AS7341_CH_LIST_NIR    0x02

#define AS7341_SMUX_10CH      0x0C

#define AS7341_SP_EN_SPECTRAL  0x01

#define LOG_FILE_NAME         "spectral_log.csv"
#define SAMPLE_INTERVAL_S     5

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to an AS7341 register; returns 0 on success, -1 on error. */
static int as7341_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %s\n",
                reg, value, strerror(errno));
    }
    return rc;
}

/* ------------------------------------------------------------------ */
/* Read one byte from an AS7341 register; returns 0 on success, -1 on error. */
static int as7341_read_reg(int handle, uint8_t reg, uint8_t *out)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian register pair; returns 0 on success, -1 on error. */
static int as7341_read_reg16(int handle, uint8_t reg, uint16_t *out)
{
    uint8_t lo, hi;
    if (as7341_read_reg(handle, reg, &lo) != 0)
        return -1;
    if (as7341_read_reg(handle, reg + 1, &hi) != 0)
        return -1;
    *out = (uint16_t)((hi << 8) | lo);
    return 0;
}

/* ------------------------------------------------------------------ */
static int as7341_init(int handle)
{
    uint8_t id = 0;

    /* --- Verify device identity --- */
    if (as7341_read_reg(handle, AS7341_REG_ID, &id) != 0) {
        fprintf(stderr, "[ERROR] Cannot read AS7341 ID register.\n");
        return -1;
    }
    if (id != AS7341_ID_VALUE) {
        fprintf(stderr, "[ERROR] Unexpected ID 0x%02X (expected 0x%02X). Wrong sensor or wrong bus.\n",
                id, AS7341_ID_VALUE);
        return -1;
    }
    printf("[INFO] AS7341 detected (ID = 0x%02X).\n", id);

    /* --- Power on --- */
    if (as7341_write_reg(handle, AS7341_REG_ENABLE, AS7341_PON) != 0)
        return -1;
    gpioDelay(10000); /* 10 ms settle */

    /* --- Configure spectral channels --- */
    if (as7341_write_reg(handle, AS7341_REG_CH_LIST,
                         AS7341_CH_LIST_F1 | AS7341_CH_LIST_F2 |
                         AS7341_CH_LIST_F3 | AS7341_CH_LIST_F4 |
                         AS7341_CH_LIST_F5 | AS7341_CH_LIST_F6 |
                         AS7341_CH_LIST_F7 | AS7341_CH_LIST_F8 |
                         AS7341_CH_LIST_CLEAR | AS7341_CH_LIST_NIR) != 0)
        return -1;

    /* --- Enable spectral measurement --- */
    if (as7341_write_reg(handle, AS7341_REG_SP_EN, AS7341_SP_EN_SPECTRAL) != 0)
        return -1;

    /* --- Set sample rate to 1 Hz (SMUX_CH_LIST = 0x0C) --- */
    if (as7341_write_reg(handle, AS7341_REG_CFG6, AS7341_SMUX_10CH) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
static int as7341_read_spectral(int handle, uint16_t *channels[10])
{
    for (int i = 0; i < 10; i++) {
        if (as7341_read_reg16(handle, AS7341_REG_CH_LIST + (uint8_t)i,
                             &channels[i]) != 0)
            return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static float calculate_lux(uint16_t *channels)
{
    float lux = 0.0f;

    /* Simplified approximation: sum of F1..F8 channels scaled by 0.1 */
    float sum = 0.0f;
    for (int i = 0; i < 8; i++)
        sum += (float)channels[i];
    lux = sum * 0.1f;

    /* Clamp to [0, 1000] */
    if (lux < 0.0f) lux = 0.0f;
    if (lux > 1000.0f) lux = 1000.0f;

    return lux;
}

/* ------------------------------------------------------------------ */
static int log_data(uint16_t *channels, float lux)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(g_log_file, "%s,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%.2f\n",
                timestamp,
                channels[0], channels[1], channels[2], channels[3],
                channels[4], channels[5], channels[6], channels[7],
                channels[8], channels[9], lux) < 0) {
        fprintf(stderr, "[ERROR] fprintf to log file failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "[ERROR] fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        /* Power down the sensor before closing the bus */
        (void)as7341_write_reg(g_i2c_handle, AS7341_REG_ENABLE, 0x00);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    uint16_t channels[10];
    float lux;

    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus --- */
    g_i2c_handle = i2cOpen(AS7341_I2C_BUS, AS7341_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                AS7341_I2C_BUS, AS7341_I2C_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Initialize sensor --- */
    if (as7341_init(g_i2c_handle) != 0) {
        fprintf(stderr, "[ERROR] AS7341 initialisation failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Open log file (append) --- */
    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[ERROR] Cannot open %s: %s\n", LOG_FILE_NAME, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,CH1,CH2,CH3,CH4,CH5,CH6,CH7,CH8,CH9,CH10,lux\n");
        fflush(g_log_file);
    }

    /* --- Signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGINT) failed: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGTERM) failed: %s\n", strerror(errno));
    }

