#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define DEFAULT_I2C_ADDRESS 0x1D
#define DEFAULT_OUTPUT_FILE "seismic_data.csv"
#define DEFAULT_INTERVAL_SEC 1
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10
#define ERROR_LOG_FILE "seismic_error.log"

typedef struct {
    float x;
    float y;
    float z;
} AccelerationData;

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *error_log = NULL;
static FILE *data_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_error(const char *msg) {
    if (!error_log) return;
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];
    localtime_r(&now, &tm_info);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(error_log, "%s: %s\n", ts, msg);
    fflush(error_log);
}

static int i2c_write_byte(int fd, unsigned char reg) {
    if (write(fd, &reg, 1) != 1) return -1;
    return 0;
}

static int i2c_read_bytes(int fd, unsigned char *buf, int len) {
    if (read(fd, buf, len) != len) return -1;
    return 0;
}

static int read_acceleration(int fd, AccelerationData *data) {
    unsigned char buf[6];
    int16_t raw_x, raw_y, raw_z;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2c_write_byte(fd, 0x00) < 0) {
            log_error("I2C write failed (reg select).");
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        usleep(1000);
        if (i2c_read_bytes(fd, buf, 6) < 0) {
            log_error("I2C read failed.");
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        raw_x = (int16_t)((buf[1] << 8) | buf[0]);
        raw_y = (int16_t)((buf[3] << 8) | buf[2]);
        raw_z = (int16_t)((buf[5] << 8) | buf[4]);
        data->x = (float)raw_x / 4096.0f;
        data->y = (float)raw_y / 4096.0f;
        data->z = (float)raw_z / 4096.0f;
        return 0;
    }
    log_error("Failed to read acceleration data after retries.");
    return -1;
}

static void log_data(AccelerationData data) {
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];
    localtime_r(&now, &tm_info);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(data_file, "%s,%.4f,%.4f,%.4f\n", ts, data.x, data.y, data.z);
    fflush(data_file);
}

static void cleanup(void) {
    if (data_file) { fclose(data_file); data_file = NULL; }
    if (error_log) { fclose(error_log); error_log = NULL; }
    if (i2c_fd >= 0) { close(i2c_fd); i2c_fd = -1; }
}

int main(int argc, char *argv[]) {
    int i2c_address = DEFAULT_I2C_ADDRESS;
    int interval_sec = DEFAULT_INTERVAL_SEC;
    char output_file[256];
    char *endptr;

    while ((endptr = strchr(argv[0], '\n')) != NULL) *endptr = '\0';
    while (argv[0] == "--") argv[0] = NULL;

    if (argc > 1) {
        char *opt = strtok(argv[1], " \t");
        while (opt != NULL) {
            if (strcmp(opt, "-a") == 0) i2c_address = strtol(optarg, &endptr, 0);
            else if (strcmp(opt, "-i") == 0) interval_sec = strtol(optarg, &endptr, 0);
            else if (strcmp(opt, "-f") == 0) {
                strncpy(output_file, optarg, sizeof(output_file) - 1);
                output_file[sizeof(output_file) - 1] = '\0';
            } else {
                fprintf(stderr, "Usage: %s [-a i2c_addr] [-i interval_sec] [-f output_file]\n", argv[0]);
                return 1;
            }
            opt = strtok(NULL, " \t");
        }
    }

    if (i2c_address < 0x03 || i2c_address > 0x77) {
        fprintf(stderr, "Invalid I2C address: 0x%02X\n", i2c_address);
        return 1;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        log_error("Failed to open /dev/i2c-1.");
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, i2c_address) < 0) {
        log_error("Failed to set I2C slave address.");
        cleanup();
        return 1;
    }

    error_log = fopen(ERROR_LOG_FILE, "a");
    if (!error_log) {
        fprintf(stderr, "Warning: could not open %s: %s\n", ERROR_LOG_FILE, strerror(errno));
    }

    data_file = fopen(DEFAULT_OUTPUT_FILE, "w");
    if (!data_file) {
        log_error("Failed to create output file.");
        cleanup();
        return 1;
    }
    fprintf(data_file, "timestamp,x_g,y_g,z_g\n");

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Seismic data acquisition started. Press Ctrl+C to stop.\n");

    while (running) {
        AccelerationData data;
        if (read_acceleration(i2c_fd, &data) == 0) {
            log_data(data);
        } else {
            log_error("Sensor read failed; skipping sample.");
        }
        sleep(interval_sec);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

