#include <arpa/inet.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define BH1750_ADDR    0x77
#define BH1750_CONT_H  0x10
#define BH1750_CONT_L  0x20
#define BH1750_RESET    0x07
#define BH1750_POWER_ON 0x01
#define BH1750_POWER_OFF 0x00
#define BH1750_MEAS_MS  0x03
#define BH1750_CONV_MS  0x02
#define BH1750_ALS_VIS  0x00
#define BH1750_ALS_IR   0x01
#define BH1750_ALS_VIS_DATA 0x10
#define BH1750_ALS_IR_DATA  0x20
#define BH1750_DATA_READY  0x01
#define BH1750_ERROR      0x07

#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5000
#define MULTICAST_TTL  1
#define SAMPLE_INTERVAL 1

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo) {
    (void)signo;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int bh1750_init(int fd) {
    if (i2c_write_byte(fd, BH1750_RESET, BH1750_POWER_OFF) < 0) return -1;
    usleep(10000);
    if (i2c_write_byte(fd, BH1750_RESET, BH1750_POWER_ON) < 0) return -1;
    usleep(10000);
    if (i2c_write_byte(fd, BH1750_MEAS_MS, 0x00) < 0) return -1;
    if (i2c_write_byte(fd, BH1750_CONV_MS, 0x02) < 0) return -1;
    if (i2c_write_byte(fd, BH1750_ALS_VIS, 0x00) < 0) return -1;
    if (i2c_write_byte(fd, BH1750_DATA_READY, 0x00) < 0) return -1;
    return 0;
}

static int bh1750_read_lux(int fd, float *lux_out) {
    uint8_t msb, lsb;
    if (i2c_read_byte(fd, BH1750_CONT_H, &msb) < 0) return -1;
    if (i2c_read_byte(fd, BH1750_CONT_L, &lsb) < 0) return -1;
    uint16_t raw = ((uint16_t)msb << 8) | lsb;
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static int send_udp_multicast(float lux) {
    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("socket creation failed");
        return -1;
    }
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons(MULTICAST_PORT);
    if (inet_pton(AF_INET, MULTICAST_ADDR, &addr.sin_addr) <= 0) {
        fprintf(stderr, "Invalid multicast address: %s\n", MULTICAST_ADDR);
        close(sockfd);
        return -1;
    }
    char buffer[32];
    int len = snprintf(buffer, sizeof(buffer), "%.2f", lux);
    if (sendto(sockfd, buffer, len, 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("sendto failed");
        close(sockfd);
        return -1;
    }
    close(sockfd);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction failed");
        return 1;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", BH1750_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (bh1750_init(fd) < 0) {
        fprintf(stderr, "BH1750 initialization failed.\n");
        close(fd);
        return 1;
    }

    while (g_running) {
        float lux;
        if (bh1750_read_lux(fd, &lux) < 0) {
            fprintf(stderr, "Sensor read error, retrying in %d seconds...\n", SAMPLE_INTERVAL);
            sleep(SAMPLE_INTERVAL);
            continue;
        }
        if (send_udp_multicast(lux) < 0) {
            fprintf(stderr, "UDP multicast send failed.\n");
        }
        sleep(SAMPLE_INTERVAL);
    }

    close(fd);
    return 0;
}

