#include <sys/select.h>
#include <sys/time.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B115200
#define READ_TIMEOUT_SEC 2
#define LINE_BUF_SIZE 256
#define READ_BUF_SIZE 512
#define POLL_TIMEOUT_SEC 0.5

static volatile sig_atomic_t g_running = 1;
static int g_uart_fd = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int init_uart(const char *device)
{
    int fd = open(device, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", device, strerror(errno));
        return -1;
    }

    struct termios tty;
    memset(&tty, 0, sizeof(tty));
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "tcgetattr failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    cfsetispeed(&tty, BAUD_RATE);
    cfsetospeed(&tty, BAUD_RATE);

    tty.c_cflag &= ~PARENB;
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CSIZE;
    tty.c_cflag |= CS8;
    tty.c_cflag &= ~CRTSCTS;
    tty.c_cflag |= CREAD | CLOCAL;

    tty.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    tty.c_iflag &= ~(IXON | IXOFF | IXANY | IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL);
    tty.c_oflag &= ~OPOST;

    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 0;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "tcsetattr failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static int read_line(int fd, char *buf, size_t buf_size, char *line_buf, size_t line_buf_size)
{
    size_t idx = 0;
    char ch;
    char read_buf[READ_BUF_SIZE];

    while (idx < line_buf_size - 1) {
        ssize_t n = read(fd, &ch, 1);
        if (n < 0) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                if (idx == 0) {
                    return -1;
                }
                return 0;
            }
            fprintf(stderr, "UART read error: %s\n", strerror(errno));
            return -1;
        }
        if (n == 0) {
            return 0;
        }

        if (ch == '\n') {
            line_buf[idx] = '\0';
            if (idx > 0) {
                strncpy(line_buf, buf, line_buf_size - 1);
                line_buf[line_buf_size - 1] = '\0';
            }
            return 1;
        }

        if (ch != '\r') {
            if (idx < line_buf_size - 1) {
                buf[idx++] = ch;
            }
        }
    }

    if (idx > 0) {
        strncpy(line_buf, buf, line_buf_size - 1);
        line_buf[line_buf_size - 1] = '\0';
    }
    return 0;
}

